fn defensive_line_break_threat_fit(line_gap: f64) -> f64 {
    ((DEFENSIVE_LINE_BREAK_TRIGGER_GAP_YARDS - line_gap)
        / (DEFENSIVE_LINE_BREAK_TRIGGER_GAP_YARDS + 16.0))
        .clamp(0.0, 1.0)
}

