#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BallAgent {
    pub id: usize,
    pub position: Vec2,
    pub velocity: Vec2,
    pub acceleration: Vec2,
    pub jerk: Vec2,
    pub curl_acceleration: Vec2,
    pub altitude_yards: f64,
    pub position_history: VecDeque<BallPositionSample>,
    pub holder: Option<usize>,
    pub last_touch_team: Option<Team>,
    pub last_decision: Option<BallDecisionTrace>,
    #[serde(default)]
    untargeted_long_ball_launcher: Option<(usize, u64)>,
    #[serde(default)]
    untargeted_long_ball_flight: Option<UntargetedLongBallFlight>,
}

impl BallAgent {
    pub fn new(id: usize, state: BallState) -> Self {
        BallAgent {
            id,
            position: state.position,
            velocity: state.velocity,
            acceleration: state.acceleration,
            jerk: state.jerk,
            curl_acceleration: state.curl_acceleration,
            altitude_yards: state.altitude_yards,
            position_history: VecDeque::from([BallPositionSample {
                tick: 0,
                clock_seconds: 0.0,
                position: state.position,
                velocity: state.velocity,
                acceleration: state.acceleration,
                jerk: state.jerk,
                curl_acceleration: state.curl_acceleration,
                altitude_yards: state.altitude_yards,
                holder: state.holder,
                last_touch_team: state.last_touch_team,
            }]),
            holder: state.holder,
            last_touch_team: state.last_touch_team,
            last_decision: None,
            untargeted_long_ball_launcher: None,
            untargeted_long_ball_flight: None,
        }
    }

    pub fn to_state(&self) -> BallState {
        let decision = self.last_decision.as_ref();
        BallState {
            position: self.position,
            velocity: self.velocity,
            acceleration: self.acceleration,
            jerk: self.jerk,
            curl_acceleration: self.curl_acceleration,
            altitude_yards: self.altitude_yards,
            decision_speed_yps: decision
                .map(|decision| decision.velocity.len())
                .unwrap_or_else(|| self.velocity.len()),
            decision_altitude_yards: decision
                .map(|decision| decision.altitude_yards)
                .unwrap_or(self.altitude_yards),
            decision_curl_yps2: decision
                .map(|decision| decision.curl_acceleration.len())
                .unwrap_or_else(|| self.curl_acceleration.len()),
            holder: self.holder,
            last_touch_team: self.last_touch_team,
            scheduled_index: None,
            last_decision: self.last_decision.clone(),
        }
    }

    fn update_kinematics_from(
        &mut self,
        previous_velocity: Vec2,
        previous_acceleration: Vec2,
        dt_seconds: f64,
    ) {
        self.acceleration = if dt_seconds > 0.0 {
            (self.velocity - previous_velocity) / dt_seconds
        } else {
            Vec2::zero()
        };
        self.jerk = if dt_seconds > 0.0 {
            (self.acceleration - previous_acceleration) / dt_seconds
        } else {
            Vec2::zero()
        };
    }

    fn record_position_history(&mut self, tick: u64, clock_seconds: f64) {
        self.position_history.push_back(BallPositionSample {
            tick,
            clock_seconds,
            position: self.position,
            velocity: self.velocity,
            acceleration: self.acceleration,
            jerk: self.jerk,
            curl_acceleration: self.curl_acceleration,
            altitude_yards: self.altitude_yards,
            holder: self.holder,
            last_touch_team: self.last_touch_team,
        });
        while self.position_history.len() > BALL_POSITION_HISTORY_LIMIT {
            self.position_history.pop_front();
        }
    }

    pub fn history_velocity_estimate(&self, dt_seconds: f64) -> Vec2 {
        if self.position_history.len() < 2 {
            return self.velocity;
        }
        let last = self.position_history.len() - 1;
        ball_sample_velocity_between(
            &self.position_history[last - 1],
            &self.position_history[last],
            dt_seconds,
        )
        .unwrap_or(self.velocity)
    }

    pub fn history_acceleration_estimate(&self, dt_seconds: f64) -> Vec2 {
        if self.position_history.len() < 3 {
            return self.acceleration;
        }
        let last = self.position_history.len() - 1;
        ball_sample_acceleration_between(
            &self.position_history[last - 2],
            &self.position_history[last - 1],
            &self.position_history[last],
            dt_seconds,
        )
        .unwrap_or(self.acceleration)
    }

    pub fn history_jerk_estimate(&self, dt_seconds: f64) -> Vec2 {
        if self.position_history.len() < 4 {
            return self.jerk;
        }
        let last = self.position_history.len() - 1;
        ball_sample_jerk_between(
            &self.position_history[last - 3],
            &self.position_history[last - 2],
            &self.position_history[last - 1],
            &self.position_history[last],
            dt_seconds,
        )
        .unwrap_or(self.jerk)
    }

    fn untargeted_long_ball_team(&self, pending_pass: Option<&PendingPass>) -> Option<Team> {
        if self.holder.is_some() || pending_pass.is_some() {
            return None;
        }
        let long_ball_action = self
            .last_decision
            .as_ref()
            .is_some_and(|decision| is_untargeted_long_ball_action(&decision.action));
        if long_ball_action && (self.velocity.len() >= 8.0 || self.altitude_yards > 0.02) {
            self.last_touch_team
        } else {
            None
        }
    }

    fn untargeted_long_ball_launch_exclusion(
        &self,
        current_tick: u64,
        pending_pass: Option<&PendingPass>,
    ) -> Option<usize> {
        self.untargeted_long_ball_team(pending_pass)?;
        self.untargeted_long_ball_launcher
            .filter(|(_, launch_tick)| current_tick <= *launch_tick)
            .map(|(player_id, _)| player_id)
    }

    fn run_time_step(
        &mut self,
        context: BallStepContext<'_>,
        rng: &mut SeededRandom,
    ) -> BallStepOutcome {
        if let Some(holder) = self.holder {
            if let Some(player) = context.players.iter().find(|player| player.id == holder) {
                let lead = carried_ball_lead(player);
                self.position = (player.position + lead)
                    .clamp_to_pitch(context.field_width, context.field_length);
                self.velocity = player.velocity;
                self.acceleration = player.acceleration;
                self.jerk = player.jerk;
                self.curl_acceleration = Vec2::zero();
                self.altitude_yards = 0.0;
                self.last_touch_team = Some(player.team);
                if !self
                    .last_decision
                    .as_ref()
                    .is_some_and(|decision| restart_action_label(&decision.action).is_some())
                {
                    self.record_decision(context.tick, "held", context.scheduled_index);
                }
            }
            self.untargeted_long_ball_launcher = None;
            self.untargeted_long_ball_flight = None;
            return BallStepOutcome::None;
        }

        let previous_position = self.position;
        let previous_velocity = self.velocity;
        self.velocity = apply_ball_curl(self.velocity, self.curl_acceleration, context.dt_seconds);
        let resistance_altitude_yards = context
            .pending_pass
            .as_ref()
            .map(|pass| {
                let midpoint = self.position + self.velocity * (context.dt_seconds * 0.5);
                pass_ball_altitude_yards(pass, midpoint)
            })
            .unwrap_or(self.altitude_yards)
            .max(self.altitude_yards);
        self.velocity = ball_velocity_after_resistance(
            self.velocity,
            context.dt_seconds,
            context.ball_drag_per_tick,
            context.ball_air_resistance,
            context.ball_grass_resistance_yps2,
            resistance_altitude_yards,
        );
        self.curl_acceleration = decayed_ball_curl(self.curl_acceleration, context.dt_seconds);
        self.position += (previous_velocity + self.velocity) * 0.5 * context.dt_seconds;
        let loose_long_ball_altitude = if self
            .untargeted_long_ball_team(context.pending_pass.as_ref())
            .is_some()
        {
            self.untargeted_long_ball_flight
                .as_ref()
                .map(|flight| {
                    untargeted_long_ball_altitude_yards(flight, self.position, self.velocity.len())
                })
                .unwrap_or_else(|| loose_long_ball_altitude_yards(self.velocity.len()))
        } else {
            0.0
        };
        self.altitude_yards = context
            .pending_pass
            .as_ref()
            .map(|pass| pass_ball_altitude_yards(pass, self.position))
            .unwrap_or(loose_long_ball_altitude);
        if self.velocity.len() < context.ball_stop_speed_yps {
            self.velocity = Vec2::zero();
            self.curl_acceleration = Vec2::zero();
            self.altitude_yards = 0.0;
            self.untargeted_long_ball_launcher = None;
            self.untargeted_long_ball_flight = None;
        }

        if let Some(shot) = context.pending_shot.as_ref() {
            let goal = Vec2::new(
                context.field_width * 0.5,
                shot.team.goal_y(context.field_length),
            );
            let shot_speed = previous_velocity.len().max(self.velocity.len());
            if let Some(assessment) = shot_block_assessment_for_agents(
                context.players,
                previous_position,
                goal,
                shot.team,
                shot_speed,
                false,
            ) {
                let reached_blocker = (0.0..=1.0).contains(&segment_projection_factor(
                    previous_position,
                    self.position,
                    assessment.block_position,
                )) && segment_distance_to_point(
                    previous_position,
                    self.position,
                    assessment.block_position,
                ) <= PLAYER_BODY_RADIUS_YARDS + 0.28;
                if reached_blocker && rng.next_float() < assessment.probability {
                    let roll = rng.next_float();
                    let deflection_kind = if roll < 0.52 {
                        ShotDeflectionKind::CornerKick
                    } else if roll < 0.68 {
                        ShotDeflectionKind::GoalBound
                    } else {
                        ShotDeflectionKind::Rebound
                    };
                    let deflection_speed = (shot_speed
                        * match deflection_kind {
                            ShotDeflectionKind::CornerKick => 0.0,
                            ShotDeflectionKind::GoalBound => 0.42 + rng.next_float() * 0.18,
                            ShotDeflectionKind::Rebound => 0.28 + rng.next_float() * 0.24,
                        })
                    .max(0.0);
                    let velocity = match deflection_kind {
                        ShotDeflectionKind::CornerKick => Vec2::zero(),
                        ShotDeflectionKind::GoalBound => {
                            let target_x = (goal.x
                                + (rng.next_float() - 0.5) * context.goal_width * 0.72)
                                .clamp(
                                    goal.x - context.goal_width * 0.5,
                                    goal.x + context.goal_width * 0.5,
                                );
                            (Vec2::new(target_x, goal.y) - assessment.block_position).normalized()
                                * deflection_speed
                        }
                        ShotDeflectionKind::Rebound => {
                            let incoming_dir = if previous_velocity.len() > 1e-6 {
                                previous_velocity.normalized()
                            } else {
                                (goal - previous_position).normalized()
                            };
                            let lateral = Vec2::new(-incoming_dir.y, incoming_dir.x)
                                * if rng.next_float() < 0.5 { -1.0 } else { 1.0 };
                            let away_from_goal = (assessment.block_position - goal).normalized();
                            (away_from_goal * 0.64 + lateral * 0.36).normalized() * deflection_speed
                        }
                    };
                    let restart = if deflection_kind == ShotDeflectionKind::CornerKick {
                        let corner_x = if assessment.block_position.x <= context.field_width * 0.5 {
                            0.0
                        } else {
                            context.field_width
                        };
                        Some(BallRestart {
                            kind: BallRestartKind::CornerKick,
                            awarded_team: shot.team,
                            position: Vec2::new(corner_x, goal.y),
                        })
                    } else {
                        None
                    };
                    self.position = assessment
                        .block_position
                        .clamp_to_pitch(context.field_width, context.field_length);
                    self.velocity = velocity;
                    self.curl_acceleration = Vec2::zero();
                    self.altitude_yards = 0.0;
                    self.untargeted_long_ball_flight = None;
                    self.untargeted_long_ball_launcher = None;
                    self.holder = None;
                    self.last_touch_team = Some(assessment.defending_team);
                    self.record_decision(context.tick, "shot-blocked", context.scheduled_index);
                    return BallStepOutcome::ShotBlocked {
                        shot: shot.clone(),
                        blocker_id: assessment.blocker_id,
                        defending_team: assessment.defending_team,
                        position: self.position,
                        velocity,
                        deflection_kind,
                        keep_shot_active: deflection_kind == ShotDeflectionKind::GoalBound,
                        restart,
                    };
                }
            }
        }

        let x_crossing_fraction = boundary_crossing_fraction(
            previous_position.x,
            self.position.x,
            0.0,
            context.field_width,
        );
        let y_crossing_fraction = boundary_crossing_fraction(
            previous_position.y,
            self.position.y,
            0.0,
            context.field_length,
        );
        if self.position.x < 0.0 || self.position.x > context.field_width {
            let endline_crossed_first =
                matches!((x_crossing_fraction, y_crossing_fraction), (Some(x), Some(y)) if y <= x);
            if !endline_crossed_first {
                let awarded_team = self.last_touch_team.map(Team::other).unwrap_or(Team::Home);
                self.position = Vec2::new(
                    self.position.x.max(0.0).min(context.field_width),
                    self.position.y.max(0.0).min(context.field_length),
                );
                self.velocity = Vec2::zero();
                self.curl_acceleration = Vec2::zero();
                self.altitude_yards = 0.0;
                self.untargeted_long_ball_flight = None;
                self.untargeted_long_ball_launcher = None;
                self.holder = None;
                self.last_touch_team = Some(awarded_team);
                self.record_decision(context.tick, "throw-in", context.scheduled_index);
                return BallStepOutcome::OutOfPlay {
                    restart: BallRestart {
                        kind: BallRestartKind::ThrowIn,
                        awarded_team,
                        position: self.position,
                    },
                    shot: context.pending_shot,
                };
            }
        }

        if self.position.y < 0.0 || self.position.y > context.field_length {
            let goal_x = context.field_width * 0.5;
            let goal_line_y = if self.position.y > context.field_length {
                context.field_length
            } else {
                0.0
            };
            let crossing_fraction = y_crossing_fraction.unwrap_or(1.0);
            let crossing_x =
                previous_position.x + (self.position.x - previous_position.x) * crossing_fraction;
            let crossing_position =
                Vec2::new(crossing_x.clamp(0.0, context.field_width), goal_line_y);
            let in_goal = (crossing_x - goal_x).abs() <= context.goal_width * 0.5;
            if in_goal {
                let scoring_team = if self.position.y > context.field_length {
                    Team::Home
                } else {
                    Team::Away
                };
                if let Some(shot) = context.pending_shot {
                    let defending_team = scoring_team.other();
                    if let Some(keeper_id) = goalkeeper_for_players(context.players, defending_team)
                    {
                        let Some(keeper) =
                            context.players.iter().find(|player| player.id == keeper_id)
                        else {
                            self.record_decision(context.tick, "goal", context.scheduled_index);
                            return BallStepOutcome::Goal {
                                scoring_team,
                                shot: Some(shot),
                            };
                        };
                        let sightline_screen_probability =
                            shot_sightline_screen_probability_for_agents(
                                context.players,
                                shot.origin,
                                crossing_position,
                                shot.team,
                                self.velocity.len(),
                                false,
                            );
                        let save_probability = goalkeeper_save_probability(
                            keeper,
                            shot.origin,
                            crossing_position,
                            self.velocity.len(),
                            context.goal_width,
                            sightline_screen_probability,
                        );
                        if rng.next_float() < save_probability {
                            let save_y = match defending_team {
                                Team::Home => SHOT_SAVE_DEPTH_YARDS,
                                Team::Away => context.field_length - SHOT_SAVE_DEPTH_YARDS,
                            };
                            let save_position = Vec2::new(
                                crossing_position.x.clamp(
                                    context.field_width * 0.5 - context.goal_width * 0.55,
                                    context.field_width * 0.5 + context.goal_width * 0.55,
                                ),
                                save_y,
                            );
                            let catch_probability = goalkeeper_catch_probability_after_save(
                                keeper,
                                shot.origin,
                                crossing_position,
                                self.velocity.len(),
                                context.goal_width,
                                sightline_screen_probability,
                            );
                            if rng.next_float() < catch_probability {
                                self.holder = Some(keeper_id);
                                self.position = save_position;
                                self.velocity = Vec2::zero();
                                self.curl_acceleration = Vec2::zero();
                                self.altitude_yards = 0.0;
                                self.untargeted_long_ball_flight = None;
                                self.untargeted_long_ball_launcher = None;
                                self.last_touch_team = Some(defending_team);
                                self.record_decision(context.tick, "save", context.scheduled_index);
                                return BallStepOutcome::Save {
                                    shot,
                                    defending_team,
                                    keeper_id,
                                    save_position,
                                };
                            }
                            let away_from_goal = Vec2::new(0.0, defending_team.attack_dir());
                            let lateral = Vec2::new(1.0, 0.0)
                                * if rng.next_float() < 0.5 { -1.0 } else { 1.0 };
                            let parry_direction =
                                (away_from_goal * 0.78 + lateral * 0.22).normalized();
                            let parry_distance = GOALKEEPER_PARRY_MIN_YARDS
                                + rng.next_float()
                                    * (GOALKEEPER_PARRY_MAX_YARDS - GOALKEEPER_PARRY_MIN_YARDS);
                            let parry_position = (save_position + parry_direction * parry_distance)
                                .clamp_to_pitch(context.field_width, context.field_length);
                            let parry_speed = (4.8 + rng.next_float() * 3.8).max(
                                parry_position.distance(save_position)
                                    / context.dt_seconds.max(0.35),
                            );
                            let parry_velocity = parry_direction * parry_speed;
                            self.holder = None;
                            self.position = parry_position;
                            self.velocity = parry_velocity;
                            self.curl_acceleration = Vec2::zero();
                            self.altitude_yards = 0.0;
                            self.untargeted_long_ball_flight = None;
                            self.untargeted_long_ball_launcher = None;
                            self.last_touch_team = Some(defending_team);
                            self.record_decision(
                                context.tick,
                                "keeper-parry",
                                context.scheduled_index,
                            );
                            return BallStepOutcome::KeeperParry {
                                shot,
                                defending_team,
                                keeper_id,
                                save_position,
                                parry_position,
                                velocity: parry_velocity,
                            };
                        }
                    }
                    self.record_decision(context.tick, "goal", context.scheduled_index);
                    return BallStepOutcome::Goal {
                        scoring_team,
                        shot: Some(shot),
                    };
                }
            }
            let defending_team = if self.position.y > context.field_length {
                Team::Away
            } else {
                Team::Home
            };
            let attacking_team = defending_team.other();
            let last_touch = self.last_touch_team;
            let kind = if last_touch == Some(defending_team) {
                BallRestartKind::CornerKick
            } else {
                BallRestartKind::GoalKick
            };
            let awarded_team = match kind {
                BallRestartKind::CornerKick => attacking_team,
                BallRestartKind::GoalKick => defending_team,
                BallRestartKind::ThrowIn => unreachable!("endline cannot award throw-in"),
                BallRestartKind::FreeKick => unreachable!("endline cannot award free kick"),
            };
            let end_y = self.position.y.max(0.0).min(context.field_length);
            let restart_position = match kind {
                BallRestartKind::GoalKick => {
                    let y = match defending_team {
                        Team::Home => SHOT_SAVE_DEPTH_YARDS + 4.4,
                        Team::Away => context.field_length - SHOT_SAVE_DEPTH_YARDS - 4.4,
                    };
                    Vec2::new(context.field_width * 0.5, y)
                }
                BallRestartKind::CornerKick => {
                    let corner_x = if crossing_position.x <= context.field_width * 0.5 {
                        0.0
                    } else {
                        context.field_width
                    };
                    Vec2::new(corner_x, end_y)
                }
                BallRestartKind::ThrowIn => unreachable!("endline cannot award throw-in"),
                BallRestartKind::FreeKick => unreachable!("endline cannot award free kick"),
            };
            self.position = restart_position;
            self.velocity = Vec2::zero();
            self.curl_acceleration = Vec2::zero();
            self.altitude_yards = 0.0;
            self.untargeted_long_ball_flight = None;
            self.untargeted_long_ball_launcher = None;
            self.holder = None;
            self.last_touch_team = Some(awarded_team);
            let action = match kind {
                BallRestartKind::GoalKick => "goal-kick",
                BallRestartKind::CornerKick => "corner-kick",
                BallRestartKind::ThrowIn => "throw-in",
                BallRestartKind::FreeKick => "free-kick",
            };
            self.record_decision(context.tick, action, context.scheduled_index);
            return BallStepOutcome::OutOfPlay {
                restart: BallRestart {
                    kind,
                    awarded_team,
                    position: restart_position,
                },
                shot: context.pending_shot,
            };
        }

        let loose_long_ball_team = self.untargeted_long_ball_team(context.pending_pass.as_ref());
        let same_tick_long_ball_launcher =
            self.untargeted_long_ball_launch_exclusion(context.tick, context.pending_pass.as_ref());
        if context.pending_shot.is_none() {
            if let Some((holder, holder_team, control_position)) =
                nearest_ball_controller_for_segment(
                    context.tick,
                    previous_position,
                    self.position,
                    self.velocity,
                    context.players,
                    context.pending_pass.as_ref(),
                    loose_long_ball_team,
                    same_tick_long_ball_launcher,
                    self.altitude_yards,
                    rng,
                )
            {
                let untargeted_long_ball = self
                    .untargeted_long_ball_team(context.pending_pass.as_ref())
                    .and_then(|team| {
                        self.untargeted_long_ball_launcher
                            .and_then(|(launcher_id, launch_tick)| {
                                self.untargeted_long_ball_flight.as_ref().map(|flight| {
                                    ResolvedUntargetedLongBall {
                                        launcher_id,
                                        launch_tick,
                                        team,
                                        action: flight.action.clone(),
                                        origin: flight.origin,
                                        target: flight.target,
                                        distance_yards: flight.distance_yards,
                                    }
                                })
                            })
                    });
                self.holder = Some(holder);
                self.position =
                    control_position.clamp_to_pitch(context.field_width, context.field_length);
                self.last_touch_team = Some(holder_team);
                self.curl_acceleration = Vec2::zero();
                self.untargeted_long_ball_launcher = None;
                self.record_decision(context.tick, "controlled", context.scheduled_index);
                let possession_result = match context.pending_pass {
                    Some(pass) if pass.team == holder_team => {
                        BallPossessionResult::PassCompleted(holder_team)
                    }
                    Some(pass) if pass.team != holder_team => {
                        BallPossessionResult::Interception(holder_team)
                    }
                    _ => BallPossessionResult::LooseBallRecovery(holder_team),
                };
                return BallStepOutcome::Controlled {
                    holder,
                    holder_team,
                    possession_result,
                    untargeted_long_ball,
                };
            }
        }

        if loose_long_ball_team.is_none() {
            self.record_decision(context.tick, "roll", context.scheduled_index);
        }
        BallStepOutcome::None
    }

    fn record_decision(&mut self, tick: u64, action: &str, scheduled_index: Option<usize>) {
        self.last_decision = Some(BallDecisionTrace {
            tick,
            action: action.to_string(),
            position: self.position,
            velocity: self.velocity,
            acceleration: self.acceleration,
            jerk: self.jerk,
            curl_acceleration: self.curl_acceleration,
            altitude_yards: self.altitude_yards,
            holder: self.holder,
            scheduled_index,
            operation_order: ball_agent_operation_order(tick, action, scheduled_index),
        });
    }
}

fn ball_agent_operation_order(
    tick: u64,
    action: &str,
    scheduled_index: Option<usize>,
) -> Vec<String> {
    let mut trace_rng = SeededRandom::new(
        (tick as u32)
            .wrapping_mul(747_796_405)
            .wrapping_add(BALL_AGENT_ID as u32)
            .wrapping_add((scheduled_index.unwrap_or(0) as u32).wrapping_mul(2_891_336_453)),
    );
    let shot_weight = if matches!(action, "shot-blocked" | "save" | "keeper-parry" | "goal") {
        1.60
    } else {
        0.74
    };
    let holder_weight = if action == "held" { 1.72 } else { 0.82 };
    let boundary_weight = if restart_action_label(action).is_some() || action == "goal" {
        1.46
    } else {
        0.80
    };
    let control_weight = if matches!(action, "controlled" | "held") {
        1.36
    } else {
        0.92
    };
    weighted_fisher_yates_order(
        vec![
            ("sync-holder".to_string(), holder_weight),
            ("apply-curl".to_string(), 1.02),
            ("apply-resistance".to_string(), 1.18),
            ("advance-position".to_string(), 1.12),
            ("resolve-shot".to_string(), shot_weight),
            ("resolve-boundary".to_string(), boundary_weight),
            ("resolve-control".to_string(), control_weight),
        ],
        &mut trace_rng,
    )
}

fn ball_sample_delta_seconds(
    a: &BallPositionSample,
    b: &BallPositionSample,
    fallback_dt_seconds: f64,
) -> Option<f64> {
    let sample_dt = b.clock_seconds - a.clock_seconds;
    if sample_dt.is_finite() && sample_dt > 0.0 {
        Some(sample_dt)
    } else if fallback_dt_seconds.is_finite() && fallback_dt_seconds > 0.0 {
        Some(fallback_dt_seconds)
    } else {
        None
    }
}

fn ball_sample_velocity_between(
    a: &BallPositionSample,
    b: &BallPositionSample,
    fallback_dt_seconds: f64,
) -> Option<Vec2> {
    let dt_seconds = ball_sample_delta_seconds(a, b, fallback_dt_seconds)?;
    Some((b.position - a.position) / dt_seconds)
}

fn ball_sample_acceleration_between(
    a: &BallPositionSample,
    b: &BallPositionSample,
    c: &BallPositionSample,
    fallback_dt_seconds: f64,
) -> Option<Vec2> {
    let dt_ab = ball_sample_delta_seconds(a, b, fallback_dt_seconds)?;
    let dt_bc = ball_sample_delta_seconds(b, c, fallback_dt_seconds)?;
    let velocity_ab = (b.position - a.position) / dt_ab;
    let velocity_bc = (c.position - b.position) / dt_bc;
    let midpoint_dt_seconds = ((dt_ab + dt_bc) * 0.5).max(1e-9);
    Some((velocity_bc - velocity_ab) / midpoint_dt_seconds)
}

fn ball_sample_jerk_between(
    a: &BallPositionSample,
    b: &BallPositionSample,
    c: &BallPositionSample,
    d: &BallPositionSample,
    fallback_dt_seconds: f64,
) -> Option<Vec2> {
    let dt_ab = ball_sample_delta_seconds(a, b, fallback_dt_seconds)?;
    let dt_bc = ball_sample_delta_seconds(b, c, fallback_dt_seconds)?;
    let dt_cd = ball_sample_delta_seconds(c, d, fallback_dt_seconds)?;
    let velocity_ab = (b.position - a.position) / dt_ab;
    let velocity_bc = (c.position - b.position) / dt_bc;
    let velocity_cd = (d.position - c.position) / dt_cd;
    let acceleration_ab_bc = (velocity_bc - velocity_ab) / ((dt_ab + dt_bc) * 0.5).max(1e-9);
    let acceleration_bc_cd = (velocity_cd - velocity_bc) / ((dt_bc + dt_cd) * 0.5).max(1e-9);
    let acceleration_midpoint_dt_seconds = ((dt_ab + 2.0 * dt_bc + dt_cd) * 0.25).max(1e-9);
    Some((acceleration_bc_cd - acceleration_ab_bc) / acceleration_midpoint_dt_seconds)
}

fn ball_position_sample_from_agent(
    ball: &BallAgent,
    tick: u64,
    clock_seconds: f64,
) -> BallPositionSample {
    BallPositionSample {
        tick,
        clock_seconds,
        position: ball.position,
        velocity: ball.velocity,
        acceleration: ball.acceleration,
        jerk: ball.jerk,
        curl_acceleration: ball.curl_acceleration,
        altitude_yards: ball.altitude_yards,
        holder: ball.holder,
        last_touch_team: ball.last_touch_team,
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OfficialDecisionTrace {
    pub tick: u64,
    pub action: String,
    pub kind: OfficialKind,
    pub position: Vec2,
    pub target: Vec2,
    #[serde(default)]
    pub scheduled_index: Option<usize>,
    #[serde(default)]
    pub offside_line_y: Option<f64>,
    #[serde(default)]
    pub operation_order: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OfficialAgent {
    pub id: usize,
    pub kind: OfficialKind,
    pub position: Vec2,
    pub velocity: Vec2,
    pub acceleration: Vec2,
    pub jerk: Vec2,
    pub position_history: VecDeque<Vec2>,
    #[serde(default)]
    pub last_decision: Option<OfficialDecisionTrace>,
}

impl OfficialAgent {
    fn new(id: usize, kind: OfficialKind, position: Vec2) -> Self {
        OfficialAgent {
            id,
            kind,
            position,
            velocity: Vec2::zero(),
            acceleration: Vec2::zero(),
            jerk: Vec2::zero(),
            position_history: VecDeque::from([position]),
            last_decision: None,
        }
    }

    fn record_position_history(&mut self) {
        self.position_history.push_back(self.position);
        while self.position_history.len() > PLAYER_POSITION_HISTORY_LIMIT {
            self.position_history.pop_front();
        }
    }

    pub fn history_velocity_estimate(&self, dt_seconds: f64) -> Vec2 {
        if dt_seconds <= 0.0 || self.position_history.len() < 2 {
            return self.velocity;
        }
        let last = self.position_history.len() - 1;
        (self.position_history[last] - self.position_history[last - 1]) / dt_seconds
    }

    pub fn history_acceleration_estimate(&self, dt_seconds: f64) -> Vec2 {
        if dt_seconds <= 0.0 || self.position_history.len() < 3 {
            return self.acceleration;
        }
        let last = self.position_history.len() - 1;
        let v0 = (self.position_history[last - 1] - self.position_history[last - 2]) / dt_seconds;
        let v1 = (self.position_history[last] - self.position_history[last - 1]) / dt_seconds;
        (v1 - v0) / dt_seconds
    }

    pub fn history_jerk_estimate(&self, dt_seconds: f64) -> Vec2 {
        if dt_seconds <= 0.0 || self.position_history.len() < 4 {
            return self.jerk;
        }
        let last = self.position_history.len() - 1;
        let v0 = (self.position_history[last - 2] - self.position_history[last - 3]) / dt_seconds;
        let v1 = (self.position_history[last - 1] - self.position_history[last - 2]) / dt_seconds;
        let v2 = (self.position_history[last] - self.position_history[last - 1]) / dt_seconds;
        let a0 = (v1 - v0) / dt_seconds;
        let a1 = (v2 - v1) / dt_seconds;
        (a1 - a0) / dt_seconds
    }

    fn run_time_step(&mut self, snapshot: &WorldSnapshot, rng: &mut SeededRandom) {
        let previous_velocity = self.velocity;
        let previous_acceleration = self.acceleration;
        let offside_line = assistant_offside_line_snapshot(snapshot, self.kind);
        let base_target = match self.kind {
            OfficialKind::CenterReferee => center_referee_play_centroid_target(snapshot),
            OfficialKind::AssistantRefereeNear => Vec2::new(
                assistant_ref_touchline_x(self.kind, snapshot.field_width),
                assistant_ref_half_y(
                    self.kind,
                    offside_line
                        .as_ref()
                        .map(|line| line.effective_line_y)
                        .unwrap_or(snapshot.ball.position.y),
                    snapshot.field_length,
                ),
            ),
            OfficialKind::AssistantRefereeFar => Vec2::new(
                assistant_ref_touchline_x(self.kind, snapshot.field_width),
                assistant_ref_half_y(
                    self.kind,
                    offside_line
                        .as_ref()
                        .map(|line| line.effective_line_y)
                        .unwrap_or(snapshot.ball.position.y),
                    snapshot.field_length,
                ),
            ),
        };
        let jitter = Vec2::new(rng.next_float() - 0.5, rng.next_float() - 0.5) * 0.25;
        let target = official_position_bounds(
            self.kind,
            official_clearance_target(self.kind, base_target + jitter, self.position, snapshot),
            snapshot.field_width,
            snapshot.field_length,
        );
        let desired = (target - self.position).normalized() * 6.1;
        self.velocity = approach_velocity(self.velocity, desired, 5.2, snapshot.dt_seconds);
        self.acceleration = if snapshot.dt_seconds > 0.0 {
            (self.velocity - previous_velocity) / snapshot.dt_seconds
        } else {
            Vec2::zero()
        };
        self.jerk = if snapshot.dt_seconds > 0.0 {
            (self.acceleration - previous_acceleration) / snapshot.dt_seconds
        } else {
            Vec2::zero()
        };
        self.position += self.velocity * snapshot.dt_seconds;
        self.position = official_position_bounds(
            self.kind,
            self.position,
            snapshot.field_width,
            snapshot.field_length,
        );
        let scheduled_index = snapshot
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Official && entry.id == self.id);
        let action = match self.kind {
            OfficialKind::CenterReferee => "track-center-of-play",
            OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar => {
                "track-offside-line"
            }
        };
        self.last_decision = Some(OfficialDecisionTrace {
            tick: snapshot.tick,
            action: action.to_string(),
            kind: self.kind,
            position: self.position,
            target,
            scheduled_index,
            offside_line_y: offside_line.as_ref().map(|line| line.effective_line_y),
            operation_order: official_agent_operation_order(
                snapshot.tick,
                self.id,
                self.kind,
                scheduled_index,
            ),
        });
        self.record_position_history();
    }
}

fn official_agent_operation_order(
    tick: u64,
    id: usize,
    kind: OfficialKind,
    scheduled_index: Option<usize>,
) -> Vec<String> {
    let kind_salt = match kind {
        OfficialKind::CenterReferee => 11,
        OfficialKind::AssistantRefereeNear => 23,
        OfficialKind::AssistantRefereeFar => 37,
    };
    let mut trace_rng = SeededRandom::new(
        (tick as u32)
            .wrapping_mul(2_246_822_519)
            .wrapping_add((id as u32).wrapping_mul(326_648_991))
            .wrapping_add((scheduled_index.unwrap_or(0) as u32).wrapping_mul(668_265_263))
            .wrapping_add(kind_salt),
    );
    let offside_weight = match kind {
        OfficialKind::CenterReferee => 0.42,
        OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar => 1.48,
    };
    let centroid_weight = match kind {
        OfficialKind::CenterReferee => 1.42,
        OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar => 0.76,
    };
    weighted_fisher_yates_order(
        vec![
            ("sense-ball".to_string(), 1.10),
            ("sample-offside-line".to_string(), offside_weight),
            ("choose-referee-target".to_string(), centroid_weight),
            ("avoid-player-lanes".to_string(), 0.94),
            ("clamp-duty-zone".to_string(), 1.24),
            ("update-kinematics".to_string(), 1.06),
        ],
        &mut trace_rng,
    )
}

fn assistant_ref_touchline_x(kind: OfficialKind, field_width: f64) -> f64 {
    match kind {
        OfficialKind::AssistantRefereeNear => -ASSISTANT_REF_TOUCHLINE_OFFSET_YARDS,
        OfficialKind::AssistantRefereeFar => field_width + ASSISTANT_REF_TOUCHLINE_OFFSET_YARDS,
        OfficialKind::CenterReferee => field_width * 0.5,
    }
}

fn assistant_ref_half_y(kind: OfficialKind, y: f64, field_length: f64) -> f64 {
    let half = field_length * 0.5;
    match kind {
        OfficialKind::AssistantRefereeNear => y.clamp(0.0, half),
        OfficialKind::AssistantRefereeFar => y.clamp(half, field_length),
        OfficialKind::CenterReferee => y.clamp(0.0, field_length),
    }
}

fn official_position_bounds(
    kind: OfficialKind,
    position: Vec2,
    field_width: f64,
    field_length: f64,
) -> Vec2 {
    match kind {
        OfficialKind::CenterReferee => position.clamp_to_pitch(field_width, field_length),
        OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar => Vec2::new(
            assistant_ref_touchline_x(kind, field_width),
            assistant_ref_half_y(kind, position.y, field_length),
        ),
    }
}

#[derive(Clone, Copy, Debug)]
struct CenterOfPlayCentroids {
    player_centroid: Vec2,
    live_play_centroid: Vec2,
    center_of_play: Vec2,
}

fn center_of_play_centroids(snapshot: &WorldSnapshot) -> CenterOfPlayCentroids {
    if snapshot.players.is_empty() {
        let center = Vec2::new(snapshot.field_width * 0.5, snapshot.field_length * 0.5);
        return CenterOfPlayCentroids {
            player_centroid: center,
            live_play_centroid: center,
            center_of_play: center,
        };
    }

    let mut player_sum = Vec2::zero();
    let mut live_play_sum = Vec2::zero();
    let mut live_play_weight = 0.0;
    for player in &snapshot.players {
        player_sum += player.position;
        let distance_to_ball = player.position.distance(snapshot.ball.position);
        let near_ball_weight = (1.0 - distance_to_ball / 42.0).clamp(0.0, 1.0);
        let holder_bonus = if snapshot.ball.holder == Some(player.id) {
            1.15
        } else {
            0.0
        };
        let weight = 0.28 + near_ball_weight * 1.72 + holder_bonus;
        live_play_sum += player.position * weight;
        live_play_weight += weight;
    }

    let player_centroid = player_sum / snapshot.players.len() as f64;
    let live_play_centroid = if live_play_weight > 0.0 {
        live_play_sum / live_play_weight
    } else {
        player_centroid
    };
    let center_of_play = (player_centroid * CENTER_REF_PLAYER_CENTROID_WEIGHT
        + live_play_centroid * CENTER_REF_LIVE_PLAY_CENTROID_WEIGHT
        + snapshot.ball.position * CENTER_REF_BALL_POSITION_WEIGHT)
        .clamp_to_pitch(snapshot.field_width, snapshot.field_length);
    CenterOfPlayCentroids {
        player_centroid,
        live_play_centroid,
        center_of_play,
    }
}

fn center_referee_play_centroid_target(snapshot: &WorldSnapshot) -> Vec2 {
    center_of_play_centroids(snapshot).center_of_play
}

fn official_clearance_target(
    kind: OfficialKind,
    target: Vec2,
    position: Vec2,
    snapshot: &WorldSnapshot,
) -> Vec2 {
    let clearance = match kind {
        OfficialKind::CenterReferee => CENTER_REF_BALL_CLEARANCE_YARDS,
        OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar => {
            ASSISTANT_REF_BALL_CLEARANCE_YARDS
        }
    };
    let fallback = official_clearance_fallback(kind, snapshot.ball.position, snapshot);
    let mut adjusted = point_with_clearance(target, snapshot.ball.position, fallback, clearance);

    if let Some(holder_position) = snapshot
        .ball
        .holder
        .and_then(|holder| snapshot.players.iter().find(|player| player.id == holder))
        .map(|player| player.position)
    {
        adjusted = point_with_clearance(adjusted, holder_position, fallback, clearance * 0.78);
    }

    let current_distance = position.distance(snapshot.ball.position);
    if current_distance < clearance {
        let away = if current_distance > 1e-6 {
            (position - snapshot.ball.position).normalized()
        } else {
            fallback
        };
        adjusted += away * (clearance - current_distance + 0.7);
    }

    adjusted.clamp_to_pitch(snapshot.field_width, snapshot.field_length)
}

fn point_with_clearance(point: Vec2, blocked: Vec2, fallback: Vec2, clearance: f64) -> Vec2 {
    let delta = point - blocked;
    let distance = delta.len();
    if distance >= clearance {
        point
    } else {
        let away = if distance > 1e-6 {
            delta.normalized()
        } else {
            fallback
        };
        blocked + away * clearance
    }
}

fn official_clearance_fallback(
    kind: OfficialKind,
    ball_position: Vec2,
    snapshot: &WorldSnapshot,
) -> Vec2 {
    match kind {
        OfficialKind::CenterReferee => {
            if ball_position.x <= snapshot.field_width * 0.5 {
                Vec2::new(1.0, 0.0)
            } else {
                Vec2::new(-1.0, 0.0)
            }
        }
        OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar => {
            if ball_position.y <= snapshot.field_length * 0.5 {
                Vec2::new(0.0, -1.0)
            } else {
                Vec2::new(0.0, 1.0)
            }
        }
    }
}

fn assistant_offside_line_snapshot(
    snapshot: &WorldSnapshot,
    kind: OfficialKind,
) -> Option<AssistantOffsideLineSnapshot> {
    let flank = match kind {
        OfficialKind::AssistantRefereeNear => AssistantFlank::Near,
        OfficialKind::AssistantRefereeFar => AssistantFlank::Far,
        OfficialKind::CenterReferee => return None,
    };
    let attacking_team = snapshot.possession_team()?;
    let defending_team = attacking_team.other();
    let mut defender_ys = snapshot
        .players
        .iter()
        .filter(|player| player.team == defending_team)
        .filter_map(|player| {
            snapshot
                .player_position(player.id)
                .map(|position| position.y)
        })
        .collect::<Vec<_>>();
    if defender_ys.len() < 2 {
        return None;
    }

    let halfway_y = snapshot.field_length * 0.5;
    let second_last_defender_y = match attacking_team {
        Team::Home => {
            defender_ys.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
            defender_ys[1]
        }
        Team::Away => {
            defender_ys.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            defender_ys[1]
        }
    };
    let effective_line_y = match attacking_team {
        Team::Home => snapshot
            .ball
            .position
            .y
            .max(second_last_defender_y)
            .max(halfway_y),
        Team::Away => snapshot
            .ball
            .position
            .y
            .min(second_last_defender_y)
            .min(halfway_y),
    };
    let players_beyond_line = snapshot
        .players
        .iter()
        .filter(|player| player.team == attacking_team)
        .filter_map(|player| {
            let position = snapshot.player_position(player.id)?;
            if !assistant_flank_contains(flank, position, snapshot.field_width) {
                return None;
            }
            let beyond_line = match attacking_team {
                Team::Home => position.y > effective_line_y,
                Team::Away => position.y < effective_line_y,
            };
            beyond_line.then_some(player.id)
        })
        .collect();

    Some(AssistantOffsideLineSnapshot {
        flank,
        attacking_team,
        defending_team,
        second_last_defender_y,
        ball_y: snapshot.ball.position.y,
        halfway_y,
        effective_line_y,
        players_beyond_line,
    })
}

fn assistant_flank_contains(flank: AssistantFlank, position: Vec2, field_width: f64) -> bool {
    match flank {
        AssistantFlank::Near => position.x <= field_width * 0.5,
        AssistantFlank::Far => position.x > field_width * 0.5,
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
