struct WorldSnapshotOptions {
    include_player_histories: bool,
    include_shared_histories: bool,
    include_player_decisions: bool,
    include_ball_history: bool,
}

impl WorldSnapshotOptions {
    const FULL: Self = Self {
        include_player_histories: true,
        include_shared_histories: true,
        include_player_decisions: true,
        include_ball_history: true,
    };

    const AGENT_DECISION: Self = Self {
        include_player_histories: false,
        include_shared_histories: false,
        include_player_decisions: false,
        include_ball_history: true,
    };

    const DEFENSIVE_OR_LOOSE_AGENT_DECISION: Self = Self {
        include_player_histories: false,
        include_shared_histories: false,
        include_player_decisions: false,
        include_ball_history: false,
    };

    const LEARNING: Self = Self {
        include_player_histories: false,
        include_shared_histories: false,
        include_player_decisions: false,
        include_ball_history: true,
    };

    const OFFICIAL_DECISION: Self = Self {
        include_player_histories: false,
        include_shared_histories: false,
        include_player_decisions: false,
        include_ball_history: false,
    };

    const LIVE_HTTP_FRAME: Self = Self {
        include_player_histories: true,
        include_shared_histories: false,
        include_player_decisions: false,
        include_ball_history: true,
    };
}

fn player_sample_forward_progress_over_seconds(
    history: &[PlayerPositionSample],
    current_position: Vec2,
    attack_dir: f64,
    current_clock_seconds: f64,
    seconds: f64,
) -> Option<f64> {
    if history.len() < 2 || seconds <= 0.0 {
        return None;
    }

    let latest_clock = if current_clock_seconds.is_finite() {
        current_clock_seconds
    } else {
        history
            .iter()
            .rev()
            .find(|sample| sample.clock_seconds.is_finite())
            .map(|sample| sample.clock_seconds)?
    };
    let target_clock = latest_clock - seconds;
    let mut oldest: Option<&PlayerPositionSample> = None;
    let mut previous: Option<&PlayerPositionSample> = None;

    for sample in history
        .iter()
        .filter(|sample| sample.clock_seconds.is_finite() && sample.clock_seconds <= latest_clock)
    {
        oldest.get_or_insert(sample);
        if let Some(prev) = previous {
            if prev.clock_seconds <= target_clock && target_clock <= sample.clock_seconds {
                let dt_seconds = sample.clock_seconds - prev.clock_seconds;
                if dt_seconds > 1e-9 {
                    let t = ((target_clock - prev.clock_seconds) / dt_seconds).clamp(0.0, 1.0);
                    let start_position = prev.position + (sample.position - prev.position) * t;
                    return Some((current_position.y - start_position.y) * attack_dir);
                }
            }
        }
        previous = Some(sample);
    }

    let oldest = oldest?;
    let elapsed_seconds = (latest_clock - oldest.clock_seconds).max(0.0);
    if elapsed_seconds >= seconds * 0.5 {
        let observed = (current_position.y - oldest.position.y) * attack_dir;
        Some(observed * (seconds / elapsed_seconds.max(1e-9)).clamp(0.5, 2.0))
    } else {
        None
    }
}

impl WorldSnapshot {
    fn from_match(m: &SoccerMatch) -> Self {
        Self::from_match_with_options(m, WorldSnapshotOptions::FULL)
    }

    fn from_match_for_agent_decision(m: &SoccerMatch) -> Self {
        Self::from_match_with_options(m, WorldSnapshotOptions::AGENT_DECISION)
    }

    fn from_match_for_defensive_or_loose_agent_decision(m: &SoccerMatch) -> Self {
        Self::from_match_with_options(m, WorldSnapshotOptions::DEFENSIVE_OR_LOOSE_AGENT_DECISION)
    }

    fn from_match_for_learning(m: &SoccerMatch) -> Self {
        Self::from_match_with_options(m, WorldSnapshotOptions::LEARNING)
    }

    fn from_match_for_official_decision(m: &SoccerMatch) -> Self {
        Self::from_match_with_options(m, WorldSnapshotOptions::OFFICIAL_DECISION)
    }

    fn formation_lp_guidance_for(
        &self,
        player_id: usize,
    ) -> Option<&SoccerFormationLpPlayerGuidance> {
        self.formation_lp_guidance
            .iter()
            .find(|guidance| guidance.player_id == player_id)
    }

    fn from_match_with_options(m: &SoccerMatch, options: WorldSnapshotOptions) -> Self {
        let shared_positions = if options.include_shared_histories {
            m.shared_positions.snapshot_with_current_players(
                &m.players,
                &m.officials,
                &m.ball,
                m.tick,
                m.clock_seconds,
                m.config.dt_seconds,
            )
        } else {
            m.shared_positions.latest_snapshot_with_current_players(
                &m.players,
                &m.officials,
                &m.ball,
                m.tick,
                m.clock_seconds,
                m.config.dt_seconds,
            )
        };
        let players =
            m.players
                .iter()
                .map(|p| PlayerSnapshot {
                    id: p.id,
                    name: p.name.clone(),
                    team: p.team,
                    role: p.role,
                    shirt: p.shirt,
                    position: p.position,
                    position_history: if options.include_player_histories {
                        p.position_history.iter().cloned().collect()
                    } else {
                        Vec::new()
                    },
                    velocity: p.velocity,
                    movement_gait: p.movement_gait,
                    receive_facing: p.receive_facing,
                    action_facing: p.action_facing,
                    incoming_ball: p.incoming_ball.clone(),
                    skills: p.skills.clone(),
                    fatigue: p.fatigue,
                    home_position: p.home_position,
                    controller_slot: p.controller_slot,
                    scheduled_index: m.last_agent_schedule.iter().position(|entry| {
                        entry.kind == AgentScheduleKind::Player && entry.id == p.id
                    }),
                    preferences: p.preferences.clone(),
                    vision_range_yards: vision_range_yards(p.skills.vision),
                    field_of_view_degrees: field_of_view_degrees(p.skills.vision),
                    acceleration: shared_positions
                        .latest_for(p.id)
                        .map(|sample| sample.acceleration)
                        .unwrap_or(p.acceleration),
                    jerk: shared_positions
                        .latest_for(p.id)
                        .map(|sample| sample.jerk)
                        .unwrap_or(p.jerk),
                    last_decision: if options.include_player_decisions {
                        p.last_decision.clone()
                    } else {
                        None
                    },
                    learned_policy: None,
                })
                .collect::<Vec<_>>();
        let pending_pass = m.pending_pass.as_ref().map(|pass| {
            pending_pass_snapshot_from(pass, m.ball.position, m.ball.velocity, &players)
        });
        let possession_elapsed = m
            .possession_progress_tracker
            .as_ref()
            .map(|tracker| tracker.elapsed_seconds(m.clock_seconds))
            .unwrap_or(0.0);
        let (home_team_possession_seconds, away_team_possession_seconds) = match m
            .possession_progress_tracker
            .as_ref()
            .map(|tracker| tracker.team)
        {
            Some(Team::Home) => (possession_elapsed, 0.0),
            Some(Team::Away) => (0.0, possession_elapsed),
            None => (0.0, 0.0),
        };
        let ball_holder_possession_seconds = m
            .ball
            .holder
            .map(|holder| {
                let mut start_clock = m.clock_seconds;
                for sample in m.ball.position_history.iter().rev() {
                    if sample.holder == Some(holder) {
                        start_clock = sample.clock_seconds;
                    } else {
                        break;
                    }
                }
                (m.clock_seconds - start_clock).max(0.0)
            })
            .unwrap_or(0.0);
        let mut ball = m.ball.to_state();
        ball.scheduled_index = m
            .last_agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID);

        WorldSnapshot {
            tick: m.tick,
            clock_seconds: m.clock_seconds,
            dt_seconds: m.config.dt_seconds,
            field_length: m.config.field_length_yards,
            field_width: m.config.field_width_yards,
            goal_width: m.config.goal_width_yards,
            ball,
            ball_history: if options.include_ball_history {
                m.ball.position_history.iter().cloned().collect()
            } else {
                Vec::new()
            },
            pending_pass,
            pending_rebound: m.pending_rebound.clone(),
            active_set_play: m.active_set_play.clone(),
            players,
            shared_positions,
            agent_schedule: m.last_agent_schedule.clone(),
            score_home: m.score_home,
            score_away: m.score_away,
            phase: m.central_brain.phase,
            home_directive: m.central_brain.home_directive.clone(),
            away_directive: m.central_brain.away_directive.clone(),
            formation_lp_enabled: m.config.formation_lp_enabled,
            home_team_possession_seconds,
            away_team_possession_seconds,
            ball_holder_possession_seconds,
            formation_lp_guidance: if m.config.formation_lp_enabled {
                m.central_brain.formation_lp_guidance()
            } else {
                Vec::new()
            },
            formation_lp_teams: if m.config.formation_lp_enabled {
                m.central_brain.formation_lp_team_snapshots()
            } else {
                Vec::new()
            },
        }
    }

    pub fn possession_team(&self) -> Option<Team> {
        self.ball
            .holder
            .and_then(|id| self.players.iter().find(|p| p.id == id))
            .map(|p| p.team)
            .or(self.ball.last_touch_team)
    }

    pub fn controlled_possession_team(&self) -> Option<Team> {
        self.ball
            .holder
            .and_then(|id| self.players.iter().find(|p| p.id == id))
            .map(|p| p.team)
    }

    fn possession_team_for_ball_sample(&self, sample: &BallPositionSample) -> Option<Team> {
        sample
            .holder
            .and_then(|id| self.players.iter().find(|p| p.id == id))
            .map(|p| p.team)
            .or(sample.last_touch_team)
    }

    fn possession_elapsed_seconds_for_team(&self, team: Team) -> f64 {
        if self.possession_team() != Some(team) {
            return 0.0;
        }
        let mut oldest_same_team = self.clock_seconds;
        for sample in self.ball_history.iter().rev() {
            if self.possession_team_for_ball_sample(sample) == Some(team) {
                oldest_same_team = sample.clock_seconds;
            } else {
                break;
            }
        }
        (self.clock_seconds - oldest_same_team).max(0.0)
    }

    fn possession_spacing_weight(&self, team: Team) -> f64 {
        let settled = (self.possession_elapsed_seconds_for_team(team) / SETTLED_POSSESSION_SECONDS)
            .clamp(0.0, 1.0);
        0.35 + settled * 0.65
    }

    fn team_spacing_mode_for(&self, team: Team) -> Option<TeamSpacingMode> {
        match self.possession_team() {
            Some(t) if t == team => Some(TeamSpacingMode::InPossession),
            Some(_) => Some(TeamSpacingMode::Defending),
            None => None,
        }
    }

    fn striker_holder_in_opponent_half(&self, team: Team) -> Option<(usize, Vec2)> {
        let holder_id = self.ball.holder?;
        let holder = self.players.iter().find(|player| player.id == holder_id)?;
        if holder.team != team
            || holder.role != PlayerRole::Forward
            || !position_in_opponent_half(team, self.ball.position, self.field_length)
        {
            return None;
        }
        Some((
            holder_id,
            self.player_position(holder_id)
                .unwrap_or(self.ball.position),
        ))
    }

    fn opponent_striker_holder_in_attacking_half(&self, defending_team: Team) -> Option<Vec2> {
        self.striker_holder_in_opponent_half(defending_team.other())
            .map(|(_, position)| position)
    }

    fn team_speed_surge_active(&self, team: Team) -> bool {
        self.players.iter().any(|player| {
            player.team == team
                && matches!(
                    player.movement_gait,
                    MovementGait::Run | MovementGait::Sprint
                )
        })
    }

    fn attacking_support_sprint_active(&self, team: Team) -> bool {
        self.striker_holder_in_opponent_half(team).is_some() || self.team_speed_surge_active(team)
    }

    fn defensive_tracking_sprint_active(&self, team: Team) -> bool {
        self.opponent_striker_holder_in_attacking_half(team)
            .is_some()
            || self.team_speed_surge_active(team.other())
    }

    fn player_snapshot_position(&self, player: &PlayerSnapshot) -> Vec2 {
        if let Some(sample) = self.shared_positions.latest.get(player.id) {
            if sample.player_id == player.id {
                return sample.position;
            }
        }
        self.shared_positions
            .latest_for(player.id)
            .map(|sample| sample.position)
            .unwrap_or(player.position)
    }

    pub fn player_position(&self, player_id: usize) -> Option<Vec2> {
        self.shared_positions
            .latest_for(player_id)
            .map(|sample| sample.position)
            .or_else(|| {
                self.players
                    .iter()
                    .find(|p| p.id == player_id)
                    .map(|p| p.position)
            })
    }

    pub fn set_player_position(&mut self, player_id: usize, position: Vec2) {
        let player_index = self
            .players
            .iter()
            .position(|player| player.id == player_id);
        let mut sample = player_index
            .map(|index| {
                let player = &self.players[index];
                PlayerPositionSample {
                    player_id,
                    tick: self.tick,
                    clock_seconds: self.clock_seconds,
                    position,
                    velocity: player.velocity,
                    acceleration: player.acceleration,
                    jerk: player.jerk,
                }
            })
            .or_else(|| self.shared_positions.latest_for(player_id).cloned())
            .unwrap_or(PlayerPositionSample {
                player_id,
                tick: self.tick,
                clock_seconds: self.clock_seconds,
                position,
                velocity: Vec2::zero(),
                acceleration: Vec2::zero(),
                jerk: Vec2::zero(),
            });
        sample.position = position;

        if let Some(index) = player_index {
            self.players[index].position = position;
        }
        if let Some(latest) = self
            .shared_positions
            .latest
            .iter_mut()
            .find(|latest| latest.player_id == player_id)
        {
            *latest = sample.clone();
        } else {
            self.shared_positions.latest.push(sample.clone());
        }

        let history = self
            .shared_positions
            .histories
            .entry(player_id)
            .or_default();
        if let Some(last) = history.last_mut() {
            *last = sample;
        } else {
            history.push(sample);
        }
    }

    pub fn player_velocity(&self, player_id: usize) -> Option<Vec2> {
        self.shared_positions
            .latest_for(player_id)
            .map(|sample| sample.velocity)
            .or_else(|| {
                self.players
                    .iter()
                    .find(|p| p.id == player_id)
                    .map(|p| p.velocity)
            })
    }

    pub fn player_acceleration(&self, player_id: usize) -> Option<Vec2> {
        self.shared_positions
            .latest_for(player_id)
            .map(|sample| sample.acceleration)
            .or_else(|| {
                self.players
                    .iter()
                    .find(|p| p.id == player_id)
                    .map(|p| p.acceleration)
            })
    }

    pub fn player_jerk(&self, player_id: usize) -> Option<Vec2> {
        self.shared_positions
            .latest_for(player_id)
            .map(|sample| sample.jerk)
            .or_else(|| {
                self.players
                    .iter()
                    .find(|p| p.id == player_id)
                    .map(|p| p.jerk)
            })
    }

    pub fn player_position_history(&self, player_id: usize) -> Option<&[PlayerPositionSample]> {
        self.shared_positions.history_for(player_id)
    }

    pub fn ball_position_history(&self) -> &[BallPositionSample] {
        &self.ball_history
    }

    fn active_set_play_is_live(&self, call: &SoccerSetPlayCall) -> bool {
        self.tick <= call.expires_tick && self.clock_seconds <= call.expires_clock_seconds
    }

    pub fn active_set_play_assignment_for(
        &self,
        player_id: usize,
    ) -> Option<&SoccerSetPlayAssignment> {
        let call = self.active_set_play.as_ref()?;
        if !self.active_set_play_is_live(call) {
            return None;
        }
        call.assignments
            .iter()
            .find(|assignment| assignment.player_id == player_id)
    }

    fn active_set_play_release_for(
        &self,
        taker_id: usize,
        restart_label: &str,
    ) -> Option<(SoccerAction, String)> {
        let call = self.active_set_play.as_ref()?;
        if !self.active_set_play_is_live(call)
            || !set_play_restart_labels_match(&call.restart, restart_label)
        {
            return None;
        }
        let taker = self.players.iter().find(|player| player.id == taker_id)?;
        if taker.team != call.team {
            return None;
        }
        let is_taker = call.assignments.iter().any(|assignment| {
            assignment.player_id == taker_id
                && assignment.role == SoccerSetPlayAssignmentRole::Taker
        });
        if !is_taker {
            return None;
        }
        let elapsed = (self.clock_seconds - call.started_clock_seconds).max(0.0);
        let release_delay = call
            .assignments
            .iter()
            .filter(|assignment| assignment.role != SoccerSetPlayAssignmentRole::Taker)
            .filter(|assignment| assignment.release_after_seconds.is_finite())
            .map(|assignment| assignment.release_after_seconds)
            .fold(0.0, f64::max)
            .clamp(0.0, SOCCER_SET_PLAY_MAX_RELEASE_DELAY_SECONDS);
        if elapsed + 1e-9 < release_delay {
            return Some((
                SoccerAction::MoveTo(taker.position),
                "hold-restart".to_string(),
            ));
        }
        let release_player = call.release_player.filter(|player_id| {
            self.players
                .iter()
                .any(|player| player.id == *player_id && player.team == call.team)
        });
        let release_power = if call.release_power.is_finite() {
            call.release_power.clamp(0.0, 1.0)
        } else {
            0.65
        };
        let action = match call.release_kind {
            SoccerSetPlayReleaseKind::Pass => SoccerAction::Pass {
                target_player: release_player,
                power: release_power,
                flight: PassFlight::Floor,
            },
            SoccerSetPlayReleaseKind::AerialPass => SoccerAction::Pass {
                target_player: release_player,
                power: release_power,
                flight: PassFlight::Aerial,
            },
            SoccerSetPlayReleaseKind::Shoot => SoccerAction::Shoot {
                power: release_power,
            },
        };
        Some((action, restart_label.to_string()))
    }

    fn nearest_opponent_at(&self, team: Team, position: Vec2) -> Option<(usize, Vec2, f64)> {
        let (width, length) = sane_pitch_dimensions(self.field_width, self.field_length);
        let center = Vec2::new(width * 0.5, length * 0.5);
        let position = finite_pitch_point(position, width, length, center);
        self.players
            .iter()
            .filter(|player| player.team == team.other())
            .filter_map(|player| {
                let player_position = finite_pitch_point(
                    self.player_snapshot_position(player),
                    width,
                    length,
                    player.home_position,
                );
                Some((
                    player.id,
                    player_position,
                    player_position.distance(position),
                ))
            })
            .min_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal))
    }

    fn nearest_opponent_distance_at(&self, team: Team, position: Vec2) -> f64 {
        self.nearest_opponent_at(team, position)
            .map(|(_, _, distance)| distance)
            .unwrap_or(f64::INFINITY)
    }

    fn no_pressure_at(&self, team: Team, position: Vec2) -> bool {
        self.nearest_opponent_distance_at(team, position) > NO_PRESSURE_BACK_PASS_THRESHOLD_YARDS
    }

    fn candidate_occupancy_at(
        &self,
        team: Team,
        position: Vec2,
        exclude_player_id: Option<usize>,
    ) -> CandidateOccupancy {
        let (width, length) = sane_pitch_dimensions(self.field_width, self.field_length);
        let center = Vec2::new(width * 0.5, length * 0.5);
        let position = finite_pitch_point(position, width, length, center);
        let mut opponent_distance_sq: f64 = 35.0_f64.powi(2);
        let mut teammate_crowding_sq: f64 = 25.0_f64.powi(2);
        let mut nearest_teammate_distance_sq = f64::INFINITY;
        for player in &self.players {
            let player_position = finite_pitch_point(
                self.player_snapshot_position(player),
                width,
                length,
                player.home_position,
            );
            let delta = player_position - position;
            let distance_sq = delta.x * delta.x + delta.y * delta.y;
            if player.team != team {
                opponent_distance_sq = opponent_distance_sq.min(distance_sq);
            } else {
                if distance_sq > 0.01 {
                    teammate_crowding_sq = teammate_crowding_sq.min(distance_sq);
                }
                if exclude_player_id != Some(player.id) {
                    nearest_teammate_distance_sq = nearest_teammate_distance_sq.min(distance_sq);
                }
            }
        }
        let opponent_distance = opponent_distance_sq.sqrt();
        let teammate_crowding = teammate_crowding_sq.sqrt();
        let nearest_teammate_distance = nearest_teammate_distance_sq.sqrt();
        CandidateOccupancy {
            open_space_score: open_space_score_from_distances(opponent_distance, teammate_crowding),
            nearest_teammate_distance,
        }
    }

    fn nearest_teammate_distance_at(
        &self,
        team: Team,
        position: Vec2,
        exclude_player_id: Option<usize>,
    ) -> f64 {
        self.candidate_occupancy_at(team, position, exclude_player_id)
            .nearest_teammate_distance
    }

    fn teammate_occupied_space_pressure_at(
        &self,
        team: Team,
        position: Vec2,
        exclude_player_id: Option<usize>,
    ) -> f64 {
        self.candidate_occupancy_at(team, position, exclude_player_id)
            .teammate_occupied_space_pressure()
    }

    fn teammate_occupied_space_penalty_at(
        &self,
        team: Team,
        position: Vec2,
        exclude_player_id: Option<usize>,
        relief: f64,
    ) -> f64 {
        let pressure =
            self.effective_teammate_spacing_pressure_at(team, position, exclude_player_id, relief);
        TEAMMATE_OCCUPIED_SPACE_MAX_PENALTY * pressure
    }

    fn effective_teammate_spacing_pressure_at(
        &self,
        team: Team,
        position: Vec2,
        exclude_player_id: Option<usize>,
        relief: f64,
    ) -> f64 {
        self.teammate_occupied_space_pressure_at(team, position, exclude_player_id)
            * (1.0 - relief.clamp(0.0, 0.78))
    }

    fn team_spacing_score_for_candidate(
        &self,
        team: Team,
        exclude_player_id: Option<usize>,
        position: Vec2,
        mode: TeamSpacingMode,
    ) -> f64 {
        self.candidate_occupancy_at(team, position, exclude_player_id)
            .team_spacing_score(mode)
    }

    fn vertical_lane_fit_for_player_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
        relief: f64,
    ) -> VerticalLaneFit {
        let in_possession = self
            .controlled_possession_team()
            .or_else(|| self.possession_team())
            == Some(player.team);
        vertical_lane_fit_for_role_target(
            player.role,
            player.home_position.x,
            target.x,
            self.field_width,
            in_possession,
            relief,
        )
    }

    fn vertical_lane_penalty_for_player_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
        relief: f64,
    ) -> f64 {
        let fit = self.vertical_lane_fit_for_player_target(player, target, relief);
        if fit.commitment <= 1e-9 {
            return 0.0;
        }
        (1.0 - fit.affinity_score) * (3.4 + fit.commitment * 5.6)
            + fit.deviation_yards * 0.070 * fit.commitment
    }

    fn offensive_high_speed_run_relief(&self, player: &PlayerSnapshot, target: Vec2) -> f64 {
        if self
            .controlled_possession_team()
            .or_else(|| self.possession_team())
            != Some(player.team)
            || player.role == PlayerRole::Goalkeeper
        {
            return 0.0;
        }
        let current = self.player_snapshot_position(player);
        let Some((_, teammate_position, teammate_distance)) = self
            .players
            .iter()
            .filter(|teammate| teammate.team == player.team && teammate.id != player.id)
            .map(|teammate| {
                let teammate_position = self.player_snapshot_position(teammate);
                (
                    teammate.id,
                    teammate_position,
                    teammate_position
                        .distance(current)
                        .min(teammate_position.distance(target)),
                )
            })
            .filter(|(_, _, distance)| *distance <= OFFENSIVE_OVERLAP_RELIEF_TEAMMATE_RADIUS_YARDS)
            .min_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal))
        else {
            return 0.0;
        };
        let forward = (target.y - current.y) * player.team.attack_dir();
        let velocity = self.player_velocity(player.id).unwrap_or(player.velocity);
        let speed = velocity.len();
        let motion_forward = (velocity.y * player.team.attack_dir()).max(0.0);
        let projected = target
            + velocity
                * self
                    .dt_seconds
                    .max(DEFAULT_DT_SECONDS)
                    .max(OFFENSIVE_OVERLAP_RELIEF_LOOKAHEAD_SECONDS);
        let current_vs_teammate = (current.y - teammate_position.y) * player.team.attack_dir();
        let target_vs_teammate = (target.y - teammate_position.y) * player.team.attack_dir();
        let projected_vs_teammate = (projected.y - teammate_position.y) * player.team.attack_dir();
        let max_forward_vs_teammate = current_vs_teammate
            .max(target_vs_teammate)
            .max(projected_vs_teammate);
        let passing_teammate_fit =
            ((max_forward_vs_teammate - OFFENSIVE_OVERLAP_RELIEF_MIN_FORWARD_YARDS) / 3.0)
                .clamp(0.0, 1.0);
        let close_teammate_fit = ((OFFENSIVE_OVERLAP_RELIEF_TEAMMATE_RADIUS_YARDS
            - teammate_distance)
            / (OFFENSIVE_OVERLAP_RELIEF_TEAMMATE_RADIUS_YARDS
                - TEAMMATE_OCCUPIED_SPACE_HARD_RADIUS_YARDS)
                .max(1e-6))
        .clamp(0.0, 1.0);
        let forward_fit = ((forward.max(motion_forward * 0.70) - 3.0) / 10.0).clamp(0.0, 1.0);
        let speed_fit = ((speed - 4.5) / 3.0).clamp(0.0, 1.0);
        (forward_fit * speed_fit * passing_teammate_fit * close_teammate_fit * 0.60)
            .clamp(0.0, 0.60)
    }

    fn positional_shape_exception_relief_for_player_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
    ) -> f64 {
        self.offensive_high_speed_run_relief(player, target)
            .max(self.defensive_tracking_relief(player, target))
    }

    fn defensive_tracking_relief(&self, player: &PlayerSnapshot, target: Vec2) -> f64 {
        if self
            .controlled_possession_team()
            .or_else(|| self.possession_team())
            != Some(player.team.other())
            || !matches!(player.role, PlayerRole::Defender | PlayerRole::Midfielder)
        {
            return 0.0;
        }
        let Some(holder_id) = self.ball.holder else {
            return 0.0;
        };
        let Some(holder) = self
            .players
            .iter()
            .find(|candidate| candidate.id == holder_id && candidate.team == player.team.other())
        else {
            return 0.0;
        };
        let holder_position = self.player_snapshot_position(holder);
        let current = self.player_snapshot_position(player);
        let current_distance = current.distance(holder_position);
        let target_distance = target.distance(holder_position);
        if current_distance > DEFENSIVE_TRACKING_RELIEF_RADIUS_YARDS
            || target_distance > DEFENSIVE_TRACKING_RELIEF_TARGET_RADIUS_YARDS
        {
            return 0.0;
        }
        let player_tracking_distance = current_distance.min(target_distance);
        let player_tracking_score =
            defensive_tracking_marker_score(player, player_tracking_distance);
        let teammate_has_better_marker_claim = self.players.iter().any(|candidate| {
            candidate.team == player.team
                && candidate.id != player.id
                && matches!(
                    candidate.role,
                    PlayerRole::Defender | PlayerRole::Midfielder
                )
                && defensive_tracking_marker_score(
                    candidate,
                    self.player_snapshot_position(candidate)
                        .distance(holder_position),
                ) > player_tracking_score + 1e-9
        });
        if teammate_has_better_marker_claim {
            return 0.0;
        }
        (0.48 + ability01(player.skills.defensive_tracking) * 0.34).clamp(0.0, 0.82)
    }

    fn role_line_deviation_yards_for_target(&self, player: &PlayerSnapshot, target: Vec2) -> f64 {
        if !matches!(player.role, PlayerRole::Defender | PlayerRole::Midfielder) {
            return 0.0;
        }
        let mut total_y = 0.0;
        let mut count = 0usize;
        for teammate in self.players.iter().filter(|teammate| {
            teammate.team == player.team && teammate.role == player.role && teammate.id != player.id
        }) {
            total_y += self.player_snapshot_position(teammate).y;
            count += 1;
        }
        if count < 2 {
            0.0
        } else {
            (target.y - total_y / count as f64).abs()
        }
    }

    fn role_line_cohesion_error_yards_for_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
    ) -> f64 {
        let tolerance = match player.role {
            PlayerRole::Defender => DEFENDER_LINE_COHESION_TOLERANCE_YARDS,
            PlayerRole::Midfielder => MIDFIELDER_LINE_COHESION_TOLERANCE_YARDS,
            PlayerRole::Goalkeeper | PlayerRole::Forward => return 0.0,
        };
        let mut total_gap = 0.0;
        let mut max_gap: f64 = 0.0;
        let mut count = 0usize;
        for teammate in self.players.iter().filter(|teammate| {
            teammate.team == player.team && teammate.role == player.role && teammate.id != player.id
        }) {
            let gap = (target.y - self.player_snapshot_position(teammate).y).abs();
            total_gap += gap;
            max_gap = max_gap.max(gap);
            count += 1;
        }
        if count < 2 {
            return 0.0;
        }
        let blended_gap = total_gap / count as f64 * 0.70 + max_gap * 0.30;
        (blended_gap - tolerance).max(0.0)
    }

    fn role_line_cohesion_score_for_player_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
    ) -> f64 {
        (1.0 - self.role_line_cohesion_error_yards_for_target(player, target)
            / ROLE_LINE_COHESION_DECAY_YARDS)
            .clamp(0.0, 1.0)
    }

    fn role_line_cohesion_penalty_for_player_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
        relief: f64,
    ) -> f64 {
        let in_possession = self
            .controlled_possession_team()
            .or_else(|| self.possession_team())
            == Some(player.team);
        let weight = match (player.role, in_possession) {
            (PlayerRole::Defender, true) => 0.026,
            (PlayerRole::Defender, false) => 0.088,
            (PlayerRole::Midfielder, true) => 0.014,
            (PlayerRole::Midfielder, false) => 0.056,
            _ => 0.0,
        };
        self.role_line_cohesion_error_yards_for_target(player, target)
            * weight
            * (1.0 - relief.clamp(0.0, 0.82))
    }

    fn role_line_penalty_for_player_target(
        &self,
        player: &PlayerSnapshot,
        target: Vec2,
        relief: f64,
    ) -> f64 {
        let in_possession = self
            .controlled_possession_team()
            .or_else(|| self.possession_team())
            == Some(player.team);
        let weight = match (player.role, in_possession) {
            (PlayerRole::Defender, true) => 0.030,
            (PlayerRole::Defender, false) => 0.095,
            (PlayerRole::Midfielder, true) => 0.012,
            (PlayerRole::Midfielder, false) => 0.070,
            _ => 0.0,
        };
        let deviation = self.role_line_deviation_yards_for_target(player, target);
        (deviation - 5.5).max(0.0) * weight * (1.0 - relief.clamp(0.0, 0.80))
            + self.role_line_cohesion_penalty_for_player_target(player, target, relief)
    }

    fn own_goal_y_for(&self, team: Team) -> f64 {
        team.other().goal_y(self.field_length)
    }

    fn ball_near_own_goal_line(&self, team: Team) -> bool {
        (self.ball.position.y - self.own_goal_y_for(team)).abs() <= DEFENSIVE_GOAL_LINE_BUFFER_YARDS
    }

    fn depth_from_own_goal_y(&self, team: Team, y: f64) -> f64 {
        ((y - self.own_goal_y_for(team)) * team.attack_dir()).clamp(0.0, self.field_length)
    }

    fn y_from_own_goal_depth(&self, team: Team, depth: f64) -> f64 {
        self.own_goal_y_for(team) + team.attack_dir() * depth.clamp(0.0, self.field_length)
    }

    fn midfielder_deep_retreat_allowed(&self, player_id: usize) -> bool {
        deterministic_unit_draw(self.tick, player_id, 389) < MIDFIELDER_DEEP_RETREAT_CHANCE
    }

    fn minimum_defensive_depth_from_own_goal(&self, player: &PlayerSnapshot) -> f64 {
        let ball_depth = self.depth_from_own_goal_y(player.team, self.ball.position.y);
        match player.role {
            PlayerRole::Goalkeeper => 0.0,
            PlayerRole::Defender => {
                if ball_depth <= DEFENSIVE_GOAL_LINE_BUFFER_YARDS {
                    0.0
                } else {
                    DEFENSIVE_GOAL_LINE_BUFFER_YARDS
                }
            }
            PlayerRole::Midfielder => {
                if ball_depth <= MIDFIELDER_STANDARD_RETREAT_LINE_YARDS {
                    if self.midfielder_deep_retreat_allowed(player.id) {
                        MIDFIELDER_DEEP_RETREAT_LINE_YARDS
                    } else {
                        MIDFIELDER_STANDARD_RETREAT_LINE_YARDS
                    }
                } else {
                    MIDFIELDER_DEEP_RETREAT_LINE_YARDS
                }
            }
            PlayerRole::Forward => self.field_length * 0.5,
        }
    }

    fn goal_side_defensive_target_for_player(&self, player: &PlayerSnapshot, target: Vec2) -> Vec2 {
        if player.role == PlayerRole::Goalkeeper
            || self
                .controlled_possession_team()
                .or_else(|| self.possession_team())
                != Some(player.team.other())
        {
            return target.clamp_to_pitch(self.field_width, self.field_length);
        }

        let ball_depth = self.depth_from_own_goal_y(player.team, self.ball.position.y);
        let mut target_depth = self.depth_from_own_goal_y(player.team, target.y);
        let min_depth = self.minimum_defensive_depth_from_own_goal(player);
        let cushion = match player.role {
            PlayerRole::Defender if ball_depth <= DEFENSIVE_GOAL_LINE_BUFFER_YARDS => ball_depth,
            PlayerRole::Defender => DEFENSIVE_GOAL_SIDE_CUSHION_YARDS + 1.25,
            PlayerRole::Midfielder => DEFENSIVE_GOAL_SIDE_CUSHION_YARDS,
            PlayerRole::Forward => DEFENSIVE_GOAL_SIDE_CUSHION_YARDS * 0.70,
            PlayerRole::Goalkeeper => 0.0,
        };
        let goal_side_depth = (ball_depth - cushion).max(0.0);
        target_depth = target_depth.min(goal_side_depth).max(min_depth);

        let mut guarded = target;
        guarded.y = self.y_from_own_goal_depth(player.team, target_depth);
        guarded.clamp_to_pitch(self.field_width, self.field_length)
    }

    fn goal_side_defensive_target_for(&self, player_id: usize, target: Vec2) -> Vec2 {
        self.players
            .iter()
            .find(|player| player.id == player_id)
            .map(|player| self.goal_side_defensive_target_for_player(player, target))
            .unwrap_or_else(|| target.clamp_to_pitch(self.field_width, self.field_length))
    }

    fn goalkeeper_ball_goal_tracking_target(&self, team: Team) -> Vec2 {
        let goal = Vec2::new(self.field_width * 0.5, self.own_goal_y_for(team));
        let to_ball = self.ball.position - goal;
        let ball_distance = to_ball.len();
        if ball_distance <= 1e-9 {
            return goal.clamp_to_pitch(self.field_width, self.field_length);
        }
        let ball_pressure = (1.0 - ball_distance / 72.0).clamp(0.0, 1.0);
        let holder_pressure = self
            .ball
            .holder
            .and_then(|holder| self.players.iter().find(|player| player.id == holder))
            .filter(|holder| holder.team == team.other())
            .map(|holder| {
                let holder_position = self.player_snapshot_position(holder);
                let line_gap = (holder_position.y - goal.y).abs();
                (1.0 - line_gap / 42.0).clamp(0.0, 1.0)
            })
            .unwrap_or(0.0);
        let raw_depth = (3.5 + ball_pressure * 12.5 + holder_pressure * 4.2).clamp(3.5, 18.0);
        let depth = raw_depth.min((ball_distance - 0.85).max(0.0));
        (goal + to_ball.normalized() * depth).clamp_to_pitch(self.field_width, self.field_length)
    }

    fn goalkeeper_direct_intervention_is_safe(&self, keeper_id: usize) -> bool {
        let Some(keeper) = self.players.iter().find(|player| player.id == keeper_id) else {
            return false;
        };
        if keeper.role != PlayerRole::Goalkeeper {
            return true;
        }
        let current = self.player_snapshot_position(keeper);
        if current.distance(self.ball.position) > GOALKEEPER_LINE_SAFE_INTERVENTION_RADIUS_YARDS {
            return false;
        }
        let goal = Vec2::new(self.field_width * 0.5, self.own_goal_y_for(keeper.team));
        let projection = segment_projection_factor(goal, self.ball.position, current);
        (0.0..=1.0).contains(&projection)
            && segment_distance_to_point(goal, self.ball.position, current)
                <= GOALKEEPER_LINE_SAFE_INTERVENTION_DEVIATION_YARDS
    }

    fn goalkeeper_line_recovery_sprint_active(&self, keeper_id: usize) -> bool {
        let Some(keeper) = self.players.iter().find(|player| player.id == keeper_id) else {
            return false;
        };
        if keeper.role != PlayerRole::Goalkeeper {
            return false;
        }
        if self.ball.holder == Some(keeper_id) {
            return false;
        }
        let current = self.player_snapshot_position(keeper);
        let line_target = self.goalkeeper_ball_goal_tracking_target(keeper.team);
        let goal = Vec2::new(self.field_width * 0.5, self.own_goal_y_for(keeper.team));
        let line_deviation = segment_distance_to_point(goal, self.ball.position, current);
        let projection = segment_projection_factor(goal, self.ball.position, current);
        if current.distance(line_target) < GOALKEEPER_LINE_RECOVERY_SPRINT_DISTANCE_YARDS
            && line_deviation < GOALKEEPER_LINE_RECOVERY_DEVIATION_YARDS
            && (0.0..=1.0).contains(&projection)
        {
            return false;
        }
        line_deviation >= GOALKEEPER_LINE_RECOVERY_DEVIATION_YARDS
            || !(0.0..=1.0).contains(&projection)
            || goalkeeper_ball_goal_line_alignment_score(keeper.team, current, self)
                < GOALKEEPER_LINE_RECOVERY_SPRINT_ALIGNMENT_SCORE
    }

    fn opponent_breakthrough_ball_carrier(&self, team: Team) -> Option<(Vec2, f64)> {
        let holder_id = self.ball.holder?;
        let holder = self
            .players
            .iter()
            .find(|player| player.id == holder_id && player.team == team.other())?;
        if holder.role == PlayerRole::Goalkeeper {
            return None;
        }
        let holder_position = self.player_snapshot_position(holder);
        let own_goal_y = self.own_goal_y_for(team);
        let ball_goal_distance = (holder_position.y - own_goal_y).abs();
        if ball_goal_distance > self.field_length * 0.62 {
            return None;
        }

        let mut defender_y_total = 0.0;
        let mut defender_count = 0usize;
        for defender in self
            .players
            .iter()
            .filter(|player| player.team == team && player.role == PlayerRole::Defender)
        {
            defender_y_total += self.player_snapshot_position(defender).y;
            defender_count += 1;
        }
        if defender_count < 3 {
            return None;
        }
        let defensive_line_y = defender_y_total / defender_count as f64;
        let own_goal_y = self.own_goal_y_for(team);
        let line_advancement_from_goal = (defensive_line_y - own_goal_y) * team.attack_dir();
        if line_advancement_from_goal < DEFENSIVE_LINE_BREAK_MIN_ADVANCEMENT_FROM_GOAL_YARDS {
            return None;
        }
        let line_gap = (holder_position.y - defensive_line_y) * team.attack_dir();
        let carrier_velocity = self.player_velocity(holder.id).unwrap_or(holder.velocity);
        let carrier_goalward_speed = (-(carrier_velocity.y * team.attack_dir())).max(0.0);
        let projected_line_gap =
            if carrier_goalward_speed >= DEFENSIVE_LINE_BREAK_CARRIER_SPEED_TRIGGER_YPS {
                line_gap - carrier_goalward_speed * DEFENSIVE_LINE_BREAK_CARRIER_LOOKAHEAD_SECONDS
            } else {
                line_gap
            };
        if !(-16.0..=DEFENSIVE_LINE_BREAK_TRIGGER_GAP_YARDS).contains(&projected_line_gap) {
            return None;
        }
        if line_advancement_from_goal < 10.0
            && projected_line_gap > DEFENSIVE_LOW_LINE_BREAK_TRIGGER_GAP_YARDS
        {
            return None;
        }
        Some((holder_position, projected_line_gap))
    }

    fn defensive_line_break_retreat_target_y(
        &self,
        team: Team,
        holder: Vec2,
        line_gap: f64,
    ) -> f64 {
        let urgency = defensive_line_break_threat_fit(line_gap);
        let retreat_gap = DEFENSIVE_LINE_BREAK_BASE_RETREAT_GAP_YARDS
            + urgency * DEFENSIVE_LINE_BREAK_URGENT_RETREAT_GAP_YARDS;
        let target_y = holder.y - team.attack_dir() * retreat_gap;
        let own_goal_y = self.own_goal_y_for(team);
        if !self.ball_near_own_goal_line(team) {
            if own_goal_y <= self.field_length * 0.5 {
                target_y.max(own_goal_y + DEFENSIVE_GOAL_LINE_BUFFER_YARDS)
            } else {
                target_y.min(own_goal_y - DEFENSIVE_GOAL_LINE_BUFFER_YARDS)
            }
        } else {
            target_y
        }
    }

    fn clamp_defensive_line_break_retreat(
        &self,
        team: Team,
        holder: Vec2,
        line_gap: f64,
        mut target: Vec2,
    ) -> Vec2 {
        let retreat_y = self.defensive_line_break_retreat_target_y(team, holder, line_gap);
        let threat_fit = defensive_line_break_threat_fit(line_gap);
        let dir = team.attack_dir();
        // Preserve a narrow close-down window; otherwise the back line either drops
        // for an immediate break threat or retreats to stay connected behind the ball.
        let should_hard_retreat = line_gap <= DEFENSIVE_LINE_BREAK_HARD_RETREAT_GAP_YARDS
            || line_gap >= DEFENSIVE_LOW_LINE_BREAK_TRIGGER_GAP_YARDS;
        if should_hard_retreat {
            if dir > 0.0 {
                target.y = target.y.min(retreat_y + 1.0);
            } else {
                target.y = target.y.max(retreat_y - 1.0);
            }
        }
        let max_behind_ball = DEFENSIVE_MAX_BEHIND_BALL_YARDS
            + DEFENSIVE_LINE_BREAK_EXTRA_BEHIND_BALL_YARDS * threat_fit;
        self.clamp_defensive_goal_line_and_ball_gap_with_max(team, target, max_behind_ball)
    }

    fn likely_next_opponent_pass_target_for_defense(&self, defending_team: Team) -> Option<Vec2> {
        let attacking_team = defending_team.other();
        if let Some(pass) = self
            .pending_pass
            .as_ref()
            .filter(|pass| pass.team == attacking_team)
        {
            let receiver_position = pass
                .nearest_receiver
                .and_then(|id| self.player_position(id))
                .unwrap_or(pass.intended_target);
            return Some(
                (pass.intended_target * 0.64 + receiver_position * 0.36)
                    .clamp_to_pitch(self.field_width, self.field_length),
            );
        }

        if self.ball.holder.is_none()
            && self.possession_team() == Some(attacking_team)
            && self.ball.velocity.len() > 4.0
        {
            if let Some(projected) = self.projected_loose_ball_target() {
                return Some(projected);
            }
        }

        let holder_id = self.ball.holder?;
        let holder = self.players.iter().find(|player| player.id == holder_id)?;
        if holder.team != attacking_team {
            return None;
        }
        self.best_visible_pass_target(holder_id)
            .or_else(|| self.best_aerial_pass_target(holder_id))
            .and_then(|target_id| self.player_position(target_id))
    }

    fn defensive_midfielder_press_focus(&self, defending_team: Team) -> Vec2 {
        self.likely_next_opponent_pass_target_for_defense(defending_team)
            .map(|next_pass| self.ball.position * 0.58 + next_pass * 0.42)
            .unwrap_or(self.ball.position)
            .clamp_to_pitch(self.field_width, self.field_length)
    }

    fn clamp_defensive_goal_line_and_ball_gap(&self, team: Team, target: Vec2) -> Vec2 {
        self.clamp_defensive_goal_line_and_ball_gap_with_max(
            team,
            target,
            DEFENSIVE_MAX_BEHIND_BALL_YARDS,
        )
    }

    fn clamp_defensive_goal_line_and_ball_gap_with_max(
        &self,
        team: Team,
        mut target: Vec2,
        max_behind_ball: f64,
    ) -> Vec2 {
        let dir = team.attack_dir();
        let own_goal_y = self.own_goal_y_for(team);
        if !self.ball_near_own_goal_line(team) {
            if own_goal_y <= self.field_length * 0.5 {
                target.y = target.y.max(own_goal_y + DEFENSIVE_GOAL_LINE_BUFFER_YARDS);
            } else {
                target.y = target.y.min(own_goal_y - DEFENSIVE_GOAL_LINE_BUFFER_YARDS);
            }

            let deepest_connected_y = self.ball.position.y - dir * max_behind_ball.max(0.0);
            if dir > 0.0 {
                target.y = target.y.max(deepest_connected_y);
            } else {
                target.y = target.y.min(deepest_connected_y);
            }
        }
        target.clamp_to_pitch(self.field_width, self.field_length)
    }

    fn clamp_forward_onside_support(&self, player: &PlayerSnapshot, mut target: Vec2) -> Vec2 {
        if self.possession_team() != Some(player.team)
            || player.role != PlayerRole::Forward
            || self.in_behind_run_target_for(player.id).is_some()
        {
            return target;
        }
        let Some(line_y) = self.second_last_defender_line_for(player.team) else {
            return target;
        };
        let half_line = self.field_length * 0.5;
        match player.team {
            Team::Home
                if target.y > half_line && target.y > line_y - STRIKER_ONSIDE_BUFFER_YARDS =>
            {
                target.y = line_y - STRIKER_ONSIDE_BUFFER_YARDS;
            }
            Team::Away
                if target.y < half_line && target.y < line_y + STRIKER_ONSIDE_BUFFER_YARDS =>
            {
                target.y = line_y + STRIKER_ONSIDE_BUFFER_YARDS;
            }
            _ => {}
        }
        target.clamp_to_pitch(self.field_width, self.field_length)
    }

    pub fn tactical_directive(&self, team: Team) -> &TeamTacticalDirective {
        match team {
            Team::Home => &self.home_directive,
            Team::Away => &self.away_directive,
        }
    }

    pub fn goalkeeper_for(&self, team: Team) -> Option<usize> {
        self.players
            .iter()
            .find(|player| player.team == team && player.role == PlayerRole::Goalkeeper)
            .map(|player| player.id)
    }

    pub fn mdp_state(&self) -> SoccerMdpState {
        SoccerMdpState {
            tick: self.tick,
            ball_zone_x: zone(self.ball.position.x, self.field_width, 6),
            ball_zone_y: zone(self.ball.position.y, self.field_length, 8),
            player_grid: PitchGridAddress::default(),
            receive_facing: FacingBucket::Unknown,
            action_facing: FacingBucket::Unknown,
            possession_team: self.possession_team(),
            score_diff_for_home: self.score_home as i32 - self.score_away as i32,
            phase: self.phase,
        }
    }

    pub fn mdp_state_for_player(&self, player_id: usize) -> SoccerMdpState {
        let mut state = self.mdp_state();
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return state;
        };
        let position = self.player_snapshot_position(me);
        state.player_grid = pitch_grid_address(position, self.field_width, self.field_length);
        state.receive_facing = me.receive_facing;
        state.action_facing = self.player_state_action_facing(me);
        state
    }

    pub fn observation_for(&self, player_id: usize) -> SoccerPomdpObservation {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return SoccerPomdpObservation {
                player_id,
                player_grid: PitchGridAddress::default(),
                receive_facing: FacingBucket::Unknown,
                action_facing: FacingBucket::Unknown,
                has_ball: false,
                visible_ball: false,
                visible_teammates: 0,
                visible_opponents: 0,
                visible_pass_options: 0,
                visible_aerial_pass_options: 0,
                teammates_ahead: 0,
                visible_forward_pass_options: 0,
                best_forward_pass_receiver_openness: 0.0,
                nearest_forward_teammate_distance_yards: 0.0,
                floor_pass_lane_score: 0.0,
                best_pass_receiver_openness: 0.0,
                best_aerial_pass_receiver_openness: 0.0,
                best_pass_stride_fit: 0.0,
                best_aerial_pass_stride_fit: 0.0,
                expected_pass_completion: 0.0,
                expected_aerial_pass_completion: 0.0,
                aerial_pass_bypass_score: 0.0,
                aerial_pass_interception_risk: 0.0,
                aerial_forward_runner_pass_multiplier: 1.0,
                ball_position_confidence: 0.0,
                teammate_position_confidence: 0.0,
                opponent_position_confidence: 0.0,
                player_position_confidences: Vec::new(),
                look_behind_scan_active: false,
                look_behind_scan_seconds: 0.0,
                look_behind_confidence_bonus: 0.0,
                look_behind_drift_risk: 0.0,
                scheduled_index: None,
                ball_scheduled_index: None,
                ball_schedule_order: 0,
                controller_slot: None,
                human_controlled: false,
                human_input_present: false,
                human_input_seq: None,
                human_input_queue_age_ms: None,
                movement_gait: MovementGait::Stand,
                actor_speed_yps: 0.0,
                actor_acceleration_yps2: 0.0,
                actor_jerk_yps3: 0.0,
                ball_speed_yps: 0.0,
                ball_acceleration_yps2: 0.0,
                ball_jerk_yps3: 0.0,
                ball_forward_velocity_yps: 0.0,
                ball_lateral_speed_yps: 0.0,
                ball_altitude_yards: 0.0,
                ball_airborne: false,
                loose_ball: false,
                loose_ball_fifty_fifty: false,
                loose_ball_team_time_advantage_seconds: 0.0,
                loose_ball_player_time_to_ball_seconds: 0.0,
                ball_distance: 0.0,
                nearest_opponent_distance: 0.0,
                nearest_teammate_distance: 0.0,
                team_spacing_score: 0.0,
                preferred_team_spacing_yards: 0.0,
                vertical_lane_affinity_score: 1.0,
                vertical_lane_deviation_yards: 0.0,
                teammate_occupied_space_pressure: 0.0,
                effective_teammate_spacing_pressure: 0.0,
                role_line_deviation_yards: 0.0,
                role_line_cohesion_score: 1.0,
                positional_shape_exception_relief: 0.0,
                team_brain_mode: TeamBrainMode::Transition,
                team_brain_press_intensity: 0.0,
                team_brain_risk_tolerance: 0.0,
                team_brain_flank_attack_policy: FlankAttackPolicy::None,
                team_brain_flank_overlap_run_probability: 0.0,
                flank_cross_arrival_available: false,
                flank_cross_arrival_distance_yards: 0.0,
                flank_cross_arrival_fit: 0.0,
                defensive_cross_arrival_threat_available: false,
                defensive_cross_arrival_threat_distance_yards: 0.0,
                defensive_cross_arrival_threat_fit: 0.0,
                goalkeeper_ball_goal_line_alignment_score: 0.0,
                defensive_line_break_threat: 0.0,
                team_brain_defensive_cover_target: 0,
                team_brain_defensive_cover_actual: 0,
                team_centroid_to_ball_yards: 0.0,
                team_spread_yards: 0.0,
                team_players_near_ball: 0,
                team_forward_velocity_yps: 0.0,
                formation_lp_guidance_present: false,
                formation_lp_recommended_move_yards: 0.0,
                formation_lp_pair_error_yards: 0.0,
                formation_lp_pressure_weight: 0.0,
                formation_lp_speed_match_weight: 0.0,
                attacking_overload_attackers: 0,
                attacking_overload_defenders: 0,
                attacking_numbers_advantage: 0,
                attacking_overload_score: 0.0,
                shot_lane_open: false,
                shot_block_probability: 1.0,
                shot_blocker_distance_yards: 0.0,
                shot_on_frame_probability: 0.0,
                shot_beat_goalkeeper_probability: 0.0,
                shot_curl_probability: 0.0,
                pass_curl_probability: 0.0,
                immediate_dispossession_risk: 0.0,
                yards_to_goal: 0.0,
                yards_to_own_goal: 0.0,
                opponent_goal_angle_degrees: 0.0,
                opposing_goalkeeper_distance: 0.0,
                opposing_goalkeeper_angle_degrees: 0.0,
                forward_dribble_space_yards: 0.0,
                real_pressure: 0.0,
                perceived_pressure: 0.0,
                pressure_urgency: 0.0,
                offensive_urgency: 0.0,
                defensive_urgency: 0.0,
                decision_urgency: 0.0,
                goal_attack_window_score: 0.0,
                real_time_on_ball_seconds: 0.0,
                perceived_time_on_ball_seconds: 0.0,
                actual_time_on_ball_seconds: 0.0,
                excessive_hold_pressure: 0.0,
                fatigue: 0.0,
                nearest_defender_fatigue: 0.0,
                perceived_nearest_defender_fatigue: 0.5,
                nearest_defender_fatigue_confidence: 0.0,
                perceived_fatigue_advantage: 0.0,
                first_touch_available: false,
                incoming_ball_kind: IncomingBallKind::None,
                incoming_ball_speed_yps: 0.0,
                incoming_ball_distance_yards: 0.0,
                receiving_pending_pass: false,
                pending_pass_off_target_yards: 0.0,
                pending_pass_receiver_urgency: 0.0,
                first_time_shot_score: 0.0,
                first_time_pass_score: 0.0,
                control_touch_score: 0.0,
                skill_top_speed: 0.0,
                skill_acceleration: 0.0,
                skill_stamina: 0.0,
                skill_strength: 0.0,
                skill_height: 0.0,
                skill_weight_pounds: 0.0,
                skill_dribbling: 0.0,
                skill_aggression: 0.0,
                skill_defending: 0.0,
                skill_shooting: 0.0,
                skill_right_foot_shot_power: 0.0,
                skill_left_foot_shot_power: 0.0,
                skill_passing_completion_rate: 0.0,
                skill_passing: 0.0,
                skill_first_touch: 0.0,
                skill_flair_passing: 0.0,
                skill_vision: 0.0,
                skill_crossing_left: 0.0,
                skill_crossing_right: 0.0,
                skill_goalkeeping: 0.0,
                skill_defensive_tracking: 0.0,
                open_space_score: 0.0,
            };
        };
        let me_position = self.player_snapshot_position(me);
        let observation_started = Instant::now();
        let phase_started = Instant::now();
        let opponents = self
            .players
            .iter()
            .filter(|p| p.team != me.team)
            .collect::<Vec<_>>();
        let teammates = self
            .players
            .iter()
            .filter(|p| p.team == me.team && p.id != me.id)
            .collect::<Vec<_>>();
        let vision_range = player_vision_range(me);
        let mut visible_opponents = 0usize;
        let mut nearest_opponent_distance = f64::INFINITY;
        for p in &opponents {
            if !self.player_can_see_player(me.id, p.id) {
                continue;
            }
            visible_opponents += 1;
            let position = self.player_snapshot_position(p);
            nearest_opponent_distance =
                nearest_opponent_distance.min(position.distance(me_position));
        }
        nearest_opponent_distance = nearest_opponent_distance.min(vision_range + 12.0);

        let mut visible_teammates = 0usize;
        let mut nearest_teammate_distance = f64::INFINITY;
        for p in &teammates {
            if !self.player_can_see_player(me.id, p.id) {
                continue;
            }
            visible_teammates += 1;
            let position = self.player_snapshot_position(p);
            nearest_teammate_distance =
                nearest_teammate_distance.min(position.distance(me_position));
        }
        nearest_teammate_distance = nearest_teammate_distance.min(vision_range + 12.0);
        let (team_spacing_score, preferred_team_spacing_yards) = self
            .team_spacing_mode_for(me.team)
            .map(|mode| {
                (
                    spacing_score_from_distance(nearest_teammate_distance, mode),
                    mode.ideal(),
                )
            })
            .unwrap_or((0.0, 0.0));
        let lane_relief = self.positional_shape_exception_relief_for_player_target(me, me_position);
        let vertical_lane_fit =
            self.vertical_lane_fit_for_player_target(me, me_position, lane_relief);
        let teammate_occupied_space_pressure =
            self.teammate_occupied_space_pressure_at(me.team, me_position, Some(me.id));
        let effective_teammate_spacing_pressure = self.effective_teammate_spacing_pressure_at(
            me.team,
            me_position,
            Some(me.id),
            lane_relief,
        );
        let role_line_deviation_yards = self.role_line_deviation_yards_for_target(me, me_position);
        let role_line_cohesion_score =
            self.role_line_cohesion_score_for_player_target(me, me_position);
        let team_directive = self.tactical_directive(me.team);
        let team_brain_mode = team_brain_mode_for(me.team, self.phase, self.possession_team());
        let team_shape = team_shape_observation_from_snapshot(self, me.team, self.ball.position);
        let goal = Vec2::new(self.field_width * 0.5, me.team.goal_y(self.field_length));
        let own_goal = Vec2::new(
            self.field_width * 0.5,
            me.team.other().goal_y(self.field_length),
        );
        let has_ball = self.ball.holder == Some(player_id);
        let visible_ball = has_ball || self.player_can_see_point(me.id, self.ball.position);
        let action_facing = self.player_state_action_facing(me);
        let look_behind_scan = look_behind_scan_context_for_observer(
            self.tick,
            self.dt_seconds,
            me,
            me_position,
            self.ball.position,
            self.ball.velocity.len(),
        );
        let loose_ball_race = loose_ball_race_context_for_snapshot(self, player_id);
        let ball_position_confidence = if has_ball {
            1.0
        } else {
            self.player_position_confidence_for_point(me.id, self.ball.position)
                .unwrap_or(0.0)
        };
        let mut player_position_confidences = self
            .players
            .iter()
            .filter(|player| player.id != me.id)
            .filter_map(|player| self.player_position_confidence_entry(me.id, player))
            .collect::<Vec<_>>();
        if look_behind_scan.active {
            for entry in &mut player_position_confidences {
                if !entry.in_front {
                    entry.confidence =
                        (entry.confidence + look_behind_scan.confidence_bonus).clamp(0.0, 1.0);
                }
            }
        }
        let teammate_position_confidence =
            average_player_position_confidence_entries(&player_position_confidences, me.team);
        let opponent_position_confidence = average_player_position_confidence_entries(
            &player_position_confidences,
            me.team.other(),
        );
        let scheduled_index = self
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Player && entry.id == player_id);
        let ball_scheduled_index = self
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID);
        let ball_schedule_order =
            schedule_order_relative_to_ball(scheduled_index, ball_scheduled_index);
        let visibility_elapsed = phase_started.elapsed();
        let phase_started = Instant::now();
        let visible_pass_targets = if has_ball {
            self.ranked_visible_pass_targets(player_id, 3)
        } else {
            Vec::new()
        };
        let visible_aerial_pass_targets = if has_ball {
            self.ranked_visible_aerial_pass_targets(player_id, 3)
        } else {
            Vec::new()
        };
        let forward_support_context =
            self.forward_support_context_for(player_id, &visible_pass_targets);
        let floor_pass_lane_score = if has_ball {
            floor_pass_lane_score_for_snapshot(self, me, me_position, &visible_pass_targets)
        } else {
            0.0
        };
        let best_floor_pass_quality = if has_ball {
            best_pass_target_quality_for_snapshot(
                self,
                me,
                me_position,
                &visible_pass_targets,
                PassFlight::Floor,
            )
        } else {
            PassTargetQuality::default()
        };
        let best_aerial_pass_quality = if has_ball {
            best_pass_target_quality_for_snapshot(
                self,
                me,
                me_position,
                &visible_aerial_pass_targets,
                PassFlight::Aerial,
            )
        } else {
            PassTargetQuality::default()
        };
        let aerial_pass_bypass_score = if has_ball {
            aerial_pass_bypass_score_for_snapshot(
                self,
                me,
                me_position,
                &visible_aerial_pass_targets,
            )
        } else {
            0.0
        };
        let aerial_pass_interception_risk = if has_ball {
            aerial_pass_interception_risk_for_snapshot(
                self,
                me,
                me_position,
                &visible_aerial_pass_targets,
            )
        } else {
            0.0
        };
        let flank_cross_arrival_target =
            self.flank_cross_arrival_target_for(player_id, me.home_position);
        let flank_cross_arrival_distance_yards = flank_cross_arrival_target
            .map(|target| me_position.distance(target))
            .unwrap_or(0.0);
        let flank_cross_arrival_fit = flank_cross_arrival_target
            .map(|target| {
                let distance_fit =
                    (1.0 - flank_cross_arrival_distance_yards / 16.0).clamp(0.0, 1.0);
                let lane_fit = if self.clear_line(self.ball.position, target, me.team.other(), 1.8)
                {
                    1.0
                } else if team_directive.flank_attack_policy.prefers_high_cross() {
                    0.45
                } else {
                    0.18
                };
                let space_fit = (self.space_score_at(target, me.team) / 18.0).clamp(0.0, 1.0);
                let urgency_fit = team_directive.flank_overlap_run_probability.clamp(0.0, 1.0);
                (distance_fit * 0.50 + lane_fit * 0.20 + space_fit * 0.20 + urgency_fit * 0.10)
                    .clamp(0.0, 1.0)
            })
            .unwrap_or(0.0);
        let defensive_cross_arrival_target =
            if matches!(me.role, PlayerRole::Defender | PlayerRole::Midfielder) {
                let defensive_zone = self.defensive_shape_for(player_id, me.home_position);
                soccer_defensive_cross_arrival_mark_target(self, me.team, me.role, defensive_zone)
                    .map(|(target, _score)| target)
            } else {
                None
            };
        let defensive_cross_arrival_threat_distance_yards = defensive_cross_arrival_target
            .map(|target| me_position.distance(target))
            .unwrap_or(0.0);
        let defensive_cross_arrival_threat_fit = defensive_cross_arrival_target
            .map(|target| {
                let distance_fit =
                    (1.0 - defensive_cross_arrival_threat_distance_yards / 14.0).clamp(0.0, 1.0);
                let own_goal_y = me.team.other().goal_y(self.field_length);
                let goal_side_fit = if goal_side_between_y(me_position.y, target.y, own_goal_y) {
                    1.0
                } else {
                    0.22
                };
                let tracking_fit = ability01(me.skills.defensive_tracking) * 0.18
                    + ability01(me.skills.defending) * 0.12;
                let opponent_flank_urgency = self
                    .tactical_directive(me.team.other())
                    .flank_overlap_run_probability
                    .clamp(0.0, 1.0);
                (distance_fit * 0.50
                    + goal_side_fit * 0.20
                    + tracking_fit
                    + opponent_flank_urgency * 0.12)
                    .clamp(0.0, 1.0)
            })
            .unwrap_or(0.0);
        let goalkeeper_ball_goal_line_alignment_score = if me.role == PlayerRole::Goalkeeper {
            goalkeeper_ball_goal_line_alignment_score(me.team, me_position, self)
        } else {
            0.0
        };
        let defensive_line_break_threat = if me.role == PlayerRole::Defender {
            self.opponent_breakthrough_ball_carrier(me.team)
                .map(|(_, line_gap)| defensive_line_break_threat_fit(line_gap))
                .unwrap_or(0.0)
        } else {
            0.0
        };
        let pass_eval_elapsed = phase_started.elapsed();
        let phase_started = Instant::now();
        let player_grid = pitch_grid_address(me_position, self.field_width, self.field_length);
        let real_pressure = pressure_from_nearest_distance(nearest_opponent_distance);
        let perceived_pressure =
            perceived_pressure_for_player(me, real_pressure, visible_opponents);
        let real_time_on_ball_seconds = time_on_ball_seconds(real_pressure);
        let perceived_time_on_ball_seconds = time_on_ball_seconds(perceived_pressure);
        let actual_time_on_ball_seconds = if has_ball {
            self.ball_holder_possession_seconds.max(0.0)
        } else {
            0.0
        };
        let expected_shot_power = shot_power_for_skill(ability01(me.skills.shooting));
        let expected_shot_speed_yps = shot_speed_yps_from_power(expected_shot_power, &me.skills);
        let shot_block_assessment = if has_ball {
            shot_block_assessment_for_snapshot(
                self,
                me_position,
                me.team,
                expected_shot_speed_yps,
                false,
            )
        } else {
            None
        };
        let shot_block_probability = shot_block_assessment
            .as_ref()
            .map(|assessment| assessment.probability)
            .unwrap_or(0.0);
        let shot_blocker_distance_yards = shot_block_assessment
            .as_ref()
            .map(|assessment| assessment.distance_to_ball)
            .unwrap_or(self.field_length);
        let first_time_shot_block_probability = if has_ball {
            shot_block_assessment_for_snapshot(
                self,
                me_position,
                me.team,
                expected_shot_speed_yps,
                true,
            )
            .map(|assessment| assessment.probability)
            .unwrap_or(0.0)
        } else {
            0.0
        };
        let shot_curl_probability = if has_ball {
            shot_curl_probability_for_player(
                &me.skills,
                perceived_pressure,
                (goal.y - me_position.y).abs(),
                self.goal_angle_degrees(me_position, me.team),
            )
        } else {
            0.0
        };
        let pass_curl_probability = if has_ball {
            pass_curl_probability_for_snapshot(
                self,
                me,
                me_position,
                &visible_pass_targets,
                &visible_aerial_pass_targets,
                perceived_pressure,
            )
        } else {
            0.0
        };
        let nearest_defender = opponents
            .iter()
            .filter_map(|p| {
                let position = self.player_snapshot_position(p);
                Some((*p, position, position.distance(me_position)))
            })
            .min_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal));
        let (nearest_defender_fatigue, nearest_defender_fatigue_confidence) =
            if let Some((defender, defender_position, _)) = nearest_defender {
                let position_confidence = self
                    .player_position_confidence_for_point(me.id, defender_position)
                    .unwrap_or(0.0);
                (
                    defender.fatigue.clamp(0.0, 1.0),
                    (position_confidence * 0.85).clamp(0.0, 1.0),
                )
            } else {
                (0.5, 0.0)
            };
        let perceived_nearest_defender_fatigue = nearest_defender_fatigue
            * nearest_defender_fatigue_confidence
            + 0.5 * (1.0 - nearest_defender_fatigue_confidence);
        let perceived_fatigue_advantage =
            perceived_nearest_defender_fatigue - me.fatigue.clamp(0.0, 1.0);
        let opposing_keeper_position = if has_ball {
            self.goalkeeper_for(me.team.other())
                .and_then(|keeper_id| self.player_position(keeper_id))
        } else {
            None
        };
        let incoming = me.incoming_ball.as_ref().filter(|context| {
            self.tick.saturating_sub(context.received_tick) <= FIRST_TOUCH_WINDOW_TICKS
        });
        let first_touch_available = has_ball && incoming.is_some();
        let incoming_kind = incoming
            .map(|context| context.kind)
            .unwrap_or(IncomingBallKind::None);
        let incoming_speed_yps = incoming.map(|context| context.speed_yps).unwrap_or(0.0);
        let incoming_distance_yards = incoming
            .map(|context| context.distance_yards)
            .unwrap_or(0.0);
        let receiving_pending_pass = self
            .pending_pass
            .as_ref()
            .is_some_and(|pass| pass.team == me.team && pass.nearest_receiver == Some(me.id));
        let pending_pass_off_target_yards = if receiving_pending_pass {
            self.pending_pass
                .as_ref()
                .map(|pass| pass.off_target_yards)
                .unwrap_or(0.0)
        } else {
            0.0
        };
        let pending_pass_receiver_urgency = if receiving_pending_pass {
            self.pending_pass
                .as_ref()
                .map(|pass| pass.receiver_urgency)
                .unwrap_or(0.0)
        } else {
            0.0
        };
        let first_time_shot_score = if first_touch_available {
            first_time_shot_score_for_player(
                me,
                incoming_kind,
                first_time_shot_block_probability,
                (goal.y - me_position.y).abs(),
                self.goal_angle_degrees(me_position, me.team),
                perceived_pressure,
            )
        } else {
            0.0
        };
        let first_time_pass_score = if first_touch_available {
            first_time_pass_score_for_player(me, incoming_kind, perceived_pressure)
        } else {
            0.0
        };
        let control_touch_score = if first_touch_available {
            control_touch_score_for_player(
                me,
                incoming_kind,
                incoming_speed_yps,
                perceived_pressure,
            )
        } else {
            0.0
        };
        let shot_lane_open = has_ball && shot_block_probability <= 0.34;
        let yards_to_goal = (goal.y - me_position.y).abs();
        let opponent_goal_angle_degrees = self.goal_angle_degrees(me_position, me.team);
        let forward_dribble_space_yards = if has_ball {
            self.forward_dribble_space_yards(player_id)
        } else {
            0.0
        };
        let aerial_forward_runner_pass_multiplier = if has_ball {
            self.aerial_forward_runner_pass_multiplier(player_id)
        } else {
            1.0
        };
        let shot_on_frame_probability = if has_ball {
            shot_on_frame_probability(
                self.goal_width,
                ability01(me.skills.shooting),
                perceived_pressure,
                yards_to_goal,
                opponent_goal_angle_degrees,
                shot_block_probability,
            )
        } else {
            0.0
        };
        let shot_beat_goalkeeper_probability = if has_ball {
            (shot_beat_goalkeeper_probability_for_snapshot(self, me, me_position)
                * (1.0 - shot_block_probability * 0.70).clamp(0.20, 1.0)
                + shot_curl_probability * 0.045)
                .clamp(0.0, 1.0)
        } else {
            0.0
        };
        let shot_eval_elapsed = phase_started.elapsed();
        let phase_started = Instant::now();
        let immediate_dispossession_risk = if has_ball {
            immediate_dispossession_risk_for_player(
                me,
                nearest_opponent_distance,
                perceived_pressure,
                perceived_time_on_ball_seconds,
            )
        } else {
            0.0
        };
        let facing_goal_alignment = self
            .player_facing_direction(me)
            .map(|facing| facing.normalized().dot((goal - me_position).normalized()))
            .unwrap_or_else(|| {
                Vec2::new(0.0, me.team.attack_dir()).dot((goal - me_position).normalized())
            });
        let facing_goal_score = ((facing_goal_alignment + 0.20) / 1.20).clamp(0.0, 1.0);
        let goal_attack_window_score = goal_attack_window_score_for_role(
            me.role,
            has_ball,
            yards_to_goal,
            shot_lane_open,
            shot_block_probability,
            shot_on_frame_probability,
            shot_beat_goalkeeper_probability,
            opponent_goal_angle_degrees,
            forward_dribble_space_yards,
            facing_goal_score,
        );
        let goal_distance_urgency = if yards_to_goal <= GOAL_URGENCY_MAX_YARDS {
            let raw = ((GOAL_URGENCY_MAX_YARDS + 2.0 - yards_to_goal)
                / (GOAL_URGENCY_MAX_YARDS - GOAL_URGENCY_KEEPER_CROWD_YARDS).max(1.0))
            .clamp(0.18, 1.0);
            if yards_to_goal < GOAL_URGENCY_KEEPER_CROWD_YARDS {
                raw * (yards_to_goal / GOAL_URGENCY_KEEPER_CROWD_YARDS).clamp(0.45, 1.0)
            } else {
                raw
            }
        } else {
            0.0
        };
        let role_goal_urgency = match me.role {
            PlayerRole::Forward => 1.24,
            PlayerRole::Midfielder => 0.86,
            PlayerRole::Defender => 0.42,
            PlayerRole::Goalkeeper => 0.10,
        };
        let shot_geometry_urgency = (goal_distance_urgency
            * (0.42
                + if shot_lane_open { 0.24 } else { 0.0 }
                + shot_on_frame_probability.clamp(0.0, 1.0) * 0.22
                + shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 0.16)
            * (0.58 + facing_goal_score * 0.54)
            * role_goal_urgency)
            .clamp(0.0, 1.0);
        let offensive_urgency = if has_ball {
            (shot_geometry_urgency + team_directive.attacking_overload_score.clamp(0.0, 1.0) * 0.14)
                .clamp(0.0, 1.0)
        } else {
            0.0
        };
        let own_half = pass_origin_in_own_half(me.team, me_position, self.field_length);
        let own_goal_pressure = if own_half {
            (1.0 - (own_goal.y - me_position.y).abs() / (self.field_length * 0.46).max(1.0))
                .clamp(0.0, 1.0)
        } else {
            0.0
        };
        let defensive_role_urgency = match me.role {
            PlayerRole::Goalkeeper => 1.10,
            PlayerRole::Defender => 1.0,
            PlayerRole::Midfielder => 0.72,
            PlayerRole::Forward => 0.36,
        };
        let defensive_urgency = if has_ball && own_half {
            ((0.28
                + own_goal_pressure * 0.48
                + perceived_pressure * 0.24
                + immediate_dispossession_risk * 0.30)
                * defensive_role_urgency)
                .clamp(0.0, 1.0)
        } else {
            0.0
        };
        let pressure_urgency = if has_ball {
            (perceived_pressure * 0.58
                + immediate_dispossession_risk * 0.52
                + (1.0 - perceived_time_on_ball_seconds / 2.8).clamp(0.0, 1.0) * 0.20)
                .clamp(0.0, 1.0)
        } else {
            pending_pass_receiver_urgency.clamp(0.0, 1.0) * 0.75
        };
        let decision_urgency = pressure_urgency
            .max(offensive_urgency)
            .max(defensive_urgency)
            .clamp(0.0, 1.0);
        let excessive_hold_pressure = if has_ball {
            excessive_hold_pressure_from_parts(
                actual_time_on_ball_seconds,
                pressure_urgency,
                defensive_urgency,
                perceived_pressure,
                immediate_dispossession_risk,
                ability01(me.skills.dribbling),
            )
        } else {
            0.0
        };
        let formation_lp_guidance = self.formation_lp_guidance_for(player_id);
        let formation_lp_recommended_move_yards = formation_lp_guidance
            .map(|guidance| finite_metric(guidance.recommended_move_yards))
            .unwrap_or(0.0);
        let formation_lp_pair_error_yards = formation_lp_guidance
            .map(|guidance| finite_metric(guidance.pair_error_yards))
            .unwrap_or(0.0);
        let formation_lp_pressure_weight = formation_lp_guidance
            .map(|guidance| finite_metric(guidance.pressure_weight))
            .unwrap_or(0.0);
        let formation_lp_speed_match_weight = formation_lp_guidance
            .map(|guidance| finite_metric(guidance.speed_match_weight))
            .unwrap_or(0.0);
        let urgency_elapsed = phase_started.elapsed();
        let observation = SoccerPomdpObservation {
            player_id,
            player_grid,
            receive_facing: me.receive_facing,
            action_facing,
            has_ball,
            visible_ball,
            visible_teammates,
            visible_opponents,
            visible_pass_options: visible_pass_targets.len(),
            visible_aerial_pass_options: visible_aerial_pass_targets.len(),
            teammates_ahead: forward_support_context.teammates_ahead,
            visible_forward_pass_options: forward_support_context.visible_forward_pass_options,
            best_forward_pass_receiver_openness: forward_support_context
                .best_forward_pass_receiver_openness,
            nearest_forward_teammate_distance_yards: forward_support_context
                .nearest_forward_teammate_distance_yards,
            floor_pass_lane_score,
            best_pass_receiver_openness: best_floor_pass_quality.receiver_openness,
            best_aerial_pass_receiver_openness: best_aerial_pass_quality.receiver_openness,
            best_pass_stride_fit: best_floor_pass_quality.stride_fit,
            best_aerial_pass_stride_fit: best_aerial_pass_quality.stride_fit,
            expected_pass_completion: best_floor_pass_quality.expected_completion,
            expected_aerial_pass_completion: best_aerial_pass_quality.expected_completion,
            aerial_pass_bypass_score,
            aerial_pass_interception_risk,
            aerial_forward_runner_pass_multiplier,
            ball_position_confidence,
            teammate_position_confidence,
            opponent_position_confidence,
            player_position_confidences,
            look_behind_scan_active: look_behind_scan.active,
            look_behind_scan_seconds: look_behind_scan.duration_seconds,
            look_behind_confidence_bonus: look_behind_scan.confidence_bonus,
            look_behind_drift_risk: look_behind_scan.drift_risk,
            scheduled_index,
            ball_scheduled_index,
            ball_schedule_order,
            controller_slot: me.controller_slot,
            human_controlled: me.controller_slot.is_some(),
            human_input_present: false,
            human_input_seq: None,
            human_input_queue_age_ms: None,
            movement_gait: me.movement_gait,
            actor_speed_yps: me.velocity.len(),
            actor_acceleration_yps2: me.acceleration.len(),
            actor_jerk_yps3: me.jerk.len(),
            ball_speed_yps: self.ball.velocity.len(),
            ball_acceleration_yps2: self.ball.acceleration.len(),
            ball_jerk_yps3: self.ball.jerk.len(),
            ball_forward_velocity_yps: self.ball.velocity.y * me.team.attack_dir(),
            ball_lateral_speed_yps: self.ball.velocity.x.abs(),
            ball_altitude_yards: self.ball.altitude_yards.max(0.0),
            ball_airborne: self.ball.altitude_yards > BALL_ROLLING_ALTITUDE_YARDS,
            loose_ball: loose_ball_race.loose_ball,
            loose_ball_fifty_fifty: loose_ball_race.fifty_fifty,
            loose_ball_team_time_advantage_seconds: loose_ball_race.team_time_advantage_seconds,
            loose_ball_player_time_to_ball_seconds: loose_ball_race.player_time_to_ball_seconds,
            ball_distance: if visible_ball {
                me_position.distance(self.ball.position)
            } else {
                vision_range + 12.0
            },
            nearest_opponent_distance,
            nearest_teammate_distance,
            team_spacing_score,
            preferred_team_spacing_yards,
            vertical_lane_affinity_score: vertical_lane_fit.affinity_score,
            vertical_lane_deviation_yards: vertical_lane_fit.deviation_yards,
            teammate_occupied_space_pressure,
            effective_teammate_spacing_pressure,
            role_line_deviation_yards,
            role_line_cohesion_score,
            positional_shape_exception_relief: lane_relief,
            team_brain_mode,
            team_brain_press_intensity: team_directive.press_intensity,
            team_brain_risk_tolerance: team_directive.risk_tolerance,
            team_brain_flank_attack_policy: team_directive.flank_attack_policy,
            team_brain_flank_overlap_run_probability: team_directive.flank_overlap_run_probability,
            flank_cross_arrival_available: flank_cross_arrival_target.is_some(),
            flank_cross_arrival_distance_yards,
            flank_cross_arrival_fit,
            defensive_cross_arrival_threat_available: defensive_cross_arrival_target.is_some(),
            defensive_cross_arrival_threat_distance_yards,
            defensive_cross_arrival_threat_fit,
            goalkeeper_ball_goal_line_alignment_score,
            defensive_line_break_threat,
            team_brain_defensive_cover_target: team_directive.defensive_cover_target,
            team_brain_defensive_cover_actual: team_directive.defensive_cover_actual,
            team_centroid_to_ball_yards: team_shape.centroid_to_ball_yards,
            team_spread_yards: team_shape.spread_yards,
            team_players_near_ball: team_shape.players_near_ball,
            team_forward_velocity_yps: team_shape.forward_velocity_yps,
            formation_lp_guidance_present: formation_lp_guidance.is_some(),
            formation_lp_recommended_move_yards,
            formation_lp_pair_error_yards,
            formation_lp_pressure_weight,
            formation_lp_speed_match_weight,
            attacking_overload_attackers: team_directive.attacking_overload_attackers,
            attacking_overload_defenders: team_directive.attacking_overload_defenders,
            attacking_numbers_advantage: team_directive.attacking_numbers_advantage,
            attacking_overload_score: team_directive.attacking_overload_score,
            shot_lane_open,
            shot_block_probability,
            shot_blocker_distance_yards,
            shot_on_frame_probability,
            shot_beat_goalkeeper_probability,
            shot_curl_probability,
            pass_curl_probability,
            immediate_dispossession_risk,
            yards_to_goal,
            yards_to_own_goal: (own_goal.y - me_position.y).abs(),
            opponent_goal_angle_degrees,
            opposing_goalkeeper_distance: opposing_keeper_position
                .map(|position| me_position.distance(position))
                .unwrap_or(self.field_length),
            opposing_goalkeeper_angle_degrees: opposing_keeper_position
                .map(|position| {
                    angle_between_vectors_degrees(goal - me_position, position - me_position)
                })
                .unwrap_or(0.0),
            forward_dribble_space_yards,
            real_pressure,
            perceived_pressure,
            pressure_urgency,
            offensive_urgency,
            defensive_urgency,
            decision_urgency,
            goal_attack_window_score,
            real_time_on_ball_seconds,
            perceived_time_on_ball_seconds,
            actual_time_on_ball_seconds,
            excessive_hold_pressure,
            fatigue: me.fatigue.clamp(0.0, 1.0),
            nearest_defender_fatigue,
            perceived_nearest_defender_fatigue,
            nearest_defender_fatigue_confidence,
            perceived_fatigue_advantage,
            first_touch_available,
            incoming_ball_kind: incoming_kind,
            incoming_ball_speed_yps: incoming_speed_yps,
            incoming_ball_distance_yards: incoming_distance_yards,
            receiving_pending_pass,
            pending_pass_off_target_yards,
            pending_pass_receiver_urgency,
            first_time_shot_score,
            first_time_pass_score,
            control_touch_score,
            skill_top_speed: me.skills.top_speed,
            skill_acceleration: me.skills.acceleration,
            skill_stamina: me.skills.stamina,
            skill_strength: me.skills.strength,
            skill_height: me.skills.height,
            skill_weight_pounds: me.skills.weight_pounds,
            skill_dribbling: me.skills.dribbling,
            skill_aggression: me.skills.aggression,
            skill_defending: me.skills.defending,
            skill_shooting: me.skills.shooting,
            skill_right_foot_shot_power: me.skills.right_foot_shot_power,
            skill_left_foot_shot_power: me.skills.left_foot_shot_power,
            skill_passing_completion_rate: me.skills.passing_completion_rate,
            skill_passing: me.skills.passing,
            skill_first_touch: me.skills.first_touch,
            skill_flair_passing: me.skills.flair_passing,
            skill_vision: me.skills.vision,
            skill_crossing_left: me.skills.crossing_left,
            skill_crossing_right: me.skills.crossing_right,
            skill_goalkeeping: me.skills.goalkeeping,
            skill_defensive_tracking: me.skills.defensive_tracking,
            open_space_score: self.space_score_at(me_position, me.team),
        };
        let total_elapsed = observation_started.elapsed();
        if total_elapsed > Duration::from_millis(25) {
            eprintln!(
                concat!(
                    "# soccer-observation telemetry tick={} player={} totalMs={:.2} ",
                    "visibilityMs={:.2} passEvalMs={:.2} shotEvalMs={:.2} ",
                    "urgencyMs={:.2}"
                ),
                self.tick,
                player_id,
                soccer_live_duration_ms(total_elapsed),
                soccer_live_duration_ms(visibility_elapsed),
                soccer_live_duration_ms(pass_eval_elapsed),
                soccer_live_duration_ms(shot_eval_elapsed),
                soccer_live_duration_ms(urgency_elapsed),
            );
        }
        observation
    }

    pub fn best_pass_target(&self, player_id: usize) -> Option<usize> {
        self.ranked_pass_targets(player_id, 1).into_iter().next()
    }

    pub fn best_visible_pass_target(&self, player_id: usize) -> Option<usize> {
        self.ranked_visible_pass_targets(player_id, 1)
            .into_iter()
            .next()
    }

    pub fn best_aerial_pass_target(&self, player_id: usize) -> Option<usize> {
        self.ranked_visible_aerial_pass_targets(player_id, 1)
            .into_iter()
            .next()
            .or_else(|| self.best_pass_target(player_id))
    }

    pub fn pressure_clearance_target_for(&self, player_id: usize) -> Option<Vec2> {
        let me = self.players.iter().find(|player| player.id == player_id)?;
        let from = self.player_snapshot_position(me);
        let base =
            clearance_target_for_actor(me.team, from, self.field_width, self.field_length, me.role);
        let attack_dir = me.team.attack_dir();
        let nominal_speed = pass_speed_yps_from_power(0.92, PassFlight::Aerial, false, &me.skills);
        let outlet = self
            .ranked_visible_aerial_pass_targets(player_id, 5)
            .into_iter()
            .filter_map(|target_id| {
                let target = self.players.iter().find(|player| player.id == target_id)?;
                let target_position = self
                    .anticipated_pass_reception_point(
                        player_id,
                        target_id,
                        PassFlight::Aerial,
                        nominal_speed,
                    )
                    .or_else(|| self.player_position(target_id))
                    .unwrap_or_else(|| self.player_snapshot_position(target));
                let forward = (target_position.y - from.y) * attack_dir;
                if forward < 10.0
                    || self
                        .pending_offside_for_pass(player_id, target_id)
                        .is_some()
                {
                    return None;
                }
                let role_bonus = match target.role {
                    PlayerRole::Forward => 10.0,
                    PlayerRole::Midfielder => 4.0,
                    PlayerRole::Defender => 1.0,
                    PlayerRole::Goalkeeper => -8.0,
                };
                let runner_bonus = if target.role == PlayerRole::Forward
                    && self.player_is_recent_forward_runner(target)
                {
                    13.0
                } else {
                    0.0
                };
                let base_fit = (1.0 - target_position.distance(base) / 54.0).clamp(0.0, 1.0) * 12.0;
                Some((
                    target_position,
                    forward + role_bonus + runner_bonus + base_fit,
                ))
            })
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(target_position, _)| target_position);
        outlet
            .map(|target_position| {
                let runner_lead = Vec2::new(0.0, attack_dir * 8.0);
                (target_position + runner_lead).clamp_to_pitch(self.field_width, self.field_length)
                    * 0.72
                    + base * 0.28
            })
            .map(|target| target.clamp_to_pitch(self.field_width, self.field_length))
    }

    pub fn route_one_target_for(&self, player_id: usize) -> Option<Vec2> {
        let me = self.players.iter().find(|player| player.id == player_id)?;
        let from = self.player_snapshot_position(me);
        let base =
            route_one_target_for_actor(me.team, from, self.field_width, self.field_length, me.role);
        let attack_dir = me.team.attack_dir();
        let nominal_speed = pass_speed_yps_from_power(0.88, PassFlight::Aerial, false, &me.skills);
        let outlet = self
            .ranked_visible_aerial_pass_targets(player_id, 7)
            .into_iter()
            .filter_map(|target_id| {
                let target = self.players.iter().find(|player| player.id == target_id)?;
                if target.role == PlayerRole::Goalkeeper
                    || self
                        .pending_offside_for_pass(player_id, target_id)
                        .is_some()
                {
                    return None;
                }
                let target_position = self
                    .anticipated_pass_reception_point(
                        player_id,
                        target_id,
                        PassFlight::Aerial,
                        nominal_speed,
                    )
                    .or_else(|| self.player_position(target_id))
                    .unwrap_or_else(|| self.player_snapshot_position(target));
                let forward = (target_position.y - from.y) * attack_dir;
                if forward < 18.0 {
                    return None;
                }
                let role_bonus = match target.role {
                    PlayerRole::Forward => 14.0,
                    PlayerRole::Midfielder => 7.0,
                    PlayerRole::Defender => 1.5,
                    PlayerRole::Goalkeeper => -10.0,
                };
                let runner_bonus = if self.player_is_recent_forward_runner(target) {
                    9.0
                } else {
                    0.0
                };
                let base_fit = (1.0 - target_position.distance(base) / 62.0).clamp(0.0, 1.0) * 9.0;
                Some((
                    target_position,
                    forward * 0.58 + role_bonus + runner_bonus + base_fit,
                ))
            })
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(target_position, _)| target_position);
        outlet
            .map(|target_position| {
                let runner_lead = Vec2::new(0.0, attack_dir * 12.0);
                let mut target = (target_position + runner_lead)
                    .clamp_to_pitch(self.field_width, self.field_length)
                    * 0.68
                    + base * 0.32;
                target.y = match me.team {
                    Team::Home => target.y.max(self.field_length * 0.56),
                    Team::Away => target.y.min(self.field_length * 0.44),
                };
                target
            })
            .map(|target| target.clamp_to_pitch(self.field_width, self.field_length))
    }

    pub fn ranked_pass_targets(&self, player_id: usize, limit: usize) -> Vec<usize> {
        self.ranked_pass_targets_filtered(player_id, limit, false)
    }

    pub fn ranked_visible_pass_targets(&self, player_id: usize, limit: usize) -> Vec<usize> {
        self.ranked_pass_targets_filtered(player_id, limit, true)
    }

    pub fn ranked_visible_aerial_pass_targets(&self, player_id: usize, limit: usize) -> Vec<usize> {
        self.ranked_aerial_pass_targets_filtered(player_id, limit, true)
    }

    pub fn killer_pass_target_for(
        &self,
        player_id: usize,
        visible_targets: &[usize],
    ) -> Option<usize> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if self.ball.holder != Some(player_id) || me.role == PlayerRole::Goalkeeper {
            return None;
        }
        let me_position = self.player_snapshot_position(me);
        let goal_y = me.team.goal_y(self.field_length);
        let yards_to_goal = (goal_y - me_position.y).abs();
        if yards_to_goal > KILLER_PASS_MAX_YARDS_TO_GOAL {
            return None;
        }

        let attack_dir = me.team.attack_dir();
        let nominal_speed = pass_speed_yps_from_power(0.82, PassFlight::Floor, false, &me.skills);
        let candidates = if visible_targets.is_empty() {
            self.ranked_visible_pass_targets(player_id, 5)
        } else {
            visible_targets.to_vec()
        };
        candidates
            .into_iter()
            .filter_map(|target_id| {
                let target = self.players.iter().find(|p| p.id == target_id)?;
                if target.role == PlayerRole::Goalkeeper
                    || target.team != me.team
                    || self
                        .pending_offside_for_pass(player_id, target_id)
                        .is_some()
                {
                    return None;
                }
                let target_position = self.player_snapshot_position(target);
                let reception = self
                    .anticipated_pass_reception_point(
                        player_id,
                        target_id,
                        PassFlight::Floor,
                        nominal_speed,
                    )
                    .unwrap_or(target_position);
                let forward = (reception.y - me_position.y) * attack_dir;
                if forward < KILLER_PASS_MIN_FORWARD_YARDS {
                    return None;
                }
                let receiver_yards_to_goal = (goal_y - reception.y).abs();
                let goal_gain = yards_to_goal - receiver_yards_to_goal;
                if goal_gain < KILLER_PASS_MIN_RECEIVER_GOAL_GAIN_YARDS {
                    return None;
                }
                let lane_fit = if self.clear_line(me_position, reception, me.team.other(), 1.8) {
                    1.0
                } else {
                    0.18
                };
                let quality = pass_target_quality_for_snapshot(
                    self,
                    me,
                    me_position,
                    target,
                    target_position,
                    PassFlight::Floor,
                );
                if quality.expected_completion < 0.24 || lane_fit < 0.30 {
                    return None;
                }
                let window = self.shooting_window_score_at(target, reception);
                let range_fit = ((KILLER_PASS_MAX_YARDS_TO_GOAL - yards_to_goal)
                    / KILLER_PASS_MAX_YARDS_TO_GOAL)
                    .clamp(0.0, 1.0);
                let role_bonus = match target.role {
                    PlayerRole::Forward => 1.4,
                    PlayerRole::Midfielder => 0.85,
                    PlayerRole::Defender => 0.20,
                    PlayerRole::Goalkeeper => -3.0,
                };
                let runner_bonus = if self.player_is_recent_forward_runner(target) {
                    1.2
                } else {
                    0.0
                };
                let score = goal_gain * 0.12
                    + forward.min(24.0) * 0.055
                    + window * 4.8
                    + quality.receiver_openness * 1.7
                    + quality.expected_completion * 1.5
                    + quality.stride_fit * 1.25
                    + lane_fit * 1.3
                    + range_fit * 1.2
                    + role_bonus
                    + runner_bonus;
                Some((target_id, score))
            })
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(target_id, _)| target_id)
    }

    fn ranked_pass_targets_filtered(
        &self,
        player_id: usize,
        limit: usize,
        visible_only: bool,
    ) -> Vec<usize> {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return Vec::new();
        };
        let me_position = self.player_snapshot_position(me);
        let directive = self.tactical_directive(me.team);
        let no_pressure = self.no_pressure_at(me.team, me_position);
        let keeper_pressure = if me.role == PlayerRole::Goalkeeper {
            pressure_from_nearest_distance(self.nearest_opponent_distance_at(me.team, me_position))
        } else {
            0.0
        };
        let mut ranked = self
            .players
            .iter()
            .filter(|p| p.team == me.team && p.id != me.id)
            .filter_map(|p| {
                let position = self.player_snapshot_position(p);
                let initial_is_cross = pass_would_be_cross(
                    me_position,
                    position,
                    me.team,
                    self.field_width,
                    self.field_length,
                );
                let nominal_speed = pass_speed_yps_from_power(
                    0.68,
                    PassFlight::Floor,
                    initial_is_cross,
                    &me.skills,
                );
                let anticipated_position = self
                    .anticipated_pass_reception_point(me.id, p.id, PassFlight::Floor, nominal_speed)
                    .unwrap_or(position);
                let forward = (anticipated_position.y - me_position.y) * me.team.attack_dir();
                if me.role == PlayerRole::Goalkeeper
                    && forward < -1.25
                    && !goalkeeper_backward_emergency_release_allowed(
                        me.team,
                        me_position,
                        anticipated_position,
                        self.field_width,
                        keeper_pressure,
                    )
                {
                    return None;
                }
                if no_pressure && forward < -1.25 {
                    return None;
                }
                ((!visible_only || self.player_can_see_player(me.id, p.id))
                    && self.clear_line(me_position, anticipated_position, me.team.other(), 2.5)
                    && self.pending_offside_for_pass(me.id, p.id).is_none())
                .then_some((p, position, anticipated_position))
            })
            .map(|p| {
                let (p, position, pass_point) = p;
                let forward = (pass_point.y - me_position.y) * me.team.attack_dir();
                let dist = me_position.distance(position);
                let support_fit = (dist - directive.support_depth_yards).abs();
                let confidence = self
                    .player_position_confidence_for_point(me.id, position)
                    .unwrap_or(0.0);
                let own_half = pass_origin_in_own_half(me.team, me_position, self.field_length);
                let backward = forward < -1.25;
                let lateral = forward.abs() <= 1.25;
                let blind_backward_penalty = if backward && own_half {
                    3.6 + (1.0 - confidence) * 4.2
                } else if backward {
                    1.5 + (1.0 - confidence) * 1.8
                } else {
                    0.0
                };
                let lateral_penalty = if lateral { 0.85 } else { 0.0 };
                let forward_weight = 0.14 + directive.risk_tolerance * 0.22;
                let role_bonus = match p.role {
                    PlayerRole::Forward => 1.4,
                    PlayerRole::Midfielder => 1.05,
                    PlayerRole::Defender => 0.1,
                    PlayerRole::Goalkeeper => -3.0,
                };
                let pass_quality = pass_target_quality_for_snapshot(
                    self,
                    me,
                    me_position,
                    p,
                    position,
                    PassFlight::Floor,
                );
                let finishing_window_bonus = self.shooting_window_score_at(p, pass_point)
                    * (5.4 + directive.risk_tolerance * 2.4);
                let keeper_distribution_bonus = if me.role == PlayerRole::Goalkeeper {
                    goalkeeper_distribution_score(
                        me.team,
                        me_position,
                        pass_point,
                        self.field_width,
                        keeper_pressure,
                    )
                } else {
                    0.0
                };
                let is_cross = pass_would_be_cross(
                    me_position,
                    pass_point,
                    me.team,
                    self.field_width,
                    self.field_length,
                );
                let low_cross_policy_bonus =
                    if is_cross && directive.flank_attack_policy.prefers_low_cross() {
                        1.15 + directive.flank_overlap_run_probability * 0.75
                    } else if is_cross && directive.flank_attack_policy.is_flank() {
                        0.38
                    } else {
                        0.0
                    };
                let score = forward * forward_weight + self.space_score_at(position, me.team)
                    - dist * 0.010
                    - support_fit * 0.020
                    + confidence * 0.65
                    + role_bonus
                    + pass_quality.expected_completion * 1.55
                    + pass_quality.receiver_openness * 0.62
                    + pass_quality.stride_fit * 1.18
                    + (p.velocity.y * me.team.attack_dir()).max(0.0).min(5.5) * 0.12
                    + finishing_window_bonus
                    + keeper_distribution_bonus;
                let score =
                    score + low_cross_policy_bonus - blind_backward_penalty - lateral_penalty;
                (p.id, score)
            })
            .collect::<Vec<_>>();
        ranked.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        ranked.into_iter().take(limit).map(|(id, _)| id).collect()
    }

    fn ranked_aerial_pass_targets_filtered(
        &self,
        player_id: usize,
        limit: usize,
        visible_only: bool,
    ) -> Vec<usize> {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return Vec::new();
        };
        let me_position = self.player_snapshot_position(me);
        let directive = self.tactical_directive(me.team);
        let no_pressure = self.no_pressure_at(me.team, me_position);
        let keeper_pressure = if me.role == PlayerRole::Goalkeeper {
            pressure_from_nearest_distance(self.nearest_opponent_distance_at(me.team, me_position))
        } else {
            0.0
        };
        let preferred_in_behind_target = self.long_ball_in_behind_target(me.id);
        let mut ranked = self
            .players
            .iter()
            .filter(|p| p.team == me.team && p.id != me.id)
            .filter_map(|p| {
                let position = self.player_snapshot_position(p);
                let initial_is_cross = pass_would_be_cross(
                    me_position,
                    position,
                    me.team,
                    self.field_width,
                    self.field_length,
                );
                let nominal_speed = pass_speed_yps_from_power(
                    0.68,
                    PassFlight::Aerial,
                    initial_is_cross,
                    &me.skills,
                );
                let anticipated_position = self
                    .anticipated_pass_reception_point(
                        me.id,
                        p.id,
                        PassFlight::Aerial,
                        nominal_speed,
                    )
                    .unwrap_or(position);
                let pass_point = self
                    .projected_in_behind_pass_point(me.id, p.id)
                    .unwrap_or(anticipated_position);
                let forward = (pass_point.y - me_position.y) * me.team.attack_dir();
                if me.role == PlayerRole::Goalkeeper
                    && forward < -1.25
                    && !goalkeeper_backward_emergency_release_allowed(
                        me.team,
                        me_position,
                        pass_point,
                        self.field_width,
                        keeper_pressure,
                    )
                {
                    return None;
                }
                if no_pressure && forward < -1.25 {
                    return None;
                }
                ((!visible_only || self.player_can_see_player(me.id, p.id))
                    && self.pending_offside_for_pass(me.id, p.id).is_none())
                .then_some((p, position, pass_point))
            })
            .map(|(p, position, pass_point)| {
                let forward = (pass_point.y - me_position.y) * me.team.attack_dir();
                let dist = me_position.distance(pass_point);
                let confidence = self
                    .player_position_confidence_for_point(me.id, position)
                    .unwrap_or(0.0);
                let is_cross = pass_would_be_cross(
                    me_position,
                    pass_point,
                    me.team,
                    self.field_width,
                    self.field_length,
                );
                let aerial_target_bonus = ability01(p.skills.height) * 1.4
                    + ability01(p.skills.strength) * 0.8
                    + ability01(p.skills.first_touch) * 0.6;
                let lane_bonus = if self.clear_line(me_position, position, me.team.other(), 2.5) {
                    0.4
                } else {
                    1.8
                };
                let cross_bonus = if is_cross {
                    1.3 + if directive.flank_attack_policy.prefers_high_cross() {
                        1.20 + directive.flank_overlap_run_probability * 0.80
                    } else if directive.flank_attack_policy.is_flank() {
                        0.35
                    } else {
                        0.0
                    }
                } else {
                    0.0
                };
                let wide_outlet_bonus = if self.is_wide_midfielder(p) {
                    let center_x = self.field_width * 0.5;
                    let width =
                        ((pass_point.x - center_x).abs() / center_x.max(1.0)).clamp(0.0, 1.0);
                    let openness = pass_receiver_openness_for_snapshots_with_teammates(
                        &self.players,
                        me.team,
                        pass_point,
                        Some(p.id),
                    );
                    let forward_support = (pass_point.y - me_position.y) * me.team.attack_dir();
                    (width * 1.25 + openness * 2.4 + forward_support.clamp(0.0, 24.0) * 0.035)
                        .clamp(0.0, 4.2)
                } else {
                    0.0
                };
                let finishing_window_bonus = self.shooting_window_score_at(p, pass_point)
                    * (3.4 + directive.risk_tolerance * 1.8);
                let in_behind_bonus = self
                    .projected_in_behind_pass_point(me.id, p.id)
                    .map(|pass_point| {
                        let role_fit = match p.role {
                            PlayerRole::Forward => 1.35,
                            PlayerRole::Midfielder => 0.55,
                            PlayerRole::Defender => -0.70,
                            PlayerRole::Goalkeeper => -3.0,
                        };
                        3.2 + role_fit + self.space_score_at(pass_point, me.team) * 0.060
                    })
                    .unwrap_or(0.0);
                let preferred_in_behind_bonus = if preferred_in_behind_target == Some(p.id) {
                    7.2
                } else {
                    0.0
                };
                let pass_quality = pass_target_quality_for_snapshot(
                    self,
                    me,
                    me_position,
                    p,
                    position,
                    PassFlight::Aerial,
                );
                let keeper_distribution_bonus = if me.role == PlayerRole::Goalkeeper {
                    goalkeeper_distribution_score(
                        me.team,
                        me_position,
                        position,
                        self.field_width,
                        keeper_pressure,
                    )
                } else {
                    0.0
                };
                let lateral_penalty = if forward.abs() <= 1.25 { 0.55 } else { 0.0 };
                let blind_backward_penalty = if forward < -1.25
                    && pass_origin_in_own_half(me.team, me_position, self.field_length)
                {
                    2.5 + (1.0 - confidence) * 2.8
                } else if forward < -1.25 {
                    1.1 + (1.0 - confidence) * 1.2
                } else {
                    0.0
                };
                let score = forward * (0.16 + directive.risk_tolerance * 0.24)
                    + self.space_score_at(pass_point, me.team) * 0.65
                    - dist * 0.018
                    + confidence * 0.42
                    + aerial_target_bonus
                    + lane_bonus
                    + cross_bonus
                    + wide_outlet_bonus
                    + finishing_window_bonus
                    + in_behind_bonus
                    + preferred_in_behind_bonus
                    + pass_quality.expected_completion * 0.85
                    + pass_quality.receiver_openness * 0.38
                    + pass_quality.stride_fit * 0.46
                    + keeper_distribution_bonus
                    - blind_backward_penalty
                    - lateral_penalty;
                (p.id, score)
            })
            .collect::<Vec<_>>();
        ranked.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        ranked.into_iter().take(limit).map(|(id, _)| id).collect()
    }

    pub fn player_can_see_player(&self, observer_id: usize, target_id: usize) -> bool {
        if observer_id == target_id {
            return true;
        }
        self.player_position(target_id)
            .map(|position| self.player_can_see_point(observer_id, position))
            .unwrap_or(false)
    }

    pub fn player_can_see_point(&self, observer_id: usize, point: Vec2) -> bool {
        let Some(observer) = self.players.iter().find(|p| p.id == observer_id) else {
            return false;
        };
        let observer_position = self
            .player_position(observer.id)
            .unwrap_or(observer.position);
        let to_point = point - observer_position;
        let distance = to_point.len();
        if distance <= PLAYER_CONTROL_RADIUS_YARDS * 3.0 {
            return true;
        }
        let vision_range = player_vision_range(observer);
        if distance > vision_range {
            return false;
        }
        let facing = self.player_facing_direction(observer);
        let Some(facing) = facing else {
            return true;
        };
        if self.ball.holder == Some(observer_id) {
            let angle = angle_between_vectors_degrees(facing, to_point);
            return angle
                <= (BALL_HOLDER_CORE_VISION_DEGREES * 0.5 + BALL_HOLDER_SHOULDER_VISION_DEGREES);
        }
        let fov = player_field_of_view(observer);
        let half_fov_cos = (fov.to_radians() * 0.5).cos();
        facing.dot(to_point.normalized()) >= half_fov_cos
    }

    pub fn player_position_confidence_for_point(
        &self,
        observer_id: usize,
        point: Vec2,
    ) -> Option<f64> {
        let observer = self.players.iter().find(|p| p.id == observer_id)?;
        let observer_position = self
            .player_position(observer.id)
            .unwrap_or(observer.position);
        Some(position_confidence_for_observer(
            observer,
            observer_position,
            point,
            self.player_facing_direction(observer),
            self.ball.holder == Some(observer_id),
        ))
    }

    pub fn player_position_confidence_entry(
        &self,
        observer_id: usize,
        target: &PlayerSnapshot,
    ) -> Option<PlayerPositionConfidence> {
        let observer = self.players.iter().find(|p| p.id == observer_id)?;
        let observer_position = self
            .player_position(observer.id)
            .unwrap_or(observer.position);
        let target_position = self.player_snapshot_position(target);
        let to_target = target_position - observer_position;
        let facing = self.player_facing_direction(observer);
        let in_front = facing
            .map(|facing| facing.normalized().dot(to_target.normalized()) >= 0.0)
            .unwrap_or(false);
        Some(PlayerPositionConfidence {
            observer_id,
            player_id: target.id,
            team: target.team,
            distance_yards: to_target.len(),
            in_front,
            confidence: position_confidence_for_observer(
                observer,
                observer_position,
                target_position,
                facing,
                self.ball.holder == Some(observer_id),
            ),
        })
    }

    fn player_facing_direction(&self, player: &PlayerSnapshot) -> Option<Vec2> {
        if self.ball.holder == Some(player.id) {
            return facing_bucket_to_vector(player.action_facing)
                .or_else(|| Some(Vec2::new(0.0, player.team.attack_dir())));
        }
        let player_position = self.player_snapshot_position(player);
        let to_ball = self.ball.position - player_position;
        if to_ball.len() > PLAYER_CONTROL_RADIUS_YARDS * 0.6 {
            Some(to_ball.normalized())
        } else {
            Some(Vec2::new(0.0, player.team.attack_dir()))
        }
    }

    fn player_state_action_facing(&self, player: &PlayerSnapshot) -> FacingBucket {
        if player.action_facing != FacingBucket::Unknown {
            return player.action_facing;
        }
        self.player_facing_direction(player)
            .map(facing_bucket_from_vector)
            .unwrap_or(FacingBucket::Unknown)
    }

    fn pending_offside_for_pass(
        &self,
        passer_id: usize,
        target_id: usize,
    ) -> Option<PendingOffside> {
        if self
            .ball
            .last_decision
            .as_ref()
            .is_some_and(|decision| offside_exempt_restart_action(&decision.action))
        {
            return None;
        }
        let passer = self.players.iter().find(|p| p.id == passer_id)?;
        let target = self.players.iter().find(|p| p.id == target_id)?;
        if passer.team != target.team || passer.id == target.id {
            return None;
        }
        let target_position = self.player_snapshot_position(target);
        let half_line = self.field_length * 0.5;
        match passer.team {
            Team::Home if target_position.y <= half_line => return None,
            Team::Away if target_position.y >= half_line => return None,
            _ => {}
        }

        let mut defender_ys = self
            .players
            .iter()
            .filter(|p| p.team == passer.team.other())
            .filter_map(|p| self.player_position(p.id).map(|position| position.y))
            .collect::<Vec<_>>();
        if defender_ys.len() < 2 {
            return None;
        }

        let is_offside = match passer.team {
            Team::Home => {
                defender_ys.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
                let second_last_defender_y = defender_ys[1];
                (target_position.y > self.ball.position.y)
                    && (target_position.y > second_last_defender_y)
                    && (target_position.y > half_line)
            }
            Team::Away => {
                defender_ys.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                let second_last_defender_y = defender_ys[1];
                (target_position.y < self.ball.position.y)
                    && (target_position.y < second_last_defender_y)
                    && (target_position.y < half_line)
            }
        };
        if !is_offside {
            return None;
        }

        let second_last_defender_y = match passer.team {
            Team::Home => defender_ys[1],
            Team::Away => defender_ys[1],
        };
        Some(PendingOffside {
            team: passer.team,
            passer: passer.id,
            target: target.id,
            position: target_position,
            ball_y: self.ball.position.y,
            second_last_defender_y,
        })
    }

    fn second_last_defender_line_for(&self, attacking_team: Team) -> Option<f64> {
        let mut defender_ys = self
            .players
            .iter()
            .filter(|p| p.team == attacking_team.other())
            .filter_map(|p| self.player_position(p.id).map(|position| position.y))
            .collect::<Vec<_>>();
        if defender_ys.len() < 2 {
            return None;
        }
        match attacking_team {
            Team::Home => {
                defender_ys.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
            }
            Team::Away => {
                defender_ys.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            }
        }
        defender_ys.get(1).copied()
    }

    fn neutral_in_behind_window(&self, team: Team) -> bool {
        let progress_from_midfield =
            (self.ball.position.y - self.field_length * 0.5) * team.attack_dir();
        (-18.0..=28.0).contains(&progress_from_midfield)
    }

    fn in_behind_run_target_for(&self, player_id: usize) -> Option<Vec2> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if self.possession_team() != Some(me.team)
            || self.ball.holder == Some(player_id)
            || !matches!(me.role, PlayerRole::Forward | PlayerRole::Midfielder)
            || !self.neutral_in_behind_window(me.team)
        {
            return None;
        }
        let cadence = (self.tick + player_id as u64 * 17) % 41;
        if cadence > 5 {
            return None;
        }
        let current = self.player_snapshot_position(me);
        let line_y = self.second_last_defender_line_for(me.team)?;
        let staging_y = line_y - me.team.attack_dir() * 20.0;
        if (current.y - staging_y).abs() > 14.0 {
            return None;
        }
        let holder_position = self
            .ball
            .holder
            .and_then(|holder| self.player_position(holder))
            .unwrap_or(self.ball.position);
        let run_y = line_y + me.team.attack_dir() * 9.0;
        let target = Vec2::new(
            (current.x * 0.76 + holder_position.x * 0.24).clamp(4.0, self.field_width - 4.0),
            run_y,
        )
        .clamp_to_pitch(self.field_width, self.field_length);
        Some(target)
    }

    fn projected_in_behind_pass_point(&self, passer_id: usize, target_id: usize) -> Option<Vec2> {
        let passer = self.players.iter().find(|p| p.id == passer_id)?;
        let target = self.players.iter().find(|p| p.id == target_id)?;
        if passer.team != target.team
            || passer.id == target.id
            || self
                .pending_offside_for_pass(passer_id, target_id)
                .is_some()
            || !self.neutral_in_behind_window(passer.team)
        {
            return None;
        }
        let target_position = self.player_snapshot_position(target);
        let line_y = self.second_last_defender_line_for(passer.team)?;
        let staging_y = line_y - passer.team.attack_dir() * 20.0;
        if (target_position.y - staging_y).abs() > 16.0 {
            return None;
        }
        let projected_y = line_y + passer.team.attack_dir() * 11.0;
        Some(
            Vec2::new(target_position.x, projected_y)
                .clamp_to_pitch(self.field_width, self.field_length),
        )
    }

    fn player_forward_progress_over_seconds(&self, player: &PlayerSnapshot, seconds: f64) -> f64 {
        let seconds = seconds.max(0.0);
        if seconds <= 0.0 {
            return 0.0;
        }
        let current = self.player_snapshot_position(player);
        let attack_dir = player.team.attack_dir();
        if let Some(progress) = self.player_position_history(player.id).and_then(|history| {
            player_sample_forward_progress_over_seconds(
                history,
                current,
                attack_dir,
                self.clock_seconds,
                seconds,
            )
        }) {
            return progress;
        }
        let dt = self.dt_seconds.max(0.0);
        if dt > 0.0 {
            let steps = (seconds / dt).round().max(1.0) as usize;
            if player.position_history.len() > steps {
                let start = player.position_history[player.position_history.len() - 1 - steps];
                return (current.y - start.y) * attack_dir;
            }
            if player.position_history.len() >= 2 {
                let start = player.position_history[0];
                let elapsed = (player.position_history.len() - 1) as f64 * dt;
                if elapsed >= seconds * 0.5 {
                    let observed = (current.y - start.y) * attack_dir;
                    return observed * (seconds / elapsed.max(dt)).clamp(0.5, 2.0);
                }
            }
        }
        player.velocity.y * attack_dir * seconds
    }

    fn player_is_recent_forward_runner(&self, player: &PlayerSnapshot) -> bool {
        self.player_forward_progress_over_seconds(player, 2.0) > 5.0
            || self.player_forward_progress_over_seconds(player, 4.0) > 10.0
    }

    fn aerial_forward_runner_pass_multiplier(&self, passer_id: usize) -> f64 {
        let Some(passer) = self.players.iter().find(|p| p.id == passer_id) else {
            return 1.0;
        };
        let multiplier = match passer.role {
            PlayerRole::Defender => 1.15,
            PlayerRole::Midfielder => 1.50,
            _ => return 1.0,
        };
        let has_visible_runner = self.players.iter().any(|target| {
            if target.team != passer.team || target.id == passer.id {
                return false;
            }
            let role_ok = match passer.role {
                PlayerRole::Defender => target.role == PlayerRole::Forward,
                PlayerRole::Midfielder => {
                    matches!(target.role, PlayerRole::Forward | PlayerRole::Midfielder)
                }
                _ => false,
            };
            role_ok
                && self.player_is_recent_forward_runner(target)
                && self.player_can_see_player(passer.id, target.id)
                && self
                    .pending_offside_for_pass(passer.id, target.id)
                    .is_none()
        });
        if has_visible_runner {
            multiplier
        } else {
            1.0
        }
    }

    fn long_ball_in_behind_target(&self, passer_id: usize) -> Option<usize> {
        let passer = self.players.iter().find(|p| p.id == passer_id)?;
        if self.ball.holder != Some(passer_id)
            || self.possession_team() != Some(passer.team)
            || !self.neutral_in_behind_window(passer.team)
        {
            return None;
        }
        let passer_position = self.player_snapshot_position(passer);
        self.players
            .iter()
            .filter(|p| p.team == passer.team && p.id != passer.id)
            .filter(|p| matches!(p.role, PlayerRole::Forward | PlayerRole::Midfielder))
            .filter_map(|target| {
                let pass_point = self.projected_in_behind_pass_point(passer.id, target.id)?;
                let target_position = self.player_snapshot_position(target);
                let forward = (pass_point.y - passer_position.y) * passer.team.attack_dir();
                if forward <= 12.0 {
                    return None;
                }
                let line_bonus = if self.clear_line(
                    passer_position,
                    target_position,
                    passer.team.other(),
                    2.5,
                ) {
                    0.0
                } else {
                    1.2
                };
                let score = forward * 0.10 + self.space_score_at(pass_point, passer.team) * 0.06
                    - passer_position.distance(pass_point) * 0.010
                    + line_bonus;
                Some((target.id, score))
            })
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(id, _)| id)
    }

    fn check_to_ball_target_for(&self, player_id: usize, home: Vec2) -> Option<Vec2> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if self.possession_team() != Some(me.team)
            || self.ball.holder == Some(player_id)
            || me.role == PlayerRole::Goalkeeper
        {
            return None;
        }
        let current = self.player_snapshot_position(me);
        let marker = self.nearest_opponent_at(me.team, current)?;
        if marker.2 > 4.5 {
            return None;
        }
        let toward_ball = (self.ball.position - current).normalized();
        let toward_own_goal = (Vec2::new(
            self.field_width * 0.5,
            me.team.other().goal_y(self.field_length),
        ) - current)
            .normalized();
        let lateral_away = (current - marker.1).normalized();
        let candidate = (current + toward_ball * 4.8 + toward_own_goal * 3.8 + lateral_away * 1.6)
            .clamp_to_pitch(self.field_width, self.field_length);
        if candidate.distance(self.ball.position) >= current.distance(self.ball.position) {
            return None;
        }
        let candidate_pressure = self.nearest_opponent_distance_at(me.team, candidate);
        if candidate_pressure <= marker.2 + 0.8 && candidate_pressure < 5.2 {
            return None;
        }
        if self.position_would_be_offside(me.team, candidate)
            || !self.clear_line(self.ball.position, candidate, me.team.other(), 2.0)
        {
            return None;
        }
        Some(self.clamp_to_role_position(player_id, candidate, home, false))
    }

    fn pending_pass_reception_target_for(&self, player_id: usize) -> Option<(Vec2, bool)> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        let pass = self.pending_pass.as_ref()?;
        if self.ball.holder.is_some()
            || pass.team != me.team
            || pass.nearest_receiver != Some(player_id)
        {
            return None;
        }
        let current = self.player_snapshot_position(me);
        let distance_to_ball = current.distance(self.ball.position);
        if distance_to_ball > 42.0 {
            return None;
        }
        let nearest_opponent_to_ball =
            self.nearest_opponent_distance_at(me.team, self.ball.position);
        let pressured_reception =
            nearest_opponent_to_ball <= distance_to_ball + 5.0 || nearest_opponent_to_ball <= 6.0;
        let lead_seconds = if pressured_reception {
            (0.08 + distance_to_ball / 55.0 * 0.22).clamp(0.08, 0.30)
        } else {
            (0.18 + distance_to_ball / 42.0 * 0.42).clamp(0.18, 0.60)
        };
        let fallback_target = (self.ball.position + self.ball.velocity * lead_seconds)
            .clamp_to_pitch(self.field_width, self.field_length);
        let target = if self.ball.velocity.len() > 0.25 {
            let sprint_speed = player_top_speed_yps(me.role, &me.skills)
                * fatigue_speed_factor(me.skills.stamina, me.fatigue)
                * MovementGait::Sprint.speed_multiplier();
            let remaining_ball_path = self.ball.position.distance(pass.intended_target);
            let ball_time_to_target = (remaining_ball_path / self.ball.velocity.len().max(0.25))
                .clamp(0.12, if pressured_reception { 0.85 } else { 1.35 });
            let horizon = ball_time_to_target.max(lead_seconds);
            let mut best_target = fallback_target;
            let mut best_score = f64::NEG_INFINITY;
            for step in 1..=6 {
                let t = horizon * step as f64 / 6.0;
                let candidate = (self.ball.position + self.ball.velocity * t)
                    .clamp_to_pitch(self.field_width, self.field_length);
                let arrival_time = current.distance(candidate) / sprint_speed.max(1.0);
                let lateness = (arrival_time - t).max(0.0);
                let forward_receive =
                    ((candidate.y - current.y) * me.team.attack_dir()).clamp(-4.0, 12.0);
                let score = -lateness * 3.2 - arrival_time * 0.10 + forward_receive * 0.035;
                if score > best_score {
                    best_score = score;
                    best_target = candidate;
                }
            }
            best_target
        } else {
            fallback_target
        };
        let sprint = pass.receiver_urgency >= 0.30
            || pass.off_target_yards > 0.75
            || distance_to_ball > 4.5
            || pressured_reception;
        Some((target, sprint))
    }

    fn projected_loose_ball_target(&self) -> Option<Vec2> {
        if self.ball.holder.is_some() || self.pending_pass.is_some() {
            return None;
        }
        let speed = self.ball.velocity.len();
        if speed < 8.0 {
            return None;
        }
        let long_ball_action = self
            .ball
            .last_decision
            .as_ref()
            .is_some_and(|decision| is_untargeted_long_ball_action(&decision.action));
        if !long_ball_action && self.ball.altitude_yards <= 0.02 {
            return None;
        }
        let horizon = if long_ball_action {
            (1.30 + speed / 16.0).clamp(1.60, 4.00)
        } else {
            (0.42 + speed / 32.0).clamp(0.45, 1.25)
        };
        Some(
            (self.ball.position + self.ball.velocity * horizon)
                .clamp_to_pitch(self.field_width, self.field_length),
        )
    }

    fn active_rebound_for_player(&self, player_id: usize) -> Option<&PendingRebound> {
        let rebound = self.pending_rebound.as_ref()?;
        if self.ball.holder.is_some() || self.tick.saturating_sub(rebound.launch_tick) > 16 {
            return None;
        }
        self.players.iter().find(|player| player.id == player_id)?;
        Some(rebound)
    }

    fn rebound_recovery_sprint_active(&self, player_id: usize) -> bool {
        self.active_rebound_for_player(player_id).is_some()
    }

    fn loose_ball_recovery_target_for(&self, player_id: usize) -> Vec2 {
        if self.active_rebound_for_player(player_id).is_some() {
            return self
                .projected_loose_ball_target()
                .unwrap_or(self.ball.position)
                .clamp_to_pitch(self.field_width, self.field_length);
        }
        let target = self
            .projected_loose_ball_target()
            .unwrap_or(self.ball.position);
        let Some(player) = self.players.iter().find(|player| player.id == player_id) else {
            return target;
        };
        if player.role != PlayerRole::Goalkeeper {
            return target;
        }
        let current = self.player_snapshot_position(player);
        let ball_distance = current.distance(target);
        let line_target = self.goalkeeper_ball_goal_tracking_target(player.team);
        if ball_distance <= GOALKEEPER_LOOSE_BALL_COLLECTION_WINDOW_YARDS
            && target.distance(line_target) <= GOALKEEPER_LINE_COLLECTION_DEVIATION_YARDS
            && self.nearest_opponent_distance_at(player.team, target)
                > GOALKEEPER_LOOSE_BALL_COLLECTION_WINDOW_YARDS
        {
            return target;
        }
        line_target
    }

    fn is_wide_defender(&self, player: &PlayerSnapshot) -> bool {
        player.role == PlayerRole::Defender
            && (player.home_position.x < self.field_width * 0.28
                || player.home_position.x > self.field_width * 0.72)
    }

    fn is_wide_midfielder(&self, player: &PlayerSnapshot) -> bool {
        player.role == PlayerRole::Midfielder
            && (player.home_position.x < self.field_width * 0.30
                || player.home_position.x > self.field_width * 0.70)
    }

    fn support_target_with_min_upfield_slope(
        &self,
        current: Vec2,
        target: Vec2,
        team: Team,
    ) -> Vec2 {
        let lateral = (target.x - current.x).abs();
        if lateral <= 1e-6 {
            return target.clamp_to_pitch(self.field_width, self.field_length);
        }
        let min_forward = lateral * SUPPORT_MIN_UPFIELD_PER_LATERAL_YARD;
        let forward = (target.y - current.y) * team.attack_dir();
        if forward >= min_forward {
            return target.clamp_to_pitch(self.field_width, self.field_length);
        }
        Vec2::new(target.x, current.y + team.attack_dir() * min_forward)
            .clamp_to_pitch(self.field_width, self.field_length)
    }

    fn wide_possession_outlet_target_for(&self, player_id: usize, home: Vec2) -> Option<Vec2> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if self.possession_team() != Some(me.team)
            || self.ball.holder == Some(player_id)
            || !self.is_wide_midfielder(me)
        {
            return None;
        }
        let current = self.player_snapshot_position(me);
        let center_x = self.field_width * 0.5;
        let touchline_x = if home.x <= center_x {
            WIDE_OUTLET_TOUCHLINE_BUFFER_YARDS
        } else {
            self.field_width - WIDE_OUTLET_TOUCHLINE_BUFFER_YARDS
        };
        let lateral = (touchline_x - current.x).abs();
        let min_forward =
            (lateral * SUPPORT_MIN_UPFIELD_PER_LATERAL_YARD).max(WIDE_OUTLET_MIN_FORWARD_YARDS);
        let direct = Vec2::new(touchline_x, current.y + me.team.attack_dir() * min_forward);
        let advanced = Vec2::new(
            touchline_x,
            self.ball.position.y + me.team.attack_dir() * (8.0 + min_forward * 0.35),
        );
        let candidates = [
            self.support_target_with_min_upfield_slope(current, direct, me.team),
            self.support_target_with_min_upfield_slope(current, advanced, me.team),
        ];
        candidates
            .into_iter()
            .filter(|candidate| !self.position_would_be_offside(me.team, *candidate))
            .map(|candidate| {
                let openness = pass_receiver_openness_for_snapshots_with_teammates(
                    &self.players,
                    me.team,
                    candidate,
                    Some(me.id),
                );
                let width = ((candidate.x - center_x).abs() / center_x.max(1.0)).clamp(0.0, 1.0);
                let lane_bonus =
                    if self.clear_line(self.ball.position, candidate, me.team.other(), 2.0) {
                        1.0
                    } else {
                        -0.8
                    };
                let forward = (candidate.y - current.y) * me.team.attack_dir();
                let relief =
                    self.positional_shape_exception_relief_for_player_target(me, candidate);
                let lane_penalty =
                    self.vertical_lane_penalty_for_player_target(me, candidate, relief);
                let teammate_penalty = self.teammate_occupied_space_penalty_at(
                    me.team,
                    candidate,
                    Some(me.id),
                    relief,
                );
                let line_penalty = self.role_line_penalty_for_player_target(me, candidate, relief);
                let score = self.space_score_at(candidate, me.team)
                    + openness * 3.0
                    + width * 2.0
                    + forward.clamp(0.0, 18.0) * 0.08
                    + lane_bonus
                    - candidate.distance(home) * 0.025
                    - lane_penalty
                    - teammate_penalty
                    - line_penalty;
                (candidate, score)
            })
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(candidate, _)| self.clamp_to_role_position(player_id, candidate, home, false))
    }

    fn flank_cross_arrival_target_for(&self, player_id: usize, home: Vec2) -> Option<Vec2> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if self.possession_team() != Some(me.team)
            || self.ball.holder == Some(player_id)
            || !matches!(me.role, PlayerRole::Forward | PlayerRole::Midfielder)
            || self.is_wide_midfielder(me)
        {
            return None;
        }
        if me.role == PlayerRole::Midfielder
            && me.preferences.defensive_mindedness > me.preferences.offensive_mindedness
        {
            return None;
        }

        let directive = self.tactical_directive(me.team);
        if !directive.flank_attack_policy.is_flank() {
            return None;
        }

        let crosser_position = self
            .ball
            .holder
            .and_then(|holder| {
                self.players
                    .iter()
                    .find(|p| p.id == holder)
                    .and_then(|p| (p.team == me.team).then(|| self.player_snapshot_position(p)))
            })
            .unwrap_or(self.ball.position);
        if flank_lane_score(crosser_position, self.field_width) < 0.42 {
            return None;
        }

        let dir = me.team.attack_dir();
        let attacking_depth = (crosser_position.y - self.field_length * 0.5) * dir;
        if attacking_depth < -10.0 {
            return None;
        }

        let center_x = self.field_width * 0.5;
        let goal_y = me.team.goal_y(self.field_length);
        let source_side = if crosser_position.x >= center_x {
            1.0
        } else {
            -1.0
        };
        let near_post = Vec2::new(center_x + source_side * 2.8, goal_y - dir * 7.0);
        let cutback = Vec2::new(center_x - source_side * 1.5, goal_y - dir * 14.0);
        let penalty_spot = Vec2::new(center_x, goal_y - dir * 11.5);
        let far_post = Vec2::new(center_x - source_side * 3.8, goal_y - dir * 4.8);
        let far_header_lane = Vec2::new(center_x - source_side * 5.2, goal_y - dir * 8.2);
        let current = self.player_snapshot_position(me);
        let candidates: &[Vec2] = if directive.flank_attack_policy.prefers_high_cross() {
            &[far_post, far_header_lane, penalty_spot]
        } else {
            &[near_post, cutback, penalty_spot]
        };

        candidates
            .iter()
            .copied()
            .map(|candidate| self.clamp_forward_onside_support(me, candidate))
            .filter(|candidate| !self.position_would_be_offside(me.team, *candidate))
            .map(|candidate| {
                let goalward = ((candidate.y - current.y) * dir).clamp(-6.0, 26.0);
                let cross_lane = if self.clear_line(
                    crosser_position,
                    candidate,
                    me.team.other(),
                    if directive.flank_attack_policy.prefers_high_cross() {
                        1.1
                    } else {
                        2.1
                    },
                ) {
                    1.0
                } else if directive.flank_attack_policy.prefers_high_cross() {
                    0.42
                } else {
                    -0.55
                };
                let centrality =
                    (1.0 - ((candidate.x - center_x).abs() / center_x.max(1.0))).clamp(0.0, 1.0);
                let far_post_fit =
                    (((candidate.x - center_x) * -source_side) / 6.0).clamp(0.0, 1.0);
                let near_post_fit =
                    (((candidate.x - center_x) * source_side) / 5.0).clamp(0.0, 1.0);
                let policy_lane_fit = if directive.flank_attack_policy.prefers_high_cross() {
                    far_post_fit * 1.18
                } else {
                    near_post_fit * 0.32
                        + ((goal_y - candidate.y).abs() / 16.0).clamp(0.0, 1.0) * 0.12
                };
                let aerial_fit = if directive.flank_attack_policy.prefers_high_cross() {
                    ability01(me.skills.height) * 0.34 + ability01(me.skills.strength) * 0.20
                } else {
                    ability01(me.skills.first_touch) * 0.22
                        + ability01(me.skills.acceleration) * 0.18
                };
                let role_fit = match (me.role, directive.flank_attack_policy) {
                    (PlayerRole::Forward, FlankAttackPolicy::PlayDownFlankHighCross) => 0.54,
                    (PlayerRole::Forward, FlankAttackPolicy::PlayDownFlankLowCross) => 0.42,
                    (PlayerRole::Midfielder, FlankAttackPolicy::PlayDownFlankLowCross) => 0.34,
                    (PlayerRole::Midfielder, FlankAttackPolicy::PlayDownFlankHighCross) => 0.18,
                    _ => 0.0,
                };
                let score = self.shooting_window_score_at(me, candidate) * 4.2
                    + self.space_score_at(candidate, me.team) * 0.055
                    + pass_receiver_openness_for_snapshots_with_teammates(
                        &self.players,
                        me.team,
                        candidate,
                        Some(me.id),
                    ) * 0.36
                    + goalward.max(0.0) * 0.060
                    + cross_lane * 0.68
                    + centrality * 0.12
                    + policy_lane_fit
                    + aerial_fit
                    + role_fit
                    - candidate.distance(current) * 0.026
                    - candidate.distance(home) * 0.010
                    - {
                        let relief =
                            self.positional_shape_exception_relief_for_player_target(me, candidate);
                        self.teammate_occupied_space_penalty_at(
                            me.team,
                            candidate,
                            Some(me.id),
                            relief,
                        ) * 0.62
                            + self.vertical_lane_penalty_for_player_target(me, candidate, relief)
                                * 0.40
                            + self.role_line_penalty_for_player_target(me, candidate, relief) * 0.34
                    };
                (candidate, score)
            })
            .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
            .map(|(candidate, _)| self.clamp_to_role_position(player_id, candidate, home, false))
    }

    fn center_back_screen_y(&self, team: Team) -> Option<f64> {
        let mut total = 0.0;
        let mut count = 0usize;
        for player in self
            .players
            .iter()
            .filter(|player| player.team == team && player.role == PlayerRole::Defender)
            .filter(|player| !self.is_wide_defender(player))
        {
            total += self.player_snapshot_position(player).y;
            count += 1;
        }
        if count == 0 {
            return None;
        }
        Some((total / count as f64 + team.attack_dir() * 18.0).clamp(0.0, self.field_length))
    }

    fn defensive_midfield_center_back_cover_score(&self, team: Team) -> f64 {
        let center_backs = self
            .players
            .iter()
            .filter(|player| player.team == team && player.role == PlayerRole::Defender)
            .filter(|player| !self.is_wide_defender(player))
            .filter_map(|player| {
                let position = self.player_position(player.id)?;
                vec2_is_finite(position).then_some(position)
            })
            .collect::<Vec<_>>();
        if center_backs.is_empty() {
            return 0.0;
        }
        let center_back_centroid = center_backs
            .iter()
            .copied()
            .fold(Vec2::zero(), |sum, position| sum + position)
            / center_backs.len() as f64;

        self.players
            .iter()
            .filter(|player| player.team == team && player.role == PlayerRole::Midfielder)
            .filter_map(|player| {
                let position = self.player_position(player.id)?;
                if !vec2_is_finite(position) {
                    return None;
                }
                let nearest_center_back = center_backs
                    .iter()
                    .map(|center_back| position.distance(*center_back))
                    .fold(f64::INFINITY, f64::min);
                let distance_fit = logistic_probability(
                    (DEFENSIVE_MID_CENTER_BACK_COVER_RADIUS_YARDS - nearest_center_back) / 2.4,
                );
                let screen_depth = (position.y - center_back_centroid.y) * team.attack_dir();
                let screen_fit = logistic_probability((screen_depth + 1.5) / 2.6)
                    * logistic_probability((14.0 - screen_depth) / 3.6);
                let defensive_fit = soccer_lp_clamped(
                    (player.preferences.defensive_mindedness
                        - player.preferences.offensive_mindedness
                        + 0.18)
                        / 0.58,
                    0.0,
                    1.0,
                    0.0,
                );
                let score = distance_fit * (0.55 + screen_fit * 0.45) * defensive_fit;
                score.is_finite().then_some(score)
            })
            .fold(0.0, f64::max)
            .clamp(0.0, 1.0)
    }

    fn wingback_extra_push_yards(&self, player: &PlayerSnapshot) -> f64 {
        if self.possession_team() != Some(player.team) || !self.is_wide_defender(player) {
            return 0.0;
        }
        let directive = self.tactical_directive(player.team);
        let forward_space = self.forward_dribble_space_yards(player.id);
        let space_fit = smoothstep_unit((forward_space - 5.0) / 22.0);
        let cover_fit = self.defensive_midfield_center_back_cover_score(player.team);
        let risk_tolerance = soccer_lp_clamped(directive.risk_tolerance, 0.0, 1.0, 0.50);
        let center_back_advance_probability =
            (0.34 + risk_tolerance * 0.14 + space_fit * 0.08).clamp(0.18, 0.68);
        let wingback_advance_probability = probability_with_odds_multiplier(
            center_back_advance_probability,
            WINGBACK_ADVANCE_ODDS_MULTIPLIER,
        );
        let draw = deterministic_unit_draw(self.tick, player.id, 337)
            + deterministic_unit_draw(self.tick, player.id, 353)
            - 1.0;
        let mean_push = 1.4
            + wingback_advance_probability * 4.6
            + space_fit * 3.4
            + cover_fit * 3.2
            + risk_tolerance * 1.1;
        let spread = 0.85 + (1.0 - space_fit) * 0.55 + (1.0 - cover_fit) * 0.35;
        soccer_lp_clamped(mean_push + draw * spread, 0.0, 12.5, 0.0)
    }

    fn defender_possession_line_y(&self, player: &PlayerSnapshot, home: Vec2) -> f64 {
        let team = player.team;
        let wide = self.is_wide_defender(player);
        let wingback_push = if wide {
            self.wingback_extra_push_yards(player)
        } else {
            0.0
        };
        let base_gap = if wide { 15.0 } else { 21.0 };
        let base_home_push = if wide { 23.0 } else { 19.0 };
        let behind_ball =
            self.ball.position.y - team.attack_dir() * (base_gap - wingback_push * 0.55).max(8.0);
        let home_push = home.y + team.attack_dir() * (base_home_push + wingback_push);
        match team {
            Team::Home => behind_ball.max(home_push),
            Team::Away => behind_ball.min(home_push),
        }
        .clamp(0.0, self.field_length)
    }

    fn apply_defender_possession_line_floor(
        &self,
        player: &PlayerSnapshot,
        home: Vec2,
        mut target: Vec2,
    ) -> Vec2 {
        if self.possession_team() != Some(player.team) || player.role != PlayerRole::Defender {
            return target;
        }
        let line_y = self.defender_possession_line_y(player, home);
        target.y = match player.team {
            Team::Home => target.y.max(line_y),
            Team::Away => target.y.min(line_y),
        };
        self.clamp_to_role_position(player.id, target, home, false)
    }

    fn defender_open_space_depth_yards(
        &self,
        player: &PlayerSnapshot,
        own_half_possession: bool,
    ) -> f64 {
        let wide = self.is_wide_defender(player);
        let base = match (wide, own_half_possession) {
            (true, true) => 13.0,
            (true, false) => 18.0,
            (false, true) => 9.0,
            (false, false) => 11.0,
        };
        if wide {
            base + self.wingback_extra_push_yards(player)
                * if own_half_possession { 0.45 } else { 0.62 }
        } else {
            base
        }
    }

    pub fn open_space_for(&self, player_id: usize, home: Vec2) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        let me_position = self.player_snapshot_position(me);
        let directive = self.tactical_directive(me.team);
        let spread_draw = deterministic_unit_draw(self.tick, player_id, 83) * 2.0 - 1.0;
        let width_scale = (directive.width_yards / (self.field_width * 0.62)
            * (1.0 + spread_draw * 0.055))
            .clamp(0.65, 1.35);
        let depth_scale = (directive.support_depth_yards / 11.0).clamp(0.65, 1.65);
        let possession = self.possession_team() == Some(me.team);
        let own_half_possession =
            possession && pass_origin_in_own_half(me.team, self.ball.position, self.field_length);
        let tendency = me.preferences.offensive_mindedness - me.preferences.defensive_mindedness;
        let role_depth = match me.role {
            PlayerRole::Goalkeeper => -8.0,
            PlayerRole::Defender => self.defender_open_space_depth_yards(me, own_half_possession),
            PlayerRole::Midfielder if own_half_possession => {
                directive.support_depth_yards + 7.0 + tendency * 8.0
            }
            PlayerRole::Midfielder => directive.support_depth_yards + 3.0 + tendency * 10.0,
            PlayerRole::Forward if own_half_possession => directive.support_depth_yards + 8.0,
            PlayerRole::Forward => directive.support_depth_yards + 5.0,
        };
        let base = if possession {
            let possession_width_fit =
                (directive.width_yards / self.field_width.max(1.0)).clamp(0.45, 0.96);
            let home_anchor = (0.58 + (possession_width_fit - 0.62) * 0.78 + spread_draw * 0.035)
                .clamp(0.50, 0.82);
            let ball_anchor = 1.0 - home_anchor;
            Vec2::new(
                home.x * home_anchor + self.ball.position.x * ball_anchor,
                self.ball.position.y + role_depth * me.team.attack_dir(),
            )
        } else {
            home
        };
        let mut best = base.clamp_to_pitch(self.field_width, self.field_length);
        let mut best_score = f64::NEG_INFINITY;
        for dx in [-22.0, -13.0, -6.0, 0.0, 6.0, 13.0, 22.0] {
            for dy in [-8.0, 0.0, 7.0, 14.0, 22.0, 30.0] {
                let raw_p = Vec2::new(
                    base.x + dx * width_scale,
                    base.y + dy * depth_scale * me.team.attack_dir(),
                )
                .clamp_to_pitch(self.field_width, self.field_length);
                let p = if possession
                    && self.ball.holder != Some(player_id)
                    && me.role != PlayerRole::Goalkeeper
                {
                    self.support_target_with_min_upfield_slope(me_position, raw_p, me.team)
                } else {
                    raw_p
                };
                let forward = (p.y - me_position.y) * me.team.attack_dir();
                let forward_from_ball = (p.y - self.ball.position.y) * me.team.attack_dir();
                let lateral = (p.x - me_position.x).abs();
                let diagonal_support_bonus = if possession && lateral > 3.0 {
                    let required_forward = lateral * SUPPORT_MIN_UPFIELD_PER_LATERAL_YARD;
                    if forward >= required_forward {
                        0.55 + (forward / required_forward.max(1.0)).clamp(0.0, 2.0) * 0.18
                    } else {
                        -1.4
                    }
                } else {
                    0.0
                };
                let lane_bonus = if self.clear_line(self.ball.position, p, me.team.other(), 2.0) {
                    1.8
                } else {
                    -1.2
                };
                let offside_penalty = if self.position_would_be_offside(me.team, p) {
                    14.0
                } else {
                    0.0
                };
                let occupancy = self.candidate_occupancy_at(me.team, p, Some(me.id));
                let spacing_bonus = if possession {
                    occupancy.team_spacing_score(TeamSpacingMode::InPossession)
                        * (1.0 + self.possession_spacing_weight(me.team) * 1.5)
                } else {
                    0.0
                };
                let designated_lane_side = (home.x - self.field_width * 0.5).signum();
                let candidate_lane_side = (p.x - self.field_width * 0.5).signum();
                let correct_side = designated_lane_side == 0.0
                    || candidate_lane_side == 0.0
                    || designated_lane_side == candidate_lane_side;
                let width_possession_bonus = if possession && me.role != PlayerRole::Goalkeeper {
                    let lane_width = ((p.x - self.field_width * 0.5).abs()
                        / (self.field_width * 0.5).max(1.0))
                    .clamp(0.0, 1.0);
                    let home_lane_fit = (1.0
                        - (p.x - home.x).abs() / (self.field_width * 0.42).max(1.0))
                    .clamp(0.0, 1.0);
                    (lane_width * 0.38 + home_lane_fit * 0.34)
                        * if correct_side { 1.0 } else { 0.46 }
                } else {
                    0.0
                };
                let movement_relief =
                    self.positional_shape_exception_relief_for_player_target(me, p);
                let lane_position_penalty =
                    self.vertical_lane_penalty_for_player_target(me, p, movement_relief);
                let teammate_occupation_penalty =
                    occupancy.teammate_occupied_space_penalty(movement_relief);
                let line_shape_penalty =
                    self.role_line_penalty_for_player_target(me, p, movement_relief);
                let score = occupancy.open_space_score
                    + forward.max(-4.0) * (0.04 + directive.risk_tolerance * 0.08)
                    + forward_from_ball.clamp(-6.0, 28.0)
                        * (0.08 + directive.risk_tolerance * 0.09)
                    - (forward_from_ball - role_depth).abs() * 0.035
                    - p.distance(home) * 0.010
                    + lane_bonus
                    + diagonal_support_bonus
                    + spacing_bonus
                    + width_possession_bonus
                    - offside_penalty
                    - lane_position_penalty
                    - teammate_occupation_penalty
                    - line_shape_penalty;
                if score > best_score {
                    best = p;
                    best_score = score;
                }
            }
        }
        best
    }

    fn forward_support_context_for(
        &self,
        player_id: usize,
        visible_pass_targets: &[usize],
    ) -> ForwardSupportContext {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return ForwardSupportContext {
                teammates_ahead: 0,
                visible_forward_pass_options: 0,
                best_forward_pass_receiver_openness: 0.0,
                nearest_forward_teammate_distance_yards: 0.0,
            };
        };
        let current = self.player_snapshot_position(me);
        let mut teammates_ahead = 0usize;
        let mut nearest_forward_teammate_distance_yards = f64::INFINITY;
        for player in self
            .players
            .iter()
            .filter(|player| player.team == me.team && player.id != me.id)
            .filter(|player| player.role != PlayerRole::Goalkeeper)
        {
            let position = self.player_snapshot_position(player);
            let forward = (position.y - current.y) * me.team.attack_dir();
            if forward > 1.25 {
                teammates_ahead += 1;
                nearest_forward_teammate_distance_yards =
                    nearest_forward_teammate_distance_yards.min(current.distance(position));
            }
        }

        let mut visible_forward_pass_options = 0usize;
        let mut best_forward_pass_receiver_openness = 0.0f64;
        for target_id in visible_pass_targets {
            let Some(target) = self.players.iter().find(|player| player.id == *target_id) else {
                continue;
            };
            let target_position = self.player_snapshot_position(target);
            let forward = (target_position.y - current.y) * me.team.attack_dir();
            if forward <= 1.25 {
                continue;
            }
            visible_forward_pass_options += 1;
            let quality = pass_target_quality_for_snapshot(
                self,
                me,
                current,
                target,
                target_position,
                PassFlight::Floor,
            );
            best_forward_pass_receiver_openness =
                best_forward_pass_receiver_openness.max(quality.receiver_openness);
        }

        ForwardSupportContext {
            teammates_ahead,
            visible_forward_pass_options,
            best_forward_pass_receiver_openness,
            nearest_forward_teammate_distance_yards: if nearest_forward_teammate_distance_yards
                .is_finite()
            {
                nearest_forward_teammate_distance_yards
            } else {
                self.field_length
            },
        }
    }

    fn teammate_ahead_count_for(&self, player_id: usize) -> usize {
        self.forward_support_context_for(player_id, &[])
            .teammates_ahead
    }

    pub fn striker_hold_up_flank_target_for(&self, player_id: usize) -> Option<Vec2> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if self.ball.holder != Some(player_id) || me.role != PlayerRole::Forward {
            return None;
        }
        let current = self.player_snapshot_position(me);
        let yards_to_goal = (me.team.goal_y(self.field_length) - current.y).abs();
        if yards_to_goal <= STRIKER_HOLD_UP_MIN_GOAL_DISTANCE_YARDS {
            return None;
        }
        if self.teammate_ahead_count_for(player_id) > 0 {
            return None;
        }
        let center_x = self.field_width * 0.5;
        let nearest_defender = self.nearest_opponent_at(me.team, current);
        let flank_sign = if let Some((_, defender_position, defender_distance)) = nearest_defender {
            if defender_distance <= 6.5 && (defender_position.x - current.x).abs() > 0.4 {
                if defender_position.x >= current.x {
                    -1.0
                } else {
                    1.0
                }
            } else if current.x <= center_x {
                -1.0
            } else {
                1.0
            }
        } else if current.x <= center_x {
            -1.0
        } else {
            1.0
        };
        let edge_buffer = 5.0;
        let safe_sign = if current.x <= edge_buffer {
            1.0
        } else if current.x >= self.field_width - edge_buffer {
            -1.0
        } else {
            flank_sign
        };
        let target = Vec2::new(
            current.x + safe_sign * STRIKER_HOLD_UP_SIDEWAYS_YARDS,
            current.y + me.team.attack_dir() * STRIKER_HOLD_UP_FORWARD_YARDS,
        )
        .clamp_to_pitch(self.field_width, self.field_length);
        Some(target)
    }

    pub fn forward_space_for(&self, player_id: usize, home: Vec2) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        let me_position = self.player_snapshot_position(me);
        let ahead = Vec2::new(
            me_position.x + (self.field_width * 0.5 - me_position.x) * 0.08,
            me_position.y + 9.0 * me.team.attack_dir(),
        );
        self.open_space_for(player_id, ahead)
            .clamp_to_pitch(self.field_width, self.field_length)
    }

    pub fn shot_creation_space_for(&self, player_id: usize, home: Vec2) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        let me_position = self.player_snapshot_position(me);
        let center_x = self.field_width * 0.5;
        let dir = me.team.attack_dir();
        let base = self.forward_space_for(player_id, home);
        let mut best = base;
        let mut best_score = self.shot_creation_score_for(player_id, me, best, home);

        for dx in [-18.0, -12.0, -7.0, -3.0, 0.0, 3.0, 7.0, 12.0, 18.0] {
            for dy in [4.0, 8.0, 12.0, 16.0, 22.0, 28.0] {
                let raw = Vec2::new(me_position.x + dx, me_position.y + dy * dir);
                let central_pull = if (raw.y - self.field_length * 0.5) * dir > 8.0 {
                    0.34
                } else {
                    0.16
                };
                let candidate = Vec2::new(
                    raw.x * (1.0 - central_pull) + center_x * central_pull,
                    raw.y,
                )
                .clamp_to_pitch(self.field_width, self.field_length);
                let score = self.shot_creation_score_for(player_id, me, candidate, home);
                if score > best_score {
                    best = candidate;
                    best_score = score;
                }
            }
        }
        best.clamp_to_pitch(self.field_width, self.field_length)
    }

    pub fn side_step_dribble_kind_for(&self, player_id: usize) -> DribbleMoveKind {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return DribbleMoveKind::LeftCut;
        };
        let current = self.player_snapshot_position(me);
        let Some((_, defender_position, _)) = self.nearest_opponent_at(me.team, current) else {
            return DribbleMoveKind::LeftCut;
        };
        let away_x_sign = if defender_position.x >= current.x {
            -1.0
        } else {
            1.0
        };
        let left_x_sign = -me.team.attack_dir();
        if (left_x_sign - away_x_sign).abs() < f64::EPSILON {
            DribbleMoveKind::LeftCut
        } else {
            DribbleMoveKind::RightCut
        }
    }

    pub fn dribble_move_target_for(
        &self,
        player_id: usize,
        home: Vec2,
        kind: DribbleMoveKind,
    ) -> Vec2 {
        let touch = self.deterministic_dribble_touch_decision_for(player_id, kind);
        self.dribble_move_target_for_touch(player_id, home, kind, touch)
    }

    pub fn choose_dribble_touch_decision_for(
        &self,
        player_id: usize,
        kind: DribbleMoveKind,
        rng: &mut SeededRandom,
    ) -> DribbleTouchDecision {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return DribbleTouchDecision::default();
        };
        let bucket = choose_dribble_touch_bucket(kind, rng);
        let distance = self.dribble_touch_distance_for(me, kind, bucket, rng.next_float());
        DribbleTouchDecision::new(bucket, distance)
    }

    pub fn deterministic_dribble_touch_decision_for(
        &self,
        player_id: usize,
        kind: DribbleMoveKind,
    ) -> DribbleTouchDecision {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return DribbleTouchDecision::default();
        };
        let bucket = deterministic_dribble_touch_bucket(self.tick, player_id, kind);
        let distance = self.dribble_touch_distance_for(
            me,
            kind,
            bucket,
            deterministic_unit_draw(self.tick, player_id, 29),
        );
        DribbleTouchDecision::new(bucket, distance)
    }

    fn dribble_touch_distance_for(
        &self,
        player: &PlayerSnapshot,
        kind: DribbleMoveKind,
        bucket: u8,
        draw01: f64,
    ) -> f64 {
        let position = self.player_snapshot_position(player);
        let nearest_opponent_distance = self
            .nearest_opponent_at(player.team, position)
            .map(|(_, _, distance)| distance)
            .unwrap_or(36.0);
        let pressure = pressure_from_nearest_distance(nearest_opponent_distance);
        let forward_space = self.forward_dribble_space_yards(player.id);
        let (lateral_component, forward_component) = dribble_touch_bucket_components(bucket);
        let open_grass = (forward_space / 18.0).clamp(0.0, 1.0);
        let dribbling = ability01(player.skills.dribbling);
        let first_touch = ability01(player.skills.first_touch);
        let acceleration = ability01(player.skills.acceleration);
        let control = dribbling * 0.48 + first_touch * 0.22 + acceleration * 0.30;
        let forward_bonus = forward_component.max(0.0) * (0.55 + open_grass * 0.95);
        let backward_penalty = (-forward_component).max(0.0) * 0.48;
        let kind_bonus = match dribble_final_cut_kind(kind) {
            DribbleMoveKind::CarryForward => {
                forward_component.max(0.0) * (0.42 + open_grass * 0.48) + (1.0 - pressure) * 0.18
            }
            DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight => {
                lateral_component.abs() * 0.34
                    + forward_component.max(0.0) * 0.24
                    + (1.0 - pressure) * 0.14
            }
            DribbleMoveKind::ProtectBall => pressure * 0.26 - forward_component.max(0.0) * 0.18,
            DribbleMoveKind::LeftCut | DribbleMoveKind::RightCut => {
                lateral_component.abs() * 0.42
                    + pressure * 0.18
                    + if matches!(
                        kind,
                        DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft
                    ) {
                        pressure * 0.16
                    } else {
                        0.0
                    }
            }
            DribbleMoveKind::Nutmeg => forward_component.max(0.0) * 0.35 + pressure * 0.36,
            DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft => {
                unreachable!("feints are resolved into their final cut before touch distance")
            }
        };
        let beat_defender_bonus = if pressure > 0.40 && forward_component > 0.05 {
            0.55 + pressure * 0.85 + acceleration * 0.68 + draw01.clamp(0.0, 1.0) * 1.15
        } else {
            0.0
        };
        let mut distance = 0.78
            + control * 0.86
            + open_grass * 1.05
            + forward_bonus
            + kind_bonus
            + beat_defender_bonus
            + draw01.clamp(0.0, 1.0) * 0.52
            - backward_penalty;
        if forward_component < -0.20 {
            distance *= 0.70;
        } else if forward_component.abs() <= 0.20 {
            distance *= 0.82;
        }
        let cap = if forward_component > 0.20 {
            (forward_space + PLAYER_CONTROL_RADIUS_YARDS * 2.1)
                .max(3.65)
                .min(DRIBBLE_MAX_TOUCH_YARDS)
        } else if forward_component < -0.20 {
            3.10
        } else {
            3.80
        };
        if kind == DribbleMoveKind::ProtectBall {
            return distance.clamp(0.62, 1.45);
        }
        if kind == DribbleMoveKind::CarryForward {
            return distance.clamp(1.05, cap.max(3.2).min(DRIBBLE_MAX_TOUCH_YARDS));
        }
        if matches!(
            kind,
            DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight
        ) {
            return distance.clamp(0.95, cap.max(2.8).min(4.35));
        }
        distance.clamp(DRIBBLE_MIN_TOUCH_YARDS, cap)
    }

    fn carry_forward_direction_for(&self, player: &PlayerSnapshot, current: Vec2) -> Vec2 {
        let straight = Vec2::new(0.0, player.team.attack_dir());
        let goal = Vec2::new(
            self.field_width * 0.5,
            player.team.goal_y(self.field_length),
        );
        let yards_to_goal = (goal.y - current.y).abs();
        if yards_to_goal > GOAL_APPROACH_CARRY_YARDS {
            return straight;
        }
        let to_goal = (goal - current).normalized();
        if to_goal.len() <= 1e-9 || to_goal.dot(straight) <= 0.12 {
            return straight;
        }
        let approach_fit = ((GOAL_APPROACH_CARRY_YARDS - yards_to_goal)
            / (GOAL_APPROACH_CARRY_YARDS - TEAMMATE_MUST_SHOOT_YARDS).max(1.0))
        .clamp(0.0, 1.0);
        let lateral_fit = ((current.x - self.field_width * 0.5).abs()
            / (self.field_width * 0.5).max(1.0))
        .clamp(0.0, 1.0);
        let goal_blend = (0.12 + approach_fit * 0.72 + lateral_fit * 0.42).clamp(0.0, 0.94);
        (straight * (1.0 - goal_blend) + to_goal * goal_blend).normalized()
    }

    pub fn dribble_move_target_for_touch(
        &self,
        player_id: usize,
        home: Vec2,
        kind: DribbleMoveKind,
        touch: DribbleTouchDecision,
    ) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        let current = self.player_snapshot_position(me);
        let nearest_defender = self.nearest_opponent_at(me.team, current);
        let direction = match kind {
            DribbleMoveKind::CarryForward => self.carry_forward_direction_for(me, current),
            DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight => {
                let outward_x = match kind {
                    DribbleMoveKind::CarryOutLeft => -1.0,
                    DribbleMoveKind::CarryOutRight => 1.0,
                    _ => unreachable!("only carry-out variants use diagonal carry-out geometry"),
                };
                Vec2::new(outward_x * 0.52, me.team.attack_dir() * 0.78).normalized()
            }
            DribbleMoveKind::ProtectBall => nearest_defender
                .map(|(_, defender_position, _)| {
                    let away = (current - defender_position).normalized();
                    (away * 0.86 + Vec2::new(0.0, me.team.attack_dir()) * 0.18).normalized()
                })
                .unwrap_or_else(|| Vec2::new(0.0, me.team.attack_dir())),
            _ => touch.direction_for_team(me.team),
        };
        let direction = self.attacking_dribble_goal_drive_direction(me, current, direction, kind);
        let mut target = current + direction * touch.distance_yards;
        if let Some((_, defender_position, defender_distance)) = nearest_defender {
            if kind == DribbleMoveKind::Nutmeg && defender_distance <= 5.6 {
                let through_target = Vec2::new(
                    current.x * 0.70 + defender_position.x * 0.30,
                    current.y
                        + (touch.distance_yards + DRIBBLE_NUTMEG_FORWARD_YARDS * 0.30)
                            * me.team.attack_dir(),
                );
                target = target * 0.72 + through_target * 0.28;
            }
        } else if touch.distance_yards <= DRIBBLE_TOUCH_LEAD_YARDS + 0.10 {
            target = self.shot_creation_space_for(player_id, home);
        }

        if let Some(goalmouth_target) =
            self.goalmouth_carry_target_for_touch(player_id, current, target, kind, touch)
        {
            target = goalmouth_target;
        }

        target.clamp_to_pitch(self.field_width, self.field_length)
    }

    fn attacking_dribble_goal_drive_direction(
        &self,
        player: &PlayerSnapshot,
        current: Vec2,
        base_direction: Vec2,
        kind: DribbleMoveKind,
    ) -> Vec2 {
        let base_direction = base_direction.normalized();
        if base_direction.len() <= 1e-6 {
            return Vec2::new(0.0, player.team.attack_dir());
        }
        if player.role == PlayerRole::Goalkeeper
            || self.ball.holder != Some(player.id)
            || matches!(dribble_final_cut_kind(kind), DribbleMoveKind::ProtectBall)
        {
            return base_direction;
        }

        let goal_y = player.team.goal_y(self.field_length);
        let yards_to_goal = (goal_y - current.y).abs();
        if yards_to_goal > GOAL_APPROACH_CARRY_YARDS || yards_to_goal <= 2.0 {
            return base_direction;
        }

        let attack_dir = player.team.attack_dir();
        let pocket_depth = attacking_dribble_shooting_pocket_depth(yards_to_goal);
        let pocket_y = goal_y - attack_dir * pocket_depth;
        let goal_drive = Vec2::new(self.field_width * 0.5, pocket_y)
            .clamp_to_pitch(self.field_width, self.field_length)
            - current;
        if goal_drive.len() <= 1e-6 {
            return base_direction;
        }

        let final_kind = dribble_final_cut_kind(kind);
        let kind_weight = match final_kind {
            DribbleMoveKind::CarryForward => 1.0,
            DribbleMoveKind::Nutmeg => 0.86,
            DribbleMoveKind::LeftCut | DribbleMoveKind::RightCut => 0.62,
            DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight => 0.46,
            DribbleMoveKind::ProtectBall
            | DribbleMoveKind::FakeLeftCutRight
            | DribbleMoveKind::FakeRightCutLeft => 0.0,
        };
        if kind_weight <= 0.0 {
            return base_direction;
        }

        let range_fit = ((GOAL_APPROACH_CARRY_YARDS - yards_to_goal) / GOAL_APPROACH_CARRY_YARDS)
            .clamp(0.0, 1.0);
        let center_x = self.field_width * 0.5;
        let central_need = ((current.x - center_x).abs() / center_x.max(1.0)).clamp(0.0, 1.0);
        let bend = ((0.28 + range_fit * 0.50 + central_need * 0.36) * kind_weight).clamp(0.0, 0.92);
        if bend <= 0.04 {
            return base_direction;
        }

        (base_direction * (1.0 - bend) + goal_drive.normalized() * bend).normalized()
    }

    fn goalmouth_carry_target_for_touch(
        &self,
        player_id: usize,
        current: Vec2,
        base_target: Vec2,
        kind: DribbleMoveKind,
        touch: DribbleTouchDecision,
    ) -> Option<Vec2> {
        let me = self.players.iter().find(|p| p.id == player_id)?;
        if me.role == PlayerRole::Goalkeeper || kind == DribbleMoveKind::ProtectBall {
            return None;
        }
        let attack_dir = me.team.attack_dir();
        if (current.y - self.field_length * 0.5) * attack_dir < 0.0 {
            return None;
        }
        let goal_y = me.team.goal_y(self.field_length);
        let yards_to_goal = (goal_y - current.y).abs();
        let activation_yards = goal_approach_carry_window_yards(me.role);
        if yards_to_goal > activation_yards {
            return None;
        }

        let shooting_pocket_depth = attacking_dribble_shooting_pocket_depth(yards_to_goal);
        let shooting_pocket = Vec2::new(
            self.field_width * 0.5,
            goal_y - attack_dir * shooting_pocket_depth,
        )
        .clamp_to_pitch(self.field_width, self.field_length);
        let to_shooting_pocket = shooting_pocket - current;
        if to_shooting_pocket.len() <= 0.45 {
            let center_x = self.field_width * 0.5;
            let lateral_sign = if (current.x - center_x).abs() > 1.2 {
                (center_x - current.x).signum()
            } else {
                self.nearest_opponent_at(me.team, current)
                    .map(|(_, defender_position, _)| {
                        if defender_position.x >= current.x {
                            -1.0
                        } else {
                            1.0
                        }
                    })
                    .unwrap_or_else(|| if me.id % 2 == 0 { -1.0 } else { 1.0 })
            };
            let lateral_step = touch.distance_yards.clamp(1.15, 3.4) * 0.82;
            let held_y = if (current.y - shooting_pocket.y) * attack_dir > 0.25 {
                current.y - attack_dir * 0.55
            } else {
                current.y
            };
            return Some(
                Vec2::new(current.x + lateral_sign * lateral_step, held_y)
                    .clamp_to_pitch(self.field_width, self.field_length),
            );
        }
        let staging_buffer = if yards_to_goal <= TEAMMATE_MUST_SHOOT_YARDS {
            5.0
        } else {
            7.0
        };
        let step_yards = touch
            .distance_yards
            .clamp(1.15, DRIBBLE_MAX_TOUCH_YARDS)
            .min((yards_to_goal - staging_buffer).max(1.6));
        let goal_step = current + to_shooting_pocket.normalized() * step_yards;
        let final_kind = dribble_final_cut_kind(kind);
        let goal_blend = match final_kind {
            DribbleMoveKind::CarryForward | DribbleMoveKind::Nutmeg => 0.96,
            DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight => 0.90,
            DribbleMoveKind::LeftCut | DribbleMoveKind::RightCut => 0.82,
            DribbleMoveKind::ProtectBall => return None,
            DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft => 0.82,
        };
        let mut target = goal_step * goal_blend + base_target * (1.0 - goal_blend);
        let center_x = self.field_width * 0.5;
        let lateral_fit =
            ((current.x - center_x).abs() / (self.field_width * 0.25).max(1.0)).clamp(0.0, 1.0);
        let byline_risk_fit = ((TEAMMATE_MUST_SHOOT_YARDS - yards_to_goal)
            / TEAMMATE_MUST_SHOOT_YARDS)
            .clamp(0.0, 1.0);
        if yards_to_goal <= STRIKER_SHOT_WINDOW_YARDS {
            let center_pull =
                (0.36 + lateral_fit * 0.18 + byline_risk_fit * 0.10).clamp(0.36, 0.64);
            target.x = target.x * (1.0 - center_pull) + center_x * center_pull;
        }

        let goalmouth_y = goal_y - attack_dir * shooting_pocket_depth;
        if attack_dir > 0.0 {
            target.y = if current.y < goalmouth_y - 0.35 {
                target.y.min(goalmouth_y).max(current.y + 0.55)
            } else {
                target.y.min(current.y - 0.35).max(goalmouth_y)
            };
        } else {
            target.y = if current.y > goalmouth_y + 0.35 {
                target.y.max(goalmouth_y).min(current.y - 0.55)
            } else {
                target.y.max(current.y + 0.35).min(goalmouth_y)
            };
        }
        if byline_risk_fit * lateral_fit > 0.22 {
            let max_goalward_step =
                (touch.distance_yards * (0.16 + (1.0 - lateral_fit) * 0.14)).clamp(0.35, 1.30);
            let goalward_step = (target.y - current.y) * attack_dir;
            if goalward_step > max_goalward_step {
                target.y = current.y + attack_dir * max_goalward_step;
            }
        }
        Some(target.clamp_to_pitch(self.field_width, self.field_length))
    }

    pub fn side_step_dribble_target_for(&self, player_id: usize, home: Vec2) -> Vec2 {
        let kind = self.side_step_dribble_kind_for(player_id);
        let bucket = match dribble_final_cut_kind(kind) {
            DribbleMoveKind::CarryForward
            | DribbleMoveKind::CarryOutLeft
            | DribbleMoveKind::CarryOutRight
            | DribbleMoveKind::ProtectBall => 0,
            DribbleMoveKind::LeftCut => 9,
            DribbleMoveKind::RightCut => 3,
            DribbleMoveKind::Nutmeg => 0,
            DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft => 0,
        };
        self.dribble_move_target_for_touch(
            player_id,
            home,
            kind,
            DribbleTouchDecision::new(bucket, 1.05),
        )
    }

    fn anticipated_pass_reception_point(
        &self,
        passer_id: usize,
        target_id: usize,
        flight: PassFlight,
        speed_yps: f64,
    ) -> Option<Vec2> {
        let passer = self.players.iter().find(|p| p.id == passer_id)?;
        let target = self.players.iter().find(|p| p.id == target_id)?;
        if passer.team != target.team {
            return None;
        }
        let passer_position = self.player_snapshot_position(passer);
        let target_position = self.player_snapshot_position(target);
        let pass_distance = passer_position.distance(target_position);
        let flight_time = (pass_distance / speed_yps.max(1.0)).clamp(0.18, 2.6);
        let anticipation_skill = (ability01(passer.skills.passing_completion_rate) * 0.48
            + ability01(passer.skills.passing) * 0.28
            + ability01(passer.skills.vision) * 0.24)
            .clamp(0.05, 0.99);
        let receiver_speed = player_top_speed_yps(target.role, &target.skills)
            * if flight.is_aerial() { 0.78 } else { 0.62 };
        let max_run = receiver_speed * flight_time;
        let team_has_possession = self.possession_team() == Some(target.team);
        let forward_bias = if team_has_possession && target.role != PlayerRole::Goalkeeper {
            match target.role {
                PlayerRole::Forward => 10.0,
                PlayerRole::Midfielder => 7.5,
                PlayerRole::Defender => 4.0,
                PlayerRole::Goalkeeper => 0.0,
            }
        } else {
            0.0
        };
        let center_x = self.field_width * 0.5;
        let wide_bias = if team_has_possession && self.is_wide_midfielder(target) {
            let touchline_x = if target.home_position.x <= center_x {
                WIDE_OUTLET_TOUCHLINE_BUFFER_YARDS
            } else {
                self.field_width - WIDE_OUTLET_TOUCHLINE_BUFFER_YARDS
            };
            (touchline_x - target_position.x).clamp(-8.0, 8.0)
        } else {
            0.0
        };
        let support_target = Vec2::new(
            target_position.x + target.velocity.x * flight_time * 0.45 + wide_bias,
            target_position.y
                + target.velocity.y * flight_time * 0.30
                + target.team.attack_dir() * forward_bias,
        )
        .clamp_to_pitch(self.field_width, self.field_length);
        let support_delta = support_target - target_position;
        let led_support = if support_delta.len() <= max_run {
            support_target
        } else {
            target_position + support_delta.normalized() * max_run
        };
        let movement_led =
            target_position + target.velocity * flight_time * (0.48 + anticipation_skill * 0.36);
        let openness = pass_receiver_openness_for_snapshots_with_teammates(
            &self.players,
            passer.team,
            led_support,
            Some(target.id),
        );
        let base_support_weight = if self.is_wide_midfielder(target) && openness > 0.58 {
            0.70
        } else if openness > 0.45 {
            0.58
        } else {
            0.42
        };
        let support_weight =
            (base_support_weight * (0.86 + anticipation_skill * 0.18)).clamp(0.32, 0.74);
        let blended = led_support * support_weight + movement_led * (1.0 - support_weight);
        Some(
            led_pass_target_for_receiver(
                passer_position,
                blended,
                target.velocity,
                speed_yps,
                anticipation_skill,
                openness,
                passer.team,
                self.field_width,
                self.field_length,
            )
            .clamp_to_pitch(self.field_width, self.field_length),
        )
    }

    fn shot_creation_score_for(
        &self,
        player_id: usize,
        player: &PlayerSnapshot,
        candidate: Vec2,
        home: Vec2,
    ) -> f64 {
        let current = self.player_snapshot_position(player);
        let forward = (candidate.y - current.y) * player.team.attack_dir();
        let pass_lane = if self.clear_line(self.ball.position, candidate, player.team.other(), 2.2)
        {
            0.62
        } else {
            -0.72
        };
        let offside_penalty = if self.ball.holder != Some(player_id)
            && self.position_would_be_offside(player.team, candidate)
        {
            12.0
        } else {
            0.0
        };
        let centrality = (1.0
            - ((candidate.x - self.field_width * 0.5).abs() / (self.field_width * 0.5)))
            .clamp(0.0, 1.0);
        self.shooting_window_score_at(player, candidate) * 5.4
            + self.space_score_at(candidate, player.team) * 0.060
            + forward.clamp(-4.0, 24.0) * 0.090
            + centrality * 0.70
            + pass_lane
            - candidate.distance(current) * 0.022
            - candidate.distance(home) * 0.006
            - offside_penalty
    }

    fn shooting_window_score_at(&self, player: &PlayerSnapshot, position: Vec2) -> f64 {
        let goal = Vec2::new(
            self.field_width * 0.5,
            player.team.goal_y(self.field_length),
        );
        let shot_speed = shot_speed_yps_from_power(
            shot_power_for_skill(ability01(player.skills.shooting)),
            &player.skills,
        );
        let shot_block_probability =
            shot_block_assessment_for_snapshot(self, position, player.team, shot_speed, false)
                .map(|assessment| assessment.probability)
                .unwrap_or(0.0);
        let yards_to_goal = (goal.y - position.y).abs();
        let nearest_opponent_distance = self
            .players
            .iter()
            .filter(|other| other.team == player.team.other())
            .map(|other| self.player_snapshot_position(other).distance(position))
            .fold(36.0, f64::min)
            .min(36.0);
        let pressure = pressure_from_nearest_distance(nearest_opponent_distance);
        let on_frame = shot_on_frame_probability(
            self.goal_width,
            ability01(player.skills.shooting),
            pressure,
            yards_to_goal,
            self.goal_angle_degrees(position, player.team),
            shot_block_probability,
        );
        let beat_keeper = shot_beat_goalkeeper_probability_for_snapshot(self, player, position)
            * (1.0 - shot_block_probability * 0.70).clamp(0.20, 1.0);
        let centrality = (1.0
            - ((position.x - self.field_width * 0.5).abs() / (self.field_width * 0.5)))
            .clamp(0.0, 1.0);
        let range_shape = (1.0 - (yards_to_goal - 14.0).abs() / 24.0).clamp(0.0, 1.0);
        (on_frame * 0.66 + beat_keeper * 0.38 + centrality * 0.08 + range_shape * 0.07)
            .clamp(0.0, 1.25)
    }

    pub fn forward_dribble_space_yards(&self, player_id: usize) -> f64 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return 0.0;
        };
        let start = self.player_snapshot_position(me);
        let dir = Vec2::new(0.0, me.team.attack_dir());
        let max_space = 30.0_f64
            .min(match me.team {
                Team::Home => self.field_length - start.y,
                Team::Away => start.y,
            })
            .max(0.0);
        let mut nearest_block = max_space;
        for opponent in self.players.iter().filter(|p| p.team == me.team.other()) {
            let position = self.player_snapshot_position(opponent);
            let to_opponent = position - start;
            let forward = to_opponent.dot(dir);
            if forward <= 0.0 || forward > max_space {
                continue;
            }
            let lateral = (to_opponent - dir * forward).len();
            if lateral <= 4.0 {
                nearest_block = nearest_block.min((forward - PLAYER_CONTROL_RADIUS_YARDS).max(0.0));
            }
        }
        nearest_block
    }

    pub fn goal_angle_degrees(&self, position: Vec2, attacking_team: Team) -> f64 {
        let goal_y = attacking_team.goal_y(self.field_length);
        let left_post = Vec2::new(self.field_width * 0.5 - self.goal_width * 0.5, goal_y);
        let right_post = Vec2::new(self.field_width * 0.5 + self.goal_width * 0.5, goal_y);
        angle_between_vectors_degrees(left_post - position, right_post - position)
    }

    pub fn positional_open_space_for(&self, player_id: usize, home: Vec2, roam: bool) -> Vec2 {
        self.attacking_support_movement_for(player_id, home, roam)
            .point
    }

    fn attacking_support_movement_for(
        &self,
        player_id: usize,
        home: Vec2,
        roam: bool,
    ) -> SupportMovementTarget {
        let special_targets = SupportSpecialTargets {
            check_to_ball: self.check_to_ball_target_for(player_id, home),
            in_behind: self.in_behind_run_target_for(player_id),
            wide_outlet: self.wide_possession_outlet_target_for(player_id, home),
            flank_cross_arrival: self.flank_cross_arrival_target_for(player_id, home),
        };
        self.attacking_support_movement_for_with_targets(player_id, home, roam, &special_targets)
    }

    fn attacking_support_movement_for_with_targets(
        &self,
        player_id: usize,
        home: Vec2,
        roam: bool,
        special_targets: &SupportSpecialTargets,
    ) -> SupportMovementTarget {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return SupportMovementTarget {
                point: home,
                action_label: "support-shape",
            };
        };
        let open = self.open_space_for(player_id, home);
        if me.role == PlayerRole::Goalkeeper {
            return SupportMovementTarget {
                point: self.goalkeeper_ball_goal_tracking_target(me.team),
                action_label: "support-shape",
            };
        }
        if self.possession_team() == Some(me.team) && !roam {
            if let Some(target) = special_targets.check_to_ball {
                return SupportMovementTarget {
                    point: self.shape_guarded_support_point(
                        player_id,
                        target,
                        &[open, home],
                        home,
                        roam,
                    ),
                    action_label: "check-to-ball",
                };
            }
            if let Some(target) = special_targets.in_behind {
                return SupportMovementTarget {
                    point: self.shape_guarded_support_point(
                        player_id,
                        target,
                        &[open, home],
                        home,
                        roam,
                    ),
                    action_label: "run-in-behind",
                };
            }
            if let Some(target) = special_targets.flank_cross_arrival {
                return SupportMovementTarget {
                    point: self.shape_guarded_support_point(
                        player_id,
                        target,
                        &[open, home],
                        home,
                        roam,
                    ),
                    action_label: "shot-creation-run",
                };
            }
            let striker_attack = self.striker_holder_in_opponent_half(me.team).is_some();
            let current = self.player_snapshot_position(me);
            let current_wide =
                current.x < self.field_width * 0.30 || current.x > self.field_width * 0.70;
            let overlap_run_preferred = striker_attack
                && current_wide
                && me.role == PlayerRole::Midfielder
                && me.preferences.offensive_mindedness >= me.preferences.defensive_mindedness;
            if !overlap_run_preferred {
                if let Some(target) = special_targets.wide_outlet {
                    return SupportMovementTarget {
                        point: self.shape_guarded_support_point(
                            player_id,
                            target,
                            &[open, home],
                            home,
                            roam,
                        ),
                        action_label: "wide-outlet",
                    };
                }
            }
        }
        if roam {
            return SupportMovementTarget {
                point: self.shape_guarded_support_point(player_id, open, &[home], home, roam),
                action_label: "support-roam",
            };
        }
        let own_half_possession = self.possession_team() == Some(me.team)
            && pass_origin_in_own_half(me.team, self.ball.position, self.field_length);
        let shape = if self.possession_team() == Some(me.team) {
            let tendency =
                me.preferences.offensive_mindedness - me.preferences.defensive_mindedness;
            let mut support_y = if me.role == PlayerRole::Defender {
                self.defender_possession_line_y(me, home)
            } else {
                self.ball.position.y
                    - me.team.attack_dir()
                        * match me.role {
                            PlayerRole::Goalkeeper if own_half_possession => 24.0,
                            PlayerRole::Goalkeeper => 30.0,
                            PlayerRole::Midfielder if own_half_possession => -8.0 - tendency * 12.0,
                            PlayerRole::Midfielder => -2.0 - tendency * 18.0,
                            PlayerRole::Forward if own_half_possession => -12.0,
                            PlayerRole::Forward => -6.0,
                            PlayerRole::Defender => 18.0,
                        }
            };
            if me.role == PlayerRole::Midfielder
                && me.preferences.defensive_mindedness > me.preferences.offensive_mindedness
            {
                if let Some(screen_y) = self.center_back_screen_y(me.team) {
                    let screen_weight = (me.preferences.defensive_mindedness
                        - me.preferences.offensive_mindedness)
                        .clamp(0.0, 0.75);
                    support_y = support_y * (1.0 - screen_weight) + screen_y * screen_weight;
                }
            }
            Vec2::new(home.x * 0.72 + self.ball.position.x * 0.28, support_y)
                .clamp_to_pitch(self.field_width, self.field_length)
        } else {
            self.defensive_shape_for(player_id, home)
        };
        let attack_depth = (self.ball.position.y - self.field_length * 0.5) * me.team.attack_dir();
        let defensive_midfield_screen = me.role == PlayerRole::Midfielder
            && me.preferences.defensive_mindedness > me.preferences.offensive_mindedness;
        let striker_overlap_target =
            self.striker_holder_in_opponent_half(me.team)
                .and_then(|(_, striker_pos)| {
                    let attacking_midfielder = me.role == PlayerRole::Midfielder
                        && me.preferences.offensive_mindedness >= 0.64
                        && !defensive_midfield_screen;
                    if !attacking_midfielder {
                        return None;
                    }
                    let mid_x = self.field_width * 0.5;
                    let current = self.player_snapshot_position(me);
                    let current_x = current.x.clamp(0.0, self.field_width);
                    let wide =
                        current_x < self.field_width * 0.30 || current_x > self.field_width * 0.70;
                    let lane_sign = if current_x < mid_x {
                        -1.0
                    } else if current_x > mid_x {
                        1.0
                    } else if striker_pos.x < mid_x {
                        1.0
                    } else {
                        -1.0
                    };
                    let lateral = if wide { 12.0 } else { 7.5 };
                    let forward = if wide { 9.0 } else { 5.5 };
                    let candidate = Vec2::new(
                        striker_pos.x + lane_sign * lateral,
                        striker_pos.y + me.team.attack_dir() * forward,
                    )
                    .clamp_to_pitch(self.field_width, self.field_length);
                    let support_space = self.space_score_at(candidate, me.team);
                    (support_space >= 6.0 || wide).then_some(candidate)
                });
        if self.possession_team() == Some(me.team) && !roam && striker_overlap_target.is_none() {
            if let Some(target) = special_targets.flank_cross_arrival {
                return SupportMovementTarget {
                    point: self.shape_guarded_support_point(
                        player_id,
                        target,
                        &[open, shape, home],
                        home,
                        roam,
                    ),
                    action_label: "shot-creation-run",
                };
            }
            if let Some(target) = special_targets.wide_outlet {
                return SupportMovementTarget {
                    point: self.shape_guarded_support_point(
                        player_id,
                        target,
                        &[open, shape, home],
                        home,
                        roam,
                    ),
                    action_label: "wide-outlet",
                };
            }
        }
        let (target, action_label) = if self.possession_team() == Some(me.team)
            && attack_depth > -4.0
            && matches!(me.role, PlayerRole::Forward | PlayerRole::Midfielder)
            && !defensive_midfield_screen
        {
            let finish = special_targets
                .flank_cross_arrival
                .unwrap_or_else(|| self.shot_creation_space_for(player_id, home));
            if let Some(overlap) = striker_overlap_target {
                (
                    open * 0.24 + shape * 0.16 + finish * 0.18 + overlap * 0.34 + home * 0.08,
                    "overlap-run",
                )
            } else {
                (
                    open * 0.34 + shape * 0.20 + finish * 0.36 + home * 0.10,
                    "shot-creation-run",
                )
            }
        } else if defensive_midfield_screen {
            (open * 0.14 + shape * 0.72 + home * 0.14, "support-screen")
        } else if own_half_possession && me.role != PlayerRole::Goalkeeper {
            (open * 0.64 + shape * 0.26 + home * 0.10, "support-push-up")
        } else {
            (open * 0.55 + shape * 0.30 + home * 0.15, "support-shape")
        };
        let point =
            self.shape_guarded_support_point(player_id, target, &[open, shape, home], home, roam);
        let point = if !roam {
            self.apply_defender_possession_line_floor(me, home, point)
        } else {
            point
        };
        SupportMovementTarget {
            point,
            action_label,
        }
    }

    pub fn defensive_shape_for(&self, player_id: usize, home: Vec2) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        let ball_y = self.ball.position.y;
        let directive = self.tactical_directive(me.team);
        if me.role == PlayerRole::Goalkeeper
            && self
                .controlled_possession_team()
                .or_else(|| self.possession_team())
                != Some(me.team)
        {
            return self.goalkeeper_ball_goal_tracking_target(me.team);
        }
        let role_line_bias = match me.role {
            PlayerRole::Goalkeeper => 0.10,
            PlayerRole::Defender => 0.70,
            PlayerRole::Midfielder => 0.48,
            PlayerRole::Forward => 0.28,
        };
        let mut compact_y = home.y * (1.0 - role_line_bias)
            + directive.defensive_line_y * role_line_bias
            + ball_y * 0.18
            - 3.0 * me.team.attack_dir();
        let mut width_factor = (directive.width_yards / self.field_width).clamp(0.42, 0.88);
        if self.possession_team() == Some(me.team.other()) {
            let opponent_width_factor = (self.team_lateral_width_yards(me.team.other())
                / self.field_width.max(1.0))
            .clamp(0.0, 1.0);
            let markovian_spread = deterministic_unit_draw(self.tick, player_id, 97) * 2.0 - 1.0;
            let follow_width = (opponent_width_factor * DEFENSE_SPREAD_FOLLOW_RATIO
                + markovian_spread * 0.035)
                .clamp(0.34, 0.74);
            width_factor = width_factor.max(follow_width);
        }
        let mid_x = self.field_width * 0.5;
        let mut compact_x = mid_x
            + (home.x - mid_x) * width_factor
            + (self.ball.position.x - mid_x) * (0.18 + directive.press_intensity * 0.12);
        if me.role == PlayerRole::Midfielder {
            let press_focus = self.defensive_midfielder_press_focus(me.team);
            let goal_side_press_y =
                press_focus.y - me.team.attack_dir() * MIDFIELDER_PRESS_FOCUS_IDEAL_YARDS;
            let press_blend = (0.24 + directive.press_intensity * 0.28).clamp(0.24, 0.56);
            compact_x = compact_x * (1.0 - press_blend) + press_focus.x * press_blend;
            compact_y = compact_y * (1.0 - press_blend) + goal_side_press_y * press_blend;
        }
        if let Some(striker_pos) = self.opponent_striker_holder_in_attacking_half(me.team) {
            let press_distance = match me.role {
                PlayerRole::Defender => 6.0,
                PlayerRole::Midfielder => 3.8,
                PlayerRole::Forward => 8.5,
                PlayerRole::Goalkeeper => 0.0,
            };
            if press_distance > 0.0 {
                let press_y = striker_pos.y - me.team.attack_dir() * press_distance;
                let press_blend = match me.role {
                    PlayerRole::Defender => 0.36,
                    PlayerRole::Midfielder => 0.30,
                    PlayerRole::Forward => 0.16,
                    PlayerRole::Goalkeeper => 0.0,
                } * directive.press_intensity.clamp(0.55, 1.0);
                compact_x = compact_x * (1.0 - press_blend) + striker_pos.x * press_blend;
                compact_y = compact_y * (1.0 - press_blend) + press_y * press_blend;
            }
        }
        if me.role == PlayerRole::Defender {
            if let Some((holder_position, line_gap)) =
                self.opponent_breakthrough_ball_carrier(me.team)
            {
                let threat_fit = defensive_line_break_threat_fit(line_gap);
                let retreat_y =
                    self.defensive_line_break_retreat_target_y(me.team, holder_position, line_gap);
                let retreat_blend =
                    (0.92 + threat_fit * 0.08) * directive.press_intensity.clamp(0.94, 1.0);
                compact_y = compact_y * (1.0 - retreat_blend) + retreat_y * retreat_blend;
                compact_x = compact_x * 0.88 + holder_position.x * 0.12;
            }
        }
        let mut shape =
            Vec2::new(compact_x, compact_y).clamp_to_pitch(self.field_width, self.field_length);
        if self.possession_team() == Some(me.team.other()) && me.role != PlayerRole::Goalkeeper {
            let own_goal_y = self.own_goal_y_for(me.team);
            let buffer = if self.ball_near_own_goal_line(me.team) {
                1.25
            } else {
                DEFENSIVE_GOAL_LINE_BUFFER_YARDS
            };
            if own_goal_y <= self.field_length * 0.5 {
                shape.y = shape.y.max(own_goal_y + buffer);
            } else {
                shape.y = shape.y.min(own_goal_y - buffer);
            }
            shape = shape.clamp_to_pitch(self.field_width, self.field_length);
        }
        shape
    }

    fn team_lateral_width_yards(&self, team: Team) -> f64 {
        let mut min_x = f64::INFINITY;
        let mut max_x = f64::NEG_INFINITY;
        let mut count = 0usize;
        for player in self
            .players
            .iter()
            .filter(|player| player.team == team && player.role != PlayerRole::Goalkeeper)
        {
            let position = self.player_snapshot_position(player);
            min_x = min_x.min(position.x);
            max_x = max_x.max(position.x);
            count += 1;
        }
        if count < 2 {
            0.0
        } else {
            (max_x - min_x).clamp(0.0, self.field_width.max(0.0))
        }
    }

    pub fn mark_or_zone_for(&self, player_id: usize, home: Vec2) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        if me.role == PlayerRole::Goalkeeper {
            return self.defensive_shape_for(player_id, home);
        }

        let zone = self.defensive_shape_for(player_id, home);
        let Some(mark_target) = soccer_defensive_mark_target(self, me.team, me.role, zone) else {
            return zone;
        };
        (mark_target * 0.5 + zone * 0.5).clamp_to_pitch(self.field_width, self.field_length)
    }

    pub fn defensive_assignment_for(&self, player_id: usize, home: Vec2, roam: bool) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            let zone = self.defensive_shape_for(player_id, home);
            return self.clamp_to_role_position(player_id, zone, home, roam);
        };
        let zone = self.defensive_shape_for(player_id, home);
        if me.role == PlayerRole::Goalkeeper {
            return zone;
        }
        let mark = self.mark_or_zone_for(player_id, home);
        let opponent_width_factor = (self.team_lateral_width_yards(me.team.other())
            / self.field_width.max(1.0))
        .clamp(0.0, 1.0);
        let spread_follow = ((opponent_width_factor - 0.42) / 0.48).clamp(0.0, 1.0);
        let markovian_mark = deterministic_unit_draw(self.tick, player_id, 101) * 2.0 - 1.0;
        let mark_weight = if roam {
            (0.78 + spread_follow * 0.04 + markovian_mark * 0.035).clamp(0.70, 0.88)
        } else {
            (0.46 + spread_follow * 0.18 + markovian_mark * 0.045).clamp(0.42, 0.70)
        };
        let blended = mark * mark_weight + zone * (1.0 - mark_weight);
        let mut best = blended;
        let mut best_score = f64::NEG_INFINITY;
        for dx in [-5.0, -2.5, 0.0, 2.5, 5.0] {
            for dy in [-4.0, -2.0, 0.0, 2.0, 4.0] {
                let candidate = (blended + Vec2::new(dx, dy))
                    .clamp_to_pitch(self.field_width, self.field_length);
                let compact_score = self.team_spacing_score_for_candidate(
                    me.team,
                    Some(player_id),
                    candidate,
                    TeamSpacingMode::Defending,
                );
                let tracking_relief =
                    self.positional_shape_exception_relief_for_player_target(me, candidate);
                let lane_penalty =
                    self.vertical_lane_penalty_for_player_target(me, candidate, tracking_relief);
                let line_penalty =
                    self.role_line_penalty_for_player_target(me, candidate, tracking_relief);
                let teammate_penalty = self.teammate_occupied_space_penalty_at(
                    me.team,
                    candidate,
                    Some(player_id),
                    tracking_relief,
                ) * 0.55;
                let score = compact_score * 0.45
                    - candidate.distance(blended) * 0.055
                    - candidate.distance(mark) * 0.025
                    - lane_penalty
                    - line_penalty
                    - teammate_penalty;
                if score > best_score {
                    best = candidate;
                    best_score = score;
                }
            }
        }
        let mut guarded =
            self.shape_guarded_movement_point(player_id, best, &[mark, zone, home], home, roam);
        if let Some(holder_position) = self.ball.holder.and_then(|holder| {
            self.players
                .iter()
                .find(|player| player.id == holder && player.team == me.team.other())
                .map(|player| self.player_snapshot_position(player))
        }) {
            let mark_candidate = self.clamp_to_role_position(player_id, mark, home, roam);
            let mark_relief =
                self.positional_shape_exception_relief_for_player_target(me, mark_candidate);
            let mark_teammate_pressure =
                self.teammate_occupied_space_pressure_at(me.team, mark_candidate, Some(player_id));
            if mark_candidate.distance(holder_position) + 0.25 < guarded.distance(holder_position)
                && mark_candidate.distance(holder_position) < zone.distance(holder_position)
                && (mark_teammate_pressure < 0.90 || mark_relief >= 0.20)
            {
                guarded = mark_candidate;
            }
        }
        if let Some((cross_mark, _)) =
            soccer_defensive_cross_arrival_mark_target(self, me.team, me.role, zone)
        {
            let cross_blend =
                (cross_mark * 0.5 + zone * 0.5).clamp_to_pitch(self.field_width, self.field_length);
            let cross_candidate = self.clamp_to_role_position(player_id, cross_blend, home, roam);
            let cross_relief =
                self.positional_shape_exception_relief_for_player_target(me, cross_candidate);
            let cross_teammate_pressure =
                self.teammate_occupied_space_pressure_at(me.team, cross_candidate, Some(player_id));
            if cross_candidate.distance(cross_mark) + 0.25 < guarded.distance(cross_mark)
                && cross_candidate.distance(cross_mark) < zone.distance(cross_mark)
                && (cross_teammate_pressure < 0.90 || cross_relief >= 0.20)
            {
                guarded = cross_candidate;
            }
        }
        if me.role == PlayerRole::Defender {
            if let Some((holder_position, line_gap)) =
                self.opponent_breakthrough_ball_carrier(me.team)
            {
                let target = self.clamp_defensive_line_break_retreat(
                    me.team,
                    holder_position,
                    line_gap,
                    guarded,
                );
                return self.goal_side_defensive_target_for_player(me, target);
            }
        }
        self.goal_side_defensive_target_for_player(me, guarded)
    }

    fn clamp_to_role_position(
        &self,
        player_id: usize,
        target: Vec2,
        home: Vec2,
        roam: bool,
    ) -> Vec2 {
        let Some(me) = self.players.iter().find(|p| p.id == player_id) else {
            return home;
        };
        if roam {
            return target.clamp_to_pitch(self.field_width, self.field_length);
        }
        let in_possession = self.possession_team() == Some(me.team);
        let radius = match me.role {
            PlayerRole::Goalkeeper => 7.0,
            PlayerRole::Defender if in_possession && self.is_wide_defender(me) => {
                26.0 + self.wingback_extra_push_yards(me) * 0.38
            }
            PlayerRole::Defender if in_possession => 24.0,
            PlayerRole::Defender => 13.0,
            PlayerRole::Midfielder => 24.0,
            PlayerRole::Forward => 20.0,
        };
        let delta = target - home;
        let mut bounded = if delta.len() <= radius {
            target.clamp_to_pitch(self.field_width, self.field_length)
        } else {
            (home + delta.normalized() * radius).clamp_to_pitch(self.field_width, self.field_length)
        };
        let relief = self.positional_shape_exception_relief_for_player_target(me, bounded);
        let fit = self.vertical_lane_fit_for_player_target(me, bounded, relief);
        if fit.commitment > 1e-9 && fit.deviation_yards > 0.0 {
            let lane_x = vertical_lane_clamped_x_for_role(
                me.role,
                home.x,
                bounded.x,
                self.field_width,
                in_possession,
            );
            if fit.commitment >= 0.65 && relief < 0.15 {
                bounded.x = lane_x;
            } else {
                let lane_blend = (fit.commitment * 0.72).clamp(0.0, 0.72);
                bounded.x = bounded.x * (1.0 - lane_blend) + lane_x * lane_blend;
            }
            bounded = bounded.clamp_to_pitch(self.field_width, self.field_length);
        }
        let bounded = self.clamp_forward_onside_support(me, bounded);
        if self.possession_team() == Some(me.team.other()) && me.role != PlayerRole::Goalkeeper {
            let bounded = self.clamp_defensive_goal_line_and_ball_gap(me.team, bounded);
            self.goal_side_defensive_target_for_player(me, bounded)
        } else {
            bounded
        }
    }

    fn movement_target_shape_score(&self, player: &PlayerSnapshot, target: Vec2) -> f64 {
        let possession = self
            .controlled_possession_team()
            .or_else(|| self.possession_team());
        let spacing_mode = if possession == Some(player.team.other()) {
            TeamSpacingMode::Defending
        } else {
            TeamSpacingMode::InPossession
        };
        let relief = self.positional_shape_exception_relief_for_player_target(player, target);
        let spacing = self.team_spacing_score_for_candidate(
            player.team,
            Some(player.id),
            target,
            spacing_mode,
        );
        let space = (self.space_score_at(target, player.team) / 18.0).clamp(0.0, 1.0);
        let teammate_penalty =
            self.teammate_occupied_space_penalty_at(player.team, target, Some(player.id), relief);
        let lane_penalty = self.vertical_lane_penalty_for_player_target(player, target, relief);
        let line_penalty = self.role_line_penalty_for_player_target(player, target, relief);
        let offside_penalty = if possession == Some(player.team)
            && self.position_would_be_offside(player.team, target)
        {
            1.5
        } else {
            0.0
        };

        space * 0.48 + spacing * 0.34 + relief * 0.18
            - teammate_penalty * 0.72
            - lane_penalty * 0.34
            - line_penalty * 0.42
            - offside_penalty
    }

    fn shape_guarded_learned_support_target(
        &self,
        player_id: usize,
        proposed: Vec2,
        fallback: Vec2,
        home: Vec2,
    ) -> Vec2 {
        self.shape_guarded_support_point(player_id, proposed, &[fallback], home, false)
    }

    fn shape_guarded_support_point(
        &self,
        player_id: usize,
        proposed: Vec2,
        fallback_candidates: &[Vec2],
        home: Vec2,
        roam: bool,
    ) -> Vec2 {
        self.shape_guarded_movement_point(player_id, proposed, fallback_candidates, home, roam)
    }

    fn shape_guarded_movement_point(
        &self,
        player_id: usize,
        proposed: Vec2,
        fallback_candidates: &[Vec2],
        home: Vec2,
        roam: bool,
    ) -> Vec2 {
        let clamp = |snapshot: &WorldSnapshot, target: Vec2| {
            if roam {
                target.clamp_to_pitch(snapshot.field_width, snapshot.field_length)
            } else {
                snapshot.clamp_to_role_position(player_id, target, home, false)
            }
        };
        let proposed = clamp(self, proposed);
        let Some(player) = self.players.iter().find(|p| p.id == player_id) else {
            return fallback_candidates
                .first()
                .copied()
                .map(|candidate| clamp(self, candidate))
                .unwrap_or(proposed);
        };
        let proposed_score = self.movement_target_shape_score(player, proposed);
        let proposed_relief =
            self.positional_shape_exception_relief_for_player_target(player, proposed);
        let proposed_teammate_pressure =
            self.teammate_occupied_space_pressure_at(player.team, proposed, Some(player_id));
        let hard_teammate_occupied = proposed_teammate_pressure > 0.90 && proposed_relief < 0.20;
        let current = self.player_snapshot_position(player);
        let proposed_forward = (proposed.y - current.y) * player.team.attack_dir();
        let proposed_lateral = (proposed.x - current.x).abs();
        let active_attacking_support = self.possession_team() == Some(player.team)
            && !roam
            && player.role != PlayerRole::Goalkeeper
            && (proposed_forward > 3.0
                || (proposed_lateral > 3.0
                    && proposed_forward
                        >= proposed_lateral * SUPPORT_MIN_UPFIELD_PER_LATERAL_YARD - 1e-6));
        let mut best = proposed;
        let mut best_score = proposed_score;
        for candidate in fallback_candidates {
            let candidate = clamp(self, *candidate);
            let candidate_score = self.movement_target_shape_score(player, candidate);
            if candidate_score > best_score {
                best = candidate;
                best_score = candidate_score;
            }
        }
        let fallback_margin = if hard_teammate_occupied {
            0.10
        } else if active_attacking_support {
            0.85
        } else {
            0.10
        };
        if best_score > proposed_score + fallback_margin {
            best
        } else {
            proposed
        }
    }

    fn space_score_at(&self, p: Vec2, team: Team) -> f64 {
        self.candidate_occupancy_at(team, p, None).open_space_score
    }

    fn clear_line(&self, from: Vec2, to: Vec2, defending_team: Team, radius: f64) -> bool {
        self.players
            .iter()
            .filter(|p| p.team == defending_team)
            .all(|p| {
                let position = self.player_snapshot_position(p);
                segment_distance_to_point(from, to, position) > radius
            })
    }

    fn shot_lane_clear(&self, from: Vec2, attacking_team: Team, radius: f64) -> bool {
        let speed = mph_to_yps(60.0);
        let threshold = if radius <= 2.0 { 0.18 } else { 0.34 };
        shot_block_assessment_for_snapshot(self, from, attacking_team, speed, false)
            .map(|assessment| assessment.probability <= threshold)
            .unwrap_or(true)
    }

    fn position_would_be_offside(&self, team: Team, position: Vec2) -> bool {
        let half_line = self.field_length * 0.5;
        match team {
            Team::Home if position.y <= half_line => return false,
            Team::Away if position.y >= half_line => return false,
            _ => {}
        }

        let mut defender_ys = self
            .players
            .iter()
            .filter(|p| p.team == team.other())
            .filter_map(|p| self.player_position(p.id).map(|position| position.y))
            .collect::<Vec<_>>();
        if defender_ys.len() < 2 {
            return false;
        }

        match team {
            Team::Home => {
                defender_ys.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
                position.y > self.ball.position.y && position.y > defender_ys[1]
            }
            Team::Away => {
                defender_ys.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                position.y < self.ball.position.y && position.y < defender_ys[1]
            }
        }
    }
}

fn sample_defensive_cover_target(rng: &mut SeededRandom) -> usize {
    let roll = rng.next_float();
    if roll < 0.10 {
        0
    } else if roll < 0.20 {
        1
    } else if roll < 0.50 {
        2
    } else if roll < 0.80 {
        3
    } else {
        4
    }
}

fn defensive_cover_profile(
    snapshot: &WorldSnapshot,
    team: Team,
    target: usize,
) -> DefensiveCoverProfile {
    let foremost_attacker_y = snapshot
        .players
        .iter()
        .filter(|player| player.team == team.other() && player.role != PlayerRole::Goalkeeper)
        .filter_map(|player| {
            snapshot
                .player_position(player.id)
                .map(|position| position.y)
        })
        .reduce(|a, b| match team {
            Team::Home => a.min(b),
            Team::Away => a.max(b),
        });

    let actual = foremost_attacker_y
        .map(|attacker_y| {
            snapshot
                .players
                .iter()
                .filter(|player| player.team == team && player.role != PlayerRole::Goalkeeper)
                .filter_map(|player| snapshot.player_position(player.id))
                .filter(|position| match team {
                    Team::Home => position.y <= attacker_y,
                    Team::Away => position.y >= attacker_y,
                })
                .count()
        })
        .unwrap_or(0);

    DefensiveCoverProfile {
        target,
        actual,
        foremost_attacker_y,
    }
}

fn attacking_overload_profile(snapshot: &WorldSnapshot, team: Team) -> AttackingOverloadProfile {
    let controlled_possession = snapshot.controlled_possession_team() == Some(team);
    let loose_long_ball = !controlled_possession
        && snapshot.ball.holder.is_none()
        && snapshot.pending_pass.is_none()
        && snapshot.possession_team() == Some(team);
    let focus = if controlled_possession {
        snapshot.ball.position
    } else if loose_long_ball {
        let Some(projected) = snapshot.projected_loose_ball_target() else {
            return AttackingOverloadProfile::default();
        };
        projected
    } else {
        return AttackingOverloadProfile::default();
    };

    let dir = team.attack_dir();
    let goal_x = snapshot.field_width * 0.5;
    let corridor_center_x = focus.x * 0.68 + goal_x * 0.32;
    let corridor_half_width = (18.0 + snapshot.field_width * 0.12).clamp(20.0, 30.0);
    let forward_depth = if loose_long_ball { 50.0 } else { 44.0 };
    let defender_forward_depth = if loose_long_ball {
        18.0
    } else {
        forward_depth + 5.0
    };
    let support_trailer_yards = if loose_long_ball { 14.0 } else { 7.0 };

    let in_threat_lane = |position: Vec2| {
        let forward = (position.y - focus.y) * dir;
        forward >= -support_trailer_yards
            && forward <= forward_depth
            && (position.x - corridor_center_x).abs() <= corridor_half_width
    };

    let mut attackers = 0usize;
    let mut defenders = 0usize;
    for player in &snapshot.players {
        if player.role == PlayerRole::Goalkeeper {
            continue;
        }
        let Some(position) = snapshot.player_position(player.id) else {
            continue;
        };
        if player.team == team {
            if in_threat_lane(position) {
                attackers += 1;
            }
        } else {
            let forward = (position.y - focus.y) * dir;
            if forward >= -1.5
                && forward <= defender_forward_depth
                && (position.x - corridor_center_x).abs() <= corridor_half_width + 4.0
            {
                defenders += 1;
            }
        }
    }

    let advantage = attackers as i32 - defenders as i32;
    let field_progress = ((focus.y - snapshot.field_length * 0.5) * dir / 36.0).clamp(-0.35, 0.45);
    let score = if advantage > 0 {
        (advantage as f64 * 0.34 + field_progress + (attackers as f64 / 6.0).clamp(0.0, 0.45))
            .clamp(0.0, 1.0)
    } else {
        0.0
    };

    AttackingOverloadProfile {
        attackers,
        defenders,
        advantage,
        score,
    }
}

fn flank_attack_policy_for_team(
    team: Team,
    attacking_phase: bool,
    build_up_phase: bool,
    own_half_possession: bool,
    has_ball: bool,
    ball_position: Vec2,
    field_width: f64,
    field_length: f64,
    risk_tolerance: f64,
    overload_score: f64,
) -> FlankAttackPolicy {
    if !has_ball || (!attacking_phase && !build_up_phase && !own_half_possession) {
        return FlankAttackPolicy::None;
    }

    let center_x = field_width * 0.5;
    let half_width = center_x.max(1.0);
    let width_fit = ((ball_position.x - center_x).abs() / half_width).clamp(0.0, 1.0);
    let progress = ((ball_position.y - field_length * 0.5) * team.attack_dir()
        / (field_length * 0.5).max(1.0))
    .clamp(-1.0, 1.0);
    let phase_bonus = if attacking_phase {
        0.16
    } else if build_up_phase {
        0.09
    } else {
        0.06
    };
    let flank_probability = (0.14
        + width_fit * 0.28
        + progress.max(0.0) * 0.10
        + risk_tolerance * 0.14
        + overload_score * 0.16
        + phase_bonus
        + if own_half_possession { 0.06 } else { 0.0 })
    .clamp(0.10, 0.74);
    let zone_x = ((ball_position.x / field_width.max(1.0)) * 8.0)
        .floor()
        .clamp(0.0, 7.0) as u64;
    let zone_y = ((ball_position.y / field_length.max(1.0)) * 12.0)
        .floor()
        .clamp(0.0, 11.0) as u64;
    let phase_key = if attacking_phase {
        3
    } else if build_up_phase {
        2
    } else {
        1
    };
    let team_key = match team {
        Team::Home => 0,
        Team::Away => 1,
    };
    let zone_key = zone_x + zone_y * 17 + phase_key * 257;
    if deterministic_unit_draw(zone_key, team_key, 211) >= flank_probability {
        return FlankAttackPolicy::None;
    }

    let high_cross_share = (0.32
        + progress.max(0.0) * 0.24
        + overload_score * 0.18
        + risk_tolerance * 0.10
        + width_fit * 0.04)
        .clamp(0.24, 0.72);
    let high_draw = deterministic_unit_draw(zone_x + zone_y * 19 + phase_key * 263, team_key, 223);
    if high_draw < high_cross_share {
        FlankAttackPolicy::PlayDownFlankHighCross
    } else {
        FlankAttackPolicy::PlayDownFlankLowCross
    }
}

fn tactical_directive_for_team(
    team: Team,
    phase: TacticalPhase,
    possession_team: Option<Team>,
    ball_position: Vec2,
    score_diff_for_team: i32,
    field_width: f64,
    field_length: f64,
    defensive_cover: DefensiveCoverProfile,
    attacking_overload: AttackingOverloadProfile,
) -> TeamTacticalDirective {
    let has_ball = possession_team == Some(team);
    let defending = possession_team == Some(team.other());
    let overload_score = if has_ball {
        attacking_overload.score
    } else {
        0.0
    };
    let attacking_phase = matches!(
        (team, phase),
        (Team::Home, TacticalPhase::HomeAttack) | (Team::Away, TacticalPhase::AwayAttack)
    );
    let own_half_possession =
        has_ball && pass_origin_in_own_half(team, ball_position, field_length);
    let build_up_phase = matches!(
        (team, phase),
        (Team::Home, TacticalPhase::HomeBuildUp) | (Team::Away, TacticalPhase::AwayBuildUp)
    );
    let trailing = score_diff_for_team < 0;
    let leading = score_diff_for_team > 0;
    let urgency: f64 = if trailing {
        0.16
    } else if leading {
        -0.08
    } else {
        0.0
    };
    let attack_dir = team.attack_dir();
    let mut line_seed = if has_ball {
        let holding_distance = if own_half_possession {
            14.0
        } else if attacking_phase {
            18.0
        } else {
            25.0
        };
        ball_position.y - attack_dir * holding_distance
    } else if defending {
        let press_step = 8.0 + (urgency.max(0.0) * 18.0);
        ball_position.y - attack_dir * press_step
    } else {
        match team {
            Team::Home => field_length * 0.42,
            Team::Away => field_length * 0.58,
        }
    };
    if defending {
        if let Some(foremost_attacker_y) = defensive_cover.foremost_attacker_y {
            let goal_side_dir = -attack_dir;
            let cover_gap = match defensive_cover.target {
                0 => -2.0,
                1 => 3.5,
                2 => 6.5,
                3 => 9.5,
                _ => 12.5,
            };
            let shortage = defensive_cover
                .target
                .saturating_sub(defensive_cover.actual) as f64;
            let surplus = defensive_cover
                .actual
                .saturating_sub(defensive_cover.target + 1) as f64;
            let adjusted_gap = cover_gap + shortage * 2.0 - surplus * 1.0;
            let cover_line_seed = foremost_attacker_y + goal_side_dir * adjusted_gap;
            line_seed = line_seed * 0.32 + cover_line_seed * 0.68;
        }
    }
    let defensive_line_y: f64 = line_seed.clamp(field_length * 0.08, field_length * 0.92);

    let risk_tolerance: f64 = (0.46
        + if attacking_phase { 0.15 } else { 0.0 }
        + if build_up_phase { 0.04 } else { 0.0 }
        + if own_half_possession { 0.11 } else { 0.0 }
        + overload_score * 0.18
        + urgency)
        .clamp(0.28, 0.92);
    let press_intensity: f64 = (if defending {
        0.58 + risk_tolerance * 0.45
    } else if possession_team.is_none() {
        0.54
    } else {
        0.30 + risk_tolerance * 0.12 + overload_score * 0.26
    })
    .clamp(0.22, 1.0);
    let pass_base: f64 = if has_ball {
        if build_up_phase {
            1.18
        } else if attacking_phase {
            0.96
        } else {
            1.04
        }
    } else {
        0.84
    };
    let pass_priority: f64 = (pass_base + overload_score * 0.16 + if leading { 0.06 } else { 0.0 }
        - if trailing && attacking_phase {
            0.04
        } else {
            0.0
        })
    .clamp(0.62, 1.32);
    let carry_priority: f64 = (if has_ball {
        if attacking_phase {
            1.20
        } else if own_half_possession {
            1.16
        } else if build_up_phase {
            0.92
        } else {
            1.02
        }
    } else {
        0.76
    } + urgency * 0.55
        + overload_score * 0.22)
        .clamp(0.55, 1.35);
    let flank_attack_policy = flank_attack_policy_for_team(
        team,
        attacking_phase,
        build_up_phase,
        own_half_possession,
        has_ball,
        ball_position,
        field_width,
        field_length,
        risk_tolerance,
        overload_score,
    );
    let flank_overlap_run_probability = if flank_attack_policy.is_flank() {
        ((1.0 / 3.0)
            + risk_tolerance * 0.16
            + overload_score * 0.12
            + if attacking_phase { 0.06 } else { 0.0 })
        .clamp(1.0 / 3.0, 0.72)
    } else {
        0.0
    };
    let support_depth_yards: f64 = (if attacking_phase {
        15.5
    } else if build_up_phase {
        11.5
    } else if defending {
        7.5
    } else {
        10.0
    } + risk_tolerance * 3.0
        + if own_half_possession { 4.5 } else { 0.0 }
        + overload_score * 5.0
        + if flank_attack_policy.is_flank() {
            1.5
        } else {
            0.0
        })
    .clamp(6.5, 24.0);
    let width_factor = if has_ball {
        if attacking_phase {
            0.76 + risk_tolerance * 0.18 + overload_score * 0.06
        } else if build_up_phase || own_half_possession {
            0.71 + risk_tolerance * 0.16 + overload_score * 0.05
        } else {
            0.69 + risk_tolerance * 0.14 + overload_score * 0.04
        }
    } else if defending {
        0.36 + press_intensity * 0.10
    } else {
        0.52 + press_intensity * 0.08
    };
    let width_factor = if flank_attack_policy.is_flank() {
        width_factor + 0.04
    } else {
        width_factor
    };
    let width_yards: f64 = (field_width * width_factor).clamp(
        field_width * if has_ball { 0.56 } else { 0.34 },
        field_width * if has_ball { 0.94 } else { 0.72 },
    );
    let shot_base: f64 =
        20.0 + if attacking_phase { 2.4 } else { 0.0 } + if trailing { 2.0 } else { 0.0 }
            - if leading { 1.2 } else { 0.0 }
            + overload_score * 3.5;
    let shot_threshold_yards: f64 = shot_base.clamp(16.0, 28.0);

    TeamTacticalDirective {
        team,
        defensive_line_y,
        defensive_cover_target: defensive_cover.target,
        defensive_cover_actual: defensive_cover.actual,
        foremost_attacker_y: defensive_cover.foremost_attacker_y,
        attacking_overload_attackers: attacking_overload.attackers,
        attacking_overload_defenders: attacking_overload.defenders,
        attacking_numbers_advantage: attacking_overload.advantage,
        attacking_overload_score: overload_score,
        support_depth_yards,
        width_yards,
        press_intensity,
        pass_priority,
        carry_priority,
        shot_threshold_yards,
        risk_tolerance,
        flank_attack_policy,
        flank_overlap_run_probability,
        adversarial_embedding_attack_score: 0.0,
        adversarial_embedding_defense_score: 0.0,
        adversarial_embedding_hits: 0,
    }
}

fn apply_adversarial_embedding_signal(
    directive: &mut TeamTacticalDirective,
    signal: SoccerAdversarialEmbeddingSignal,
    field_width: f64,
    field_length: f64,
) {
    let attack = signal.attack_score.clamp(0.0, 1.0);
    let defense = signal.defense_score.clamp(0.0, 1.0);
    directive.adversarial_embedding_attack_score = attack;
    directive.adversarial_embedding_defense_score = defense;
    directive.adversarial_embedding_hits = signal.hits;
    if attack <= 1e-9 && defense <= 1e-9 {
        return;
    }

    directive.risk_tolerance =
        (directive.risk_tolerance + attack * 0.10 - defense * 0.03).clamp(0.20, 0.96);
    directive.pass_priority = (directive.pass_priority + attack * 0.12).clamp(0.62, 1.42);
    directive.carry_priority = (directive.carry_priority + attack * 0.10).clamp(0.55, 1.42);
    directive.shot_threshold_yards =
        (directive.shot_threshold_yards + attack * 2.2).clamp(15.0, 30.0);
    directive.support_depth_yards =
        (directive.support_depth_yards + attack * 3.0 - defense * 0.5).clamp(6.0, 25.0);
    directive.width_yards = (directive.width_yards
        + field_width * (attack * 0.04 - defense * 0.02))
        .clamp(field_width * 0.30, field_width * 0.96);
    directive.press_intensity =
        (directive.press_intensity + defense * 0.18 + attack * 0.04).clamp(0.22, 1.0);
    if directive.flank_attack_policy.is_flank() {
        directive.flank_overlap_run_probability =
            (directive.flank_overlap_run_probability + attack * 0.06).clamp(1.0 / 3.0, 0.78);
    }

    let goal_side_dir = -directive.team.attack_dir();
    directive.defensive_line_y = (directive.defensive_line_y + goal_side_dir * defense * 3.5)
        .clamp(field_length * 0.08, field_length * 0.92);
}

fn belief_from_observation(obs: &SoccerPomdpObservation) -> BeliefState {
    let pressure = obs.perceived_pressure;
    let shot_quality =
        if obs.visible_ball && obs.shot_block_probability <= SHOT_BLOCK_BAILOUT_MAX_PROBABILITY {
            let block_factor = (1.0 - obs.shot_block_probability * 0.55).clamp(0.25, 1.0);
            ((obs.shot_on_frame_probability * 0.64
                + obs.shot_beat_goalkeeper_probability * 0.30
                + obs.shot_curl_probability * 0.08
                + (1.0 - obs.immediate_dispossession_risk) * 0.06)
                * block_factor)
                .clamp(0.0, 1.0)
        } else {
            0.0
        };
    let visible_option_confidence = (obs.visible_pass_options as f64 / 3.0).clamp(0.0, 1.0);
    BeliefState {
        possession_confidence: if obs.has_ball {
            0.98
        } else if obs.visible_ball {
            0.62
        } else {
            0.28
        },
        pressure,
        pass_lane_open: (visible_option_confidence * 0.38
            + obs.expected_pass_completion.clamp(0.0, 1.0) * 0.42
            + obs.best_pass_receiver_openness.clamp(0.0, 1.0) * 0.20)
            .clamp(0.0, 1.0),
        shot_quality,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PassDirectionBucket {
    Forward,
    Lateral,
    Backward,
}

fn pass_origin_in_own_half(team: Team, origin: Vec2, field_length: f64) -> bool {
    match team {
        Team::Home => origin.y < field_length * 0.5,
        Team::Away => origin.y > field_length * 0.5,
    }
}

fn position_in_opponent_half(team: Team, position: Vec2, field_length: f64) -> bool {
    match team {
        Team::Home => position.y > field_length * 0.5,
        Team::Away => position.y < field_length * 0.5,
    }
}

fn pass_direction_bucket(team: Team, origin: Vec2, target: Vec2) -> PassDirectionBucket {
    let forward = (target.y - origin.y) * team.attack_dir();
    if forward > 1.25 {
        PassDirectionBucket::Forward
    } else if forward < -1.25 {
        PassDirectionBucket::Backward
    } else {
        PassDirectionBucket::Lateral
    }
}

fn completed_pass_reward(team: Team, origin: Vec2, target: Vec2, field_length: f64) -> f64 {
    let forward_yards = ((target.y - origin.y) * team.attack_dir())
        .max(0.0)
        .clamp(0.0, COMPLETED_FORWARD_PASS_PROGRESS_REWARD_MAX_YARDS);
    let forward_progress_reward = forward_yards * COMPLETED_FORWARD_PASS_PROGRESS_REWARD_PER_YARD;
    match (
        pass_direction_bucket(team, origin, target),
        pass_origin_in_own_half(team, origin, field_length),
    ) {
        (PassDirectionBucket::Forward, true) => {
            COMPLETED_FORWARD_PASS_BASE_REWARD_OWN_HALF + forward_progress_reward
        }
        (PassDirectionBucket::Forward, false) => {
            COMPLETED_FORWARD_PASS_BASE_REWARD_OPPONENT_HALF + forward_progress_reward
        }
        (PassDirectionBucket::Lateral, _) => 1.6,
        (PassDirectionBucket::Backward, true) => 0.1,
        (PassDirectionBucket::Backward, false) => 0.7,
    }
}

fn cross_scoring_channel_score(
    team: Team,
    origin: Vec2,
    target: Vec2,
    field_width: f64,
    field_length: f64,
) -> f64 {
    if !pass_would_be_cross(origin, target, team, field_width, field_length) {
        return 0.0;
    }
    let flank_origin = flank_lane_score(origin, field_width).clamp(0.0, 1.0);
    let central_target = (1.0
        - ((target.x - field_width * 0.5).abs() / (field_width * 0.24).max(1.0)))
    .clamp(0.0, 1.0);
    let yards_to_goal = (team.goal_y(field_length) - target.y).abs();
    let box_depth = (1.0 - yards_to_goal / 24.0).clamp(0.0, 1.0);
    let cutback_or_six = (1.0 - (yards_to_goal - 10.0).abs() / 18.0).clamp(0.0, 1.0);
    (flank_origin * 0.32 + central_target * 0.28 + box_depth * 0.28 + cutback_or_six * 0.12)
        .clamp(0.0, 1.0)
}

fn completed_cross_reward_from_parts(
    team: Team,
    flight: PassFlight,
    is_cross: bool,
    origin: Vec2,
    target: Vec2,
    receiver_role: PlayerRole,
    receiver_skills: &SkillProfile,
    field_width: f64,
    field_length: f64,
) -> f64 {
    if !is_cross {
        return 0.0;
    }
    let scoring_channel =
        cross_scoring_channel_score(team, origin, target, field_width, field_length);
    if scoring_channel <= 0.0 {
        return 0.0;
    }
    let receiver_role = match receiver_role {
        PlayerRole::Forward => 0.18,
        PlayerRole::Midfielder => 0.10,
        PlayerRole::Defender => 0.04,
        PlayerRole::Goalkeeper => 0.0,
    };
    let receiver_tool = if flight.is_aerial() {
        ability01(receiver_skills.height) * 0.45
            + ability01(receiver_skills.strength) * 0.20
            + ability01(receiver_skills.first_touch) * 0.20
            + ability01(receiver_skills.shooting) * 0.15
    } else {
        ability01(receiver_skills.first_touch) * 0.34
            + ability01(receiver_skills.shooting) * 0.30
            + ability01(receiver_skills.top_speed) * 0.16
            + ability01(receiver_skills.dribbling) * 0.20
    };
    let flight_fit = if flight.is_aerial() {
        0.64 + receiver_tool * 0.68
    } else {
        0.66 + receiver_tool * 0.40
    };
    (COMPLETED_DANGEROUS_CROSS_BONUS_POINTS
        * scoring_channel
        * (flight_fit + receiver_role).clamp(0.55, 1.35))
    .clamp(0.0, COMPLETED_CROSS_MAX_BONUS_POINTS)
}

fn completed_cross_reward(
    pass: &PendingPass,
    receiver: &PlayerAgent,
    field_width: f64,
    field_length: f64,
) -> f64 {
    completed_cross_reward_from_parts(
        pass.team,
        pass.flight,
        pass.is_cross,
        pass.origin,
        pass.intended_target,
        receiver.role,
        &receiver.skills,
        field_width,
        field_length,
    )
}

fn completed_killer_pass_reward_from_parts(
    team: Team,
    flight: PassFlight,
    is_cross: bool,
    origin: Vec2,
    target: Vec2,
    receiver_role: PlayerRole,
    receiver_skills: &SkillProfile,
    field_width: f64,
    field_length: f64,
    receiver_openness: f64,
    stride_fit: f64,
) -> f64 {
    if is_cross || flight.is_aerial() {
        return 0.0;
    }
    let forward_yards = (target.y - origin.y) * team.attack_dir();
    if forward_yards < KILLER_PASS_MIN_FORWARD_YARDS {
        return 0.0;
    }
    let origin_yards_to_goal = (team.goal_y(field_length) - origin.y).abs();
    if origin_yards_to_goal > KILLER_PASS_MAX_YARDS_TO_GOAL {
        return 0.0;
    }
    let target_yards_to_goal = (team.goal_y(field_length) - target.y).abs();
    let goal_gain = origin_yards_to_goal - target_yards_to_goal;
    if goal_gain < KILLER_PASS_MIN_RECEIVER_GOAL_GAIN_YARDS {
        return 0.0;
    }
    let goal_channel =
        (1.0 - target_yards_to_goal / (TEAMMATE_MUST_SHOOT_YARDS + 8.0)).clamp(0.0, 1.0);
    if goal_channel <= 0.0 {
        return 0.0;
    }
    let centrality = goalmouth_centrality(target, field_width);
    let range_fit = ((KILLER_PASS_MAX_YARDS_TO_GOAL - origin_yards_to_goal)
        / KILLER_PASS_MAX_YARDS_TO_GOAL)
        .clamp(0.0, 1.0);
    let receiver_role_fit = match receiver_role {
        PlayerRole::Forward => 1.0,
        PlayerRole::Midfielder => 0.82,
        PlayerRole::Defender => 0.46,
        PlayerRole::Goalkeeper => 0.0,
    };
    let receiver_finish_tool = (ability01(receiver_skills.first_touch) * 0.34
        + ability01(receiver_skills.shooting) * 0.32
        + ability01(receiver_skills.top_speed) * 0.18
        + ability01(receiver_skills.dribbling) * 0.16)
        .clamp(0.0, 1.0);
    let stride_fit = stride_fit.clamp(0.0, 1.0);
    let openness = receiver_openness.clamp(0.0, 1.0);
    let threaded_fit = (goal_gain / 22.0).clamp(0.0, 1.0) * 0.18
        + range_fit * 0.12
        + goal_channel * 0.24
        + centrality * 0.16
        + openness * 0.12
        + stride_fit * 0.20;
    (COMPLETED_KILLER_PASS_BONUS_POINTS
        * threaded_fit
        * (0.62 + receiver_role_fit * 0.22 + receiver_finish_tool * 0.24).clamp(0.55, 1.08))
    .clamp(0.0, COMPLETED_KILLER_PASS_MAX_BONUS_POINTS)
}

fn completed_killer_pass_reward(
    pass: &PendingPass,
    receiver: &PlayerAgent,
    field_width: f64,
    field_length: f64,
) -> f64 {
    completed_killer_pass_reward_from_parts(
        pass.team,
        pass.flight,
        pass.is_cross,
        pass.origin,
        pass.intended_target,
        receiver.role,
        &receiver.skills,
        field_width,
        field_length,
        pass.receiver_openness,
        completed_pass_stride_anticipation_fit(pass),
    )
}

fn pass_stride_anticipation_reward_from_fit(
    stride_fit: f64,
    target_forward_yards: f64,
    receiver_openness: f64,
) -> f64 {
    if !stride_fit.is_finite() {
        return 0.0;
    }
    let directional_weight = if target_forward_yards > 2.0 {
        1.0 + (target_forward_yards / 32.0).clamp(0.0, 0.35)
    } else if target_forward_yards >= -1.25 {
        0.62
    } else {
        0.18
    };
    let openness_weight = 0.78 + receiver_openness.clamp(0.0, 1.0) * 0.34;
    let fit = ((stride_fit.clamp(0.0, 1.0) - 0.32) / 0.68).clamp(0.0, 1.0);
    (fit * 2.55 * directional_weight * openness_weight).clamp(0.0, 3.2)
}

fn completed_pass_stride_anticipation_fit(pass: &PendingPass) -> f64 {
    let Some(receiver_position) = pass.receiver_position_at_launch else {
        return 0.0;
    };
    let receiver_velocity = pass.receiver_velocity_at_launch.unwrap_or_else(Vec2::zero);
    pass_into_stride_fit(
        pass.origin,
        receiver_position,
        receiver_velocity,
        pass.intended_target,
        pass.launch_speed_yps,
        pass.team,
    )
}

fn completed_pass_anticipation_reward(pass: &PendingPass) -> f64 {
    let target_forward = (pass.intended_target.y - pass.origin.y) * pass.team.attack_dir();
    pass_stride_anticipation_reward_from_fit(
        completed_pass_stride_anticipation_fit(pass),
        target_forward,
        pass.receiver_openness,
    )
}

fn completed_pass_anticipation_reward_from_context(
    context: &SoccerDecisionContext,
    team: Team,
    receiver_openness: f64,
) -> f64 {
    pass_stride_anticipation_reward_from_fit(
        pass_into_stride_fit_for_context(context, team),
        context.target_forward_yards,
        receiver_openness,
    )
}

fn pass_chain_link_reward(direction: PassDirectionBucket, depth: usize) -> f64 {
    let base = match direction {
        PassDirectionBucket::Forward => 2.40,
        PassDirectionBucket::Lateral => 1.25,
        PassDirectionBucket::Backward => 0.45,
    };
    let depth_multiplier = match depth {
        0 => 1.0,
        1 => 0.62,
        _ => 0.0,
    };
    base * depth_multiplier
}

fn intercepted_pass_passer_penalty(pass: &PendingPass, field_length: f64) -> f64 {
    let direction = pass_direction_bucket(pass.team, pass.origin, pass.intended_target);
    let own_half = pass_origin_in_own_half(pass.team, pass.origin, field_length);
    let openness_cost = (1.0 - pass.receiver_openness.clamp(0.0, 1.0)) * 2.40;
    let direction_cost = match direction {
        PassDirectionBucket::Forward => 0.80,
        PassDirectionBucket::Lateral => 1.35,
        PassDirectionBucket::Backward => 2.10,
    };
    let own_half_cost = if own_half { 1.15 } else { 0.35 };
    let aerial_cost = if pass.flight.is_aerial() { 0.85 } else { 0.0 };
    (1.65 + openness_cost + direction_cost + own_half_cost + aerial_cost).clamp(2.0, 7.5)
}

fn quick_receiver_dispossession_passer_penalty(
    entry: &CompletedPassChainEntry,
    age_seconds: f64,
) -> f64 {
    if !(0.0..=3.2).contains(&age_seconds) {
        return 0.0;
    }
    let age_fit = (1.0 - age_seconds / 3.2).clamp(0.0, 1.0);
    let openness_cost = (1.0 - entry.receiver_openness.clamp(0.0, 1.0)) * 1.75;
    let direction_cost = match entry.direction {
        PassDirectionBucket::Forward => 0.58,
        PassDirectionBucket::Lateral => 1.05,
        PassDirectionBucket::Backward => 1.55,
    };
    let negative_progress_cost = if entry.target_forward_yards < -1.25 {
        0.70
    } else if entry.target_forward_yards <= 1.25 {
        0.30
    } else {
        0.0
    };
    ((1.05 + openness_cost + direction_cost + negative_progress_cost) * age_fit).clamp(0.0, 4.8)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PassChainContinuationKind {
    Shot,
    Pass,
    Dribble,
}

fn pass_chain_continuation_kind(action: &str) -> Option<PassChainContinuationKind> {
    let action = normalize_soccer_action_label(action);
    if matches!(action, "shoot" | "first-time-shot" | "first-time-header") {
        return Some(PassChainContinuationKind::Shot);
    }
    if is_pass_like_action(action) {
        return Some(PassChainContinuationKind::Pass);
    }
    is_dribble_action_label(action).then_some(PassChainContinuationKind::Dribble)
}

fn team_has_constructive_upfield_possession(snapshot: &WorldSnapshot, team: Team) -> bool {
    snapshot.controlled_possession_team() == Some(team)
        || snapshot
            .pending_pass
            .as_ref()
            .is_some_and(|pass| pass.team == team)
}

fn pass_chain_continuation_retained_possession(
    kind: PassChainContinuationKind,
    team: Team,
    after: &WorldSnapshot,
) -> bool {
    match kind {
        PassChainContinuationKind::Dribble => after.controlled_possession_team() == Some(team),
        PassChainContinuationKind::Pass => team_has_constructive_upfield_possession(after, team),
        PassChainContinuationKind::Shot => after.possession_team() == Some(team),
    }
}

fn ball_distance_from_own_goal(team: Team, position: Vec2, field_length: f64) -> f64 {
    (position.y - team.other().goal_y(field_length)).abs()
}

fn intentional_long_ball_loss_penalty(
    action: &str,
    own_half_holder: bool,
    ball_forward: f64,
    own_goal_relief: f64,
    loose_ball: bool,
) -> Option<f64> {
    match action {
        "clearance" => {
            let relief = own_goal_relief.max(ball_forward);
            let penalty = if relief >= 20.0 {
                if loose_ball {
                    0.12
                } else {
                    0.42
                }
            } else if relief >= 9.0 {
                if loose_ball {
                    0.34
                } else {
                    0.78
                }
            } else if own_half_holder {
                if loose_ball {
                    0.72
                } else {
                    1.35
                }
            } else if loose_ball {
                0.52
            } else {
                1.65
            };
            Some(penalty)
        }
        "route-one" => {
            let penalty = if ball_forward >= 30.0 {
                if loose_ball {
                    0.10
                } else {
                    0.48
                }
            } else if ball_forward >= 15.0 {
                if loose_ball {
                    0.30
                } else {
                    0.86
                }
            } else if own_half_holder {
                if loose_ball {
                    0.68
                } else {
                    1.30
                }
            } else if loose_ball {
                0.58
            } else {
                1.75
            };
            Some(penalty)
        }
        _ => None,
    }
}

fn intentional_long_ball_release_reward(
    player: &PlayerAgent,
    action: &str,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_obs: &SoccerPomdpObservation,
    ball_forward: f64,
    own_goal_relief: f64,
) -> f64 {
    let from_own_half =
        pass_origin_in_own_half(player.team, before.ball.position, before.field_length);
    let after_in_opponent_half =
        !pass_origin_in_own_half(player.team, after.ball.position, after.field_length);
    let pressure = before_obs.perceived_pressure.clamp(0.0, 1.0);
    let own_goal_distance =
        ball_distance_from_own_goal(player.team, before.ball.position, before.field_length);
    let defensive_third =
        (1.0 - own_goal_distance / (before.field_length * 0.35).max(1.0)).clamp(0.0, 1.0);
    let after_possession = after.controlled_possession_team();

    match action {
        "clearance" => {
            let role_scale = match player.role {
                PlayerRole::Goalkeeper => 0.92,
                PlayerRole::Defender => 1.0,
                PlayerRole::Midfielder => 0.48,
                PlayerRole::Forward => 0.22,
            };
            let relief_reward = own_goal_relief.clamp(-8.0, 42.0)
                * (0.035 + pressure * 0.035 + defensive_third * 0.025);
            let territory_reward = ball_forward.clamp(-8.0, 48.0) * 0.032;
            let pressure_bonus = pressure * 0.44 + defensive_third * 0.34;
            let outcome = if after_possession == Some(player.team.other()) && own_goal_relief < 12.0
            {
                -0.70
            } else if after_possession == Some(player.team) {
                0.22
            } else {
                0.10
            };
            let poor_clearance_penalty = if ball_forward < 2.0 { 0.95 } else { 0.0 };
            (relief_reward + territory_reward + pressure_bonus + outcome - poor_clearance_penalty)
                * role_scale
                - if from_own_half { 0.0 } else { 0.45 }
        }
        "route-one" => {
            let overload_bonus = before_obs.attacking_overload_score.clamp(0.0, 1.0) * 0.42;
            let territory_reward = ball_forward.clamp(-12.0, 65.0) * 0.052;
            let own_half_bonus = if from_own_half { 0.34 } else { -0.55 };
            let half_cross_bonus = if after_in_opponent_half { 0.48 } else { 0.0 };
            let opponent_recovery_penalty = if after_possession == Some(player.team.other()) {
                if ball_forward >= 30.0 {
                    0.10
                } else {
                    0.58
                }
            } else {
                0.0
            };
            let stagnant_penalty = if ball_forward < 8.0 { 0.90 } else { 0.0 };
            territory_reward + own_half_bonus + half_cross_bonus + overload_bonus
                - opponent_recovery_penalty
                - stagnant_penalty
        }
        _ => 0.0,
    }
}

#[derive(Clone, Debug)]
struct PlayerRewardLoad {
    player_id: usize,
    amount: f64,
    load: f64,
}

#[derive(Clone, Debug)]
struct PossessionChaseSignal {
    possession_team: Team,
    defending_team: Team,
    attacking_load: f64,
    defensive_load: f64,
    attacking_credit: f64,
    defender_penalties: Vec<PlayerRewardLoad>,
}

#[derive(Clone, Debug)]
struct DefensiveRelaxationSignal {
    possession_team: Team,
    defending_team: Team,
    attacking_credit: f64,
    defender_penalties: Vec<PlayerRewardLoad>,
}

#[derive(Clone, Debug)]
struct TeamworkProgressSignal {
    possession_team: Team,
    ball_progress: f64,
    team_centroid_progress: f64,
    near_ball_centroid_progress: f64,
    attacking_credit: f64,
    support_players: Vec<usize>,
}

#[derive(Clone, Debug)]
struct SoccerGoalCreditCandidate {
    transition: SoccerLearningTransition,
    score: f64,
}

fn snapshot_player<'a>(
    snapshot: &'a WorldSnapshot,
    player_id: usize,
) -> Option<&'a PlayerSnapshot> {
    snapshot
        .players
        .iter()
        .find(|player| player.id == player_id)
}

fn snapshot_player_position(snapshot: &WorldSnapshot, player: &PlayerSnapshot) -> Vec2 {
    snapshot
        .player_position(player.id)
        .unwrap_or(player.position)
}

fn unique_team_player_ids(
    ids: impl IntoIterator<Item = usize>,
    snapshot: &WorldSnapshot,
    team: Team,
) -> Vec<usize> {
    let mut unique = Vec::new();
    for id in ids {
        if unique.contains(&id) {
            continue;
        }
        if snapshot
            .players
            .iter()
            .any(|player| player.id == id && player.team == team)
        {
            unique.push(id);
        }
    }
    unique
}

fn team_field_player_ids(snapshot: &WorldSnapshot, team: Team) -> Vec<usize> {
    snapshot
        .players
        .iter()
        .filter(|player| player.team == team && player.role != PlayerRole::Goalkeeper)
        .map(|player| player.id)
        .collect()
}

fn nearest_team_field_players_to_ball(
    snapshot: &WorldSnapshot,
    team: Team,
    count: usize,
) -> Vec<usize> {
    let mut players = snapshot
        .players
        .iter()
        .filter(|player| player.team == team && player.role != PlayerRole::Goalkeeper)
        .map(|player| {
            (
                player.id,
                snapshot_player_position(snapshot, player).distance(snapshot.ball.position),
            )
        })
        .collect::<Vec<_>>();
    players.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
    players
        .into_iter()
        .take(count)
        .map(|(player_id, _)| player_id)
        .collect()
}

fn team_centroid_for_player_ids(snapshot: &WorldSnapshot, player_ids: &[usize]) -> Option<Vec2> {
    let mut total = Vec2::zero();
    let mut count = 0.0;
    for player_id in player_ids {
        let Some(player) = snapshot_player(snapshot, *player_id) else {
            continue;
        };
        total += snapshot_player_position(snapshot, player);
        count += 1.0;
    }
    (count > 0.0).then_some(total / count)
}

fn centroid_upfield_progress(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    team: Team,
    player_ids: &[usize],
) -> f64 {
    let Some(before_centroid) = team_centroid_for_player_ids(before, player_ids) else {
        return 0.0;
    };
    let Some(after_centroid) = team_centroid_for_player_ids(after, player_ids) else {
        return 0.0;
    };
    (after_centroid.y - before_centroid.y) * team.attack_dir()
}

fn player_upfield_progress(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    team: Team,
    player_id: usize,
) -> f64 {
    let Some(before_player) = snapshot_player(before, player_id) else {
        return 0.0;
    };
    let before_position = snapshot_player_position(before, before_player);
    let after_position = snapshot_player(after, player_id)
        .map(|player| snapshot_player_position(after, player))
        .unwrap_or(before_position);
    (after_position.y - before_position.y) * team.attack_dir()
}

fn player_motion_distance(before: &WorldSnapshot, after: &WorldSnapshot, player_id: usize) -> f64 {
    let Some(before_player) = snapshot_player(before, player_id) else {
        return 0.0;
    };
    let before_position = before
        .player_position(player_id)
        .unwrap_or(before_player.position);
    let after_position = after
        .player_position(player_id)
        .or_else(|| snapshot_player(after, player_id).map(|player| player.position))
        .unwrap_or(before_position);
    before_position.distance(after_position)
}

fn player_motion_load(before: &WorldSnapshot, after: &WorldSnapshot, player_id: usize) -> f64 {
    let distance = player_motion_distance(before, after, player_id);
    if distance <= 1e-9 {
        return 0.0;
    }
    let dt = before.dt_seconds.max(1e-6);
    let speed_yps = distance / dt;
    let acceleration = after
        .player_acceleration(player_id)
        .or_else(|| snapshot_player(after, player_id).map(|player| player.acceleration))
        .unwrap_or_else(Vec2::zero)
        .len();
    let gait_multiplier = snapshot_player(after, player_id)
        .map(|player| match player.movement_gait {
            MovementGait::Sprint => 1.28,
            MovementGait::Run => 1.16,
            MovementGait::Jog => 1.08,
            MovementGait::SideStep
            | MovementGait::BackJog
            | MovementGait::BackSkip
            | MovementGait::Skip => 1.04,
            MovementGait::Walk | MovementGait::BackWalk => 0.92,
            MovementGait::Stand => 0.70,
        })
        .unwrap_or(1.0);
    let speed_cost = 1.0 + (speed_yps / 8.0).powi(2).clamp(0.0, 1.15) * 0.32;
    distance * gait_multiplier * speed_cost + acceleration * dt * 0.035
}

fn distance_to_segment(point: Vec2, a: Vec2, b: Vec2) -> f64 {
    let ab = b - a;
    let len2 = ab.dot(ab);
    if len2 <= 1e-9 {
        return point.distance(a);
    }
    let t = ((point - a).dot(ab) / len2).clamp(0.0, 1.0);
    point.distance(a + ab * t)
}

fn team_kinematic_average(snapshot: &WorldSnapshot, team: Team) -> (f64, f64) {
    let mut speed_total = 0.0;
    let mut acceleration_total = 0.0;
    let mut count = 0.0;
    for player in snapshot.players.iter().filter(|player| player.team == team) {
        speed_total += snapshot
            .player_velocity(player.id)
            .unwrap_or(player.velocity)
            .len();
        acceleration_total += snapshot
            .player_acceleration(player.id)
            .unwrap_or(player.acceleration)
            .len();
        count += 1.0;
    }
    if count <= 0.0 {
        (0.0, 0.0)
    } else {
        (speed_total / count, acceleration_total / count)
    }
}

fn soccer_decision_target_point(
    team: Team,
    action: &str,
    action_target: Option<&AgentActionTargetTrace>,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> (Option<Vec2>, Option<usize>) {
    let target_player = action_target.and_then(|target| target.player_id);
    let point = action_target
        .and_then(|target| target.point)
        .or_else(|| {
            target_player.and_then(|player_id| {
                before
                    .player_position(player_id)
                    .or_else(|| after.player_position(player_id))
            })
        })
        .or_else(|| match normalize_soccer_action_label(action) {
            "shoot" | "first-time-shot" | "first-time-header" => Some(Vec2::new(
                before.field_width * 0.5,
                team.goal_y(before.field_length),
            )),
            action
                if (is_pass_like_action(action) || matches!(action, "clearance" | "route-one"))
                    && after.ball.position.distance(before.ball.position) > 0.25 =>
            {
                Some(after.ball.position)
            }
            _ => None,
        });
    (point, target_player)
}

fn soccer_decision_context_for(
    player_id: usize,
    team: Team,
    action: &str,
    action_target: Option<&AgentActionTargetTrace>,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> SoccerDecisionContext {
    let actor_position = before
        .player_position(player_id)
        .or_else(|| after.player_position(player_id))
        .unwrap_or(before.ball.position);
    let actor_velocity = before
        .player_velocity(player_id)
        .or_else(|| after.player_velocity(player_id))
        .unwrap_or_else(Vec2::zero);
    let actor_acceleration = before
        .player_acceleration(player_id)
        .or_else(|| after.player_acceleration(player_id))
        .unwrap_or_else(Vec2::zero);
    let (target_point, target_player) =
        soccer_decision_target_point(team, action, action_target, before, after);
    let target_player_position = target_player.and_then(|target_id| {
        before
            .player_position(target_id)
            .or_else(|| after.player_position(target_id))
    });
    let target_player_velocity = target_player.and_then(|target_id| {
        before
            .player_velocity(target_id)
            .or_else(|| after.player_velocity(target_id))
    });
    let target_delta = target_point.map(|point| point - actor_position);
    let attack_dir = team.attack_dir();
    let target_distance_yards = target_delta.map(Vec2::len).unwrap_or(0.0);
    let target_forward_yards = target_delta
        .map(|delta| delta.y * attack_dir)
        .unwrap_or(0.0);
    let target_lateral_yards = target_delta.map(|delta| delta.x).unwrap_or(0.0);
    let target_angle_degrees = target_delta
        .map(|delta| angle_between_vectors_degrees(Vec2::new(0.0, attack_dir), delta))
        .unwrap_or(0.0);
    let action_ball_speed_yps = after.ball.velocity.len();
    let dribble_touch = action_target.and_then(|target| {
        if is_dribble_action_label(action) {
            target.dribble_touch
        } else {
            None
        }
    });
    let (
        dribble_touch_angle_bucket,
        dribble_touch_distance_yards,
        dribble_touch_distance_bin,
        dribble_touch_forward_class,
    ) = if let Some(touch) = dribble_touch {
        (
            Some(touch.angle_bucket),
            touch.distance_yards,
            dribble_touch_distance_bin(touch.distance_yards),
            dribble_touch_forward_class(touch.angle_bucket),
        )
    } else {
        (None, 0.0, 0, 0)
    };
    let (attacking_team_speed_yps, attacking_team_acceleration_yps2) =
        team_kinematic_average(before, team);
    let (defending_team_speed_yps, defending_team_acceleration_yps2) =
        team_kinematic_average(before, team.other());
    let loose_ball_race = loose_ball_race_context_for_snapshot(before, player_id);

    let mut nearest_defenders = before
        .players
        .iter()
        .filter(|player| player.team == team.other())
        .map(|defender| {
            let position = before
                .player_position(defender.id)
                .unwrap_or(defender.position);
            let velocity = before
                .player_velocity(defender.id)
                .unwrap_or(defender.velocity);
            let acceleration = before
                .player_acceleration(defender.id)
                .unwrap_or(defender.acceleration);
            let distance_yards = position.distance(actor_position);
            let lane_distance_yards = target_point
                .map(|target| distance_to_segment(position, actor_position, target))
                .unwrap_or(distance_yards);
            let angle_degrees = target_delta
                .map(|delta| angle_between_vectors_degrees(delta, position - actor_position))
                .unwrap_or(0.0);
            let closing_direction = (actor_position - position).normalized();
            let closing_speed_yps = (velocity - actor_velocity).dot(closing_direction);
            SoccerNearestDefenderContext {
                player_id: defender.id,
                position,
                velocity,
                acceleration,
                distance_yards,
                lane_distance_yards,
                angle_degrees,
                closing_speed_yps,
            }
        })
        .collect::<Vec<_>>();
    nearest_defenders.sort_by(|a, b| {
        let a_relevance = if target_point.is_some() {
            a.lane_distance_yards.min(a.distance_yards)
        } else {
            a.distance_yards
        };
        let b_relevance = if target_point.is_some() {
            b.lane_distance_yards.min(b.distance_yards)
        } else {
            b.distance_yards
        };
        a_relevance
            .partial_cmp(&b_relevance)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| {
                a.distance_yards
                    .partial_cmp(&b.distance_yards)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| {
                a.player_id
                    .partial_cmp(&b.player_id)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
    });
    nearest_defenders.truncate(3);

    SoccerDecisionContext {
        actor_position,
        actor_velocity,
        actor_acceleration,
        ball_position: before.ball.position,
        ball_velocity: before.ball.velocity,
        ball_acceleration: before.ball.acceleration,
        ball_jerk: before.ball.jerk,
        ball_forward_velocity_yps: before.ball.velocity.y * team.attack_dir(),
        ball_lateral_speed_yps: before.ball.velocity.x.abs(),
        ball_altitude_yards: before.ball.altitude_yards.max(0.0),
        ball_airborne: before.ball.altitude_yards > BALL_ROLLING_ALTITUDE_YARDS,
        loose_ball: loose_ball_race.loose_ball,
        loose_ball_fifty_fifty: loose_ball_race.fifty_fifty,
        loose_ball_team_time_advantage_seconds: loose_ball_race.team_time_advantage_seconds,
        loose_ball_player_time_to_ball_seconds: loose_ball_race.player_time_to_ball_seconds,
        target_point,
        target_player,
        target_player_position,
        target_player_velocity,
        target_distance_yards,
        target_forward_yards,
        target_lateral_yards,
        target_angle_degrees,
        action_ball_speed_yps,
        dribble_touch_angle_bucket,
        dribble_touch_distance_yards,
        dribble_touch_distance_bin,
        dribble_touch_forward_class,
        nearest_defenders,
        attacking_team_speed_yps,
        defending_team_speed_yps,
        attacking_team_acceleration_yps2,
        defending_team_acceleration_yps2,
        tracking_source_frame_id: None,
        next_tracking_source_frame_id: None,
        tracking_confidence: 0.0,
    }
}

fn player_normalized_last_action(player: &PlayerSnapshot) -> &str {
    player
        .last_decision
        .as_ref()
        .map(|decision| normalize_soccer_action_label(&decision.action))
        .unwrap_or("hold")
}

fn team_average_defensive_depth(snapshot: &WorldSnapshot, team: Team) -> f64 {
    let own_goal_y = team.other().goal_y(snapshot.field_length);
    let mut total = 0.0;
    let mut count = 0.0;
    for player in snapshot.players.iter().filter(|player| player.team == team) {
        let position = snapshot
            .player_position(player.id)
            .unwrap_or(player.position);
        total += (position.y - own_goal_y).abs();
        count += 1.0;
    }
    if count > 0.0 {
        total / count
    } else {
        snapshot.field_length
    }
}

fn teamwork_progress_signal(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    possession_team: Team,
) -> Option<TeamworkProgressSignal> {
    if before.controlled_possession_team() != Some(possession_team)
        || !team_has_constructive_upfield_possession(after, possession_team)
    {
        return None;
    }

    let ball_relocation = before.ball.position.distance(after.ball.position);
    if ball_relocation < TEAMWORK_PROGRESS_MIN_RELOCATION_YARDS {
        return None;
    }

    let ball_progress =
        (after.ball.position.y - before.ball.position.y) * possession_team.attack_dir();
    let all_field_players = team_field_player_ids(before, possession_team);
    let near_ball_players = nearest_team_field_players_to_ball(
        before,
        possession_team,
        TEAMWORK_PROGRESS_NEAR_BALL_PLAYERS,
    );
    if all_field_players.is_empty() || near_ball_players.is_empty() {
        return None;
    }

    let team_centroid_progress =
        centroid_upfield_progress(before, after, possession_team, &all_field_players);
    let near_ball_centroid_progress =
        centroid_upfield_progress(before, after, possession_team, &near_ball_players);
    let advancing_threshold = (before.dt_seconds.max(0.0) * 0.18).clamp(0.015, 0.12);
    let advancing_supporters = near_ball_players
        .iter()
        .filter(|player_id| {
            player_upfield_progress(before, after, possession_team, **player_id)
                >= advancing_threshold
        })
        .count();
    if advancing_supporters < 3 && near_ball_centroid_progress < advancing_threshold * 0.75 {
        return None;
    }

    if ball_progress <= 0.05
        && near_ball_centroid_progress <= advancing_threshold * 0.5
        && team_centroid_progress <= advancing_threshold * 0.35
    {
        return None;
    }

    let retained_control = after.controlled_possession_team() == Some(possession_team);
    let support_ratio =
        (advancing_supporters as f64 / TEAMWORK_PROGRESS_NEAR_BALL_PLAYERS as f64).clamp(0.0, 1.0);
    let coordinated_multiplier = if ball_progress > 0.10 && near_ball_centroid_progress > 0.02 {
        1.0 + support_ratio * 0.36
    } else {
        1.0
    };
    let possession_credit = if retained_control { 0.018 } else { 0.006 };
    let forward_drive = ball_progress.max(0.0).clamp(0.0, 14.0) * 0.055
        + near_ball_centroid_progress.max(0.0).clamp(0.0, 6.0) * 0.22
        + team_centroid_progress.max(0.0).clamp(0.0, 4.0) * 0.16;
    let backward_cost = (-ball_progress).max(0.0).clamp(0.0, 10.0) * 0.055
        + (-near_ball_centroid_progress).max(0.0).clamp(0.0, 5.0) * 0.14
        + (-team_centroid_progress).max(0.0).clamp(0.0, 4.0) * 0.08;
    let attacking_credit = (possession_credit + forward_drive * coordinated_multiplier
        - backward_cost)
        .clamp(0.0, 0.62);
    if attacking_credit < TEAMWORK_PROGRESS_MIN_CREDIT {
        return None;
    }

    let mut support_players = Vec::new();
    if let Some(holder) = before.ball.holder {
        support_players.push(holder);
    }
    support_players.extend(near_ball_players);
    if let Some(holder) = after.ball.holder {
        support_players.push(holder);
    }
    let support_players = unique_team_player_ids(support_players, before, possession_team);

    Some(TeamworkProgressSignal {
        possession_team,
        ball_progress,
        team_centroid_progress,
        near_ball_centroid_progress,
        attacking_credit,
        support_players,
    })
}

fn possession_chase_signal(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    possession_team: Team,
) -> Option<PossessionChaseSignal> {
    if before.controlled_possession_team() != Some(possession_team)
        || after.controlled_possession_team() != Some(possession_team)
    {
        return None;
    }

    let ball_relocation = before.ball.position.distance(after.ball.position);
    if ball_relocation < POSSESSION_CHASE_MIN_BALL_RELOCATION_YARDS {
        return None;
    }

    let defending_team = possession_team.other();
    let mut attacking_load = 0.0;
    let mut defensive_load = 0.0;
    let mut active_defender_loads = Vec::new();
    let mut defender_speed_total = 0.0;
    let mut defender_count = 0.0;

    for player in &before.players {
        let load = player_motion_load(before, after, player.id);
        if player.team == possession_team {
            attacking_load += load;
            continue;
        }
        defensive_load += load;
        defender_count += 1.0;
        defender_speed_total += load / before.dt_seconds.max(1e-6);

        let Some(after_player) = snapshot_player(after, player.id) else {
            continue;
        };
        let action = player_normalized_last_action(after_player);
        let before_position = before.player_position(player.id).unwrap_or(player.position);
        let distance_to_ball = before_position.distance(before.ball.position);
        let moved = player_motion_distance(before, after, player.id);
        let speed_yps = moved / before.dt_seconds.max(1e-6);
        let active_chase = matches!(action, "defend" | "tackle")
            && distance_to_ball <= 38.0
            && (speed_yps >= 1.15 || moved >= 0.45);
        if active_chase {
            active_defender_loads.push((player.id, load));
        }
    }

    if active_defender_loads.len() < POSSESSION_CHASE_MIN_ACTIVE_DEFENDERS {
        return None;
    }

    let average_defender_load_rate = if defender_count > 0.0 {
        defender_speed_total / defender_count
    } else {
        0.0
    };
    let average_defensive_depth = team_average_defensive_depth(before, defending_team);
    let compact_low_block = average_defensive_depth <= 34.0 && average_defender_load_rate < 1.25;
    if compact_low_block {
        return None;
    }

    let load_advantage = defensive_load - attacking_load * 1.08;
    if load_advantage <= 0.0 {
        return None;
    }

    let lateral_switch_bonus =
        1.0 + ((after.ball.position.x - before.ball.position.x).abs() / 26.0).clamp(0.0, 0.45);
    let attacking_credit = (load_advantage / 11.0 * 0.070 * lateral_switch_bonus).clamp(0.0, 0.48);
    if attacking_credit < POSSESSION_CHASE_MIN_CREDIT {
        return None;
    }

    let active_load_total = active_defender_loads
        .iter()
        .map(|(_, load)| *load)
        .sum::<f64>()
        .max(1e-6);
    let defender_penalties = active_defender_loads
        .into_iter()
        .filter_map(|(player_id, load)| {
            let share = load / active_load_total;
            let amount = -(attacking_credit * 0.78 * share).clamp(0.015, 0.16);
            (amount.abs() >= 0.015).then_some(PlayerRewardLoad {
                player_id,
                amount,
                load,
            })
        })
        .collect::<Vec<_>>();

    Some(PossessionChaseSignal {
        possession_team,
        defending_team,
        attacking_load,
        defensive_load,
        attacking_credit,
        defender_penalties,
    })
}

fn defensive_relaxation_signal(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    possession_team: Team,
) -> Option<DefensiveRelaxationSignal> {
    if before.controlled_possession_team() != Some(possession_team)
        || after.controlled_possession_team() != Some(possession_team)
    {
        return None;
    }

    let ball_relocation = before.ball.position.distance(after.ball.position);
    if ball_relocation < POSSESSION_CHASE_MIN_BALL_RELOCATION_YARDS {
        return None;
    }

    let defending_team = possession_team.other();
    let attacking_goal_y = possession_team.goal_y(before.field_length);
    let yards_to_goal = (attacking_goal_y - after.ball.position.y).abs();
    let ball_progress =
        (after.ball.position.y - before.ball.position.y) * possession_team.attack_dir();
    let lateral_shift = (after.ball.position.x - before.ball.position.x).abs();
    let threat_increased = yards_to_goal <= DEFENSIVE_RELAXATION_THREAT_YARDS
        || ball_progress > 0.80
        || lateral_shift > 5.0;
    if !threat_increased {
        return None;
    }

    let average_defensive_depth = team_average_defensive_depth(before, defending_team);
    if average_defensive_depth <= 34.0 && yards_to_goal > 24.0 {
        return None;
    }

    let dt = before.dt_seconds.max(1e-6);
    let mut defender_penalties = Vec::new();
    let mut opening_pressure = 0.0;
    for defender in before
        .players
        .iter()
        .filter(|player| player.team == defending_team)
    {
        let Some(after_defender) = snapshot_player(after, defender.id) else {
            continue;
        };
        let before_position = before
            .player_position(defender.id)
            .unwrap_or(defender.position);
        let after_position = after
            .player_position(defender.id)
            .unwrap_or(after_defender.position);
        let moved = before_position.distance(after_position);
        let speed_yps = moved / dt;
        let distance_to_after_ball = after_position.distance(after.ball.position);
        if distance_to_after_ball > 36.0 && yards_to_goal > 30.0 {
            continue;
        }

        let action = player_normalized_last_action(after_defender);
        let passive = speed_yps < 0.75
            && !matches!(action, "tackle")
            && (!matches!(action, "defend") || moved < 0.18);
        if !passive {
            continue;
        }

        let fatigue = after_defender.fatigue.clamp(0.0, 1.0);
        let stamina = ability01(after_defender.skills.stamina);
        let energy_reserve = ((1.0 - fatigue) * 0.62 + stamina * 0.38).clamp(0.0, 1.0);
        let proximity_weight = ((36.0 - distance_to_after_ball) / 36.0).clamp(0.0, 1.0);
        let danger_weight =
            ((DEFENSIVE_RELAXATION_THREAT_YARDS - yards_to_goal) / 36.0).clamp(0.15, 1.0);
        let movement_weight =
            ((ball_progress.max(0.0) + lateral_shift * 0.14) / 4.5).clamp(0.0, 1.0);
        let opening = proximity_weight * danger_weight * (0.58 + movement_weight * 0.42);
        if opening < 0.10 {
            continue;
        }

        let penalty_scale = 0.55 + energy_reserve * 0.75;
        let amount = -(0.026 + opening * 0.095 * penalty_scale).clamp(0.025, 0.18);
        opening_pressure += opening * (0.70 + fatigue * 0.30);
        defender_penalties.push(PlayerRewardLoad {
            player_id: defender.id,
            amount,
            load: 0.0,
        });
    }

    let min_passive_defenders = if yards_to_goal <= 24.0 { 1 } else { 2 };
    if defender_penalties.len() < min_passive_defenders {
        return None;
    }

    let attacking_credit = (0.030 + opening_pressure * 0.040).clamp(0.035, 0.34);
    Some(DefensiveRelaxationSignal {
        possession_team,
        defending_team,
        attacking_credit,
        defender_penalties,
    })
}

fn soccer_goal_credit_action_is_relevant(action: &str) -> bool {
    matches!(
        normalize_soccer_action_label(action),
        "shoot"
            | "first-time-shot"
            | "first-time-header"
            | "pass"
            | "killer-pass"
            | "aerial-pass"
            | "flank-low-cross"
            | "flank-high-cross"
            | "first-time-pass"
            | "dribble"
            | "carry-forward"
            | "carry-out-left"
            | "carry-out-right"
            | "protect-ball"
            | "side-step"
            | "left-cut"
            | "right-cut"
            | "nutmeg"
            | "fake-left-cut-right"
            | "fake-right-cut-left"
            | "hold-up-flank"
            | "space"
            | "support-shape"
            | "support-roam"
            | "check-to-ball"
            | "run-in-behind"
            | "wide-outlet"
            | "shot-creation-run"
            | "overlap-run"
            | "support-push-up"
            | "support-screen"
            | "control-touch"
            | "set-play-run"
            | "clearance"
            | "route-one"
    )
}

fn soccer_context_defender_distance(transition: &SoccerLearningTransition, fallback: f64) -> f64 {
    transition
        .decision_context
        .nearest_defenders
        .first()
        .map(|defender| defender.distance_yards)
        .filter(|distance| distance.is_finite())
        .unwrap_or(fallback)
}

fn soccer_context_lane_clearance(transition: &SoccerLearningTransition) -> f64 {
    transition
        .decision_context
        .nearest_defenders
        .iter()
        .map(|defender| defender.lane_distance_yards)
        .filter(|distance| distance.is_finite())
        .fold(f64::INFINITY, f64::min)
}

fn goalmouth_centrality(position: Vec2, field_width_yards: f64) -> f64 {
    if !position.x.is_finite() || field_width_yards <= 0.0 {
        return 0.0;
    }
    let half_width = (field_width_yards * 0.5).max(1.0);
    (1.0 - ((position.x - field_width_yards * 0.5).abs() / half_width)).clamp(0.0, 1.0)
}

fn attacking_goal_line_depth_yards(team: Team, position: Vec2, field_length_yards: f64) -> f64 {
    (team.goal_y(field_length_yards) - position.y).abs()
}

fn soccer_goal_credit_pass_weight_fit(context: &SoccerDecisionContext) -> f64 {
    if context.target_distance_yards <= 1.0 || context.action_ball_speed_yps <= 1e-6 {
        return 0.45;
    }
    let ideal_speed = (context.target_distance_yards * 0.38 + 8.0).clamp(7.0, 28.0);
    (1.0 - (context.action_ball_speed_yps - ideal_speed).abs() / ideal_speed.max(1.0))
        .clamp(0.0, 1.0)
}

fn soccer_goal_credit_transition_score(
    transition: &SoccerLearningTransition,
    age_ticks: u64,
) -> f64 {
    let action = normalize_soccer_action_label(&transition.action);
    if !soccer_goal_credit_action_is_relevant(action) {
        return 0.0;
    }

    let obs = &transition.observation;
    let next_obs = &transition.next_observation;
    let context = &transition.decision_context;
    let pressure = obs.perceived_pressure.clamp(0.0, 1.0);
    let nearest_defender =
        soccer_context_defender_distance(transition, obs.nearest_opponent_distance);
    let defender_space = (nearest_defender / 14.0).clamp(0.0, 1.0);
    let lane_clearance = soccer_context_lane_clearance(transition);
    let lane_score = if lane_clearance.is_finite() {
        (lane_clearance / 8.0).clamp(0.0, 1.0)
    } else {
        obs.floor_pass_lane_score.clamp(0.0, 1.0)
    };
    let forward_gain = (obs.yards_to_goal - next_obs.yards_to_goal).clamp(-18.0, 32.0);
    let target_forward = (context.target_forward_yards / 34.0).clamp(-0.75, 1.0);
    let target_angle_fit =
        (1.0 - (context.target_angle_degrees - 34.0).abs() / 92.0).clamp(0.0, 1.0);
    let dense_signal = transition.reward.max(0.0).min(6.0) * 0.12;
    let base = match action {
        "shoot" | "first-time-shot" | "first-time-header" => {
            let angle = (obs.opponent_goal_angle_degrees / 42.0).clamp(0.0, 1.0);
            let range = (1.0 - (obs.yards_to_goal / 42.0)).clamp(0.0, 1.0);
            0.65 + obs.shot_on_frame_probability.clamp(0.0, 1.0) * 1.20
                + obs.shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 1.45
                + angle * 0.38
                + range * 0.28
                + defender_space * 0.22
                - obs.shot_block_probability.clamp(0.0, 1.0) * 0.64
                - pressure * 0.18
                + dense_signal
        }
        "pass" | "killer-pass" | "aerial-pass" | "flank-low-cross" | "flank-high-cross"
        | "first-time-pass" => {
            let completion = if matches!(action, "aerial-pass" | "flank-high-cross") {
                obs.expected_aerial_pass_completion
                    .max(obs.expected_pass_completion * 0.82)
            } else {
                obs.expected_pass_completion
            }
            .clamp(0.0, 1.0);
            let receiver_openness = obs
                .best_pass_receiver_openness
                .max(obs.best_aerial_pass_receiver_openness)
                .clamp(0.0, 1.0);
            let weight_fit = soccer_goal_credit_pass_weight_fit(context);
            let stride_fit = pass_into_stride_fit_for_context(context, transition.team);
            let pressure_release = pressure * completion;
            let backward_penalty = if context.target_forward_yards < -4.0 && pressure < 0.35 {
                0.52
            } else {
                0.0
            };
            0.32 + completion * 1.12
                + receiver_openness * 0.72
                + obs.floor_pass_lane_score.clamp(0.0, 1.0) * 0.42
                + lane_score * 0.46
                + target_angle_fit * 0.34
                + target_forward.max(0.0) * 0.58
                + (forward_gain / 24.0).clamp(-0.25, 1.0) * 0.62
                + pressure_release * 0.28
                + weight_fit * 0.48
                + stride_fit * 0.42
                - obs.aerial_pass_interception_risk.clamp(0.0, 1.0) * 0.54
                - backward_penalty
                + dense_signal
        }
        "dribble"
        | "carry-forward"
        | "carry-out-left"
        | "carry-out-right"
        | "protect-ball"
        | "hold-up-flank"
        | "side-step"
        | "left-cut"
        | "right-cut"
        | "nutmeg"
        | "fake-left-cut-right"
        | "fake-right-cut-left" => {
            let goal_approach_fit = ((GOAL_APPROACH_CARRY_YARDS - obs.yards_to_goal)
                / GOAL_APPROACH_CARRY_YARDS)
                .clamp(0.0, 1.0);
            let endline_trap_risk = if obs.yards_to_goal <= GOAL_APPROACH_CARRY_YARDS
                && next_obs.yards_to_goal <= 6.0
                && next_obs.goal_attack_window_score <= obs.goal_attack_window_score + 0.02
            {
                0.38
            } else {
                0.0
            };
            let acceleration = (context.actor_acceleration.len() / 10.0).clamp(0.0, 1.0);
            let speed = (context.actor_velocity.len() / 8.5).clamp(0.0, 1.0);
            let defender_stress = (1.0 - defender_space) * pressure.max(0.25);
            0.34 + (obs.forward_dribble_space_yards / 18.0).clamp(0.0, 1.0) * 0.86
                + obs.open_space_score.clamp(0.0, 1.0) * 0.34
                + target_forward.max(0.0) * 0.42
                + (forward_gain / 16.0).clamp(-0.20, 1.0) * 0.52
                + goal_approach_fit * next_obs.goal_attack_window_score.clamp(0.0, 1.0) * 0.44
                + speed * 0.18
                + acceleration * 0.22
                + defender_stress * 0.25
                - obs.immediate_dispossession_risk.clamp(0.0, 1.0) * 0.80
                - obs.fatigue.clamp(0.0, 1.0) * 0.18
                - endline_trap_risk
                + dense_signal
        }
        "clearance" | "route-one" => {
            let weight_fit = soccer_goal_credit_pass_weight_fit(context);
            let own_goal_urgency = (1.0 - obs.yards_to_own_goal / 36.0).clamp(0.0, 1.0);
            0.26 + pressure * 0.42
                + own_goal_urgency * 0.52
                + target_forward.max(0.0) * 0.50
                + lane_score * 0.22
                + weight_fit * 0.30
                + dense_signal
        }
        _ => {
            0.18 + obs.open_space_score.clamp(0.0, 1.0) * 0.50
                + obs.team_spacing_score.clamp(0.0, 1.0) * 0.36
                + target_forward.max(0.0) * 0.22
                + defender_space * 0.14
                + dense_signal
        }
    };
    let recency = 1.0 / (1.0 + age_ticks as f64 / 180.0);
    (base * recency).max(0.0)
}

fn soccer_transition_reward(
    player: &PlayerAgent,
    decision: &AgentDecisionTrace,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    score_home_before: u32,
    score_away_before: u32,
    score_home_after: u32,
    score_away_after: u32,
    infer_discrete_events: bool,
) -> f64 {
    soccer_transition_reward_with_tactics(
        player,
        decision,
        before,
        after,
        score_home_before,
        score_away_before,
        score_home_after,
        score_away_after,
        infer_discrete_events,
        &SoccerTacticalLearningWeights::default(),
    )
}

fn soccer_transition_reward_with_tactics(
    player: &PlayerAgent,
    decision: &AgentDecisionTrace,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    score_home_before: u32,
    score_away_before: u32,
    score_home_after: u32,
    score_away_after: u32,
    infer_discrete_events: bool,
    tactical_learning: &SoccerTacticalLearningWeights,
) -> f64 {
    let action = normalize_soccer_action_label(&decision.action);
    let mut reward =
        dense_soccer_transition_reward(player, decision, before, after, action, tactical_learning);

    if !infer_discrete_events {
        return reward;
    }

    let (before_for, before_against, after_for, after_against) = match player.team {
        Team::Home => (
            score_home_before,
            score_away_before,
            score_home_after,
            score_away_after,
        ),
        Team::Away => (
            score_away_before,
            score_home_before,
            score_away_after,
            score_home_after,
        ),
    };
    reward += (after_for as f64 - before_for as f64) * 100.0;
    if after_against > before_against {
        reward -= if matches!(player.role, PlayerRole::Goalkeeper | PlayerRole::Defender) {
            8.0
        } else {
            2.0
        };
    }

    if is_pass_like_action(action) {
        if let Some(holder) = after.ball.holder {
            if holder != player.id {
                if let Some(receiver_player) = after
                    .players
                    .iter()
                    .find(|candidate| candidate.id == holder && candidate.team == player.team)
                {
                    let target = after.player_position(holder).unwrap_or(after.ball.position);
                    let origin = before
                        .player_position(player.id)
                        .unwrap_or(before.ball.position);
                    reward +=
                        completed_pass_reward(player.team, origin, target, before.field_length);
                    let flight = pass_like_action_flight(action).unwrap_or(PassFlight::Floor);
                    let is_cross = matches!(action, "flank-low-cross" | "flank-high-cross")
                        || pass_would_be_cross(
                            origin,
                            target,
                            player.team,
                            before.field_width,
                            before.field_length,
                        );
                    reward += completed_cross_reward_from_parts(
                        player.team,
                        flight,
                        is_cross,
                        origin,
                        target,
                        receiver_player.role,
                        &receiver_player.skills,
                        before.field_width,
                        before.field_length,
                    );
                    let action_context = soccer_decision_context_for(
                        player.id,
                        player.team,
                        &decision.action,
                        decision.action_target.as_ref(),
                        before,
                        after,
                    );
                    let receiver_openness = pass_receiver_openness_for_snapshots_with_teammates(
                        &after.players,
                        player.team,
                        target,
                        decision
                            .action_target
                            .as_ref()
                            .and_then(|target| target.player_id),
                    );
                    reward += completed_pass_anticipation_reward_from_context(
                        &action_context,
                        player.team,
                        receiver_openness,
                    );
                    reward += completed_killer_pass_reward_from_parts(
                        player.team,
                        flight,
                        is_cross,
                        origin,
                        target,
                        receiver_player.role,
                        &receiver_player.skills,
                        before.field_width,
                        before.field_length,
                        receiver_openness,
                        pass_into_stride_fit_for_context(&action_context, player.team),
                    );
                }
            }
            assert!(
                (135.0..=225.0).contains(&player.skills.weight_pounds),
                "{} body weight out of range: {}",
                player.name,
                player.skills.weight_pounds
            );
        }
    }

    if before.possession_team() == Some(player.team.other()) && after.ball.holder == Some(player.id)
    {
        reward += 10.0;
    }

    reward
}

fn dense_soccer_transition_reward(
    player: &PlayerAgent,
    decision: &AgentDecisionTrace,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    action: &str,
    tactical_learning: &SoccerTacticalLearningWeights,
) -> f64 {
    let before_pos = before.player_position(player.id).unwrap_or(player.position);
    let after_pos = after.player_position(player.id).unwrap_or(before_pos);
    let moved_yards = before_pos.distance(after_pos);
    let before_obs = &decision.observation;
    let after_obs = after.observation_for(player.id);
    let before_possession = before.controlled_possession_team();
    let after_possession = after.controlled_possession_team();
    let attack_dir = player.team.attack_dir();
    let ball_forward = (after.ball.position.y - before.ball.position.y) * attack_dir;
    let player_forward = (after_pos.y - before_pos.y) * attack_dir;
    let mut reward = 0.0;
    let spacing_mode = before.team_spacing_mode_for(player.team);
    let spacing_delta = spacing_mode
        .map(|mode| {
            let before_score = before.team_spacing_score_for_candidate(
                player.team,
                Some(player.id),
                before_pos,
                mode,
            );
            let after_score = after.team_spacing_score_for_candidate(
                player.team,
                Some(player.id),
                after_pos,
                mode,
            );
            (before_score, after_score, after_score - before_score)
        })
        .unwrap_or((0.0, 0.0, 0.0));

    if before_obs.receiving_pending_pass {
        reward += pending_pass_reception_reward(
            player.id,
            player.team,
            action,
            before_pos,
            after_pos,
            before,
            after,
            before_obs,
        );
    }

    if before.ball.holder == Some(player.id) {
        let own_half_holder =
            pass_origin_in_own_half(player.team, before.ball.position, before.field_length);
        let own_goal_relief =
            ball_distance_from_own_goal(player.team, after.ball.position, after.field_length)
                - ball_distance_from_own_goal(
                    player.team,
                    before.ball.position,
                    before.field_length,
                );
        if after_possession == Some(player.team) {
            reward += 0.09;
        } else if after_possession == Some(player.team.other()) {
            reward -= intentional_long_ball_loss_penalty(
                action,
                own_half_holder,
                ball_forward,
                own_goal_relief,
                false,
            )
            .unwrap_or(if own_half_holder { 3.5 } else { 2.2 });
        } else {
            reward -= intentional_long_ball_loss_penalty(
                action,
                own_half_holder,
                ball_forward,
                own_goal_relief,
                true,
            )
            .unwrap_or(if own_half_holder { 0.85 } else { 0.55 });
        }
        reward += ball_forward.clamp(-8.0, 14.0) * 0.15;
        if own_half_holder {
            reward += ball_forward.clamp(-8.0, 16.0) * 0.11;
            if ball_forward < -1.25 && before_obs.perceived_pressure < 0.25 {
                reward -= 2.0;
            }
            if is_pass_like_action(action)
                && ball_forward < -1.25
                && before_obs.perceived_pressure < 0.35
            {
                reward -= 1.7;
            }
        }
        if is_pass_like_action(action) {
            let decision_context = soccer_decision_context_for(
                player.id,
                player.team,
                &decision.action,
                decision.action_target.as_ref(),
                before,
                after,
            );
            reward -= low_pressure_forced_pass_penalty_points(
                before_obs,
                &decision_context,
                pass_like_action_flight(action).unwrap_or(PassFlight::Floor),
                after_possession == Some(player.team),
            );
            if ball_forward > 1.25 {
                reward +=
                    ball_forward.clamp(0.0, 24.0) * DENSE_FORWARD_PASS_PROGRESS_REWARD_PER_YARD;
            } else if ball_forward.abs() <= 1.25 && before_obs.perceived_pressure < 0.30 {
                reward -= 0.22;
            }
            reward += pass_into_stride_fit_for_context(&decision_context, player.team) * 0.16;
        }
        reward += intentional_long_ball_release_reward(
            player,
            action,
            before,
            after,
            before_obs,
            ball_forward,
            own_goal_relief,
        );
        reward += (before_obs.yards_to_goal - after_obs.yards_to_goal).clamp(-8.0, 8.0) * 0.07;
        reward += goalmouth_dribble_learning_reward(
            player, action, before_obs, &after_obs, before, after, before_pos, after_pos,
        );
        if is_dribble_action_label(action) && after_possession == Some(player.team) {
            reward -= excessive_hold_penalty_points(before_obs, ability01(player.skills.dribbling));
            let carry_progress = ball_forward.max(player_forward).clamp(-4.0, 18.0);
            if carry_progress > 0.0 {
                let role_multiplier = match player.role {
                    PlayerRole::Forward => 1.18,
                    PlayerRole::Midfielder => 1.04,
                    PlayerRole::Defender => 0.86,
                    PlayerRole::Goalkeeper => 0.30,
                };
                let pressure_multiplier =
                    (1.0 - before_obs.perceived_pressure.clamp(0.0, 1.0) * 0.22).clamp(0.70, 1.0);
                reward += carry_progress
                    * DENSE_FORWARD_CARRY_PROGRESS_REWARD_PER_YARD
                    * role_multiplier
                    * pressure_multiplier;
                if carry_progress >= 6.0 {
                    reward += 0.18 * role_multiplier;
                }
            } else if carry_progress < -1.25 && before_obs.perceived_pressure < 0.30 {
                reward -= 0.42;
            }
        }
        if is_dribble_action_label(action) {
            reward -= pressured_stale_dribble_learning_penalty_points(
                before_obs,
                ability01(player.skills.dribbling),
                ball_forward,
                player_forward,
                after_possession == Some(player.team),
            );
        }
        if matches!(
            action,
            "dribble"
                | "carry-forward"
                | "carry-out-left"
                | "carry-out-right"
                | "protect-ball"
                | "side-step"
                | "left-cut"
                | "right-cut"
                | "nutmeg"
                | "fake-left-cut-right"
                | "fake-right-cut-left"
                | "hold-up-flank"
                | "set-play-run"
                | "pass"
                | "killer-pass"
                | "aerial-pass"
                | "flank-low-cross"
                | "flank-high-cross"
                | "shoot"
                | "clearance"
                | "route-one"
        ) {
            reward += 0.08;
        }
        if action == "hold-up-flank" {
            let isolated_striker_state =
                before.striker_hold_up_flank_target_for(player.id).is_some();
            let lateral_carry = (after_pos.x - before_pos.x).abs();
            if isolated_striker_state && after_possession == Some(player.team) {
                reward += 0.42
                    + lateral_carry.clamp(0.0, 8.0) * 0.055
                    + player_forward.clamp(-1.0, 5.0) * 0.035;
            } else {
                reward -= 0.22;
            }
        }
        if let Some(TeamSpacingMode::InPossession) = spacing_mode {
            let weight = before.possession_spacing_weight(player.team);
            reward += spacing_delta.2.clamp(-1.0, 1.0) * 0.05 * weight;
        }
        reward += tactical_shape_reward(
            player,
            before,
            after,
            before_pos,
            after_pos,
            spacing_mode,
            spacing_delta,
            tactical_learning,
        );
        if moved_yards < 0.08 && ball_forward.abs() < 0.08 {
            reward -= 0.55;
        }
    } else if before_possession == Some(player.team) {
        let own_half_team_possession =
            pass_origin_in_own_half(player.team, before.ball.position, before.field_length);
        reward +=
            (after_obs.open_space_score - before_obs.open_space_score).clamp(-5.0, 5.0) * 0.12;
        reward += match player.role {
            PlayerRole::Goalkeeper => player_forward.clamp(-4.0, 4.0) * 0.01,
            PlayerRole::Defender => player_forward.clamp(-5.0, 8.0) * 0.025,
            PlayerRole::Midfielder => player_forward.clamp(-6.0, 12.0) * 0.060,
            PlayerRole::Forward => player_forward.clamp(-6.0, 10.0) * 0.055,
        };
        if own_half_team_possession && player.role != PlayerRole::Goalkeeper {
            reward += player_forward.clamp(-5.0, 12.0) * 0.055;
            if player_forward < -0.35 {
                reward -= 0.16;
            }
        }
        if let Some(TeamSpacingMode::InPossession) = spacing_mode {
            let weight = before.possession_spacing_weight(player.team);
            reward += spacing_delta.2.clamp(-1.0, 1.0) * 0.20 * weight;
            reward += spacing_delta.1.clamp(-1.0, 1.0) * 0.045 * weight;
        }
        if is_attacking_support_action_label(action)
            && !matches!(player.role, PlayerRole::Goalkeeper)
        {
            reward += attacking_support_urgency_learning_reward(
                player, action, before, after, before_pos, after_pos,
            );
            reward += flank_cross_arrival_support_learning_reward(
                player, action, before, before_pos, after_pos,
            );
            let lateral = (after_pos.x - before_pos.x).abs();
            if lateral > 2.5 {
                let required_forward = lateral * SUPPORT_MIN_UPFIELD_PER_LATERAL_YARD;
                let forward_ratio = (player_forward / required_forward.max(0.8)).clamp(-1.0, 2.0);
                if player_forward >= required_forward {
                    reward += 0.12 + forward_ratio * 0.08;
                } else {
                    reward -= 0.10 + (required_forward - player_forward).clamp(0.0, 5.0) * 0.035;
                }
            } else if player_forward > 0.35 {
                reward += 0.06;
            }
            if player.role == PlayerRole::Midfielder
                && (player.home_position.x < before.field_width * 0.30
                    || player.home_position.x > before.field_width * 0.70)
            {
                let before_width =
                    (before_pos.x - before.field_width * 0.5).abs() / (before.field_width * 0.5);
                let after_width =
                    (after_pos.x - after.field_width * 0.5).abs() / (after.field_width * 0.5);
                reward += (after_width - before_width).clamp(-0.4, 0.4) * 0.42;
                reward += after
                    .space_score_at(after_pos, player.team)
                    .clamp(0.0, 18.0)
                    * 0.006;
            }
        }
        reward += tactical_shape_reward(
            player,
            before,
            after,
            before_pos,
            after_pos,
            spacing_mode,
            spacing_delta,
            tactical_learning,
        );
        reward += ball_forward.clamp(-8.0, 12.0) * 0.025;
        if is_attacking_support_action_label(action) && moved_yards > 0.15 {
            reward += 0.07;
        }
        if moved_yards < 0.06 && !matches!(player.role, PlayerRole::Goalkeeper) {
            reward -= 0.18;
        }
    } else if before_possession == Some(player.team.other()) {
        let before_target = before
            .ball
            .holder
            .and_then(|holder| before.player_position(holder))
            .unwrap_or(before.ball.position);
        let after_target = before
            .ball
            .holder
            .and_then(|holder| after.player_position(holder))
            .unwrap_or(after.ball.position);
        let before_distance = before_pos.distance(before_target);
        let after_distance = after_pos.distance(after_target);
        let tracking_skill = ability01(player.skills.defensive_tracking);
        reward +=
            (before_distance - after_distance).clamp(-6.0, 6.0) * (0.055 + tracking_skill * 0.045);
        reward += defensive_goal_side_reward(player.team, before_pos, before);
        if player.role == PlayerRole::Goalkeeper {
            let before_line_score =
                goalkeeper_ball_goal_line_alignment_score(player.team, before_pos, before);
            let after_line_score =
                goalkeeper_ball_goal_line_alignment_score(player.team, after_pos, after);
            reward += after_line_score.clamp(-1.0, 1.0) * 0.34
                + (after_line_score - before_line_score).clamp(-1.0, 1.0) * 0.62;
        }
        reward += defensive_cross_arrival_coverage_learning_reward(
            player, action, before, before_pos, after_pos,
        );
        let before_goal_line_shape =
            defensive_goal_line_spacing_score(player.team, before_pos, before);
        let after_goal_line_shape =
            defensive_goal_line_spacing_score(player.team, after_pos, after);
        reward += after_goal_line_shape * 0.08
            + (after_goal_line_shape - before_goal_line_shape).clamp(-1.0, 1.0) * 0.18;
        if let Some(TeamSpacingMode::Defending) = spacing_mode {
            reward += spacing_delta.2.clamp(-1.0, 1.0) * 0.09;
            reward += spacing_delta.1.clamp(-1.0, 1.0) * 0.025;
        }
        reward += tactical_shape_reward(
            player,
            before,
            after,
            before_pos,
            after_pos,
            spacing_mode,
            spacing_delta,
            tactical_learning,
        );
        let opponent_forward =
            (after.ball.position.y - before.ball.position.y) * player.team.other().attack_dir();
        reward -= opponent_forward.clamp(-8.0, 12.0) * 0.035;
        if matches!(action, "defend" | "tackle") && moved_yards > 0.10 {
            reward += 0.06;
        }
        if after_possession == Some(player.team) {
            reward += if after.ball.holder == Some(player.id) {
                1.2
            } else {
                0.28
            };
        }
        if moved_yards < 0.06 && before_distance > 7.0 {
            reward -= 0.22;
        }
    } else {
        let before_distance = before_pos.distance(before.ball.position);
        let after_distance = after_pos.distance(after.ball.position);
        reward += (before_distance - after_distance).clamp(-8.0, 8.0) * 0.10;
        reward += loose_ball_contest_learning_reward(
            player, action, before, after, before_obs, before_pos, after_pos,
        );
        if loose_ball_fifty_fifty_duel_for(before, player.id) {
            reward += if after_distance < before_distance {
                0.75
            } else {
                -0.35
            };
        }
        if after_possession == Some(player.team) {
            reward += if after.ball.holder == Some(player.id) {
                0.95
            } else {
                0.24
            };
        }
        if moved_yards < 0.06 && before_distance > 9.0 {
            reward -= 0.20;
        }
    }

    if action == "hold" {
        reward -= if before.ball.holder == Some(player.id) || before_possession == Some(player.team)
        {
            0.55
        } else {
            0.20
        };
    }

    reward.clamp(-4.0, 4.0)
}

fn loose_ball_contest_learning_reward(
    player: &PlayerAgent,
    action: &str,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_obs: &SoccerPomdpObservation,
    before_pos: Vec2,
    after_pos: Vec2,
) -> f64 {
    if before.ball.holder.is_some() || !before_obs.loose_ball {
        return 0.0;
    }
    let target = before.loose_ball_recovery_target_for(player.id);
    let before_target_distance = before_pos.distance(target);
    let after_target_distance = after_pos.distance(target);
    let closing_yards = (before_target_distance - after_target_distance).clamp(-10.0, 10.0);
    let time_advantage = before_obs
        .loose_ball_team_time_advantage_seconds
        .clamp(-3.0, 3.0);
    let player_time_fit =
        (1.0 - before_obs.loose_ball_player_time_to_ball_seconds / 4.5).clamp(0.0, 1.0);
    let race_urgency = if before_obs.loose_ball_fifty_fifty {
        1.0
    } else if time_advantage >= 0.0 {
        (0.62 + time_advantage / 2.5).clamp(0.62, 1.0)
    } else {
        (0.38 + (-time_advantage) / 4.0).clamp(0.38, 0.82)
    };
    let mut reward = closing_yards * (0.10 + race_urgency * 0.08 + player_time_fit * 0.05);

    if action == "recover" {
        reward += 0.12 + race_urgency * 0.20 + player_time_fit * 0.16;
    } else if action == "hold" && (before_obs.loose_ball_fifty_fifty || time_advantage > 0.10) {
        reward -= 0.18 + race_urgency * 0.24 + player_time_fit * 0.18;
    }

    match after.controlled_possession_team() {
        Some(team) if team == player.team => {
            reward += if after.ball.holder == Some(player.id) {
                0.88 + race_urgency * 0.44 + player_time_fit * 0.24
            } else {
                0.34 + race_urgency * 0.22
            };
        }
        Some(team) if team == player.team.other() => {
            let favored_loss = if time_advantage > 0.12 {
                0.50 + time_advantage.clamp(0.0, 2.0) * 0.25
            } else {
                0.0
            };
            let duel_loss = if before_obs.loose_ball_fifty_fifty {
                0.42
            } else {
                0.0
            };
            reward -= 0.36 + favored_loss + duel_loss + player_time_fit * 0.18;
        }
        _ => {
            if closing_yards < 0.10
                && before_target_distance > 4.0
                && (before_obs.loose_ball_fifty_fifty || time_advantage > 0.10)
            {
                reward -= 0.20 + race_urgency * 0.20;
            }
        }
    }

    reward.clamp(-3.0, 3.4)
}

fn goalmouth_dribble_learning_reward(
    player: &PlayerAgent,
    action: &str,
    before_obs: &SoccerPomdpObservation,
    after_obs: &SoccerPomdpObservation,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
) -> f64 {
    if player.role == PlayerRole::Goalkeeper
        || !is_dribble_action_label(action)
        || before_obs.yards_to_goal > GOAL_APPROACH_CARRY_YARDS
        || before.ball.holder != Some(player.id)
    {
        return 0.0;
    }

    let retained_possession = after.controlled_possession_team() == Some(player.team);
    let goal_progress = (before_obs.yards_to_goal - after_obs.yards_to_goal).clamp(-8.0, 8.0);
    let centrality_gain = goalmouth_centrality(after_pos, after.field_width)
        - goalmouth_centrality(before_pos, before.field_width);
    let window_gain = after_obs.goal_attack_window_score.clamp(0.0, 1.0)
        - before_obs.goal_attack_window_score.clamp(0.0, 1.0);
    let approach_fit = ((GOAL_APPROACH_CARRY_YARDS - before_obs.yards_to_goal)
        / (GOAL_APPROACH_CARRY_YARDS - TEAMMATE_MUST_SHOOT_YARDS).max(1.0))
    .clamp(0.0, 1.0);
    let role_fit = match player.role {
        PlayerRole::Forward => 1.18,
        PlayerRole::Midfielder => 0.96,
        PlayerRole::Defender => 0.58,
        PlayerRole::Goalkeeper => 0.0,
    };

    let positive = if retained_possession {
        GOALMOUTH_CARRY_REWARD_POINTS
            * role_fit
            * (0.58 + approach_fit * 0.42)
            * ((goal_progress.max(0.0) / 8.0).clamp(0.0, 1.0) * 0.38
                + centrality_gain.max(0.0).clamp(0.0, 0.70) * 0.34
                + window_gain.max(0.0).clamp(0.0, 0.70) * 0.52)
    } else {
        -0.22 * (0.55 + approach_fit * 0.45)
    };

    let after_goal_line_depth =
        attacking_goal_line_depth_yards(player.team, after_pos, after.field_length);
    let endline_trap_penalty = if after_goal_line_depth <= 7.0
        && after_obs.yards_to_goal <= TEAMMATE_MUST_SHOOT_YARDS
        && centrality_gain < 0.08
    {
        let endline_fit = ((7.0 - after_goal_line_depth) / 7.0).clamp(0.0, 1.0);
        ENDLINE_DRIBBLE_TRAP_PENALTY_POINTS
            * role_fit
            * (0.62 + endline_fit * 0.38)
            * (0.70 + (-centrality_gain).max(0.0).clamp(0.0, 0.70) * 0.30)
    } else {
        0.0
    };

    (positive - endline_trap_penalty).clamp(-2.8, 2.4)
}

fn pending_pass_reception_reward(
    player_id: usize,
    player_team: Team,
    action: &str,
    before_pos: Vec2,
    after_pos: Vec2,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_obs: &SoccerPomdpObservation,
) -> f64 {
    let before_ball_distance = before_pos.distance(before.ball.position);
    let after_ball_distance = after_pos.distance(after.ball.position);
    let closing_yards = (before_ball_distance - after_ball_distance).clamp(-10.0, 10.0);
    let urgency = before_obs.pending_pass_receiver_urgency.clamp(0.0, 1.0);
    let off_target = (before_obs.pending_pass_off_target_yards / 7.0).clamp(0.0, 1.0);
    let pressure = before_obs.perceived_pressure.clamp(0.0, 1.0);
    let scale = 0.12 + urgency * 0.30 + off_target * 0.20 + pressure * 0.20;
    let mut reward = closing_yards * scale;

    if matches!(action, "recover") {
        reward += 0.08 + urgency * 0.20 + pressure * 0.12;
    }

    if after.ball.holder == Some(player_id) {
        reward += 0.65 + urgency * 0.45 + pressure * 0.18;
    } else if after
        .ball
        .holder
        .and_then(|holder| {
            after
                .players
                .iter()
                .find(|candidate| candidate.id == holder)
        })
        .is_some_and(|holder| holder.team != player_team)
    {
        reward -= 0.55 + urgency * 0.35 + pressure * 0.18;
    } else if closing_yards < 0.15 && before_ball_distance > 3.0 {
        reward -= 0.20 + urgency * 0.30 + pressure * 0.15;
    }

    reward.clamp(-2.4, 2.8)
}

fn attacking_support_urgency_learning_reward(
    player: &PlayerAgent,
    action: &str,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
) -> f64 {
    if player.role == PlayerRole::Goalkeeper
        || before.controlled_possession_team() != Some(player.team)
        || !is_attacking_support_action_label(action)
    {
        return 0.0;
    }

    let before_shape_urgency = attacking_shape_support_urgency(before, player.team);
    let after_shape_urgency = attacking_shape_support_urgency(after, player.team);
    let before_pressure_urgency = holder_pressure_support_urgency(before, player.team);
    let after_pressure_urgency = holder_pressure_support_urgency(after, player.team);
    let urgency_improvement = ((before_shape_urgency - after_shape_urgency) * 0.46
        + (before_pressure_urgency - after_pressure_urgency) * 0.64)
        .clamp(-1.0, 1.0);

    let before_lane =
        if before.clear_line(before.ball.position, before_pos, player.team.other(), 2.0) {
            1.0
        } else {
            0.0
        };
    let after_lane = if after.clear_line(after.ball.position, after_pos, player.team.other(), 2.0) {
        1.0
    } else {
        0.0
    };
    let lane_delta = after_lane - before_lane;
    let space_delta = (after.space_score_at(after_pos, player.team)
        - before.space_score_at(before_pos, player.team))
    .clamp(-12.0, 12.0)
        / 12.0;
    let width_delta = (((after_pos.x - after.field_width * 0.5).abs()
        - (before_pos.x - before.field_width * 0.5).abs())
        / (before.field_width * 0.5).max(1.0))
    .clamp(-1.0, 1.0);
    let ball_distance_delta =
        before_pos.distance(before.ball.position) - after_pos.distance(after.ball.position);
    let pressure_context = before_pressure_urgency
        .max(before_shape_urgency)
        .clamp(0.0, 1.0);
    let checking_bonus = if action == "check-to-ball" && ball_distance_delta > 0.25 {
        (0.10 + ball_distance_delta.clamp(0.0, 8.0) * 0.018) * (0.60 + pressure_context * 0.55)
    } else {
        0.0
    };
    let outlet_bonus = if matches!(action, "wide-outlet" | "support-roam" | "support-shape") {
        width_delta.max(0.0) * (0.16 + pressure_context * 0.18)
    } else {
        0.0
    };

    (urgency_improvement * 0.62
        + lane_delta * 0.16
        + space_delta * 0.20
        + checking_bonus
        + outlet_bonus)
        .clamp(-1.0, 1.2)
}

fn flank_cross_arrival_support_learning_reward(
    player: &PlayerAgent,
    action: &str,
    before: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
) -> f64 {
    if player.role == PlayerRole::Goalkeeper
        || before.controlled_possession_team() != Some(player.team)
        || before.ball.holder == Some(player.id)
        || !is_attacking_support_action_label(action)
    {
        return 0.0;
    }
    let Some(arrival_target) =
        before.flank_cross_arrival_target_for(player.id, player.home_position)
    else {
        return 0.0;
    };

    let before_distance = before_pos.distance(arrival_target);
    let after_distance = after_pos.distance(arrival_target);
    let closing_yards = (before_distance - after_distance).clamp(-10.0, 10.0);
    let before_arrival_fit = (1.0 - before_distance / 13.0).clamp(0.0, 1.0);
    let after_arrival_fit = (1.0 - after_distance / 13.0).clamp(0.0, 1.0);
    let arrival_fit_delta = (after_arrival_fit - before_arrival_fit).clamp(-1.0, 1.0);
    let goalward = ((after_pos.y - before_pos.y) * player.team.attack_dir()).clamp(-6.0, 12.0);
    let policy = before.tactical_directive(player.team).flank_attack_policy;
    let policy_skill_fit = if policy.prefers_high_cross() {
        ability01(player.skills.height) * 0.20 + ability01(player.skills.strength) * 0.14
    } else {
        ability01(player.skills.acceleration) * 0.16 + ability01(player.skills.first_touch) * 0.12
    };
    let action_fit = if action == "shot-creation-run" {
        0.24
    } else if action == "support-roam" {
        0.06
    } else {
        0.0
    };

    (closing_yards * 0.095
        + arrival_fit_delta * 0.55
        + after_arrival_fit * 0.16
        + goalward.max(0.0) * 0.012
        + policy_skill_fit
        + action_fit
        - (-closing_yards).max(0.0) * 0.085)
        .clamp(-0.80, 1.25)
}

fn defensive_cross_arrival_coverage_learning_reward(
    player: &PlayerAgent,
    action: &str,
    before: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
) -> f64 {
    if !matches!(player.role, PlayerRole::Defender | PlayerRole::Midfielder)
        || before.controlled_possession_team() != Some(player.team.other())
    {
        return 0.0;
    }

    let zone = before.defensive_shape_for(player.id, player.home_position);
    let Some((coverage_target, _score)) =
        soccer_defensive_cross_arrival_mark_target(before, player.team, player.role, zone)
    else {
        return 0.0;
    };

    let before_distance = before_pos.distance(coverage_target);
    let after_distance = after_pos.distance(coverage_target);
    let closing_yards = (before_distance - after_distance).clamp(-8.0, 8.0);
    let before_fit = (1.0 - before_distance / 12.0).clamp(0.0, 1.0);
    let after_fit = (1.0 - after_distance / 12.0).clamp(0.0, 1.0);
    let fit_delta = (after_fit - before_fit).clamp(-1.0, 1.0);
    let policy = before
        .tactical_directive(player.team.other())
        .flank_attack_policy;
    let role_fit = match (player.role, policy) {
        (PlayerRole::Defender, FlankAttackPolicy::PlayDownFlankHighCross) => 0.18,
        (PlayerRole::Defender, FlankAttackPolicy::PlayDownFlankLowCross) => 0.14,
        (PlayerRole::Midfielder, FlankAttackPolicy::PlayDownFlankLowCross) => 0.12,
        (PlayerRole::Midfielder, FlankAttackPolicy::PlayDownFlankHighCross) => 0.08,
        _ => 0.0,
    };
    let action_fit = match action {
        "defend-shape" => 0.12,
        "defend-roam" => 0.06,
        "tackle" => -0.03,
        "defend" => 0.08,
        _ => 0.0,
    };

    (closing_yards * 0.125 + fit_delta * 0.72 + after_fit * 0.22 + role_fit + action_fit
        - (-closing_yards).max(0.0) * 0.115)
        .clamp(-0.90, 1.35)
}

#[derive(Clone, Copy, Debug, Default)]
struct PositionalShapeLearningSignal {
    before_vertical_lane_affinity_score: f64,
    after_vertical_lane_affinity_score: f64,
    before_teammate_congestion_pressure: f64,
    after_teammate_congestion_pressure: f64,
    before_effective_teammate_spacing_pressure: f64,
    after_effective_teammate_spacing_pressure: f64,
    before_role_line_deviation_yards: f64,
    after_role_line_deviation_yards: f64,
    before_role_line_cohesion_score: f64,
    after_role_line_cohesion_score: f64,
    positional_shape_exception_relief: f64,
    reward: f64,
}

fn role_line_shape_score_from_deviation(deviation_yards: f64) -> f64 {
    (1.0 - ((deviation_yards - 5.5) / 18.0).clamp(0.0, 1.0)).clamp(0.0, 1.0)
}

fn defensive_tracking_marker_score(player: &PlayerSnapshot, distance_yards: f64) -> f64 {
    if !distance_yards.is_finite() {
        return 0.0;
    }
    let distance_fit =
        (1.0 - distance_yards / DEFENSIVE_TRACKING_RELIEF_TARGET_RADIUS_YARDS).clamp(0.0, 1.0);
    distance_fit * (0.72 + ability01(player.skills.defensive_tracking) * 0.28)
}

fn positional_shape_learning_signal(
    player_id: usize,
    team: Team,
    role: PlayerRole,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
) -> PositionalShapeLearningSignal {
    let Some(before_player) = before.players.iter().find(|player| player.id == player_id) else {
        return PositionalShapeLearningSignal::default();
    };
    let after_player = after
        .players
        .iter()
        .find(|player| player.id == player_id)
        .unwrap_or(before_player);
    let before_relief =
        before.positional_shape_exception_relief_for_player_target(before_player, before_pos);
    let after_relief =
        after.positional_shape_exception_relief_for_player_target(after_player, after_pos);
    let before_lane =
        before.vertical_lane_fit_for_player_target(before_player, before_pos, before_relief);
    let after_lane =
        after.vertical_lane_fit_for_player_target(after_player, after_pos, after_relief);
    let before_teammate_congestion_pressure =
        before.teammate_occupied_space_pressure_at(team, before_pos, Some(player_id));
    let after_teammate_congestion_pressure =
        after.teammate_occupied_space_pressure_at(team, after_pos, Some(player_id));
    let before_effective_teammate_spacing_pressure = before.effective_teammate_spacing_pressure_at(
        team,
        before_pos,
        Some(player_id),
        before_relief,
    );
    let after_effective_teammate_spacing_pressure = after.effective_teammate_spacing_pressure_at(
        team,
        after_pos,
        Some(player_id),
        after_relief,
    );
    let before_role_line_deviation_yards =
        before.role_line_deviation_yards_for_target(before_player, before_pos);
    let after_role_line_deviation_yards =
        after.role_line_deviation_yards_for_target(after_player, after_pos);
    let before_role_line_cohesion_score =
        before.role_line_cohesion_score_for_player_target(before_player, before_pos);
    let after_role_line_cohesion_score =
        after.role_line_cohesion_score_for_player_target(after_player, after_pos);

    let possession = before.controlled_possession_team();
    let in_possession = possession == Some(team);
    let defending = possession == Some(team.other());
    let lane_commitment = before_lane.commitment.max(after_lane.commitment);
    let lane_reward = if lane_commitment > 1e-9 {
        let delta = (after_lane.affinity_score - before_lane.affinity_score).clamp(-1.0, 1.0);
        let steady_state = (after_lane.affinity_score - 0.62).clamp(-0.62, 0.38);
        (delta * 0.38 + steady_state * 0.10) * lane_commitment
    } else {
        0.0
    };

    let congestion_weight = if in_possession {
        0.34
    } else if defending {
        0.27
    } else {
        0.20
    };
    let congestion_improvement = (before_effective_teammate_spacing_pressure
        - after_effective_teammate_spacing_pressure)
        .clamp(-1.0, 1.0)
        * congestion_weight;
    let congestion_state =
        (0.24 - after_effective_teammate_spacing_pressure).clamp(-0.76, 0.24) * 0.10;
    let hard_congestion_penalty =
        if after_effective_teammate_spacing_pressure > 0.85 && after_relief < 0.25 {
            -(after_effective_teammate_spacing_pressure - 0.85) * 0.42
        } else {
            0.0
        };

    let before_line_score = role_line_shape_score_from_deviation(before_role_line_deviation_yards);
    let after_line_score = role_line_shape_score_from_deviation(after_role_line_deviation_yards);
    let line_weight = match (role, in_possession, defending) {
        (PlayerRole::Defender, false, true) => 0.34,
        (PlayerRole::Midfielder, false, true) => 0.26,
        (PlayerRole::Defender, true, false) => 0.16,
        (PlayerRole::Midfielder, true, false) => 0.11,
        _ => 0.0,
    };
    let line_relief = after_relief.clamp(0.0, 0.85);
    let line_reward = ((after_line_score - before_line_score).clamp(-1.0, 1.0) * line_weight
        + (after_line_score - 0.55).clamp(-0.55, 0.45) * line_weight * 0.18)
        * (1.0 - line_relief);
    let line_cohesion_reward = ((after_role_line_cohesion_score - before_role_line_cohesion_score)
        .clamp(-1.0, 1.0)
        * line_weight
        * 0.78
        + (after_role_line_cohesion_score - 0.62).clamp(-0.62, 0.38) * line_weight * 0.16)
        * (1.0 - line_relief);

    PositionalShapeLearningSignal {
        before_vertical_lane_affinity_score: before_lane.affinity_score,
        after_vertical_lane_affinity_score: after_lane.affinity_score,
        before_teammate_congestion_pressure,
        after_teammate_congestion_pressure,
        before_effective_teammate_spacing_pressure,
        after_effective_teammate_spacing_pressure,
        before_role_line_deviation_yards,
        after_role_line_deviation_yards,
        before_role_line_cohesion_score,
        after_role_line_cohesion_score,
        positional_shape_exception_relief: after_relief,
        reward: (lane_reward
            + congestion_improvement
            + congestion_state
            + hard_congestion_penalty
            + line_reward
            + line_cohesion_reward)
            .clamp(
                -POSITIONAL_SHAPE_REWARD_CLAMP,
                POSITIONAL_SHAPE_REWARD_CLAMP,
            ),
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct LookBehindShapeSignal {
    active: bool,
    drift_risk: f64,
    penalty: f64,
}

fn look_behind_shape_learning_signal(
    player_id: usize,
    team: Team,
    role: PlayerRole,
    before: &WorldSnapshot,
    before_pos: Vec2,
) -> LookBehindShapeSignal {
    if role == PlayerRole::Goalkeeper {
        return LookBehindShapeSignal::default();
    }
    let Some(player) = before.players.iter().find(|player| player.id == player_id) else {
        return LookBehindShapeSignal::default();
    };
    let scan = look_behind_scan_context_for_observer(
        before.tick,
        before.dt_seconds,
        player,
        before_pos,
        before.ball.position,
        before.ball.velocity.len(),
    );
    if !scan.active {
        return LookBehindShapeSignal::default();
    }

    let phase_weight = match before.controlled_possession_team() {
        Some(possession_team) if possession_team == team.other() => 1.0,
        Some(possession_team) if possession_team == team => 0.42,
        _ => 0.68,
    };
    let role_weight = match role {
        PlayerRole::Defender => 1.0,
        PlayerRole::Midfielder => 0.78,
        PlayerRole::Forward => 0.48,
        PlayerRole::Goalkeeper => 0.0,
    };

    LookBehindShapeSignal {
        active: true,
        drift_risk: scan.drift_risk,
        penalty: (-scan.drift_risk * phase_weight * role_weight * 0.46).clamp(-0.46, 0.0),
    }
}

fn tactical_shape_reward(
    player: &PlayerAgent,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
    spacing_mode: Option<TeamSpacingMode>,
    spacing_delta: (f64, f64, f64),
    weights: &SoccerTacticalLearningWeights,
) -> f64 {
    tactical_shape_trace(
        player.id,
        player.team,
        player.role,
        before,
        after,
        before_pos,
        after_pos,
        spacing_mode,
        spacing_delta,
        weights,
    )
    .tactical_reward
}

fn tactical_shape_trace_for_snapshots(
    player_id: usize,
    team: Team,
    role: PlayerRole,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
    weights: &SoccerTacticalLearningWeights,
) -> SoccerTacticalLearningTrace {
    let spacing_mode = before.team_spacing_mode_for(team);
    let spacing_delta = spacing_mode
        .map(|mode| {
            let before_score =
                before.team_spacing_score_for_candidate(team, Some(player_id), before_pos, mode);
            let after_score =
                after.team_spacing_score_for_candidate(team, Some(player_id), after_pos, mode);
            (before_score, after_score, after_score - before_score)
        })
        .unwrap_or((0.0, 0.0, 0.0));
    tactical_shape_trace(
        player_id,
        team,
        role,
        before,
        after,
        before_pos,
        after_pos,
        spacing_mode,
        spacing_delta,
        weights,
    )
}

fn tactical_shape_trace(
    player_id: usize,
    team: Team,
    role: PlayerRole,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
    spacing_mode: Option<TeamSpacingMode>,
    spacing_delta: (f64, f64, f64),
    weights: &SoccerTacticalLearningWeights,
) -> SoccerTacticalLearningTrace {
    let lp_trace = formation_lp_learning_trace_for_snapshots(
        player_id, before, before_pos, after_pos, weights,
    );
    if matches!(role, PlayerRole::Goalkeeper) {
        return lp_trace;
    }
    let field_width = before.field_width.max(1.0);
    let before_possession = before.controlled_possession_team();
    let positional_signal = positional_shape_learning_signal(
        player_id, team, role, before, after, before_pos, after_pos,
    );
    let look_behind_signal =
        look_behind_shape_learning_signal(player_id, team, role, before, before_pos);
    if before_possession == Some(team) {
        let spacing_weight = before.possession_spacing_weight(team).max(0.35);
        let before_width =
            team_field_player_lateral_width_for_candidate(before, team, player_id, before_pos);
        let after_width =
            team_field_player_lateral_width_for_candidate(after, team, player_id, after_pos);
        let width_delta = ((after_width - before_width) / field_width).clamp(-1.0, 1.0);
        let flank_delta = (flank_lane_score(after_pos, field_width)
            - flank_lane_score(before_pos, field_width))
        .clamp(-1.0, 1.0);
        let mut reward = width_delta * weights.attack_width_delta_weight * spacing_weight;
        reward += attack_width_score(after_width, field_width)
            * weights.attack_width_score_weight
            * spacing_weight;
        reward += flank_delta * weights.attack_flank_lane_weight;
        reward +=
            flank_lane_score(after_pos, field_width) * weights.attack_flank_lane_weight * 0.18;
        if let Some(TeamSpacingMode::InPossession) = spacing_mode {
            reward += spacing_delta.2.clamp(-1.0, 1.0)
                * weights.attack_spacing_delta_weight
                * spacing_weight;
            reward += spacing_delta.1.clamp(-1.0, 1.0)
                * weights.attack_spacing_score_weight
                * spacing_weight;
        }
        reward += positional_signal.reward;
        reward += look_behind_signal.penalty;
        reward += lp_trace.tactical_reward;
        return SoccerTacticalLearningTrace {
            attack_shape: true,
            defense_shape: false,
            before_team_width_yards: before_width,
            after_team_width_yards: after_width,
            width_delta_yards: after_width - before_width,
            attack_width_score: attack_width_score(after_width, field_width),
            defense_contract_score: 0.0,
            before_flank_lane_score: flank_lane_score(before_pos, field_width),
            after_flank_lane_score: flank_lane_score(after_pos, field_width),
            flank_lane_delta: flank_delta,
            before_spacing_score: spacing_delta.0,
            after_spacing_score: spacing_delta.1,
            spacing_delta: spacing_delta.2,
            defense_ball_gap_yards: 0.0,
            defense_ball_gap_score: 0.0,
            defense_endline_depth_yards: 0.0,
            defense_endline_soft_penalty: 0.0,
            defense_endline_hard_penalty: 0.0,
            defense_role_press_distance_yards: 0.0,
            defense_role_press_score: 0.0,
            defense_role_press_delta: 0.0,
            before_vertical_lane_affinity_score: positional_signal
                .before_vertical_lane_affinity_score,
            after_vertical_lane_affinity_score: positional_signal
                .after_vertical_lane_affinity_score,
            vertical_lane_affinity_delta: positional_signal.after_vertical_lane_affinity_score
                - positional_signal.before_vertical_lane_affinity_score,
            before_teammate_congestion_pressure: positional_signal
                .before_teammate_congestion_pressure,
            after_teammate_congestion_pressure: positional_signal
                .after_teammate_congestion_pressure,
            teammate_congestion_delta: positional_signal.after_teammate_congestion_pressure
                - positional_signal.before_teammate_congestion_pressure,
            before_effective_teammate_spacing_pressure: positional_signal
                .before_effective_teammate_spacing_pressure,
            after_effective_teammate_spacing_pressure: positional_signal
                .after_effective_teammate_spacing_pressure,
            effective_teammate_spacing_delta: positional_signal
                .after_effective_teammate_spacing_pressure
                - positional_signal.before_effective_teammate_spacing_pressure,
            before_role_line_deviation_yards: positional_signal.before_role_line_deviation_yards,
            after_role_line_deviation_yards: positional_signal.after_role_line_deviation_yards,
            role_line_deviation_delta_yards: positional_signal.after_role_line_deviation_yards
                - positional_signal.before_role_line_deviation_yards,
            before_role_line_cohesion_score: positional_signal.before_role_line_cohesion_score,
            after_role_line_cohesion_score: positional_signal.after_role_line_cohesion_score,
            role_line_cohesion_delta: positional_signal.after_role_line_cohesion_score
                - positional_signal.before_role_line_cohesion_score,
            positional_shape_exception_relief: positional_signal.positional_shape_exception_relief,
            positional_shape_reward: positional_signal.reward,
            look_behind_scan_active: look_behind_signal.active,
            look_behind_drift_risk: look_behind_signal.drift_risk,
            look_behind_shape_penalty: look_behind_signal.penalty,
            tactical_reward: reward,
            ..lp_trace
        };
    }

    if before_possession == Some(team.other()) {
        let before_width =
            team_field_player_lateral_width_for_candidate(before, team, player_id, before_pos);
        let after_width =
            team_field_player_lateral_width_for_candidate(after, team, player_id, after_pos);
        let contract_delta = ((before_width - after_width) / field_width).clamp(-1.0, 1.0);
        let mut reward = contract_delta * weights.defense_contract_delta_weight;
        reward += defense_contract_width_score(after_width, field_width)
            * weights.defense_compactness_score_weight;
        let before_ball_gap_score = defensive_ball_gap_score(team, before_pos, before);
        let after_ball_gap_yards = defensive_ball_gap_yards(team, after_pos, after);
        let after_ball_gap_score = defensive_ball_gap_score(team, after_pos, after);
        reward += after_ball_gap_score.clamp(-1.0, 0.35) * weights.defense_ball_depth_score_weight;
        reward += (after_ball_gap_score - before_ball_gap_score).clamp(-1.0, 1.0)
            * weights.defense_ball_depth_score_weight
            * 0.50;
        let after_endline_depth = defensive_endline_depth_yards(team, after_pos, after);
        let (endline_soft_penalty, endline_hard_penalty) =
            defensive_endline_penalty_components(team, after_pos, after);
        reward -= endline_soft_penalty * weights.defense_endline_soft_penalty_weight;
        reward -= endline_hard_penalty * weights.defense_endline_hard_penalty_weight;
        let before_role_press = defensive_role_press_signal(before, team, role, before_pos);
        let after_role_press = defensive_role_press_signal(after, team, role, after_pos);
        let press_weight = match role {
            PlayerRole::Defender => weights.defender_midfielder_press_weight,
            PlayerRole::Midfielder => weights.midfielder_press_weight,
            PlayerRole::Goalkeeper | PlayerRole::Forward => 0.0,
        };
        reward += after_role_press.score.clamp(-1.0, 1.0) * press_weight * 0.35;
        reward += (after_role_press.score - before_role_press.score).clamp(-1.0, 1.0)
            * press_weight
            * 0.65;
        if let Some(TeamSpacingMode::Defending) = spacing_mode {
            reward += spacing_delta.2.clamp(-1.0, 1.0) * weights.defense_spacing_delta_weight;
            reward += spacing_delta.1.clamp(-1.0, 1.0) * weights.defense_spacing_score_weight;
        }
        reward += positional_signal.reward;
        reward += look_behind_signal.penalty;
        reward += lp_trace.tactical_reward;
        return SoccerTacticalLearningTrace {
            attack_shape: false,
            defense_shape: true,
            before_team_width_yards: before_width,
            after_team_width_yards: after_width,
            width_delta_yards: after_width - before_width,
            attack_width_score: 0.0,
            defense_contract_score: defense_contract_width_score(after_width, field_width),
            before_flank_lane_score: flank_lane_score(before_pos, field_width),
            after_flank_lane_score: flank_lane_score(after_pos, field_width),
            flank_lane_delta: 0.0,
            before_spacing_score: spacing_delta.0,
            after_spacing_score: spacing_delta.1,
            spacing_delta: spacing_delta.2,
            defense_ball_gap_yards: after_ball_gap_yards,
            defense_ball_gap_score: after_ball_gap_score,
            defense_endline_depth_yards: after_endline_depth,
            defense_endline_soft_penalty: endline_soft_penalty,
            defense_endline_hard_penalty: endline_hard_penalty,
            defense_role_press_distance_yards: after_role_press.distance_yards,
            defense_role_press_score: after_role_press.score,
            defense_role_press_delta: after_role_press.score - before_role_press.score,
            before_vertical_lane_affinity_score: positional_signal
                .before_vertical_lane_affinity_score,
            after_vertical_lane_affinity_score: positional_signal
                .after_vertical_lane_affinity_score,
            vertical_lane_affinity_delta: positional_signal.after_vertical_lane_affinity_score
                - positional_signal.before_vertical_lane_affinity_score,
            before_teammate_congestion_pressure: positional_signal
                .before_teammate_congestion_pressure,
            after_teammate_congestion_pressure: positional_signal
                .after_teammate_congestion_pressure,
            teammate_congestion_delta: positional_signal.after_teammate_congestion_pressure
                - positional_signal.before_teammate_congestion_pressure,
            before_effective_teammate_spacing_pressure: positional_signal
                .before_effective_teammate_spacing_pressure,
            after_effective_teammate_spacing_pressure: positional_signal
                .after_effective_teammate_spacing_pressure,
            effective_teammate_spacing_delta: positional_signal
                .after_effective_teammate_spacing_pressure
                - positional_signal.before_effective_teammate_spacing_pressure,
            before_role_line_deviation_yards: positional_signal.before_role_line_deviation_yards,
            after_role_line_deviation_yards: positional_signal.after_role_line_deviation_yards,
            role_line_deviation_delta_yards: positional_signal.after_role_line_deviation_yards
                - positional_signal.before_role_line_deviation_yards,
            before_role_line_cohesion_score: positional_signal.before_role_line_cohesion_score,
            after_role_line_cohesion_score: positional_signal.after_role_line_cohesion_score,
            role_line_cohesion_delta: positional_signal.after_role_line_cohesion_score
                - positional_signal.before_role_line_cohesion_score,
            positional_shape_exception_relief: positional_signal.positional_shape_exception_relief,
            positional_shape_reward: positional_signal.reward,
            look_behind_scan_active: look_behind_signal.active,
            look_behind_drift_risk: look_behind_signal.drift_risk,
            look_behind_shape_penalty: look_behind_signal.penalty,
            tactical_reward: reward,
            ..lp_trace
        };
    }

    lp_trace
}

fn formation_lp_learning_trace_for_snapshots(
    player_id: usize,
    before: &WorldSnapshot,
    before_pos: Vec2,
    after_pos: Vec2,
    weights: &SoccerTacticalLearningWeights,
) -> SoccerTacticalLearningTrace {
    let Some(guidance) = before.formation_lp_guidance_for(player_id) else {
        return SoccerTacticalLearningTrace::default();
    };
    let recommended = guidance.target - before_pos;
    let actual = after_pos - before_pos;
    let recommended_move_yards = recommended.len();
    let actual_move_yards = actual.len();
    let disagreement_yards = after_pos.distance(guidance.target);
    let alignment_score = if recommended_move_yards <= 1e-6 {
        if actual_move_yards <= 0.20 {
            1.0
        } else {
            0.0
        }
    } else if actual_move_yards <= 1e-6 {
        -0.25
    } else {
        actual
            .normalized()
            .dot(recommended.normalized())
            .clamp(-1.0, 1.0)
            * (actual_move_yards / recommended_move_yards).clamp(0.0, 1.0)
    };
    let alignment_reward = ((alignment_score + 1.0) * 0.5).clamp(0.0, 1.0);
    let disagreement_penalty = (disagreement_yards / 4.0).clamp(0.0, 1.0);
    let tactical_reward = (alignment_reward - 0.65 * disagreement_penalty)
        * weights.formation_lp_alignment_weight
        * guidance.alignment_weight.clamp(0.20, 1.60);
    SoccerTacticalLearningTrace {
        formation_lp_guidance: true,
        formation_lp_recommended_move_yards: recommended_move_yards,
        formation_lp_actual_move_yards: actual_move_yards,
        formation_lp_disagreement_yards: disagreement_yards,
        formation_lp_alignment_score: alignment_score,
        formation_lp_pressure_weight: guidance.pressure_weight,
        formation_lp_speed_match_weight: guidance.speed_match_weight,
        formation_lp_recommended_speed_yps: guidance.recommended_speed_yps,
        formation_lp_recommended_acceleration_yps2: guidance.recommended_acceleration_yps2,
        formation_lp_pressure_error_yards: guidance.pressure_error_yards,
        formation_lp_fore_aft_speed_error_yps: guidance.fore_aft_speed_error_yps,
        formation_lp_pair_error_yards: guidance.pair_error_yards,
        tactical_reward,
        ..Default::default()
    }
}

fn team_field_player_lateral_width_for_candidate(
    snapshot: &WorldSnapshot,
    team: Team,
    replace_player_id: usize,
    candidate_position: Vec2,
) -> f64 {
    let mut min_x = f64::INFINITY;
    let mut max_x = f64::NEG_INFINITY;
    let mut count = 0;
    for player in snapshot
        .players
        .iter()
        .filter(|player| player.team == team && player.role != PlayerRole::Goalkeeper)
    {
        let position = if player.id == replace_player_id {
            candidate_position
        } else {
            snapshot
                .player_position(player.id)
                .unwrap_or(player.position)
        };
        min_x = min_x.min(position.x);
        max_x = max_x.max(position.x);
        count += 1;
    }
    if count < 2 {
        0.0
    } else {
        (max_x - min_x).clamp(0.0, snapshot.field_width.max(0.0))
    }
}

fn attack_width_score(width_yards: f64, field_width_yards: f64) -> f64 {
    width_band_score(
        width_yards,
        field_width_yards,
        field_width_yards * 0.52,
        field_width_yards * 0.78,
        field_width_yards * 0.96,
    )
}

fn defense_contract_width_score(width_yards: f64, field_width_yards: f64) -> f64 {
    width_band_score(
        width_yards,
        field_width_yards,
        field_width_yards * 0.22,
        field_width_yards * 0.38,
        field_width_yards * 0.58,
    )
}

fn width_band_score(
    width_yards: f64,
    field_width_yards: f64,
    min_yards: f64,
    ideal_yards: f64,
    max_yards: f64,
) -> f64 {
    if !width_yards.is_finite() || field_width_yards <= 0.0 {
        return -1.0;
    }
    if width_yards < min_yards {
        -((min_yards - width_yards) / min_yards.max(1.0)).clamp(0.0, 1.0)
    } else if width_yards > max_yards {
        -((width_yards - max_yards) / (field_width_yards - max_yards).max(1.0)).clamp(0.0, 1.0)
    } else {
        let span = if width_yards <= ideal_yards {
            (ideal_yards - min_yards).max(1e-6)
        } else {
            (max_yards - ideal_yards).max(1e-6)
        };
        (1.0 - ((width_yards - ideal_yards).abs() / span) * 0.45).clamp(0.55, 1.0)
    }
}

fn flank_lane_score(position: Vec2, field_width_yards: f64) -> f64 {
    if !position.x.is_finite() || field_width_yards <= 0.0 {
        return 0.0;
    }
    let half_width = (field_width_yards * 0.5).max(1.0);
    let lateral = ((position.x - field_width_yards * 0.5).abs() / half_width).clamp(0.0, 1.0);
    if lateral < 0.35 {
        -((0.35 - lateral) / 0.35).clamp(0.0, 1.0)
    } else {
        ((lateral - 0.35) / 0.55).clamp(0.0, 1.0)
    }
}

fn defensive_ball_gap_yards(team: Team, player_position: Vec2, snapshot: &WorldSnapshot) -> f64 {
    ((snapshot.ball.position.y - player_position.y) * team.attack_dir()).max(0.0)
}

fn defensive_ball_gap_score(team: Team, player_position: Vec2, snapshot: &WorldSnapshot) -> f64 {
    let gap = defensive_ball_gap_yards(team, player_position, snapshot);
    if !gap.is_finite() {
        return -1.0;
    }
    if gap <= DEFENSIVE_MAX_BEHIND_BALL_YARDS {
        (0.35 - gap / DEFENSIVE_MAX_BEHIND_BALL_YARDS * 0.10).clamp(0.20, 0.35)
    } else {
        -((gap - DEFENSIVE_MAX_BEHIND_BALL_YARDS) / DEFENSIVE_MAX_BEHIND_BALL_YARDS).clamp(0.0, 1.0)
    }
}

fn goalkeeper_ball_goal_line_alignment_score(
    team: Team,
    player_position: Vec2,
    snapshot: &WorldSnapshot,
) -> f64 {
    let goal = Vec2::new(
        snapshot.field_width * 0.5,
        team.other().goal_y(snapshot.field_length),
    );
    let ball = snapshot.ball.position;
    let ball_goal_distance = goal.distance(ball);
    if ball_goal_distance <= 1e-9 {
        return 1.0;
    }
    let line_distance = segment_distance_to_point(goal, ball, player_position);
    let projection = segment_projection_factor(goal, ball, player_position);
    let line_score = (1.0 - line_distance / 1.0).clamp(-1.0, 1.0);
    let projection_score = if (0.0..=1.0).contains(&projection) {
        1.0
    } else {
        (1.0 - projection.min(0.0).abs().max((projection - 1.0).max(0.0)) / 0.35).clamp(-1.0, 1.0)
    };
    let ideal = snapshot.goalkeeper_ball_goal_tracking_target(team);
    let depth_score = (1.0 - player_position.distance(ideal) / 4.5).clamp(-1.0, 1.0);
    (line_score * 0.82 + projection_score * 0.08 + depth_score * 0.10).clamp(-1.0, 1.0)
}

fn defensive_endline_depth_yards(
    team: Team,
    player_position: Vec2,
    snapshot: &WorldSnapshot,
) -> f64 {
    (player_position.y - team.other().goal_y(snapshot.field_length)).abs()
}

fn defensive_endline_penalty_components(
    team: Team,
    player_position: Vec2,
    snapshot: &WorldSnapshot,
) -> (f64, f64) {
    let defender_depth = defensive_endline_depth_yards(team, player_position, snapshot);
    let ball_depth = (snapshot.ball.position.y - team.other().goal_y(snapshot.field_length)).abs();
    let ball_closer_to_endline = ball_depth + 1e-6 < defender_depth;
    if ball_closer_to_endline {
        return (0.0, 0.0);
    }

    let soft = if defender_depth < DEFENSIVE_GOAL_LINE_BUFFER_YARDS {
        ((DEFENSIVE_GOAL_LINE_BUFFER_YARDS - defender_depth) / DEFENSIVE_GOAL_LINE_BUFFER_YARDS)
            .clamp(0.0, 1.0)
    } else {
        0.0
    };
    let hard = if defender_depth < DEFENSIVE_GOAL_LINE_HARD_BUFFER_YARDS {
        ((DEFENSIVE_GOAL_LINE_HARD_BUFFER_YARDS - defender_depth)
            / DEFENSIVE_GOAL_LINE_HARD_BUFFER_YARDS)
            .clamp(0.0, 1.0)
    } else {
        0.0
    };
    (soft, hard)
}

#[derive(Clone, Copy, Debug, Default)]
struct DefensiveRolePressSignal {
    distance_yards: f64,
    score: f64,
}

fn defensive_press_distance_score(distance_yards: f64, ideal_yards: f64) -> f64 {
    if !distance_yards.is_finite() {
        return 0.0;
    }
    let ideal = ideal_yards.max(1.0);
    if distance_yards <= ideal {
        (1.0 - distance_yards / ideal * 0.20).clamp(0.80, 1.0)
    } else {
        -((distance_yards - ideal) / ideal).clamp(0.0, 1.0)
    }
}

fn defensive_role_press_signal(
    snapshot: &WorldSnapshot,
    team: Team,
    role: PlayerRole,
    player_position: Vec2,
) -> DefensiveRolePressSignal {
    match role {
        PlayerRole::Defender => {
            let Some(distance_yards) = snapshot
                .players
                .iter()
                .filter(|player| {
                    player.team == team.other() && player.role == PlayerRole::Midfielder
                })
                .filter_map(|player| snapshot.player_position(player.id))
                .map(|position| position.distance(player_position))
                .min_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
            else {
                return DefensiveRolePressSignal::default();
            };
            DefensiveRolePressSignal {
                distance_yards,
                score: defensive_press_distance_score(
                    distance_yards,
                    DEFENDER_PRESS_MIDFIELDER_IDEAL_YARDS,
                ),
            }
        }
        PlayerRole::Midfielder => {
            let focus = snapshot.defensive_midfielder_press_focus(team);
            let distance_yards = player_position.distance(focus);
            DefensiveRolePressSignal {
                distance_yards,
                score: defensive_press_distance_score(
                    distance_yards,
                    MIDFIELDER_PRESS_FOCUS_IDEAL_YARDS,
                ),
            }
        }
        PlayerRole::Goalkeeper | PlayerRole::Forward => DefensiveRolePressSignal::default(),
    }
}

fn defensive_goal_side_reward(team: Team, player_position: Vec2, snapshot: &WorldSnapshot) -> f64 {
    let Some(attacker_position) = snapshot
        .ball
        .holder
        .and_then(|holder| snapshot.players.iter().find(|p| p.id == holder))
        .filter(|holder| holder.team == team.other())
        .and_then(|holder| snapshot.player_position(holder.id))
    else {
        return 0.0;
    };
    let own_goal_y = team.other().goal_y(snapshot.field_length);
    let goal_side_of_ball =
        goal_side_between_y(player_position.y, snapshot.ball.position.y, own_goal_y);
    let goal_side_of_attacker =
        goal_side_between_y(player_position.y, attacker_position.y, own_goal_y);
    match (goal_side_of_ball, goal_side_of_attacker) {
        (true, true) => 0.24,
        (true, false) | (false, true) => -0.12,
        (false, false) => -0.42,
    }
}

fn defensive_goal_line_spacing_score(
    team: Team,
    player_position: Vec2,
    snapshot: &WorldSnapshot,
) -> f64 {
    let (soft_endline_penalty, hard_endline_penalty) =
        defensive_endline_penalty_components(team, player_position, snapshot);
    let behind_ball = defensive_ball_gap_yards(team, player_position, snapshot);
    let disconnected_penalty = if !snapshot.ball_near_own_goal_line(team)
        && behind_ball > DEFENSIVE_MAX_BEHIND_BALL_YARDS
    {
        -((behind_ball - DEFENSIVE_MAX_BEHIND_BALL_YARDS) / DEFENSIVE_MAX_BEHIND_BALL_YARDS)
            .clamp(0.0, 1.0)
    } else {
        0.0
    };
    let endline_penalty = soft_endline_penalty * 0.35 + hard_endline_penalty * 0.80;
    let healthy_line_bonus = if endline_penalty == 0.0 && disconnected_penalty == 0.0 {
        0.35
    } else {
        0.0
    };
    (healthy_line_bonus - endline_penalty + disconnected_penalty).clamp(-1.0, 0.35)
}

fn goal_side_between_y(player_y: f64, threat_y: f64, own_goal_y: f64) -> bool {
    if own_goal_y <= threat_y {
        player_y <= threat_y + 0.75
    } else {
        player_y >= threat_y - 0.75
    }
}

fn loose_ball_fifty_fifty_duel_for(snapshot: &WorldSnapshot, player_id: usize) -> bool {
    let Some(me) = snapshot.players.iter().find(|p| p.id == player_id) else {
        return false;
    };
    if snapshot.ball.holder.is_some() || snapshot.ball.velocity.len() > 10.0 {
        return false;
    }
    let Some((home, away)) = loose_ball_fifty_fifty_duel(snapshot) else {
        return false;
    };
    let contender_id = match me.team {
        Team::Home => home,
        Team::Away => away,
    };
    contender_id == player_id
}

fn loose_ball_fifty_fifty_duel(snapshot: &WorldSnapshot) -> Option<(usize, usize)> {
    if snapshot.ball.holder.is_some() {
        return None;
    }
    let nearest = |team| {
        snapshot
            .players
            .iter()
            .filter(|player| player.team == team)
            .filter_map(|player| {
                let position = player.position;
                let velocity_toward_ball = player
                    .velocity
                    .normalized()
                    .dot((snapshot.ball.position - position).normalized());
                Some((
                    player.id,
                    position.distance(snapshot.ball.position),
                    velocity_toward_ball,
                ))
            })
            .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
    };
    let home = nearest(Team::Home)?;
    let away = nearest(Team::Away)?;
    let distance_close = home.1.min(away.1) <= 18.0;
    let distance_even = (home.1 - away.1).abs() <= 2.8;
    let velocity_even = (home.2 - away.2).abs() <= 0.55;
    (distance_close && distance_even && velocity_even).then_some((home.0, away.0))
}

#[derive(Clone, Copy, Debug, Default)]
struct LooseBallRaceContext {
    loose_ball: bool,
    fifty_fifty: bool,
    team_time_advantage_seconds: f64,
    player_time_to_ball_seconds: f64,
}

fn loose_ball_race_context_for_snapshot(
    snapshot: &WorldSnapshot,
    player_id: usize,
) -> LooseBallRaceContext {
    if snapshot.ball.holder.is_some() {
        return LooseBallRaceContext::default();
    }
    let Some(me) = snapshot
        .players
        .iter()
        .find(|player| player.id == player_id)
    else {
        return LooseBallRaceContext::default();
    };
    let target = snapshot.loose_ball_recovery_target_for(player_id);
    let player_time_to_ball_seconds =
        loose_ball_arrival_time_seconds(snapshot, me, target).clamp(0.0, 8.0);
    let mut own_best = f64::INFINITY;
    let mut opponent_best = f64::INFINITY;
    for player in &snapshot.players {
        let arrival = loose_ball_arrival_time_seconds(snapshot, player, target);
        if player.team == me.team {
            own_best = own_best.min(arrival);
        } else {
            opponent_best = opponent_best.min(arrival);
        }
    }
    let team_time_advantage_seconds = if own_best.is_finite() && opponent_best.is_finite() {
        (opponent_best - own_best).clamp(-3.0, 3.0)
    } else {
        0.0
    };
    LooseBallRaceContext {
        loose_ball: true,
        fifty_fifty: loose_ball_fifty_fifty_duel(snapshot).is_some()
            || team_time_advantage_seconds.abs() <= 0.12,
        team_time_advantage_seconds,
        player_time_to_ball_seconds,
    }
}

fn loose_ball_arrival_time_seconds(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    target: Vec2,
) -> f64 {
    let position = snapshot
        .player_position(player.id)
        .unwrap_or(player.position);
    let distance = position.distance(target);
    if distance <= 0.05 {
        return 0.0;
    }
    let to_target = (target - position).normalized();
    let velocity = snapshot
        .player_velocity(player.id)
        .unwrap_or(player.velocity);
    let closing_speed = velocity.dot(to_target).max(0.0);
    let sprint_speed = player_top_speed_yps(player.role, &player.skills)
        * MovementGait::Sprint.speed_multiplier()
        * fatigue_speed_factor(player.skills.stamina, player.fatigue);
    let effective_speed = (sprint_speed * 0.78 + closing_speed.min(sprint_speed) * 0.22).max(0.85);
    distance / effective_speed
}

impl SoccerPomdpObservation {
    fn pressure_like_penalty(&self) -> f64 {
        (self.perceived_pressure * 18.0).max(0.0)
    }
}

