fn default_home_team_brain_snapshot() -> TeamBrainSnapshot {
    default_team_brain_snapshot(Team::Home)
}

fn default_away_team_brain_snapshot() -> TeamBrainSnapshot {
    default_team_brain_snapshot(Team::Away)
}

fn team_brain_mode_for(
    team: Team,
    phase: TacticalPhase,
    possession_team: Option<Team>,
) -> TeamBrainMode {
    if phase == TacticalPhase::Kickoff {
        return TeamBrainMode::Kickoff;
    }
    match possession_team {
        Some(possession) if possession == team => match (team, phase) {
            (Team::Home, TacticalPhase::HomeAttack) | (Team::Away, TacticalPhase::AwayAttack) => {
                TeamBrainMode::Attack
            }
            _ => TeamBrainMode::BuildUp,
        },
        Some(_) => TeamBrainMode::Defend,
        None => TeamBrainMode::Transition,
    }
}

fn team_brain_shape_from_awareness(
    players: &[CentralBrainPlayerAwareness],
    team: Team,
    ball_position: Vec2,
) -> (Vec2, Vec2, f64, usize) {
    let mut count = 0_usize;
    let mut position_sum = Vec2::zero();
    let mut velocity_sum = Vec2::zero();
    let mut players_near_ball = 0_usize;
    for player in players.iter().filter(|player| player.team == team) {
        count += 1;
        position_sum += player.position;
        velocity_sum += player.velocity;
        if player.position.distance(ball_position) <= TEAM_SHAPE_NEAR_BALL_RADIUS_YARDS {
            players_near_ball += 1;
        }
    }
    if count == 0 {
        return (Vec2::zero(), Vec2::zero(), 0.0, 0);
    }
    let count_f = count as f64;
    let centroid = position_sum / count_f;
    let average_velocity = velocity_sum / count_f;
    let spread = players
        .iter()
        .filter(|player| player.team == team)
        .map(|player| player.position.distance(centroid))
        .sum::<f64>()
        / count_f;
    (centroid, average_velocity, spread, players_near_ball)
}

#[derive(Clone, Copy, Debug, Default)]
struct TeamShapeObservation {
    centroid_to_ball_yards: f64,
    spread_yards: f64,
    players_near_ball: usize,
    forward_velocity_yps: f64,
}

fn central_brain_team_shape_trace(shape: TeamShapeObservation) -> CentralBrainTeamShapeTrace {
    CentralBrainTeamShapeTrace {
        centroid_to_ball_yards: shape.centroid_to_ball_yards,
        spread_yards: shape.spread_yards,
        players_near_ball: shape.players_near_ball,
        forward_velocity_yps: shape.forward_velocity_yps,
    }
}

fn team_shape_observation_from_snapshot(
    snapshot: &WorldSnapshot,
    team: Team,
    ball_position: Vec2,
) -> TeamShapeObservation {
    let (width, length) = sane_pitch_dimensions(snapshot.field_width, snapshot.field_length);
    let center = Vec2::new(width * 0.5, length * 0.5);
    let ball_position = finite_pitch_point(ball_position, width, length, center);
    let mut count = 0_usize;
    let mut position_sum = Vec2::zero();
    let mut velocity_sum = Vec2::zero();
    let mut players_near_ball = 0_usize;

    for player in snapshot.players.iter().filter(|player| player.team == team) {
        let position = finite_pitch_point(
            snapshot
                .player_position(player.id)
                .unwrap_or(player.position),
            width,
            length,
            player.home_position,
        );
        count += 1;
        position_sum += position;
        velocity_sum += finite_vec2(player.velocity, Vec2::zero());
        if position.distance(ball_position) <= TEAM_SHAPE_NEAR_BALL_RADIUS_YARDS {
            players_near_ball += 1;
        }
    }

    if count == 0 {
        return TeamShapeObservation::default();
    }

    let count_f = count as f64;
    let centroid = position_sum / count_f;
    let average_velocity = velocity_sum / count_f;
    let spread_yards = snapshot
        .players
        .iter()
        .filter(|player| player.team == team)
        .map(|player| {
            finite_pitch_point(
                snapshot
                    .player_position(player.id)
                    .unwrap_or(player.position),
                width,
                length,
                player.home_position,
            )
            .distance(centroid)
        })
        .sum::<f64>()
        / count_f;

    TeamShapeObservation {
        centroid_to_ball_yards: centroid.distance(ball_position),
        spread_yards,
        players_near_ball,
        forward_velocity_yps: average_velocity.y * team.attack_dir(),
    }
}

fn attacking_shape_support_urgency(snapshot: &WorldSnapshot, team: Team) -> f64 {
    if snapshot.possession_team() != Some(team) {
        return 0.0;
    }
    let shape = team_shape_observation_from_snapshot(snapshot, team, snapshot.ball.position);
    let near_ball_shortage = ((3.0 - shape.players_near_ball as f64) / 3.0).clamp(0.0, 1.0);
    let centroid_gap = ((shape.centroid_to_ball_yards - 14.0) / 30.0).clamp(0.0, 1.0);
    let spread_gap = ((shape.spread_yards - 18.0) / 22.0).clamp(0.0, 1.0);
    let retreating_shape = (-shape.forward_velocity_yps / 5.0).clamp(0.0, 1.0);
    (near_ball_shortage * 0.42 + centroid_gap * 0.30 + spread_gap * 0.20 + retreating_shape * 0.08)
        .clamp(0.0, 1.0)
}

fn holder_pressure_support_urgency(snapshot: &WorldSnapshot, team: Team) -> f64 {
    let Some(holder_id) = snapshot.ball.holder else {
        return 0.0;
    };
    let Some(holder) = snapshot
        .players
        .iter()
        .find(|player| player.id == holder_id)
    else {
        return 0.0;
    };
    if holder.team != team {
        return 0.0;
    }
    let holder_position = snapshot
        .player_position(holder.id)
        .unwrap_or(holder.position);
    let mut nearest = f64::INFINITY;
    let mut close_opponents = 0usize;
    for opponent in snapshot.players.iter().filter(|player| player.team != team) {
        let position = snapshot
            .player_position(opponent.id)
            .unwrap_or(opponent.position);
        let distance = position.distance(holder_position);
        nearest = nearest.min(distance);
        if distance <= 5.5 {
            close_opponents += 1;
        }
    }
    let pressure = pressure_from_nearest_distance(nearest.min(36.0));
    let crowding = (close_opponents as f64 / 3.0).clamp(0.0, 1.0);
    let team_shape = team_shape_observation_from_snapshot(snapshot, team, snapshot.ball.position);
    let outlet_shortage = ((3.0 - team_shape.players_near_ball as f64) / 3.0).clamp(0.0, 1.0);
    (pressure * 0.52 + crowding * 0.32 + outlet_shortage * 0.16).clamp(0.0, 1.0)
}

