fn playback_intent_priority(
    player_id: usize,
    team: Team,
    role: PlayerRole,
    action: &str,
    possession_team: Option<Team>,
    ball_holder: Option<usize>,
) -> Option<f64> {
    let holder_bonus = if ball_holder == Some(player_id) {
        32.0
    } else {
        0.0
    };
    match action {
        "shoot" | "first-time-shot" | "first-time-header" => Some(110.0 + holder_bonus),
        action if is_pass_like_action(action) => Some(104.0 + holder_bonus),
        "clearance" | "route-one" => Some(98.0 + holder_bonus),
        "left-cut"
        | "carry-forward"
        | "carry-out-left"
        | "carry-out-right"
        | "protect-ball"
        | "right-cut"
        | "nutmeg"
        | "fake-left-cut-right"
        | "fake-right-cut-left"
        | "hold-up-flank" => Some(92.0 + holder_bonus),
        action if is_attacking_support_action_label(action) && possession_team == Some(team) => {
            let role_bonus = match role {
                PlayerRole::Forward => 9.0,
                PlayerRole::Midfielder => 7.0,
                PlayerRole::Defender => 3.0,
                PlayerRole::Goalkeeper => 0.0,
            };
            Some(62.0 + role_bonus)
        }
        "recover" if ball_holder.is_none() => Some(58.0),
        _ => None,
    }
}

fn playback_pass_flight_for_action(action: &str) -> Option<PassFlight> {
    pass_like_action_flight(action).or(match action {
        "clearance" | "route-one" => Some(PassFlight::Aerial),
        _ => None,
    })
}

fn playback_selected_action_option_stats(
    decision: &AgentDecisionTrace,
    action: &str,
) -> (f64, f64, f64, usize) {
    let considered_actions = decision
        .action_options
        .iter()
        .filter(|option| option.legal)
        .count();
    let selected = decision
        .action_options
        .iter()
        .find(|option| normalize_soccer_action_label(&option.label) == action)
        .or_else(|| {
            decision
                .action_options
                .iter()
                .find(|option| option.label == decision.action)
        });
    selected
        .map(|option| {
            (
                option.score,
                option.probability.clamp(0.0, 1.0),
                option.tick_probability.clamp(0.0, 1.0),
                considered_actions,
            )
        })
        .unwrap_or((0.0, 0.0, 0.0, considered_actions))
}

fn playback_player_decision_stats(decision: Option<&AgentDecisionTrace>) -> (f64, f64, f64, usize) {
    let Some(decision) = decision else {
        return (0.0, 0.0, 0.0, 0);
    };
    let action = normalize_soccer_action_label(&decision.action);
    playback_selected_action_option_stats(decision, action)
}

fn playback_intent_from_decision(
    player_id: usize,
    team: Team,
    role: PlayerRole,
    decision: &AgentDecisionTrace,
    possession_team: Option<Team>,
    ball_holder: Option<usize>,
    field_width_yards: f64,
    field_length_yards: f64,
) -> Option<(f64, usize, SoccerPlaybackIntentFrame)> {
    let action = normalize_soccer_action_label(&decision.action).to_string();
    let priority =
        playback_intent_priority(player_id, team, role, &action, possession_team, ball_holder)?;
    let action_target = decision.action_target.as_ref();
    let target_point = action_target.and_then(|target| target.point);
    if target_point.is_none() {
        return None;
    }
    let target_grid = action_target
        .and_then(|target| target.grid)
        .or_else(|| {
            target_point
                .map(|point| pitch_grid_address(point, field_width_yards, field_length_yards))
        })
        .map(playback_player_grid_frame);
    let target_facing = action_target
        .map(|target| target.facing)
        .filter(|facing| *facing != FacingBucket::Unknown);
    let urgency = decision.observation.decision_urgency.clamp(0.0, 1.0);
    let (action_score, action_probability, action_tick_probability, considered_actions) =
        playback_selected_action_option_stats(decision, &action);
    Some((
        priority + urgency * 4.0,
        player_id,
        SoccerPlaybackIntentFrame {
            player_id,
            team,
            role,
            action: action.clone(),
            target_point,
            target_player: action_target.and_then(|target| target.player_id),
            target_grid,
            target_facing,
            flight: playback_pass_flight_for_action(&action),
            urgency,
            action_score,
            action_probability,
            action_tick_probability,
            considered_actions,
        },
    ))
}

fn playback_intents_from_frame(frame: &MatchFrame) -> Vec<SoccerPlaybackIntentFrame> {
    playback_intents_from_frame_with_pitch(
        frame,
        DEFAULT_FIELD_WIDTH_YARDS,
        DEFAULT_FIELD_LENGTH_YARDS,
    )
}

fn playback_intents_from_frame_with_pitch(
    frame: &MatchFrame,
    field_width_yards: f64,
    field_length_yards: f64,
) -> Vec<SoccerPlaybackIntentFrame> {
    let possession_team = frame.central_brain.possession_team.or_else(|| {
        frame
            .ball
            .holder
            .and_then(|holder| frame.players.iter().find(|player| player.id == holder))
            .map(|player| player.team)
    });
    let mut candidates = frame
        .players
        .iter()
        .filter_map(|player| {
            let decision = player.last_decision.as_ref()?;
            playback_intent_from_decision(
                player.id,
                player.team,
                player.role,
                decision,
                possession_team,
                frame.ball.holder,
                field_width_yards,
                field_length_yards,
            )
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|a, b| {
        b.0.partial_cmp(&a.0)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.1.cmp(&b.1))
    });
    candidates
        .into_iter()
        .take(8)
        .map(|(_, _, intent)| intent)
        .collect()
}

fn playback_intents_from_agents(
    players: &[PlayerAgent],
    possession_team: Option<Team>,
    ball_holder: Option<usize>,
    field_width_yards: f64,
    field_length_yards: f64,
) -> Vec<SoccerPlaybackIntentFrame> {
    let mut candidates = players
        .iter()
        .filter_map(|player| {
            let decision = player.last_decision.as_ref()?;
            playback_intent_from_decision(
                player.id,
                player.team,
                player.role,
                decision,
                possession_team,
                ball_holder,
                field_width_yards,
                field_length_yards,
            )
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|a, b| {
        b.0.partial_cmp(&a.0)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.1.cmp(&b.1))
    });
    candidates
        .into_iter()
        .take(8)
        .map(|(_, _, intent)| intent)
        .collect()
}

impl SoccerPlaybackFrame {
    fn from_match(sim: &SoccerMatch) -> Self {
        let ball_holder_team = sim.ball.holder.and_then(|holder| {
            sim.players
                .iter()
                .find(|player| player.id == holder)
                .map(|player| player.team)
        });
        let possession_team = sim
            .central_brain
            .possession_team
            .or(ball_holder_team)
            .or(sim.ball.last_touch_team);
        let pending_pass = WorldSnapshot::from_match_with_options(
            sim,
            WorldSnapshotOptions::DEFENSIVE_OR_LOOSE_AGENT_DECISION,
        )
        .pending_pass;

        SoccerPlaybackFrame {
            tick: sim.tick,
            clock_seconds: sim.clock_seconds,
            ball: SoccerPlaybackBallFrame {
                position: sim.ball.position,
                velocity: sim.ball.velocity,
                acceleration: sim.ball.acceleration,
                jerk: sim.ball.jerk,
                decision_speed_yps: sim
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.velocity.len())
                    .unwrap_or_else(|| sim.ball.velocity.len()),
                decision_altitude_yards: sim
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.altitude_yards)
                    .unwrap_or(sim.ball.altitude_yards),
                decision_curl_yps2: sim
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.curl_acceleration.len())
                    .unwrap_or_else(|| sim.ball.curl_acceleration.len()),
                scheduled_index: sim
                    .last_agent_schedule
                    .iter()
                    .position(|entry| entry.kind == AgentScheduleKind::Ball),
                last_action: sim
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.action.clone()),
                operation_order: sim
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.operation_order.clone())
                    .unwrap_or_default(),
                altitude_yards: sim.ball.altitude_yards,
                holder: sim.ball.holder,
                last_touch_team: sim.ball.last_touch_team,
            },
            pending_pass,
            players: sim
                .players
                .iter()
                .map(|player| {
                    let (
                        action_score,
                        action_probability,
                        action_tick_probability,
                        considered_actions,
                    ) = playback_player_decision_stats(player.last_decision.as_ref());
                    SoccerPlaybackPlayerFrame {
                        id: player.id,
                        name: player.name.clone(),
                        team: player.team,
                        role: player.role,
                        shirt: player.shirt,
                        position: player.position,
                        velocity: player.velocity,
                        player_grid: playback_player_grid_frame(pitch_grid_address(
                            player.position,
                            sim.config.field_width_yards,
                            sim.config.field_length_yards,
                        )),
                        movement_gait: player.movement_gait,
                        receive_facing: player.receive_facing,
                        action_facing: player.action_facing,
                        controller_slot: player.controller_slot,
                        scheduled_index: sim.last_agent_schedule.iter().position(|entry| {
                            entry.kind == AgentScheduleKind::Player && entry.id == player.id
                        }),
                        last_action: player
                            .last_decision
                            .as_ref()
                            .map(|decision| decision.action.clone()),
                        operation_order: player
                            .last_decision
                            .as_ref()
                            .map(|decision| decision.operation_order.clone())
                            .unwrap_or_default(),
                        action_score,
                        action_probability,
                        action_tick_probability,
                        considered_actions,
                    }
                })
                .collect(),
            officials: sim
                .officials
                .iter()
                .map(|official| SoccerPlaybackOfficialFrame {
                    id: official.id,
                    kind: official.kind,
                    position: official.position,
                    velocity: official.velocity,
                    acceleration: official.acceleration,
                    jerk: official.jerk,
                    scheduled_index: sim.last_agent_schedule.iter().position(|entry| {
                        entry.kind == AgentScheduleKind::Official && entry.id == official.id
                    }),
                    last_action: official
                        .last_decision
                        .as_ref()
                        .map(|decision| decision.action.clone()),
                    operation_order: official
                        .last_decision
                        .as_ref()
                        .map(|decision| decision.operation_order.clone())
                        .unwrap_or_default(),
                })
                .collect(),
            score_home: sim.score_home,
            score_away: sim.score_away,
            phase: sim.central_brain.phase,
            central_brain: SoccerPlaybackCentralBrainFrame {
                possession_team,
                ball_holder: sim.ball.holder,
                tracked_players: sim.players.iter().map(|player| player.id).collect(),
                tracked_officials: sim.officials.len(),
                home_shape: sim
                    .central_brain
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.home_shape.clone()),
                away_shape: sim
                    .central_brain
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.away_shape.clone()),
            },
            agent_schedule_summary: agent_schedule_summary_for(
                &sim.last_agent_schedule,
                sim.players.len(),
                sim.officials.len(),
            ),
            home_directive: SoccerPlaybackDirectiveFrame {
                press_intensity: sim.central_brain.home_directive.press_intensity,
                risk_tolerance: sim.central_brain.home_directive.risk_tolerance,
                flank_attack_policy: sim.central_brain.home_directive.flank_attack_policy,
                flank_overlap_run_probability: sim
                    .central_brain
                    .home_directive
                    .flank_overlap_run_probability,
            },
            away_directive: SoccerPlaybackDirectiveFrame {
                press_intensity: sim.central_brain.away_directive.press_intensity,
                risk_tolerance: sim.central_brain.away_directive.risk_tolerance,
                flank_attack_policy: sim.central_brain.away_directive.flank_attack_policy,
                flank_overlap_run_probability: sim
                    .central_brain
                    .away_directive
                    .flank_overlap_run_probability,
            },
            intents: playback_intents_from_agents(
                &sim.players,
                possession_team,
                sim.ball.holder,
                sim.config.field_width_yards,
                sim.config.field_length_yards,
            ),
        }
    }
}

impl From<&MatchFrame> for SoccerPlaybackFrame {
    fn from(frame: &MatchFrame) -> Self {
        SoccerPlaybackFrame {
            tick: frame.tick,
            clock_seconds: frame.clock_seconds,
            ball: SoccerPlaybackBallFrame {
                position: frame.ball.position,
                velocity: frame.ball.velocity,
                acceleration: frame.ball.acceleration,
                jerk: frame.ball.jerk,
                decision_speed_yps: frame
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.velocity.len())
                    .unwrap_or_else(|| frame.ball.velocity.len()),
                decision_altitude_yards: frame
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.altitude_yards)
                    .unwrap_or(frame.ball.altitude_yards),
                decision_curl_yps2: frame
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.curl_acceleration.len())
                    .unwrap_or_else(|| frame.ball.curl_acceleration.len()),
                scheduled_index: frame.ball.scheduled_index,
                last_action: frame
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.action.clone()),
                operation_order: frame
                    .ball
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.operation_order.clone())
                    .unwrap_or_default(),
                altitude_yards: frame.ball.altitude_yards,
                holder: frame.ball.holder,
                last_touch_team: frame.ball.last_touch_team,
            },
            pending_pass: frame.pending_pass.clone(),
            players: frame
                .players
                .iter()
                .map(|player| {
                    let (
                        action_score,
                        action_probability,
                        action_tick_probability,
                        considered_actions,
                    ) = playback_player_decision_stats(player.last_decision.as_ref());
                    SoccerPlaybackPlayerFrame {
                        id: player.id,
                        name: player.name.clone(),
                        team: player.team,
                        role: player.role,
                        shirt: player.shirt,
                        position: player.position,
                        velocity: player.velocity,
                        player_grid: playback_player_grid_frame(pitch_grid_address(
                            player.position,
                            DEFAULT_FIELD_WIDTH_YARDS,
                            DEFAULT_FIELD_LENGTH_YARDS,
                        )),
                        movement_gait: player.movement_gait,
                        receive_facing: player.receive_facing,
                        action_facing: player.action_facing,
                        controller_slot: player.controller_slot,
                        scheduled_index: player.scheduled_index,
                        last_action: player
                            .last_decision
                            .as_ref()
                            .map(|decision| decision.action.clone()),
                        operation_order: player
                            .last_decision
                            .as_ref()
                            .map(|decision| decision.operation_order.clone())
                            .unwrap_or_default(),
                        action_score,
                        action_probability,
                        action_tick_probability,
                        considered_actions,
                    }
                })
                .collect(),
            officials: frame
                .officials
                .iter()
                .map(|official| SoccerPlaybackOfficialFrame {
                    id: official.id,
                    kind: official.kind,
                    position: official.position,
                    velocity: official.velocity,
                    acceleration: official.acceleration,
                    jerk: official.jerk,
                    scheduled_index: official.scheduled_index,
                    last_action: official
                        .last_decision
                        .as_ref()
                        .map(|decision| decision.action.clone()),
                    operation_order: official
                        .last_decision
                        .as_ref()
                        .map(|decision| decision.operation_order.clone())
                        .unwrap_or_default(),
                })
                .collect(),
            score_home: frame.score_home,
            score_away: frame.score_away,
            phase: frame.phase,
            central_brain: SoccerPlaybackCentralBrainFrame {
                possession_team: frame.central_brain.possession_team,
                ball_holder: frame.central_brain.ball_holder,
                tracked_players: frame
                    .central_brain
                    .tracked_players
                    .iter()
                    .map(|player| player.id)
                    .collect(),
                tracked_officials: frame.central_brain.tracked_officials,
                home_shape: frame
                    .central_brain
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.home_shape.clone()),
                away_shape: frame
                    .central_brain
                    .last_decision
                    .as_ref()
                    .map(|decision| decision.away_shape.clone()),
            },
            agent_schedule_summary: frame.agent_schedule_summary.clone(),
            home_directive: SoccerPlaybackDirectiveFrame {
                press_intensity: frame.home_directive.press_intensity,
                risk_tolerance: frame.home_directive.risk_tolerance,
                flank_attack_policy: frame.home_directive.flank_attack_policy,
                flank_overlap_run_probability: frame.home_directive.flank_overlap_run_probability,
            },
            away_directive: SoccerPlaybackDirectiveFrame {
                press_intensity: frame.away_directive.press_intensity,
                risk_tolerance: frame.away_directive.risk_tolerance,
                flank_attack_policy: frame.away_directive.flank_attack_policy,
                flank_overlap_run_probability: frame.away_directive.flank_overlap_run_probability,
            },
            intents: playback_intents_from_frame(frame),
        }
    }
}

