impl SoccerTeamPolicyArtifact {
    pub fn postgres_branch_tip_export(
        &self,
        request: SoccerPolicyPostgresBranchTipExportRequest,
    ) -> Result<SoccerPolicyPostgresBranchTipExport, String> {
        validate_soccer_policy_postgres_export_request(&request)?;
        let mut entries = Vec::with_capacity(
            self.home_entries.len()
                + self.away_entries.len()
                + self.home_target_entries.len()
                + self.away_target_entries.len(),
        );
        append_soccer_policy_postgres_action_rows(
            &mut entries,
            Team::Home,
            &self.home_entries,
            request.source_run_id.clone(),
        )?;
        append_soccer_policy_postgres_action_rows(
            &mut entries,
            Team::Away,
            &self.away_entries,
            request.source_run_id.clone(),
        )?;
        append_soccer_policy_postgres_target_rows(
            &mut entries,
            Team::Home,
            &self.home_target_entries,
            request.source_run_id.clone(),
        )?;
        append_soccer_policy_postgres_target_rows(
            &mut entries,
            Team::Away,
            &self.away_target_entries,
            request.source_run_id.clone(),
        )?;

        let entry_count = self.home_entries.len() + self.away_entries.len();
        let target_entry_count = self.home_target_entries.len() + self.away_target_entries.len();
        let visit_count = entries
            .iter()
            .map(|entry| u64::from(entry.visits))
            .sum::<u64>();
        let options = serde_json::json!({
            "home": self.home_options,
            "away": self.away_options,
        });
        let config = serde_json::to_value(&self.config)
            .map_err(|err| format!("serialize postgres policy config: {err}"))?;
        let lineage = match request.parent_policy_version_id.as_ref() {
            Some(parent) => serde_json::json!([parent]),
            None => serde_json::json!([]),
        };
        let policy_dimensions = soccer_policy_postgres_dimension_summary(&entries);
        let metrics = serde_json::json!({
            "summary": self.summary,
            "learning": self.learning,
            "tacticalSummary": self.tactical_summary,
            "adversarial": self.adversarial,
            "homeActionProbabilityStates": self.home_action_probabilities.len(),
            "awayActionProbabilityStates": self.away_action_probabilities.len(),
            "policyDimensions": &policy_dimensions,
        });

        Ok(SoccerPolicyPostgresBranchTipExport {
            artifact_schema: "SoccerTeamPolicyArtifact/v1".to_string(),
            contract: SoccerPolicyPostgresStorageContract::default(),
            policy_dimensions,
            version: SoccerPolicyPostgresPolicyVersionRow {
                experiment_slug: request.experiment_slug,
                policy_version_id: request.policy_version_id,
                parent_policy_version_id: request.parent_policy_version_id,
                generation: request.generation,
                version_label: request.version_label,
                source_kind: request.source_kind,
                status: request.status,
                options,
                config,
                lineage,
                metrics,
                entry_count,
                target_entry_count,
                visit_count,
                fitness_micros: request.fitness_micros,
            },
            entries,
        })
    }
}

fn validate_soccer_policy_postgres_export_request(
    request: &SoccerPolicyPostgresBranchTipExportRequest,
) -> Result<(), String> {
    let slug = request.experiment_slug.trim();
    if slug.len() < 3
        || slug.len() > 160
        || !slug.chars().all(|c| {
            c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '.' | '_' | '/' | '-')
        })
        || !slug
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        || !slug
            .chars()
            .last()
            .is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
    {
        return Err(format!(
            "invalid soccer policy postgres experiment slug: {slug}"
        ));
    }
    let label = request.version_label.trim();
    if label.is_empty()
        || label.len() > 160
        || !label
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | ':' | '/' | '-'))
    {
        return Err(format!(
            "invalid soccer policy postgres version label: {label}"
        ));
    }
    if !matches!(
        request.source_kind.as_str(),
        "seed" | "merge" | "mutation" | "crossover" | "import" | "replay"
    ) {
        return Err(format!(
            "invalid soccer policy postgres source kind: {}",
            request.source_kind
        ));
    }
    if !matches!(
        request.status.as_str(),
        "candidate" | "active" | "archived" | "rejected"
    ) {
        return Err(format!(
            "invalid soccer policy postgres status: {}",
            request.status
        ));
    }
    Ok(())
}

fn append_soccer_policy_postgres_action_rows(
    rows: &mut Vec<SoccerPolicyPostgresPolicyEntryRow>,
    team: Team,
    entries: &[SoccerQEntry],
    source_run_id: Option<String>,
) -> Result<(), String> {
    for entry in entries {
        rows.push(soccer_policy_postgres_row_from_action_entry(
            team,
            entry,
            source_run_id.clone(),
        )?);
    }
    Ok(())
}

fn append_soccer_policy_postgres_target_rows(
    rows: &mut Vec<SoccerPolicyPostgresPolicyEntryRow>,
    team: Team,
    entries: &[SoccerQTargetEntry],
    source_run_id: Option<String>,
) -> Result<(), String> {
    for entry in entries {
        rows.push(soccer_policy_postgres_row_from_target_entry(
            team,
            entry,
            source_run_id.clone(),
        )?);
    }
    Ok(())
}

fn soccer_policy_postgres_row_from_action_entry(
    team: Team,
    entry: &SoccerQEntry,
    source_run_id: Option<String>,
) -> Result<SoccerPolicyPostgresPolicyEntryRow, String> {
    soccer_policy_postgres_entry_row(
        team,
        "action",
        &entry.state,
        &entry.action,
        -1,
        -1,
        -1,
        -1,
        entry.value,
        entry.visits,
        source_run_id,
    )
}

fn soccer_policy_postgres_row_from_target_entry(
    team: Team,
    entry: &SoccerQTargetEntry,
    source_run_id: Option<String>,
) -> Result<SoccerPolicyPostgresPolicyEntryRow, String> {
    soccer_policy_postgres_entry_row(
        team,
        "target",
        &entry.state,
        &entry.action,
        soccer_policy_postgres_cell_id(entry.target_fine_cell_id)?,
        soccer_policy_postgres_cell_id(entry.target_tactical_cell_id)?,
        soccer_policy_postgres_cell_id(entry.target_macro_cell_id)?,
        soccer_policy_postgres_cell_id(entry.target_root_cell_id)?,
        entry.value,
        entry.visits,
        source_run_id,
    )
}

#[allow(clippy::too_many_arguments)]
fn soccer_policy_postgres_entry_row(
    team: Team,
    entry_kind: &str,
    state: &SoccerQStateKey,
    action: &str,
    target_fine_cell_id: i32,
    target_tactical_cell_id: i32,
    target_macro_cell_id: i32,
    target_root_cell_id: i32,
    value: f64,
    visits: u32,
    source_run_id: Option<String>,
) -> Result<SoccerPolicyPostgresPolicyEntryRow, String> {
    let state_key = soccer_policy_postgres_state_key(state)?;
    let state_hash = soccer_policy_postgres_state_hash(&state_key)?;
    let action = normalize_soccer_action_label(action).to_string();
    let role_scope = soccer_policy_role_storage_label(state.role).to_string();
    let player_fine_cell_id = soccer_policy_postgres_cell_id(state.player_fine_cell_id)?;
    let player_tactical_cell_id = soccer_policy_postgres_cell_id(state.player_tactical_cell_id)?;
    let player_macro_cell_id = soccer_policy_postgres_cell_id(state.player_macro_cell_id)?;
    let player_root_cell_id = soccer_policy_postgres_cell_id(state.player_root_cell_id)?;
    let scope_key = soccer_policy_postgres_scope_key(
        team,
        &role_scope,
        player_fine_cell_id,
        player_tactical_cell_id,
        player_macro_cell_id,
        player_root_cell_id,
    );
    if action.is_empty() || action.len() > 80 {
        return Err(format!(
            "soccer policy postgres action must be 1..=80 bytes, got {}",
            action.len()
        ));
    }
    Ok(SoccerPolicyPostgresPolicyEntryRow {
        team: soccer_policy_postgres_team(team).to_string(),
        entry_kind: entry_kind.to_string(),
        state_hash,
        state_key,
        role_scope,
        player_fine_cell_id,
        player_tactical_cell_id,
        player_macro_cell_id,
        player_root_cell_id,
        scope_key,
        action,
        target_fine_cell_id,
        target_tactical_cell_id,
        target_macro_cell_id,
        target_root_cell_id,
        value_micros: soccer_policy_value_micros(value),
        visits,
        source_run_id,
    })
}

fn soccer_policy_postgres_scope_key(
    team: Team,
    role_scope: &str,
    player_fine_cell_id: i32,
    player_tactical_cell_id: i32,
    player_macro_cell_id: i32,
    player_root_cell_id: i32,
) -> String {
    format!(
        "team={}:role={role_scope}:fine={player_fine_cell_id}:tactical={player_tactical_cell_id}:macro={player_macro_cell_id}:root={player_root_cell_id}",
        soccer_policy_postgres_team(team)
    )
}

fn soccer_policy_postgres_team(team: Team) -> &'static str {
    match team {
        Team::Home => "home",
        Team::Away => "away",
    }
}

fn soccer_policy_role_storage_label(role: PlayerRole) -> &'static str {
    match role {
        PlayerRole::Goalkeeper => "goalkeeper",
        PlayerRole::Defender => "defender",
        PlayerRole::Midfielder => "midfielder",
        PlayerRole::Forward => "forward",
    }
}

fn normalize_soccer_policy_role_storage_label(raw: &str) -> String {
    match raw.trim().to_ascii_lowercase().as_str() {
        "goalkeeper" | "keeper" | "gk" => soccer_policy_role_storage_label(PlayerRole::Goalkeeper),
        "defender" | "defense" | "centreback" | "centerback" | "fullback" => {
            soccer_policy_role_storage_label(PlayerRole::Defender)
        }
        "midfielder" | "midfield" | "mid" => {
            soccer_policy_role_storage_label(PlayerRole::Midfielder)
        }
        "forward" | "striker" | "attacker" => soccer_policy_role_storage_label(PlayerRole::Forward),
        other => other,
    }
    .to_string()
}

fn soccer_policy_postgres_entry_role(entry: &SoccerPolicyPostgresPolicyEntryRow) -> String {
    if !entry.role_scope.is_empty() {
        return normalize_soccer_policy_role_storage_label(&entry.role_scope);
    }
    entry
        .state_key
        .get("role")
        .and_then(|role| role.as_str())
        .map(normalize_soccer_policy_role_storage_label)
        .unwrap_or_else(|| "unknown".to_string())
}

fn soccer_policy_postgres_dimension_summary(
    entries: &[SoccerPolicyPostgresPolicyEntryRow],
) -> SoccerPolicyPostgresDimensionSummary {
    let mut by_role = BTreeMap::<String, SoccerPolicyPostgresRoleDimensionSummary>::new();
    for role in [
        PlayerRole::Goalkeeper,
        PlayerRole::Defender,
        PlayerRole::Midfielder,
        PlayerRole::Forward,
    ] {
        let label = soccer_policy_role_storage_label(role).to_string();
        by_role.insert(
            label.clone(),
            SoccerPolicyPostgresRoleDimensionSummary {
                role: label,
                ..Default::default()
            },
        );
    }

    let mut summary = SoccerPolicyPostgresDimensionSummary::default();
    for entry in entries {
        match entry.entry_kind.as_str() {
            "action" => summary.global_action_entry_count += 1,
            "target" => summary.global_target_entry_count += 1,
            _ => {}
        }
        summary.global_total_entry_count += 1;
        summary.global_visit_count += u64::from(entry.visits);

        let role = soccer_policy_postgres_entry_role(entry);
        let role_summary = by_role.entry(role.clone()).or_insert_with(|| {
            SoccerPolicyPostgresRoleDimensionSummary {
                role,
                ..Default::default()
            }
        });
        match entry.entry_kind.as_str() {
            "action" => role_summary.action_entry_count += 1,
            "target" => role_summary.target_entry_count += 1,
            _ => {}
        }
        role_summary.total_entry_count += 1;
        role_summary.visit_count += u64::from(entry.visits);
    }
    summary.role_counts = by_role.into_values().collect();
    summary
}

fn soccer_policy_postgres_cell_id(cell_id: usize) -> Result<i32, String> {
    i32::try_from(cell_id).map_err(|_| format!("soccer policy target cell id too large: {cell_id}"))
}

fn soccer_policy_postgres_state_key(state: &SoccerQStateKey) -> Result<serde_json::Value, String> {
    serde_json::to_value(state).map_err(|err| format!("serialize soccer policy state key: {err}"))
}

fn soccer_policy_postgres_state_hash(state: &serde_json::Value) -> Result<String, String> {
    let bytes = serde_json::to_vec(state)
        .map_err(|err| format!("serialize soccer policy state hash input: {err}"))?;
    let mut hash = 14_695_981_039_346_656_037_u64;
    for byte in bytes {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(1_099_511_628_211);
    }
    Ok(format!("{hash:016x}"))
}

fn soccer_policy_value_micros(value: f64) -> i64 {
    let micros = finite_metric(value) * SOCCER_POLICY_VALUE_MICROS_SCALE;
    if micros >= i64::MAX as f64 {
        i64::MAX
    } else if micros <= i64::MIN as f64 {
        i64::MIN
    } else {
        micros.round() as i64
    }
}

impl SoccerTrackingDataset {
    pub fn validate(&self) -> Result<(), String> {
        if self.config.dt_seconds <= 0.0 {
            return Err("tracking dataset config.dtSeconds must be positive".to_string());
        }
        if self.config.field_length_yards <= 0.0 || self.config.field_width_yards <= 0.0 {
            return Err("tracking dataset field dimensions must be positive".to_string());
        }
        if self.frames.len() < 2 {
            return Err("tracking dataset needs at least two frames".to_string());
        }
        for (idx, frame) in self.frames.iter().enumerate() {
            if frame.players.is_empty() {
                return Err(format!("tracking frame {idx} has no players"));
            }
            if let Some(holder) = frame.ball_holder {
                if !frame.players.iter().any(|p| p.id == holder) {
                    return Err(format!(
                        "tracking frame {idx} ballHolder {holder} is missing from players"
                    ));
                }
            }
            if let Some(action_player) = frame.action_player {
                if !frame.players.iter().any(|p| p.id == action_player) {
                    return Err(format!(
                        "tracking frame {idx} actionPlayer {action_player} is missing from players"
                    ));
                }
            }
            if let Some(action) = frame.ball_action.as_deref() {
                normalize_tracking_ball_action(action).map_err(|e| {
                    format!("tracking frame {idx} ballAction {action:?} is invalid: {e}")
                })?;
            }
            validate_optional_tracking_confidence(
                frame.tracking_confidence,
                &format!("tracking frame {idx} trackingConfidence"),
            )?;
            validate_optional_tracking_confidence(
                frame.ball_confidence,
                &format!("tracking frame {idx} ballConfidence"),
            )?;
            for player in &frame.players {
                validate_optional_tracking_confidence(
                    player.tracking_confidence,
                    &format!(
                        "tracking frame {idx} player {} trackingConfidence",
                        player.id
                    ),
                )?;
            }
        }
        Ok(())
    }

    pub fn to_learning_dataset(&self) -> Result<SoccerLearningDataset, String> {
        soccer_tracking_dataset_to_learning_dataset(self)
    }
}

fn validate_optional_tracking_confidence(
    confidence: Option<f64>,
    label: &str,
) -> Result<(), String> {
    if let Some(confidence) = confidence {
        if !confidence.is_finite() || !(0.0..=1.0).contains(&confidence) {
            return Err(format!("{label} must be finite and between 0 and 1"));
        }
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SoccerPhysicsSmokeLimits {
    pub player_max_speed_yps: f64,
    pub ball_max_speed_yps: f64,
    pub player_max_accel_yps2: f64,
    pub ball_max_accel_yps2: f64,
    pub pitch_margin_yards: f64,
    pub frame_epsilon_yards: f64,
}

impl Default for SoccerPhysicsSmokeLimits {
    fn default() -> Self {
        Self {
            player_max_speed_yps: SOCCER_PHYSICS_PLAYER_MAX_SPEED_YPS,
            ball_max_speed_yps: SOCCER_PHYSICS_BALL_MAX_SPEED_YPS,
            player_max_accel_yps2: SOCCER_PHYSICS_PLAYER_MAX_ACCEL_YPS2,
            ball_max_accel_yps2: SOCCER_PHYSICS_BALL_MAX_ACCEL_YPS2,
            pitch_margin_yards: SOCCER_PHYSICS_PITCH_MARGIN_YARDS,
            frame_epsilon_yards: SOCCER_PHYSICS_FRAME_EPSILON_YARDS,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SoccerPhysicsSmokeViolation {
    pub tick: u64,
    pub subject: String,
    pub metric: String,
    pub value: f64,
    pub limit: f64,
    pub message: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SoccerPhysicsSmokeReport {
    pub frames_analyzed: usize,
    pub full_time_reached: bool,
    pub max_player_speed_yps: f64,
    pub max_ball_speed_yps: f64,
    pub max_player_accel_yps2: f64,
    pub max_ball_accel_yps2: f64,
    pub max_player_frame_speed_yps: f64,
    pub max_ball_frame_speed_yps: f64,
    pub violation_count: usize,
    pub violations: Vec<SoccerPhysicsSmokeViolation>,
}

impl SoccerPhysicsSmokeReport {
    pub fn ok(&self) -> bool {
        self.violations.is_empty()
    }

    fn push_violation(
        &mut self,
        tick: u64,
        subject: impl Into<String>,
        metric: impl Into<String>,
        value: f64,
        limit: f64,
        message: impl Into<String>,
    ) {
        self.violations.push(SoccerPhysicsSmokeViolation {
            tick,
            subject: subject.into(),
            metric: metric.into(),
            value,
            limit,
            message: message.into(),
        });
        self.violation_count = self.violations.len();
    }
}

pub fn soccer_simulation_physics_smoke_report(trace: &SimulationTrace) -> SoccerPhysicsSmokeReport {
    soccer_match_frame_physics_smoke_report_with_limits(
        &trace.config,
        &trace.frames,
        SoccerPhysicsSmokeLimits::default(),
    )
}

pub fn soccer_match_frame_physics_smoke_report(
    config: &MatchConfig,
    frames: &[MatchFrame],
) -> SoccerPhysicsSmokeReport {
    soccer_match_frame_physics_smoke_report_with_limits(
        config,
        frames,
        SoccerPhysicsSmokeLimits::default(),
    )
}

pub fn soccer_match_frame_physics_smoke_report_with_limits(
    config: &MatchConfig,
    frames: &[MatchFrame],
    limits: SoccerPhysicsSmokeLimits,
) -> SoccerPhysicsSmokeReport {
    let mut report = SoccerPhysicsSmokeReport {
        frames_analyzed: frames.len(),
        full_time_reached: frames
            .last()
            .is_some_and(|frame| frame.tick >= config.total_ticks()),
        ..SoccerPhysicsSmokeReport::default()
    };
    if frames.is_empty() {
        report.push_violation(0, "match", "frames", 0.0, 1.0, "no frames to analyze");
        return report;
    }

    let mut previous_clock = None::<f64>;
    let mut previous_ball = None::<(u64, f64, Vec2)>;
    let mut previous_players = HashMap::<usize, (u64, f64, Vec2)>::new();
    for frame in frames {
        check_clock_monotonicity(
            &mut report,
            frame.tick,
            frame.clock_seconds,
            &mut previous_clock,
        );
        check_position_bounds(
            &mut report,
            frame.tick,
            "ball",
            frame.ball.position,
            config,
            limits.pitch_margin_yards,
        );
        if let Some(value) = check_motion_vector(
            &mut report,
            frame.tick,
            "ball",
            "velocity",
            frame.ball.velocity,
            limits.ball_max_speed_yps,
        ) {
            report.max_ball_speed_yps = report.max_ball_speed_yps.max(value);
        }
        if let Some(value) = check_motion_vector(
            &mut report,
            frame.tick,
            "ball",
            "acceleration",
            frame.ball.acceleration,
            limits.ball_max_accel_yps2,
        ) {
            report.max_ball_accel_yps2 = report.max_ball_accel_yps2.max(value);
        }
        if let Some((prev_tick, prev_clock, prev_pos)) = previous_ball {
            if let Some(value) = check_frame_displacement(
                &mut report,
                frame.tick,
                "ball",
                prev_tick,
                prev_clock,
                prev_pos,
                frame.clock_seconds,
                frame.ball.position,
                limits.ball_max_speed_yps,
                limits.frame_epsilon_yards,
            ) {
                report.max_ball_frame_speed_yps = report.max_ball_frame_speed_yps.max(value);
            }
        }
        previous_ball = Some((frame.tick, frame.clock_seconds, frame.ball.position));

        for player in &frame.players {
            let subject = format!("player:{}", player.id);
            check_position_bounds(
                &mut report,
                frame.tick,
                &subject,
                player.position,
                config,
                limits.pitch_margin_yards,
            );
            if let Some(value) = check_motion_vector(
                &mut report,
                frame.tick,
                &subject,
                "velocity",
                player.velocity,
                limits.player_max_speed_yps,
            ) {
                report.max_player_speed_yps = report.max_player_speed_yps.max(value);
            }
            if let Some(value) = check_motion_vector(
                &mut report,
                frame.tick,
                &subject,
                "acceleration",
                player.acceleration,
                limits.player_max_accel_yps2,
            ) {
                report.max_player_accel_yps2 = report.max_player_accel_yps2.max(value);
            }
            if let Some((prev_tick, prev_clock, prev_pos)) =
                previous_players.get(&player.id).copied()
            {
                if let Some(value) = check_frame_displacement(
                    &mut report,
                    frame.tick,
                    &subject,
                    prev_tick,
                    prev_clock,
                    prev_pos,
                    frame.clock_seconds,
                    player.position,
                    limits.player_max_speed_yps,
                    limits.frame_epsilon_yards,
                ) {
                    report.max_player_frame_speed_yps =
                        report.max_player_frame_speed_yps.max(value);
                }
            }
            previous_players.insert(
                player.id,
                (frame.tick, frame.clock_seconds, player.position),
            );
        }
    }
    report.violation_count = report.violations.len();
    report
}

pub fn soccer_tracking_physics_smoke_report(
    tracking: &SoccerTrackingDataset,
) -> SoccerPhysicsSmokeReport {
    soccer_tracking_physics_smoke_report_with_limits(tracking, SoccerPhysicsSmokeLimits::default())
}

pub fn soccer_tracking_physics_smoke_report_with_limits(
    tracking: &SoccerTrackingDataset,
    limits: SoccerPhysicsSmokeLimits,
) -> SoccerPhysicsSmokeReport {
    let mut report = SoccerPhysicsSmokeReport {
        frames_analyzed: tracking.frames.len(),
        full_time_reached: tracking
            .frames
            .last()
            .is_some_and(|frame| frame.tick >= tracking.config.total_ticks()),
        ..SoccerPhysicsSmokeReport::default()
    };
    if tracking.frames.is_empty() {
        report.push_violation(0, "tracking", "frames", 0.0, 1.0, "no frames to analyze");
        return report;
    }

    let frames = tracking_frames_with_inferred_kinematics(tracking);
    let mut previous_clock = None::<f64>;
    let mut previous_ball = None::<(u64, f64, Vec2)>;
    let mut previous_players = HashMap::<usize, (u64, f64, Vec2)>::new();
    for frame in &frames {
        check_clock_monotonicity(
            &mut report,
            frame.tick,
            frame.clock_seconds,
            &mut previous_clock,
        );
        check_position_bounds(
            &mut report,
            frame.tick,
            "ball",
            frame.ball_position,
            &tracking.config,
            limits.pitch_margin_yards,
        );
        let ball_velocity = frame.ball_velocity.unwrap_or(Vec2::zero());
        let ball_acceleration = frame.ball_acceleration.unwrap_or(Vec2::zero());
        if let Some(value) = check_motion_vector(
            &mut report,
            frame.tick,
            "ball",
            "velocity",
            ball_velocity,
            limits.ball_max_speed_yps,
        ) {
            report.max_ball_speed_yps = report.max_ball_speed_yps.max(value);
        }
        if let Some(value) = check_motion_vector(
            &mut report,
            frame.tick,
            "ball",
            "acceleration",
            ball_acceleration,
            limits.ball_max_accel_yps2,
        ) {
            report.max_ball_accel_yps2 = report.max_ball_accel_yps2.max(value);
        }
        if let Some((prev_tick, prev_clock, prev_pos)) = previous_ball {
            if let Some(value) = check_frame_displacement(
                &mut report,
                frame.tick,
                "ball",
                prev_tick,
                prev_clock,
                prev_pos,
                frame.clock_seconds,
                frame.ball_position,
                limits.ball_max_speed_yps,
                limits.frame_epsilon_yards,
            ) {
                report.max_ball_frame_speed_yps = report.max_ball_frame_speed_yps.max(value);
            }
        }
        previous_ball = Some((frame.tick, frame.clock_seconds, frame.ball_position));

        for player in &frame.players {
            let subject = format!("player:{}", player.id);
            check_position_bounds(
                &mut report,
                frame.tick,
                &subject,
                player.position,
                &tracking.config,
                limits.pitch_margin_yards,
            );
            let velocity = player.velocity.unwrap_or(Vec2::zero());
            let acceleration = player.motion_acceleration.unwrap_or(Vec2::zero());
            if let Some(value) = check_motion_vector(
                &mut report,
                frame.tick,
                &subject,
                "velocity",
                velocity,
                limits.player_max_speed_yps,
            ) {
                report.max_player_speed_yps = report.max_player_speed_yps.max(value);
            }
            if let Some(value) = check_motion_vector(
                &mut report,
                frame.tick,
                &subject,
                "acceleration",
                acceleration,
                limits.player_max_accel_yps2,
            ) {
                report.max_player_accel_yps2 = report.max_player_accel_yps2.max(value);
            }
            if let Some((prev_tick, prev_clock, prev_pos)) =
                previous_players.get(&player.id).copied()
            {
                if let Some(value) = check_frame_displacement(
                    &mut report,
                    frame.tick,
                    &subject,
                    prev_tick,
                    prev_clock,
                    prev_pos,
                    frame.clock_seconds,
                    player.position,
                    limits.player_max_speed_yps,
                    limits.frame_epsilon_yards,
                ) {
                    report.max_player_frame_speed_yps =
                        report.max_player_frame_speed_yps.max(value);
                }
            }
            previous_players.insert(
                player.id,
                (frame.tick, frame.clock_seconds, player.position),
            );
        }
    }
    report.violation_count = report.violations.len();
    report
}

fn check_clock_monotonicity(
    report: &mut SoccerPhysicsSmokeReport,
    tick: u64,
    clock_seconds: f64,
    previous_clock: &mut Option<f64>,
) {
    if !clock_seconds.is_finite() {
        report.push_violation(
            tick,
            "clock",
            "finite",
            clock_seconds,
            0.0,
            "clock seconds must be finite",
        );
        return;
    }
    if let Some(previous) = *previous_clock {
        if clock_seconds + 1e-9 < previous {
            report.push_violation(
                tick,
                "clock",
                "monotonic",
                clock_seconds - previous,
                0.0,
                "clock moved backwards between frames",
            );
        }
    }
    *previous_clock = Some(clock_seconds);
}

fn check_position_bounds(
    report: &mut SoccerPhysicsSmokeReport,
    tick: u64,
    subject: &str,
    position: Vec2,
    config: &MatchConfig,
    margin: f64,
) {
    if !vec2_is_finite(position) {
        report.push_violation(
            tick,
            subject,
            "positionFinite",
            0.0,
            0.0,
            "position must be finite",
        );
        return;
    }
    let x_limit = config.field_width_yards + margin.max(0.0);
    let y_limit = config.field_length_yards + margin.max(0.0);
    let outside = (-margin - position.x)
        .max(position.x - x_limit)
        .max(-margin - position.y)
        .max(position.y - y_limit);
    if outside > 0.0 {
        report.push_violation(
            tick,
            subject,
            "pitchBounds",
            outside,
            0.0,
            "position left the tolerated pitch bounds",
        );
    }
}

fn check_motion_vector(
    report: &mut SoccerPhysicsSmokeReport,
    tick: u64,
    subject: &str,
    metric: &str,
    vector: Vec2,
    limit: f64,
) -> Option<f64> {
    if !vec2_is_finite(vector) {
        report.push_violation(
            tick,
            subject,
            format!("{metric}Finite"),
            0.0,
            0.0,
            format!("{metric} must be finite"),
        );
        return None;
    }
    let value = vector.len();
    if value > limit {
        report.push_violation(
            tick,
            subject,
            metric,
            value,
            limit,
            format!("{metric} exceeded smoke-test limit"),
        );
    }
    Some(value)
}

#[allow(clippy::too_many_arguments)]
fn check_frame_displacement(
    report: &mut SoccerPhysicsSmokeReport,
    tick: u64,
    subject: &str,
    previous_tick: u64,
    previous_clock: f64,
    previous_position: Vec2,
    clock_seconds: f64,
    position: Vec2,
    speed_limit: f64,
    epsilon_yards: f64,
) -> Option<f64> {
    let dt = clock_seconds - previous_clock;
    if dt <= 1e-9 || !dt.is_finite() {
        report.push_violation(
            tick,
            subject,
            "frameDt",
            dt,
            0.0,
            format!("non-positive frame dt after tick {previous_tick}"),
        );
        return None;
    }
    if !vec2_is_finite(previous_position) || !vec2_is_finite(position) {
        return None;
    }
    let distance = position.distance(previous_position);
    let inferred_speed = distance / dt;
    let tolerated_speed = speed_limit + epsilon_yards.max(0.0) / dt;
    if inferred_speed > tolerated_speed {
        report.push_violation(
            tick,
            subject,
            "frameDisplacementSpeed",
            inferred_speed,
            tolerated_speed,
            format!("frame-to-frame displacement is impossible after tick {previous_tick}"),
        );
    }
    Some(inferred_speed)
}

fn vec2_is_finite(value: Vec2) -> bool {
    value.x.is_finite() && value.y.is_finite()
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SoccerAccountingSmokeViolation {
    pub tick: u64,
    pub subject: String,
    pub metric: String,
    pub expected: String,
    pub actual: String,
    pub message: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SoccerAccountingSmokeReport {
    pub frames_analyzed: usize,
    pub events_analyzed: usize,
    pub full_time_reached: bool,
    pub possession_frames: usize,
    pub non_possession_frames: usize,
    pub home_possession_frames: usize,
    pub away_possession_frames: usize,
    pub fifty_fifty_duel_frames: usize,
    pub moving_player_count: usize,
    pub player_movement_yards: f64,
    pub ball_movement_yards: f64,
    pub ball_goalward_progress_yards: f64,
    pub ball_active_frames: usize,
    pub score_home_from_goal_events: u32,
    pub score_away_from_goal_events: u32,
    pub violation_count: usize,
    pub violations: Vec<SoccerAccountingSmokeViolation>,
}

impl SoccerAccountingSmokeReport {
    pub fn ok(&self) -> bool {
        self.violations.is_empty()
    }

    fn push_violation(
        &mut self,
        tick: u64,
        subject: impl Into<String>,
        metric: impl Into<String>,
        expected: impl Into<String>,
        actual: impl Into<String>,
        message: impl Into<String>,
    ) {
        self.violations.push(SoccerAccountingSmokeViolation {
            tick,
            subject: subject.into(),
            metric: metric.into(),
            expected: expected.into(),
            actual: actual.into(),
            message: message.into(),
        });
        self.violation_count = self.violations.len();
    }
}

pub fn soccer_simulation_accounting_smoke_report(
    trace: &SimulationTrace,
) -> SoccerAccountingSmokeReport {
    let mut report = SoccerAccountingSmokeReport {
        frames_analyzed: trace.frames.len(),
        events_analyzed: trace.events.len(),
        full_time_reached: trace
            .frames
            .last()
            .is_some_and(|frame| frame.tick >= trace.config.total_ticks()),
        score_home_from_goal_events: trace
            .events
            .iter()
            .filter(|event| event.kind == "goal" && event.team == Some(Team::Home))
            .count() as u32,
        score_away_from_goal_events: trace
            .events
            .iter()
            .filter(|event| event.kind == "goal" && event.team == Some(Team::Away))
            .count() as u32,
        ..SoccerAccountingSmokeReport::default()
    };

    soccer_accounting_check_frames(trace, &mut report);
    soccer_accounting_check_events(trace, &mut report);
    soccer_accounting_check_stats(trace, &mut report);
    report.violation_count = report.violations.len();
    report
}

fn soccer_accounting_check_frames(
    trace: &SimulationTrace,
    report: &mut SoccerAccountingSmokeReport,
) {
    let Some(last_frame) = trace.frames.last() else {
        report.push_violation(
            0,
            "match",
            "frames",
            "at least one frame",
            "0",
            "accounting smoke needs frames",
        );
        return;
    };

    if last_frame.tick != trace.summary.ticks {
        report.push_violation(
            last_frame.tick,
            "summary",
            "ticks",
            trace.summary.ticks.to_string(),
            last_frame.tick.to_string(),
            "last frame tick should match summary ticks",
        );
    }
    if last_frame.score_home != trace.summary.score_home {
        report.push_violation(
            last_frame.tick,
            "summary",
            "scoreHome",
            trace.summary.score_home.to_string(),
            last_frame.score_home.to_string(),
            "last frame home score should match summary",
        );
    }
    if last_frame.score_away != trace.summary.score_away {
        report.push_violation(
            last_frame.tick,
            "summary",
            "scoreAway",
            trace.summary.score_away.to_string(),
            last_frame.score_away.to_string(),
            "last frame away score should match summary",
        );
    }

    let mut previous = None::<(u64, f64, u32, u32)>;
    for frame in &trace.frames {
        if let Some((prev_tick, prev_clock, prev_home, prev_away)) = previous {
            if frame.tick < prev_tick {
                report.push_violation(
                    frame.tick,
                    "frame",
                    "tickOrder",
                    format!(">= {prev_tick}"),
                    frame.tick.to_string(),
                    "frame ticks must be monotonic",
                );
            }
            if frame.clock_seconds + 1e-9 < prev_clock {
                report.push_violation(
                    frame.tick,
                    "frame",
                    "clockOrder",
                    format!(">= {prev_clock:.6}"),
                    format!("{:.6}", frame.clock_seconds),
                    "frame clocks must be monotonic",
                );
            }
            if frame.score_home < prev_home || frame.score_away < prev_away {
                report.push_violation(
                    frame.tick,
                    "score",
                    "monotonic",
                    format!("home >= {prev_home}, away >= {prev_away}"),
                    format!("home {}, away {}", frame.score_home, frame.score_away),
                    "scores must not decrease between frames",
                );
            }
        }
        previous = Some((
            frame.tick,
            frame.clock_seconds,
            frame.score_home,
            frame.score_away,
        ));

        soccer_accounting_check_frame_roster(frame, report);
        soccer_accounting_check_frame_ball_accounting(frame, report);
        soccer_accounting_check_frame_shared_positions(frame, report);
        soccer_accounting_check_frame_histories(frame, report);
        soccer_accounting_check_agent_schedule(frame, report);
    }

    soccer_accounting_check_frame_buckets(trace, report);
    soccer_accounting_check_frame_liveness(trace, report);
}

fn soccer_accounting_check_frame_liveness(
    trace: &SimulationTrace,
    report: &mut SoccerAccountingSmokeReport,
) {
    if trace.frames.len() < 2 || trace.summary.ticks == 0 {
        return;
    }

    let mut previous_players = HashMap::<usize, Vec2>::new();
    let mut previous_ball = None::<Vec2>;
    let mut moving_players = HashSet::<usize>::new();
    for frame in &trace.frames {
        if let Some(prev_ball) = previous_ball {
            let movement = frame.ball.position.distance(prev_ball);
            if movement.is_finite() {
                report.ball_movement_yards += movement;
            }
            if let Some(team) = soccer_accounting_frame_ball_team(frame) {
                let goalward = (frame.ball.position.y - prev_ball.y) * team.attack_dir();
                if goalward.is_finite() && goalward > 0.0 {
                    report.ball_goalward_progress_yards += goalward;
                }
            }
        }
        if frame.ball.holder.is_some() || frame.ball.velocity.len() > 0.05 {
            report.ball_active_frames = report.ball_active_frames.saturating_add(1);
        }
        previous_ball = Some(frame.ball.position);

        for player in &frame.players {
            if let Some(prev) = previous_players.insert(player.id, player.position) {
                let movement = player.position.distance(prev);
                if movement.is_finite() {
                    report.player_movement_yards += movement;
                    if movement > 0.025 {
                        moving_players.insert(player.id);
                    }
                }
            }
        }
    }
    report.moving_player_count = moving_players.len();

    let expected_movers = if trace.summary.ticks >= 5 { 6 } else { 2 };
    if report.moving_player_count < expected_movers {
        report.push_violation(
            trace.summary.ticks,
            "liveness",
            "movingPlayers",
            format!(">= {expected_movers}"),
            report.moving_player_count.to_string(),
            "multi-frame soccer simulation should have active player movement",
        );
    }

    if report.ball_active_frames == 0 && report.ball_movement_yards <= 0.025 {
        report.push_violation(
            trace.summary.ticks,
            "liveness",
            "ballActivity",
            "controlled ball or movement",
            format!(
                "activeFrames={} movement={:.6}",
                report.ball_active_frames, report.ball_movement_yards
            ),
            "multi-frame soccer simulation should keep the ball active or controlled",
        );
    }

    if trace.summary.ticks >= 5 && report.ball_goalward_progress_yards <= 0.10 {
        report.push_violation(
            trace.summary.ticks,
            "liveness",
            "ballGoalwardProgress",
            "> 0.10".to_string(),
            format!("{:.6}", report.ball_goalward_progress_yards),
            "multi-frame soccer simulation should move the ball toward a team's goal at least once",
        );
    }
}

fn soccer_accounting_frame_ball_team(frame: &MatchFrame) -> Option<Team> {
    frame
        .ball
        .holder
        .and_then(|holder| {
            frame
                .players
                .iter()
                .find(|player| player.id == holder)
                .map(|player| player.team)
        })
        .or(frame.central_brain.possession_team)
        .or(frame.ball.last_touch_team)
}

fn soccer_accounting_check_frame_roster(
    frame: &MatchFrame,
    report: &mut SoccerAccountingSmokeReport,
) {
    let mut ids = HashSet::new();
    let mut home = 0usize;
    let mut away = 0usize;
    let mut home_gk = 0usize;
    let mut away_gk = 0usize;
    for player in &frame.players {
        if !ids.insert(player.id) {
            report.push_violation(
                frame.tick,
                "players",
                "uniquePlayerIds",
                "unique ids",
                format!("duplicate {}", player.id),
                "frame contains duplicate player ids",
            );
        }
        match player.team {
            Team::Home => {
                home += 1;
                if player.role == PlayerRole::Goalkeeper {
                    home_gk += 1;
                }
            }
            Team::Away => {
                away += 1;
                if player.role == PlayerRole::Goalkeeper {
                    away_gk += 1;
                }
            }
        }
    }
    if frame.players.len() != 22 || home != 11 || away != 11 {
        report.push_violation(
            frame.tick,
            "players",
            "rosterSize",
            "22 players: 11 home, 11 away",
            format!("total {}, home {home}, away {away}", frame.players.len()),
            "11v11 frame roster accounting is invalid",
        );
    }
    if home_gk != 1 || away_gk != 1 {
        report.push_violation(
            frame.tick,
            "players",
            "goalkeepers",
            "one goalkeeper per team",
            format!("home {home_gk}, away {away_gk}"),
            "frame should have exactly one goalkeeper per team",
        );
    }
}

fn soccer_accounting_check_frame_ball_accounting(
    frame: &MatchFrame,
    report: &mut SoccerAccountingSmokeReport,
) {
    soccer_accounting_record_frame_possession_bucket(frame, report);

    if frame.central_brain.ball_holder != frame.ball.holder {
        report.push_violation(
            frame.tick,
            "centralBrain",
            "ballHolderConsistency",
            format!("{:?}", frame.ball.holder),
            format!("{:?}", frame.central_brain.ball_holder),
            "central brain holder should match ball state holder",
        );
    }

    if let Some(holder) = frame.ball.holder {
        let Some(holder_player) = frame.players.iter().find(|player| player.id == holder) else {
            report.push_violation(
                frame.tick,
                "ball",
                "holderExists",
                "holder id in players",
                holder.to_string(),
                "ball holder is missing from frame players",
            );
            return;
        };
        if frame.ball.last_touch_team != Some(holder_player.team) {
            report.push_violation(
                frame.tick,
                "ball",
                "lastTouchTeam",
                holder_player.team.label(),
                format!("{:?}", frame.ball.last_touch_team),
                "a controlled ball should have last touch credited to the holder team",
            );
        }
        if let Some(set_play) = &frame.active_set_play {
            if set_play.team != holder_player.team {
                report.push_violation(
                    frame.tick,
                    "setPlay",
                    "restartHolderTeam",
                    set_play.team.label(),
                    holder_player.team.label(),
                    "active set-play holder should be on the restart team",
                );
            }
        }
    }
}

fn soccer_accounting_record_frame_possession_bucket(
    frame: &MatchFrame,
    report: &mut SoccerAccountingSmokeReport,
) {
    if soccer_accounting_frame_fifty_fifty_duel(frame) {
        report.non_possession_frames += 1;
        report.fifty_fifty_duel_frames += 1;
        return;
    }

    if let Some(holder) = frame.ball.holder {
        report.possession_frames += 1;
        if let Some(holder_player) = frame.players.iter().find(|player| player.id == holder) {
            match holder_player.team {
                Team::Home => report.home_possession_frames += 1,
                Team::Away => report.away_possession_frames += 1,
            }
        }
    } else if let Some(team) = frame.central_brain.possession_team {
        report.possession_frames += 1;
        match team {
            Team::Home => report.home_possession_frames += 1,
            Team::Away => report.away_possession_frames += 1,
        }
    } else {
        report.non_possession_frames += 1;
    }
}

fn soccer_accounting_check_frame_shared_positions(
    frame: &MatchFrame,
    report: &mut SoccerAccountingSmokeReport,
) {
    const POSITION_EPSILON_YARDS: f64 = 1e-6;
    const CLOCK_EPSILON_SECONDS: f64 = 1e-9;

    for player in &frame.players {
        let Some(sample) = frame.shared_positions.latest_for(player.id) else {
            report.push_violation(
                frame.tick,
                "sharedPositions",
                "playerLatest",
                format!("player {}", player.id),
                "missing".to_string(),
                "shared position data should expose every player's latest x/y position",
            );
            continue;
        };
        if sample.tick != frame.tick
            || (sample.clock_seconds - frame.clock_seconds).abs() > CLOCK_EPSILON_SECONDS
            || sample.position.distance(player.position) > POSITION_EPSILON_YARDS
        {
            report.push_violation(
                frame.tick,
                "sharedPositions",
                "playerLatestConsistency",
                format!(
                    "id {} tick {} clock {:.6} pos {:?}",
                    player.id, frame.tick, frame.clock_seconds, player.position
                ),
                format!(
                    "id {} tick {} clock {:.6} pos {:?}",
                    sample.player_id, sample.tick, sample.clock_seconds, sample.position
                ),
                "shared player position sample should match the authoritative player state",
            );
        }
    }

    for official in &frame.officials {
        let Some(sample) = frame.shared_positions.official_latest_for(official.id) else {
            report.push_violation(
                frame.tick,
                "sharedPositions",
                "officialLatest",
                format!("official {}", official.id),
                "missing".to_string(),
                "shared position data should expose every official's latest x/y position",
            );
            continue;
        };
        if sample.tick != frame.tick
            || (sample.clock_seconds - frame.clock_seconds).abs() > CLOCK_EPSILON_SECONDS
            || sample.position.distance(official.position) > POSITION_EPSILON_YARDS
        {
            report.push_violation(
                frame.tick,
                "sharedPositions",
                "officialLatestConsistency",
                format!(
                    "id {} tick {} clock {:.6} pos {:?}",
                    official.id, frame.tick, frame.clock_seconds, official.position
                ),
                format!(
                    "id {} tick {} clock {:.6} pos {:?}",
                    sample.official_id, sample.tick, sample.clock_seconds, sample.position
                ),
                "shared official position sample should match the authoritative official state",
            );
        }
    }

    let Some(ball_sample) = frame.shared_positions.ball_latest() else {
        report.push_violation(
            frame.tick,
            "sharedPositions",
            "ballLatest",
            "ball latest sample",
            "missing".to_string(),
            "shared position data should expose the ball's latest x/y position",
        );
        return;
    };
    if ball_sample.tick != frame.tick
        || (ball_sample.clock_seconds - frame.clock_seconds).abs() > CLOCK_EPSILON_SECONDS
        || ball_sample.position.distance(frame.ball.position) > POSITION_EPSILON_YARDS
    {
        report.push_violation(
            frame.tick,
            "sharedPositions",
            "ballLatestConsistency",
            format!(
                "tick {} clock {:.6} pos {:?}",
                frame.tick, frame.clock_seconds, frame.ball.position
            ),
            format!(
                "tick {} clock {:.6} pos {:?}",
                ball_sample.tick, ball_sample.clock_seconds, ball_sample.position
            ),
            "shared ball position sample should match the authoritative ball state",
        );
    }
}

fn soccer_accounting_expected_history_len(tick: u64, limit: usize) -> usize {
    usize::try_from(tick)
        .unwrap_or(usize::MAX)
        .saturating_add(1)
        .min(limit)
        .max(1)
}

fn soccer_accounting_check_frame_histories(
    frame: &MatchFrame,
    report: &mut SoccerAccountingSmokeReport,
) {
    const POSITION_EPSILON_YARDS: f64 = 1e-6;
    let expected_player_history =
        soccer_accounting_expected_history_len(frame.tick, PLAYER_POSITION_HISTORY_LIMIT);
    let expected_ball_history =
        soccer_accounting_expected_history_len(frame.tick, BALL_POSITION_HISTORY_LIMIT);

    for player in &frame.players {
        if player.position_history.len() > PLAYER_POSITION_HISTORY_LIMIT
            || player.position_history.len() < expected_player_history
        {
            report.push_violation(
                frame.tick,
                "history",
                "playerPositionHistory",
                format!(
                    "{}..={}",
                    expected_player_history, PLAYER_POSITION_HISTORY_LIMIT
                ),
                format!("player {} len {}", player.id, player.position_history.len()),
                "full playback frames should retain each player's rolling 50-position history",
            );
        }
        if player
            .position_history
            .last()
            .is_none_or(|position| position.distance(player.position) > POSITION_EPSILON_YARDS)
        {
            report.push_violation(
                frame.tick,
                "history",
                "playerPositionHistoryLatest",
                format!("player {} latest {:?}", player.id, player.position),
                format!("last {:?}", player.position_history.last()),
                "player history should end at the authoritative player position",
            );
        }

        let shared_history_len = frame
            .shared_positions
            .history_for(player.id)
            .map(|history| history.len())
            .unwrap_or(0);
        if shared_history_len > PLAYER_POSITION_HISTORY_LIMIT
            || shared_history_len < expected_player_history
        {
            report.push_violation(
                frame.tick,
                "sharedPositions",
                "playerHistory",
                format!(
                    "player {} len {}..={}",
                    player.id, expected_player_history, PLAYER_POSITION_HISTORY_LIMIT
                ),
                shared_history_len.to_string(),
                "shared position data should retain each player's rolling 50-sample history",
            );
        }
    }

    for official in &frame.officials {
        if official.position_history.len() > PLAYER_POSITION_HISTORY_LIMIT
            || official.position_history.len() < expected_player_history
        {
            report.push_violation(
                frame.tick,
                "history",
                "officialPositionHistory",
                format!(
                    "{}..={}",
                    expected_player_history, PLAYER_POSITION_HISTORY_LIMIT
                ),
                format!(
                    "official {} len {}",
                    official.id,
                    official.position_history.len()
                ),
                "full playback frames should retain each official's rolling 50-position history",
            );
        }
        if official
            .position_history
            .last()
            .is_none_or(|position| position.distance(official.position) > POSITION_EPSILON_YARDS)
        {
            report.push_violation(
                frame.tick,
                "history",
                "officialPositionHistoryLatest",
                format!("official {} latest {:?}", official.id, official.position),
                format!("last {:?}", official.position_history.last()),
                "official history should end at the authoritative official position",
            );
        }

        let shared_history_len = frame
            .shared_positions
            .official_history_for(official.id)
            .map(|history| history.len())
            .unwrap_or(0);
        if shared_history_len > PLAYER_POSITION_HISTORY_LIMIT
            || shared_history_len < expected_player_history
        {
            report.push_violation(
                frame.tick,
                "sharedPositions",
                "officialHistory",
                format!(
                    "official {} len {}..={}",
                    official.id, expected_player_history, PLAYER_POSITION_HISTORY_LIMIT
                ),
                shared_history_len.to_string(),
                "shared position data should retain each official's rolling 50-sample history",
            );
        }
    }

    if frame.ball_history.len() > BALL_POSITION_HISTORY_LIMIT
        || frame.ball_history.len() < expected_ball_history
    {
        report.push_violation(
            frame.tick,
            "history",
            "ballPositionHistory",
            format!(
                "{}..={}",
                expected_ball_history, BALL_POSITION_HISTORY_LIMIT
            ),
            frame.ball_history.len().to_string(),
            "full playback frames should retain the ball agent's rolling 50-sample history",
        );
    }
    if frame
        .ball_history
        .last()
        .is_none_or(|sample| sample.position.distance(frame.ball.position) > POSITION_EPSILON_YARDS)
    {
        report.push_violation(
            frame.tick,
            "history",
            "ballPositionHistoryLatest",
            format!("ball latest {:?}", frame.ball.position),
            format!(
                "last {:?}",
                frame.ball_history.last().map(|sample| sample.position)
            ),
            "ball history should end at the authoritative ball position",
        );
    }

    let shared_ball_history_len = frame.shared_positions.ball_history().len();
    if shared_ball_history_len > BALL_POSITION_HISTORY_LIMIT
        || shared_ball_history_len < expected_ball_history
    {
        report.push_violation(
            frame.tick,
            "sharedPositions",
            "ballHistory",
            format!(
                "{}..={}",
                expected_ball_history, BALL_POSITION_HISTORY_LIMIT
            ),
            shared_ball_history_len.to_string(),
            "shared position data should retain the ball agent's rolling 50-sample history",
        );
    }
}

fn soccer_accounting_check_frame_buckets(
    trace: &SimulationTrace,
    report: &mut SoccerAccountingSmokeReport,
) {
    let frame_total = trace.frames.len();
    let possession_total = report.possession_frames + report.non_possession_frames;
    if possession_total != frame_total {
        report.push_violation(
            trace.summary.ticks,
            "frames",
            "possessionBucketTotal",
            frame_total.to_string(),
            possession_total.to_string(),
            "possession and non-possession frames should partition all frames",
        );
    }

    let team_total = report.home_possession_frames + report.away_possession_frames;
    if team_total != report.possession_frames {
        report.push_violation(
            trace.summary.ticks,
            "frames",
            "teamPossessionBucketTotal",
            report.possession_frames.to_string(),
            team_total.to_string(),
            "home and away possession frames should add up to possession frames",
        );
    }

    if report.fifty_fifty_duel_frames > report.non_possession_frames {
        report.push_violation(
            trace.summary.ticks,
            "frames",
            "fiftyFiftySubset",
            format!("<= {}", report.non_possession_frames),
            report.fifty_fifty_duel_frames.to_string(),
            "50-50 duel frames should be a subset of non-possession frames",
        );
    }
}

fn soccer_accounting_frame_fifty_fifty_duel(frame: &MatchFrame) -> bool {
    if frame.ball.holder.is_some()
        || !vec2_is_finite(frame.ball.position)
        || frame.ball.velocity.len() > SOCCER_ACCOUNTING_FIFTY_FIFTY_MAX_BALL_SPEED_YPS
    {
        return false;
    }

    let Some(home) = soccer_accounting_nearest_ball_challenger(frame, Team::Home) else {
        return false;
    };
    let Some(away) = soccer_accounting_nearest_ball_challenger(frame, Team::Away) else {
        return false;
    };

    home.0.min(away.0) <= SOCCER_ACCOUNTING_FIFTY_FIFTY_MAX_DISTANCE_YARDS
        && (home.0 - away.0).abs() <= SOCCER_ACCOUNTING_FIFTY_FIFTY_MAX_DISTANCE_DELTA_YARDS
        && (home.1 - away.1).abs() <= SOCCER_ACCOUNTING_FIFTY_FIFTY_MAX_CLOSING_DELTA
}

fn soccer_accounting_nearest_ball_challenger(frame: &MatchFrame, team: Team) -> Option<(f64, f64)> {
    frame
        .players
        .iter()
        .filter(|player| player.team == team)
        .filter_map(|player| {
            if !vec2_is_finite(player.position) || !vec2_is_finite(player.velocity) {
                return None;
            }
            let to_ball = frame.ball.position - player.position;
            let distance = to_ball.len();
            if !distance.is_finite() {
                return None;
            }
            let closing = if distance <= 1e-9 {
                0.0
            } else {
                player.velocity.normalized().dot(to_ball.normalized())
            };
            Some((distance, closing.clamp(-1.0, 1.0)))
        })
        .min_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal))
}

fn soccer_accounting_check_agent_schedule(
    frame: &MatchFrame,
    report: &mut SoccerAccountingSmokeReport,
) {
    if frame.agent_schedule.is_empty() {
        if frame.tick == 0 {
            return;
        }
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "length",
            "scheduled agents after an executed tick",
            "0",
            "agent schedule is missing after the simulation tick ran",
        );
        return;
    }

    let mut seen = HashSet::new();
    for (idx, entry) in frame.agent_schedule.iter().enumerate() {
        let key = format!("{:?}:{}", entry.kind, entry.id);
        if !seen.insert(key.clone()) {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "uniqueAgents",
                "unique (kind,id)",
                key,
                "agent schedule contains duplicate entries",
            );
        }
        if entry.kind == AgentScheduleKind::CentralBrain
            && (idx != 0 || entry.id != CENTRAL_BRAIN_AGENT_ID)
        {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "centralBrainSlot",
                format!("slot 0 id {CENTRAL_BRAIN_AGENT_ID}"),
                format!("slot {idx} id {}", entry.id),
                "central brain should be the first scheduled agent",
            );
        }
    }

    let expected_len = 1 + frame.players.len() + frame.officials.len() + 1;
    if frame.agent_schedule.len() != expected_len {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "length",
            expected_len.to_string(),
            frame.agent_schedule.len().to_string(),
            "agent schedule should include central brain, every player, every official, and ball",
        );
    }
    if frame
        .agent_schedule
        .first()
        .map(|entry| (&entry.kind, entry.id))
        != Some((&AgentScheduleKind::CentralBrain, CENTRAL_BRAIN_AGENT_ID))
    {
        let actual = frame
            .agent_schedule
            .first()
            .map(|entry| format!("{:?}:{}", entry.kind, entry.id))
            .unwrap_or_else(|| "none".to_string());
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "firstAgent",
            format!("CentralBrain:{CENTRAL_BRAIN_AGENT_ID}"),
            actual,
            "central brain should run before the shuffled field agents",
        );
    }
    if frame.central_brain.scheduled_index != Some(0) {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "centralBrainScheduledIndex",
            "Some(0)".to_string(),
            format!("{:?}", frame.central_brain.scheduled_index),
            "central brain snapshot should expose its fixed schedule index",
        );
    }

    let central_count = frame
        .agent_schedule
        .iter()
        .filter(|entry| entry.kind == AgentScheduleKind::CentralBrain)
        .count();
    let player_count = frame
        .agent_schedule
        .iter()
        .filter(|entry| entry.kind == AgentScheduleKind::Player)
        .count();
    let official_count = frame
        .agent_schedule
        .iter()
        .filter(|entry| entry.kind == AgentScheduleKind::Official)
        .count();
    let ball_count = frame
        .agent_schedule
        .iter()
        .filter(|entry| entry.kind == AgentScheduleKind::Ball)
        .count();
    for (metric, expected, actual) in [
        ("centralBrainCount", 1usize, central_count),
        ("playerCount", frame.players.len(), player_count),
        ("officialCount", frame.officials.len(), official_count),
        ("ballCount", 1usize, ball_count),
    ] {
        if expected != actual {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                metric,
                expected.to_string(),
                actual.to_string(),
                "agent schedule has the wrong count for this agent kind",
            );
        }
    }

    if let Some(decision) = frame.central_brain.last_decision.as_ref() {
        if decision.scheduled_index != Some(0) {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "centralBrainDecisionScheduledIndex",
                "Some(0)".to_string(),
                format!("{:?}", decision.scheduled_index),
                "central brain decision trace should expose the fixed schedule index",
            );
        }
        if decision.operation_order.is_empty() {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "centralBrainDecisionOperationOrder",
                "non-empty".to_string(),
                "empty".to_string(),
                "central brain decision trace should expose the internal operation order",
            );
        }
        soccer_accounting_check_operation_order_contains(
            report,
            frame.tick,
            "centralBrainDecisionOperationOrderItems",
            &decision.operation_order,
            &[
                "sense-possession",
                "classify-phase",
                "sample-defensive-cover",
                "measure-overloads",
                "issue-team-directives",
            ],
            "central brain operation order should expose its internal tactical loop",
        );
    } else if frame.tick > 0 {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "centralBrainDecisionTrace",
            "present".to_string(),
            "missing".to_string(),
            "scheduled central brain should expose its run_time_step decision trace",
        );
    }

    if !frame
        .agent_schedule
        .iter()
        .any(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID)
    {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "ballAgent",
            format!("Ball:{BALL_AGENT_ID}"),
            "missing".to_string(),
            "ball should be scheduled as its own agent",
        );
    }

    for player in &frame.players {
        let scheduled_index = frame
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Player && entry.id == player.id);
        if scheduled_index.is_none() {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "playerScheduled",
                format!("player {}", player.id),
                "missing".to_string(),
                "every player should appear exactly once in the field-agent schedule",
            );
        }
        if player.scheduled_index != scheduled_index {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "playerScheduledIndex",
                format!("{scheduled_index:?}"),
                format!("{:?}", player.scheduled_index),
                "player snapshot should expose its shuffled schedule index",
            );
        }
    }

    for official in &frame.officials {
        let scheduled_index = frame
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Official && entry.id == official.id);
        if scheduled_index.is_none() {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "officialScheduled",
                format!("official {}", official.id),
                "missing".to_string(),
                "every official should appear exactly once in the field-agent schedule",
            );
        }
        if official.scheduled_index != scheduled_index {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "officialScheduledIndex",
                format!("{scheduled_index:?}"),
                format!("{:?}", official.scheduled_index),
                "official snapshot should expose its shuffled schedule index",
            );
        }
        if let Some(decision) = official.last_decision.as_ref() {
            if decision.scheduled_index != scheduled_index {
                report.push_violation(
                    frame.tick,
                    "agentSchedule",
                    "officialDecisionScheduledIndex",
                    format!("{scheduled_index:?}"),
                    format!("{:?}", decision.scheduled_index),
                    "official decision trace should expose the official agent schedule index",
                );
            }
            if decision.operation_order.is_empty() {
                report.push_violation(
                    frame.tick,
                    "agentSchedule",
                    "officialDecisionOperationOrder",
                    "non-empty".to_string(),
                    "empty".to_string(),
                    "official decision trace should expose the internal operation order",
                );
            }
            soccer_accounting_check_operation_order_contains(
                report,
                frame.tick,
                "officialDecisionOperationOrderItems",
                &decision.operation_order,
                &[
                    "sense-ball",
                    "sample-offside-line",
                    "choose-referee-target",
                    "avoid-player-lanes",
                    "clamp-duty-zone",
                    "update-kinematics",
                ],
                "official operation order should expose the referee's internal loop",
            );
        }
    }

    let scheduled_index = frame
        .agent_schedule
        .iter()
        .position(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID);
    if frame.central_brain.ball_scheduled_index != scheduled_index {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "centralBrainBallScheduledIndex",
            format!("{scheduled_index:?}"),
            format!("{:?}", frame.central_brain.ball_scheduled_index),
            "central brain snapshot should expose the ball agent schedule index",
        );
    }
    if frame.ball.scheduled_index != scheduled_index {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "ballScheduledIndex",
            format!("{scheduled_index:?}"),
            format!("{:?}", frame.ball.scheduled_index),
            "ball state should expose the ball agent schedule index",
        );
    }
    if let Some(decision) = frame.ball.last_decision.as_ref() {
        if decision.scheduled_index != scheduled_index {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "ballDecisionScheduledIndex",
                format!("{scheduled_index:?}"),
                format!("{:?}", decision.scheduled_index),
                "ball decision trace should expose the ball agent schedule index",
            );
        }
        if decision.operation_order.is_empty() {
            report.push_violation(
                frame.tick,
                "agentSchedule",
                "ballDecisionOperationOrder",
                "non-empty".to_string(),
                "empty".to_string(),
                "ball decision trace should expose the ball agent internal operation order",
            );
        }
        soccer_accounting_check_operation_order_contains(
            report,
            frame.tick,
            "ballDecisionOperationOrderItems",
            &decision.operation_order,
            &[
                "sync-holder",
                "apply-curl",
                "apply-resistance",
                "advance-position",
                "resolve-shot",
                "resolve-boundary",
                "resolve-control",
            ],
            "ball operation order should expose its full run_time_step loop",
        );
    } else if scheduled_index.is_some() {
        report.push_violation(
            frame.tick,
            "agentSchedule",
            "ballDecisionTrace",
            "present".to_string(),
            "missing".to_string(),
            "scheduled ball agent should expose its run_time_step decision trace",
        );
    }
}

fn soccer_accounting_check_operation_order_contains(
    report: &mut SoccerAccountingSmokeReport,
    tick: u64,
    metric: &str,
    operation_order: &[String],
    expected: &[&str],
    message: &str,
) {
    for op in expected {
        if !operation_order.iter().any(|actual| actual == op) {
            report.push_violation(
                tick,
                "agentSchedule",
                metric,
                expected.join(","),
                operation_order.join(","),
                message,
            );
            return;
        }
    }
}

fn soccer_accounting_check_events(
    trace: &SimulationTrace,
    report: &mut SoccerAccountingSmokeReport,
) {
    let known_players = trace
        .frames
        .iter()
        .flat_map(|frame| frame.players.iter().map(|player| player.id))
        .collect::<HashSet<_>>();
    let mut previous = None::<(u64, f64)>;
    let mut by_tick = BTreeMap::<u64, Vec<&MatchEvent>>::new();
    for event in &trace.events {
        if event.kind.trim().is_empty() {
            report.push_violation(
                event.tick,
                "event",
                "kind",
                "non-empty",
                "empty",
                "event kind must not be empty",
            );
        }
        if event.tick > trace.summary.ticks {
            report.push_violation(
                event.tick,
                "event",
                "tickWithinMatch",
                format!("<= {}", trace.summary.ticks),
                event.tick.to_string(),
                "event tick exceeds the match summary",
            );
        }
        if !event.clock_seconds.is_finite() {
            report.push_violation(
                event.tick,
                "event",
                "clockFinite",
                "finite",
                format!("{:?}", event.clock_seconds),
                "event clock must be finite",
            );
        }
        if let Some((prev_tick, prev_clock)) = previous {
            if event.tick < prev_tick
                || (event.tick == prev_tick && event.clock_seconds + 1e-9 < prev_clock)
            {
                report.push_violation(
                    event.tick,
                    "event",
                    "eventOrder",
                    format!("after tick {prev_tick} clock {prev_clock:.6}"),
                    format!("tick {} clock {:.6}", event.tick, event.clock_seconds),
                    "events should be emitted in chronological order",
                );
            }
        }
        previous = Some((event.tick, event.clock_seconds));

        if let Some(player_id) = event.player_id {
            if !known_players.is_empty() && !known_players.contains(&player_id) {
                report.push_violation(
                    event.tick,
                    "event",
                    "playerId",
                    "known player id",
                    player_id.to_string(),
                    "event references a player not present in match frames",
                );
            }
        }
        if soccer_accounting_team_required_event(&event.kind) && event.team.is_none() {
            report.push_violation(
                event.tick,
                "event",
                "team",
                "team present",
                "None",
                "team-scoped event is missing a team",
            );
        }
        by_tick.entry(event.tick).or_default().push(event);
    }

    for (tick, events) in by_tick {
        soccer_accounting_check_exclusive_event_class(
            report,
            tick,
            "restartEvents",
            "at most one restart event per tick",
            events
                .iter()
                .copied()
                .filter(|event| soccer_accounting_restart_event(&event.kind)),
        );
        soccer_accounting_check_exclusive_event_class(
            report,
            tick,
            "shotTerminalEvents",
            "at most one terminal shot outcome per tick",
            events
                .iter()
                .copied()
                .filter(|event| soccer_accounting_shot_terminal_event(&event.kind)),
        );
        soccer_accounting_check_exclusive_event_class(
            report,
            tick,
            "goalEvents",
            "at most one goal event per tick",
            events.iter().copied().filter(|event| event.kind == "goal"),
        );
    }
}

fn soccer_accounting_check_exclusive_event_class<'a>(
    report: &mut SoccerAccountingSmokeReport,
    tick: u64,
    metric: &str,
    expected: &str,
    events: impl Iterator<Item = &'a MatchEvent>,
) {
    let labels = events
        .map(|event| format!("{}:{:?}", event.kind, event.team))
        .collect::<Vec<_>>();
    if labels.len() > 1 {
        report.push_violation(
            tick,
            "events",
            metric,
            expected,
            labels.join(","),
            "mutually exclusive event accounting collided in one tick",
        );
    }
}

fn soccer_accounting_restart_event(kind: &str) -> bool {
    matches!(
        kind,
        "kickoff" | "throw-in" | "goal-kick" | "corner-kick" | "free-kick"
    )
}

fn soccer_accounting_shot_terminal_event(kind: &str) -> bool {
    matches!(kind, "goal" | "miss" | "save" | "shot-blocked")
}

fn soccer_accounting_team_required_event(kind: &str) -> bool {
    matches!(
        kind,
        "goal"
            | "shot"
            | "miss"
            | "save"
            | "shot-blocked"
            | "throw-in"
            | "goal-kick"
            | "corner-kick"
            | "free-kick"
            | "foul"
            | "offside"
            | "kickoff"
    )
}

fn soccer_accounting_check_stats(
    trace: &SimulationTrace,
    report: &mut SoccerAccountingSmokeReport,
) {
    soccer_accounting_expect_eq(
        report,
        trace.summary.ticks,
        "summary",
        "scoreHomeGoalEvents",
        trace.summary.score_home,
        report.score_home_from_goal_events,
        "home score should equal home goal events",
    );
    soccer_accounting_expect_eq(
        report,
        trace.summary.ticks,
        "summary",
        "scoreAwayGoalEvents",
        trace.summary.score_away,
        report.score_away_from_goal_events,
        "away score should equal away goal events",
    );

    let stats = &trace.summary.stats;
    soccer_accounting_expect_le(
        report,
        "stats",
        "shotsOnTargetHome",
        stats.shots_on_target_home,
        stats.shots_home,
        "home shots on target cannot exceed home shots",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "shotsOnTargetAway",
        stats.shots_on_target_away,
        stats.shots_away,
        "away shots on target cannot exceed away shots",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "passesCompletedHome",
        stats.passes_completed_home,
        stats.passes_attempted_home,
        "home completed passes cannot exceed attempts",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "passesCompletedAway",
        stats.passes_completed_away,
        stats.passes_attempted_away,
        "away completed passes cannot exceed attempts",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "savesHome",
        stats.saves_home,
        stats.shots_on_target_away,
        "home saves cannot exceed away shots on target",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "savesAway",
        stats.saves_away,
        stats.shots_on_target_home,
        "away saves cannot exceed home shots on target",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "shotBlocksHome",
        stats.shot_blocks_home,
        stats.shots_away,
        "home shot blocks cannot exceed away shots",
    );
    soccer_accounting_expect_le(
        report,
        "stats",
        "shotBlocksAway",
        stats.shot_blocks_away,
        stats.shots_home,
        "away shot blocks cannot exceed home shots",
    );

    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "throw-in",
        Team::Home,
        "throwInsHome",
        stats.throw_ins_home,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "throw-in",
        Team::Away,
        "throwInsAway",
        stats.throw_ins_away,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "goal-kick",
        Team::Home,
        "goalKicksHome",
        stats.goal_kicks_home,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "goal-kick",
        Team::Away,
        "goalKicksAway",
        stats.goal_kicks_away,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "corner-kick",
        Team::Home,
        "cornerKicksHome",
        stats.corner_kicks_home,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "corner-kick",
        Team::Away,
        "cornerKicksAway",
        stats.corner_kicks_away,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "free-kick",
        Team::Home,
        "freeKicksHome",
        stats.free_kicks_home,
    );
    soccer_accounting_check_event_stat_count(
        report,
        trace,
        "free-kick",
        Team::Away,
        "freeKicksAway",
        stats.free_kicks_away,
    );
    soccer_accounting_check_dribble_beat_stat_count(
        report,
        trace,
        Team::Home,
        "dribbleBeatsHome",
        stats.dribble_beats_home,
    );
    soccer_accounting_check_dribble_beat_stat_count(
        report,
        trace,
        Team::Away,
        "dribbleBeatsAway",
        stats.dribble_beats_away,
    );
}

fn soccer_dribble_beat_event_kind(event_kind: &str) -> bool {
    matches!(
        event_kind,
        "dribble-beat"
            | "carry-forward"
            | "carry-out-left"
            | "carry-out-right"
            | "protect-ball"
            | "left-cut"
            | "right-cut"
            | "nutmeg"
            | "fake-left-cut-right"
            | "fake-right-cut-left"
    )
}

fn soccer_accounting_check_dribble_beat_stat_count(
    report: &mut SoccerAccountingSmokeReport,
    trace: &SimulationTrace,
    team: Team,
    metric: &str,
    stat_value: u32,
) {
    let event_count = trace
        .events
        .iter()
        .filter(|event| event.team == Some(team) && soccer_dribble_beat_event_kind(&event.kind))
        .count() as u32;
    soccer_accounting_expect_eq(
        report,
        trace.summary.ticks,
        "stats",
        metric,
        stat_value,
        event_count,
        format!("{metric} should match emitted dribble-beat events"),
    );
}

fn soccer_accounting_check_event_stat_count(
    report: &mut SoccerAccountingSmokeReport,
    trace: &SimulationTrace,
    event_kind: &str,
    team: Team,
    metric: &str,
    stat_value: u32,
) {
    let event_count = trace
        .events
        .iter()
        .filter(|event| event.kind == event_kind && event.team == Some(team))
        .count() as u32;
    soccer_accounting_expect_eq(
        report,
        trace.summary.ticks,
        "stats",
        metric,
        stat_value,
        event_count,
        format!("{metric} should match emitted {event_kind} events"),
    );
}

fn soccer_accounting_expect_eq(
    report: &mut SoccerAccountingSmokeReport,
    tick: u64,
    subject: &str,
    metric: &str,
    expected: u32,
    actual: u32,
    message: impl Into<String>,
) {
    if expected != actual {
        report.push_violation(
            tick,
            subject,
            metric,
            expected.to_string(),
            actual.to_string(),
            message,
        );
    }
}

fn soccer_accounting_expect_le(
    report: &mut SoccerAccountingSmokeReport,
    subject: &str,
    metric: &str,
    actual: u32,
    upper_bound: u32,
    message: impl Into<String>,
) {
    if actual > upper_bound {
        report.push_violation(
            0,
            subject,
            metric,
            format!("<= {upper_bound}"),
            actual.to_string(),
            message,
        );
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SoccerComputationSmokeLimits {
    pub heavy_record_elapsed_ms: f64,
    pub max_record_elapsed_ms: f64,
    pub max_total_elapsed_ms: f64,
    pub max_records: usize,
}

impl Default for SoccerComputationSmokeLimits {
    fn default() -> Self {
        Self {
            heavy_record_elapsed_ms: SOCCER_COMPUTATION_HEAVY_RECORD_MS,
            max_record_elapsed_ms: SOCCER_COMPUTATION_MAX_RECORD_MS,
            max_total_elapsed_ms: SOCCER_COMPUTATION_MAX_TOTAL_MS,
            max_records: SOCCER_COMPUTATION_MAX_RECORDS,
        }
    }
}

