fn csv_required_pitch_point(
    row: &[String],
    header: &HashMap<String, usize>,
    aliases: TrackingCsvPitchPointAliases,
    config: &MatchConfig,
    line_no: usize,
) -> Result<Vec2, String> {
    csv_optional_pitch_point(row, header, aliases, config, line_no)?.ok_or_else(|| {
        format!(
            "csv line {line_no} missing required position columns {}, {}, or {}",
            aliases.direct_x[0], aliases.normalized_x[0], aliases.pixel_x[0]
        )
    })
}

fn csv_optional_pitch_point(
    row: &[String],
    header: &HashMap<String, usize>,
    aliases: TrackingCsvPitchPointAliases,
    config: &MatchConfig,
    line_no: usize,
) -> Result<Option<Vec2>, String> {
    if let Some(point) =
        csv_optional_vec2(row, header, aliases.direct_x, aliases.direct_y, line_no)?
    {
        return Ok(Some(point));
    }
    let calibration = TrackingCsvCoordinateCalibration::from_row(row, header, line_no)?;
    if let Some(point) = csv_optional_vec2(
        row,
        header,
        aliases.normalized_x,
        aliases.normalized_y,
        line_no,
    )? {
        return Ok(Some(calibration.map_normalized(point, config)));
    }

    let pixel = csv_optional_vec2(row, header, aliases.pixel_x, aliases.pixel_y, line_no)?;
    let Some(pixel) = pixel else {
        return Ok(None);
    };
    let image_dimensions = csv_required_image_dimensions(row, header, line_no)?;
    Ok(Some(calibration.map_pixel(pixel, image_dimensions, config)))
}

fn csv_required_image_dimensions(
    row: &[String],
    header: &HashMap<String, usize>,
    line_no: usize,
) -> Result<Vec2, String> {
    let dimensions = csv_optional_vec2(
        row,
        header,
        &[
            "image_width",
            "imagewidth",
            "frame_width",
            "framewidth",
            "video_width",
            "videowidth",
            "width",
        ],
        &[
            "image_height",
            "imageheight",
            "frame_height",
            "frameheight",
            "video_height",
            "videoheight",
            "height",
        ],
        line_no,
    )?;
    let Some(dimensions) = dimensions else {
        return Err(format!(
            "csv line {line_no} pixel coordinates require image_width and image_height"
        ));
    };
    if dimensions.x <= 0.0 || dimensions.y <= 0.0 {
        return Err(format!(
            "csv line {line_no} image dimensions must be positive"
        ));
    }
    Ok(dimensions)
}

fn csv_optional_skill_score(
    row: &[String],
    header: &HashMap<String, usize>,
    aliases: &[&str],
    line_no: usize,
) -> Result<Option<f64>, String> {
    csv_optional_f64(row, header, aliases, line_no).map(|value| value.map(ability_score))
}

fn tracking_csv_skill_profile(
    row: &[String],
    header: &HashMap<String, usize>,
    role: PlayerRole,
    line_no: usize,
) -> Result<Option<SkillProfile>, String> {
    let mut skills = neutral_tracking_skill_profile(role);
    let mut found = false;

    macro_rules! apply_skill {
        ($field:ident, [$($alias:expr),+ $(,)?]) => {
            if let Some(score) = csv_optional_skill_score(row, header, &[$($alias),+], line_no)? {
                skills.$field = score;
                found = true;
            }
        };
    }

    macro_rules! apply_positive_raw {
        ($field:ident, [$($alias:expr),+ $(,)?]) => {
            if let Some(value) = csv_optional_f64(row, header, &[$($alias),+], line_no)? {
                if !value.is_finite() || value <= 0.0 {
                    return Err(format!(
                        "csv line {line_no} {} must be a positive finite number",
                        stringify!($field)
                    ));
                }
                skills.$field = value;
                found = true;
            }
        };
    }

    apply_skill!(
        top_speed,
        [
            "top_speed",
            "topSpeed",
            "top_speed_yps",
            "topSpeedYps",
            "skill_top_speed",
            "speed"
        ]
    );
    apply_skill!(
        acceleration,
        [
            "acceleration",
            "acceleration_yps2",
            "accelerationYps2",
            "skill_acceleration"
        ]
    );
    apply_skill!(strength, ["strength", "skill_strength"]);
    apply_skill!(height, ["height", "skill_height"]);
    apply_positive_raw!(
        weight_pounds,
        [
            "weight",
            "weight_pounds",
            "weightPounds",
            "weight_lbs",
            "weightLbs",
            "body_weight",
            "bodyWeight",
            "body_weight_pounds",
            "bodyWeightPounds"
        ]
    );
    apply_skill!(shooting, ["shooting", "shooting_ability", "skill_shooting"]);
    apply_skill!(
        right_foot_shot_power,
        [
            "right_foot_shot_power",
            "rightFootShotPower",
            "right_shot",
            "skill_right_foot_shot_power"
        ]
    );
    apply_skill!(
        left_foot_shot_power,
        [
            "left_foot_shot_power",
            "leftFootShotPower",
            "left_shot",
            "skill_left_foot_shot_power"
        ]
    );
    apply_skill!(passing, ["passing", "passing_ability", "skill_passing"]);
    apply_skill!(
        passing_completion_rate,
        [
            "passing_completion_rate",
            "passingCompletionRate",
            "pass_completion",
            "pass_completion_rate",
            "skill_passing_completion_rate"
        ]
    );
    apply_skill!(
        flair_passing,
        [
            "flair_passing",
            "flairPassing",
            "flair",
            "skill_flair_passing"
        ]
    );
    apply_skill!(
        crossing_left,
        [
            "crossing_left",
            "crossingLeft",
            "left_crossing",
            "leftFootCrossingAbility",
            "crossingAbilityWithLeftRoot",
            "skill_crossing_left"
        ]
    );
    apply_skill!(
        crossing_right,
        [
            "crossing_right",
            "crossingRight",
            "right_crossing",
            "rightFootCrossingAbility",
            "skill_crossing_right"
        ]
    );
    apply_skill!(
        dribbling,
        ["dribbling", "dribbling_ability", "skill_dribbling"]
    );
    apply_skill!(
        first_touch,
        [
            "first_touch",
            "firstTouch",
            "control_touch",
            "skill_first_touch"
        ]
    );
    apply_skill!(
        defending,
        [
            "defending",
            "defensive_ability",
            "defensiveAbility",
            "skill_defending"
        ]
    );
    apply_skill!(
        goalkeeping,
        [
            "goalkeeping",
            "gk_strength",
            "ability_in_goal",
            "abilityInGoal",
            "skill_goalkeeping"
        ]
    );
    apply_skill!(
        defensive_tracking,
        [
            "defensive_tracking",
            "defensiveTracking",
            "tracking_back",
            "trackingBack",
            "skill_defensive_tracking"
        ]
    );
    apply_skill!(stamina, ["stamina", "skill_stamina"]);
    apply_skill!(vision, ["vision", "skill_vision"]);
    apply_skill!(aggression, ["aggression", "skill_aggression"]);

    if let Some(noise) = csv_optional_f64(
        row,
        header,
        &["decision_noise", "decisionNoise", "skill_decision_noise"],
        line_no,
    )? {
        skills.decision_noise = if noise.is_finite() {
            noise.clamp(0.0, 1.0)
        } else {
            skills.decision_noise
        };
        found = true;
    }

    Ok(found.then_some(skills))
}

fn parse_tracking_team(raw: &str, line_no: usize) -> Result<Team, String> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "home" | "h" | "1" => Ok(Team::Home),
        "away" | "a" | "2" => Ok(Team::Away),
        _ => Err(format!("csv line {line_no} unknown team {raw}")),
    }
}

fn parse_tracking_role(raw: &str, line_no: usize) -> Result<PlayerRole, String> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "goalkeeper" | "keeper" | "gk" | "g" => Ok(PlayerRole::Goalkeeper),
        "defender" | "defence" | "defense" | "def" | "d" => Ok(PlayerRole::Defender),
        "midfielder" | "midfield" | "mid" | "m" => Ok(PlayerRole::Midfielder),
        "forward" | "striker" | "winger" | "fw" | "st" | "f" => Ok(PlayerRole::Forward),
        _ => Err(format!("csv line {line_no} unknown role {raw}")),
    }
}

fn parse_tracking_pass_flight(raw: &str, line_no: usize) -> Result<PassFlight, String> {
    match normalize_csv_header(raw).as_str() {
        "floor" | "ground" | "groundpass" | "grounded" | "low" | "rolling" | "roll" | "0" => {
            Ok(PassFlight::Floor)
        }
        "aerial" | "air" | "airborne" | "aerialpass" | "aerialcross" | "chipped" | "chip"
        | "high" | "lob" | "lofted" | "longball" | "1" => Ok(PassFlight::Aerial),
        _ => Err(format!("csv line {line_no} unknown pass flight {raw}")),
    }
}

fn parse_tracking_facing_bucket(raw: &str) -> Result<FacingBucket, String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(FacingBucket::Unknown);
    }
    let numeric = trimmed
        .trim_end_matches('°')
        .trim_end_matches("degrees")
        .trim_end_matches("degree")
        .trim_end_matches("deg")
        .trim();
    if let Ok(degrees) = numeric.parse::<f64>() {
        return Ok(facing_bucket_from_degrees(degrees));
    }
    match normalize_csv_header(trimmed).as_str() {
        "unknown" | "none" | "na" | "null" | "notavailable" => Ok(FacingBucket::Unknown),
        "north" | "n" | "up" => Ok(FacingBucket::North),
        "northeast" | "ne" | "upperright" => Ok(FacingBucket::NorthEast),
        "east" | "e" | "right" => Ok(FacingBucket::East),
        "southeast" | "se" | "lowerright" => Ok(FacingBucket::SouthEast),
        "south" | "s" | "down" => Ok(FacingBucket::South),
        "southwest" | "sw" | "lowerleft" => Ok(FacingBucket::SouthWest),
        "west" | "w" | "left" => Ok(FacingBucket::West),
        "northwest" | "nw" | "upperleft" => Ok(FacingBucket::NorthWest),
        _ => Err("expected facing bucket name or degrees".to_string()),
    }
}

fn parse_tracking_ball_action(raw: &str, line_no: usize) -> Result<Option<String>, String> {
    normalize_tracking_ball_action(raw)
        .map_err(|err| format!("csv line {line_no} unknown ball action {raw}: {err}"))
}

fn normalize_tracking_ball_action(raw: &str) -> Result<Option<String>, String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    let compact = normalize_csv_header(trimmed);
    let action = match compact.as_str() {
        "none" | "na" | "null" | "noaction" => return Ok(None),
        "groundpass" | "floorpass" | "shortpass" => "pass",
        "killer"
        | "killerpass"
        | "throughpass"
        | "threadedpass"
        | "splitpass"
        | "splittingpass"
        | "linebreakingpass"
        | "defensesplittingpass" => "killer-pass",
        "lowcross" | "flanklowcross" | "downflanklowcross" | "playdownflanklowcross" => {
            "flank-low-cross"
        }
        "aerial" | "aerialpass" | "chippedpass" | "loftedpass" | "cross" | "aerialcross" => {
            "aerial-pass"
        }
        "highcross"
        | "crossforheader"
        | "highcrossheader"
        | "flankhighcross"
        | "flankhighcrossheader"
        | "downflankhighcross"
        | "playdownflankhighcross" => "flank-high-cross",
        "shot" => "shoot",
        "routeone" | "route1" | "longball" | "longpass" | "directball" => "route-one",
        "clear" | "clearance" | "hoof" | "hoofedclearance" => "clearance",
        "firsttimepass" => "first-time-pass",
        "firsttimeshot" => "first-time-shot",
        "firsttimeheader" | "header" => "first-time-header",
        "control" | "trap" | "chestcontrol" => "control-touch",
        "sidestep" | "sidestepdribble" | "sidestepmove" => "side-step",
        "carry" | "carryforward" | "dribbleforward" => "carry-forward",
        "carryout" | "dribbleout" => "carry-out-left",
        "carryoutleft" | "carryleft" => "carry-out-left",
        "carryoutright" | "carryright" => "carry-out-right",
        "protect" | "protectball" | "shield" | "shieldball" => "protect-ball",
        "leftcut" | "leftcutdribble" | "cutleft" => "left-cut",
        "rightcut" | "rightcutdribble" | "cutright" => "right-cut",
        "nutmeg" | "nutmegged" | "meg" => "nutmeg",
        "fakeleftcutright" | "fakelefttoright" => "fake-left-cut-right",
        "fakerightcutleft" | "fakerighttoleft" => "fake-right-cut-left",
        "freekick" => "free-kick",
        "goalkick" => "goal-kick",
        "cornerkick" => "corner-kick",
        "throwin" => "throw-in",
        "supportshape" => "support-shape",
        "supportroam" => "support-roam",
        "checktoball" | "checkrun" => "check-to-ball",
        "runinbehind" | "inbehind" => "run-in-behind",
        "wideoutlet" | "touchlineoutlet" => "wide-outlet",
        "shotcreationrun" | "shootingrun" => "shot-creation-run",
        "overlap" | "overlaprun" => "overlap-run",
        "supportpushup" | "pushup" => "support-push-up",
        "supportscreen" | "screenrun" => "support-screen",
        other => normalize_soccer_action_label(other),
    };
    match action {
        "pass"
        | "aerial-pass"
        | "flank-low-cross"
        | "flank-high-cross"
        | "killer-pass"
        | "first-time-pass"
        | "clearance"
        | "route-one"
        | "shoot"
        | "first-time-shot"
        | "first-time-header"
        | "control-touch"
        | "dribble"
        | "carry-forward"
        | "carry-out-left"
        | "carry-out-right"
        | "protect-ball"
        | "side-step"
        | "left-cut"
        | "right-cut"
        | "nutmeg"
        | "fake-left-cut-right"
        | "fake-right-cut-left"
        | "set-play-run"
        | "space"
        | "support-shape"
        | "support-roam"
        | "check-to-ball"
        | "run-in-behind"
        | "wide-outlet"
        | "shot-creation-run"
        | "overlap-run"
        | "support-push-up"
        | "support-screen"
        | "defend"
        | "tackle"
        | "recover"
        | "hold"
        | "kickoff"
        | "throw-in"
        | "goal-kick"
        | "corner-kick"
        | "free-kick"
        | "offside"
        | "goal"
        | "save"
        | "shot-blocked" => Ok(Some(action.to_string())),
        _ => Err("expected a known soccer action label".to_string()),
    }
}

fn known_tracking_facing(facing: Option<FacingBucket>) -> Option<FacingBucket> {
    facing.filter(|bucket| *bucket != FacingBucket::Unknown)
}

fn tracking_velocity_facing(sample: &SoccerTrackingPlayerSample) -> Option<FacingBucket> {
    let facing = facing_bucket_from_vector(sample.velocity.unwrap_or_default());
    (facing != FacingBucket::Unknown).then_some(facing)
}

fn tracking_player_receive_facing(sample: &SoccerTrackingPlayerSample) -> FacingBucket {
    known_tracking_facing(sample.receive_facing)
        .or_else(|| known_tracking_facing(sample.facing))
        .or_else(|| tracking_velocity_facing(sample))
        .unwrap_or(FacingBucket::Unknown)
}

fn tracking_player_action_facing(sample: &SoccerTrackingPlayerSample) -> FacingBucket {
    known_tracking_facing(sample.action_facing)
        .or_else(|| known_tracking_facing(sample.facing))
        .or_else(|| tracking_velocity_facing(sample))
        .unwrap_or_else(|| default_team_facing(sample.team))
}

fn tracking_frame_to_world_snapshot(
    config: &MatchConfig,
    frame: &SoccerTrackingFrame,
    home_positions: &HashMap<usize, Vec2>,
) -> WorldSnapshot {
    let holder_team = frame
        .ball_holder
        .and_then(|holder| frame.players.iter().find(|p| p.id == holder))
        .map(|p| p.team);
    let last_touch_team = frame.last_touch_team.or(holder_team);
    let players = frame
        .players
        .iter()
        .map(|p| {
            let skills = p
                .skills
                .clone()
                .unwrap_or_else(|| neutral_tracking_skill_profile(p.role));
            PlayerSnapshot {
                id: p.id,
                name: p
                    .name
                    .clone()
                    .unwrap_or_else(|| format!("Tracking {}", p.id)),
                team: p.team,
                role: p.role,
                shirt: p.shirt.unwrap_or((p.id % 100).max(1) as u8),
                position: p.position,
                position_history: vec![p.position],
                velocity: p.velocity.unwrap_or_default(),
                movement_gait: MovementGait::Stand,
                receive_facing: tracking_player_receive_facing(p),
                action_facing: tracking_player_action_facing(p),
                incoming_ball: None,
                vision_range_yards: vision_range_yards(skills.vision),
                field_of_view_degrees: field_of_view_degrees(skills.vision),
                skills,
                fatigue: 0.0,
                home_position: home_positions
                    .get(&p.id)
                    .copied()
                    .unwrap_or(p.home_position.unwrap_or(p.position)),
                controller_slot: None,
                scheduled_index: None,
                preferences: AgentPreferences::default(),
                acceleration: p.motion_acceleration.unwrap_or_default(),
                jerk: p.motion_jerk.unwrap_or_default(),
                last_decision: None,
                learned_policy: None,
            }
        })
        .collect::<Vec<_>>();
    let shared_positions = SharedPlayerPositionSnapshot::from_player_snapshots(
        &players,
        frame.tick,
        frame.clock_seconds,
    );
    let phase = tracking_phase(config, frame, last_touch_team);
    let score_home = frame.score_home.unwrap_or(0);
    let score_away = frame.score_away.unwrap_or(0);
    let score_diff_home = score_home as i32 - score_away as i32;
    WorldSnapshot {
        tick: frame.tick,
        clock_seconds: frame.clock_seconds,
        dt_seconds: config.dt_seconds,
        field_length: config.field_length_yards,
        field_width: config.field_width_yards,
        goal_width: config.goal_width_yards,
        ball: BallState {
            position: frame.ball_position,
            velocity: frame.ball_velocity.unwrap_or_default(),
            acceleration: frame.ball_acceleration.unwrap_or_default(),
            jerk: frame.ball_jerk.unwrap_or_default(),
            curl_acceleration: frame.ball_curl_acceleration.unwrap_or_default(),
            altitude_yards: frame.ball_altitude_yards.unwrap_or(0.0).max(0.0),
            decision_speed_yps: frame.ball_velocity.unwrap_or_default().len(),
            decision_altitude_yards: frame.ball_altitude_yards.unwrap_or(0.0).max(0.0),
            decision_curl_yps2: frame.ball_curl_acceleration.unwrap_or_default().len(),
            holder: frame.ball_holder,
            last_touch_team,
            scheduled_index: None,
            last_decision: frame
                .ball_action
                .as_deref()
                .and_then(|action| normalize_tracking_ball_action(action).ok().flatten())
                .map(|action| {
                    let scheduled_index = None;
                    BallDecisionTrace {
                        tick: frame.tick,
                        operation_order: ball_agent_operation_order(
                            frame.tick,
                            &action,
                            scheduled_index,
                        ),
                        action,
                        position: frame.ball_position,
                        velocity: frame.ball_velocity.unwrap_or_default(),
                        acceleration: frame.ball_acceleration.unwrap_or_default(),
                        jerk: frame.ball_jerk.unwrap_or_default(),
                        curl_acceleration: frame.ball_curl_acceleration.unwrap_or_default(),
                        altitude_yards: frame.ball_altitude_yards.unwrap_or(0.0).max(0.0),
                        holder: frame.ball_holder,
                        scheduled_index,
                    }
                }),
        },
        ball_history: vec![BallPositionSample {
            tick: frame.tick,
            clock_seconds: frame.clock_seconds,
            position: frame.ball_position,
            velocity: frame.ball_velocity.unwrap_or_default(),
            acceleration: frame.ball_acceleration.unwrap_or_default(),
            jerk: frame.ball_jerk.unwrap_or_default(),
            curl_acceleration: frame.ball_curl_acceleration.unwrap_or_default(),
            altitude_yards: frame.ball_altitude_yards.unwrap_or(0.0).max(0.0),
            holder: frame.ball_holder,
            last_touch_team,
        }],
        pending_pass: None,
        pending_rebound: None,
        active_set_play: None,
        players,
        shared_positions,
        agent_schedule: Vec::new(),
        score_home,
        score_away,
        phase,
        home_directive: tactical_directive_for_team(
            Team::Home,
            phase,
            last_touch_team,
            frame.ball_position,
            score_diff_home,
            config.field_width_yards,
            config.field_length_yards,
            DefensiveCoverProfile::default(),
            AttackingOverloadProfile::default(),
        ),
        away_directive: tactical_directive_for_team(
            Team::Away,
            phase,
            last_touch_team,
            frame.ball_position,
            -score_diff_home,
            config.field_width_yards,
            config.field_length_yards,
            DefensiveCoverProfile::default(),
            AttackingOverloadProfile::default(),
        ),
        formation_lp_enabled: config.formation_lp_enabled,
        home_team_possession_seconds: if last_touch_team == Some(Team::Home) {
            frame.clock_seconds.max(0.0)
        } else {
            0.0
        },
        away_team_possession_seconds: if last_touch_team == Some(Team::Away) {
            frame.clock_seconds.max(0.0)
        } else {
            0.0
        },
        ball_holder_possession_seconds: if frame.ball_holder.is_some() {
            frame.clock_seconds.max(0.0)
        } else {
            0.0
        },
        formation_lp_guidance: Vec::new(),
        formation_lp_teams: Vec::new(),
    }
}

fn tracking_frame_to_world_snapshot_with_history(
    config: &MatchConfig,
    frames: &[SoccerTrackingFrame],
    frame_idx: usize,
    home_positions: &HashMap<usize, Vec2>,
) -> WorldSnapshot {
    debug_assert!(!frames.is_empty());
    let frame = &frames[frame_idx.min(frames.len().saturating_sub(1))];
    let mut snapshot = tracking_frame_to_world_snapshot(config, frame, home_positions);
    let mut shared_player_histories = Vec::new();
    for player in &mut snapshot.players {
        let history = tracking_player_position_history_at(frames, frame_idx, player.id);
        if !history.is_empty() {
            player.position_history = history;
        }
        let sample_history =
            tracking_player_position_sample_history_at(frames, frame_idx, player.id);
        if !sample_history.is_empty() {
            shared_player_histories.push((player.id, sample_history));
        }
    }
    for (player_id, sample_history) in shared_player_histories {
        if let Some(latest) = sample_history.last().cloned() {
            if let Some(existing) = snapshot
                .shared_positions
                .latest
                .iter_mut()
                .find(|sample| sample.player_id == player_id)
            {
                *existing = latest;
            } else {
                snapshot.shared_positions.latest.push(latest);
            }
        }
        snapshot
            .shared_positions
            .histories
            .insert(player_id, sample_history);
    }
    let ball_history = tracking_ball_position_history_at(frames, frame_idx);
    if !ball_history.is_empty() {
        snapshot.ball_history = ball_history;
    }
    annotate_tracking_incoming_ball_contexts(&mut snapshot, frames, frame_idx);
    snapshot
}

fn tracking_pass_flight_from_frames(
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
) -> PassFlight {
    after_frame
        .pass_flight
        .or(before_frame.pass_flight)
        .unwrap_or_else(|| {
            let before_altitude = before_frame.ball_altitude_yards.unwrap_or(0.0);
            let after_altitude = after_frame.ball_altitude_yards.unwrap_or(0.0);
            if before_altitude.max(after_altitude) > 0.35 {
                PassFlight::Aerial
            } else {
                PassFlight::Floor
            }
        })
}

fn tracking_first_touch_action_label(action: &str) -> Option<&'static str> {
    match normalize_tracking_ball_action(action)
        .ok()
        .flatten()?
        .as_str()
    {
        "first-time-pass" => Some("first-time-pass"),
        "first-time-shot" => Some("first-time-shot"),
        "first-time-header" => Some("first-time-header"),
        "control-touch" => Some("control-touch"),
        _ => None,
    }
}

fn tracking_incoming_context_from_frames(
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
    target: &PlayerSnapshot,
    from_player: Option<usize>,
    received_tick: u64,
    force_aerial: bool,
    field_width: f64,
    field_length: f64,
) -> IncomingBallContext {
    let mut flight = tracking_pass_flight_from_frames(before_frame, after_frame);
    if force_aerial {
        flight = PassFlight::Aerial;
    }
    let origin = before_frame.ball_position;
    let intended_target = target.position;
    let distance_yards = origin.distance(intended_target);
    let frame_dt = (after_frame.clock_seconds - before_frame.clock_seconds).max(0.0);
    let inferred_velocity = if frame_dt > 1e-6 {
        (after_frame.ball_position - before_frame.ball_position) / frame_dt
    } else {
        Vec2::zero()
    };
    let speed_yps = after_frame
        .ball_velocity
        .or(before_frame.ball_velocity)
        .unwrap_or(inferred_velocity)
        .len();
    let is_cross = pass_would_be_cross(
        origin,
        intended_target,
        target.team,
        field_width,
        field_length,
    );
    IncomingBallContext {
        from_player,
        target_player: Some(target.id),
        team: Some(target.team),
        kind: match (flight, is_cross) {
            (PassFlight::Floor, false) => IncomingBallKind::GroundPass,
            (PassFlight::Aerial, false) => IncomingBallKind::AerialPass,
            (PassFlight::Floor, true) => IncomingBallKind::Cross,
            (PassFlight::Aerial, true) => IncomingBallKind::AerialCross,
        },
        origin: Some(origin),
        intended_target: Some(intended_target),
        speed_yps,
        distance_yards,
        received_tick,
        is_cross,
        is_aerial: flight.is_aerial(),
    }
}

fn annotate_tracking_incoming_ball_contexts(
    snapshot: &mut WorldSnapshot,
    frames: &[SoccerTrackingFrame],
    frame_idx: usize,
) {
    if frames.is_empty() {
        return;
    }
    let idx = frame_idx.min(frames.len() - 1);
    let frame = &frames[idx];

    if idx > 0 {
        let previous = &frames[idx - 1];
        if let Some(holder_id) = frame.ball_holder {
            if previous.ball_holder != Some(holder_id) {
                if let Some(player) = snapshot.players.iter_mut().find(|p| p.id == holder_id) {
                    let from_player = previous.ball_holder.filter(|from| *from != holder_id);
                    player.incoming_ball = Some(tracking_incoming_context_from_frames(
                        previous,
                        frame,
                        player,
                        from_player,
                        frame.tick,
                        false,
                        snapshot.field_width,
                        snapshot.field_length,
                    ));
                }
            }
        }
    }

    let Some(next_frame) = frames.get(idx + 1) else {
        return;
    };
    let Some(raw_action) = next_frame
        .ball_action
        .as_deref()
        .or(frame.ball_action.as_deref())
    else {
        return;
    };
    let Some(first_touch_action) = tracking_first_touch_action_label(raw_action) else {
        return;
    };
    let Some(action_player) = next_frame.action_player.or(frame.action_player) else {
        return;
    };
    if let Some(player) = snapshot
        .players
        .iter_mut()
        .find(|player| player.id == action_player)
    {
        let from_player = frame
            .ball_holder
            .filter(|holder| *holder != action_player)
            .or_else(|| {
                idx.checked_sub(1)
                    .and_then(|previous_idx| frames[previous_idx].ball_holder)
                    .filter(|holder| *holder != action_player)
            });
        player.incoming_ball = Some(tracking_incoming_context_from_frames(
            frame,
            next_frame,
            player,
            from_player,
            frame.tick,
            first_touch_action == "first-time-header",
            snapshot.field_width,
            snapshot.field_length,
        ));
    }
}

fn tracking_player_position_history_at(
    frames: &[SoccerTrackingFrame],
    frame_idx: usize,
    player_id: usize,
) -> Vec<Vec2> {
    if frames.is_empty() {
        return Vec::new();
    }
    let end = frame_idx.min(frames.len() - 1);
    let start = (end + 1).saturating_sub(PLAYER_POSITION_HISTORY_LIMIT);
    frames[start..=end]
        .iter()
        .filter_map(|frame| {
            frame
                .players
                .iter()
                .find(|player| player.id == player_id)
                .map(|player| player.position)
        })
        .collect()
}

fn tracking_player_position_sample_history_at(
    frames: &[SoccerTrackingFrame],
    frame_idx: usize,
    player_id: usize,
) -> Vec<PlayerPositionSample> {
    if frames.is_empty() {
        return Vec::new();
    }
    let end = frame_idx.min(frames.len() - 1);
    let start = (end + 1).saturating_sub(PLAYER_POSITION_HISTORY_LIMIT);
    frames[start..=end]
        .iter()
        .filter_map(|frame| {
            frame
                .players
                .iter()
                .find(|player| player.id == player_id)
                .map(|player| PlayerPositionSample {
                    player_id,
                    tick: frame.tick,
                    clock_seconds: frame.clock_seconds,
                    position: player.position,
                    velocity: player.velocity.unwrap_or_default(),
                    acceleration: player.motion_acceleration.unwrap_or_default(),
                    jerk: player.motion_jerk.unwrap_or_default(),
                })
        })
        .collect()
}

fn tracking_ball_position_history_at(
    frames: &[SoccerTrackingFrame],
    frame_idx: usize,
) -> Vec<BallPositionSample> {
    if frames.is_empty() {
        return Vec::new();
    }
    let end = frame_idx.min(frames.len() - 1);
    let start = (end + 1).saturating_sub(BALL_POSITION_HISTORY_LIMIT);
    frames[start..=end]
        .iter()
        .map(|frame| BallPositionSample {
            tick: frame.tick,
            clock_seconds: frame.clock_seconds,
            position: frame.ball_position,
            velocity: frame.ball_velocity.unwrap_or_default(),
            acceleration: frame.ball_acceleration.unwrap_or_default(),
            jerk: frame.ball_jerk.unwrap_or_default(),
            curl_acceleration: frame.ball_curl_acceleration.unwrap_or_default(),
            altitude_yards: frame.ball_altitude_yards.unwrap_or(0.0).max(0.0),
            holder: frame.ball_holder,
            last_touch_team: frame.last_touch_team,
        })
        .collect()
}

fn tracking_phase(
    config: &MatchConfig,
    frame: &SoccerTrackingFrame,
    possession_team: Option<Team>,
) -> TacticalPhase {
    let y = frame.ball_position.y;
    match possession_team {
        Some(Team::Home) if y > config.field_length_yards * 0.68 => TacticalPhase::HomeAttack,
        Some(Team::Home) => TacticalPhase::HomeBuildUp,
        Some(Team::Away) if y < config.field_length_yards * 0.32 => TacticalPhase::AwayAttack,
        Some(Team::Away) => TacticalPhase::AwayBuildUp,
        None if frame.tick < 5 => TacticalPhase::Kickoff,
        None => TacticalPhase::Transition,
    }
}

fn infer_tracking_action(
    player: &PlayerSnapshot,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
) -> String {
    let Some(next_player) = after.players.iter().find(|p| p.id == player.id) else {
        return "hold".to_string();
    };
    let before_obs = before.observation_for(player.id);
    let after_obs = after.observation_for(player.id);
    let moved = player.position.distance(next_player.position);

    if before.ball.holder != Some(player.id) {
        if let Some(action) =
            tracking_explicit_off_ball_action(player.id, before_frame, after_frame)
        {
            return action;
        }
    }

    if before.ball.holder == Some(player.id) {
        if let Some(action) =
            tracking_explicit_holder_action(player.id, before_frame, after_frame, before, after)
        {
            return action;
        }
        if tracking_team_scored(player.team, before, after) {
            return "shoot".to_string();
        }
        if let Some(holder) = after.ball.holder {
            if holder != player.id
                && after
                    .players
                    .iter()
                    .find(|p| p.id == holder)
                    .is_some_and(|p| p.team == player.team)
            {
                return tracking_pass_label(before_frame, after_frame, before, after).to_string();
            }
        }
        if tracking_ball_near_teammate(after, player.id, player.team)
            && after.ball.holder != Some(player.id)
        {
            return tracking_pass_label(before_frame, after_frame, before, after).to_string();
        }
        if before_obs.shot_lane_open
            && before_obs.yards_to_goal <= 25.0
            && tracking_ball_moved_toward_goal(before, after, player.team)
        {
            return "shoot".to_string();
        }
        if moved > before.dt_seconds * 1.2 {
            return "dribble".to_string();
        }
        return "hold".to_string();
    }

    if before.possession_team() == Some(player.team.other())
        && after.ball.holder == Some(player.id)
        && player.position.distance(before.ball.position) < 3.8
    {
        return "tackle".to_string();
    }

    let before_ball_distance = player.position.distance(before.ball.position);
    let after_ball_distance = next_player.position.distance(after.ball.position);
    if before.possession_team() == Some(player.team.other())
        && after_ball_distance + 0.35 < before_ball_distance
    {
        return "defend".to_string();
    }

    if before.possession_team() == Some(player.team)
        && (after_obs.open_space_score > before_obs.open_space_score + 0.25
            || moved > before.dt_seconds * 1.2)
    {
        return infer_tracking_support_action(player, next_player, before, after, &before_obs)
            .unwrap_or("space")
            .to_string();
    }

    if moved > before.dt_seconds * 1.2 {
        if before.possession_team() == Some(player.team.other()) {
            "defend".to_string()
        } else {
            "space".to_string()
        }
    } else {
        "hold".to_string()
    }
}

fn tracking_explicit_off_ball_action(
    player_id: usize,
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
) -> Option<String> {
    let (raw_action, action_player) = after_frame
        .ball_action
        .as_deref()
        .map(|action| (action, after_frame.action_player))
        .or_else(|| {
            before_frame
                .ball_action
                .as_deref()
                .map(|action| (action, before_frame.action_player))
        })?;
    if action_player != Some(player_id) {
        return None;
    }
    let action = normalize_tracking_ball_action(raw_action).ok().flatten()?;
    match action.as_str() {
        "space" | "support-shape" | "support-roam" | "check-to-ball" | "run-in-behind"
        | "wide-outlet" | "shot-creation-run" | "overlap-run" | "support-push-up"
        | "support-screen" | "defend" | "tackle" | "recover" | "hold" => Some(action),
        _ => None,
    }
}

fn infer_tracking_support_action(
    player: &PlayerSnapshot,
    next_player: &PlayerSnapshot,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    before_observation: &SoccerPomdpObservation,
) -> Option<&'static str> {
    if before.possession_team() != Some(player.team) || before.ball.holder == Some(player.id) {
        return None;
    }
    let movement = next_player.position - player.position;
    let moved = movement.len();
    if moved <= before.dt_seconds.max(DEFAULT_DT_SECONDS) * 1.2 {
        return None;
    }
    let forward = movement.y * player.team.attack_dir();
    let center_x = before.field_width * 0.5;
    let current_width = (player.position.x - center_x).abs();
    let next_width = (next_player.position.x - center_x).abs();
    let lateral = (next_player.position.x - player.position.x).abs();
    let before_ball_distance = player.position.distance(before.ball.position);
    let after_ball_distance = next_player.position.distance(after.ball.position);
    let checked_to_ball_yards = before_ball_distance - after_ball_distance;
    let nearest_pressure = before_observation
        .nearest_opponent_distance
        .min(after.nearest_opponent_distance_at(player.team, next_player.position));

    if checked_to_ball_yards > (0.65 + moved * 0.25)
        && nearest_pressure <= 7.0
        && forward < moved * 0.45
    {
        return Some("check-to-ball");
    }

    if matches!(player.role, PlayerRole::Midfielder | PlayerRole::Forward)
        && next_width > current_width + 2.0
        && lateral >= moved * 0.52
        && forward >= -0.25
        && (next_width / center_x.max(1.0)) >= 0.62
    {
        return Some("wide-outlet");
    }

    let yards_to_goal_before = (player.team.goal_y(before.field_length) - player.position.y).abs();
    let yards_to_goal_after =
        (player.team.goal_y(after.field_length) - next_player.position.y).abs();
    if matches!(player.role, PlayerRole::Forward | PlayerRole::Midfielder)
        && forward >= moved * 0.58
        && forward >= 3.0
        && yards_to_goal_after + 1.5 < yards_to_goal_before
    {
        return Some("run-in-behind");
    }

    None
}

fn tracking_explicit_holder_action(
    player_id: usize,
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> Option<String> {
    let (raw_action, action_player) = after_frame
        .ball_action
        .as_deref()
        .map(|action| (action, after_frame.action_player))
        .or_else(|| {
            before_frame
                .ball_action
                .as_deref()
                .map(|action| (action, before_frame.action_player))
        })?;
    if action_player.is_some_and(|id| id != player_id) {
        return None;
    }
    let action = normalize_tracking_ball_action(raw_action).ok().flatten()?;
    match action.as_str() {
        "pass" => Some(tracking_pass_label(before_frame, after_frame, before, after).to_string()),
        "aerial-pass" | "flank-low-cross" | "flank-high-cross" | "killer-pass"
        | "first-time-pass" | "clearance" | "route-one" | "shoot" | "first-time-shot"
        | "first-time-header" | "control-touch" => Some(action),
        action if is_dribble_action_label(action) => Some(action.to_string()),
        _ => None,
    }
}

fn tracking_pass_label(
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> &'static str {
    if tracking_pass_flight_between(before_frame, after_frame, before, after).is_aerial() {
        "aerial-pass"
    } else {
        "pass"
    }
}

fn tracking_pass_flight_between(
    before_frame: &SoccerTrackingFrame,
    after_frame: &SoccerTrackingFrame,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> PassFlight {
    after_frame
        .pass_flight
        .or(before_frame.pass_flight)
        .unwrap_or_else(|| {
            let before_altitude = before_frame
                .ball_altitude_yards
                .unwrap_or(before.ball.altitude_yards);
            let after_altitude = after_frame
                .ball_altitude_yards
                .unwrap_or(after.ball.altitude_yards);
            if before_altitude.max(after_altitude) > 0.35 {
                PassFlight::Aerial
            } else {
                PassFlight::Floor
            }
        })
}

fn tracking_action_target_trace(
    player: &PlayerSnapshot,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    action: &str,
) -> Option<AgentActionTargetTrace> {
    let next_player = after.players.iter().find(|p| p.id == player.id);
    let goal = Vec2::new(
        before.field_width * 0.5,
        player.team.goal_y(before.field_length),
    );
    let (point, target_player) = match normalize_soccer_action_label(action) {
        action if is_pass_like_action(action) => {
            let holder_teammate = after.ball.holder.and_then(|holder| {
                after
                    .players
                    .iter()
                    .find(|p| p.id == holder && p.team == player.team && p.id != player.id)
                    .map(|p| (p.position, Some(p.id)))
            });
            holder_teammate.unwrap_or_else(|| {
                (
                    after.ball.position,
                    infer_tracking_pass_receiver(player, before, after),
                )
            })
        }
        "clearance" | "route-one" => (after.ball.position, None),
        "shoot" | "first-time-shot" | "first-time-header" => (goal, None),
        "dribble"
        | "carry-forward"
        | "carry-out-left"
        | "carry-out-right"
        | "protect-ball"
        | "side-step"
        | "left-cut"
        | "right-cut"
        | "nutmeg"
        | "fake-left-cut-right"
        | "fake-right-cut-left"
        | "control-touch"
        | "space"
        | "support-shape"
        | "support-roam"
        | "check-to-ball"
        | "run-in-behind"
        | "wide-outlet"
        | "shot-creation-run"
        | "overlap-run"
        | "support-push-up"
        | "support-screen"
        | "defend" => (
            next_player.map(|p| p.position).unwrap_or(player.position),
            None,
        ),
        "tackle" => {
            let target_player = before.ball.holder.or(after.ball.holder);
            let point = target_player
                .and_then(|id| {
                    before
                        .player_position(id)
                        .or_else(|| after.player_position(id))
                })
                .unwrap_or(before.ball.position);
            (point, target_player)
        }
        "hold" => (player.home_position, None),
        _ => return None,
    };
    let point = point.clamp_to_pitch(before.field_width, before.field_length);
    let dribble_touch = if is_dribble_action_label(action) {
        tracking_dribble_touch_from_positions(player.team, player.position, point)
    } else {
        None
    };
    Some(AgentActionTargetTrace {
        point: Some(point),
        player_id: target_player,
        grid: Some(pitch_grid_address(
            point,
            before.field_width,
            before.field_length,
        )),
        facing: facing_bucket_from_vector(point - player.position),
        dribble_touch,
    })
}

fn tracking_dribble_touch_from_positions(
    team: Team,
    origin: Vec2,
    target: Vec2,
) -> Option<DribbleTouchDecision> {
    let delta = target - origin;
    let distance = delta.len();
    if distance <= 1e-6 {
        return None;
    }
    let direction = delta.normalized();
    let lateral = direction.x * team.attack_dir();
    let forward = direction.y * team.attack_dir();
    let mut angle_degrees = lateral.atan2(forward).to_degrees();
    if angle_degrees < 0.0 {
        angle_degrees += 360.0;
    }
    let bucket = ((angle_degrees / DRIBBLE_TOUCH_BUCKET_DEGREES).round() as u8)
        % DRIBBLE_TOUCH_ANGLE_BUCKETS;
    Some(DribbleTouchDecision::new(bucket, distance))
}

fn infer_tracking_pass_receiver(
    player: &PlayerSnapshot,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> Option<usize> {
    let pass_vector = after.ball.position - before.ball.position;
    if pass_vector.len() < 1.0 {
        return None;
    }
    let pass_dir = pass_vector.normalized();
    let mut candidates = after
        .players
        .iter()
        .filter(|candidate| candidate.team == player.team && candidate.id != player.id)
        .filter_map(|candidate| {
            let position = after
                .player_position(candidate.id)
                .unwrap_or(candidate.position);
            let distance_to_ball = position.distance(after.ball.position);
            let lane_distance =
                distance_to_segment(position, before.ball.position, after.ball.position);
            if distance_to_ball > 18.0 && lane_distance > 5.5 {
                return None;
            }
            let velocity = after
                .player_velocity(candidate.id)
                .or_else(|| before.player_velocity(candidate.id))
                .unwrap_or(candidate.velocity);
            let to_ball = after.ball.position - position;
            let closing_speed = if to_ball.len() > 1e-6 {
                velocity.dot(to_ball.normalized()).max(0.0)
            } else {
                0.0
            };
            let stride_speed = velocity.dot(pass_dir).max(0.0);
            let forward_ball = pass_vector.y * player.team.attack_dir();
            let candidate_forward = (position.y - player.position.y) * player.team.attack_dir();
            let forward_fit = if forward_ball > 0.5 && candidate_forward > -2.0 {
                1.0
            } else {
                0.0
            };
            let score = distance_to_ball + lane_distance * 0.38
                - closing_speed * 0.58
                - stride_speed * 0.34
                - forward_fit * 0.65;
            Some((score, candidate.id))
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|a, b| {
        a.0.partial_cmp(&b.0)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.1.cmp(&b.1))
    });
    candidates.first().map(|(_, id)| *id)
}

fn tracking_team_scored(team: Team, before: &WorldSnapshot, after: &WorldSnapshot) -> bool {
    match team {
        Team::Home => after.score_home > before.score_home,
        Team::Away => after.score_away > before.score_away,
    }
}

fn tracking_ball_moved_toward_goal(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    team: Team,
) -> bool {
    (after.ball.position.y - before.ball.position.y) * team.attack_dir() > 3.0
}

fn tracking_ball_near_teammate(after: &WorldSnapshot, player_id: usize, team: Team) -> bool {
    after
        .players
        .iter()
        .filter(|p| p.team == team && p.id != player_id)
        .any(|p| p.position.distance(after.ball.position) < 4.0)
}

fn tracking_goal_events(
    before: &WorldSnapshot,
    after: &WorldSnapshot,
    events: &mut Vec<MatchEvent>,
) {
    if after.score_home > before.score_home {
        events.push(MatchEvent {
            tick: after.tick,
            clock_seconds: after.clock_seconds,
            kind: "goal".to_string(),
            team: Some(Team::Home),
            player_id: before.ball.holder,
            description: "Home goal from tracking data".to_string(),
        });
    }
    if after.score_away > before.score_away {
        events.push(MatchEvent {
            tick: after.tick,
            clock_seconds: after.clock_seconds,
            kind: "goal".to_string(),
            team: Some(Team::Away),
            player_id: before.ball.holder,
            description: "Away goal from tracking data".to_string(),
        });
    }
}

fn soccer_moment_replay_action_for_label(label: &str) -> Option<&'static str> {
    match label {
        "great_shot_to_goal" => Some("shoot"),
        "great_pass_to_goal" => Some("pass"),
        "great_dribble_to_goal" => Some("dribble"),
        _ => None,
    }
}

fn soccer_moment_replay_reward_for_label(label: &str) -> Option<f64> {
    match label {
        "great_shot_to_goal" => Some(SOCCER_MOMENT_REPLAY_SHOT_REWARD),
        "great_pass_to_goal" => Some(SOCCER_MOMENT_REPLAY_PASS_REWARD),
        "great_dribble_to_goal" => Some(SOCCER_MOMENT_REPLAY_DRIBBLE_REWARD),
        _ => None,
    }
}

fn soccer_moment_action_matches_label(action: &SoccerMomentActionMarker, label: &str) -> bool {
    let action = normalize_soccer_action_label(&action.action);
    match label {
        "great_shot_to_goal" => matches!(action, "shoot" | "first-time-shot"),
        "great_pass_to_goal" => is_pass_like_action(action),
        "great_dribble_to_goal" => is_dribble_action_label(action),
        _ => false,
    }
}

fn soccer_moment_replay_marker(
    actions: &[SoccerMomentActionMarker],
    label: &str,
    player_id: Option<usize>,
) -> Option<SoccerMomentActionMarker> {
    actions
        .iter()
        .rev()
        .filter(|action| soccer_moment_action_matches_label(action, label))
        .find(|action| player_id.map(|id| id == action.player_id).unwrap_or(true))
        .or_else(|| {
            actions
                .iter()
                .rev()
                .find(|action| soccer_moment_action_matches_label(action, label))
        })
        .cloned()
}

fn soccer_moment_frame_pair_for_tick(
    frames: &[SoccerTrackingFrame],
    tick: u64,
) -> Option<(&SoccerTrackingFrame, &SoccerTrackingFrame)> {
    if frames.len() < 2 {
        return None;
    }
    for pair in frames.windows(2) {
        let before = &pair[0];
        let after = &pair[1];
        if before.tick <= tick && tick <= after.tick {
            return Some((before, after));
        }
    }
    if tick < frames[0].tick {
        Some((&frames[0], &frames[1]))
    } else {
        let last = frames.len() - 1;
        Some((&frames[last - 1], &frames[last]))
    }
}

fn soccer_moment_action_target_trace(
    marker: Option<&SoccerMomentActionMarker>,
    action: &str,
    player: &PlayerSnapshot,
    before: &WorldSnapshot,
    after: &WorldSnapshot,
) -> Option<AgentActionTargetTrace> {
    let normalized = normalize_soccer_action_label(action);
    let next_player = after.players.iter().find(|p| p.id == player.id);
    let goal = Vec2::new(
        before.field_width * 0.5,
        player.team.goal_y(before.field_length),
    );
    let marker_target = marker.and_then(|marker| marker.target_player);
    let (point, target_player) = match normalized {
        action if is_pass_like_action(action) => {
            let target_player = marker_target.or(after.ball.holder);
            let point = target_player
                .and_then(|id| {
                    after
                        .player_position(id)
                        .or_else(|| before.player_position(id))
                })
                .unwrap_or(after.ball.position);
            (point, target_player)
        }
        "shoot" | "first-time-shot" | "first-time-header" => (goal, None),
        "dribble"
        | "carry-forward"
        | "carry-out-left"
        | "carry-out-right"
        | "protect-ball"
        | "side-step"
        | "left-cut"
        | "right-cut"
        | "nutmeg"
        | "fake-left-cut-right"
        | "fake-right-cut-left"
        | "control-touch"
        | "space"
        | "support-shape"
        | "support-roam"
        | "check-to-ball"
        | "run-in-behind"
        | "wide-outlet"
        | "shot-creation-run"
        | "overlap-run"
        | "support-push-up"
        | "support-screen"
        | "defend" => (
            next_player.map(|p| p.position).unwrap_or(player.position),
            None,
        ),
        "tackle" => {
            let target_player = before.ball.holder.or(after.ball.holder);
            let point = target_player
                .and_then(|id| {
                    before
                        .player_position(id)
                        .or_else(|| after.player_position(id))
                })
                .unwrap_or(before.ball.position);
            (point, target_player)
        }
        _ => return None,
    };
    let point = point.clamp_to_pitch(before.field_width, before.field_length);
    let dribble_touch = if is_dribble_action_label(normalized) {
        tracking_dribble_touch_from_positions(player.team, player.position, point)
    } else {
        None
    };
    Some(AgentActionTargetTrace {
        point: Some(point),
        player_id: target_player,
        grid: Some(pitch_grid_address(
            point,
            before.field_width,
            before.field_length,
        )),
        facing: facing_bucket_from_vector(point - player.position),
        dribble_touch,
    })
}

fn soccer_moment_replay_transition(
    record: &SoccerMomentStorageRecord,
    config: &MatchConfig,
    reward_scale: f64,
) -> Result<Option<SoccerLearningTransition>, String> {
    let label = record.window.summary.label.as_str();
    let Some(default_action) = soccer_moment_replay_action_for_label(label) else {
        return Ok(None);
    };
    let Some(base_reward) = soccer_moment_replay_reward_for_label(label) else {
        return Ok(None);
    };
    if record.window.frames.len() < 2 {
        return Ok(None);
    }

    let marker = soccer_moment_replay_marker(
        &record.window.actions,
        label,
        record.window.summary.player_id,
    );
    let action = marker
        .as_ref()
        .map(|marker| normalize_soccer_action_label(&marker.action).to_string())
        .unwrap_or_else(|| default_action.to_string());
    let tick = marker
        .as_ref()
        .map(|marker| marker.tick)
        .unwrap_or(record.window.summary.event_tick);
    let player_id = marker
        .as_ref()
        .map(|marker| marker.player_id)
        .or(record.window.summary.player_id);
    let Some(player_id) = player_id else {
        return Ok(None);
    };

    let tracking = SoccerTrackingDataset {
        source: format!("moment-replay:{}", record.window.summary.id),
        config: config.clone(),
        frames: record.window.frames.clone(),
    };
    tracking.validate()?;
    let frames = tracking_frames_with_inferred_kinematics(&tracking);
    let home_positions = tracking_home_positions(&tracking);
    let Some((before_frame, after_frame)) = soccer_moment_frame_pair_for_tick(&frames, tick) else {
        return Ok(None);
    };
    let before = tracking_frame_to_world_snapshot(config, before_frame, &home_positions);
    let after = tracking_frame_to_world_snapshot(config, after_frame, &home_positions);
    let Some(player) = before.players.iter().find(|player| player.id == player_id) else {
        return Ok(None);
    };

    let observation = before.observation_for(player_id);
    let action_target =
        soccer_moment_action_target_trace(marker.as_ref(), &action, player, &before, &after);
    let marker_reward = marker
        .as_ref()
        .map(|marker| marker.reward)
        .filter(|reward| reward.is_finite())
        .unwrap_or(0.0);
    let reward = marker_reward + base_reward * reward_scale;
    let mut decision_context = soccer_decision_context_for(
        player_id,
        player.team,
        &action,
        action_target.as_ref(),
        &before,
        &after,
    );
    decision_context.tracking_source_frame_id = before_frame.source_frame_id.clone();
    decision_context.next_tracking_source_frame_id = after_frame.source_frame_id.clone();
    let before_pos = before.player_position(player_id).unwrap_or(player.position);
    let after_pos = after.player_position(player_id).unwrap_or(before_pos);

    Ok(Some(SoccerLearningTransition {
        tick,
        player_id,
        team: player.team,
        role: player.role,
        state: before.mdp_state_for_player(player_id),
        observation: observation.clone(),
        belief: belief_from_observation(&observation),
        action,
        action_target,
        decision_context,
        tactical_trace: tactical_shape_trace_for_snapshots(
            player_id,
            player.team,
            player.role,
            &before,
            &after,
            before_pos,
            after_pos,
            &config.tactical_learning,
        ),
        reward,
        next_state: after.mdp_state_for_player(player_id),
        next_observation: after.observation_for(player_id),
        done: after_frame.tick
            == frames
                .last()
                .map(|frame| frame.tick)
                .unwrap_or(after_frame.tick),
    }))
}

fn player_agent_from_snapshot(player: &PlayerSnapshot) -> PlayerAgent {
    let mut position_history = player
        .position_history
        .iter()
        .copied()
        .collect::<VecDeque<_>>();
    if position_history.is_empty() {
        position_history.push_back(player.position);
    }
    while position_history.len() > PLAYER_POSITION_HISTORY_LIMIT {
        position_history.pop_front();
    }
    PlayerAgent {
        id: player.id,
        name: player.name.clone(),
        team: player.team,
        role: player.role,
        shirt: player.shirt,
        home_position: player.home_position,
        position: player.position,
        velocity: player.velocity,
        acceleration: player.acceleration,
        jerk: player.jerk,
        movement_gait: player.movement_gait,
        position_history,
        receive_facing: player.receive_facing,
        action_facing: player.action_facing,
        incoming_ball: player.incoming_ball.clone(),
        skills: player.skills.clone(),
        fatigue: player.fatigue.clamp(0.0, 1.0),
        controller_slot: None,
        preferences: player.preferences.clone(),
        last_decision: None,
    }
}

fn neutral_tracking_skill_profile(role: PlayerRole) -> SkillProfile {
    let shooting = match role {
        PlayerRole::Forward => 7.8,
        PlayerRole::Midfielder => 6.6,
        PlayerRole::Defender => 5.0,
        PlayerRole::Goalkeeper => 4.0,
    };
    SkillProfile {
        top_speed: 7.4,
        acceleration: 7.1,
        strength: match role {
            PlayerRole::Goalkeeper => 7.8,
            PlayerRole::Defender => 8.0,
            PlayerRole::Midfielder => 6.6,
            PlayerRole::Forward => 7.4,
        },
        height: match role {
            PlayerRole::Goalkeeper => 8.6,
            PlayerRole::Defender => 7.6,
            PlayerRole::Midfielder => 6.0,
            PlayerRole::Forward => 7.0,
        },
        weight_pounds: default_player_weight_for_traits(
            role,
            match role {
                PlayerRole::Goalkeeper => 7.8,
                PlayerRole::Defender => 8.0,
                PlayerRole::Midfielder => 6.6,
                PlayerRole::Forward => 7.4,
            },
            match role {
                PlayerRole::Goalkeeper => 8.6,
                PlayerRole::Defender => 7.6,
                PlayerRole::Midfielder => 6.0,
                PlayerRole::Forward => 7.0,
            },
            0.0,
        ),
        shooting,
        right_foot_shot_power: (shooting + 0.6).clamp(1.0, 10.0),
        left_foot_shot_power: (shooting - 0.8).clamp(1.0, 10.0),
        passing: 7.2,
        passing_completion_rate: 7.2,
        flair_passing: 4.2,
        crossing_left: 6.6,
        crossing_right: 7.0,
        dribbling: 6.8,
        first_touch: 7.0,
        defending: 6.8,
        goalkeeping: if role == PlayerRole::Goalkeeper {
            8.8
        } else {
            1.6
        },
        defensive_tracking: 6.8,
        stamina: 8.2,
        vision: DEFAULT_PLAYER_VISION_SKILL,
        decision_noise: 0.05,
        aggression: 5.8,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DefenderDribbleResponse {
    HoldUp,
    Commit,
}

fn dribble_dispossession_probability(
    defender: &SkillProfile,
    attacker: &SkillProfile,
    response: DefenderDribbleResponse,
) -> f64 {
    let base = match response {
        DefenderDribbleResponse::HoldUp => HOLD_UP_DISPOSSESSION_PROBABILITY,
        DefenderDribbleResponse::Commit => COMMIT_DISPOSSESSION_PROBABILITY,
    };
    let ball_control =
        ability01(attacker.dribbling) * 0.70 + ability01(attacker.first_touch) * 0.30;
    let defensive_pressure =
        ability01(defender.defending) * 0.82 + ability01(defender.aggression) * 0.18;
    let skill_edge = defensive_pressure - ball_control;
    match response {
        DefenderDribbleResponse::HoldUp => (base + skill_edge * 0.16).clamp(0.06, 0.42),
        DefenderDribbleResponse::Commit => (base + skill_edge * 0.22).clamp(0.24, 0.76),
    }
}

fn dribble_beat_probability(
    kind: DribbleMoveKind,
    attacker: &SkillProfile,
    defender: &SkillProfile,
    response: DefenderDribbleResponse,
) -> f64 {
    let attacker_evasion = ability01(attacker.dribbling) * 0.52
        + ability01(attacker.acceleration) * 0.28
        + ability01(attacker.first_touch) * 0.20;
    let defender_balance =
        ability01(defender.defending) * 0.68 + ability01(defender.aggression) * 0.32;
    let kind_multiplier = match kind {
        DribbleMoveKind::CarryForward => 0.72,
        DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight => 0.84,
        DribbleMoveKind::ProtectBall => 0.46,
        DribbleMoveKind::LeftCut | DribbleMoveKind::RightCut => 1.0,
        DribbleMoveKind::Nutmeg => 0.82,
        DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft => 1.05,
    };
    let response_multiplier = match response {
        DefenderDribbleResponse::HoldUp => 1.0,
        DefenderDribbleResponse::Commit => COMMIT_DRIBBLE_BEAT_MULTIPLIER,
    };
    let raw = attacker_evasion / (attacker_evasion + defender_balance * 0.94);
    (raw * kind_multiplier * response_multiplier).clamp(0.10, 0.88)
}

fn dribble_beat_geometry_is_valid(
    attacking_team: Team,
    attacker_before: Vec2,
    attacker_after: Vec2,
    defender_before: Vec2,
    defender_after: Vec2,
) -> bool {
    let challenge_distance = attacker_before.distance(defender_before);
    if challenge_distance > DRIBBLE_BEAT_CONTACT_RADIUS_YARDS {
        return false;
    }
    let attack_dir = attacking_team.attack_dir();
    let before_gap = (attacker_before.y - defender_before.y) * attack_dir;
    let after_gap = (attacker_after.y - defender_after.y) * attack_dir;
    let forward_progress = (attacker_after.y - attacker_before.y) * attack_dir;
    let after_lateral_gap = (attacker_after.x - defender_after.x).abs();
    before_gap <= DRIBBLE_BEAT_FRONT_LINE_TOLERANCE_YARDS
        && after_gap >= DRIBBLE_BEAT_BEHIND_LINE_TOLERANCE_YARDS
        && forward_progress >= 0.25
        && after_lateral_gap <= 6.0
}

fn dribble_dispossession_kind_multiplier(kind: DribbleMoveKind) -> f64 {
    match kind {
        DribbleMoveKind::ProtectBall => 0.58,
        DribbleMoveKind::CarryForward => 0.86,
        DribbleMoveKind::CarryOutLeft | DribbleMoveKind::CarryOutRight => 0.78,
        DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft => 0.92,
        DribbleMoveKind::LeftCut | DribbleMoveKind::RightCut => 1.0,
        DribbleMoveKind::Nutmeg => 1.12,
    }
}

fn tackle_success_probability(defender: &SkillProfile, attacker: &SkillProfile) -> f64 {
    dribble_dispossession_probability(defender, attacker, DefenderDribbleResponse::Commit)
}

fn tackle_foul_probability(
    defender: &SkillProfile,
    attacker: &SkillProfile,
    contact_distance: f64,
    contact_speed: f64,
) -> f64 {
    let timing_risk = (1.0 - ability01(defender.defending)) * 0.34;
    let aggression_risk = ability01(defender.aggression) * 0.24;
    let control_risk =
        (ability01(attacker.dribbling) * 0.55 + ability01(attacker.first_touch) * 0.45) * 0.12;
    let speed_risk = (contact_speed / 10.0).clamp(0.0, 1.0) * 0.18;
    let reach_risk = (contact_distance / 2.2).clamp(0.0, 1.0) * 0.10;
    (0.02 + timing_risk + aggression_risk + control_risk + speed_risk + reach_risk)
        .clamp(0.03, 0.78)
}

fn carried_ball_lead(player: &PlayerAgent) -> Vec2 {
    let facing = if player.velocity.len() > 0.45 {
        player.velocity.normalized()
    } else {
        Vec2::new(0.0, player.team.attack_dir())
    };
    facing * DRIBBLE_TOUCH_LEAD_YARDS
}

fn dribble_heavy_touch_probability(player: &PlayerAgent, pressure: f64) -> f64 {
    let control = ability01(player.skills.dribbling) * 0.58
        + ability01(player.skills.first_touch) * 0.30
        + ability01(player.skills.stamina) * 0.12;
    let fatigue_risk = player.fatigue.clamp(0.0, 1.0) * 0.05;
    let pressure = pressure.clamp(0.0, 1.0);
    (0.004 + pressure * (1.0 - control).clamp(0.0, 1.0) * 0.42 + fatigue_risk).clamp(0.004, 0.36)
}

fn pressure_from_observation(observation: &SoccerPomdpObservation) -> f64 {
    soccer_lp_unit(observation.perceived_pressure)
}

fn pressure_from_nearest_distance(nearest_opponent_distance: f64) -> f64 {
    if nearest_opponent_distance.is_finite() {
        (1.0 - nearest_opponent_distance / 18.0).clamp(0.0, 1.0)
    } else {
        0.0
    }
}

fn perceived_pressure_for_player(
    player: &PlayerSnapshot,
    real_pressure: f64,
    visible_opponents: usize,
) -> f64 {
    let vision_relief = (ability01(player.skills.vision) - 0.55).clamp(-0.25, 0.35) * 0.22;
    let crowding = (visible_opponents as f64 / 8.0).clamp(0.0, 1.0) * 0.12;
    (real_pressure + crowding - vision_relief).clamp(0.0, 1.0)
}

fn time_on_ball_seconds(pressure: f64) -> f64 {
    (2.8 - pressure.clamp(0.0, 1.0) * 2.35).clamp(0.25, 3.0)
}

fn dribble_hold_base_seconds(dribbling: f64) -> f64 {
    let dribbling = dribbling.clamp(0.0, 1.0);
    let elite_hold_start = 0.86;
    let elite_fit = ((dribbling - elite_hold_start)
        / (NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF - elite_hold_start))
        .clamp(0.0, 1.0);
    NON_ELITE_DRIBBLE_HOLD_BASE_SECONDS
        + (ELITE_DRIBBLE_HOLD_BASE_SECONDS - NON_ELITE_DRIBBLE_HOLD_BASE_SECONDS) * elite_fit
}

fn excessive_hold_pressure_from_parts(
    actual_time_on_ball_seconds: f64,
    pressure_urgency: f64,
    defensive_urgency: f64,
    perceived_pressure: f64,
    immediate_dispossession_risk: f64,
    dribbling: f64,
) -> f64 {
    let actual_hold = actual_time_on_ball_seconds.max(0.0);
    if actual_hold <= 0.0 {
        return 0.0;
    }
    let urgency = pressure_urgency
        .max(defensive_urgency)
        .max(perceived_pressure)
        .clamp(0.0, 1.0);
    let allowed_seconds = (dribble_hold_base_seconds(dribbling)
        - urgency * 1.55
        - immediate_dispossession_risk.clamp(0.0, 1.0) * 1.00)
        .clamp(0.55, ELITE_DRIBBLE_HOLD_BASE_SECONDS + 0.75);
    ((actual_hold - allowed_seconds) / 3.2).clamp(0.0, 1.0)
}

fn excessive_hold_pressure(observation: &SoccerPomdpObservation, dribbling: f64) -> f64 {
    excessive_hold_pressure_from_parts(
        observation.actual_time_on_ball_seconds,
        observation.pressure_urgency,
        observation.defensive_urgency,
        observation.perceived_pressure,
        observation.immediate_dispossession_risk,
        dribbling,
    )
}

fn dribble_hold_score_multiplier(observation: &SoccerPomdpObservation, dribbling: f64) -> f64 {
    let hold_pressure = excessive_hold_pressure(observation, dribbling);
    if hold_pressure <= 0.0 {
        return 1.0;
    }
    let non_elite_fit =
        ((NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF - dribbling.clamp(0.0, 1.0)) / 0.34).clamp(0.0, 1.0);
    let pressure_fit = observation
        .pressure_urgency
        .max(observation.perceived_pressure)
        .max(observation.immediate_dispossession_risk)
        .clamp(0.0, 1.0);
    (1.0 - hold_pressure * (0.38 + non_elite_fit * 0.86 + pressure_fit * 0.36)).clamp(
        if dribbling >= NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF {
            0.66
        } else {
            0.06
        },
        1.0,
    )
}

fn release_after_hold_multiplier(observation: &SoccerPomdpObservation, dribbling: f64) -> f64 {
    let hold_pressure = excessive_hold_pressure(observation, dribbling);
    if hold_pressure <= 0.0 {
        return 1.0;
    }
    let non_elite_fit =
        ((NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF - dribbling.clamp(0.0, 1.0)) / 0.34).clamp(0.0, 1.0);
    let urgency_fit = observation
        .pressure_urgency
        .max(observation.defensive_urgency)
        .max(observation.immediate_dispossession_risk)
        .clamp(0.0, 1.0);
    (1.0 + hold_pressure * (0.58 + non_elite_fit * 0.86 + urgency_fit * 0.68)).clamp(1.0, 3.20)
}

fn excessive_hold_penalty_points(observation: &SoccerPomdpObservation, dribbling: f64) -> f64 {
    let hold_pressure = excessive_hold_pressure(observation, dribbling);
    if hold_pressure <= 0.0 {
        return 0.0;
    }
    let non_elite_fit =
        ((NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF - dribbling.clamp(0.0, 1.0)) / 0.34).clamp(0.0, 1.0);
    let urgency_fit = observation
        .pressure_urgency
        .max(observation.defensive_urgency)
        .max(observation.immediate_dispossession_risk)
        .clamp(0.0, 1.0);
    (EXCESSIVE_HOLD_PENALTY_POINTS
        * hold_pressure
        * (0.35 + non_elite_fit * 0.52 + urgency_fit * 0.30))
        .clamp(0.0, EXCESSIVE_HOLD_PENALTY_POINTS * 1.25)
}

fn pressured_stale_dribble_learning_penalty_points(
    observation: &SoccerPomdpObservation,
    dribbling: f64,
    ball_forward_yards: f64,
    player_forward_yards: f64,
    retained_team_possession: bool,
) -> f64 {
    let hold_pressure = excessive_hold_pressure(observation, dribbling);
    let danger_pressure = observation
        .pressure_urgency
        .max(observation.perceived_pressure)
        .max(observation.immediate_dispossession_risk)
        .clamp(0.0, 1.0);
    if hold_pressure < 0.12 || danger_pressure < 0.38 {
        return 0.0;
    }

    let progress = ball_forward_yards.max(player_forward_yards);
    let progress_relief = (progress / 7.0).clamp(0.0, 1.0);
    if dribbling >= NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF
        && (hold_pressure < 0.70 || progress_relief >= 0.35)
    {
        return 0.0;
    }

    let non_elite_fit =
        ((NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF - dribbling.clamp(0.0, 1.0)) / 0.34).clamp(0.0, 1.0);
    let skill_multiplier = if dribbling >= NON_ELITE_DRIBBLE_HOLD_SKILL_CUTOFF {
        0.18
    } else {
        0.42 + non_elite_fit * 0.72
    };
    let possession_multiplier = if retained_team_possession { 0.78 } else { 1.12 };
    (EXCESSIVE_HOLD_PENALTY_POINTS
        * hold_pressure
        * (0.44 + danger_pressure * 0.56)
        * skill_multiplier
        * possession_multiplier
        * (1.0 - progress_relief * 0.74).clamp(0.20, 1.0))
    .clamp(0.0, EXCESSIVE_HOLD_PENALTY_POINTS * 1.35)
}

fn immediate_dispossession_risk_for_player(
    player: &PlayerSnapshot,
    nearest_opponent_distance: f64,
    perceived_pressure: f64,
    perceived_time_on_ball_seconds: f64,
) -> f64 {
    let close_risk =
        (1.0 - (nearest_opponent_distance - PLAYER_CONTROL_RADIUS_YARDS) / 4.4).clamp(0.0, 1.0);
    let control_skill = ability01(player.skills.dribbling) * 0.52
        + ability01(player.skills.first_touch) * 0.30
        + ability01(player.skills.strength) * 0.18;
    let skill_risk = (1.0 - control_skill).clamp(0.0, 1.0);
    let clock_risk = (1.0 - perceived_time_on_ball_seconds / 2.8).clamp(0.0, 1.0);
    (perceived_pressure.clamp(0.0, 1.0) * 0.42
        + close_risk * 0.32
        + clock_risk * 0.16
        + skill_risk * 0.16
        + player.fatigue.clamp(0.0, 1.0) * 0.10)
        .clamp(0.0, 1.0)
}

fn goal_attack_window_score_for_role(
    role: PlayerRole,
    has_ball: bool,
    yards_to_goal: f64,
    shot_lane_open: bool,
    shot_block_probability: f64,
    shot_on_frame_probability: f64,
    shot_beat_goalkeeper_probability: f64,
    opponent_goal_angle_degrees: f64,
    forward_dribble_space_yards: f64,
    facing_goal_score: f64,
) -> f64 {
    if !has_ball || role == PlayerRole::Goalkeeper || yards_to_goal <= 0.0 {
        return 0.0;
    }
    let window_yards = match role {
        PlayerRole::Forward => ATTACKING_DRIBBLE_GOAL_DRIVE_YARDS,
        PlayerRole::Midfielder => TEAMMATE_MUST_SHOOT_YARDS + 6.0,
        PlayerRole::Defender => TEAMMATE_MUST_SHOOT_YARDS + 3.0,
        PlayerRole::Goalkeeper => return 0.0,
    };
    if yards_to_goal > window_yards {
        return 0.0;
    }

    let mut distance_fit = ((window_yards - yards_to_goal) / window_yards).clamp(0.0, 1.0);
    if role == PlayerRole::Forward && yards_to_goal <= STRIKER_SHOT_WINDOW_YARDS {
        distance_fit = distance_fit.max(0.30);
    }
    if yards_to_goal <= TEAMMATE_MUST_SHOOT_YARDS {
        distance_fit = distance_fit.max(0.48);
    }

    let block_fit = (1.0 - shot_block_probability.clamp(0.0, 1.0)).clamp(0.0, 1.0);
    let shot_fit = (shot_on_frame_probability.clamp(0.0, 1.0) * 0.36
        + shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 0.28
        + block_fit * 0.24
        + (opponent_goal_angle_degrees / 42.0).clamp(0.0, 1.0) * 0.12)
        .clamp(0.0, 1.0);
    let carry_space_fit = (forward_dribble_space_yards / 12.0).clamp(0.0, 1.0);
    let lane_fit = if shot_lane_open {
        0.50 + shot_fit * 0.32
    } else {
        carry_space_fit * 0.38 + block_fit * 0.10
    };
    let role_fit = match role {
        PlayerRole::Forward => 1.14,
        PlayerRole::Midfielder => 0.94,
        PlayerRole::Defender => 0.64,
        PlayerRole::Goalkeeper => 0.0,
    };

    (distance_fit
        * (0.22 + lane_fit + carry_space_fit * 0.16 + facing_goal_score.clamp(0.0, 1.0) * 0.16)
        * role_fit)
        .clamp(0.0, 1.0)
}

fn shot_decision_is_qualified(observation: &SoccerPomdpObservation) -> bool {
    if !observation.shot_lane_open {
        return false;
    }
    let block_risk = observation.shot_block_probability.clamp(0.0, 1.0);
    let quality_shot = block_risk <= SHOT_BLOCK_DECISION_MAX_PROBABILITY
        && observation.shot_on_frame_probability >= SHOT_ON_FRAME_MIN_PROBABILITY
        && observation.shot_beat_goalkeeper_probability >= SHOT_KEEPER_BEAT_MIN_PROBABILITY;
    let pressure_bailout = block_risk <= SHOT_BLOCK_BAILOUT_MAX_PROBABILITY
        && observation.yards_to_goal <= SHOT_BAILOUT_NEAR_GOAL_YARDS
        && observation.immediate_dispossession_risk >= SHOT_BAILOUT_DISPOSSESSION_RISK
        && observation.shot_on_frame_probability >= SHOT_BAILOUT_ON_FRAME_PROBABILITY;
    let goal_urgency_bailout = observation.offensive_urgency >= 0.58
        && block_risk <= 0.62
        && observation.shot_on_frame_probability >= 0.18
        && observation.shot_beat_goalkeeper_probability >= 0.12;
    quality_shot || pressure_bailout || goal_urgency_bailout
}

fn shot_decision_is_qualified_for_role(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    shot_decision_is_qualified(observation)
        || attacking_goal_pressure_shot_is_qualified(observation, role)
        || clean_twenty_yard_shot_is_qualified(observation, role)
        || teammate_near_goal_shot_is_qualified(observation, role)
        || striker_shot_window_is_qualified(observation, role)
}

fn attacking_goal_pressure_shot_is_qualified(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    if role == PlayerRole::Goalkeeper || !observation.shot_lane_open {
        return false;
    }
    observation.yards_to_goal <= ATTACKING_GOAL_PRESSURE_SHOT_YARDS
        && observation.shot_block_probability.clamp(0.0, 1.0) <= SHOT_BLOCK_DECISION_MAX_PROBABILITY
        && observation.shot_on_frame_probability >= STRIKER_SHOT_MIN_ON_FRAME_PROBABILITY
        && observation.shot_beat_goalkeeper_probability >= STRIKER_SHOT_MIN_KEEPER_BEAT_PROBABILITY
        && observation.opponent_goal_angle_degrees >= 8.0
}

fn attacking_goal_pressure_shot_attempt_probability(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> f64 {
    if !attacking_goal_pressure_shot_is_qualified(observation, role) {
        return 0.0;
    }
    let range_fit = ((ATTACKING_GOAL_PRESSURE_SHOT_YARDS - observation.yards_to_goal)
        / (ATTACKING_GOAL_PRESSURE_SHOT_YARDS - TEAMMATE_MUST_SHOOT_YARDS).max(1e-6))
    .clamp(0.0, 1.0);
    let role_bonus = match role {
        PlayerRole::Forward => 0.18,
        PlayerRole::Midfielder => 0.11,
        PlayerRole::Defender => 0.04,
        PlayerRole::Goalkeeper => 0.0,
    };
    (0.10
        + role_bonus
        + shooting_skill.clamp(0.0, 1.0) * 0.10
        + range_fit * 0.22
        + observation.offensive_urgency.clamp(0.0, 1.0) * 0.12
        + observation.goal_attack_window_score.clamp(0.0, 1.0) * 0.08
        + observation.shot_on_frame_probability.clamp(0.0, 1.0) * 0.08)
        .clamp(0.0, 0.66)
}

fn speculative_long_shot_is_qualified(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> bool {
    if role == PlayerRole::Goalkeeper || !observation.shot_lane_open {
        return false;
    }
    let distance = observation.yards_to_goal;
    if !(TEAMMATE_MUST_SHOOT_YARDS..=SPECULATIVE_LONG_SHOT_MAX_YARDS).contains(&distance) {
        return false;
    }
    if observation.shot_block_probability.clamp(0.0, 1.0)
        > SPECULATIVE_LONG_SHOT_MAX_BLOCK_PROBABILITY
    {
        return false;
    }
    if observation.shot_on_frame_probability < SPECULATIVE_LONG_SHOT_MIN_ON_FRAME_PROBABILITY {
        return false;
    }
    let urgency = observation
        .offensive_urgency
        .max(observation.decision_urgency)
        .max(observation.pressure_urgency * 0.72)
        .clamp(0.0, 1.0);
    let role_floor = match role {
        PlayerRole::Forward => 0.06,
        PlayerRole::Midfielder => 0.03,
        PlayerRole::Defender | PlayerRole::Goalkeeper => 0.0,
    };
    shooting_skill >= SPECULATIVE_LONG_SHOT_SKILL_GATE
        || urgency >= 0.48
        || observation.goal_attack_window_score >= 0.18
        || role_floor > 0.0 && observation.offensive_urgency >= 0.36
}

fn speculative_long_shot_attempt_probability(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> f64 {
    if !speculative_long_shot_is_qualified(observation, role, shooting_skill) {
        return 0.0;
    }
    let distance_fit = ((SPECULATIVE_LONG_SHOT_MAX_YARDS - observation.yards_to_goal)
        / (SPECULATIVE_LONG_SHOT_MAX_YARDS - TEAMMATE_MUST_SHOOT_YARDS).max(1e-6))
    .clamp(0.0, 1.0);
    let lane_fit = (1.0
        - observation.shot_block_probability.clamp(0.0, 1.0)
            / SPECULATIVE_LONG_SHOT_MAX_BLOCK_PROBABILITY.max(1e-6))
    .clamp(0.0, 1.0);
    let urgency = observation
        .offensive_urgency
        .max(observation.decision_urgency)
        .max(observation.pressure_urgency * 0.72)
        .clamp(0.0, 1.0);
    let role_bonus = match role {
        PlayerRole::Forward => 0.020,
        PlayerRole::Midfielder => 0.012,
        PlayerRole::Defender => 0.004,
        PlayerRole::Goalkeeper => 0.0,
    };
    (0.012
        + role_bonus
        + shooting_skill.clamp(0.0, 1.0) * 0.050
        + urgency * 0.040
        + distance_fit * 0.025
        + lane_fit * 0.018
        + observation.shot_on_frame_probability.clamp(0.0, 1.0) * 0.020)
        .clamp(0.0, 0.18)
}

fn goal_proximity_shot_pressure_score(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> f64 {
    if role == PlayerRole::Goalkeeper || !observation.shot_lane_open {
        return 0.0;
    }
    let window_yards = match role {
        PlayerRole::Forward => SPECULATIVE_LONG_SHOT_MAX_YARDS,
        PlayerRole::Midfielder => SPECULATIVE_LONG_SHOT_MAX_YARDS - 5.0,
        PlayerRole::Defender => TEAMMATE_MUST_SHOOT_YARDS + 5.0,
        PlayerRole::Goalkeeper => return 0.0,
    };
    if observation.yards_to_goal > window_yards {
        return 0.0;
    }
    let block_risk = observation.shot_block_probability.clamp(0.0, 1.0);
    let lane_fit =
        (1.0 - block_risk / STRIKER_SHOT_MAX_BLOCK_PROBABILITY.max(1e-6)).clamp(0.0, 1.0);
    let distance_fit = ((window_yards - observation.yards_to_goal) / window_yards)
        .clamp(0.0, 1.0)
        .powf(0.72);
    let quality_fit = (observation.shot_on_frame_probability.clamp(0.0, 1.0) * 0.42
        + observation.shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 0.24
        + lane_fit * 0.22
        + (observation.opponent_goal_angle_degrees / 42.0).clamp(0.0, 1.0) * 0.12)
        .clamp(0.0, 1.0);
    let role_fit = match role {
        PlayerRole::Forward => 1.12,
        PlayerRole::Midfielder => 0.92,
        PlayerRole::Defender => 0.54,
        PlayerRole::Goalkeeper => 0.0,
    };
    (distance_fit * 0.42
        + quality_fit * 0.24
        + observation.goal_attack_window_score.clamp(0.0, 1.0) * 0.18
        + observation.offensive_urgency.clamp(0.0, 1.0) * 0.10
        + shooting_skill.clamp(0.0, 1.0) * 0.06)
        .mul_add(role_fit, 0.0)
        .clamp(0.0, 1.0)
}

fn goal_proximity_shot_pressure_floor(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> f64 {
    if role == PlayerRole::Goalkeeper
        || !(shot_decision_is_qualified_for_role(observation, role)
            || speculative_long_shot_is_qualified(observation, role, shooting_skill))
    {
        return 0.0;
    }
    let pressure = goal_proximity_shot_pressure_score(observation, role, shooting_skill);
    if pressure <= 0.0 {
        return 0.0;
    }
    let role_floor = match role {
        PlayerRole::Forward => 0.06,
        PlayerRole::Midfielder => 0.04,
        PlayerRole::Defender => 0.015,
        PlayerRole::Goalkeeper => 0.0,
    };
    (role_floor
        + pressure * 0.34
        + observation.goal_attack_window_score.clamp(0.0, 1.0) * 0.08
        + observation.offensive_urgency.clamp(0.0, 1.0) * 0.04)
        .clamp(0.0, 0.56)
}

fn clean_twenty_yard_shot_is_qualified(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    if role == PlayerRole::Goalkeeper || !observation.shot_lane_open {
        return false;
    }
    observation.yards_to_goal <= CLEAN_SHOT_MUST_SHOOT_YARDS
        && observation.shot_block_probability.clamp(0.0, 1.0) <= CLEAN_SHOT_MAX_BLOCK_PROBABILITY
        && observation.shot_on_frame_probability >= CLEAN_SHOT_MIN_ON_FRAME_PROBABILITY
        && observation.shot_beat_goalkeeper_probability >= CLEAN_SHOT_MIN_KEEPER_BEAT_PROBABILITY
        && (observation.forward_dribble_space_yards >= 1.5
            || observation.shot_block_probability <= CLEAN_SHOT_MAX_BLOCK_PROBABILITY * 0.52)
}

fn teammate_near_goal_shot_is_qualified(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    let _ = role;
    let block_risk = observation.shot_block_probability.clamp(0.0, 1.0);
    observation.yards_to_goal <= TEAMMATE_MUST_SHOOT_YARDS
        && observation.shot_lane_open
        && block_risk <= STRIKER_SHOT_MAX_BLOCK_PROBABILITY
        && observation.shot_on_frame_probability >= STRIKER_SHOT_MIN_ON_FRAME_PROBABILITY
        && observation.shot_beat_goalkeeper_probability >= STRIKER_SHOT_MIN_KEEPER_BEAT_PROBABILITY
}

fn striker_shot_window_is_qualified(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    if role != PlayerRole::Forward {
        return false;
    }
    let block_risk = observation.shot_block_probability.clamp(0.0, 1.0);
    observation.yards_to_goal <= STRIKER_SHOT_WINDOW_YARDS
        && observation.shot_lane_open
        && block_risk <= STRIKER_SHOT_MAX_BLOCK_PROBABILITY
        && observation.shot_on_frame_probability >= STRIKER_SHOT_MIN_ON_FRAME_PROBABILITY
        && observation.shot_beat_goalkeeper_probability >= STRIKER_SHOT_MIN_KEEPER_BEAT_PROBABILITY
}

fn striker_must_shoot(observation: &SoccerPomdpObservation, role: PlayerRole) -> bool {
    must_shoot_near_goal(observation, role)
}

fn must_shoot_near_goal(observation: &SoccerPomdpObservation, role: PlayerRole) -> bool {
    teammate_near_goal_shot_is_qualified(observation, role)
        || clean_twenty_yard_shot_is_qualified(observation, role)
}

fn goal_attack_shot_is_required(observation: &SoccerPomdpObservation, role: PlayerRole) -> bool {
    if role == PlayerRole::Goalkeeper {
        return false;
    }
    must_shoot_near_goal(observation, role) || striker_shot_window_is_qualified(observation, role)
}

fn near_goal_no_shot_penalty_points(observation: &SoccerPomdpObservation, role: PlayerRole) -> f64 {
    if role == PlayerRole::Goalkeeper || !must_shoot_near_goal(observation, role) {
        return 0.0;
    }
    let role_multiplier = match role {
        PlayerRole::Forward => 1.25,
        PlayerRole::Midfielder => 1.0,
        PlayerRole::Defender => 0.62,
        PlayerRole::Goalkeeper => 0.0,
    };
    let close_fit = ((TEAMMATE_MUST_SHOOT_YARDS - observation.yards_to_goal)
        / TEAMMATE_MUST_SHOOT_YARDS)
        .clamp(0.0, 1.0);
    let shot_quality = (observation.shot_on_frame_probability.clamp(0.0, 1.0) * 0.48
        + observation.shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 0.32
        + (1.0 - observation.shot_block_probability.clamp(0.0, 1.0)) * 0.20)
        .clamp(0.0, 1.0);
    (NEAR_GOAL_NO_SHOT_PENALTY_POINTS
        * role_multiplier
        * (0.72 + close_fit * 0.58 + shot_quality * 0.42))
        .clamp(0.0, 8.0)
}

fn striker_legal_shot_attempt_bonus(observation: &SoccerPomdpObservation, role: PlayerRole) -> f64 {
    let window_qualified = striker_shot_window_is_qualified(observation, role)
        || teammate_near_goal_shot_is_qualified(observation, role);
    if !window_qualified {
        return 0.0;
    }
    let window_yards = if role == PlayerRole::Forward {
        STRIKER_SHOT_WINDOW_YARDS
    } else {
        TEAMMATE_MUST_SHOOT_YARDS
    };
    let range_fit = ((window_yards - observation.yards_to_goal) / window_yards).clamp(0.0, 1.0);
    let lane_fit = (1.0
        - observation.shot_block_probability.clamp(0.0, 1.0)
            / STRIKER_SHOT_MAX_BLOCK_PROBABILITY.max(1e-6))
    .clamp(0.0, 1.0);
    let on_frame_fit = (observation.shot_on_frame_probability
        / SHOT_ON_FRAME_MIN_PROBABILITY.max(1e-6))
    .clamp(0.0, 1.4);
    let keeper_fit = (observation.shot_beat_goalkeeper_probability
        / SHOT_KEEPER_BEAT_MIN_PROBABILITY.max(1e-6))
    .clamp(0.0, 1.4);
    let space_fit = (observation.forward_dribble_space_yards / 12.0).clamp(0.0, 1.0);
    let urgency = observation
        .offensive_urgency
        .max(observation.decision_urgency)
        .max(observation.pressure_urgency * 0.75)
        .clamp(0.0, 1.0);
    (0.08
        + range_fit * 0.14
        + lane_fit * 0.06
        + on_frame_fit * 0.05
        + keeper_fit * 0.04
        + space_fit * 0.04
        + urgency * 0.06)
        .clamp(0.0, 0.34)
}

fn near_goal_shot_pressure_floor(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> f64 {
    if role == PlayerRole::Goalkeeper || !shot_decision_is_qualified_for_role(observation, role) {
        return 0.0;
    }
    let window_yards = match role {
        PlayerRole::Forward => STRIKER_SHOT_WINDOW_YARDS,
        PlayerRole::Midfielder | PlayerRole::Defender => TEAMMATE_MUST_SHOOT_YARDS,
        PlayerRole::Goalkeeper => return 0.0,
    };
    if observation.yards_to_goal > window_yards {
        return 0.0;
    }
    let range_fit = ((window_yards - observation.yards_to_goal) / window_yards)
        .clamp(0.0, 1.0)
        .sqrt();
    let lane_fit = (1.0
        - observation.shot_block_probability.clamp(0.0, 1.0)
            / STRIKER_SHOT_MAX_BLOCK_PROBABILITY.max(1e-6))
    .clamp(0.0, 1.0);
    let shot_quality = (observation.shot_on_frame_probability.clamp(0.0, 1.0) * 0.42
        + observation.shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 0.34
        + lane_fit * 0.24)
        .clamp(0.0, 1.0);
    let role_floor = match role {
        PlayerRole::Forward => 0.16,
        PlayerRole::Midfielder => 0.11,
        PlayerRole::Defender => 0.07,
        PlayerRole::Goalkeeper => 0.0,
    };
    let must_shoot_bonus = if goal_attack_shot_is_required(observation, role) {
        0.26
    } else {
        0.0
    };
    (role_floor
        + range_fit * 0.39
        + shot_quality * 0.15
        + shooting_skill.clamp(0.0, 1.0) * 0.08
        + observation.goal_attack_window_score.clamp(0.0, 1.0) * 0.13
        + observation.offensive_urgency.clamp(0.0, 1.0) * 0.08
        + must_shoot_bonus)
        .clamp(0.0, 0.88)
}

fn killer_pass_goal_range_fit(observation: &SoccerPomdpObservation) -> f64 {
    if observation.yards_to_goal > KILLER_PASS_MAX_YARDS_TO_GOAL {
        0.0
    } else {
        ((KILLER_PASS_MAX_YARDS_TO_GOAL - observation.yards_to_goal)
            / KILLER_PASS_MAX_YARDS_TO_GOAL)
            .clamp(0.0, 1.0)
    }
}

fn killer_pass_goal_pressure_score(observation: &SoccerPomdpObservation) -> f64 {
    let range_fit = killer_pass_goal_range_fit(observation);
    if range_fit <= 0.0 {
        return 0.0;
    }
    let final_third_fit = ((42.0 - observation.yards_to_goal) / 24.0).clamp(0.0, 1.0);
    let receiver_lane_fit = (observation
        .best_forward_pass_receiver_openness
        .clamp(0.0, 1.0)
        * 0.42
        + observation.best_pass_stride_fit.clamp(0.0, 1.0) * 0.30
        + observation.floor_pass_lane_score.clamp(0.0, 1.0) * 0.28)
        .clamp(0.0, 1.0);
    (range_fit.powf(0.55) * 0.38
        + final_third_fit * 0.26
        + receiver_lane_fit * 0.22
        + observation.goal_attack_window_score.clamp(0.0, 1.0) * 0.10
        + observation.offensive_urgency.clamp(0.0, 1.0) * 0.04)
        .clamp(0.0, 1.0)
}

fn killer_pass_goal_pressure_floor(observation: &SoccerPomdpObservation) -> f64 {
    let pressure = killer_pass_goal_pressure_score(observation);
    if pressure <= 0.0 {
        return 0.0;
    }
    let danger_zone_fit = ((36.0 - observation.yards_to_goal) / 24.0).clamp(0.0, 1.0);
    (0.08
        + pressure * 0.30
        + danger_zone_fit * 0.10
        + observation
            .best_forward_pass_receiver_openness
            .clamp(0.0, 1.0)
            * 0.08
        + observation.floor_pass_lane_score.clamp(0.0, 1.0) * 0.06)
        .clamp(0.12, 0.58)
}

fn near_goal_decisive_action_pressure_score(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> f64 {
    if role == PlayerRole::Goalkeeper || observation.yards_to_goal > KILLER_PASS_MAX_YARDS_TO_GOAL {
        return 0.0;
    }
    let range_fit = ((KILLER_PASS_MAX_YARDS_TO_GOAL - observation.yards_to_goal)
        / KILLER_PASS_MAX_YARDS_TO_GOAL)
        .clamp(0.0, 1.0)
        .powf(0.62);
    let final_third_fit = ((42.0 - observation.yards_to_goal) / 24.0).clamp(0.0, 1.0);
    let shot_lane_fit = if observation.shot_lane_open {
        ((1.0 - observation.shot_block_probability.clamp(0.0, 1.0)) * 0.38
            + observation.shot_on_frame_probability.clamp(0.0, 1.0) * 0.34
            + observation.shot_beat_goalkeeper_probability.clamp(0.0, 1.0) * 0.22
            + (observation.opponent_goal_angle_degrees / 42.0).clamp(0.0, 1.0) * 0.06)
            .clamp(0.0, 1.0)
    } else {
        0.0
    };
    let threaded_lane_fit = (observation
        .best_forward_pass_receiver_openness
        .clamp(0.0, 1.0)
        * 0.36
        + observation.best_pass_stride_fit.clamp(0.0, 1.0) * 0.30
        + observation.floor_pass_lane_score.clamp(0.0, 1.0) * 0.34)
        .clamp(0.0, 1.0);
    let role_fit = match role {
        PlayerRole::Forward => 1.12,
        PlayerRole::Midfielder => 0.98,
        PlayerRole::Defender => 0.62,
        PlayerRole::Goalkeeper => 0.0,
    };

    ((range_fit * 0.34
        + final_third_fit * 0.22
        + shot_lane_fit.max(threaded_lane_fit) * 0.24
        + observation.goal_attack_window_score.clamp(0.0, 1.0) * 0.13
        + observation.offensive_urgency.clamp(0.0, 1.0) * 0.07)
        * role_fit)
        .clamp(0.0, 1.0)
}

fn killer_pass_forced_by_goal_pressure(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    if role == PlayerRole::Goalkeeper
        || goal_attack_shot_is_required(observation, role)
        || observation.visible_forward_pass_options == 0
        || observation.yards_to_goal > 42.0
    {
        return false;
    }
    let shot_not_clean = !shot_decision_is_qualified_for_role(observation, role)
        || observation.shot_block_probability.clamp(0.0, 1.0) >= 0.48;
    let threaded_lane = observation.floor_pass_lane_score.clamp(0.0, 1.0) >= 0.44
        && observation
            .best_forward_pass_receiver_openness
            .clamp(0.0, 1.0)
            >= 0.42;
    shot_not_clean && threaded_lane && killer_pass_goal_pressure_score(observation) >= 0.46
}

fn near_goal_pass_release_multiplier(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> f64 {
    if goal_attack_shot_is_required(observation, role) {
        0.08
    } else {
        1.0
    }
}

fn low_pressure_patience_factor(observation: &SoccerPomdpObservation) -> f64 {
    let urgency = observation
        .perceived_pressure
        .max(observation.pressure_urgency)
        .max(observation.immediate_dispossession_risk * 0.55)
        .clamp(0.0, 1.0);
    ((0.42 - urgency) / 0.42).clamp(0.0, 1.0)
}

fn pass_quality_for_patience(observation: &SoccerPomdpObservation, flight: PassFlight) -> f64 {
    match flight {
        PassFlight::Floor => (observation.expected_pass_completion.clamp(0.0, 1.0) * 0.50
            + observation.best_pass_receiver_openness.clamp(0.0, 1.0) * 0.32
            + observation.floor_pass_lane_score.clamp(0.0, 1.0) * 0.18)
            .clamp(0.0, 1.0),
        PassFlight::Aerial => (observation.expected_aerial_pass_completion.clamp(0.0, 1.0) * 0.46
            + observation
                .best_aerial_pass_receiver_openness
                .clamp(0.0, 1.0)
                * 0.24
            + observation.aerial_pass_bypass_score.clamp(0.0, 1.0) * 0.20
            + (1.0 - observation.aerial_pass_interception_risk.clamp(0.0, 1.0)) * 0.10)
            .clamp(0.0, 1.0),
    }
}

fn low_pressure_pass_release_multiplier(
    observation: &SoccerPomdpObservation,
    flight: PassFlight,
) -> f64 {
    let patience = low_pressure_patience_factor(observation);
    if patience <= 0.0 {
        return 1.0;
    }
    let quality = pass_quality_for_patience(observation, flight);
    let poor_pass = (1.0 - quality).clamp(0.0, 1.0);
    let carry_space = (observation.forward_dribble_space_yards / 18.0).clamp(0.0, 1.0);
    (1.0 - patience * poor_pass * (1.02 + carry_space * 0.34)).clamp(0.18, 1.0)
}

fn low_pressure_patient_carry_multiplier(observation: &SoccerPomdpObservation) -> f64 {
    let patience = low_pressure_patience_factor(observation);
    if patience <= 0.0 {
        return 1.0;
    }
    let poor_floor_pass =
        (1.0 - pass_quality_for_patience(observation, PassFlight::Floor)).clamp(0.0, 1.0);
    let carry_space = (observation.forward_dribble_space_yards / 18.0).clamp(0.0, 1.0);
    (1.0 + patience * poor_floor_pass * (0.72 + carry_space * 0.96)).clamp(1.0, 2.10)
}

fn low_pressure_patient_carry_preferred(observation: &SoccerPomdpObservation) -> bool {
    low_pressure_patience_factor(observation) >= 0.45
        && pass_quality_for_patience(observation, PassFlight::Floor) <= 0.76
        && observation.forward_dribble_space_yards >= 2.0
}

fn low_pressure_forced_pass_penalty_points(
    observation: &SoccerPomdpObservation,
    context: &SoccerDecisionContext,
    flight: PassFlight,
    retained_possession: bool,
) -> f64 {
    if !low_pressure_patient_carry_preferred(observation) {
        return 0.0;
    }
    let quality = pass_quality_for_patience(observation, flight);
    let poor_pass = (1.0 - quality).clamp(0.0, 1.0);
    if poor_pass <= 0.0 {
        return 0.0;
    }

    let patience = low_pressure_patience_factor(observation);
    let carry_space = (observation.forward_dribble_space_yards / 18.0).clamp(0.0, 1.0);
    let direction_cost = if context.target_forward_yards < -1.25 {
        0.58
    } else if context.target_forward_yards <= 1.25 {
        0.30
    } else {
        0.0
    };
    let outcome_cost = if retained_possession { 0.36 } else { 1.0 };

    (LOW_PRESSURE_FORCED_PASS_PENALTY_POINTS
        * patience
        * poor_pass
        * (0.55 + carry_space * 0.45)
        * (outcome_cost + direction_cost))
        .clamp(0.0, 2.65)
}

fn goal_approach_carry_window_yards(role: PlayerRole) -> f64 {
    match role {
        PlayerRole::Goalkeeper => 0.0,
        PlayerRole::Defender => ATTACKING_DRIBBLE_GOAL_DRIVE_YARDS,
        PlayerRole::Midfielder | PlayerRole::Forward => GOAL_APPROACH_CARRY_YARDS,
    }
}

fn goal_approach_drive_candidate(observation: &SoccerPomdpObservation, role: PlayerRole) -> bool {
    let goal_approach_window = goal_approach_carry_window_yards(role);
    observation.has_ball
        && !goal_attack_shot_is_required(observation, role)
        && observation.yards_to_goal <= goal_approach_window
        && (matches!(role, PlayerRole::Forward | PlayerRole::Midfielder)
            || observation.offensive_urgency >= 0.24
            || shot_creation_carry_multiplier(observation) >= 1.10)
}

fn goal_approach_carry_preferred(observation: &SoccerPomdpObservation, role: PlayerRole) -> bool {
    goal_approach_drive_candidate(observation, role)
        && observation.forward_dribble_space_yards >= 1.2
}

fn goal_approach_forces_goalmouth_carry(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    goal_approach_drive_candidate(observation, role)
}

fn goal_approach_dribble_kind(
    kind: DribbleMoveKind,
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> DribbleMoveKind {
    if goal_approach_forces_goalmouth_carry(observation, role)
        && !matches!(
            dribble_final_cut_kind(kind),
            DribbleMoveKind::FakeLeftCutRight | DribbleMoveKind::FakeRightCutLeft
        )
    {
        DribbleMoveKind::CarryForward
    } else {
        kind
    }
}

fn attacking_dribble_shooting_pocket_depth(yards_to_goal: f64) -> f64 {
    if yards_to_goal <= ATTACKING_DRIBBLE_SHOOTING_POCKET_YARDS {
        10.0
    } else if yards_to_goal <= TEAMMATE_MUST_SHOOT_YARDS {
        11.0
    } else {
        13.0
    }
}

fn close_clear_shot_attempt_probability(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
    shooting_skill: f64,
) -> f64 {
    if !shot_decision_is_qualified_for_role(observation, role) {
        return 0.0;
    }
    let (window_yards, ramp_yards) = match role {
        PlayerRole::Forward => (STRIKER_SHOT_WINDOW_YARDS, 18.0),
        _ => (TEAMMATE_MUST_SHOOT_YARDS, 16.0),
    };
    let mut close_fit = ((window_yards - observation.yards_to_goal) / ramp_yards).clamp(0.0, 1.0);
    if role == PlayerRole::Forward && observation.yards_to_goal <= STRIKER_SHOT_WINDOW_YARDS {
        close_fit = close_fit.max(0.24);
    }
    if striker_must_shoot(observation, role) {
        close_fit = close_fit.max(0.88);
    }
    if close_fit <= 0.0 {
        return 0.0;
    }
    let lane_fit = (1.0
        - observation.shot_block_probability.clamp(0.0, 1.0)
            / SHOT_BLOCK_DECISION_MAX_PROBABILITY.max(1e-6))
    .clamp(0.0, 1.0);
    let on_frame_fit =
        (observation.shot_on_frame_probability / SHOT_ON_FRAME_MIN_PROBABILITY).clamp(0.0, 1.35);
    let keeper_fit = (observation.shot_beat_goalkeeper_probability
        / SHOT_KEEPER_BEAT_MIN_PROBABILITY)
        .clamp(0.0, 1.35);
    let urgency = observation
        .offensive_urgency
        .max(observation.decision_urgency)
        .clamp(0.0, 1.0);
    let role_bonus = match role {
        PlayerRole::Forward => 0.24,
        PlayerRole::Midfielder => 0.08,
        PlayerRole::Defender => 0.02,
        PlayerRole::Goalkeeper => 0.0,
    };
    let striker_window_bonus = if role == PlayerRole::Forward {
        let window_fit = ((STRIKER_SHOT_WINDOW_YARDS - observation.yards_to_goal)
            / (STRIKER_SHOT_WINDOW_YARDS - STRIKER_MUST_SHOOT_YARDS).max(1e-6))
        .clamp(0.0, 1.0);
        0.18 + window_fit * 0.22
    } else {
        0.0
    };

    (0.22
        + close_fit * 0.32
        + lane_fit * 0.16
        + on_frame_fit * 0.13
        + keeper_fit * 0.11
        + shooting_skill.clamp(0.0, 1.0) * 0.10
        + urgency * 0.10
        + role_bonus
        + striker_window_bonus)
        .clamp(
            0.30,
            if role == PlayerRole::Forward {
                0.99
            } else {
                0.92
            },
        )
}

fn first_time_shot_decision_is_qualified(observation: &SoccerPomdpObservation) -> bool {
    observation.first_time_shot_score > 0.0 && shot_decision_is_qualified(observation)
}

fn first_time_shot_decision_is_qualified_for_role(
    observation: &SoccerPomdpObservation,
    role: PlayerRole,
) -> bool {
    observation.first_time_shot_score > 0.0
        && shot_decision_is_qualified_for_role(observation, role)
}

fn aerial_duel_skill_from_snapshot(player: &PlayerSnapshot) -> f64 {
    let height = ability01(player.skills.height);
    (height * 0.36
        + ability01(player.skills.strength) * 0.26
        + ability01(player.skills.aggression) * 0.18
        + ability01(player.skills.first_touch) * 0.20)
        .clamp(0.0, 1.0)
}

fn aerial_duel_skill_from_agent(player: &PlayerAgent) -> f64 {
    let height = ability01(player.skills.height);
    (height * 0.36
        + ability01(player.skills.strength) * 0.26
        + ability01(player.skills.aggression) * 0.18
        + ability01(player.skills.first_touch) * 0.20)
        .clamp(0.0, 1.0)
}

fn first_time_shot_score_for_player(
    player: &PlayerSnapshot,
    incoming_kind: IncomingBallKind,
    shot_block_probability: f64,
    yards_to_goal: f64,
    goal_angle_degrees: f64,
    pressure: f64,
) -> f64 {
    if shot_block_probability > SHOT_BLOCK_BAILOUT_MAX_PROBABILITY {
        return 0.0;
    }
    let foot_power = (ability01(
        player
            .skills
            .right_foot_shot_power
            .max(player.skills.left_foot_shot_power),
    ) * 0.70
        + ability01(player.skills.shooting) * 0.30)
        .clamp(0.0, 1.0);
    let aerial_finish = aerial_duel_skill_from_snapshot(player);
    let strike_skill = match incoming_kind {
        IncomingBallKind::AerialCross | IncomingBallKind::AerialPass => {
            foot_power * 0.45 + aerial_finish * 0.55
        }
        IncomingBallKind::Cross => foot_power * 0.78 + ability01(player.skills.first_touch) * 0.22,
        _ => foot_power * 0.70 + ability01(player.skills.first_touch) * 0.30,
    };
    let geometry = ((1.0 - yards_to_goal / 34.0).clamp(0.0, 1.0) * 0.58
        + (goal_angle_degrees / 42.0).clamp(0.0, 1.0) * 0.42)
        .clamp(0.0, 1.0);
    let quick_release_block_discount =
        (1.0 - shot_block_probability.clamp(0.0, 1.0) * 0.46).clamp(0.46, 1.0);
    ((strike_skill * 0.62 + geometry * 0.38 + pressure.clamp(0.0, 1.0) * 0.14)
        * quick_release_block_discount)
        .clamp(0.0, 1.0)
}

fn first_time_pass_score_for_player(
    player: &PlayerSnapshot,
    incoming_kind: IncomingBallKind,
    pressure: f64,
) -> f64 {
    let flair_bonus = match incoming_kind {
        IncomingBallKind::AerialCross | IncomingBallKind::AerialPass => 0.08,
        IncomingBallKind::Cross => 0.05,
        _ => 0.0,
    };
    (ability01(player.skills.passing_completion_rate) * 0.50
        + ability01(player.skills.first_touch) * 0.24
        + ability01(player.skills.flair_passing) * 0.18
        + pressure.clamp(0.0, 1.0) * 0.12
        + flair_bonus)
        .clamp(0.0, 1.0)
}

fn control_touch_score_for_player(
    player: &PlayerSnapshot,
    incoming_kind: IncomingBallKind,
    incoming_speed_yps: f64,
    pressure: f64,
) -> f64 {
    let aerial_control = if matches!(
        incoming_kind,
        IncomingBallKind::AerialCross | IncomingBallKind::AerialPass
    ) {
        aerial_duel_skill_from_snapshot(player) * 0.26
    } else {
        0.0
    };
    let speed_penalty = (incoming_speed_yps / 36.0).clamp(0.0, 1.0) * 0.20;
    (ability01(player.skills.first_touch) * 0.42
        + ability01(player.skills.strength) * 0.22
        + ability01(player.skills.dribbling) * 0.16
        + aerial_control
        - pressure.clamp(0.0, 1.0) * 0.18
        - speed_penalty)
        .clamp(0.0, 1.0)
}

fn angle_between_vectors_degrees(a: Vec2, b: Vec2) -> f64 {
    let al = a.len();
    let bl = b.len();
    if al <= 1e-9 || bl <= 1e-9 {
        return 0.0;
    }
    let cos = (a.dot(b) / (al * bl)).clamp(-1.0, 1.0);
    cos.acos().to_degrees()
}

fn vision_range_yards(vision: f64) -> f64 {
    PLAYER_BASE_VISION_RANGE_YARDS + ability01(vision) * PLAYER_VISION_RANGE_BONUS_YARDS
}

fn field_of_view_degrees(vision: f64) -> f64 {
    PLAYER_BASE_FIELD_OF_VIEW_DEGREES + ability01(vision) * PLAYER_FIELD_OF_VIEW_BONUS_DEGREES
}

fn player_vision_range(player: &PlayerSnapshot) -> f64 {
    if player.vision_range_yards.is_finite() && player.vision_range_yards > 0.0 {
        player.vision_range_yards
    } else {
        vision_range_yards(DEFAULT_PLAYER_VISION_SKILL)
    }
}

fn player_field_of_view(player: &PlayerSnapshot) -> f64 {
    if player.field_of_view_degrees.is_finite() && player.field_of_view_degrees > 0.0 {
        player.field_of_view_degrees
    } else {
        field_of_view_degrees(DEFAULT_PLAYER_VISION_SKILL)
    }
}

fn average_player_position_confidence<I>(
    snapshot: &WorldSnapshot,
    observer_id: usize,
    player_ids: I,
) -> f64
where
    I: IntoIterator<Item = usize>,
{
    let mut total = 0.0;
    let mut count = 0usize;
    for player_id in player_ids {
        if let Some(position) = snapshot.player_position(player_id) {
            if let Some(confidence) =
                snapshot.player_position_confidence_for_point(observer_id, position)
            {
                total += confidence;
                count += 1;
            }
        }
    }
    if count == 0 {
        0.0
    } else {
        total / count as f64
    }
}

fn average_player_position_confidence_entries(
    entries: &[PlayerPositionConfidence],
    team: Team,
) -> f64 {
    let mut total = 0.0;
    let mut count = 0usize;
    for entry in entries.iter().filter(|entry| entry.team == team) {
        total += finite_metric(entry.confidence).clamp(0.0, 1.0);
        count += 1;
    }
    if count == 0 {
        0.0
    } else {
        total / count as f64
    }
}

fn look_behind_scan_context_for_observer(
    tick: u64,
    dt_seconds: f64,
    observer: &PlayerSnapshot,
    observer_position: Vec2,
    ball_position: Vec2,
    ball_speed_yps: f64,
) -> LookBehindScanContext {
    let to_ball = ball_position - observer_position;
    if to_ball.len() <= PLAYER_CONTROL_RADIUS_YARDS * 0.6 {
        return LookBehindScanContext::default();
    }
    let Some(action_facing) = facing_bucket_to_vector(observer.action_facing) else {
        return LookBehindScanContext::default();
    };
    let ball_facing = to_ball.normalized();
    if action_facing.normalized().dot(ball_facing) > -0.25 {
        return LookBehindScanContext::default();
    }

    let dt = sane_dt_seconds(dt_seconds, DEFAULT_DT_SECONDS);
    let last_tick = observer
        .last_decision
        .as_ref()
        .map(|decision| decision.mdp_state.tick)
        .unwrap_or(tick.saturating_sub(1));
    let elapsed_ticks = tick.saturating_sub(last_tick).max(1);
    let duration_seconds = (elapsed_ticks as f64 * dt).clamp(dt, 4.0);
    let confidence_bonus = (0.18 + duration_seconds.min(1.2) / 1.2 * 0.24).clamp(0.0, 0.42);
    let moving_ball_risk = (finite_metric(ball_speed_yps).max(0.0) / 14.0).clamp(0.0, 0.65);
    let drift_risk =
        ((duration_seconds / 2.5).clamp(0.0, 1.0) * (0.35 + moving_ball_risk)).clamp(0.0, 1.0);

    LookBehindScanContext {
        active: true,
        duration_seconds,
        confidence_bonus,
        drift_risk,
    }
}

fn position_confidence_for_observer(
    observer: &PlayerSnapshot,
    observer_position: Vec2,
    point: Vec2,
    facing: Option<Vec2>,
    observer_has_ball: bool,
) -> f64 {
    let to_point = point - observer_position;
    let distance = to_point.len();
    if distance <= PLAYER_CONTROL_RADIUS_YARDS * 3.0 {
        return 1.0;
    }

    let range = player_vision_range(observer).max(1.0);
    let distance_confidence = (1.0 - (distance / range).clamp(0.0, 1.8) * 0.52).clamp(0.06, 1.0);
    let facing_confidence = if let Some(facing) = facing {
        let facing = facing.normalized();
        if facing.len() <= 1e-9 || distance <= 1e-9 {
            0.72
        } else {
            let dot = facing.dot(to_point.normalized());
            if observer_has_ball {
                let angle = dot.clamp(-1.0, 1.0).acos().to_degrees();
                if angle <= BALL_HOLDER_CORE_VISION_DEGREES * 0.5 {
                    BALL_HOLDER_CORE_POSITION_CONFIDENCE
                } else if angle
                    <= BALL_HOLDER_CORE_VISION_DEGREES * 0.5 + BALL_HOLDER_SHOULDER_VISION_DEGREES
                {
                    BALL_HOLDER_SHOULDER_POSITION_CONFIDENCE
                } else if dot >= 0.0 {
                    0.42
                } else {
                    0.24
                }
            } else {
                let half_fov_cos = (player_field_of_view(observer).to_radians() * 0.5).cos();
                if dot >= half_fov_cos {
                    1.0
                } else if dot >= 0.0 {
                    0.74
                } else {
                    0.50
                }
            }
        }
    } else {
        0.72
    };

    let confidence = (distance_confidence * facing_confidence).clamp(0.0, 1.0);
    if observer_has_ball && distance <= range {
        confidence.max(facing_confidence)
    } else {
        confidence
    }
}

fn pass_would_be_cross(
    from: Vec2,
    target: Vec2,
    team: Team,
    field_width: f64,
    field_length: f64,
) -> bool {
    let attacking_third = match team {
        Team::Home => from.y > field_length * 0.58 && target.y > field_length * 0.70,
        Team::Away => from.y < field_length * 0.42 && target.y < field_length * 0.30,
    };
    let wide_channel = from.x < field_width * 0.28 || from.x > field_width * 0.72;
    let target_central = target.x > field_width * 0.28 && target.x < field_width * 0.72;
    attacking_third && wide_channel && target_central
}

fn floor_pass_lane_score_for_snapshot(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    player_position: Vec2,
    targets: &[usize],
) -> f64 {
    if targets.is_empty() {
        return 0.0;
    }
    let mut total = 0.0;
    let mut count = 0usize;
    for target_id in targets {
        let Some(target) = snapshot.players.iter().find(|p| p.id == *target_id) else {
            continue;
        };
        let target_position = snapshot
            .player_position(target.id)
            .unwrap_or(target.position);
        let distance = player_position.distance(target_position);
        let confidence = snapshot
            .player_position_confidence_for_point(player.id, target_position)
            .unwrap_or(0.0);
        let forward = ((target_position.y - player_position.y) * player.team.attack_dir() / 28.0)
            .clamp(-0.25, 1.0);
        let distance_fit = (1.0 - (distance - 18.0).abs() / 32.0).clamp(0.0, 1.0);
        total += (0.30 + confidence * 0.34 + distance_fit * 0.22 + forward.max(0.0) * 0.14)
            .clamp(0.0, 1.0);
        count += 1;
    }
    if count == 0 {
        0.0
    } else {
        (total / count as f64).clamp(0.0, 1.0)
    }
}

fn aerial_pass_bypass_score_for_snapshot(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    player_position: Vec2,
    targets: &[usize],
) -> f64 {
    if targets.is_empty() {
        return 0.0;
    }
    let mut total = 0.0;
    let mut count = 0usize;
    for target_id in targets {
        let Some(target) = snapshot.players.iter().find(|p| p.id == *target_id) else {
            continue;
        };
        let target_position = snapshot
            .player_position(target.id)
            .unwrap_or(target.position);
        let floor_blocked =
            !snapshot.clear_line(player_position, target_position, player.team.other(), 2.5);
        let forward = ((target_position.y - player_position.y) * player.team.attack_dir() / 30.0)
            .clamp(-0.20, 1.0);
        let cross_bonus = if pass_would_be_cross(
            player_position,
            target_position,
            player.team,
            snapshot.field_width,
            snapshot.field_length,
        ) {
            0.18
        } else {
            0.0
        };
        let receiver_air = aerial_duel_skill_from_snapshot(target) * 0.30
            + ability01(target.skills.first_touch) * 0.12;
        let blocked_bonus = if floor_blocked { 0.44 } else { 0.08 };
        total +=
            (blocked_bonus + forward.max(0.0) * 0.18 + receiver_air + cross_bonus).clamp(0.0, 1.0);
        count += 1;
    }
    if count == 0 {
        0.0
    } else {
        (total / count as f64).clamp(0.0, 1.0)
    }
}

fn aerial_pass_interception_risk_for_snapshot(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    player_position: Vec2,
    targets: &[usize],
) -> f64 {
    if targets.is_empty() {
        return 0.0;
    }
    let mut total = 0.0;
    let mut count = 0usize;
    for target_id in targets {
        let Some(target) = snapshot.players.iter().find(|p| p.id == *target_id) else {
            continue;
        };
        let target_position = snapshot
            .player_position(target.id)
            .unwrap_or(target.position);
        let distance = player_position.distance(target_position);
        let nearest = snapshot
            .players
            .iter()
            .filter(|p| p.team != player.team)
            .map(|p| {
                snapshot
                    .player_position(p.id)
                    .unwrap_or(p.position)
                    .distance(target_position)
            })
            .fold(f64::INFINITY, f64::min);
        let nearby = snapshot
            .players
            .iter()
            .filter(|p| p.team != player.team)
            .filter(|p| {
                snapshot
                    .player_position(p.id)
                    .unwrap_or(p.position)
                    .distance(target_position)
                    <= 8.5
            })
            .count() as f64;
        let floor_like_risk =
            (0.05 + (1.0 - nearest / 16.0).clamp(0.0, 1.0) * 0.22 + nearby.min(4.0) * 0.045)
                .clamp(0.0, 0.45);
        let air_multiplier = if nearest <= 8.5 { 2.6 } else { 2.0 };
        let receiver_air = aerial_duel_skill_from_snapshot(target) * 0.62
            + ability01(target.skills.first_touch) * 0.20;
        let distance_risk = (distance / 48.0).clamp(0.0, 1.0) * 0.12;
        total += (floor_like_risk * air_multiplier + (1.0 - receiver_air) * 0.16 + distance_risk)
            .clamp(0.0, 1.0);
        count += 1;
    }
    if count == 0 {
        0.0
    } else {
        (total / count as f64).clamp(0.0, 1.0)
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct PassTargetQuality {
    receiver_openness: f64,
    expected_completion: f64,
    stride_fit: f64,
}

fn pass_target_quality_for_snapshot(
    snapshot: &WorldSnapshot,
    passer: &PlayerSnapshot,
    passer_position: Vec2,
    target: &PlayerSnapshot,
    target_position: Vec2,
    flight: PassFlight,
) -> PassTargetQuality {
    let initial_is_cross = pass_would_be_cross(
        passer_position,
        target_position,
        passer.team,
        snapshot.field_width,
        snapshot.field_length,
    );
    let initial_nominal_speed =
        pass_speed_yps_from_power(0.68, flight, initial_is_cross, &passer.skills);
    let target_velocity = snapshot
        .player_velocity(target.id)
        .unwrap_or(target.velocity);
    let initial_anticipated_target = snapshot
        .anticipated_pass_reception_point(passer.id, target.id, flight, initial_nominal_speed)
        .unwrap_or(target_position);
    let is_cross = pass_would_be_cross(
        passer_position,
        initial_anticipated_target,
        passer.team,
        snapshot.field_width,
        snapshot.field_length,
    );
    let pass_skill = pass_execution_skill(&passer.skills, flight, is_cross);
    let nominal_speed = pass_speed_yps_from_power(0.68, flight, is_cross, &passer.skills);
    let anticipated_target = if (nominal_speed - initial_nominal_speed).abs() > 0.5 {
        snapshot
            .anticipated_pass_reception_point(passer.id, target.id, flight, nominal_speed)
            .unwrap_or(initial_anticipated_target)
    } else {
        initial_anticipated_target
    };
    let distance = passer_position.distance(anticipated_target);
    let current_receiver_openness = pass_receiver_openness_for_snapshots_with_teammates(
        &snapshot.players,
        passer.team,
        target_position,
        Some(target.id),
    );
    let anticipated_receiver_openness = pass_receiver_openness_for_snapshots_with_teammates(
        &snapshot.players,
        passer.team,
        anticipated_target,
        Some(target.id),
    );
    let target_forward = (anticipated_target.y - passer_position.y) * passer.team.attack_dir();
    let anticipation_weight = if target_forward > 2.0 {
        0.38 + pass_skill * 0.34
    } else if target_forward >= -1.25 {
        0.28 + pass_skill * 0.20
    } else {
        0.12 + pass_skill * 0.10
    }
    .clamp(0.12, 0.74);
    let receiver_openness = (current_receiver_openness * (1.0 - anticipation_weight)
        + anticipated_receiver_openness * anticipation_weight)
        .clamp(0.0, 1.0);
    let stride_fit = pass_into_stride_fit(
        passer_position,
        target_position,
        target_velocity,
        anticipated_target,
        nominal_speed,
        passer.team,
    );
    let position_confidence = snapshot
        .player_position_confidence_for_point(passer.id, target_position)
        .unwrap_or(0.0);
    let lane = if flight.is_aerial() {
        let nearest_interceptor = snapshot
            .players
            .iter()
            .filter(|player| player.team != passer.team)
            .map(|player| {
                snapshot
                    .player_position(player.id)
                    .unwrap_or(player.position)
                    .distance(anticipated_target)
            })
            .fold(f64::INFINITY, f64::min);
        (0.42
            + receiver_openness * 0.18
            + (nearest_interceptor / 16.0).clamp(0.0, 1.0) * 0.16
            + aerial_duel_skill_from_snapshot(target) * 0.16)
            .clamp(0.20, 0.88)
    } else {
        let lane_open = if snapshot.clear_line(
            passer_position,
            anticipated_target,
            passer.team.other(),
            2.5,
        ) {
            1.0
        } else {
            0.24
        };
        (lane_open * 0.58 + receiver_openness * 0.28 + position_confidence * 0.14).clamp(0.10, 1.0)
    };
    let distance_fit = if flight.is_aerial() {
        (1.0 - (distance - 32.0).abs() / 58.0).clamp(0.24, 1.0)
    } else {
        (1.0 - (distance - 18.0).abs() / 42.0).clamp(0.20, 1.0)
    };
    let pressure_adjustment = 0.80 + receiver_openness * 0.20;
    let expected_completion = (0.10
        + pass_skill * 0.38
        + lane * 0.22
        + receiver_openness * 0.18
        + distance_fit * 0.08
        + stride_fit * 0.08)
        * pressure_adjustment;
    PassTargetQuality {
        receiver_openness,
        stride_fit,
        expected_completion: expected_completion.clamp(0.02, 0.98),
    }
}

fn best_pass_target_quality_for_snapshot(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    player_position: Vec2,
    targets: &[usize],
    flight: PassFlight,
) -> PassTargetQuality {
    targets
        .iter()
        .filter_map(|target_id| {
            let target = snapshot.players.iter().find(|p| p.id == *target_id)?;
            let target_position = snapshot
                .player_position(target.id)
                .unwrap_or(target.position);
            Some(pass_target_quality_for_snapshot(
                snapshot,
                player,
                player_position,
                target,
                target_position,
                flight,
            ))
        })
        .max_by(|a, b| {
            a.expected_completion
                .partial_cmp(&b.expected_completion)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .unwrap_or_default()
}

fn pass_execution_skill(skills: &SkillProfile, flight: PassFlight, is_cross: bool) -> f64 {
    let base = if is_cross {
        ability01(skills.crossing_left.max(skills.crossing_right)) * 0.74
            + ability01(skills.passing_completion_rate) * 0.18
            + ability01(skills.flair_passing) * 0.08
    } else {
        ability01(skills.passing_completion_rate) * 0.72
            + ability01(skills.passing) * 0.20
            + ability01(skills.flair_passing) * 0.08
    };
    if flight.is_aerial() {
        (base * 0.86 + ability01(skills.strength) * 0.08 + ability01(skills.flair_passing) * 0.06)
            .clamp(0.05, 0.99)
    } else {
        base.clamp(0.05, 0.99)
    }
}

fn goalkeeper_flank_width_score(position: Vec2, field_width: f64) -> f64 {
    let center_x = field_width * 0.5;
    let half_width = center_x.max(1.0);
    ((position.x - center_x).abs() / half_width).clamp(0.0, 1.0)
}

fn goalkeeper_backward_emergency_release_allowed(
    team: Team,
    passer_position: Vec2,
    target_position: Vec2,
    field_width: f64,
    pressure: f64,
) -> bool {
    let forward = (target_position.y - passer_position.y) * team.attack_dir();
    if forward >= -1.25 {
        return true;
    }
    if pressure < GOALKEEPER_BACKWARD_EMERGENCY_PRESSURE {
        return false;
    }
    let target_width = goalkeeper_flank_width_score(target_position, field_width);
    let passer_width = goalkeeper_flank_width_score(passer_position, field_width);
    target_width >= GOALKEEPER_FLANK_DISTRIBUTION_MIN_WIDTH && target_width >= passer_width + 0.16
}

fn goalkeeper_distribution_score(
    team: Team,
    passer_position: Vec2,
    target_position: Vec2,
    field_width: f64,
    pressure: f64,
) -> f64 {
    let forward = (target_position.y - passer_position.y) * team.attack_dir();
    let target_width = goalkeeper_flank_width_score(target_position, field_width);
    let passer_width = goalkeeper_flank_width_score(passer_position, field_width);
    let flank_bonus = target_width * 6.4 + (target_width - passer_width).max(0.0) * 2.0;
    let central_penalty = (1.0 - target_width) * 2.4;
    let forward_bonus = forward.max(0.0).min(54.0) * 0.035;
    let backward_penalty = if forward < -1.25 {
        if goalkeeper_backward_emergency_release_allowed(
            team,
            passer_position,
            target_position,
            field_width,
            pressure,
        ) {
            2.8
        } else {
            80.0
        }
    } else {
        0.0
    };
    flank_bonus + forward_bonus - central_penalty - backward_penalty
}

fn goalkeeper_flank_distribution_target(
    team: Team,
    from: Vec2,
    field_width: f64,
    field_length: f64,
    depth_yards: f64,
) -> Vec2 {
    let center_x = field_width * 0.5;
    let side = if from.x <= center_x { -1.0 } else { 1.0 };
    let target_x = (center_x + side * field_width * 0.38).clamp(4.0, field_width - 4.0);
    let territorial_y = from.y + team.attack_dir() * depth_yards;
    let target_y = match team {
        Team::Home => territorial_y
            .max(field_length * 0.38)
            .clamp(6.0, field_length - 8.0),
        Team::Away => territorial_y
            .min(field_length * 0.62)
            .clamp(8.0, field_length - 6.0),
    };
    Vec2::new(target_x, target_y)
}

fn clearance_target_for_actor(
    team: Team,
    from: Vec2,
    field_width: f64,
    field_length: f64,
    role: PlayerRole,
) -> Vec2 {
    if role == PlayerRole::Goalkeeper {
        goalkeeper_flank_distribution_target(team, from, field_width, field_length, 52.0)
    } else {
        clearance_target_for_player(team, from, field_width, field_length)
    }
}

fn route_one_target_for_actor(
    team: Team,
    from: Vec2,
    field_width: f64,
    field_length: f64,
    role: PlayerRole,
) -> Vec2 {
    if role == PlayerRole::Goalkeeper {
        goalkeeper_flank_distribution_target(team, from, field_width, field_length, 64.0)
    } else {
        route_one_target_for_player(team, from, field_width, field_length)
    }
}

fn clearance_target_for_player(
    team: Team,
    from: Vec2,
    field_width: f64,
    field_length: f64,
) -> Vec2 {
    let dir = team.attack_dir();
    let center_x = field_width * 0.5;
    let wide_release = if from.x <= center_x { -12.0 } else { 12.0 };
    let target_x = (from.x + wide_release).clamp(4.0, field_width - 4.0);
    let territorial_y = from.y + dir * 52.0;
    let target_y = match team {
        Team::Home => territorial_y
            .max(field_length * 0.54)
            .clamp(10.0, field_length - 8.0),
        Team::Away => territorial_y
            .min(field_length * 0.46)
            .clamp(8.0, field_length - 10.0),
    };
    Vec2::new(target_x, target_y)
}

fn route_one_target_for_player(
    team: Team,
    from: Vec2,
    field_width: f64,
    field_length: f64,
) -> Vec2 {
    let dir = team.attack_dir();
    let center_x = field_width * 0.5;
    let channel_x = (center_x + (from.x - center_x) * 0.32).clamp(10.0, field_width - 10.0);
    let territorial_y = from.y + dir * 62.0;
    let target_y = match team {
        Team::Home => territorial_y
            .max(field_length * 0.62)
            .clamp(12.0, field_length - 14.0),
        Team::Away => territorial_y
            .min(field_length * 0.38)
            .clamp(14.0, field_length - 12.0),
    };
    Vec2::new(channel_x, target_y)
}

fn incoming_context_from_pass(
    pass: &PendingPass,
    receiver: usize,
    speed_yps: f64,
    received_tick: u64,
) -> IncomingBallContext {
    IncomingBallContext {
        from_player: Some(pass.from),
        target_player: Some(receiver),
        team: Some(pass.team),
        kind: match (pass.flight, pass.is_cross) {
            (PassFlight::Floor, false) => IncomingBallKind::GroundPass,
            (PassFlight::Aerial, false) => IncomingBallKind::AerialPass,
            (PassFlight::Floor, true) => IncomingBallKind::Cross,
            (PassFlight::Aerial, true) => IncomingBallKind::AerialCross,
        },
        origin: Some(pass.origin),
        intended_target: Some(pass.intended_target),
        speed_yps,
        distance_yards: pass.distance_yards,
        received_tick,
        is_cross: pass.is_cross,
        is_aerial: pass.flight.is_aerial(),
    }
}

fn aerial_interception_multiplier(pass: &PendingPass, ball_position: Vec2) -> f64 {
    if !pass.flight.is_aerial() {
        return 1.0;
    }
    let landing_distance = ball_position.distance(pass.intended_target);
    if landing_distance <= 8.5 {
        2.6
    } else {
        2.0
    }
}

fn pass_ball_altitude_yards(pass: &PendingPass, ball_position: Vec2) -> f64 {
    if !pass.flight.is_aerial() {
        return 0.0;
    }
    let path = pass.intended_target - pass.origin;
    let denom = path.x * path.x + path.y * path.y;
    if denom <= 1e-9 {
        return 0.0;
    }
    let progress = dot(ball_position - pass.origin, path) / denom;
    let progress = progress.clamp(0.0, 1.0);
    let apex = (3.2 + pass.distance_yards.max(0.0) * 0.055).clamp(4.0, 11.5);
    (std::f64::consts::PI * progress).sin().max(0.0) * apex
}

fn pass_progress_along_path(pass: &PendingPass, ball_position: Vec2) -> f64 {
    let path = pass.intended_target - pass.origin;
    let denom = path.x * path.x + path.y * path.y;
    if denom <= 1e-9 {
        return 0.0;
    }
    (dot(ball_position - pass.origin, path) / denom).clamp(0.0, 1.0)
}

fn receiver_openness_from_nearest_opponent_distance(distance: f64) -> f64 {
    ((distance - 2.5) / 7.5).clamp(0.0, 1.0)
}

fn pass_receiver_openness_for_agents(
    players: &[PlayerAgent],
    receiving_team: Team,
    receiver_position: Vec2,
) -> f64 {
    let nearest = players
        .iter()
        .filter(|player| player.team == receiving_team.other())
        .map(|player| player.position.distance(receiver_position))
        .fold(f64::INFINITY, f64::min);
    receiver_openness_from_nearest_opponent_distance(nearest)
}

fn pass_receiver_openness_for_snapshots(
    players: &[PlayerSnapshot],
    receiving_team: Team,
    receiver_position: Vec2,
) -> f64 {
    let nearest = players
        .iter()
        .filter(|player| player.team == receiving_team.other())
        .map(|player| player.position.distance(receiver_position))
        .fold(f64::INFINITY, f64::min);
    receiver_openness_from_nearest_opponent_distance(nearest)
}

fn pass_receiver_openness_for_snapshots_with_teammates(
    players: &[PlayerSnapshot],
    receiving_team: Team,
    receiver_position: Vec2,
    receiver_id: Option<usize>,
) -> f64 {
    let opponent_openness =
        pass_receiver_openness_for_snapshots(players, receiving_team, receiver_position);
    let nearest_teammate = players
        .iter()
        .filter(|player| player.team == receiving_team)
        .filter(|player| receiver_id != Some(player.id))
        .map(|player| player.position.distance(receiver_position))
        .fold(f64::INFINITY, f64::min);
    let teammate_pressure = if nearest_teammate <= TEAMMATE_OCCUPIED_SPACE_HARD_RADIUS_YARDS {
        1.0
    } else {
        ((TEAMMATE_OCCUPIED_SPACE_RADIUS_YARDS - nearest_teammate)
            / (TEAMMATE_OCCUPIED_SPACE_RADIUS_YARDS - TEAMMATE_OCCUPIED_SPACE_HARD_RADIUS_YARDS)
                .max(1e-6))
        .clamp(0.0, 1.0)
    };
    (opponent_openness * (1.0 - teammate_pressure * 0.72)).clamp(0.02, 1.0)
}

fn noisy_pass_target(
    from: Vec2,
    target: Vec2,
    passing_skill: f64,
    pressure: f64,
    distance: f64,
    rng: &mut SeededRandom,
) -> Vec2 {
    noisy_pass_target_with_receiver_openness(
        from,
        target,
        passing_skill,
        pressure,
        distance,
        0.50,
        rng,
    )
}

fn noisy_pass_target_with_receiver_openness(
    from: Vec2,
    target: Vec2,
    passing_skill: f64,
    pressure: f64,
    distance: f64,
    receiver_openness: f64,
    rng: &mut SeededRandom,
) -> Vec2 {
    let dir = (target - from).normalized();
    let lateral = Vec2::new(-dir.y, dir.x);
    let skill_error = 1.0 - passing_skill.clamp(0.05, 0.99);
    let openness = receiver_openness.clamp(0.0, 1.0);
    let receiver_pressure = 1.0 - openness;
    let pressure =
        (pressure * (1.04 - openness * 0.18) + receiver_pressure * 0.22).clamp(0.0, 1.20);
    let openness_relief = 1.0 - openness * 0.14;
    let error_scale = (0.35 + distance * 0.020)
        * (0.35 + skill_error * 1.45 + pressure * 0.75)
        * openness_relief
        * (1.0 + receiver_pressure * 0.28);
    let lateral_error = triangular_sample(rng) * error_scale;
    let weight_error = triangular_sample(rng) * error_scale * 0.42;
    target + lateral * lateral_error + dir * weight_error
}

fn mph_to_yps(mph: f64) -> f64 {
    mph.max(0.0) * 1760.0 / 3600.0
}

fn shot_power_for_skill(shooting_skill: f64) -> f64 {
    (0.82 + shooting_skill.clamp(0.0, 1.0) * 0.18).clamp(0.82, 1.0)
}

fn shot_power_for_finish_skill(finish_skill: f64) -> f64 {
    (0.78 + finish_skill.clamp(0.0, 1.0) * 0.20).clamp(0.78, 0.98)
}

fn shot_speed_yps_from_power(power: f64, skills: &SkillProfile) -> f64 {
    let shooting = ability01(skills.shooting);
    let foot_power = ability01(
        skills
            .right_foot_shot_power
            .max(skills.left_foot_shot_power),
    );
    let strength = ability01(skills.strength);
    let technique_power = (shooting * 0.42 + foot_power * 0.40 + strength * 0.18).clamp(0.0, 1.0);
    let mph = 32.0 + power.clamp(0.0, 1.0) * (20.0 + technique_power * 10.0);
    mph_to_yps(mph.clamp(18.0, 60.0))
}

fn pass_speed_yps_from_power(
    power: f64,
    flight: PassFlight,
    is_cross: bool,
    skills: &SkillProfile,
) -> f64 {
    let passing = ability01(skills.passing_completion_rate);
    let crossing = ability01(skills.crossing_left.max(skills.crossing_right));
    let strength = ability01(skills.strength);
    let skill_power = if is_cross {
        crossing * 0.58 + passing * 0.28 + strength * 0.14
    } else {
        passing * 0.68 + ability01(skills.passing) * 0.20 + strength * 0.12
    }
    .clamp(0.0, 1.0);
    let floor = if flight.is_aerial() {
        14.0
    } else if is_cross {
        10.0
    } else {
        3.0
    };
    let ceiling = if flight.is_aerial() { 42.0 } else { 30.0 };
    let aerial_power_bonus = if flight.is_aerial() { 5.0 } else { 0.0 };
    let mph =
        floor + power.clamp(0.0, 1.0) * (ceiling - floor) + skill_power * 4.0 + aerial_power_bonus;
    mph_to_yps(mph.clamp(3.0, ceiling + 4.0))
}

fn modulated_pass_speed_yps(
    raw_speed_yps: f64,
    from: Vec2,
    target: Vec2,
    flight: PassFlight,
    is_cross: bool,
    passing_skill: f64,
    receiver_openness: f64,
    rng: &mut SeededRandom,
) -> f64 {
    let distance = from.distance(target).max(0.1);
    let openness = receiver_openness.clamp(0.0, 1.0);
    let pressure = 1.0 - openness;
    let base_time = if flight.is_aerial() {
        (0.52 + distance / 38.0).clamp(0.72, 2.35)
    } else if is_cross {
        (0.68 + distance / 31.0).clamp(0.82, 2.65)
    } else {
        (0.58 + distance / 31.0).clamp(0.72, 2.55)
    };
    let timed_time = base_time * (1.0 + openness * 0.08 - pressure * 0.10);
    let desired_speed = (distance / timed_time.max(0.35)).clamp(
        if flight.is_aerial() {
            mph_to_yps(16.0)
        } else {
            mph_to_yps(7.0)
        },
        if flight.is_aerial() {
            mph_to_yps(56.0)
        } else {
            mph_to_yps(44.0)
        },
    );
    let skill = passing_skill.clamp(0.0, 1.0);
    let fit = (0.30 + skill * 0.55 + openness * 0.10).clamp(0.28, 0.94);
    let noise = triangular_sample(rng) * ((1.0 - skill) * 0.12 + pressure * 0.035);
    let cap = if flight.is_aerial() {
        mph_to_yps(58.0)
    } else if is_cross {
        mph_to_yps(48.0)
    } else {
        mph_to_yps(42.0)
    };
    let speed =
        (raw_speed_yps + (desired_speed - raw_speed_yps) * fit) * (1.0 + noise).clamp(0.78, 1.24);
    let aerial_carry_floor = if flight.is_aerial() {
        mph_to_yps((18.0 + (distance / 4.0).clamp(0.0, 18.0)).min(36.0))
    } else {
        mph_to_yps(4.0)
    };
    speed.clamp(aerial_carry_floor, cap)
}

fn shot_curl_probability_for_player(
    skills: &SkillProfile,
    pressure: f64,
    yards_to_goal: f64,
    goal_angle_degrees: f64,
) -> f64 {
    let shooting = ability01(skills.shooting);
    let foot_power = ability01(
        skills
            .right_foot_shot_power
            .max(skills.left_foot_shot_power),
    );
    let flair = ability01(skills.flair_passing);
    let technique = (shooting * 0.52 + foot_power * 0.30 + flair * 0.18).clamp(0.0, 1.0);
    let range_fit = (1.0 - (yards_to_goal - 20.0).abs() / 34.0).clamp(0.10, 1.0);
    let narrow_angle_need = (1.0 - goal_angle_degrees / 42.0).clamp(0.0, 1.0);
    (0.03 + technique * 0.50 + range_fit * 0.10 + narrow_angle_need * 0.08
        - pressure.clamp(0.0, 1.0) * 0.20)
        .clamp(0.02, 0.74)
}

fn pass_curl_probability_for_player(
    skills: &SkillProfile,
    flight: PassFlight,
    is_cross: bool,
    distance: f64,
    pressure: f64,
) -> f64 {
    let passing = ability01(skills.passing_completion_rate);
    let crossing = ability01(skills.crossing_left.max(skills.crossing_right));
    let flair = ability01(skills.flair_passing);
    let technique = if is_cross {
        crossing * 0.52 + passing * 0.26 + flair * 0.22
    } else {
        passing * 0.54 + ability01(skills.passing) * 0.22 + flair * 0.24
    }
    .clamp(0.0, 1.0);
    let distance_fit = (distance / 34.0).clamp(0.12, 1.0);
    let aerial_bonus = if flight.is_aerial() { 0.08 } else { 0.0 };
    (0.025 + technique * 0.46 + distance_fit * 0.10 + aerial_bonus
        - pressure.clamp(0.0, 1.0) * 0.18)
        .clamp(0.01, 0.72)
}

fn pass_curl_probability_for_snapshot(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    player_position: Vec2,
    floor_targets: &[usize],
    aerial_targets: &[usize],
    pressure: f64,
) -> f64 {
    let mut best: f64 = 0.0;
    for (targets, flight) in [
        (floor_targets, PassFlight::Floor),
        (aerial_targets, PassFlight::Aerial),
    ] {
        for target_id in targets.iter().take(3) {
            let Some(target) = snapshot.players.iter().find(|p| p.id == *target_id) else {
                continue;
            };
            let target_position = snapshot
                .player_position(target.id)
                .unwrap_or(target.position);
            let is_cross = pass_would_be_cross(
                player_position,
                target_position,
                player.team,
                snapshot.field_width,
                snapshot.field_length,
            );
            best = best.max(pass_curl_probability_for_player(
                &player.skills,
                flight,
                is_cross,
                player_position.distance(target_position),
                pressure,
            ));
        }
    }
    best.clamp(0.0, 1.0)
}

fn led_pass_target_for_receiver(
    from: Vec2,
    target_position: Vec2,
    target_velocity: Vec2,
    speed_yps: f64,
    skill: f64,
    receiver_openness: f64,
    team: Team,
    field_width: f64,
    field_length: f64,
) -> Vec2 {
    let distance = from.distance(target_position);
    let travel_time = distance / speed_yps.max(1.0);
    let lead = (travel_time * (0.20 + skill.clamp(0.0, 1.0) * 0.55)).clamp(0.0, 1.35);
    let velocity_led = target_position + target_velocity * lead;

    let forward = (target_position.y - from.y) * team.attack_dir();
    let moving_upfield = (target_velocity.y * team.attack_dir()).max(0.0);
    let forward_pass_weight = if forward > 8.0 {
        1.0
    } else if forward > 1.25 {
        0.64
    } else if forward > -1.25 {
        0.28
    } else {
        0.0
    };
    let openness = receiver_openness.clamp(0.0, 1.0);
    let upfield_lead = forward_pass_weight
        * (1.25
            + skill.clamp(0.0, 1.0) * 3.6
            + openness * 2.2
            + moving_upfield * 0.28
            + (distance / 30.0).clamp(0.0, 1.5))
        .clamp(0.0, 8.5);

    (velocity_led + Vec2::new(0.0, team.attack_dir() * upfield_lead))
        .clamp_to_pitch(field_width, field_length)
}

fn pass_into_stride_fit(
    from: Vec2,
    receiver_position: Vec2,
    receiver_velocity: Vec2,
    target_point: Vec2,
    ball_speed_yps: f64,
    team: Team,
) -> f64 {
    let distance = from.distance(target_point).max(0.1);
    let travel_time = (distance / ball_speed_yps.max(1.0)).clamp(0.12, 3.2);
    let receiver_future = receiver_position + receiver_velocity * travel_time * 0.82;
    let receiver_speed = receiver_velocity.len();
    let arrival_tolerance = (2.4 + receiver_speed * 0.90 + travel_time * 1.50).clamp(3.0, 9.5);
    let arrival_fit =
        (1.0 - target_point.distance(receiver_future) / arrival_tolerance).clamp(0.0, 1.0);

    let attack_dir = team.attack_dir();
    let target_forward = (target_point.y - from.y) * attack_dir;
    let receiver_lead = target_point - receiver_position;
    let forward_lead = receiver_lead.y * attack_dir;
    let receiver_forward_speed = (receiver_velocity.y * attack_dir).max(0.0);
    let lead_fit = if target_forward > 3.0 {
        let desired_lead = (receiver_forward_speed * travel_time * 0.70 + 1.4).clamp(1.4, 7.0);
        let run_intent = if receiver_forward_speed >= 0.65 {
            1.0
        } else {
            0.38 + (receiver_forward_speed / 0.65).clamp(0.0, 1.0) * 0.42
        };
        (forward_lead / desired_lead).clamp(0.0, 1.0) * run_intent
    } else if target_forward < -1.25 {
        if forward_lead <= 0.75 {
            0.80
        } else {
            0.36
        }
    } else {
        0.58 + (forward_lead.max(0.0) / 5.0).clamp(0.0, 0.34)
    };

    (arrival_fit * 0.50 + lead_fit * 0.50).clamp(0.0, 1.0)
}

fn pass_into_stride_fit_for_context(context: &SoccerDecisionContext, team: Team) -> f64 {
    let (Some(target_point), Some(receiver_position)) =
        (context.target_point, context.target_player_position)
    else {
        return 0.0;
    };
    let receiver_velocity = context.target_player_velocity.unwrap_or_else(Vec2::zero);
    pass_into_stride_fit(
        context.actor_position,
        receiver_position,
        receiver_velocity,
        target_point,
        context.action_ball_speed_yps,
        team,
    )
}

fn curl_acceleration_for_path(
    from: Vec2,
    initial_target: Vec2,
    final_target: Vec2,
    speed_yps: f64,
    bend_yards: f64,
) -> Vec2 {
    let path = initial_target - from;
    let distance = path.len();
    if distance <= 1e-6 || speed_yps <= 1e-6 || bend_yards.abs() <= 1e-6 {
        return Vec2::zero();
    }
    let dir = path.normalized();
    let lateral = Vec2::new(-dir.y, dir.x);
    let side = dot(final_target - initial_target, lateral).signum();
    if side == 0.0 {
        return Vec2::zero();
    }
    let travel_time = (distance / speed_yps).clamp(0.12, 3.5);
    let magnitude =
        (2.0 * bend_yards.abs() / (travel_time * travel_time)).clamp(0.0, MAX_BALL_CURL_YPS2);
    lateral * side * magnitude
}

fn apply_ball_curl(velocity: Vec2, curl_acceleration: Vec2, dt_seconds: f64) -> Vec2 {
    let speed = velocity.len();
    if speed <= 1e-6 || curl_acceleration.len() <= 1e-6 || dt_seconds <= 0.0 {
        return velocity;
    }
    let dir = velocity.normalized();
    let lateral_accel = curl_acceleration - dir * dot(curl_acceleration, dir);
    let curved = velocity + lateral_accel * dt_seconds;
    if curved.len() <= 1e-6 {
        velocity
    } else {
        curved.normalized() * speed
    }
}

fn decayed_ball_curl(curl_acceleration: Vec2, dt_seconds: f64) -> Vec2 {
    if curl_acceleration.len() <= 1e-6 || dt_seconds <= 0.0 {
        return curl_acceleration;
    }
    let factor = (-BALL_CURL_DECAY_PER_SECOND * dt_seconds).exp();
    let decayed = curl_acceleration * factor;
    if decayed.len() < 0.025 {
        Vec2::zero()
    } else {
        decayed
    }
}

fn player_reaction_time_seconds_from_traits(
    skills: &SkillProfile,
    fatigue: f64,
    role: PlayerRole,
) -> f64 {
    let quickness = ability01(skills.acceleration) * 0.30
        + ability01(skills.defensive_tracking) * 0.22
        + ability01(skills.defending) * 0.18
        + ability01(skills.aggression) * 0.10
        + ability01(skills.vision) * 0.20;
    let role_floor = if role == PlayerRole::Goalkeeper {
        0.18
    } else {
        0.21
    };
    (0.44 - quickness * 0.18 + fatigue.clamp(0.0, 1.0) * 0.13).clamp(role_floor, 0.62)
}

fn goalkeeper_reaction_time_seconds(skills: &SkillProfile, fatigue: f64) -> f64 {
    let keeper_quickness = ability01(skills.goalkeeping) * 0.42
        + ability01(skills.acceleration) * 0.22
        + ability01(skills.defensive_tracking) * 0.16
        + ability01(skills.vision) * 0.20;
    (0.36 - keeper_quickness * 0.16 + fatigue.clamp(0.0, 1.0) * 0.11).clamp(0.16, 0.52)
}

fn shot_block_probability_for_candidate(
    skills: &SkillProfile,
    role: PlayerRole,
    fatigue: f64,
    from: Vec2,
    to: Vec2,
    position: Vec2,
    shot_speed_yps: f64,
    quick_release: bool,
) -> Option<(f64, Vec2, f64, f64, f64)> {
    if role == PlayerRole::Goalkeeper {
        return None;
    }
    let path = to - from;
    let distance = path.len();
    if distance <= 0.35 {
        return None;
    }
    let t = segment_projection_factor(from, to, position);
    if !(0.01..=0.99).contains(&t) {
        return None;
    }
    let block_position = from + path * t;
    let lateral_distance = position.distance(block_position);
    if lateral_distance > SHOT_BLOCK_LANE_RADIUS_YARDS {
        return None;
    }
    let line_score = if lateral_distance <= PLAYER_BODY_RADIUS_YARDS {
        1.0
    } else {
        (1.0 - (lateral_distance - PLAYER_BODY_RADIUS_YARDS)
            / (SHOT_BLOCK_LANE_RADIUS_YARDS - PLAYER_BODY_RADIUS_YARDS))
            .clamp(0.0, 1.0)
    };
    let distance_to_ball = from.distance(position);
    let screen_score = if (SHOT_SCREEN_IDEAL_MIN_YARDS..=SHOT_SCREEN_IDEAL_MAX_YARDS)
        .contains(&distance_to_ball)
    {
        1.0
    } else if distance_to_ball < SHOT_SCREEN_IDEAL_MIN_YARDS {
        (0.62 + distance_to_ball / SHOT_SCREEN_IDEAL_MIN_YARDS * 0.38).clamp(0.62, 1.0)
    } else if distance_to_ball <= 18.0 {
        (1.0 - (distance_to_ball - SHOT_SCREEN_IDEAL_MAX_YARDS) / 15.0 * 0.38).clamp(0.62, 1.0)
    } else {
        (0.62 - (distance_to_ball - 18.0) / 46.0 * 0.30).clamp(0.26, 0.62)
    };
    let arrival_time = distance_to_ball / shot_speed_yps.max(1.0);
    let reaction_time = player_reaction_time_seconds_from_traits(skills, fatigue, role);
    let reaction_factor = if arrival_time >= reaction_time {
        1.0
    } else {
        (0.62 + arrival_time / reaction_time.max(1e-6) * 0.38).clamp(0.62, 1.0)
    };
    let readiness = (0.88
        + ability01(skills.defending) * 0.14
        + ability01(skills.defensive_tracking) * 0.09
        + ability01(skills.aggression) * 0.05
        + ability01(skills.strength) * 0.04
        - fatigue.clamp(0.0, 1.0) * 0.14)
        .clamp(0.68, 1.16);
    let quick_release_factor = if quick_release {
        SHOT_BLOCK_QUICK_RELEASE_MULTIPLIER
    } else {
        1.0
    };
    let probability = (SHOT_BLOCK_DIRECT_PROBABILITY
        * line_score
        * (0.72 + screen_score * 0.28)
        * reaction_factor
        * readiness
        * quick_release_factor)
        .clamp(0.0, 0.92);
    (probability >= 0.025).then_some((
        probability,
        block_position,
        distance_to_ball,
        lateral_distance,
        screen_score,
    ))
}

fn combine_shot_block_assessments(
    mut assessments: Vec<ShotBlockAssessment>,
) -> Option<ShotBlockAssessment> {
    if assessments.is_empty() {
        return None;
    }
    assessments.sort_by(|a, b| {
        b.probability
            .partial_cmp(&a.probability)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    let combined = (1.0
        - assessments
            .iter()
            .map(|assessment| 1.0 - assessment.probability.clamp(0.0, 1.0))
            .product::<f64>())
    .clamp(0.0, 0.96);
    let mut best = assessments.remove(0);
    best.probability = combined;
    Some(best)
}

fn shot_block_assessment_for_agents(
    players: &[PlayerAgent],
    from: Vec2,
    to: Vec2,
    attacking_team: Team,
    shot_speed_yps: f64,
    quick_release: bool,
) -> Option<ShotBlockAssessment> {
    let assessments = players
        .iter()
        .filter(|player| player.team == attacking_team.other())
        .filter_map(|player| {
            let (probability, block_position, distance_to_ball, lateral_distance, screen_score) =
                shot_block_probability_for_candidate(
                    &player.skills,
                    player.role,
                    player.fatigue,
                    from,
                    to,
                    player.position,
                    shot_speed_yps,
                    quick_release,
                )?;
            Some(ShotBlockAssessment {
                blocker_id: player.id,
                defending_team: player.team,
                block_position,
                probability,
                distance_to_ball,
                lateral_distance,
                screen_score,
            })
        })
        .collect::<Vec<_>>();
    combine_shot_block_assessments(assessments)
}

fn shot_sightline_screen_probability_for_agents(
    players: &[PlayerAgent],
    from: Vec2,
    to: Vec2,
    attacking_team: Team,
    shot_speed_yps: f64,
    quick_release: bool,
) -> f64 {
    let clear_probability = players
        .iter()
        .filter(|player| {
            player.team == attacking_team.other() && player.role != PlayerRole::Goalkeeper
        })
        .filter_map(|player| {
            shot_block_probability_for_candidate(
                &player.skills,
                player.role,
                player.fatigue,
                from,
                to,
                player.position,
                shot_speed_yps,
                quick_release,
            )
            .map(|(probability, _, _, _, _)| 1.0 - probability.clamp(0.0, 1.0))
        })
        .product::<f64>();
    (1.0 - clear_probability).clamp(0.0, 1.0)
}

fn shot_goalmouth_target_points(
    field_width: f64,
    field_length: f64,
    goal_width: f64,
    attacking_team: Team,
) -> [Vec2; 5] {
    let goal_y = attacking_team.goal_y(field_length);
    let center_x = field_width * 0.5;
    let half_width = goal_width.max(1.0) * 0.5;
    SHOT_GOALMOUTH_TARGET_FRACTIONS.map(|fraction| {
        Vec2::new(
            (center_x + half_width * fraction).clamp(0.0, field_width),
            goal_y,
        )
    })
}

fn shot_block_assessment_for_snapshot_target(
    snapshot: &WorldSnapshot,
    from: Vec2,
    target: Vec2,
    attacking_team: Team,
    shot_speed_yps: f64,
    quick_release: bool,
) -> Option<ShotBlockAssessment> {
    let assessments = snapshot
        .players
        .iter()
        .filter(|player| player.team == attacking_team.other())
        .filter_map(|player| {
            let position = snapshot
                .player_position(player.id)
                .unwrap_or(player.position);
            let (probability, block_position, distance_to_ball, lateral_distance, screen_score) =
                shot_block_probability_for_candidate(
                    &player.skills,
                    player.role,
                    player.fatigue,
                    from,
                    target,
                    position,
                    shot_speed_yps,
                    quick_release,
                )?;
            Some(ShotBlockAssessment {
                blocker_id: player.id,
                defending_team: player.team,
                block_position,
                probability,
                distance_to_ball,
                lateral_distance,
                screen_score,
            })
        })
        .collect::<Vec<_>>();
    combine_shot_block_assessments(assessments)
}

fn shot_block_assessment_for_snapshot(
    snapshot: &WorldSnapshot,
    from: Vec2,
    attacking_team: Team,
    shot_speed_yps: f64,
    quick_release: bool,
) -> Option<ShotBlockAssessment> {
    let targets = shot_goalmouth_target_points(
        snapshot.field_width,
        snapshot.field_length,
        snapshot.goal_width,
        attacking_team,
    );
    let mut best: Option<ShotBlockAssessment> = None;
    for target in targets {
        match shot_block_assessment_for_snapshot_target(
            snapshot,
            from,
            target,
            attacking_team,
            shot_speed_yps,
            quick_release,
        ) {
            None => return None,
            Some(assessment)
                if best
                    .as_ref()
                    .map(|best| assessment.probability < best.probability)
                    .unwrap_or(true) =>
            {
                best = Some(assessment);
            }
            Some(_) => {}
        }
    }
    best
}

fn shot_miss_window_yards(
    goal_width: f64,
    shooting_skill: f64,
    pressure: f64,
    yards_to_goal: f64,
) -> f64 {
    let skill_error = 1.0 - shooting_skill.clamp(0.05, 0.99);
    let pressure = pressure.clamp(0.0, 1.0);
    goal_width * (0.28 + skill_error * 0.80 + pressure * 0.48)
        + yards_to_goal.max(0.0) * 0.018 * (0.45 + skill_error)
}

fn triangular_abs_within_probability(bound: f64, window: f64) -> f64 {
    if bound <= 0.0 || window <= 0.0 {
        return 0.0;
    }
    if bound >= window {
        return 1.0;
    }
    let ratio = (bound / window).clamp(0.0, 1.0);
    (2.0 * ratio - ratio * ratio).clamp(0.0, 1.0)
}

fn shot_on_frame_probability(
    goal_width: f64,
    shooting_skill: f64,
    pressure: f64,
    yards_to_goal: f64,
    goal_angle_degrees: f64,
    shot_block_probability: f64,
) -> f64 {
    let miss_window = shot_miss_window_yards(goal_width, shooting_skill, pressure, yards_to_goal);
    let geometry_probability = triangular_abs_within_probability(goal_width * 0.5, miss_window);
    let angle_factor = (0.45 + (goal_angle_degrees / 36.0).clamp(0.0, 1.0) * 0.55).clamp(0.45, 1.0);
    let distance_factor = (1.08 - (yards_to_goal.max(0.0) / 52.0).powi(2) * 0.25).clamp(0.70, 1.0);
    let block_factor = (1.0 - shot_block_probability.clamp(0.0, 1.0) * 0.74).clamp(0.20, 1.0);
    (geometry_probability * angle_factor * distance_factor * block_factor).clamp(0.0, 1.0)
}

fn noisy_shot_target_x(
    goal_center_x: f64,
    goal_width: f64,
    shooting_skill: f64,
    pressure: f64,
    yards_to_goal: f64,
    rng: &mut SeededRandom,
) -> f64 {
    let miss_window = shot_miss_window_yards(goal_width, shooting_skill, pressure, yards_to_goal);
    goal_center_x + triangular_sample(rng) * miss_window
}

fn goalkeeper_save_probability_from_traits(
    skills: &SkillProfile,
    keeper_position: Vec2,
    keeper_velocity: Vec2,
    keeper_fatigue: f64,
    shooter_position: Vec2,
    shot_crossing: Vec2,
    shot_speed: f64,
    goal_width: f64,
    sightline_screen_probability: f64,
) -> f64 {
    let reaction = ability01(skills.goalkeeping) * 0.48
        + ability01(skills.defending) * 0.18
        + ability01(skills.first_touch) * 0.20
        + ability01(skills.acceleration) * 0.14;
    let reaction_time = goalkeeper_reaction_time_seconds(skills, keeper_fatigue);
    let shot_distance = shooter_position.distance(shot_crossing);
    let shot_travel_time = shot_distance / shot_speed.max(1.0);
    let available_move_time = (shot_travel_time - reaction_time).max(0.0);
    let acceleration_reach = 0.5
        * acceleration_yps2_from_score(skills.acceleration)
        * available_move_time
        * available_move_time;
    let velocity_reach = keeper_velocity.len() * available_move_time * 0.34;
    let height_reach = (height_inches_from_score(skills.height) - 66.0).max(0.0) / 36.0;
    let reachable_radius =
        1.05 + reaction * 0.85 + acceleration_reach + velocity_reach + height_reach;
    let distance_to_shot = keeper_position.distance(shot_crossing);
    let reach_gap = (distance_to_shot - reachable_radius).max(0.0);
    let reach_penalty = (reach_gap / (goal_width * 0.72)).clamp(0.0, 1.5);
    let speed_penalty = (shot_speed / mph_to_yps(60.0)).clamp(0.0, 1.0) * 0.12;
    let reaction_penalty = if shot_travel_time <= reaction_time {
        ((reaction_time - shot_travel_time) / reaction_time.max(1e-6)).clamp(0.0, 1.0) * 0.22
    } else {
        0.0
    };
    let line_t = segment_projection_factor(shooter_position, shot_crossing, keeper_position);
    let lateral_to_lane =
        segment_distance_to_point(shooter_position, shot_crossing, keeper_position);
    let angle_cut_score = if (0.05..=0.92).contains(&line_t) {
        (1.0 - lateral_to_lane / (goal_width * 0.62).max(0.1)).clamp(0.0, 1.0)
            * (1.0 - line_t * 0.72).clamp(0.20, 1.0)
    } else {
        0.0
    };
    let rush_dir = (shooter_position - keeper_position).normalized();
    let rush_speed = dot(keeper_velocity, rush_dir).max(0.0);
    let rush_bonus =
        (rush_speed / top_speed_yps_from_score(skills.top_speed).max(1.0)).clamp(0.0, 1.0) * 0.08;
    let clean_sightline = (1.0 - sightline_screen_probability.clamp(0.0, 1.0)).clamp(0.0, 1.0);
    let distance_save_bonus = ((shot_distance - 18.0) / 42.0).clamp(0.0, 1.0) * 0.12;
    let clear_long_shot_bonus =
        clean_sightline * ((shot_distance - 24.0) / 38.0).clamp(0.0, 1.0) * 0.10;
    let screened_penalty = sightline_screen_probability.clamp(0.0, 1.0) * 0.16;
    let raw_save_probability = (0.34
        + reaction * 0.78
        + angle_cut_score * 0.18
        + rush_bonus
        + distance_save_bonus
        + clear_long_shot_bonus
        - reach_penalty * 0.24
        - speed_penalty
        - reaction_penalty
        - screened_penalty)
        .clamp(0.12, 0.94);
    let long_clear_fit =
        (clean_sightline * ((shot_distance - 24.0) / 38.0).clamp(0.0, 1.0)).clamp(0.0, 1.0);
    let contextual_cap = (0.50 + long_clear_fit * (GOALKEEPER_CLEAR_SIGHTLINE_SAVE_CAP - 0.50)
        - sightline_screen_probability.clamp(0.0, 1.0) * 0.08)
        .clamp(0.36, GOALKEEPER_CLEAR_SIGHTLINE_SAVE_CAP);
    (raw_save_probability * (0.50 + long_clear_fit * 0.24)).clamp(0.0, contextual_cap)
}

fn goalkeeper_save_probability(
    keeper: &PlayerAgent,
    shooter_position: Vec2,
    shot_crossing: Vec2,
    shot_speed: f64,
    goal_width: f64,
    sightline_screen_probability: f64,
) -> f64 {
    goalkeeper_save_probability_from_traits(
        &keeper.skills,
        keeper.position,
        keeper.velocity,
        keeper.fatigue,
        shooter_position,
        shot_crossing,
        shot_speed,
        goal_width,
        sightline_screen_probability,
    )
}

fn goalkeeper_catch_probability_after_save(
    keeper: &PlayerAgent,
    shooter_position: Vec2,
    shot_crossing: Vec2,
    shot_speed: f64,
    goal_width: f64,
    sightline_screen_probability: f64,
) -> f64 {
    let shot_distance = shooter_position.distance(shot_crossing);
    let clean_sightline = (1.0 - sightline_screen_probability.clamp(0.0, 1.0)).clamp(0.0, 1.0);
    let handling = (ability01(keeper.skills.goalkeeping) * 0.58
        + ability01(keeper.skills.first_touch) * 0.42)
        .clamp(0.0, 1.0);
    let distance_fit = ((shot_distance - 18.0) / 42.0).clamp(0.0, 1.0);
    let high_speed_fit = (shot_speed / mph_to_yps(60.0)).clamp(0.0, 1.25);
    let near_keeper_fit = (1.0
        - keeper.position.distance(shot_crossing) / (goal_width * 0.72).max(0.1))
    .clamp(0.0, 1.0);
    let short_medium_fit = if shot_distance <= 32.0 {
        (1.0 - (shot_distance - 18.0).abs() / 22.0).clamp(0.0, 1.0)
    } else {
        0.0
    };
    (0.20 + handling * 0.30 + clean_sightline * 0.18 + distance_fit * 0.24
        - high_speed_fit * 0.18
        - short_medium_fit * near_keeper_fit * 0.28
        - sightline_screen_probability.clamp(0.0, 1.0) * 0.16)
        .clamp(0.08, 0.92)
}

fn shot_beat_goalkeeper_probability_for_snapshot(
    snapshot: &WorldSnapshot,
    player: &PlayerSnapshot,
    player_position: Vec2,
) -> f64 {
    let Some(keeper_id) = snapshot.goalkeeper_for(player.team.other()) else {
        return 0.35;
    };
    let Some(keeper) = snapshot.players.iter().find(|p| p.id == keeper_id) else {
        return 0.35;
    };
    let keeper_position = snapshot
        .player_position(keeper_id)
        .unwrap_or(keeper.position);
    let goal_y = player.team.goal_y(snapshot.field_length);
    let goal_center_x = snapshot.field_width * 0.5;
    let half_width = snapshot.goal_width * 0.5;
    let keeper_opposite_x = if keeper_position.x <= goal_center_x {
        goal_center_x + half_width * 0.72
    } else {
        goal_center_x - half_width * 0.72
    };
    let shooter_angle_x = if player_position.x <= goal_center_x {
        goal_center_x + half_width * 0.38
    } else {
        goal_center_x - half_width * 0.38
    };
    let crossing_x = (keeper_opposite_x * 0.72 + shooter_angle_x * 0.28)
        .clamp(goal_center_x - half_width, goal_center_x + half_width);
    let shot_crossing = Vec2::new(crossing_x, goal_y);
    let shooting_skill = ability01(player.skills.shooting);
    let foot_power = ability01(
        player
            .skills
            .right_foot_shot_power
            .max(player.skills.left_foot_shot_power),
    );
    let shot_power = shot_power_for_skill(shooting_skill * 0.72 + foot_power * 0.28);
    let shot_speed = shot_speed_yps_from_power(shot_power.clamp(0.0, 1.0), &player.skills);
    let save_probability = goalkeeper_save_probability_from_traits(
        &keeper.skills,
        keeper_position,
        keeper.velocity,
        keeper.fatigue,
        player_position,
        shot_crossing,
        shot_speed,
        snapshot.goal_width,
        0.0,
    );
    (1.0 - save_probability).clamp(0.0, 1.0)
}

fn goalkeeper_for_players(players: &[PlayerAgent], team: Team) -> Option<usize> {
    players
        .iter()
        .find(|player| player.team == team && player.role == PlayerRole::Goalkeeper)
        .map(|player| player.id)
}

fn nearest_ball_controller_for(
    current_tick: u64,
    ball_pos: Vec2,
    ball_velocity: Vec2,
    players: &[PlayerAgent],
    pending_pass: Option<&PendingPass>,
    loose_long_ball_team: Option<Team>,
    same_tick_long_ball_launcher: Option<usize>,
    ball_altitude_yards: f64,
    rng: &mut SeededRandom,
) -> Option<(usize, Team)> {
    nearest_ball_controller_for_segment(
        current_tick,
        ball_pos,
        ball_pos,
        ball_velocity,
        players,
        pending_pass,
        loose_long_ball_team,
        same_tick_long_ball_launcher,
        ball_altitude_yards,
        rng,
    )
    .map(|(id, team, _)| (id, team))
}

fn nearest_ball_controller_for_segment(
    current_tick: u64,
    previous_ball_pos: Vec2,
    ball_pos: Vec2,
    ball_velocity: Vec2,
    players: &[PlayerAgent],
    pending_pass: Option<&PendingPass>,
    loose_long_ball_team: Option<Team>,
    same_tick_long_ball_launcher: Option<usize>,
    ball_altitude_yards: f64,
    rng: &mut SeededRandom,
) -> Option<(usize, Team, Vec2)> {
    let ball_speed = ball_velocity.len();
    let ball_segment = ball_pos - previous_ball_pos;
    let ball_segment_len = ball_segment.len();
    let mut candidates = Vec::new();
    for p in players {
        if same_tick_long_ball_launcher == Some(p.id) {
            continue;
        }
        if let Some(pass) = pending_pass {
            if current_tick <= pass.launch_tick && p.id == pass.from {
                continue;
            }
        }
        let control_point = if ball_segment_len > 1e-6 {
            previous_ball_pos
                + ball_segment * segment_projection_factor(previous_ball_pos, ball_pos, p.position)
        } else {
            ball_pos
        };
        let mut player_control_position = p.position;
        let mut control_radius = PLAYER_CONTROL_RADIUS_YARDS
            + ability01(p.skills.first_touch) * 0.48
            + (1.0 - (ball_speed / 18.0).clamp(0.0, 1.0)) * 0.24;
        let mut aerial_score_bonus = 0.0;
        let mut pass_reception_score_bonus = 0.0;
        if let Some(pass) = pending_pass {
            let is_target = pass.target == Some(p.id);
            let progress = pass_progress_along_path(pass, control_point);
            let openness = pass.receiver_openness.clamp(0.0, 1.0);
            if is_target {
                if let Some(receiver_position) = pass.receiver_position_at_launch {
                    let route = pass.intended_target - receiver_position;
                    let route_len = route.len();
                    if route_len > 1e-6 {
                        let travel_time =
                            (pass.distance_yards / pass.launch_speed_yps.max(1.0)).clamp(0.12, 3.2);
                        let route_availability = ((openness - 0.25) / 0.75).clamp(0.0, 1.0);
                        let route_speed = player_top_speed_yps(p.role, &p.skills)
                            * fatigue_speed_factor(p.skills.stamina, p.fatigue)
                            * if pass.flight.is_aerial() { 0.78 } else { 0.72 }
                            * route_availability;
                        let reachable =
                            (route_speed * travel_time * progress).clamp(0.0, route_len);
                        player_control_position =
                            receiver_position + route.normalized() * reachable;
                    }
                }
            }
            let same_tick_launch = current_tick <= pass.launch_tick && progress < 0.12;
            if same_tick_launch && p.team == pass.team && !is_target {
                control_radius *= 0.35;
            }
            if is_target {
                control_radius *= 0.48 + openness * 0.62;
                pass_reception_score_bonus += -0.18 + openness * 0.50 + pass.passer_skill * 0.16;
            } else if p.team == pass.team {
                pass_reception_score_bonus -= 0.08;
            } else {
                let marked_pressure = 1.0 - openness;
                control_radius *= 1.00 + marked_pressure * 0.12;
                pass_reception_score_bonus += marked_pressure * 0.48;
            }
            if pass.flight.is_aerial() {
                let landing_distance = control_point.distance(pass.intended_target);
                let interception_multiplier = aerial_interception_multiplier(pass, control_point);
                if !is_target && landing_distance > 7.5 {
                    control_radius *= if p.team == pass.team { 0.70 } else { 0.55 };
                }
                let aerial_duel = aerial_duel_skill_from_agent(p);
                control_radius += aerial_duel * 0.45;
                aerial_score_bonus += aerial_duel * 0.72;
                if p.team != pass.team {
                    control_radius +=
                        PLAYER_CONTROL_RADIUS_YARDS * (interception_multiplier - 1.0) * 0.26;
                    aerial_score_bonus += (interception_multiplier - 1.0) * 0.34;
                    aerial_score_bonus += if landing_distance <= 8.5 { 0.62 } else { 0.28 };
                }
            }
            if p.team != pass.team {
                let facing_multiplier = player_facing_ball_control_multiplier(p, control_point);
                control_radius *= facing_multiplier;
                pass_reception_score_bonus *= facing_multiplier;
                aerial_score_bonus *= facing_multiplier;
            }
        } else if let Some(long_ball_team) = loose_long_ball_team {
            if ball_altitude_yards > 0.02 || ball_speed >= 8.0 {
                let airborne = ball_altitude_yards > 0.02;
                if airborne {
                    let aerial_duel = aerial_duel_skill_from_agent(p);
                    let altitude_bonus = (ball_altitude_yards / 0.22).clamp(0.0, 1.0);
                    control_radius += aerial_duel * (0.34 + altitude_bonus * 0.24);
                    aerial_score_bonus += aerial_duel * (0.58 + altitude_bonus * 0.18);
                } else {
                    control_radius += ability01(p.skills.first_touch) * 0.18;
                    pass_reception_score_bonus += ability01(p.skills.dribbling) * 0.08;
                }
                if p.team == long_ball_team {
                    pass_reception_score_bonus += ability01(p.skills.first_touch) * 0.12;
                } else {
                    let defensive_duel_bonus = ability01(p.skills.defending) * 0.18
                        + ability01(p.skills.aggression) * 0.12;
                    if airborne {
                        aerial_score_bonus += defensive_duel_bonus;
                    } else {
                        pass_reception_score_bonus += defensive_duel_bonus * 0.72;
                    }
                    let facing_multiplier = player_facing_ball_control_multiplier(p, control_point);
                    control_radius *= facing_multiplier;
                    aerial_score_bonus *= facing_multiplier;
                    pass_reception_score_bonus *= facing_multiplier;
                }
            }
        }
        let dist = player_control_position.distance(control_point);
        if dist > control_radius {
            continue;
        }
        let to_ball = (control_point - player_control_position).normalized();
        let closing_speed = dot(p.velocity - ball_velocity, to_ball).clamp(-8.0, 8.0);
        let score = -dist * 1.45
            + ability01(p.skills.first_touch) * 0.72
            + ability01(p.skills.aggression) * 0.18
            + closing_speed * 0.055
            + pass_reception_score_bonus
            + aerial_score_bonus;
        candidates.push((p.id, p.team, score, control_point));
    }
    sample_control_candidate_with_point(&candidates, rng)
}

fn triangular_sample(rng: &mut SeededRandom) -> f64 {
    rng.next_float() + rng.next_float() - 1.0
}

fn boundary_crossing_fraction(start: f64, end: f64, lower: f64, upper: f64) -> Option<f64> {
    let boundary = if end < lower {
        lower
    } else if end > upper {
        upper
    } else {
        return None;
    };
    let delta = end - start;
    if delta.abs() <= 1e-9 {
        return Some(1.0);
    }
    Some(((boundary - start) / delta).clamp(0.0, 1.0))
}

pub fn segment_distance_to_point(a: Vec2, b: Vec2, p: Vec2) -> f64 {
    let t = segment_projection_factor(a, b, p);
    let projection = a + (b - a) * t;
    p.distance(projection)
}

fn segment_projection_factor(a: Vec2, b: Vec2, p: Vec2) -> f64 {
    let ab = b - a;
    let denom = ab.x * ab.x + ab.y * ab.y;
    if denom <= 1e-12 {
        return 0.0;
    }
    let ap = p - a;
    ((ap.x * ab.x + ap.y * ab.y) / denom).clamp(0.0, 1.0)
}

fn dot(a: Vec2, b: Vec2) -> f64 {
    a.x * b.x + a.y * b.y
}

fn deterministic_separation_normal(a_id: usize, b_id: usize) -> Vec2 {
    let seed = ((a_id as u64 + 1) * 1_103_515_245) ^ ((b_id as u64 + 7) * 12_345);
    let angle = (seed % 6283) as f64 / 1000.0;
    Vec2::new(angle.cos(), angle.sin()).normalized()
}

fn sample_control_candidate_with_point(
    candidates: &[(usize, Team, f64, Vec2)],
    rng: &mut SeededRandom,
) -> Option<(usize, Team, Vec2)> {
    if candidates.is_empty() {
        return None;
    }
    if candidates.len() == 1 {
        let (id, team, _, point) = candidates[0];
        return Some((id, team, point));
    }

    let max_score = candidates
        .iter()
        .map(|(_, _, score, _)| *score)
        .fold(f64::NEG_INFINITY, f64::max);
    let temperature = 0.48;
    let weights = candidates
        .iter()
        .map(|(_, _, score, _)| ((*score - max_score) / temperature).exp())
        .collect::<Vec<_>>();
    let total = weights.iter().sum::<f64>();
    if total <= 1e-12 || !total.is_finite() {
        let (id, team, _, point) = candidates[0];
        return Some((id, team, point));
    }

    let mut draw = rng.next_float() * total;
    for ((id, team, _, point), weight) in candidates.iter().zip(weights.iter()) {
        draw -= *weight;
        if draw <= 0.0 {
            return Some((*id, *team, *point));
        }
    }
    candidates
        .last()
        .map(|(id, team, _, point)| (*id, *team, *point))
}

fn sample_control_candidate(
    candidates: &[(usize, Team, f64)],
    rng: &mut SeededRandom,
) -> Option<(usize, Team)> {
    if candidates.is_empty() {
        return None;
    }
    if candidates.len() == 1 {
        let (id, team, _) = candidates[0];
        return Some((id, team));
    }

    let max_score = candidates
        .iter()
        .map(|(_, _, score)| *score)
        .fold(f64::NEG_INFINITY, f64::max);
    let temperature = 0.48;
    let weights = candidates
        .iter()
        .map(|(_, _, score)| ((*score - max_score) / temperature).exp())
        .collect::<Vec<_>>();
    let total = weights.iter().sum::<f64>();
    if total <= 1e-12 || !total.is_finite() {
        let (id, team, _) = candidates[0];
        return Some((id, team));
    }

    let mut draw = rng.next_float() * total;
    for ((id, team, _), weight) in candidates.iter().zip(weights.iter()) {
        draw -= *weight;
        if draw <= 0.0 {
            return Some((*id, *team));
        }
    }
    candidates.last().map(|(id, team, _)| (*id, *team))
}

fn restart_kind_action(kind: BallRestartKind) -> &'static str {
    match kind {
        BallRestartKind::ThrowIn => "throw-in",
        BallRestartKind::GoalKick => "goal-kick",
        BallRestartKind::CornerKick => "corner-kick",
        BallRestartKind::FreeKick => "free-kick",
    }
}

fn restart_kind_label(kind: BallRestartKind) -> &'static str {
    match kind {
        BallRestartKind::ThrowIn => "throw-in",
        BallRestartKind::GoalKick => "goal kick",
        BallRestartKind::CornerKick => "corner",
        BallRestartKind::FreeKick => "free kick",
    }
}

fn learned_action_label_is_legal(action: &str, snapshot: &WorldSnapshot, player_id: usize) -> bool {
    let action = normalize_soccer_action_label(action);
    let Some(player) = snapshot.players.iter().find(|p| p.id == player_id) else {
        return false;
    };
    let observation = snapshot.observation_for(player_id);
    let held_restart = held_restart_action_for_snapshot(snapshot, player_id);
    if let Some(restart_label) = held_restart {
        return match restart_label {
            "throw-in" => is_pass_like_action(action),
            "corner-kick" => is_pass_like_action(action) || matches!(action, "shoot"),
            "goal-kick" | "kickoff" => is_pass_like_action(action),
            "free-kick" => is_pass_like_action(action) || matches!(action, "shoot"),
            _ => false,
        };
    }
    match action {
        "shoot" => {
            observation.has_ball && shot_decision_is_qualified_for_role(&observation, player.role)
        }
        "pass" => observation.has_ball && snapshot.best_visible_pass_target(player_id).is_some(),
        "killer-pass" => {
            observation.has_ball
                && !goal_attack_shot_is_required(&observation, player.role)
                && snapshot
                    .killer_pass_target_for(
                        player_id,
                        &snapshot.ranked_visible_pass_targets(player_id, 5),
                    )
                    .is_some()
        }
        "aerial-pass" => {
            observation.has_ball && snapshot.best_aerial_pass_target(player_id).is_some()
        }
        "flank-low-cross" => {
            let player_position = snapshot
                .player_position(player_id)
                .unwrap_or(player.position);
            observation.has_ball
                && flank_cross_context_is_legal(&observation, player_position, snapshot.field_width)
                && !goal_attack_shot_is_required(&observation, player.role)
                && !snapshot
                    .ranked_visible_pass_targets(player_id, 1)
                    .is_empty()
        }
        "flank-high-cross" => {
            let player_position = snapshot
                .player_position(player_id)
                .unwrap_or(player.position);
            observation.has_ball
                && flank_cross_context_is_legal(&observation, player_position, snapshot.field_width)
                && !goal_attack_shot_is_required(&observation, player.role)
                && !snapshot
                    .ranked_visible_aerial_pass_targets(player_id, 1)
                    .is_empty()
        }
        "clearance" => observation.has_ball && observation.perceived_pressure >= 0.35,
        "route-one" => {
            observation.has_ball && observation.yards_to_own_goal < observation.yards_to_goal
        }
        "first-time-shot" | "first-time-header" => {
            observation.has_ball
                && observation.first_touch_available
                && first_time_shot_decision_is_qualified_for_role(&observation, player.role)
        }
        "first-time-pass" => {
            observation.has_ball
                && observation.first_touch_available
                && snapshot.best_visible_pass_target(player_id).is_some()
        }
        "control-touch" => observation.has_ball && observation.first_touch_available,
        "dribble" | "carry-forward" => observation.has_ball,
        "carry-out-left" | "carry-out-right" => {
            observation.has_ball && !goal_approach_forces_goalmouth_carry(&observation, player.role)
        }
        "protect-ball" => {
            observation.has_ball
                && (observation.nearest_opponent_distance <= 5.2
                    || observation.perceived_pressure >= 0.24)
        }
        "hold-up-flank" => {
            observation.has_ball
                && player.role == PlayerRole::Forward
                && observation.yards_to_goal > STRIKER_HOLD_UP_MIN_GOAL_DISTANCE_YARDS
                && snapshot
                    .striker_hold_up_flank_target_for(player_id)
                    .is_some()
        }
        "left-cut" | "right-cut" | "nutmeg" | "fake-left-cut-right" | "fake-right-cut-left" => {
            observation.has_ball && observation.nearest_opponent_distance <= 5.6
        }
        "side-step" => {
            observation.has_ball
                && observation.nearest_opponent_distance <= 4.6
                && observation.perceived_pressure >= 0.28
        }
        "defend" => snapshot.controlled_possession_team() == Some(player.team.other()),
        "recover" => snapshot.controlled_possession_team().is_none(),
        "tackle" => snapshot.ball.holder.is_some_and(|holder| {
            snapshot
                .players
                .iter()
                .find(|p| p.id == holder)
                .is_some_and(|holder_player| {
                    if holder_player.team != player.team.other() {
                        return false;
                    }
                    let player_position = snapshot.player_snapshot_position(player);
                    let holder_position = snapshot.player_snapshot_position(holder_player);
                    let my_depth = snapshot.depth_from_own_goal_y(player.team, player_position.y);
                    let holder_depth =
                        snapshot.depth_from_own_goal_y(player.team, holder_position.y);
                    my_depth <= holder_depth + 0.85
                        && player_position.distance(holder_position) <= 1.85
                })
        }),
        "check-to-ball" => {
            !observation.has_ball
                && snapshot.controlled_possession_team() == Some(player.team)
                && snapshot
                    .check_to_ball_target_for(player_id, player.home_position)
                    .is_some()
        }
        "run-in-behind" => {
            !observation.has_ball
                && snapshot.controlled_possession_team() == Some(player.team)
                && snapshot.in_behind_run_target_for(player_id).is_some()
        }
        "wide-outlet" => {
            !observation.has_ball
                && snapshot.controlled_possession_team() == Some(player.team)
                && snapshot
                    .wide_possession_outlet_target_for(player_id, player.home_position)
                    .is_some()
        }
        "shot-creation-run" | "overlap-run" | "support-push-up" | "support-screen"
        | "support-shape" | "support-roam" => {
            !observation.has_ball && snapshot.controlled_possession_team() == Some(player.team)
        }
        "space" => !observation.has_ball,
        "hold" => false,
        "human-move" => false,
        _ => false,
    }
}

pub fn shot_lane_is_clear(snapshot: &WorldSnapshot, player_id: usize) -> bool {
    let Some(player) = snapshot.players.iter().find(|p| p.id == player_id) else {
        return false;
    };
    snapshot.shot_lane_clear(player.position, player.team, 3.0)
}

fn approach_velocity(current: Vec2, desired: Vec2, accel: f64, dt: f64) -> Vec2 {
    let delta = desired - current;
    let max_delta = accel * dt;
    if delta.len() <= max_delta {
        desired
    } else {
        current + delta.normalized() * max_delta
    }
}

fn classify_movement_gait(team: Team, to_target: Vec2, sprint: bool) -> MovementGait {
    let distance = to_target.len();
    if distance < 0.18 {
        return MovementGait::Stand;
    }

    let dir = to_target.normalized();
    let forwardness = dir.dot(Vec2::new(0.0, team.attack_dir()));
    let lateral = dir.x.abs();
    let vertical = dir.y.abs();
    let retreating = forwardness < -0.34;
    let lateral_dominant = lateral > vertical * 1.18;

    if retreating {
        if distance <= 2.4 {
            MovementGait::BackWalk
        } else if distance <= 5.2 {
            MovementGait::BackJog
        } else {
            MovementGait::BackSkip
        }
    } else if sprint && distance > 1.0 {
        MovementGait::Sprint
    } else if lateral_dominant && distance > 0.75 && distance <= 7.0 {
        MovementGait::SideStep
    } else if distance <= 1.8 {
        MovementGait::Walk
    } else if distance <= 4.6 {
        MovementGait::Skip
    } else if distance <= 10.0 {
        MovementGait::Jog
    } else {
        MovementGait::Run
    }
}

fn ball_velocity_after_resistance(
    velocity: Vec2,
    dt_seconds: f64,
    linear_drag_per_tick: f64,
    air_resistance: f64,
    grass_resistance_yps2: f64,
    altitude_yards: f64,
) -> Vec2 {
    let speed = velocity.len();
    if speed <= 0.0 || dt_seconds <= 0.0 {
        return velocity;
    }
    let linear_drag = linear_drag_per_tick.clamp(0.0, 0.95);
    let reference_dt = DEFAULT_DT_SECONDS.max(1e-6);
    let linear_retention = (1.0 - linear_drag).powf((dt_seconds / reference_dt).max(0.0));
    let linear_speed_loss = speed * (1.0 - linear_retention);
    let air_deceleration = air_resistance.clamp(0.0, 0.10) * speed * speed;
    let rolling_contact = if altitude_yards <= BALL_ROLLING_ALTITUDE_YARDS {
        1.0
    } else {
        (1.0 - (altitude_yards - BALL_ROLLING_ALTITUDE_YARDS) / 0.18).clamp(0.0, 1.0)
    };
    let low_speed_grass_bonus = (1.0 - (speed / 12.0).clamp(0.0, 1.0)) * 0.62;
    let high_speed_turf_shear = ((speed - 12.0) / 24.0).clamp(0.0, 1.0).powi(2) * 0.42;
    let skidding_grass_bonus = ((speed - 28.0) / 24.0).clamp(0.0, 1.0) * 0.22;
    let grass_deceleration = grass_resistance_yps2.clamp(0.0, 5.0)
        * (1.0 + low_speed_grass_bonus + high_speed_turf_shear + skidding_grass_bonus)
        * rolling_contact;
    let speed_loss = linear_speed_loss + (air_deceleration + grass_deceleration) * dt_seconds;
    velocity.normalized() * (speed - speed_loss).max(0.0)
}

fn zone(v: f64, max: f64, buckets: usize) -> usize {
    ((v / max).clamp(0.0, 0.999_999) * buckets as f64).floor() as usize
}

fn pitch_grid_cell(
    position: Vec2,
    field_width: f64,
    field_length: f64,
    columns: usize,
    rows: usize,
    level: PitchGridLevel,
    parent_id: Option<usize>,
) -> PitchGridCell {
    let columns = columns.max(1);
    let rows = rows.max(1);
    let x = zone(position.x, field_width, columns);
    let y = zone(position.y, field_length, rows);
    PitchGridCell {
        level,
        columns,
        rows,
        x,
        y,
        id: y * columns + x,
        parent_id,
    }
}

fn pitch_grid_address(position: Vec2, field_width: f64, field_length: f64) -> PitchGridAddress {
    let (field_width, field_length) = sane_pitch_dimensions(field_width, field_length);
    let whole_pitch = PitchGridCell::default();
    let macro_zone = pitch_grid_cell(
        position,
        field_width,
        field_length,
        PITCH_MACRO_GRID_COLUMNS,
        PITCH_MACRO_GRID_ROWS,
        PitchGridLevel::Macro,
        Some(whole_pitch.id),
    );
    let tactical = pitch_grid_cell(
        position,
        field_width,
        field_length,
        PITCH_TACTICAL_GRID_COLUMNS,
        PITCH_TACTICAL_GRID_ROWS,
        PitchGridLevel::Tactical,
        Some(macro_zone.id),
    );
    let fine = pitch_grid_cell(
        position,
        field_width,
        field_length,
        PITCH_FINE_GRID_COLUMNS,
        PITCH_FINE_GRID_ROWS,
        PitchGridLevel::Fine,
        Some(tactical.id),
    );
    PitchGridAddress {
        fine,
        tactical,
        macro_zone,
        whole_pitch,
    }
}

fn facing_bucket_from_vector(v: Vec2) -> FacingBucket {
    if v.len() <= 1e-6 {
        return FacingBucket::Unknown;
    }
    facing_bucket_from_degrees(v.y.atan2(v.x).to_degrees())
}

fn facing_bucket_from_degrees(degrees: f64) -> FacingBucket {
    if !degrees.is_finite() {
        return FacingBucket::Unknown;
    }
    let mut degrees = degrees % 360.0;
    if degrees < 0.0 {
        degrees += 360.0;
    }
    let idx = ((degrees + 22.5) / 45.0).floor() as usize % 8;
    match idx {
        0 => FacingBucket::East,
        1 => FacingBucket::SouthEast,
        2 => FacingBucket::South,
        3 => FacingBucket::SouthWest,
        4 => FacingBucket::West,
        5 => FacingBucket::NorthWest,
        6 => FacingBucket::North,
        _ => FacingBucket::NorthEast,
    }
}

fn facing_bucket_to_vector(facing: FacingBucket) -> Option<Vec2> {
    match facing {
        FacingBucket::Unknown => None,
        FacingBucket::East => Some(Vec2::new(1.0, 0.0)),
        FacingBucket::SouthEast => Some(Vec2::new(1.0, 1.0).normalized()),
        FacingBucket::South => Some(Vec2::new(0.0, 1.0)),
        FacingBucket::SouthWest => Some(Vec2::new(-1.0, 1.0).normalized()),
        FacingBucket::West => Some(Vec2::new(-1.0, 0.0)),
        FacingBucket::NorthWest => Some(Vec2::new(-1.0, -1.0).normalized()),
        FacingBucket::North => Some(Vec2::new(0.0, -1.0)),
        FacingBucket::NorthEast => Some(Vec2::new(1.0, -1.0).normalized()),
    }
}

fn facing_bucket_clock_index(facing: FacingBucket) -> Option<i8> {
    match facing {
        FacingBucket::East => Some(0),
        FacingBucket::SouthEast => Some(1),
        FacingBucket::South => Some(2),
        FacingBucket::SouthWest => Some(3),
        FacingBucket::West => Some(4),
        FacingBucket::NorthWest => Some(5),
        FacingBucket::North => Some(6),
        FacingBucket::NorthEast => Some(7),
        FacingBucket::Unknown => None,
    }
}

fn facing_bucket_from_clock_index(index: i8) -> FacingBucket {
    match index.rem_euclid(8) {
        0 => FacingBucket::East,
        1 => FacingBucket::SouthEast,
        2 => FacingBucket::South,
        3 => FacingBucket::SouthWest,
        4 => FacingBucket::West,
        5 => FacingBucket::NorthWest,
        6 => FacingBucket::North,
        _ => FacingBucket::NorthEast,
    }
}

fn facing_bucket_rotate_one_step_toward(
    current: FacingBucket,
    target: FacingBucket,
) -> FacingBucket {
    let (Some(current_idx), Some(target_idx)) = (
        facing_bucket_clock_index(current),
        facing_bucket_clock_index(target),
    ) else {
        return target;
    };
    let clockwise = (target_idx - current_idx).rem_euclid(8);
    if clockwise == 0 {
        current
    } else if clockwise <= 1 || clockwise >= 7 {
        target
    } else if clockwise <= 4 {
        facing_bucket_from_clock_index(current_idx + 1)
    } else {
        facing_bucket_from_clock_index(current_idx - 1)
    }
}

fn ball_facing_bucket_from_position(
    team: Team,
    position: Vec2,
    ball_position: Vec2,
) -> FacingBucket {
    let to_ball = ball_position - position;
    if to_ball.len() > PLAYER_CONTROL_RADIUS_YARDS * 0.6 {
        facing_bucket_from_vector(to_ball)
    } else {
        default_team_facing(team)
    }
}

fn movement_action_facing_bucket(
    team: Team,
    position: Vec2,
    ball_position: Vec2,
    to_target: Vec2,
    velocity: Vec2,
    gait: MovementGait,
    has_ball: bool,
    current_facing: FacingBucket,
) -> FacingBucket {
    if has_ball && to_target.len() > 1e-6 {
        return facing_bucket_from_vector(to_target);
    }

    let to_ball = ball_position - position;
    if to_ball.len() <= PLAYER_CONTROL_RADIUS_YARDS * 0.6 && current_facing != FacingBucket::Unknown
    {
        return current_facing;
    }

    let ball_facing = ball_facing_bucket_from_position(team, position, ball_position);
    if matches!(gait, MovementGait::Run | MovementGait::Sprint)
        && velocity.len() >= FAST_AWAY_FACING_MIN_SPEED_YPS
        && to_ball.len() > PLAYER_CONTROL_RADIUS_YARDS
        && to_target.len() > PLAYER_CONTROL_RADIUS_YARDS
        && velocity.normalized().dot(to_ball.normalized()) <= FAST_AWAY_FACING_BALL_DOT
        && to_target.normalized().dot(to_ball.normalized()) <= FAST_AWAY_FACING_BALL_DOT
    {
        return facing_bucket_from_vector(to_target);
    }

    if let Some(current) = facing_bucket_to_vector(current_facing) {
        let to_ball_dir = to_ball.normalized();
        if to_ball.len() > PLAYER_CONTROL_RADIUS_YARDS
            && current.normalized().dot(to_ball_dir) >= STABLE_CURRENT_FACING_BALL_DOT
        {
            return current_facing;
        }
        if to_ball.len() > PLAYER_CONTROL_RADIUS_YARDS {
            let urgent_ball_recovery = matches!(gait, MovementGait::Run | MovementGait::Sprint)
                && to_target.len() > PLAYER_CONTROL_RADIUS_YARDS
                && to_target.normalized().dot(to_ball_dir) >= 0.45;
            if urgent_ball_recovery {
                return ball_facing;
            }
            return facing_bucket_rotate_one_step_toward(current_facing, ball_facing);
        }
    }

    ball_facing
}

fn player_facing_vector_for_ball_control(player: &PlayerAgent, ball_pos: Vec2) -> Vec2 {
    facing_bucket_to_vector(player.action_facing)
        .or_else(|| {
            facing_bucket_to_vector(ball_facing_bucket_from_position(
                player.team,
                player.position,
                ball_pos,
            ))
        })
        .or_else(|| facing_bucket_to_vector(default_team_facing(player.team)))
        .unwrap_or_else(|| Vec2::new(0.0, player.team.attack_dir()))
}

fn player_facing_ball_control_multiplier(player: &PlayerAgent, ball_pos: Vec2) -> f64 {
    let to_ball = ball_pos - player.position;
    if to_ball.len() <= PLAYER_CONTROL_RADIUS_YARDS * 0.6 {
        return 1.0;
    }
    let facing = player_facing_vector_for_ball_control(player, ball_pos);
    if facing.dot(to_ball.normalized()) >= FACING_BALL_MIN_DOT {
        1.0
    } else {
        NOT_FACING_BALL_INTERCEPTION_MULTIPLIER
    }
}

fn facing_bucket_matches(a: FacingBucket, b: FacingBucket) -> bool {
    a == b || a == FacingBucket::Unknown || b == FacingBucket::Unknown
}

fn default_team_facing(team: Team) -> FacingBucket {
    facing_bucket_from_vector(Vec2::new(0.0, team.attack_dir()))
}

fn default_agent_preferences(
    role: PlayerRole,
    shirt: u8,
    home_position: Vec2,
    field_width: f64,
) -> AgentPreferences {
    let mut preferences = AgentPreferences::default();
    let wide_position =
        home_position.x < field_width * 0.28 || home_position.x > field_width * 0.72;
    match role {
        PlayerRole::Goalkeeper => {
            preferences.offensive_mindedness = 0.08;
            preferences.defensive_mindedness = 0.92;
        }
        PlayerRole::Defender if wide_position => {
            preferences.open_space_bias = 0.74;
            preferences.offensive_mindedness = 0.58;
            preferences.defensive_mindedness = 0.66;
        }
        PlayerRole::Defender => {
            preferences.offensive_mindedness = 0.22;
            preferences.defensive_mindedness = 0.88;
        }
        PlayerRole::Midfielder if shirt == 6 => {
            preferences.pass_bias = 0.78;
            preferences.open_space_bias = 0.74;
            preferences.offensive_mindedness = 0.42;
            preferences.defensive_mindedness = 0.82;
        }
        PlayerRole::Midfielder if shirt == 8 => {
            preferences.pass_bias = 0.80;
            preferences.open_space_bias = 0.86;
            preferences.offensive_mindedness = 0.76;
            preferences.defensive_mindedness = 0.50;
        }
        PlayerRole::Midfielder => {
            preferences.pass_bias = 0.76;
            preferences.open_space_bias = 0.82;
            preferences.offensive_mindedness = 0.70;
            preferences.defensive_mindedness = 0.52;
        }
        PlayerRole::Forward => {
            preferences.shoot_bias = 0.78;
            preferences.pass_bias = 0.48;
            preferences.dribble_bias = 0.82;
            preferences.offensive_mindedness = 0.88;
            preferences.defensive_mindedness = 0.30;
        }
    }
    preferences
}

fn facing_bucket_for_player_motion(player: &PlayerAgent) -> FacingBucket {
    let facing = facing_bucket_from_vector(player.velocity);
    if facing == FacingBucket::Unknown {
        default_team_facing(player.team)
    } else {
        facing
    }
}

fn mark_player_receive_facing(players: &mut [PlayerAgent], holder_id: usize) {
    let Some(player) = players.iter_mut().find(|player| player.id == holder_id) else {
        return;
    };
    let facing = facing_bucket_for_player_motion(player);
    player.receive_facing = facing;
    player.action_facing = facing;
}

fn distance_bucket(value: f64, edges: &[f64]) -> u8 {
    if value.is_nan() {
        return 0;
    }
    if value == f64::NEG_INFINITY {
        return 0;
    }
    if value == f64::INFINITY {
        return edges.len().min(u8::MAX as usize) as u8;
    }
    edges
        .iter()
        .position(|edge| value <= *edge)
        .unwrap_or(edges.len())
        .min(u8::MAX as usize) as u8
}

fn confidence_bucket(value: f64) -> u8 {
    distance_bucket(value.clamp(0.0, 1.0), &[0.20, 0.40, 0.60, 0.80])
}

fn skill_bucket(value: f64) -> u8 {
    distance_bucket(ability_score(value), &[3.0, 5.0, 7.0, 9.0])
}

fn fatigue_advantage_bucket(value: f64) -> u8 {
    distance_bucket(value.clamp(-1.0, 1.0), &[-0.45, -0.15, 0.15, 0.45])
}

fn loose_ball_time_advantage_bucket(value: f64) -> u8 {
    distance_bucket(
        value.clamp(-3.0, 3.0),
        &[-1.20, -0.40, -0.12, 0.12, 0.40, 1.20],
    )
}

fn fatigue_speed_factor(stamina: f64, fatigue: f64) -> f64 {
    let cardio = ability01(stamina);
    let fatigue = fatigue.clamp(0.0, 1.0);
    (0.78 + 0.22 * cardio - fatigue * (0.18 + (1.0 - cardio) * 0.20)).clamp(0.45, 1.05)
}

fn fatigue_dribble_multiplier(observation: &SoccerPomdpObservation) -> f64 {
    let advantage = observation.perceived_fatigue_advantage.clamp(-1.0, 1.0);
    let confidence = observation
        .nearest_defender_fatigue_confidence
        .clamp(0.0, 1.0);
    let fresh_attacker = 1.0 - observation.fatigue.clamp(0.0, 1.0);
    let defender_tired = observation
        .perceived_nearest_defender_fatigue
        .clamp(0.0, 1.0);
    let cue_strength = confidence * (0.45 + fresh_attacker * 0.35 + defender_tired * 0.20);
    let bonus = (advantage - 0.10).max(0.0) * cue_strength * 1.15;
    let penalty = (-advantage - 0.10).max(0.0) * (0.45 + confidence * 0.25)
        + observation.fatigue.clamp(0.0, 1.0) * 0.24;
    (1.0 + bonus - penalty).clamp(0.45, 1.55)
}

fn shot_creation_carry_multiplier(observation: &SoccerPomdpObservation) -> f64 {
    if shot_decision_is_qualified(observation) {
        return 1.0;
    }
    let attacking_range =
        (1.0 - ((observation.yards_to_goal - 14.0).max(0.0) / 54.0)).clamp(0.0, 1.0);
    let almost_on_frame =
        (observation.shot_on_frame_probability / SHOT_ON_FRAME_MIN_PROBABILITY).clamp(0.0, 1.0);
    let almost_beats_keeper = (observation.shot_beat_goalkeeper_probability
        / SHOT_KEEPER_BEAT_MIN_PROBABILITY)
        .clamp(0.0, 1.0);
    let low_block = (1.0 - observation.shot_block_probability).clamp(0.0, 1.0);
    let shot_promise =
        (almost_on_frame * 0.54 + almost_beats_keeper * 0.30 + low_block * 0.16).clamp(0.0, 1.0);
    let open_grass = (observation.forward_dribble_space_yards / 16.0).clamp(0.0, 1.0);
    (1.0 + attacking_range * shot_promise * 0.72 + open_grass * 0.18).clamp(1.0, 1.82)
}

fn floor_pass_quality_for_observation(observation: &SoccerPomdpObservation) -> f64 {
    (observation.expected_pass_completion.clamp(0.0, 1.0) * 0.64
        + observation.best_pass_receiver_openness.clamp(0.0, 1.0) * 0.36)
        .clamp(0.0, 1.0)
}

fn pressure_release_signal(observation: &SoccerPomdpObservation) -> f64 {
    ((observation
        .perceived_pressure
        .max(observation.pressure_urgency)
        .max(observation.immediate_dispossession_risk)
        - 0.34)
        / 0.48)
        .clamp(0.0, 1.0)
}

fn pressured_release_multiplier(observation: &SoccerPomdpObservation) -> f64 {
    let quality = floor_pass_quality_for_observation(observation);
    let open_receiver = observation.best_pass_receiver_openness.clamp(0.0, 1.0);
    let forward_option = (observation.visible_forward_pass_options as f64 / 2.0).clamp(0.0, 1.0);
    (1.0 + pressure_release_signal(observation)
        * (0.36 + quality * 0.62 + open_receiver * 0.24 + forward_option * 0.16))
        .clamp(1.0, 2.20)
}

fn ability_score(value: f64) -> f64 {
    if !value.is_finite() {
        return 1.0;
    }
    if (0.0..1.0).contains(&value) {
        1.0 + value.clamp(0.0, 1.0) * 9.0
    } else {
        value.clamp(1.0, 10.0)
    }
}

fn ability01(value: f64) -> f64 {
    (ability_score(value) - 1.0) / 9.0
}

fn default_player_weight_for_traits(
    role: PlayerRole,
    strength_score: f64,
    height_score: f64,
    jitter: f64,
) -> f64 {
    let role_base = match role {
        PlayerRole::Goalkeeper => 171.0,
        PlayerRole::Defender => 169.0,
        PlayerRole::Midfielder => 158.0,
        PlayerRole::Forward => 163.0,
    };
    let strength = ability01(strength_score);
    let height = ability01(height_score);
    (role_base + strength * 13.0 + height * 24.0 + jitter * 10.0).clamp(135.0, 225.0)
}

fn player_weight_pounds(value: f64) -> f64 {
    if value.is_finite() && value > 0.0 {
        value.clamp(115.0, 245.0)
    } else {
        default_player_weight_pounds()
    }
}

fn player_weight_bucket(value: f64) -> u8 {
    distance_bucket(player_weight_pounds(value), &[145.0, 165.0, 185.0, 205.0])
}

fn strength_to_weight_acceleration_multiplier_from_parts(
    strength_score: f64,
    weight_pounds: f64,
) -> f64 {
    let strength = ability01(strength_score);
    let weight_load = ((player_weight_pounds(weight_pounds) - 135.0) / 90.0).clamp(0.0, 1.0);
    (1.0 + (strength - weight_load) * 0.22).clamp(0.82, 1.18)
}

fn strength_to_weight_acceleration_multiplier(skills: &SkillProfile) -> f64 {
    strength_to_weight_acceleration_multiplier_from_parts(skills.strength, skills.weight_pounds)
}

fn top_speed_yps_from_score(score: f64) -> f64 {
    5.5 + ability01(score) * 3.5
}

fn player_top_speed_yps(role: PlayerRole, skills: &SkillProfile) -> f64 {
    let role_multiplier = if role == PlayerRole::Forward {
        FORWARD_TOP_SPEED_MULTIPLIER
    } else {
        1.0
    };
    top_speed_yps_from_score(skills.top_speed) * role_multiplier
}

fn acceleration_yps2_from_score(score: f64) -> f64 {
    5.2 + ability01(score) * 4.1
}

fn height_inches_from_score(score: f64) -> f64 {
    65.0 + ability01(score) * 12.0
}

fn pressure_bucket(nearest_opponent_distance: f64) -> u8 {
    let pressure = (1.0 - nearest_opponent_distance / 18.0).clamp(0.0, 1.0);
    distance_bucket(pressure, &[0.15, 0.35, 0.60, 0.82])
}

fn default_players(config: &MatchConfig, rng: &mut SeededRandom) -> Vec<PlayerAgent> {
    let home_layout = vec![
        (
            "Home GK".to_string(),
            PlayerRole::Goalkeeper,
            1,
            Vec2::new(40.0, 7.0),
        ),
        (
            "Home LB".to_string(),
            PlayerRole::Defender,
            2,
            Vec2::new(14.0, 24.0),
        ),
        (
            "Home LCB".to_string(),
            PlayerRole::Defender,
            4,
            Vec2::new(31.0, 23.0),
        ),
        (
            "Home RCB".to_string(),
            PlayerRole::Defender,
            5,
            Vec2::new(49.0, 23.0),
        ),
        (
            "Home RB".to_string(),
            PlayerRole::Defender,
            3,
            Vec2::new(66.0, 24.0),
        ),
        (
            "Home LM".to_string(),
            PlayerRole::Midfielder,
            11,
            Vec2::new(17.0, 57.0),
        ),
        (
            "Home CM1".to_string(),
            PlayerRole::Midfielder,
            6,
            Vec2::new(33.0, 55.0),
        ),
        (
            "Home CM2".to_string(),
            PlayerRole::Midfielder,
            8,
            Vec2::new(47.0, 55.0),
        ),
        (
            "Home RM".to_string(),
            PlayerRole::Midfielder,
            7,
            Vec2::new(63.0, 57.0),
        ),
        (
            "Home ST1".to_string(),
            PlayerRole::Forward,
            9,
            Vec2::new(31.0, 78.0),
        ),
        (
            "Home ST2".to_string(),
            PlayerRole::Forward,
            10,
            Vec2::new(49.0, 78.0),
        ),
    ];
    let away_layout = home_layout
        .iter()
        .map(|(name, role, shirt, pos)| {
            (
                name.replacen("Home", "Away", 1),
                *role,
                *shirt,
                Vec2::new(pos.x, config.field_length_yards - pos.y),
            )
        })
        .collect::<Vec<_>>();

    let mut players = Vec::with_capacity(22);
    for (team, layout) in [(Team::Home, home_layout), (Team::Away, away_layout)] {
        for (name, role, shirt, pos) in layout.into_iter() {
            let id = players.len();
            let preferences = default_agent_preferences(role, shirt, pos, config.field_width_yards);
            players.push(PlayerAgent {
                id,
                name,
                team,
                role,
                shirt,
                home_position: pos,
                position: pos,
                velocity: Vec2::zero(),
                acceleration: Vec2::zero(),
                jerk: Vec2::zero(),
                movement_gait: MovementGait::Stand,
                position_history: VecDeque::from([pos]),
                receive_facing: FacingBucket::Unknown,
                action_facing: default_team_facing(team),
                incoming_ball: None,
                skills: SkillProfile::blended(id, role, rng),
                fatigue: 0.0,
                controller_slot: None,
                preferences,
                last_decision: None,
            });
        }
    }
    players
}

