    #[test]
    fn default_match_config_preserves_initial_runtime_contract() {
        let config = MatchConfig::default().sanitized_for_runtime();
        assert_eq!(config.dt_seconds, DEFAULT_DT_SECONDS);
        assert_eq!(config.dt_seconds, 0.1);
        assert_eq!(config.duration_seconds, DEFAULT_DURATION_SECONDS);
        assert_eq!(config.duration_seconds, 10.0 * 60.0);
        assert_eq!(config.effective_duration_seconds(), 600.0);
        assert_eq!(config.total_ticks(), 6_000);
        assert_eq!(config.human_slots(), 4);
        assert!(config.learning_enabled);
        assert!(config.learning_logging_enabled);
        assert!(config.full_game_learning_enabled);

        let sim = SoccerMatch::default_11v11(config);
        assert_eq!(sim.players.len(), 22);
        assert_eq!(sim.officials.len(), 3);
        assert_eq!(sim.ball.id, BALL_AGENT_ID);
        assert_eq!(sim.config.total_ticks(), 6_000);
        assert_eq!(sim.config.human_slots(), 4);
        assert_eq!(sim.config.field_length_yards, DEFAULT_FIELD_LENGTH_YARDS);
        assert_eq!(sim.config.field_width_yards, DEFAULT_FIELD_WIDTH_YARDS);
        assert_eq!(sim.config.goal_width_yards, DEFAULT_GOAL_WIDTH_YARDS);
    }

    fn assert_kickoff_shape(sim: &SoccerMatch, kickoff_team: Team) {
        let center = Vec2::new(
            sim.config.field_width_yards * 0.5,
            sim.config.field_length_yards * 0.5,
        );
        let half_line = sim.config.field_length_yards * 0.5;
        let holder = sim.ball.holder.expect("kickoff holder");
        assert_eq!(sim.players[holder].team, kickoff_team);
        assert!(sim.players[holder].position.distance(center) < 0.01);
        let mut kickoff_team_in_center_circle = 0usize;
        for player in &sim.players {
            if player.id != holder {
                match player.team {
                    Team::Home => assert!(
                        player.position.y <= half_line + 1e-9,
                        "home player outside own half at kickoff: {:?}",
                        player
                    ),
                    Team::Away => assert!(
                        player.position.y >= half_line - 1e-9,
                        "away player outside own half at kickoff: {:?}",
                        player
                    ),
                }
            }
            let in_center_circle =
                player.position.distance(center) <= KICKOFF_CENTER_CIRCLE_RADIUS_YARDS + 1e-9;
            if player.team == kickoff_team && in_center_circle {
                kickoff_team_in_center_circle += 1;
            }
            if player.team != kickoff_team {
                assert!(
                    !in_center_circle,
                    "defending kickoff player inside center circle: {:?}",
                    player
                );
            }
        }
        assert!(
            kickoff_team_in_center_circle >= 2,
            "kickoff should stage taker and a support player near center"
        );
    }

    fn park_players_except(sim: &mut SoccerMatch, keep: &[usize]) {
        for player in &mut sim.players {
            if keep.contains(&player.id) {
                continue;
            }
            let lane = (player.id % 5) as f64;
            let band = (player.id % 4) as f64;
            player.position = match player.team {
                Team::Home => Vec2::new(6.0 + lane * 2.0, 8.0 + band * 4.0),
                Team::Away => Vec2::new(64.0 + lane * 2.0, 100.0 + band * 4.0),
            }
            .clamp_to_pitch(sim.config.field_width_yards, sim.config.field_length_yards);
            player.velocity = Vec2::zero();
            player.acceleration = Vec2::zero();
        }
    }

    #[test]
    fn default_match_has_22_players_and_3_officials() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        assert_eq!(sim.players.len(), 22);
        assert_eq!(sim.officials.len(), 3);
        assert_eq!(
            sim.players
                .iter()
                .filter(|player| player.role == PlayerRole::Goalkeeper)
                .count(),
            2
        );
        assert_eq!(
            sim.players
                .iter()
                .filter(|player| player.role == PlayerRole::Defender)
                .count(),
            8
        );
        assert_eq!(
            sim.players
                .iter()
                .filter(|player| player.role == PlayerRole::Midfielder)
                .count(),
            8
        );
        assert_eq!(
            sim.players
                .iter()
                .filter(|player| player.role == PlayerRole::Forward)
                .count(),
            4
        );
        let skill_signature = |skills: &SkillProfile| {
            format!(
                "{:.1}:{:.1}:{:.1}:{:.1}:{:.1}:{:.1}:{:.1}:{:.1}",
                skills.top_speed,
                skills.acceleration,
                skills.shooting,
                skills.passing_completion_rate,
                skills.dribbling,
                skills.defending,
                skills.goalkeeping,
                skills.defensive_tracking
            )
        };
        let skill_signatures = sim
            .players
            .iter()
            .map(|player| skill_signature(&player.skills))
            .collect::<std::collections::BTreeSet<_>>();
        assert!(
            skill_signatures.len() >= 18,
            "default agents should carry differentiated skill profiles, got {skill_signatures:?}"
        );
        for player in &sim.players {
            let skills = &player.skills;
            for (name, value) in [
                ("top_speed", skills.top_speed),
                ("acceleration", skills.acceleration),
                ("strength", skills.strength),
                ("height", skills.height),
                ("shooting", skills.shooting),
                ("right_foot_shot_power", skills.right_foot_shot_power),
                ("left_foot_shot_power", skills.left_foot_shot_power),
                ("passing_completion_rate", skills.passing_completion_rate),
                ("flair_passing", skills.flair_passing),
                ("crossing_left", skills.crossing_left),
                ("crossing_right", skills.crossing_right),
                ("dribbling", skills.dribbling),
                ("defending", skills.defending),
                ("goalkeeping", skills.goalkeeping),
                ("defensive_tracking", skills.defensive_tracking),
            ] {
                assert!(
                    (1.0..=10.0).contains(&value),
                    "player {} {} skill {} should be in 1-10 range, got {}",
                    player.id,
                    format!("{:?}", player.role),
                    name,
                    value
                );
            }
            assert!(
                player.skills.weight_pounds.is_finite() && player.skills.weight_pounds > 120.0,
                "player {} should have plausible weight for physics: {}",
                player.id,
                player.skills.weight_pounds
            );
        }
        let role_average = |role: PlayerRole, metric: fn(&SkillProfile) -> f64| {
            let values = sim
                .players
                .iter()
                .filter(|player| player.role == role)
                .map(|player| metric(&player.skills))
                .collect::<Vec<_>>();
            values.iter().sum::<f64>() / values.len().max(1) as f64
        };
        let forward_speed = role_average(PlayerRole::Forward, |skills| skills.top_speed);
        let defender_speed = role_average(PlayerRole::Defender, |skills| skills.top_speed);
        let forward_shooting = role_average(PlayerRole::Forward, |skills| skills.shooting);
        let midfielder_passing = role_average(PlayerRole::Midfielder, |skills| {
            skills.passing_completion_rate
        });
        let defender_defending = role_average(PlayerRole::Defender, |skills| skills.defending);
        let goalkeeper_goalkeeping =
            role_average(PlayerRole::Goalkeeper, |skills| skills.goalkeeping);
        assert!(
            forward_speed > defender_speed,
            "forwards should be faster on average: fwd={forward_speed} def={defender_speed}"
        );
        assert!(
            forward_shooting > defender_defending * 0.80,
            "forwards should have real shooting ability: fwd_shoot={forward_shooting} def_def={defender_defending}"
        );
        assert!(
            midfielder_passing > forward_shooting * 0.75,
            "midfielders should have meaningful passing completion: mid_pass={midfielder_passing} fwd_shoot={forward_shooting}"
        );
        assert!(
            goalkeeper_goalkeeping > defender_defending,
            "goalkeepers should have the strongest ability in goal: gk={goalkeeper_goalkeeping} def={defender_defending}"
        );
        assert_eq!(sim.config.dt_seconds, DEFAULT_DT_SECONDS);
        assert_eq!(
            sim.config.effective_duration_seconds(),
            DEFAULT_DURATION_SECONDS
        );
        assert_eq!(sim.config.half_count(), 1);
        assert_eq!(sim.config.total_ticks(), 6_000);
        assert_eq!(sim.config.max_human_players, 4);
        assert_eq!(sim.config.human_slots(), 4);
        assert_eq!(sim.ball.id, BALL_AGENT_ID);
        assert_eq!(sim.ball.holder, sim.possession_chain.back().copied());
        assert!(sim.last_agent_schedule.is_empty());
        let initial_clock = sim.match_clock();
        assert_eq!(initial_clock.tick, 0);
        assert_eq!(initial_clock.total_ticks, 6_000);
        assert_eq!(initial_clock.remaining_ticks, 6_000);
        assert_eq!(initial_clock.dt_seconds, DEFAULT_DT_SECONDS);
        assert_eq!(initial_clock.total_seconds, DEFAULT_DURATION_SECONDS);
        assert!(!initial_clock.done);
        assert_eq!(
            sim.ball.position,
            Vec2::new(
                sim.config.field_width_yards * 0.5,
                sim.config.field_length_yards * 0.5
            )
        );
        assert_kickoff_shape(&sim, Team::Home);
        let near_assistant = sim
            .officials
            .iter()
            .find(|official| official.kind == OfficialKind::AssistantRefereeNear)
            .expect("near assistant");
        assert!(near_assistant.position.x < 0.0);
        assert!(near_assistant.position.y <= sim.config.field_length_yards * 0.5);
        let far_assistant = sim
            .officials
            .iter()
            .find(|official| official.kind == OfficialKind::AssistantRefereeFar)
            .expect("far assistant");
        assert!(far_assistant.position.x > sim.config.field_width_yards);
        assert!(far_assistant.position.y >= sim.config.field_length_yards * 0.5);

        sim.run_time_step();
        let frame = sim.to_frame();
        let ball_schedule_index = frame
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID)
            .expect("ball agent scheduled after first tick");
        assert_eq!(frame.tick, 1);
        assert_eq!(frame.clock_seconds, DEFAULT_DT_SECONDS);
        assert_eq!(frame.players.len(), 22);
        assert_eq!(frame.officials.len(), 3);
        assert_eq!(frame.agent_schedule.len(), 27);
        assert_eq!(
            frame
                .agent_schedule
                .first()
                .map(|entry| (&entry.kind, entry.id)),
            Some((&AgentScheduleKind::CentralBrain, CENTRAL_BRAIN_AGENT_ID))
        );
        assert_eq!(frame.central_brain.scheduled_index, Some(0));
        assert_eq!(frame.central_brain.tracked_players.len(), 22);
        assert_eq!(frame.central_brain.tracked_officials, 3);
        assert_eq!(frame.ball.scheduled_index, Some(ball_schedule_index));
        assert_eq!(
            frame
                .ball
                .last_decision
                .as_ref()
                .and_then(|decision| decision.scheduled_index),
            Some(ball_schedule_index)
        );
        assert_eq!(sim.match_clock().remaining_ticks, 5_999);
    }

