    #[test]
    fn agent_schedule_records_brain_then_shuffled_field_entities() {
        let schedule_config = |seed| MatchConfig {
            seed,
            ..MatchConfig::playback_trace(0.2)
        };
        let mut sim = SoccerMatch::default_11v11(schedule_config(303));

        sim.run_time_step();

        let frame = sim.to_frame();
        assert_eq!(frame.agent_schedule.len(), 27);
        let unique_schedule_entries = frame
            .agent_schedule
            .iter()
            .map(|entry| format!("{:?}:{}", entry.kind, entry.id))
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            unique_schedule_entries.len(),
            frame.agent_schedule.len(),
            "field schedule should include each agent exactly once"
        );
        assert_eq!(
            frame
                .agent_schedule
                .first()
                .map(|entry| (&entry.kind, entry.id)),
            Some((&AgentScheduleKind::CentralBrain, CENTRAL_BRAIN_AGENT_ID))
        );
        assert_eq!(frame.central_brain.scheduled_index, Some(0));
        let central_decision = frame
            .central_brain
            .last_decision
            .as_ref()
            .expect("central brain decision");
        assert_eq!(central_decision.tick, 0);
        assert_eq!(central_decision.scheduled_index, Some(0));
        assert_eq!(central_decision.phase, frame.central_brain.phase);
        assert_eq!(
            central_decision.possession_team,
            frame.central_brain.possession_team
        );
        assert_eq!(
            central_decision.ball_holder,
            frame.central_brain.ball_holder
        );
        assert_eq!(central_decision.tracked_players, 22);
        assert_eq!(central_decision.tracked_officials, 3);
        assert!(central_decision.action.starts_with("directives-"));
        assert!(central_decision
            .operation_order
            .iter()
            .any(|operation| operation == "issue-team-directives"));
        assert_eq!(
            frame
                .agent_schedule
                .iter()
                .filter(|entry| entry.kind == AgentScheduleKind::Player)
                .count(),
            22
        );
        assert_eq!(
            frame
                .agent_schedule
                .iter()
                .filter(|entry| entry.kind == AgentScheduleKind::Official)
                .count(),
            3
        );
        assert_eq!(
            frame
                .agent_schedule
                .iter()
                .filter(|entry| entry.kind == AgentScheduleKind::CentralBrain)
                .count(),
            1
        );
        assert_eq!(
            frame
                .agent_schedule
                .iter()
                .filter(|entry| entry.kind == AgentScheduleKind::Ball)
                .count(),
            1
        );
        assert_eq!(
            frame
                .agent_schedule
                .iter()
                .find(|entry| entry.kind == AgentScheduleKind::Ball)
                .map(|entry| entry.id),
            Some(BALL_AGENT_ID)
        );
        let ball_positions = [300, 301, 302, 303, 304]
            .into_iter()
            .map(|seed| {
                let mut seeded = SoccerMatch::default_11v11(schedule_config(seed));
                seeded.run_time_step();
                seeded
                    .to_frame()
                    .agent_schedule
                    .iter()
                    .position(|entry| entry.kind == AgentScheduleKind::Ball)
                    .expect("ball scheduled")
            })
            .collect::<std::collections::BTreeSet<_>>();
        assert!(
            ball_positions.len() > 1,
            "ball schedule slot should vary across seeds: {ball_positions:?}"
        );
        assert!(
            ball_positions
                .iter()
                .any(|slot| *slot + 1 != frame.agent_schedule.len()),
            "ball should not be deterministically appended last: {ball_positions:?}"
        );
        let scheduled_player_ids = frame
            .agent_schedule
            .iter()
            .filter(|entry| entry.kind == AgentScheduleKind::Player)
            .map(|entry| entry.id)
            .collect::<std::collections::BTreeSet<_>>();
        let expected_player_ids = (0..22).collect::<std::collections::BTreeSet<_>>();
        assert_eq!(scheduled_player_ids, expected_player_ids);
        for player in &frame.players {
            let expected_index = frame
                .agent_schedule
                .iter()
                .position(|entry| entry.kind == AgentScheduleKind::Player && entry.id == player.id)
                .expect("player scheduled");
            assert_eq!(player.scheduled_index, Some(expected_index));
            let brain_player = frame
                .central_brain
                .tracked_players
                .iter()
                .find(|awareness| awareness.id == player.id)
                .expect("central brain player awareness");
            assert_eq!(brain_player.position, player.position);
            assert_eq!(brain_player.velocity, player.velocity);
            assert_eq!(brain_player.acceleration, player.acceleration);
            assert_eq!(brain_player.scheduled_index, Some(expected_index));
            assert_eq!(
                player
                    .last_decision
                    .as_ref()
                    .and_then(|decision| decision.scheduled_index),
                Some(expected_index),
                "player decision should record shuffled schedule slot for player {}",
                player.id
            );
        }
        let scheduled_official_ids = frame
            .agent_schedule
            .iter()
            .filter(|entry| entry.kind == AgentScheduleKind::Official)
            .map(|entry| entry.id)
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            scheduled_official_ids,
            [22, 23, 24]
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>()
        );
        let scheduled_official_labels = frame
            .agent_schedule
            .iter()
            .filter(|entry| entry.kind == AgentScheduleKind::Official)
            .map(|entry| entry.label.as_str())
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            scheduled_official_labels,
            ["Center ref", "Near assistant", "Far assistant"]
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>()
        );
        let official_kinds = frame
            .officials
            .iter()
            .map(|official| official.kind.label())
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(
            official_kinds,
            ["Center ref", "Near assistant", "Far assistant"]
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>()
        );
        for official in &frame.officials {
            let expected_index = frame
                .agent_schedule
                .iter()
                .position(|entry| {
                    entry.kind == AgentScheduleKind::Official && entry.id == official.id
                })
                .expect("official scheduled");
            assert_eq!(official.scheduled_index, Some(expected_index));
            let brain_official = frame
                .central_brain
                .tracked_official_awareness
                .iter()
                .find(|awareness| awareness.id == official.id)
                .expect("central brain official awareness");
            assert_eq!(brain_official.position, official.position);
            assert_eq!(brain_official.velocity, official.velocity);
            assert_eq!(brain_official.acceleration, official.acceleration);
            assert_eq!(brain_official.scheduled_index, Some(expected_index));
            assert_eq!(
                brain_official.offside_line.is_some(),
                matches!(
                    official.kind,
                    OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar
                )
            );
            let decision = official
                .last_decision
                .as_ref()
                .expect("official decision trace");
            assert_eq!(decision.tick, 0);
            assert_eq!(decision.kind, official.kind);
            assert_eq!(decision.scheduled_index, Some(expected_index));
            assert!(
                decision
                    .operation_order
                    .iter()
                    .any(|operation| operation == "update-kinematics"),
                "official trace should expose its internal operation order: {decision:?}"
            );
            if matches!(
                official.kind,
                OfficialKind::AssistantRefereeNear | OfficialKind::AssistantRefereeFar
            ) {
                assert!(
                    decision.offside_line_y.is_some(),
                    "assistant ref trace should include the offside-line target"
                );
            }
        }
    }

    #[test]
    fn agent_schedule_reshuffles_field_entities_each_tick() {
        let mut config = MatchConfig::playback_trace(0.6);
        config.seed = 308;
        let mut sim = SoccerMatch::default_11v11(config);
        let mut field_orders = std::collections::BTreeSet::new();

        for _ in 0..5 {
            sim.run_time_step();
            let frame = sim.to_frame();
            assert_eq!(
                frame
                    .agent_schedule
                    .first()
                    .map(|entry| (&entry.kind, entry.id)),
                Some((&AgentScheduleKind::CentralBrain, CENTRAL_BRAIN_AGENT_ID))
            );
            assert_eq!(frame.agent_schedule.len(), 27);
            assert_eq!(
                frame
                    .agent_schedule
                    .iter()
                    .filter(|entry| entry.kind == AgentScheduleKind::Player)
                    .count(),
                22
            );
            assert_eq!(
                frame
                    .agent_schedule
                    .iter()
                    .filter(|entry| entry.kind == AgentScheduleKind::Official)
                    .count(),
                3
            );
            assert_eq!(
                frame
                    .agent_schedule
                    .iter()
                    .filter(|entry| entry.kind == AgentScheduleKind::Ball)
                    .count(),
                1
            );
            field_orders.insert(
                frame
                    .agent_schedule
                    .iter()
                    .skip(1)
                    .map(|entry| format!("{:?}:{}", entry.kind, entry.id))
                    .collect::<Vec<_>>(),
            );
        }

        assert!(
            field_orders.len() > 1,
            "field-agent schedule should be reshuffled across ticks"
        );
    }

    #[test]
    fn fisher_yates_schedule_interleaves_players_officials_and_ball() {
        let mut observed_official_before_last_player = false;
        let mut observed_player_before_last_official = false;
        let mut observed_ball_before_last_field_agent = false;

        for seed in 320..360 {
            let mut sim = SoccerMatch::default_11v11(MatchConfig {
                seed,
                ..MatchConfig::playback_trace(0.2)
            });
            sim.run_time_step();
            let frame = sim.to_frame();
            let player_slots = frame
                .agent_schedule
                .iter()
                .enumerate()
                .filter_map(|(slot, entry)| {
                    (entry.kind == AgentScheduleKind::Player).then_some(slot)
                })
                .collect::<Vec<_>>();
            let official_slots = frame
                .agent_schedule
                .iter()
                .enumerate()
                .filter_map(|(slot, entry)| {
                    (entry.kind == AgentScheduleKind::Official).then_some(slot)
                })
                .collect::<Vec<_>>();
            let ball_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| entry.kind == AgentScheduleKind::Ball)
                .expect("ball scheduled");
            assert_eq!(player_slots.len(), 22);
            assert_eq!(official_slots.len(), 3);
            assert_eq!(frame.agent_schedule.len(), 27);
            assert_eq!(
                frame
                    .agent_schedule
                    .first()
                    .map(|entry| (&entry.kind, entry.id)),
                Some((&AgentScheduleKind::CentralBrain, CENTRAL_BRAIN_AGENT_ID))
            );

            let first_official = *official_slots.first().expect("official slot");
            let last_official = *official_slots.last().expect("official slot");
            let first_player = *player_slots.first().expect("player slot");
            let last_player = *player_slots.last().expect("player slot");
            observed_official_before_last_player |= first_official < last_player;
            observed_player_before_last_official |= first_player < last_official;
            observed_ball_before_last_field_agent |= ball_slot < frame.agent_schedule.len() - 1;
        }

        assert!(
            observed_official_before_last_player && observed_player_before_last_official,
            "Fisher-Yates should interleave officials with the player loop, not append them in a fixed block"
        );
        assert!(
            observed_ball_before_last_field_agent,
            "ball agent should participate in the shuffled field schedule instead of always running last"
        );
    }

    #[test]
    fn ball_decision_trace_records_shuffled_schedule_slot() {
        let mut config = MatchConfig::playback_trace(0.2);
        config.seed = 307;
        let mut sim = SoccerMatch::default_11v11(config);

        sim.run_time_step();
        let frame = sim.to_frame();
        let ball_schedule_index = frame
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID)
            .expect("ball scheduled");
        let decision = frame.ball.last_decision.expect("ball decision trace");
        let snapshot = WorldSnapshot::from_match(&sim);

        assert_eq!(frame.ball.scheduled_index, Some(ball_schedule_index));
        assert_eq!(snapshot.ball.scheduled_index, Some(ball_schedule_index));
        assert_eq!(decision.scheduled_index, Some(ball_schedule_index));
        assert_eq!(decision.tick, 0);
        assert!(!decision.action.is_empty());
        assert!(
            decision
                .operation_order
                .iter()
                .any(|operation| operation == "apply-resistance"),
            "ball decision should expose its internal operation order: {decision:?}"
        );
        assert!(
            decision
                .operation_order
                .iter()
                .any(|operation| operation == "resolve-control"),
            "ball decision should include possession/control resolution: {decision:?}"
        );
    }

    #[test]
    fn integrate_ball_delegates_to_ball_agent_run_time_step() {
        let mut via_agent = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.2,
            seed: 309,
            ..Default::default()
        });
        let mut via_shim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.2,
            seed: 309,
            ..Default::default()
        });

        for sim in [&mut via_agent, &mut via_shim] {
            park_players_except(sim, &[]);
            sim.ball.holder = None;
            sim.ball.position = Vec2::new(40.0, 60.0);
            sim.ball.velocity = Vec2::new(0.0, 12.0);
            sim.ball.acceleration = Vec2::zero();
            sim.ball.curl_acceleration = Vec2::zero();
            sim.ball.altitude_yards = 0.0;
            sim.ball.last_touch_team = Some(Team::Home);
            sim.ball.last_decision = None;
            sim.pending_pass = None;
            sim.pending_shot = None;
        }

        via_agent.run_ball_time_step();
        via_shim.integrate_ball();

        assert!(via_agent.ball.position.distance(via_shim.ball.position) < 1e-9);
        assert!(via_agent.ball.velocity.distance(via_shim.ball.velocity) < 1e-9);
        assert!(
            via_agent
                .ball
                .acceleration
                .distance(via_shim.ball.acceleration)
                < 1e-9
        );
        assert_eq!(
            via_agent
                .ball
                .last_decision
                .as_ref()
                .map(|decision| decision.action.as_str()),
            Some("roll")
        );
        let agent_decision = via_agent
            .ball
            .last_decision
            .as_ref()
            .expect("agent ball decision");
        let shim_decision = via_shim
            .ball
            .last_decision
            .as_ref()
            .expect("shim ball decision");
        assert_eq!(agent_decision.tick, shim_decision.tick);
        assert_eq!(agent_decision.action, shim_decision.action);
        assert!(agent_decision.position.distance(shim_decision.position) < 1e-9);
        assert_eq!(agent_decision.holder, shim_decision.holder);
        assert_eq!(
            agent_decision.scheduled_index,
            shim_decision.scheduled_index
        );
    }

    #[test]
    fn pomdp_and_q_state_encode_relative_ball_agent_schedule() {
        let player_id = 5;
        let mut saw_pre_ball = false;
        let mut saw_post_ball = false;

        for seed in 460..620 {
            let mut sim = SoccerMatch::default_11v11(MatchConfig {
                duration_seconds: 0.2,
                seed,
                ..Default::default()
            });
            sim.run_time_step();
            let frame = sim.to_frame();
            let player_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| entry.kind == AgentScheduleKind::Player && entry.id == player_id)
                .expect("player scheduled");
            let ball_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| {
                    entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID
                })
                .expect("ball scheduled");
            let expected_order =
                schedule_order_relative_to_ball(Some(player_slot), Some(ball_slot));
            if expected_order == 0 {
                continue;
            }
            let player = frame
                .players
                .iter()
                .find(|player| player.id == player_id)
                .expect("scheduled player");
            let decision = player.last_decision.as_ref().expect("player decision");

            assert_eq!(decision.observation.scheduled_index, Some(player_slot));
            assert_eq!(decision.observation.ball_scheduled_index, Some(ball_slot));
            assert_eq!(decision.observation.ball_schedule_order, expected_order);

            let q_key = SoccerQStateKey::from_parts(
                &decision.mdp_state,
                &decision.observation,
                player.team,
                player.role,
            );
            assert_eq!(q_key.ball_schedule_order, expected_order);

            if expected_order < 0 {
                saw_pre_ball = true;
            } else {
                saw_post_ball = true;
            }
            if saw_pre_ball && saw_post_ball {
                return;
            }
        }

        panic!("expected seeds to cover player decisions both before and after the ball agent");
    }

    #[test]
    fn scheduled_player_intent_before_ball_moves_pass_same_tick() {
        let passer = 5;
        let receiver = 9;
        for seed in 310..380 {
            let mut sim = SoccerMatch::default_11v11(MatchConfig {
                duration_seconds: 0.2,
                max_human_players: 1,
                seed,
                ..Default::default()
            });
            sim.active_set_play = None;
            sim.clear_controller_assignments();
            sim.assign_controller_slot(0, Some(passer))
                .expect("assign passer");
            park_players_except(&mut sim, &[passer, receiver]);
            sim.players[passer].position = Vec2::new(40.0, 50.0);
            sim.players[passer].velocity = Vec2::zero();
            sim.players[receiver].position = Vec2::new(40.0, 72.0);
            sim.players[receiver].velocity = Vec2::zero();
            sim.ball.holder = Some(passer);
            sim.ball.position = sim.players[passer].position;
            sim.ball.velocity = Vec2::zero();
            sim.ball.last_touch_team = Some(Team::Home);
            sim.pending_pass = None;
            sim.pending_shot = None;
            let origin = sim.ball.position;
            assert!(sim.human_inputs.push(HumanInputFrame {
                controller_slot: 0,
                player_id: Some(passer),
                seq: 1,
                axis: Vec2::zero(),
                sprint: false,
                pass: true,
                pass_flight: PassFlight::Floor,
                shoot: false,
                action: None,
                target_player: Some(receiver),
            }));

            sim.run_time_step();
            let frame = sim.to_frame();
            let passer_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| entry.kind == AgentScheduleKind::Player && entry.id == passer)
                .expect("passer scheduled");
            let ball_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| {
                    entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID
                })
                .expect("ball scheduled");
            if passer_slot < ball_slot {
                assert!(
                    frame.ball.position.distance(origin) > 0.10,
                    "ball should move after a scheduled pre-ball pass: seed={seed}, passer_slot={passer_slot}, ball_slot={ball_slot}, ball={:?}, origin={origin:?}",
                    frame.ball.position
                );
                assert_eq!(
                    frame
                        .ball
                        .last_decision
                        .as_ref()
                        .and_then(|decision| decision.scheduled_index),
                    Some(ball_slot)
                );
                assert_eq!(frame.ball.holder, None);
                return;
            }
        }
        panic!("expected to find a seed with passer scheduled before ball");
    }

    #[test]
    fn held_ball_stays_with_holder_when_ball_scheduled_before_holder() {
        let holder = 5;
        for seed in 380..460 {
            let mut sim = SoccerMatch::default_11v11(MatchConfig {
                duration_seconds: 0.2,
                max_human_players: 1,
                seed,
                ..Default::default()
            });
            sim.active_set_play = None;
            sim.clear_controller_assignments();
            sim.assign_controller_slot(0, Some(holder))
                .expect("assign holder");
            park_players_except(&mut sim, &[holder]);
            sim.players[holder].position = Vec2::new(40.0, 50.0);
            sim.players[holder].velocity = Vec2::zero();
            sim.players[holder].acceleration = Vec2::zero();
            sim.ball.holder = Some(holder);
            sim.ball.position =
                sim.players[holder].position + carried_ball_lead(&sim.players[holder]);
            sim.ball.velocity = Vec2::zero();
            sim.ball.last_touch_team = Some(Team::Home);
            sim.ball.last_decision = None;
            sim.pending_pass = None;
            sim.pending_shot = None;
            let origin = sim.players[holder].position;
            assert!(sim.human_inputs.push(HumanInputFrame {
                controller_slot: 0,
                player_id: Some(holder),
                seq: 1,
                axis: Vec2::new(0.0, 1.0),
                sprint: true,
                pass: false,
                pass_flight: PassFlight::Floor,
                shoot: false,
                action: None,
                target_player: None,
            }));

            sim.run_time_step();
            let frame = sim.to_frame();
            let holder_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| entry.kind == AgentScheduleKind::Player && entry.id == holder)
                .expect("holder scheduled");
            let ball_slot = frame
                .agent_schedule
                .iter()
                .position(|entry| {
                    entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID
                })
                .expect("ball scheduled");
            if ball_slot < holder_slot {
                let holder_agent = &sim.players[holder];
                let expected_ball = (holder_agent.position + carried_ball_lead(holder_agent))
                    .clamp_to_pitch(sim.config.field_width_yards, sim.config.field_length_yards);
                assert_eq!(sim.ball.holder, Some(holder));
                assert!(
                    holder_agent.position.distance(origin) > 0.02,
                    "holder should move after the ball slot: seed={seed}, holder_slot={holder_slot}, ball_slot={ball_slot}"
                );
                assert!(
                    sim.ball.position.distance(expected_ball) < 1e-9,
                    "held ball should stay attached after holder's later move: seed={seed}, holder_slot={holder_slot}, ball_slot={ball_slot}, ball={:?}, expected={expected_ball:?}",
                    sim.ball.position
                );
                assert_eq!(sim.ball.velocity, holder_agent.velocity);
                assert_eq!(sim.ball.last_touch_team, Some(holder_agent.team));
                return;
            }
        }
        panic!("expected to find a seed with ball scheduled before holder");
    }

    #[test]
    fn scheduled_ball_agent_tick_moves_free_ball_and_records_history() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.2,
            seed: 311,
            ball_drag_per_tick: 0.04,
            ball_air_resistance: 0.004,
            ball_grass_resistance_yps2: 0.8,
            ..Default::default()
        });
        park_players_except(&mut sim, &[]);
        sim.active_set_play = None;
        sim.ball.holder = None;
        sim.ball.position = Vec2::new(40.0, 60.0);
        sim.ball.velocity = Vec2::new(9.0, 1.5);
        sim.ball.acceleration = Vec2::zero();
        sim.ball.jerk = Vec2::zero();
        sim.ball.curl_acceleration = Vec2::zero();
        sim.ball.altitude_yards = 0.0;
        sim.ball.last_touch_team = Some(Team::Home);
        sim.ball.last_decision = None;
        sim.ball.position_history.clear();
        sim.ball.record_position_history(0, 0.0);
        sim.pending_pass = None;
        sim.pending_shot = None;
        let origin = sim.ball.position;
        let initial_speed = sim.ball.velocity.len();

        sim.run_time_step();
        let frame = sim.to_frame();
        let ball_slot = frame
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Ball && entry.id == BALL_AGENT_ID)
            .expect("ball scheduled");
        let decision = frame.ball.last_decision.as_ref().expect("ball decision");

        assert_eq!(sim.tick, 1);
        assert_eq!(frame.ball.scheduled_index, Some(ball_slot));
        assert_eq!(decision.scheduled_index, Some(ball_slot));
        assert_eq!(decision.action, "roll");
        assert_eq!(decision.tick, 0);
        assert!(
            [
                "sync-holder",
                "apply-curl",
                "apply-resistance",
                "advance-position",
                "resolve-shot",
                "resolve-boundary",
                "resolve-control",
            ]
            .iter()
            .all(|operation| decision
                .operation_order
                .iter()
                .any(|seen| seen == operation)),
            "scheduled ball agent should expose its full run_time_step loop: {decision:?}"
        );
        assert!(sim.ball.position.x > origin.x);
        assert!(sim.ball.position.y > origin.y);
        assert!(
            sim.ball.velocity.len() < initial_speed,
            "scheduled ball agent should apply configured drag/resistance: before={initial_speed} after={}",
            sim.ball.velocity.len()
        );
        assert_eq!(sim.ball.holder, None);
        assert!(sim.ball.acceleration.len().is_finite());
        assert!(sim.ball.jerk.len().is_finite());
        assert_eq!(sim.ball.position_history.len(), 2);
        assert_eq!(
            sim.ball
                .position_history
                .back()
                .map(|sample| (sample.tick, sample.position)),
            Some((1, sim.ball.position))
        );
        assert_eq!(
            sim.ball
                .position_history
                .back()
                .map(|sample| sample.clock_seconds),
            Some(sim.config.dt_seconds)
        );
        assert_eq!(
            sim.shared_positions.ball_history().last().map(|sample| (
                sample.tick,
                sample.clock_seconds,
                sample.position
            )),
            Some((1, sim.config.dt_seconds, sim.ball.position))
        );
    }

    #[test]
    fn ball_agent_tracks_acceleration_and_rolling_history() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 204,
            ..Default::default()
        });
        for player in &mut sim.players {
            player.position = Vec2::new(2.0, 2.0);
            player.velocity = Vec2::zero();
        }
        sim.ball.holder = None;
        sim.ball.position = Vec2::new(20.0, 60.0);
        sim.ball.velocity = Vec2::new(10.0, 0.0);
        sim.ball.acceleration = Vec2::zero();
        sim.ball.jerk = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);
        sim.pending_pass = None;
        sim.pending_shot = None;
        sim.ball.position_history.clear();
        sim.ball.record_position_history(0, 0.0);

        for _ in 0..60 {
            sim.integrate_ball();
            sim.tick += 1;
            sim.clock_seconds += sim.config.dt_seconds;
            sim.record_ball_position_history();
        }

        assert_eq!(sim.ball.position_history.len(), BALL_POSITION_HISTORY_LIMIT);
        assert_eq!(
            sim.ball
                .position_history
                .back()
                .map(|sample| sample.position),
            Some(sim.ball.position)
        );
        assert!(sim.ball.velocity.len() < 10.0);
        assert!(sim.ball.acceleration.x <= 0.0);
        assert!(sim.ball.jerk.len().is_finite());
        assert_eq!(
            sim.ball.position_history.back().map(|sample| sample.jerk),
            Some(sim.ball.jerk)
        );
        assert!(sim
            .ball
            .history_velocity_estimate(sim.config.dt_seconds)
            .len()
            .is_finite());
        assert!(sim
            .ball
            .history_acceleration_estimate(sim.config.dt_seconds)
            .len()
            .is_finite());
        assert!(sim
            .ball
            .history_jerk_estimate(sim.config.dt_seconds)
            .len()
            .is_finite());

        let snapshot = WorldSnapshot::from_match(&sim);
        assert_eq!(
            snapshot.ball_position_history().len(),
            BALL_POSITION_HISTORY_LIMIT
        );
        assert_eq!(
            snapshot
                .ball_position_history()
                .last()
                .map(|sample| sample.position),
            Some(sim.ball.position)
        );
        assert_eq!(snapshot.ball.acceleration, sim.ball.acceleration);
        assert_eq!(snapshot.ball.jerk, sim.ball.jerk);
        assert_eq!(sim.to_frame().ball.acceleration, sim.ball.acceleration);
        assert_eq!(sim.to_frame().ball.jerk, sim.ball.jerk);
    }

    #[test]
    fn ball_history_kinematics_use_sample_clock_deltas() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 205,
            ..Default::default()
        });
        sim.ball.velocity = Vec2::new(-1.0, 0.0);
        sim.ball.acceleration = Vec2::new(-2.0, 0.0);
        sim.ball.jerk = Vec2::new(-3.0, 0.0);
        sim.ball.position_history.clear();

        for (tick, clock_seconds, x) in
            [(0, 0.0, 0.0), (1, 0.2, 2.0), (2, 0.5, 8.0), (3, 0.9, 20.0)]
        {
            sim.ball.position_history.push_back(BallPositionSample {
                tick,
                clock_seconds,
                position: Vec2::new(x, 12.0),
                velocity: Vec2::zero(),
                acceleration: Vec2::zero(),
                jerk: Vec2::zero(),
                curl_acceleration: Vec2::zero(),
                altitude_yards: 0.0,
                holder: None,
                last_touch_team: None,
            });
        }

        let velocity = sim.ball.history_velocity_estimate(0.1);
        let acceleration = sim.ball.history_acceleration_estimate(0.1);
        let jerk = sim.ball.history_jerk_estimate(0.1);

        assert!(
            (velocity.x - 30.0).abs() < 1e-9,
            "velocity should use latest sample delta, got {}",
            velocity.x
        );
        assert!(
            (acceleration.x - 28.571_428_571_428_573).abs() < 1e-9,
            "acceleration should use uneven sample deltas, got {}",
            acceleration.x
        );
        assert!(
            (jerk.x + 38.095_238_095_238_11).abs() < 1e-9,
            "jerk should use uneven acceleration midpoint deltas, got {}",
            jerk.x
        );
    }

