    #[test]
    fn team_brain_detects_attacking_numbers_up_and_raises_urgency() {
        let mut sim = home_numbers_up_overload_match();
        let snapshot = WorldSnapshot::from_match(&sim);
        let overload = attacking_overload_profile(&snapshot, Team::Home);
        let neutral = tactical_directive_for_team(
            Team::Home,
            TacticalPhase::HomeBuildUp,
            Some(Team::Home),
            sim.ball.position,
            0,
            DEFAULT_FIELD_WIDTH_YARDS,
            DEFAULT_FIELD_LENGTH_YARDS,
            DefensiveCoverProfile::default(),
            AttackingOverloadProfile::default(),
        );
        let urgent = tactical_directive_for_team(
            Team::Home,
            TacticalPhase::HomeBuildUp,
            Some(Team::Home),
            sim.ball.position,
            0,
            DEFAULT_FIELD_WIDTH_YARDS,
            DEFAULT_FIELD_LENGTH_YARDS,
            DefensiveCoverProfile::default(),
            overload,
        );
        let mut rng = mulberry32(909);
        sim.central_brain.run_time_step(&snapshot, &mut rng);

        assert_eq!(overload.attackers, 5);
        assert_eq!(overload.defenders, 1);
        assert!(overload.advantage > 0);
        assert!(overload.score > 0.70);
        assert_eq!(
            sim.central_brain.home_directive.attacking_numbers_advantage,
            4
        );
        assert!(sim.central_brain.home_directive.attacking_overload_score > 0.70);
        assert!(urgent.press_intensity > neutral.press_intensity);
        assert!(urgent.carry_priority > neutral.carry_priority);
        assert!(urgent.risk_tolerance > neutral.risk_tolerance);
    }

    #[test]
    fn team_brain_detects_route_one_numbers_up_from_projected_loose_ball() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        for player in &mut sim.players {
            player.position = match player.team {
                Team::Home => Vec2::new(4.0, 34.0),
                Team::Away => Vec2::new(76.0, 112.0),
            };
            player.velocity = Vec2::zero();
        }
        sim.players[6].position = Vec2::new(42.0, 74.0);
        sim.players[7].position = Vec2::new(34.0, 79.0);
        sim.players[8].position = Vec2::new(48.0, 82.0);
        sim.players[9].position = Vec2::new(36.0, 94.0);
        sim.players[10].position = Vec2::new(50.0, 96.0);
        sim.players[12].position = Vec2::new(42.0, 90.0);
        sim.ball.holder = None;
        sim.ball.position = Vec2::new(40.0, 42.0);
        sim.ball.velocity = Vec2::new(8.0, 18.0);
        sim.ball.altitude_yards = 0.05;
        sim.ball.last_touch_team = Some(Team::Home);
        sim.ball.last_decision = Some(BallDecisionTrace {
            tick: sim.tick,
            action: "route-one".to_string(),
            position: sim.ball.position,
            velocity: sim.ball.velocity,
            acceleration: sim.ball.acceleration,
            jerk: sim.ball.jerk,
            curl_acceleration: sim.ball.curl_acceleration,
            altitude_yards: sim.ball.altitude_yards,
            holder: None,
            scheduled_index: None,
            operation_order: ball_agent_operation_order(sim.tick, "route-one", None),
        });

        let snapshot = WorldSnapshot::from_match(&sim);
        let projected = snapshot
            .projected_loose_ball_target()
            .expect("route-one ball should project a recovery point");
        let home_overload = attacking_overload_profile(&snapshot, Team::Home);
        let away_overload = attacking_overload_profile(&snapshot, Team::Away);
        let mut rng = mulberry32(911);
        sim.central_brain.run_time_step(&snapshot, &mut rng);
        let after = WorldSnapshot::from_match(&sim);
        let runner_observation = after.observation_for(9);

        assert_eq!(snapshot.controlled_possession_team(), None);
        assert_eq!(snapshot.possession_team(), Some(Team::Home));
        assert!(projected.y > sim.ball.position.y + 30.0);
        assert_eq!(home_overload.attackers, 5);
        assert_eq!(home_overload.defenders, 1);
        assert_eq!(home_overload.advantage, 4);
        assert!(home_overload.score > 0.70);
        assert_eq!(away_overload.score, 0.0);
        assert_eq!(
            sim.central_brain.home_directive.attacking_numbers_advantage,
            4
        );
        assert!(sim.central_brain.home_directive.attacking_overload_score > 0.70);
        assert_eq!(
            sim.central_brain.away_directive.attacking_overload_score,
            0.0
        );
        assert_eq!(runner_observation.attacking_numbers_advantage, 4);
        assert!(runner_observation.attacking_overload_score > 0.70);
    }

    #[test]
    fn pomdp_and_q_state_track_attacking_numbers_up_context() {
        let mut sim = home_numbers_up_overload_match();
        let before = WorldSnapshot::from_match(&sim);
        let mut rng = mulberry32(910);
        sim.central_brain.run_time_step(&before, &mut rng);
        let snapshot = WorldSnapshot::from_match(&sim);

        let observation = snapshot.observation_for(6);
        assert_eq!(observation.attacking_overload_attackers, 5);
        assert_eq!(observation.attacking_overload_defenders, 1);
        assert_eq!(observation.attacking_numbers_advantage, 4);
        assert!(observation.attacking_overload_score > 0.70);
        assert_eq!(observation.team_brain_mode, TeamBrainMode::BuildUp);
        assert_eq!(
            observation.team_brain_defensive_cover_target,
            snapshot
                .tactical_directive(Team::Home)
                .defensive_cover_target
        );
        assert_eq!(
            observation.team_brain_defensive_cover_actual,
            snapshot
                .tactical_directive(Team::Home)
                .defensive_cover_actual
        );

        let overloaded_state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(6),
            &observation,
            Team::Home,
            sim.players[6].role,
        );
        let mut neutral_observation = observation.clone();
        neutral_observation.attacking_overload_attackers = 0;
        neutral_observation.attacking_overload_defenders = 0;
        neutral_observation.attacking_numbers_advantage = 0;
        neutral_observation.attacking_overload_score = 0.0;
        let neutral_state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(6),
            &neutral_observation,
            Team::Home,
            sim.players[6].role,
        );

        assert_eq!(overloaded_state.attacking_numbers_advantage_bin, 4);
        assert_eq!(overloaded_state.attacking_overload_score_bin, 4);
        assert_eq!(overloaded_state.team_brain_mode, TeamBrainMode::BuildUp);
        assert!(
            overloaded_state.team_brain_press_bin > 0,
            "team brain press should be binned for fast lookup"
        );
        assert!(
            overloaded_state.team_brain_risk_bin > 0,
            "team brain risk should be binned for fast lookup"
        );
        assert_eq!(neutral_state.attacking_numbers_advantage_bin, 0);
        assert_eq!(neutral_state.attacking_overload_score_bin, 0);
        assert_ne!(overloaded_state, neutral_state);

        let defending_observation = snapshot.observation_for(12);
        assert_eq!(defending_observation.attacking_numbers_advantage, 0);
        assert_eq!(defending_observation.attacking_overload_score, 0.0);
    }

    #[test]
    fn pomdp_and_q_state_track_forward_support_context() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 912,
            ..Default::default()
        });
        let striker = 9;
        for player in &mut sim.players {
            player.velocity = Vec2::zero();
            player.position = match player.team {
                Team::Home => Vec2::new(10.0 + player.id as f64, 42.0),
                Team::Away => Vec2::new(74.0, 98.0 + (player.id - 11) as f64 * 0.4),
            };
            player.home_position = player.position;
        }
        sim.players[striker].position = Vec2::new(40.0, 78.0);
        sim.players[striker].home_position = sim.players[striker].position;
        sim.ball.holder = Some(striker);
        sim.ball.position = sim.players[striker].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);

        let isolated_snapshot = WorldSnapshot::from_match(&sim);
        let isolated = isolated_snapshot.observation_for(striker);
        assert_eq!(isolated.teammates_ahead, 0);
        assert_eq!(isolated.visible_forward_pass_options, 0);
        assert!(
            isolated.nearest_forward_teammate_distance_yards >= DEFAULT_FIELD_LENGTH_YARDS - 1.0
        );

        sim.players[10].position = Vec2::new(43.0, 94.0);
        sim.players[10].home_position = sim.players[10].position;
        let supported_snapshot = WorldSnapshot::from_match(&sim);
        let supported = supported_snapshot.observation_for(striker);
        assert_eq!(supported.teammates_ahead, 1);
        assert!(
            supported.visible_forward_pass_options >= 1,
            "forward receiver should be visible to the ball holder"
        );
        assert!(
            supported.best_forward_pass_receiver_openness > 0.50,
            "open forward outlet should be represented as a high-quality support option"
        );
        assert!(supported.nearest_forward_teammate_distance_yards < 18.0);

        let isolated_key = SoccerQStateKey::from_parts(
            &isolated_snapshot.mdp_state_for_player(striker),
            &isolated,
            Team::Home,
            sim.players[striker].role,
        );
        let supported_key = SoccerQStateKey::from_parts(
            &supported_snapshot.mdp_state_for_player(striker),
            &supported,
            Team::Home,
            sim.players[striker].role,
        );

        assert_eq!(isolated_key.teammates_ahead_bin, 0);
        assert!(supported_key.teammates_ahead_bin > isolated_key.teammates_ahead_bin);
        assert!(
            supported_key.visible_forward_pass_options_bin
                > isolated_key.visible_forward_pass_options_bin
        );
        assert!(
            supported_key.best_forward_pass_receiver_openness_bin
                > isolated_key.best_forward_pass_receiver_openness_bin
        );
        assert!(
            isolated_key.nearest_forward_teammate_distance_bin
                > supported_key.nearest_forward_teammate_distance_bin
        );
        assert_ne!(isolated_key, supported_key);
    }

    #[test]
    fn pomdp_q_state_and_neural_features_track_team_shape_context() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14231,
            ..Default::default()
        });
        let holder = 5;
        let ball_position = Vec2::new(40.0, 62.0);
        for player in &mut sim.players {
            player.velocity = Vec2::zero();
            player.position = match player.team {
                Team::Home => {
                    ball_position
                        + Vec2::new((player.id % 3) as f64 - 1.0, (player.id % 4) as f64 - 1.5)
                }
                Team::Away => Vec2::new(72.0, 94.0),
            };
            player.home_position = player.position;
        }
        for player in sim
            .players
            .iter_mut()
            .filter(|player| player.team == Team::Home)
        {
            player.velocity = Vec2::new(0.0, 3.4);
        }
        sim.players[holder].position = ball_position;
        sim.ball.holder = Some(holder);
        sim.ball.position = ball_position;
        sim.ball.last_touch_team = Some(Team::Home);

        let compact_snapshot = WorldSnapshot::from_match(&sim);
        let compact_observation = compact_snapshot.observation_for(holder);
        let mdp_state = compact_snapshot.mdp_state_for_player(holder);
        let compact_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &compact_observation,
            Team::Home,
            sim.players[holder].role,
        );

        for player in sim
            .players
            .iter_mut()
            .filter(|player| player.team == Team::Home)
        {
            player.position = Vec2::new(8.0 + player.id as f64 * 6.0, 20.0 + player.id as f64);
            player.home_position = player.position;
            player.velocity = Vec2::new(0.0, -3.2);
        }
        sim.players[holder].position = ball_position;
        sim.players[holder].home_position = ball_position;
        sim.players[holder].velocity = Vec2::new(0.0, -3.2);
        sim.ball.position = ball_position;

        let stretched_snapshot = WorldSnapshot::from_match(&sim);
        let stretched_observation = stretched_snapshot.observation_for(holder);
        let stretched_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &stretched_observation,
            Team::Home,
            sim.players[holder].role,
        );

        assert!(compact_observation.team_centroid_to_ball_yards < 3.0);
        assert!(stretched_observation.team_centroid_to_ball_yards > 20.0);
        assert!(compact_observation.team_spread_yards < 4.0);
        assert!(stretched_observation.team_spread_yards > compact_observation.team_spread_yards);
        assert_eq!(compact_observation.team_players_near_ball, 11);
        assert_eq!(stretched_observation.team_players_near_ball, 1);
        assert!(compact_observation.team_forward_velocity_yps > 3.0);
        assert!(stretched_observation.team_forward_velocity_yps < -3.0);
        assert!(
            compact_key.team_centroid_ball_distance_bin
                < stretched_key.team_centroid_ball_distance_bin
        );
        assert!(compact_key.team_spread_bin < stretched_key.team_spread_bin);
        assert!(compact_key.team_players_near_ball_bin > stretched_key.team_players_near_ball_bin);
        assert!(compact_key.team_forward_velocity_bin > stretched_key.team_forward_velocity_bin);
        assert_ne!(compact_key, stretched_key);

        let decision = test_decision_trace(&compact_snapshot, holder, "carry-forward");
        let transition = SoccerLearningTransition {
            tick: compact_snapshot.tick,
            player_id: holder,
            team: Team::Home,
            role: sim.players[holder].role,
            state: decision.mdp_state.clone(),
            observation: compact_observation,
            belief: decision.belief.clone(),
            action: decision.action.clone(),
            action_target: decision.action_target.clone(),
            decision_context: SoccerDecisionContext::default(),
            tactical_trace: SoccerTacticalLearningTrace::default(),
            reward: 1.0,
            next_state: compact_snapshot.mdp_state_for_player(holder),
            next_observation: compact_snapshot.observation_for(holder),
            done: false,
        };
        let features = soccer_neural_transition_features(&transition);
        assert_eq!(features.len(), SOCCER_NEURAL_FEATURE_DIM);
        assert_eq!(
            features[SOCCER_NEURAL_FEATURE_TEAM_CENTROID_BALL_DISTANCE],
            0.0
        );
        assert_eq!(features[SOCCER_NEURAL_FEATURE_TEAM_SPREAD], 0.0);
        assert!(
            features[SOCCER_NEURAL_FEATURE_TEAM_PLAYERS_NEAR_BALL] >= 1.0,
            "all nearby teammates should produce maxed near-ball support feature"
        );
        assert!(
            features[SOCCER_NEURAL_FEATURE_TEAM_FORWARD_VELOCITY] > 0.50,
            "team forward velocity should be visible to the neural learner"
        );
    }

    #[test]
    fn pomdp_and_q_state_track_actor_motion_context() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14232,
            ..Default::default()
        });
        let actor = 6;
        for player in &mut sim.players {
            player.velocity = Vec2::zero();
            player.acceleration = Vec2::zero();
            player.jerk = Vec2::zero();
            player.movement_gait = MovementGait::Stand;
        }
        sim.ball.holder = Some(actor);
        sim.ball.position = sim.players[actor].position;
        sim.ball.velocity = Vec2::new(8.0, 18.0);
        sim.ball.acceleration = Vec2::new(0.0, 6.0);
        sim.ball.jerk = Vec2::new(0.0, 24.0);
        sim.ball.altitude_yards = 4.2;
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[actor].velocity = Vec2::new(0.8, 8.2);
        sim.players[actor].acceleration = Vec2::new(0.4, 5.4);
        sim.players[actor].jerk = Vec2::new(0.0, 13.2);
        sim.players[actor].movement_gait = MovementGait::Sprint;

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(actor);
        let mdp_state = snapshot.mdp_state_for_player(actor);
        let sprint_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &observation,
            Team::Home,
            sim.players[actor].role,
        );

        assert_eq!(observation.movement_gait, MovementGait::Sprint);
        assert!(observation.actor_speed_yps > 8.0);
        assert!(observation.actor_acceleration_yps2 > 5.0);
        assert!(observation.actor_jerk_yps3 > 13.0);
        assert!(observation.ball_speed_yps > 17.0);
        assert!(observation.ball_acceleration_yps2 > 5.0);
        assert!(observation.ball_jerk_yps3 > 23.0);
        assert!(observation.ball_forward_velocity_yps > 17.0);
        assert!(observation.ball_lateral_speed_yps > 7.0);
        assert!(observation.ball_altitude_yards > 4.0);
        assert!(observation.ball_airborne);
        assert_eq!(sprint_key.movement_gait, MovementGait::Sprint);
        assert!(sprint_key.actor_speed_bin >= 4);
        assert!(sprint_key.actor_acceleration_bin >= 3);
        assert!(sprint_key.actor_jerk_bin >= 3);
        assert!(sprint_key.ball_speed_bin >= 3);
        assert!(sprint_key.ball_acceleration_bin >= 3);
        assert!(sprint_key.ball_jerk_bin >= 3);
        assert!(sprint_key.ball_forward_velocity_bin >= 4);
        assert!(sprint_key.ball_lateral_speed_bin >= 2);
        assert!(sprint_key.ball_altitude_bin >= 3);
        assert!(sprint_key.ball_airborne);

        let mut standing_observation = observation.clone();
        standing_observation.movement_gait = MovementGait::Stand;
        standing_observation.actor_speed_yps = 0.0;
        standing_observation.actor_acceleration_yps2 = 0.0;
        standing_observation.actor_jerk_yps3 = 0.0;
        let standing_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &standing_observation,
            Team::Home,
            sim.players[actor].role,
        );

        assert_eq!(standing_key.movement_gait, MovementGait::Stand);
        assert!(sprint_key.actor_speed_bin > standing_key.actor_speed_bin);
        assert!(sprint_key.actor_acceleration_bin > standing_key.actor_acceleration_bin);
        assert!(sprint_key.actor_jerk_bin > standing_key.actor_jerk_bin);
        assert_ne!(sprint_key, standing_key);

        let mut dead_ball_observation = observation.clone();
        dead_ball_observation.ball_speed_yps = 0.0;
        dead_ball_observation.ball_acceleration_yps2 = 0.0;
        dead_ball_observation.ball_jerk_yps3 = 0.0;
        dead_ball_observation.ball_forward_velocity_yps = 0.0;
        dead_ball_observation.ball_lateral_speed_yps = 0.0;
        dead_ball_observation.ball_altitude_yards = 0.0;
        dead_ball_observation.ball_airborne = false;
        let dead_ball_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &dead_ball_observation,
            Team::Home,
            sim.players[actor].role,
        );
        assert!(sprint_key.ball_speed_bin > dead_ball_key.ball_speed_bin);
        assert!(sprint_key.ball_acceleration_bin > dead_ball_key.ball_acceleration_bin);
        assert!(sprint_key.ball_jerk_bin > dead_ball_key.ball_jerk_bin);
        assert!(sprint_key.ball_forward_velocity_bin > dead_ball_key.ball_forward_velocity_bin);
        assert!(sprint_key.ball_lateral_speed_bin > dead_ball_key.ball_lateral_speed_bin);
        assert!(sprint_key.ball_altitude_bin > dead_ball_key.ball_altitude_bin);
        assert_ne!(sprint_key.ball_airborne, dead_ball_key.ball_airborne);
        assert_ne!(sprint_key, dead_ball_key);

        let mut backward_ball_observation = observation.clone();
        backward_ball_observation.ball_forward_velocity_yps = -18.0;
        backward_ball_observation.ball_lateral_speed_yps = 0.2;
        let backward_ball_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &backward_ball_observation,
            Team::Home,
            sim.players[actor].role,
        );
        assert!(sprint_key.ball_forward_velocity_bin > backward_ball_key.ball_forward_velocity_bin);
        assert!(sprint_key.ball_lateral_speed_bin > backward_ball_key.ball_lateral_speed_bin);
        assert_ne!(sprint_key, backward_ball_key);

        let mut policy = SoccerQPolicy::default();
        policy.set_action_value(sprint_key.clone(), "overlap-run", 5.0);
        assert_eq!(
            policy.best_action_hierarchical(&sprint_key).as_deref(),
            Some("overlap-run")
        );
        assert!(
            policy.best_action_hierarchical(&standing_key).is_none(),
            "actor motion bins should prevent reusing sprint overlap policy for a standing player"
        );
        assert!(
            policy.best_action_hierarchical(&dead_ball_key).is_none(),
            "ball motion bins should prevent reusing a live-ball sprint policy for a dead ball"
        );
        assert!(
            policy
                .best_action_hierarchical(&backward_ball_key)
                .is_none(),
            "ball travel direction should prevent reusing forward-ball policy for a backward ball"
        );

        let mut loose_observation = observation.clone();
        loose_observation.has_ball = false;
        loose_observation.loose_ball = true;
        loose_observation.loose_ball_fifty_fifty = false;
        loose_observation.loose_ball_team_time_advantage_seconds = 0.55;
        loose_observation.loose_ball_player_time_to_ball_seconds = 0.65;
        let loose_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &loose_observation,
            Team::Home,
            sim.players[actor].role,
        );
        let mut late_loose_observation = loose_observation.clone();
        late_loose_observation.loose_ball_team_time_advantage_seconds = -0.80;
        late_loose_observation.loose_ball_player_time_to_ball_seconds = 3.25;
        let late_loose_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &late_loose_observation,
            Team::Home,
            sim.players[actor].role,
        );
        let mut level_loose_observation = loose_observation.clone();
        level_loose_observation.loose_ball_fifty_fifty = true;
        level_loose_observation.loose_ball_team_time_advantage_seconds = 0.04;
        let level_loose_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &level_loose_observation,
            Team::Home,
            sim.players[actor].role,
        );
        assert!(loose_key.loose_ball);
        assert!(
            loose_key.loose_ball_team_time_advantage_bin
                > late_loose_key.loose_ball_team_time_advantage_bin
        );
        assert!(late_loose_key.loose_ball_player_time_bin > loose_key.loose_ball_player_time_bin);
        assert!(level_loose_key.loose_ball_fifty_fifty);
        assert_ne!(loose_key, late_loose_key);
        assert_ne!(loose_key, level_loose_key);
        policy.set_action_value(loose_key.clone(), "contest-loose-ball", 4.0);
        assert_eq!(
            policy.best_action_hierarchical(&loose_key).as_deref(),
            Some("contest-loose-ball")
        );
        assert!(
            policy.best_action_hierarchical(&late_loose_key).is_none(),
            "loose-ball policies should distinguish first-to-ball races from late chases"
        );
        assert!(
            policy.best_action_hierarchical(&level_loose_key).is_none(),
            "loose-ball policies should distinguish clean races from 50:50 duels"
        );
    }

    #[test]
    fn pomdp_and_q_state_track_loose_ball_race_advantage() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14233,
            ..Default::default()
        });
        let home_runner_id = sim
            .players
            .iter()
            .find(|player| player.team == Team::Home && player.role == PlayerRole::Midfielder)
            .map(|player| player.id)
            .expect("home runner");
        let away_runner_id = sim
            .players
            .iter()
            .find(|player| player.team == Team::Away && player.role == PlayerRole::Midfielder)
            .map(|player| player.id)
            .expect("away runner");
        let ball_position = Vec2::new(40.0, 55.0);
        for player in &mut sim.players {
            player.position = if player.team == Team::Home {
                Vec2::new(8.0, 10.0)
            } else {
                Vec2::new(72.0, 110.0)
            };
            player.velocity = Vec2::zero();
            player.acceleration = Vec2::zero();
            player.jerk = Vec2::zero();
            player.movement_gait = MovementGait::Stand;
        }
        sim.players[home_runner_id].position = Vec2::new(40.0, 53.2);
        sim.players[home_runner_id].velocity = Vec2::new(0.0, 3.2);
        sim.players[away_runner_id].position = Vec2::new(40.0, 62.5);
        sim.players[away_runner_id].velocity = Vec2::new(0.0, -0.3);
        sim.ball.holder = None;
        sim.ball.position = ball_position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.acceleration = Vec2::zero();
        sim.ball.jerk = Vec2::zero();
        sim.ball.altitude_yards = BALL_ROLLING_ALTITUDE_YARDS;

        let snapshot = WorldSnapshot::from_match(&sim);
        let home_observation = snapshot.observation_for(home_runner_id);
        let away_observation = snapshot.observation_for(away_runner_id);
        let home_key = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(home_runner_id),
            &home_observation,
            Team::Home,
            sim.players[home_runner_id].role,
        );
        let away_key = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(away_runner_id),
            &away_observation,
            Team::Away,
            sim.players[away_runner_id].role,
        );

        assert!(home_observation.loose_ball);
        assert!(away_observation.loose_ball);
        assert!(!home_observation.loose_ball_fifty_fifty);
        assert!(home_observation.loose_ball_team_time_advantage_seconds > 0.25);
        assert!(away_observation.loose_ball_team_time_advantage_seconds < -0.25);
        assert!(
            home_observation.loose_ball_player_time_to_ball_seconds
                < away_observation.loose_ball_player_time_to_ball_seconds
        );
        assert!(home_key.loose_ball);
        assert!(away_key.loose_ball);
        assert!(
            home_key.loose_ball_team_time_advantage_bin
                > away_key.loose_ball_team_time_advantage_bin
        );
        assert!(away_key.loose_ball_player_time_bin > home_key.loose_ball_player_time_bin);
    }

    #[test]
    fn q_policy_keys_separate_same_action_by_team_brain_directive() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1423,
            ..Default::default()
        });
        sim.ball.holder = Some(5);
        sim.ball.position = sim.players[5].position;
        sim.ball.last_touch_team = Some(Team::Home);
        let snapshot = WorldSnapshot::from_match(&sim);
        let mdp_state = snapshot.mdp_state_for_player(5);
        let mut urgent_observation = snapshot.observation_for(5);
        urgent_observation.team_brain_press_intensity = 0.92;
        urgent_observation.team_brain_risk_tolerance = 0.88;
        urgent_observation.team_brain_defensive_cover_target = 4;
        urgent_observation.team_brain_defensive_cover_actual = 4;
        let urgent_state = SoccerQStateKey::from_parts(
            &mdp_state,
            &urgent_observation,
            Team::Home,
            sim.players[5].role,
        );

        let mut patient_observation = urgent_observation.clone();
        patient_observation.team_brain_press_intensity = 0.28;
        patient_observation.team_brain_risk_tolerance = 0.22;
        patient_observation.team_brain_defensive_cover_target = 1;
        patient_observation.team_brain_defensive_cover_actual = 1;
        let patient_state = SoccerQStateKey::from_parts(
            &mdp_state,
            &patient_observation,
            Team::Home,
            sim.players[5].role,
        );

        assert_eq!(urgent_state.team_brain_mode, patient_state.team_brain_mode);
        assert_ne!(
            urgent_state.team_brain_press_bin,
            patient_state.team_brain_press_bin
        );
        assert_ne!(
            urgent_state.team_brain_risk_bin,
            patient_state.team_brain_risk_bin
        );
        assert_ne!(
            urgent_state.team_brain_cover_target_bin,
            patient_state.team_brain_cover_target_bin
        );
        assert_ne!(urgent_state, patient_state);

        let mut policy = SoccerQPolicy::default();
        policy.set_action_value(urgent_state.clone(), "route-one", 5.0);
        assert_eq!(
            policy.best_action_hierarchical(&urgent_state).as_deref(),
            Some("route-one")
        );
        assert!(
            policy.best_action_hierarchical(&patient_state).is_none(),
            "team brain directive bins should prevent reusing urgent policy in patient state"
        );
    }

    #[test]
    fn q_policy_rejects_non_finite_updates_and_reads() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14232,
            ..Default::default()
        });
        let player_id = 5;
        sim.ball.holder = Some(player_id);
        sim.ball.position = sim.players[player_id].position;
        sim.ball.last_touch_team = Some(Team::Home);
        let snapshot = WorldSnapshot::from_match(&sim);
        let decision = test_decision_trace(&snapshot, player_id, "pass");
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(player_id),
            &snapshot.observation_for(player_id),
            Team::Home,
            sim.players[player_id].role,
        );

        let mut policy = SoccerQPolicy::default();
        assert!(!policy.set_action_value(state.clone(), "shoot", f64::NAN));
        assert!(!policy.set_action_value(state.clone(), "pass", f64::INFINITY));
        assert!(!policy.set_target_value(
            state.clone(),
            "pass",
            pitch_grid_address(
                sim.players[7].position,
                snapshot.field_width,
                snapshot.field_length,
            ),
            f64::NEG_INFINITY,
        ));
        assert!(!policy.set_action_value_for_snapshot(&snapshot, player_id, "shoot", f64::NAN));
        assert!(!policy.set_target_value_for_snapshot(
            &snapshot,
            player_id,
            "pass",
            sim.players[7].position,
            f64::NAN
        ));

        assert!(policy.q_value(&state, "shoot").is_none());
        assert!(policy.q_value(&state, "pass").is_none());
        assert!(policy.entries().is_empty());
        assert!(policy.target_entries().is_empty());
        assert!(policy.best_action_hierarchical(&state).is_none());

        assert!(policy.set_action_value(state.clone(), "dribble", SOCCER_Q_VALUE_LIMIT * 10.0));
        assert_eq!(
            policy.q_value(&state, "dribble"),
            Some(SOCCER_Q_VALUE_LIMIT)
        );
        assert_eq!(
            policy.best_action_hierarchical(&state).as_deref(),
            Some("dribble")
        );

        let shoot_key = SoccerQActionKey {
            state: state.clone(),
            action: "shoot".to_string(),
        };
        assert!(policy.set_action_value(state.clone(), "shoot", 4.0));
        policy.q_values.insert(shoot_key, f64::NAN);
        assert!(policy.q_value(&state, "shoot").is_none());
        assert_eq!(
            policy.best_action_hierarchical(&state).as_deref(),
            Some("dribble"),
            "indexed stale non-finite values should be skipped during action selection"
        );
        assert!(policy.entries().iter().all(|entry| entry.value.is_finite()));

        let mut transition = SoccerLearningTransition {
            tick: snapshot.tick,
            player_id,
            team: Team::Home,
            role: sim.players[player_id].role,
            state: decision.mdp_state.clone(),
            observation: decision.observation.clone(),
            belief: decision.belief.clone(),
            action: decision.action.clone(),
            action_target: decision.action_target.clone(),
            decision_context: SoccerDecisionContext::default(),
            tactical_trace: SoccerTacticalLearningTrace::default(),
            reward: f64::NAN,
            next_state: snapshot.mdp_state_for_player(player_id),
            next_observation: snapshot.observation_for(player_id),
            done: false,
        };
        let mut update_policy = SoccerQPolicy::default();
        update_policy.update(&transition);
        assert!(update_policy.entries().is_empty());
        assert_eq!(update_policy.visit_count(), 0);

        transition.reward = f64::INFINITY;
        update_policy.update(&transition);
        assert!(update_policy.entries().is_empty());
        assert_eq!(update_policy.visit_count(), 0);

        let mut finite_transition = transition.clone();
        finite_transition.reward = 1.0;
        let update_key = SoccerQActionKey {
            state: SoccerQStateKey::from_transition(&finite_transition),
            action: normalize_soccer_action_label(&finite_transition.action).to_string(),
        };
        assert!(update_policy.set_action_value(update_key.state.clone(), &update_key.action, 0.0));
        update_policy.visits.insert(update_key.clone(), u32::MAX);
        update_policy.update(&finite_transition);
        assert_eq!(
            update_policy.visits.get(&update_key).copied(),
            Some(u32::MAX),
            "long-running Q learning should saturate visits instead of overflowing"
        );
        if let Some(grid) = finite_transition
            .action_target
            .as_ref()
            .and_then(|target| target.grid)
        {
            let target_key = SoccerQTargetKey::from_state_action_grid(
                update_key.state.clone(),
                &update_key.action,
                grid,
            );
            assert!(update_policy.set_target_value(
                update_key.state.clone(),
                &update_key.action,
                grid,
                0.0
            ));
            update_policy
                .target_visits
                .insert(target_key.clone(), u32::MAX);
            update_policy.update(&finite_transition);
            assert_eq!(
                update_policy.target_visits.get(&target_key).copied(),
                Some(u32::MAX),
                "target-grid visits should saturate instead of overflowing"
            );
        }
    }

    #[test]
    fn q_state_buckets_treat_nan_observation_metrics_as_neutral() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14233,
            ..Default::default()
        });
        let player_id = 5;
        sim.ball.holder = Some(player_id);
        sim.ball.position = sim.players[player_id].position;
        sim.ball.last_touch_team = Some(Team::Home);
        let snapshot = WorldSnapshot::from_match(&sim);
        let mdp_state = snapshot.mdp_state_for_player(player_id);
        let mut observation = snapshot.observation_for(player_id);
        observation.actor_speed_yps = f64::NAN;
        observation.actor_acceleration_yps2 = f64::NAN;
        observation.ball_jerk_yps3 = f64::NAN;
        observation.ball_forward_velocity_yps = f64::NAN;
        observation.team_brain_press_intensity = f64::NAN;
        observation.shot_on_frame_probability = f64::NAN;
        observation.goalkeeper_ball_goal_line_alignment_score = f64::NAN;
        observation.defensive_line_break_threat = f64::NAN;
        observation.formation_lp_recommended_move_yards = f64::NAN;
        observation.formation_lp_pressure_weight = f64::NAN;

        let key = SoccerQStateKey::from_parts(
            &mdp_state,
            &observation,
            Team::Home,
            sim.players[player_id].role,
        );

        assert_eq!(key.actor_speed_bin, 0);
        assert_eq!(key.actor_acceleration_bin, 0);
        assert_eq!(key.ball_jerk_bin, 0);
        assert_eq!(key.ball_forward_velocity_bin, 0);
        assert_eq!(key.team_brain_press_bin, 0);
        assert_eq!(key.shot_on_frame_probability_bin, 0);
        assert_eq!(key.goalkeeper_ball_goal_line_alignment_bin, 0);
        assert_eq!(key.defensive_line_break_threat_bin, 0);
        assert_eq!(key.formation_lp_move_bin, 0);
        assert_eq!(key.formation_lp_pressure_bin, 0);

        observation.actor_speed_yps = f64::INFINITY;
        let high_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &observation,
            Team::Home,
            sim.players[player_id].role,
        );
        assert_eq!(high_key.actor_speed_bin, 5);

        observation.actor_speed_yps = f64::NEG_INFINITY;
        let low_key = SoccerQStateKey::from_parts(
            &mdp_state,
            &observation,
            Team::Home,
            sim.players[player_id].role,
        );
        assert_eq!(low_key.actor_speed_bin, 0);
    }

    #[test]
    fn pomdp_q_state_and_neural_features_track_team_flank_cross_policy() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14230,
            ..Default::default()
        });
        let holder = 6;
        sim.ball.holder = Some(holder);
        sim.ball.position = Vec2::new(5.0, 84.0);
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[holder].position = sim.ball.position;
        let mut directive = TeamTacticalDirective::neutral(
            Team::Home,
            sim.config.field_width_yards,
            sim.config.field_length_yards,
        );
        directive.flank_attack_policy = FlankAttackPolicy::PlayDownFlankHighCross;
        directive.flank_overlap_run_probability = 0.42;
        sim.central_brain.home_directive = directive;

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(holder);
        assert_eq!(
            observation.team_brain_flank_attack_policy,
            FlankAttackPolicy::PlayDownFlankHighCross
        );
        assert!((observation.team_brain_flank_overlap_run_probability - 0.42).abs() < 1e-9);

        let mdp_state = snapshot.mdp_state_for_player(holder);
        let high_state = SoccerQStateKey::from_parts(
            &mdp_state,
            &observation,
            Team::Home,
            sim.players[holder].role,
        );
        let mut low_observation = observation.clone();
        low_observation.team_brain_flank_attack_policy = FlankAttackPolicy::PlayDownFlankLowCross;
        let low_state = SoccerQStateKey::from_parts(
            &mdp_state,
            &low_observation,
            Team::Home,
            sim.players[holder].role,
        );

        assert_eq!(
            high_state.team_flank_attack_policy,
            FlankAttackPolicy::PlayDownFlankHighCross
        );
        assert_eq!(high_state.team_flank_overlap_bin, 3);
        assert_ne!(high_state, low_state);

        let mut policy = SoccerQPolicy::default();
        policy.set_action_value(high_state.clone(), "flank-high-cross", 6.0);
        assert_eq!(
            policy.best_action_hierarchical(&high_state).as_deref(),
            Some("flank-high-cross")
        );
        assert!(
            policy.best_action_hierarchical(&low_state).is_none(),
            "low-cross and high-cross team policies should not share learned choices"
        );

        let decision = test_decision_trace(&snapshot, holder, "flank-high-cross");
        let transition = SoccerLearningTransition {
            tick: snapshot.tick,
            player_id: holder,
            team: Team::Home,
            role: sim.players[holder].role,
            state: decision.mdp_state.clone(),
            observation,
            belief: decision.belief.clone(),
            action: decision.action.clone(),
            action_target: decision.action_target.clone(),
            decision_context: SoccerDecisionContext::default(),
            tactical_trace: SoccerTacticalLearningTrace::default(),
            reward: 1.0,
            next_state: snapshot.mdp_state_for_player(holder),
            next_observation: snapshot.observation_for(holder),
            done: false,
        };
        let features = soccer_neural_transition_features(&transition);
        assert_eq!(features.len(), SOCCER_NEURAL_FEATURE_DIM);
        assert_eq!(features[SOCCER_NEURAL_FEATURE_TEAM_FLANK_POLICY], 1.0);
        assert!(
            features[SOCCER_NEURAL_FEATURE_TEAM_FLANK_OVERLAP] > 0.0,
            "overlap probability bin should be visible to the neural learner"
        );
    }

