    #[test]
    fn formation_lp_guidance_tracks_role_line_shape_error() {
        let sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            learning_enabled: false,
            learning_logging_enabled: false,
            formation_lp_enabled: true,
            max_human_players: 0,
            ..Default::default()
        });
        let snapshot = WorldSnapshot::from_match(&sim);
        let directive =
            TeamTacticalDirective::neutral(Team::Home, snapshot.field_width, snapshot.field_length);
        let weights = soccer_formation_lp_objective_weights(&snapshot, Team::Home, &directive);
        let slots = soccer_formation_lp_slot_inputs(&snapshot, Team::Home, &directive, &weights);
        let mut guidance = slots
            .iter()
            .enumerate()
            .filter(|(_, slot)| slot.active)
            .map(|(slot_idx, slot)| SoccerFormationLpPlayerGuidance {
                team: Team::Home,
                player_id: slot.player_id,
                slot: slot_idx,
                current: slot.current,
                target: slot.anchor,
                formation_anchor: slot.anchor,
                pressure_target: slot.pressure_target,
                recommended_move: slot.anchor - slot.current,
                target_velocity: slot.velocity,
                target_acceleration: slot.acceleration,
                recommended_move_yards: slot.anchor.distance(slot.current),
                recommended_speed_yps: slot.velocity.len(),
                recommended_acceleration_yps2: slot.acceleration.len(),
                formation_error_yards: 0.0,
                movement_error_yards: slot.anchor.distance(slot.current),
                pair_error_yards: 0.0,
                role_line_error_yards: 0.0,
                pressure_error_yards: 0.0,
                fore_aft_speed_error_yps: 0.0,
                pressure_weight: slot.pressure_weight,
                speed_match_weight: slot.speed_match_weight,
                alignment_weight: slot.alignment_weight,
                reduced_cost_target_x: 0.0,
                reduced_cost_target_y: 0.0,
                solver_status: "test".to_string(),
                solver_objective: 0.0,
                solver_iterations: None,
                solver_elapsed_ms: 0.0,
                variable_count: 0,
                constraint_count: 0,
            })
            .collect::<Vec<_>>();

        annotate_formation_lp_role_line_errors(&mut guidance, &slots);
        assert!(guidance
            .iter()
            .all(|entry| entry.role_line_error_yards.is_finite()));

        let drifting_defender = slots
            .iter()
            .find(|slot| slot.active && slot.role == PlayerRole::Defender)
            .map(|slot| slot.player_id)
            .expect("home defender");
        let drift_entry = guidance
            .iter_mut()
            .find(|entry| entry.player_id == drifting_defender)
            .expect("defender guidance");
        drift_entry.target.y += DEFENDER_LINE_COHESION_TOLERANCE_YARDS + 12.0;

        annotate_formation_lp_role_line_errors(&mut guidance, &slots);
        let defender_error = guidance
            .iter()
            .find(|entry| entry.player_id == drifting_defender)
            .map(|entry| entry.role_line_error_yards)
            .unwrap_or(0.0);
        assert!(
            defender_error > 6.0,
            "LP role-line telemetry should flag a defender drifting out of line: {defender_error}"
        );
        assert!(guidance.iter().any(|entry| {
            slots
                .iter()
                .find(|slot| slot.player_id == entry.player_id)
                .is_some_and(|slot| {
                    matches!(slot.role, PlayerRole::Goalkeeper | PlayerRole::Forward)
                        && entry.role_line_error_yards == 0.0
                })
        }));
    }

    #[test]
    fn formation_lp_pair_objective_enforces_role_lines_and_respects_overlap_relief() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            learning_enabled: false,
            learning_logging_enabled: false,
            formation_lp_enabled: true,
            max_human_players: 0,
            ..Default::default()
        });
        sim.ball.holder = Some(7);
        sim.ball.position = sim.players[7].position;
        sim.ball.last_touch_team = Some(Team::Home);
        let snapshot = WorldSnapshot::from_match(&sim);
        let directive =
            TeamTacticalDirective::neutral(Team::Home, snapshot.field_width, snapshot.field_length);
        let weights = soccer_formation_lp_objective_weights(&snapshot, Team::Home, &directive);
        let slots = soccer_formation_lp_slot_inputs(&snapshot, Team::Home, &directive, &weights);
        let mut brain = SoccerFormationLpBrain::new(Team::Home);
        brain.update_problem_for_tick(&snapshot, &directive, &weights, &slots);

        for role in [PlayerRole::Defender, PlayerRole::Midfielder] {
            let role_slots = slots
                .iter()
                .enumerate()
                .filter(|(_, slot)| slot.active && slot.role == role)
                .map(|(slot_idx, _)| slot_idx)
                .take(2)
                .collect::<Vec<_>>();
            assert_eq!(role_slots.len(), 2, "expected two {role:?} slots");
            let pair = brain
                .pair_vars
                .iter()
                .find(|pair| {
                    (pair.a == role_slots[0] && pair.b == role_slots[1])
                        || (pair.a == role_slots[1] && pair.b == role_slots[0])
                })
                .expect("same-role pair vars");
            let x_weight = -brain.problem.c[pair.separation_slack_x];
            let y_weight = -brain.problem.c[pair.separation_slack_y];
            assert!(
                y_weight > x_weight + 0.04,
                "same-role {role:?} LP pair should prefer staying in-line: x={x_weight} y={y_weight}"
            );
        }

        let runner = 6;
        let teammate = 8;
        sim.players[runner].position = Vec2::new(55.0, 58.0);
        sim.players[teammate].position = Vec2::new(55.8, 58.4);
        sim.players[runner].velocity = Vec2::zero();
        let static_snapshot = WorldSnapshot::from_match(&sim);
        let static_weights =
            soccer_formation_lp_objective_weights(&static_snapshot, Team::Home, &directive);
        let static_slots = soccer_formation_lp_slot_inputs(
            &static_snapshot,
            Team::Home,
            &directive,
            &static_weights,
        );
        let static_runner_slot = static_slots
            .iter()
            .find(|slot| slot.player_id == runner)
            .expect("static runner slot");
        let static_teammate_slot = static_slots
            .iter()
            .find(|slot| slot.player_id == teammate)
            .expect("static teammate slot");
        let static_relief = soccer_formation_lp_pair_shape_relief(
            &static_snapshot,
            Team::Home,
            static_runner_slot,
            static_teammate_slot,
        );

        sim.players[runner].velocity = Vec2::new(0.0, 11.0);
        let overlap_snapshot = WorldSnapshot::from_match(&sim);
        let overlap_weights =
            soccer_formation_lp_objective_weights(&overlap_snapshot, Team::Home, &directive);
        let overlap_slots = soccer_formation_lp_slot_inputs(
            &overlap_snapshot,
            Team::Home,
            &directive,
            &overlap_weights,
        );
        let overlap_runner_slot = overlap_slots
            .iter()
            .find(|slot| slot.player_id == runner)
            .expect("overlap runner slot");
        let overlap_teammate_slot = overlap_slots
            .iter()
            .find(|slot| slot.player_id == teammate)
            .expect("overlap teammate slot");
        let overlap_relief = soccer_formation_lp_pair_shape_relief(
            &overlap_snapshot,
            Team::Home,
            overlap_runner_slot,
            overlap_teammate_slot,
        );

        assert!(
            static_relief < 0.05,
            "static close teammates should not get LP shape relief: {static_relief}"
        );
        assert!(
            overlap_relief > static_relief + 0.25,
            "high-speed overlap should soften LP pair shape pressure: static={static_relief} overlap={overlap_relief}"
        );
    }

    #[test]
    fn formation_lp_directive_signal_ignores_non_finite_guidance() {
        let mut directive = TeamTacticalDirective::neutral(
            Team::Home,
            DEFAULT_FIELD_WIDTH_YARDS,
            DEFAULT_FIELD_LENGTH_YARDS,
        );
        directive.press_intensity = f64::NAN;
        directive.risk_tolerance = f64::NAN;
        directive.defensive_cover_actual = 0;
        let snapshot = SoccerFormationLpTeamSnapshot {
            team: Team::Home,
            status: "optimal".to_string(),
            guided_players: 2,
            ..SoccerFormationLpTeamSnapshot::default()
        };
        let valid_guidance = SoccerFormationLpPlayerGuidance {
            team: Team::Home,
            player_id: 4,
            slot: 0,
            current: Vec2::new(30.0, 44.0),
            target: Vec2::new(31.0, 45.0),
            formation_anchor: Vec2::new(32.0, 46.0),
            pressure_target: Some(Vec2::new(31.5, 45.5)),
            recommended_move: Vec2::new(1.0, 1.0),
            target_velocity: Vec2::new(0.5, 0.5),
            target_acceleration: Vec2::new(0.1, 0.1),
            recommended_move_yards: 1.4,
            recommended_speed_yps: 0.7,
            recommended_acceleration_yps2: 0.14,
            formation_error_yards: 1.0,
            movement_error_yards: 1.4,
            pair_error_yards: 4.0,
            role_line_error_yards: 2.0,
            pressure_error_yards: 1.0,
            fore_aft_speed_error_yps: 0.2,
            pressure_weight: 0.60,
            speed_match_weight: 0.40,
            alignment_weight: 1.0,
            reduced_cost_target_x: 0.0,
            reduced_cost_target_y: 0.0,
            solver_status: "optimal".to_string(),
            solver_objective: 12.0,
            solver_iterations: Some(4),
            solver_elapsed_ms: 0.3,
            variable_count: 512,
            constraint_count: 700,
        };
        let mut bad_guidance = valid_guidance.clone();
        bad_guidance.player_id = 5;
        bad_guidance.pressure_weight = f64::NAN;
        bad_guidance.pair_error_yards = f64::INFINITY;

        apply_formation_lp_directive_signal(
            &mut directive,
            &snapshot,
            &[bad_guidance, valid_guidance],
        );

        assert!(directive.press_intensity.is_finite());
        assert!(directive.risk_tolerance.is_finite());
        assert_eq!(directive.defensive_cover_actual, 1);
        assert!((directive.press_intensity - 0.4896).abs() < 1e-9);
        assert!((directive.risk_tolerance - 0.40).abs() < 1e-9);
    }

    #[test]
    fn pomdp_observation_tracks_player_visibility() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let observer = 6;
        sim.players[observer].position = Vec2::new(40.0, 60.0);
        sim.players[observer].velocity = Vec2::new(3.0, 0.0);
        sim.ball.holder = None;
        sim.ball.position = Vec2::new(70.0, 60.0);
        sim.ball.velocity = Vec2::zero();
        for away in 11..22 {
            sim.players[away].position = Vec2::new(12.0, 60.0);
        }

        let snapshot = WorldSnapshot::from_match(&sim);
        assert!(snapshot.player_can_see_point(observer, sim.ball.position));
        let visible = snapshot.observation_for(observer);
        assert!(visible.visible_ball);
        assert_eq!(visible.visible_opponents, 0);

        sim.ball.position = Vec2::new(2.0, 4.0);
        let snapshot = WorldSnapshot::from_match(&sim);
        let hidden = snapshot.observation_for(observer);
        assert!(!hidden.visible_ball);
        assert!(hidden.ball_distance > visible.ball_distance);
        assert!(belief_from_observation(&hidden).possession_confidence < 0.35);
    }

    #[test]
    fn visible_pass_targets_filter_hidden_teammates() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let passer = 6;
        let visible_teammate = 7;
        let hidden_teammate = 8;
        sim.players[passer].position = Vec2::new(40.0, 60.0);
        sim.players[passer].velocity = Vec2::new(4.0, 0.0);
        sim.players[passer].action_facing = FacingBucket::East;
        sim.players[passer].receive_facing = FacingBucket::East;
        sim.players[visible_teammate].position = Vec2::new(56.0, 60.0);
        sim.players[hidden_teammate].position = Vec2::new(18.0, 60.0);
        for home in 0..11 {
            if ![passer, visible_teammate, hidden_teammate].contains(&home) {
                sim.players[home].position = Vec2::new(6.0, 18.0 + home as f64);
            }
        }
        for away in 11..22 {
            sim.players[away].position = Vec2::new(72.0, 95.0);
        }
        sim.ball.holder = Some(passer);
        sim.ball.position = sim.players[passer].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        assert!(snapshot.player_can_see_player(passer, visible_teammate));
        assert!(!snapshot.player_can_see_player(passer, hidden_teammate));
        let visible_targets = snapshot.ranked_visible_pass_targets(passer, 3);
        assert!(visible_targets.contains(&visible_teammate));
        assert!(!visible_targets.contains(&hidden_teammate));
        assert_eq!(
            snapshot.observation_for(passer).visible_pass_options,
            visible_targets.len()
        );
    }

    #[test]
    fn learned_pass_plan_cannot_bypass_pomdp_visibility() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let passer = 6;
        let visible_teammate = 7;
        let hidden_teammate = 8;
        sim.players[passer].position = Vec2::new(40.0, 60.0);
        sim.players[passer].velocity = Vec2::new(4.0, 0.0);
        sim.players[passer].action_facing = FacingBucket::East;
        sim.players[passer].receive_facing = FacingBucket::East;
        sim.players[visible_teammate].position = Vec2::new(56.0, 60.0);
        sim.players[hidden_teammate].position = Vec2::new(18.0, 60.0);
        for home in 0..11 {
            if ![passer, visible_teammate, hidden_teammate].contains(&home) {
                sim.players[home].position = Vec2::new(6.0, 18.0 + home as f64);
            }
        }
        for away in 11..22 {
            sim.players[away].position = Vec2::new(72.0, 95.0);
        }
        sim.ball.holder = Some(passer);
        sim.ball.position = sim.players[passer].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let hidden_pass_plan = SoccerLearnedPlan {
            action: "pass".to_string(),
            target_player: Some(hidden_teammate),
            target_point: None,
        };
        let hidden_low_cross_plan = SoccerLearnedPlan {
            action: "play-down-flank-low-cross".to_string(),
            target_player: Some(hidden_teammate),
            target_point: None,
        };
        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(passer);
        assert_eq!(
            snapshot.ranked_visible_pass_targets(passer, 11),
            vec![visible_teammate]
        );

        let (pass_action, pass_label) = sim.players[passer]
            .action_from_learned_plan(&hidden_pass_plan, &snapshot, &observation)
            .expect("visible fallback should keep learned pass executable");
        assert_eq!(pass_label, "pass");
        assert!(matches!(
            pass_action,
            SoccerAction::Pass {
                target_player: Some(target),
                flight: PassFlight::Floor,
                ..
            } if target == visible_teammate
        ));

        let (cross_action, cross_label) = sim.players[passer]
            .action_from_learned_plan(&hidden_low_cross_plan, &snapshot, &observation)
            .expect("visible fallback should keep learned low cross executable");
        assert_eq!(cross_label, "flank-low-cross");
        assert!(matches!(
            cross_action,
            SoccerAction::Pass {
                target_player: Some(target),
                flight: PassFlight::Floor,
                ..
            } if target == visible_teammate
        ));

        sim.players[visible_teammate].position = Vec2::new(18.0, 62.0);
        let hidden_snapshot = WorldSnapshot::from_match(&sim);
        let hidden_observation = hidden_snapshot.observation_for(passer);
        assert!(hidden_snapshot
            .ranked_visible_pass_targets(passer, 11)
            .is_empty());
        assert!(
            sim.players[passer]
                .action_from_learned_plan(&hidden_pass_plan, &hidden_snapshot, &hidden_observation)
                .is_none(),
            "learned pass should not fall back to an omniscient hidden target"
        );
        assert!(
            sim.players[passer]
                .action_from_learned_plan(
                    &hidden_low_cross_plan,
                    &hidden_snapshot,
                    &hidden_observation
                )
                .is_none(),
            "learned low cross should not fall back to an omniscient hidden target"
        );
    }

    #[test]
    fn player_operation_order_is_weighted_by_internal_preferences() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 203,
            ..Default::default()
        });
        let player_id = 5;
        sim.players[player_id].position = Vec2::new(40.0, 90.0);
        sim.players[player_id].velocity = Vec2::new(0.0, 5.0);
        sim.players[player_id].skills.decision_noise = 1.0;
        sim.players[6].position = Vec2::new(46.0, 102.0);
        sim.players[7].position = Vec2::new(34.0, 100.0);
        sim.players[8].position = Vec2::new(52.0, 99.0);
        for away in 11..22 {
            sim.players[away].position = Vec2::new(8.0, 110.0);
        }
        sim.ball.holder = Some(player_id);
        sim.ball.position = sim.players[player_id].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        assert!(snapshot.observation_for(player_id).shot_lane_open);
        assert!(!snapshot
            .ranked_visible_pass_targets(player_id, 3)
            .is_empty());

        let sample_first_order = |preferences: AgentPreferences| {
            let mut first_counts: HashMap<String, usize> = HashMap::new();
            for seed in 0..180 {
                let mut player = sim.players[player_id].clone();
                player.preferences = preferences.clone();
                let mut rng = mulberry32(10_000 + seed);
                let _ = player.run_time_step(&snapshot, None, None, &mut rng);
                let first = player
                    .last_decision
                    .as_ref()
                    .and_then(|decision| decision.operation_order.first())
                    .cloned()
                    .unwrap_or_default();
                *first_counts.entry(first).or_insert(0) += 1;
            }
            first_counts
        };

        let shoot_first = sample_first_order(AgentPreferences {
            shoot_bias: 0.98,
            pass_bias: 0.04,
            dribble_bias: 0.04,
            open_space_bias: 0.70,
            offensive_mindedness: 0.80,
            defensive_mindedness: 0.30,
        });
        let pass_first = sample_first_order(AgentPreferences {
            shoot_bias: 0.04,
            pass_bias: 0.98,
            dribble_bias: 0.04,
            open_space_bias: 0.70,
            offensive_mindedness: 0.50,
            defensive_mindedness: 0.50,
        });

        let shoot_pref_shoot = *shoot_first.get("shoot").unwrap_or(&0);
        let pass_pref_pass = pass_first
            .iter()
            .filter(|(label, _)| label.starts_with("pass"))
            .map(|(_, count)| *count)
            .sum::<usize>();
        let pass_pref_shoot = *pass_first.get("shoot").unwrap_or(&0);
        assert!(
            shoot_pref_shoot > pass_pref_shoot,
            "shoot bias should make shoot appear first more often than pass bias: shoot={shoot_first:?} pass={pass_first:?}"
        );
        assert!(
            pass_pref_pass > pass_pref_shoot,
            "pass-biased player should inspect passes first more often: {pass_first:?}"
        );
    }

    #[test]
    fn defensive_operation_order_uses_preferences_and_team_press() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 204,
            ..Default::default()
        });
        let defender = 3;
        let holder = 15;
        park_players_except(&mut sim, &[defender, holder]);
        sim.players[defender].position = Vec2::new(40.0, 67.0);
        sim.players[defender].home_position = Vec2::new(38.0, 48.0);
        sim.players[defender].skills.defending = 8.2;
        sim.players[holder].position = Vec2::new(40.0, 72.0);
        sim.ball.holder = Some(holder);
        sim.ball.position = sim.players[holder].position;
        sim.ball.last_touch_team = Some(Team::Away);

        let mut low_press_snapshot = WorldSnapshot::from_match(&sim);
        low_press_snapshot.home_directive.press_intensity = 0.10;
        let mut high_press_snapshot = low_press_snapshot.clone();
        high_press_snapshot.home_directive.press_intensity = 0.95;

        let mut cautious = sim.players[defender].clone();
        cautious.preferences.offensive_mindedness = 0.05;
        cautious.preferences.defensive_mindedness = 0.98;
        cautious.skills.aggression = 3.0;
        let cautious_options = cautious.defensive_action_options(
            &low_press_snapshot,
            low_press_snapshot.tactical_directive(Team::Home),
            low_press_snapshot.dt_seconds,
        );
        assert!(
            action_option_score(&cautious_options, "defend-shape")
                > action_option_score(&cautious_options, "defend-roam") * 4.0,
            "low-press cautious defender should strongly prefer shape: {cautious_options:?}"
        );

        let mut roamer = sim.players[defender].clone();
        roamer.preferences.offensive_mindedness = 0.95;
        roamer.preferences.defensive_mindedness = 0.05;
        roamer.skills.aggression = 10.0;
        let roamer_options = roamer.defensive_action_options(
            &high_press_snapshot,
            high_press_snapshot.tactical_directive(Team::Home),
            high_press_snapshot.dt_seconds,
        );
        assert!(
            action_option_score(&roamer_options, "defend-roam")
                > action_option_score(&roamer_options, "defend-shape"),
            "high-press aggressive defender should be allowed to roam first: {roamer_options:?}"
        );

        let sample_first_order =
            |template: &PlayerAgent, snapshot: &WorldSnapshot, seed_base: u32| {
                let mut first_counts: HashMap<String, usize> = HashMap::new();
                for seed in 0..180 {
                    let mut player = template.clone();
                    let mut rng = mulberry32(seed_base + seed);
                    let _ = player.run_time_step(snapshot, None, None, &mut rng);
                    let first = player
                        .last_decision
                        .as_ref()
                        .and_then(|decision| decision.operation_order.first())
                        .cloned()
                        .unwrap_or_default();
                    *first_counts.entry(first).or_insert(0) += 1;
                }
                first_counts
            };

        let cautious_first = sample_first_order(&cautious, &low_press_snapshot, 31_000);
        let roamer_first = sample_first_order(&roamer, &high_press_snapshot, 32_000);
        assert!(
            cautious_first.get("defend-shape").copied().unwrap_or(0)
                > cautious_first.get("defend-roam").copied().unwrap_or(0) * 3,
            "cautious low-press defender should mostly inspect shape first: {cautious_first:?}"
        );
        assert!(
            roamer_first.get("defend-roam").copied().unwrap_or(0)
                > roamer_first.get("defend-shape").copied().unwrap_or(0),
            "aggressive high-press defender should inspect roam first more often: {roamer_first:?}"
        );
    }

    #[test]
    fn shared_position_board_tracks_rolling_player_history() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 202,
            ..MatchConfig::playback_trace(6.0)
        });

        for _ in 0..60 {
            sim.run_time_step();
        }

        assert_eq!(
            sim.players[0].position_history.len(),
            PLAYER_POSITION_HISTORY_LIMIT
        );
        for player in &sim.players {
            assert_eq!(player.position_history.len(), PLAYER_POSITION_HISTORY_LIMIT);
            assert_eq!(
                player.position_history.back().copied(),
                Some(player.position)
            );
        }
        assert!(sim.players[0]
            .history_velocity_estimate(sim.config.dt_seconds)
            .len()
            .is_finite());
        assert!(sim.players[0]
            .history_acceleration_estimate(sim.config.dt_seconds)
            .len()
            .is_finite());
        assert!(sim.players[0]
            .history_jerk_estimate(sim.config.dt_seconds)
            .len()
            .is_finite());

        let shared = sim.shared_positions.clone();
        let (
            history_len,
            ball_history_len,
            ball_latest_position,
            official_latest_len,
            official_history_len,
            center_ref_position,
        ) = std::thread::spawn(move || {
            let snapshot = shared.snapshot();
            assert_eq!(snapshot.latest.len(), 22);
            assert_eq!(snapshot.official_latest.len(), 3);
            (
                snapshot.history_for(0).expect("player history").len(),
                snapshot.ball_history().len(),
                snapshot.ball_latest().expect("ball latest").position,
                snapshot.official_latest.len(),
                snapshot
                    .official_history_for(22)
                    .expect("center ref history")
                    .len(),
                snapshot
                    .official_latest_for(22)
                    .expect("center ref latest")
                    .position,
            )
        })
        .join()
        .expect("reader thread joins");
        assert_eq!(history_len, PLAYER_POSITION_HISTORY_LIMIT);
        assert_eq!(ball_history_len, BALL_POSITION_HISTORY_LIMIT);
        assert_eq!(ball_latest_position, sim.ball.position);
        assert_eq!(official_latest_len, 3);
        assert_eq!(official_history_len, PLAYER_POSITION_HISTORY_LIMIT);
        assert_eq!(center_ref_position, sim.officials[0].position);
        assert_eq!(
            sim.shared_positions
                .ball_latest()
                .expect("shared ball latest")
                .position,
            sim.ball.position
        );
        assert_eq!(
            sim.shared_positions.ball_history().len(),
            BALL_POSITION_HISTORY_LIMIT
        );
        assert_eq!(
            sim.shared_positions
                .official_latest_for(22)
                .expect("shared center ref latest")
                .position,
            sim.officials[0].position
        );
        assert_eq!(
            sim.shared_positions
                .official_history_for(22)
                .expect("shared center ref history")
                .len(),
            PLAYER_POSITION_HISTORY_LIMIT
        );

        let snapshot = WorldSnapshot::from_match(&sim);
        let shared_player_ids = snapshot
            .shared_positions
            .latest
            .iter()
            .map(|sample| sample.player_id)
            .collect::<HashSet<_>>();
        assert_eq!(shared_player_ids, (0..22).collect::<HashSet<_>>());
        assert_eq!(
            snapshot
                .shared_positions
                .ball_latest()
                .expect("snapshot shared ball latest")
                .position,
            sim.ball.position
        );
        assert_eq!(
            snapshot.shared_positions.ball_history().len(),
            BALL_POSITION_HISTORY_LIMIT
        );
        assert_eq!(snapshot.shared_positions.official_latest.len(), 3);
        assert_eq!(
            snapshot
                .shared_positions
                .official_latest_for(22)
                .expect("snapshot center ref latest")
                .position,
            sim.officials[0].position
        );
        assert_eq!(
            snapshot
                .shared_positions
                .official_history_for(22)
                .expect("snapshot center ref history")
                .len(),
            PLAYER_POSITION_HISTORY_LIMIT
        );
        for official in &sim.officials {
            let latest = snapshot
                .shared_positions
                .official_latest_for(official.id)
                .expect("snapshot official latest");
            assert_eq!(latest.tick, sim.tick);
            assert_eq!(latest.position, official.position);
            assert_eq!(latest.velocity, official.velocity);
            assert!(latest.acceleration.len().is_finite());
            assert!(latest.jerk.len().is_finite());
            let history = snapshot
                .shared_positions
                .official_history_for(official.id)
                .expect("snapshot official history");
            assert_eq!(history.len(), PLAYER_POSITION_HISTORY_LIMIT);
            assert_eq!(
                history.last().map(|sample| sample.position),
                Some(official.position)
            );
            assert_eq!(history.last().map(|sample| sample.tick), Some(sim.tick));
        }
        assert_eq!(
            snapshot
                .player_position_history(0)
                .expect("snapshot history")
                .len(),
            PLAYER_POSITION_HISTORY_LIMIT
        );
        assert_eq!(
            snapshot.player_position(0).expect("snapshot position"),
            sim.players[0].position
        );
        assert!(snapshot
            .player_jerk(0)
            .expect("snapshot jerk")
            .len()
            .is_finite());
        assert!(snapshot
            .shared_positions
            .latest_for(0)
            .expect("latest player sample")
            .jerk
            .len()
            .is_finite());
        for player in &sim.players {
            let shared_latest = snapshot
                .shared_positions
                .latest_for(player.id)
                .expect("snapshot shared player latest");
            assert_eq!(shared_latest.tick, sim.tick);
            assert_eq!(shared_latest.position, player.position);
            assert_eq!(shared_latest.velocity, player.velocity);
            assert!(shared_latest.acceleration.len().is_finite());
            assert!(shared_latest.jerk.len().is_finite());
            let shared_history = snapshot
                .shared_positions
                .history_for(player.id)
                .expect("snapshot shared player history");
            assert_eq!(shared_history.len(), PLAYER_POSITION_HISTORY_LIMIT);
            assert_eq!(
                shared_history.last().map(|sample| sample.position),
                Some(player.position)
            );
            assert_eq!(
                shared_history.last().map(|sample| sample.tick),
                Some(sim.tick)
            );
            let history = snapshot
                .player_position_history(player.id)
                .expect("snapshot history");
            assert_eq!(history.len(), PLAYER_POSITION_HISTORY_LIMIT);
            assert_eq!(
                history.last().map(|sample| sample.position),
                Some(player.position)
            );
            assert_eq!(
                snapshot
                    .player_position(player.id)
                    .expect("snapshot position"),
                player.position
            );
            assert!(snapshot
                .player_velocity(player.id)
                .expect("snapshot velocity")
                .len()
                .is_finite());
            assert!(snapshot
                .player_acceleration(player.id)
                .expect("snapshot acceleration")
                .len()
                .is_finite());
            assert!(snapshot
                .player_jerk(player.id)
                .expect("snapshot jerk")
                .len()
                .is_finite());
        }
        let frame = sim.to_frame();
        assert_eq!(
            frame.players[0].position_history.len(),
            PLAYER_POSITION_HISTORY_LIMIT
        );
        assert!(frame.players.iter().all(|player| {
            player.position_history.len() == PLAYER_POSITION_HISTORY_LIMIT
                && player.position_history.last().copied() == Some(player.position)
        }));
        assert_eq!(
            frame.players[0].skills.top_speed,
            sim.players[0].skills.top_speed
        );
        assert_eq!(
            frame.players[0].skills.stamina,
            sim.players[0].skills.stamina
        );
        assert_eq!(frame.players[0].fatigue, sim.players[0].fatigue);
        assert_eq!(frame.ball_history.len(), BALL_POSITION_HISTORY_LIMIT);
    }

    #[test]
    fn shared_position_board_reads_stay_coherent_during_main_loop_syncs() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 212,
            ..MatchConfig::playback_trace(1.2)
        });
        let shared = sim.shared_positions.clone();
        let running = Arc::new(AtomicBool::new(true));
        let start = Arc::new(std::sync::Barrier::new(2));

        let reader_running = running.clone();
        let reader_start = start.clone();
        let reader = std::thread::spawn(move || {
            reader_start.wait();
            let mut reads = 0usize;
            let mut last_tick = 0u64;
            let mut max_tick = 0u64;

            while reader_running.load(Ordering::Acquire) {
                let snapshot = shared.snapshot();
                let ball_tick = snapshot.ball_latest().expect("shared ball latest").tick;
                assert!(
                    ball_tick >= last_tick,
                    "shared position ticks should be monotonic for concurrent readers"
                );
                assert_eq!(snapshot.latest.len(), 22);
                assert_eq!(snapshot.official_latest.len(), 3);
                assert!(snapshot
                    .latest
                    .iter()
                    .all(|sample| sample.tick == ball_tick));
                assert!(snapshot
                    .official_latest
                    .iter()
                    .all(|sample| sample.tick == ball_tick));
                assert_eq!(
                    snapshot.ball_history().last().map(|sample| sample.tick),
                    Some(ball_tick)
                );
                last_tick = ball_tick;
                max_tick = max_tick.max(ball_tick);
                reads += 1;
                std::thread::yield_now();
            }

            let snapshot = shared.snapshot();
            let final_tick = snapshot
                .ball_latest()
                .expect("shared final ball latest")
                .tick;
            assert_eq!(snapshot.latest.len(), 22);
            assert_eq!(snapshot.official_latest.len(), 3);
            assert!(snapshot
                .latest
                .iter()
                .all(|sample| sample.tick == final_tick));
            assert!(snapshot
                .official_latest
                .iter()
                .all(|sample| sample.tick == final_tick));
            (reads, max_tick.max(final_tick))
        });

        start.wait();
        for _ in 0..12 {
            sim.run_time_step();
            std::thread::yield_now();
        }
        running.store(false, Ordering::Release);

        let (reads, max_tick) = reader.join().expect("shared position reader joins");
        assert!(reads > 0);
        assert_eq!(max_tick, sim.tick);
        assert_eq!(
            sim.shared_positions
                .ball_latest()
                .expect("shared ball latest after syncs")
                .tick,
            sim.tick
        );
    }

    #[test]
    fn shared_position_board_recovers_from_poisoned_lock() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 213,
            ..MatchConfig::playback_trace(0.4)
        });
        sim.run_time_step();
        let shared = sim.shared_positions.clone();
        let poisoner = {
            let shared = shared.clone();
            std::thread::spawn(move || {
                let _guard = shared
                    .inner
                    .write()
                    .expect("test poison shared position lock");
                panic!("poison shared player position lock");
            })
        };
        assert!(poisoner.join().is_err());

        let snapshot = shared.snapshot();
        assert_eq!(snapshot.latest.len(), 22);
        assert_eq!(snapshot.official_latest.len(), 3);
        assert_eq!(
            shared.latest_for(0).expect("recovered player latest").tick,
            sim.tick
        );
        assert_eq!(
            shared
                .official_latest_for(22)
                .expect("recovered center ref latest")
                .tick,
            sim.tick
        );
        assert_eq!(
            shared.ball_latest().expect("recovered ball latest").tick,
            sim.tick
        );

        sim.run_time_step();
        assert_eq!(
            sim.shared_positions
                .ball_latest()
                .expect("shared ball latest after recovered write")
                .tick,
            sim.tick,
            "main loop should still sync shared positions after a reader/writer panic poisons the board"
        );
    }

    #[test]
    fn agent_decision_snapshot_sees_current_positions_without_mutating_shared_histories() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 211,
            ..MatchConfig::playback_trace(0.3)
        });
        let player_id = 8;
        let original_shared_position = sim
            .shared_positions
            .latest_for(player_id)
            .expect("initial shared player position")
            .position;
        let live_position = Vec2::new(
            (original_shared_position.x + 6.0).min(sim.config.field_width_yards - 1.0),
            (original_shared_position.y + 9.0).min(sim.config.field_length_yards - 1.0),
        );
        sim.players[player_id].position = live_position;
        sim.players[player_id].velocity = Vec2::new(3.0, 4.0);

        let decision_snapshot = WorldSnapshot::from_match_for_agent_decision(&sim);

        assert_eq!(
            sim.shared_positions
                .latest_for(player_id)
                .expect("shared store should remain at prior sync point")
                .position,
            original_shared_position,
            "constructing a decision snapshot should not write mid-tick positions into the shared board"
        );
        assert_eq!(
            decision_snapshot
                .player_position(player_id)
                .expect("decision snapshot player position"),
            live_position,
            "the next agent decision should see the live in-memory position of every player"
        );
        assert_eq!(
            decision_snapshot
                .shared_positions
                .latest_for(player_id)
                .expect("decision snapshot shared latest")
                .position,
            live_position,
            "the lightweight snapshot's shared board should mirror current positions for all-agent geometry reads"
        );
        assert!(
            decision_snapshot.shared_positions.histories.is_empty(),
            "agent decision snapshots should keep the current position board without cloning rolling histories"
        );
        assert_eq!(
            decision_snapshot
                .player_velocity(player_id)
                .expect("decision snapshot player velocity"),
            sim.players[player_id].velocity
        );

        let full_snapshot = WorldSnapshot::from_match(&sim);
        assert_eq!(
            full_snapshot
                .player_position_history(player_id)
                .expect("full snapshot player history")
                .last()
                .map(|sample| sample.position),
            Some(live_position),
            "full snapshots should append the same live position to their cloned rolling history"
        );
    }

    #[test]
    fn officials_track_rolling_position_history_and_jerk() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            seed: 205,
            ..MatchConfig::playback_trace(6.0)
        });

        for _ in 0..60 {
            sim.run_time_step();
        }

        for official in &sim.officials {
            assert_eq!(
                official.position_history.len(),
                PLAYER_POSITION_HISTORY_LIMIT
            );
            assert_eq!(
                official.position_history.back().copied(),
                Some(official.position)
            );
            assert!(official
                .history_velocity_estimate(sim.config.dt_seconds)
                .len()
                .is_finite());
            assert!(official
                .history_acceleration_estimate(sim.config.dt_seconds)
                .len()
                .is_finite());
            assert!(official
                .history_jerk_estimate(sim.config.dt_seconds)
                .len()
                .is_finite());
        }

        let frame = sim.to_frame();
        assert!(frame.officials.iter().all(|official| {
            official.velocity.len().is_finite()
                && official.acceleration.len().is_finite()
                && official.jerk.len().is_finite()
        }));
        assert!(frame.officials.iter().all(|official| {
            official.position_history.len() == PLAYER_POSITION_HISTORY_LIMIT
                && official.position_history.last().copied() == Some(official.position)
        }));
    }

    #[test]
    fn player_movement_uses_discrete_soccer_gaits() {
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, 1.0), false),
            MovementGait::Walk
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, -1.0), false),
            MovementGait::BackWalk
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, -5.0), false),
            MovementGait::BackJog
        );
        assert_eq!(
            classify_movement_gait(Team::Away, Vec2::new(0.0, 5.0), false),
            MovementGait::BackJog
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, -8.0), false),
            MovementGait::BackSkip
        );
        assert_eq!(
            classify_movement_gait(Team::Away, Vec2::new(0.0, 8.0), true),
            MovementGait::BackSkip
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(4.0, 0.2), false),
            MovementGait::SideStep
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, 6.0), false),
            MovementGait::Jog
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, 12.0), false),
            MovementGait::Run
        );
        assert_eq!(
            classify_movement_gait(Team::Home, Vec2::new(0.0, 6.0), true),
            MovementGait::Sprint
        );
        assert!(
            MovementGait::Skip.speed_multiplier() > MovementGait::Jog.speed_multiplier() * 1.29
        );
        assert!(
            MovementGait::BackSkip.speed_multiplier()
                > MovementGait::BackJog.speed_multiplier() * 1.28
        );
        assert!(MovementGait::Run.speed_multiplier() > MovementGait::Skip.speed_multiplier());
        assert!(MovementGait::Sprint.speed_multiplier() > MovementGait::Run.speed_multiplier());

        let neutral_skills = SkillProfile {
            top_speed: 7.0,
            ..Default::default()
        };
        assert!(
            player_top_speed_yps(PlayerRole::Forward, &neutral_skills)
                >= player_top_speed_yps(PlayerRole::Midfielder, &neutral_skills) * 1.10
                    - f64::EPSILON
        );

        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        sim.ball.position = Vec2::new(40.0, 72.0);
        sim.players[0].position = Vec2::new(40.0, 60.0);
        sim.players[0].velocity = Vec2::zero();
        sim.move_player_towards(0, Vec2::new(40.0, 55.0), false);
        assert_eq!(sim.players[0].movement_gait, MovementGait::BackJog);
        assert_eq!(
            sim.players[0].action_facing,
            FacingBucket::South,
            "home player should backpedal toward own goal while still facing play"
        );

        let away_player = 11;
        sim.ball.position = Vec2::new(40.0, 48.0);
        sim.players[away_player].position = Vec2::new(40.0, 60.0);
        sim.players[away_player].velocity = Vec2::zero();
        sim.move_player_towards(away_player, Vec2::new(40.0, 65.0), false);
        assert_eq!(
            sim.players[away_player].movement_gait,
            MovementGait::BackJog
        );
        assert_eq!(
            sim.players[away_player].action_facing,
            FacingBucket::North,
            "away player should backpedal toward own goal while still facing play"
        );
    }

