    #[test]
    fn movement_acceleration_uses_strength_to_weight_ratio() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            dt_seconds: 0.1,
            duration_seconds: 0.1,
            seed: 2112,
            ..Default::default()
        });
        let light_strong = 6;
        let heavy_weak = 7;
        park_players_except(&mut sim, &[light_strong, heavy_weak]);
        for player_id in [light_strong, heavy_weak] {
            sim.players[player_id].role = PlayerRole::Midfielder;
            sim.players[player_id].velocity = Vec2::zero();
            sim.players[player_id].acceleration = Vec2::zero();
            sim.players[player_id].fatigue = 0.0;
            sim.players[player_id].skills.top_speed = 8.0;
            sim.players[player_id].skills.acceleration = 8.0;
            sim.players[player_id].skills.stamina = 8.0;
        }
        sim.players[light_strong].position = Vec2::new(28.0, 30.0);
        sim.players[heavy_weak].position = Vec2::new(52.0, 30.0);
        sim.players[light_strong].skills.strength = 9.5;
        sim.players[light_strong].skills.weight_pounds = 152.0;
        sim.players[heavy_weak].skills.strength = 3.0;
        sim.players[heavy_weak].skills.weight_pounds = 214.0;

        assert!(
            strength_to_weight_acceleration_multiplier(&sim.players[light_strong].skills)
                > strength_to_weight_acceleration_multiplier(&sim.players[heavy_weak].skills)
        );

        sim.move_player_towards(light_strong, Vec2::new(28.0, 90.0), true);
        sim.move_player_towards(heavy_weak, Vec2::new(52.0, 90.0), true);

        assert_eq!(
            sim.players[light_strong].movement_gait,
            MovementGait::Sprint
        );
        assert_eq!(sim.players[heavy_weak].movement_gait, MovementGait::Sprint);
        assert!(
            sim.players[light_strong].velocity.len()
                > sim.players[heavy_weak].velocity.len() + 0.10,
            "lighter/stronger player should ramp faster: light={} heavy={}",
            sim.players[light_strong].velocity.len(),
            sim.players[heavy_weak].velocity.len()
        );
        assert!(
            sim.players[light_strong].acceleration.len()
                > sim.players[heavy_weak].acceleration.len() + 1.0,
            "strength-to-weight should bound acceleration: light={} heavy={}",
            sim.players[light_strong].acceleration.len(),
            sim.players[heavy_weak].acceleration.len()
        );
    }

    #[test]
    fn fatigue_accumulates_from_repeated_sprints_and_recovers_at_rest() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            dt_seconds: 1.0,
            ..Default::default()
        });
        let high_stamina = 0;
        let low_stamina = 1;
        for player_id in [high_stamina, low_stamina] {
            sim.players[player_id].position = Vec2::new(25.0 + player_id as f64 * 10.0, 20.0);
            sim.players[player_id].velocity = Vec2::zero();
            sim.players[player_id].skills.top_speed = 8.0;
            sim.players[player_id].skills.acceleration = 8.0;
            sim.players[player_id].fatigue = 0.0;
        }
        sim.players[high_stamina].skills.stamina = 10.0;
        sim.players[low_stamina].skills.stamina = 1.0;

        for _ in 0..12 {
            sim.move_player_towards(high_stamina, Vec2::new(25.0, 220.0), true);
            sim.move_player_towards(low_stamina, Vec2::new(35.0, 220.0), true);
        }

        let high_after_sprints = sim.players[high_stamina].fatigue;
        let low_after_sprints = sim.players[low_stamina].fatigue;
        assert!(low_after_sprints > high_after_sprints + 0.12);

        for _ in 0..8 {
            let rest_spot = sim.players[low_stamina].position;
            sim.move_player_towards(low_stamina, rest_spot, false);
        }

        assert!(sim.players[low_stamina].fatigue < low_after_sprints);
    }

    #[test]
    fn center_referee_keeps_clear_of_ball_space() {
        let sim = SoccerMatch::default_11v11(MatchConfig::default());
        let mut snapshot = WorldSnapshot::from_match(&sim);
        let center = Vec2::new(snapshot.field_width * 0.5, snapshot.field_length * 0.5);
        snapshot.ball.position = center;
        snapshot.ball.holder = None;

        let mut center_ref = OfficialAgent::new(99, OfficialKind::CenterReferee, center);
        let mut rng = SeededRandom::new(300);
        for _ in 0..24 {
            center_ref.run_time_step(&snapshot, &mut rng);
        }

        assert!(
            center_ref.position.distance(center) > 2.5,
            "center ref should not sit on top of the ball"
        );
        assert!(
            official_clearance_target(OfficialKind::CenterReferee, center, center, &snapshot)
                .distance(center)
                >= CENTER_REF_BALL_CLEARANCE_YARDS
        );
    }

    #[test]
    fn center_referee_tracks_center_of_play_mass() {
        let sim = SoccerMatch::default_11v11(MatchConfig::default());
        let mut snapshot = WorldSnapshot::from_match(&sim);
        for (idx, player) in snapshot.players.iter_mut().enumerate() {
            let lane = (idx % 5) as f64;
            player.position = Vec2::new(21.0 + lane * 3.0, 74.0 + (idx / 5) as f64 * 4.0);
        }
        snapshot.ball.position = Vec2::new(24.0, 86.0);
        snapshot.ball.holder = Some(8);

        let target = center_referee_play_centroid_target(&snapshot);
        assert!(
            target.x < snapshot.field_width * 0.5 - 7.0,
            "center ref target should follow the player mass laterally: {target:?}"
        );
        assert!(
            target.y > snapshot.field_length * 0.5 + 10.0,
            "center ref target should follow the player mass vertically: {target:?}"
        );
        assert!(
            target.distance(snapshot.ball.position) < 16.0,
            "center ref should stay near the live play centroid before clearance: {target:?}"
        );

        let start = Vec2::new(snapshot.field_width * 0.5, snapshot.field_length * 0.5);
        let mut center_ref = OfficialAgent::new(99, OfficialKind::CenterReferee, start);
        let mut rng = SeededRandom::new(301);
        let initial_distance = center_ref.position.distance(target);
        for _ in 0..24 {
            center_ref.run_time_step(&snapshot, &mut rng);
        }

        assert!(
            center_ref.position.distance(target) < initial_distance,
            "center ref should move toward center-of-play target"
        );
        assert!(
            center_ref.position.x < start.x,
            "center ref should move laterally toward the player mass"
        );
    }

    #[test]
    fn assistant_referees_stay_off_pitch_and_in_assigned_halves() {
        let sim = SoccerMatch::default_11v11(MatchConfig::default());
        let snapshot = WorldSnapshot::from_match(&sim);
        let half = snapshot.field_length * 0.5;
        let mut near_assistant = OfficialAgent::new(
            23,
            OfficialKind::AssistantRefereeNear,
            Vec2::new(snapshot.field_width * 0.5, snapshot.field_length * 0.90),
        );
        let mut far_assistant = OfficialAgent::new(
            24,
            OfficialKind::AssistantRefereeFar,
            Vec2::new(snapshot.field_width * 0.5, snapshot.field_length * 0.10),
        );
        let mut rng = SeededRandom::new(302);

        near_assistant.run_time_step(&snapshot, &mut rng);
        far_assistant.run_time_step(&snapshot, &mut rng);

        assert!(
            (near_assistant.position.x + ASSISTANT_REF_TOUCHLINE_OFFSET_YARDS).abs() < 1e-9,
            "near assistant should stand just off the near touchline: {:?}",
            near_assistant.position
        );
        assert!(
            (0.0..=half).contains(&near_assistant.position.y),
            "near assistant should stay in first half: {:?}",
            near_assistant.position
        );
        assert!(
            (far_assistant.position.x
                - (snapshot.field_width + ASSISTANT_REF_TOUCHLINE_OFFSET_YARDS))
                .abs()
                < 1e-9,
            "far assistant should stand just off the far touchline: {:?}",
            far_assistant.position
        );
        assert!(
            (half..=snapshot.field_length).contains(&far_assistant.position.y),
            "far assistant should stay in second half: {:?}",
            far_assistant.position
        );

        let near_line =
            assistant_offside_line_snapshot(&snapshot, OfficialKind::AssistantRefereeNear)
                .expect("near assistant offside line");
        let far_line =
            assistant_offside_line_snapshot(&snapshot, OfficialKind::AssistantRefereeFar)
                .expect("far assistant offside line");
        assert_eq!(near_line.flank, AssistantFlank::Near);
        assert_eq!(far_line.flank, AssistantFlank::Far);
    }

    #[test]
    fn official_agents_randomize_internal_operation_order() {
        for kind in [
            OfficialKind::CenterReferee,
            OfficialKind::AssistantRefereeNear,
            OfficialKind::AssistantRefereeFar,
        ] {
            let mut first_ops = HashSet::new();
            let mut full_orders = HashSet::new();

            for seed in 0..48 {
                let mut sim = SoccerMatch::default_11v11(MatchConfig {
                    duration_seconds: 0.1,
                    seed: 3_120 + seed,
                    ..Default::default()
                });
                sim.run_time_step();
                let frame = sim.to_frame();
                let decision = frame
                    .officials
                    .iter()
                    .find(|official| official.kind == kind)
                    .and_then(|official| official.last_decision.as_ref())
                    .unwrap_or_else(|| panic!("{kind:?} decision trace"));

                assert_eq!(decision.operation_order.len(), 6);
                assert!(decision
                    .operation_order
                    .iter()
                    .any(|op| op == "update-kinematics"));
                assert!(decision
                    .operation_order
                    .iter()
                    .any(|op| op == "choose-referee-target"));
                first_ops.insert(
                    decision
                        .operation_order
                        .first()
                        .cloned()
                        .expect("first official operation"),
                );
                full_orders.insert(decision.operation_order.join(">"));
            }

            assert!(
                first_ops.len() > 1,
                "{kind:?} should not always inspect the same operation first: {first_ops:?}"
            );
            assert!(
                full_orders.len() > 4,
                "{kind:?} should expose varied weighted operation orders: {}",
                full_orders.len()
            );
        }
    }

    #[test]
    fn central_brain_snapshot_exposes_center_of_play_centroids() {
        let sim = SoccerMatch::default_11v11(MatchConfig::default());
        let mut snapshot = WorldSnapshot::from_match(&sim);
        for (idx, player) in snapshot.players.iter_mut().enumerate() {
            let lane = (idx % 4) as f64;
            player.position = Vec2::new(18.0 + lane * 4.0, 76.0 + (idx / 4) as f64 * 3.0);
        }
        snapshot.ball.position = Vec2::new(23.0, 88.0);
        snapshot.ball.holder = Some(8);

        let centroids = center_of_play_centroids(&snapshot);
        let brain = CentralBrain::default();
        let brain_snapshot = brain.to_snapshot(&snapshot, &sim.officials);

        assert_eq!(brain_snapshot.player_centroid, centroids.player_centroid);
        assert_eq!(
            brain_snapshot.live_play_centroid,
            centroids.live_play_centroid
        );
        assert_eq!(brain_snapshot.center_of_play, centroids.center_of_play);
        assert!(
            brain_snapshot.center_of_play.x < snapshot.field_width * 0.5 - 7.0,
            "central brain center-of-play should track lateral mass: {:?}",
            brain_snapshot.center_of_play
        );
        assert_eq!(brain_snapshot.tracked_players.len(), 22);
        assert_eq!(brain_snapshot.tracked_official_awareness.len(), 3);
    }

    #[test]
    fn loose_ball_control_ignores_officials() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        for player in &mut sim.players {
            player.position = Vec2::new(5.0, 5.0);
            player.velocity = Vec2::zero();
        }
        sim.ball.holder = None;
        sim.ball.position = Vec2::new(74.0, 114.0);
        sim.ball.velocity = Vec2::zero();
        sim.officials[0].position = sim.ball.position;

        sim.integrate_ball();

        assert_eq!(sim.ball.holder, None);
        assert_eq!(sim.ball.position, Vec2::new(74.0, 114.0));
    }

