    #[test]
    fn human_input_queue_rejects_stale_frames_and_allows_readers() {
        let q = SharedHumanInputs::new();
        assert!(q.push(HumanInputFrame {
            controller_slot: 0,
            player_id: Some(0),
            seq: 5,
            axis: Vec2::new(1.0, 0.0),
            sprint: false,
            pass: false,
            pass_flight: PassFlight::Floor,
            shoot: false,
            action: None,
            target_player: None,
        }));
        assert!(!q.push(HumanInputFrame {
            controller_slot: 0,
            player_id: Some(0),
            seq: 4,
            axis: Vec2::new(-1.0, 0.0),
            sprint: true,
            pass: false,
            pass_flight: PassFlight::Floor,
            shoot: false,
            action: None,
            target_player: None,
        }));
        assert_eq!(q.queued_len(), 1);
        assert_eq!(q.last_seq_for_slot(0), Some(5));

        let reader_queue = q.clone();
        let reader = std::thread::spawn(move || {
            assert_eq!(reader_queue.queued_len(), 1);
            assert_eq!(reader_queue.last_seq_for_slot(0), Some(5));
        });
        reader.join().expect("reader joins");

        assert!(q.push(HumanInputFrame {
            controller_slot: 0,
            player_id: Some(0),
            seq: 6,
            axis: Vec2::new(0.0, 1.0),
            sprint: true,
            pass: false,
            pass_flight: PassFlight::Floor,
            shoot: false,
            action: None,
            target_player: None,
        }));
        let latest = q.drain_latest_by_slot();
        assert_eq!(latest.get(&0).unwrap().seq, 6);
        assert!(latest.get(&0).unwrap().sprint);
        assert_eq!(q.queued_len(), 0);
        assert!(!q.push(HumanInputFrame {
            controller_slot: 0,
            player_id: Some(0),
            seq: 5,
            axis: Vec2::zero(),
            sprint: false,
            pass: false,
            pass_flight: PassFlight::Floor,
            shoot: false,
            action: None,
            target_player: None,
        }));

        q.clear_slot(0);
        assert_eq!(q.last_seq_for_slot(0), None);
        assert!(q.push(HumanInputFrame {
            controller_slot: 0,
            player_id: Some(0),
            seq: 1,
            axis: Vec2::new(-1.0, 0.0),
            sprint: true,
            pass: false,
            pass_flight: PassFlight::Floor,
            shoot: false,
            action: None,
            target_player: None,
        }));
        assert_eq!(q.last_seq_for_slot(0), Some(1));
    }

    #[test]
    fn human_input_queue_handles_multiple_controller_threads() {
        let q = SharedHumanInputs::new();
        let mut handles = Vec::new();
        for slot in 0..4 {
            let q = q.clone();
            handles.push(std::thread::spawn(move || {
                for seq in [1, 3, 2] {
                    let _ = q.push(HumanInputFrame {
                        controller_slot: slot,
                        player_id: Some(slot),
                        seq,
                        axis: Vec2::new(slot as f64, seq as f64),
                        sprint: seq == 3,
                        pass: false,
                        pass_flight: PassFlight::Floor,
                        shoot: false,
                        action: None,
                        target_player: None,
                    });
                }
            }));
        }
        for handle in handles {
            handle.join().expect("controller writer joins");
        }

        let latest = q.drain_latest_by_slot();
        assert_eq!(latest.len(), 4);
        for slot in 0..4 {
            let input = latest.get(&slot).expect("slot input");
            assert_eq!(input.seq, 3);
            assert!(input.sprint);
            assert_eq!(q.last_seq_for_slot(slot), Some(3));
        }
    }

