    #[test]
    fn agent_schedule_summary_exposes_full_runtime_loop_contract() {
        let trace = run_simulation(
            MatchConfig {
                seed: 13_083,
                ..MatchConfig::playback_trace(0.2)
            },
            1,
        );
        let initial = trace.frames.first().expect("initial frame");
        assert_eq!(initial.agent_schedule_summary.expected_player_count, 22);
        assert_eq!(initial.agent_schedule_summary.expected_official_count, 3);
        assert_eq!(initial.agent_schedule_summary.expected_total_agents, 27);
        assert_eq!(initial.agent_schedule_summary.total_agents, 0);
        assert!(!initial.agent_schedule_summary.complete);

        let scheduled = trace
            .frames
            .iter()
            .find(|frame| frame.tick > 0)
            .expect("post-tick scheduled frame");
        let summary = &scheduled.agent_schedule_summary;
        assert_eq!(summary.expected_player_count, 22);
        assert_eq!(summary.expected_official_count, 3);
        assert_eq!(summary.expected_total_agents, 27);
        assert_eq!(summary.total_agents, 27);
        assert_eq!(summary.unique_agents, 27);
        assert_eq!(summary.duplicate_agents, 0);
        assert_eq!(summary.central_brain_count, 1);
        assert_eq!(summary.player_count, 22);
        assert_eq!(summary.official_count, 3);
        assert_eq!(summary.ball_count, 1);
        assert!(summary.central_brain_first);
        assert_eq!(summary.ball_scheduled_index, scheduled.ball.scheduled_index);
        assert!(summary.complete);

        let playback = SoccerPlaybackFrame::from(scheduled);
        assert!(playback.agent_schedule_summary.complete);
        assert_eq!(playback.agent_schedule_summary.total_agents, 27);
    }

    #[test]
    fn runtime_agent_schedule_shuffles_field_entities_each_tick() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.8,
            seed: 13_084,
            ..Default::default()
        });
        let expected_player_ids = (0..22).collect::<HashSet<_>>();
        let expected_official_ids = [22, 23, 24].into_iter().collect::<HashSet<_>>();
        let mut field_orders = HashSet::new();
        let mut ball_indexes = HashSet::new();

        for _ in 0..8 {
            sim.run_time_step();
            let summary = agent_schedule_summary_for(
                &sim.last_agent_schedule,
                sim.players.len(),
                sim.officials.len(),
            );
            assert!(
                summary.complete,
                "runtime schedule should stay complete: {summary:?}"
            );
            assert_eq!(summary.expected_total_agents, 27);
            assert_eq!(summary.player_count, 22);
            assert_eq!(summary.official_count, 3);
            assert_eq!(summary.ball_count, 1);
            assert!(summary.central_brain_first);
            ball_indexes.insert(summary.ball_scheduled_index.expect("ball scheduled"));
            let field_segment = sim.last_agent_schedule.iter().skip(1).collect::<Vec<_>>();
            assert_eq!(
                field_segment.len(),
                26,
                "shuffled field schedule should include 22 players, 3 officials, and the ball"
            );
            assert!(
                field_segment
                    .iter()
                    .all(|entry| entry.kind != AgentScheduleKind::CentralBrain),
                "central brain should not be inside the Fisher-Yates field segment"
            );
            assert_eq!(
                field_segment
                    .iter()
                    .filter(|entry| entry.kind == AgentScheduleKind::Player)
                    .map(|entry| entry.id)
                    .collect::<HashSet<_>>(),
                expected_player_ids,
                "every player should appear exactly once in the shuffled field segment"
            );
            assert_eq!(
                field_segment
                    .iter()
                    .filter(|entry| entry.kind == AgentScheduleKind::Official)
                    .map(|entry| entry.id)
                    .collect::<HashSet<_>>(),
                expected_official_ids,
                "center ref and both assistants should appear exactly once in the shuffled field segment"
            );
            assert_eq!(
                field_segment
                    .iter()
                    .filter(|entry| entry.kind == AgentScheduleKind::Ball)
                    .map(|entry| entry.id)
                    .collect::<Vec<_>>(),
                vec![BALL_AGENT_ID],
                "ball agent should appear exactly once in the shuffled field segment"
            );
            field_orders.insert(
                sim.last_agent_schedule
                    .iter()
                    .skip(1)
                    .map(|entry| (entry.kind.clone(), entry.id))
                    .collect::<Vec<_>>(),
            );
        }

        assert!(
            field_orders.len() > 1,
            "Fisher-Yates field entity order should vary across ticks"
        );
        assert!(
            ball_indexes.len() > 1,
            "ball agent should move through the shuffled field schedule, got {ball_indexes:?}"
        );
    }

    #[test]
    fn accounting_smoke_report_flags_frozen_multi_frame_match() {
        let mut trace = run_simulation(
            MatchConfig {
                seed: 13_079,
                ..MatchConfig::playback_trace(0.8)
            },
            1,
        );
        let first = trace.frames.first().expect("initial frame").clone();
        for frame in &mut trace.frames {
            frame.players = first.players.clone();
            frame.ball.position = first.ball.position;
            frame.ball.velocity = Vec2::zero();
            frame.ball.holder = None;
            frame.central_brain.ball_position = frame.ball.position;
            frame.central_brain.ball_velocity = Vec2::zero();
            frame.central_brain.ball_holder = None;
            frame.shared_positions = first.shared_positions.clone();
        }

        let report = soccer_simulation_accounting_smoke_report(&trace);

        assert!(!report.ok());
        assert!(report.violations.iter().any(|violation| {
            violation.subject == "liveness" && violation.metric == "movingPlayers"
        }));
        assert!(report.violations.iter().any(|violation| {
            violation.subject == "liveness" && violation.metric == "ballActivity"
        }));
        assert!(report.violations.iter().any(|violation| {
            violation.subject == "liveness" && violation.metric == "ballGoalwardProgress"
        }));
    }

    #[test]
    fn accounting_smoke_report_flags_duplicate_agent_schedule_entries() {
        let mut trace = run_simulation(
            MatchConfig {
                seed: 13_080,
                ..MatchConfig::playback_trace(0.2)
            },
            1,
        );
        let scheduled_frame = trace
            .frames
            .iter_mut()
            .find(|frame| frame.tick > 0)
            .expect("post-tick scheduled frame");
        let first_player_slot = scheduled_frame
            .agent_schedule
            .iter()
            .position(|entry| entry.kind == AgentScheduleKind::Player)
            .expect("first scheduled player");
        let second_player_slot = scheduled_frame
            .agent_schedule
            .iter()
            .enumerate()
            .skip(first_player_slot + 1)
            .find(|(_, entry)| entry.kind == AgentScheduleKind::Player)
            .map(|(idx, _)| idx)
            .expect("second scheduled player");
        let missing_player_id = scheduled_frame.agent_schedule[second_player_slot].id;
        scheduled_frame.agent_schedule[second_player_slot] =
            scheduled_frame.agent_schedule[first_player_slot].clone();

        let report = soccer_simulation_accounting_smoke_report(&trace);

        assert!(!report.ok());
        assert!(report.violations.iter().any(|violation| {
            violation.subject == "agentSchedule" && violation.metric == "uniqueAgents"
        }));
        assert!(report.violations.iter().any(|violation| {
            violation.subject == "agentSchedule"
                && violation.metric == "playerScheduled"
                && violation.expected == format!("player {missing_player_id}")
        }));
        assert!(
            !report.violations.iter().any(|violation| {
                violation.subject == "agentSchedule" && violation.metric == "length"
            }),
            "duplicate-agent regression should catch exact-once violations even when schedule length stays valid"
        );
    }

