    #[test]
    fn player_mdp_state_includes_hierarchical_pitch_grid_and_facing() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 141,
            ..Default::default()
        });
        sim.players[5].position = Vec2::new(22.0, 66.0);
        sim.players[5].velocity = Vec2::new(2.0, 0.0);
        sim.players[5].receive_facing = FacingBucket::NorthWest;
        sim.players[5].action_facing = FacingBucket::West;

        let snapshot = WorldSnapshot::from_match(&sim);
        let state = snapshot.mdp_state_for_player(5);
        let observation = snapshot.observation_for(5);

        assert_eq!(state.player_grid.fine.x, 3);
        assert_eq!(state.player_grid.fine.y, 8);
        assert_eq!(state.player_grid.fine.id, 99);
        assert_eq!(state.player_grid.fine.parent_id, Some(25));
        assert_eq!(state.player_grid.tactical.id, 25);
        assert_eq!(state.player_grid.tactical.parent_id, Some(6));
        assert_eq!(state.player_grid.macro_zone.id, 6);
        assert_eq!(state.player_grid.macro_zone.parent_id, Some(0));
        assert_eq!(state.player_grid.whole_pitch.id, 0);
        assert_eq!(state.receive_facing, FacingBucket::NorthWest);
        assert_eq!(state.action_facing, FacingBucket::West);
        assert_eq!(observation.player_grid.fine.id, state.player_grid.fine.id);
        assert_eq!(observation.action_facing, FacingBucket::West);
    }

    #[test]
    fn pitch_grid_address_clamps_noisy_tracking_boundaries_and_keeps_parent_links() {
        let samples = [
            Vec2::new(-3.0, -2.0),
            Vec2::new(0.0, 0.0),
            Vec2::new(DEFAULT_FIELD_WIDTH_YARDS, DEFAULT_FIELD_LENGTH_YARDS),
            Vec2::new(
                DEFAULT_FIELD_WIDTH_YARDS + 4.0,
                DEFAULT_FIELD_LENGTH_YARDS + 6.0,
            ),
        ];

        for position in samples {
            let grid = pitch_grid_address(
                position,
                DEFAULT_FIELD_WIDTH_YARDS,
                DEFAULT_FIELD_LENGTH_YARDS,
            );

            assert_eq!(grid.whole_pitch.id, 0);
            assert_eq!(grid.whole_pitch.parent_id, None);
            assert_eq!(grid.macro_zone.parent_id, Some(grid.whole_pitch.id));
            assert_eq!(grid.tactical.parent_id, Some(grid.macro_zone.id));
            assert_eq!(grid.fine.parent_id, Some(grid.tactical.id));
            assert!(grid.macro_zone.x < PITCH_MACRO_GRID_COLUMNS);
            assert!(grid.macro_zone.y < PITCH_MACRO_GRID_ROWS);
            assert!(grid.tactical.x < PITCH_TACTICAL_GRID_COLUMNS);
            assert!(grid.tactical.y < PITCH_TACTICAL_GRID_ROWS);
            assert!(grid.fine.x < PITCH_FINE_GRID_COLUMNS);
            assert!(grid.fine.y < PITCH_FINE_GRID_ROWS);
        }

        let fallback_grid = pitch_grid_address(Vec2::new(18.0, 62.0), f64::NAN, 0.0);
        let default_grid = pitch_grid_address(
            Vec2::new(18.0, 62.0),
            DEFAULT_FIELD_WIDTH_YARDS,
            DEFAULT_FIELD_LENGTH_YARDS,
        );
        assert_eq!(fallback_grid, default_grid);
    }

    #[test]
    fn pass_and_shot_preserve_release_facing_after_recovery_movement() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1410,
            ..Default::default()
        });
        let passer = 5;
        let receiver = 8;
        park_players_except(&mut sim, &[passer, receiver]);
        sim.players[passer].position = Vec2::new(40.0, 60.0);
        sim.players[passer].home_position = Vec2::new(20.0, 20.0);
        sim.players[passer].velocity = Vec2::zero();
        sim.players[passer].action_facing = FacingBucket::Unknown;
        sim.players[passer].skills.passing = 10.0;
        sim.players[passer].skills.passing_completion_rate = 10.0;
        sim.players[passer].skills.flair_passing = 1.0;
        sim.players[receiver].position = Vec2::new(72.0, 60.0);
        sim.players[receiver].velocity = Vec2::zero();
        sim.ball.holder = Some(passer);
        sim.ball.position = sim.players[passer].position;
        sim.ball.last_touch_team = Some(Team::Home);

        sim.apply_player_intent(PlayerIntent {
            player_id: passer,
            action: SoccerAction::Pass {
                target_player: Some(receiver),
                power: 0.64,
                flight: PassFlight::Floor,
            },
            sprint: false,
        });

        assert_eq!(sim.ball.holder, None);
        assert_eq!(
            sim.pending_pass.as_ref().map(|pass| pass.from),
            Some(passer)
        );
        assert_eq!(sim.players[passer].action_facing, FacingBucket::East);

        let mut shot_sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1411,
            ..Default::default()
        });
        let shooter = 9;
        park_players_except(&mut shot_sim, &[shooter]);
        shot_sim.players[shooter].position = Vec2::new(40.0, 90.0);
        shot_sim.players[shooter].home_position = Vec2::new(20.0, 20.0);
        shot_sim.players[shooter].velocity = Vec2::zero();
        shot_sim.players[shooter].action_facing = FacingBucket::Unknown;
        shot_sim.players[shooter].skills.shooting = 10.0;
        shot_sim.ball.holder = Some(shooter);
        shot_sim.ball.position = shot_sim.players[shooter].position;
        shot_sim.ball.last_touch_team = Some(Team::Home);

        shot_sim.apply_player_intent(PlayerIntent {
            player_id: shooter,
            action: SoccerAction::Shoot { power: 1.0 },
            sprint: false,
        });

        assert_eq!(shot_sim.ball.holder, None);
        assert_eq!(
            shot_sim.pending_shot.as_ref().map(|shot| shot.shooter),
            Some(shooter)
        );
        assert_eq!(shot_sim.players[shooter].action_facing, FacingBucket::South);
    }

    #[test]
    fn pomdp_observation_includes_goal_keeper_pressure_and_forward_space_features() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1411,
            ..Default::default()
        });
        let player_id = 9;
        sim.players[player_id].position = Vec2::new(40.0, 90.0);
        sim.players[player_id].velocity = Vec2::new(0.0, 3.0);
        sim.players[11].position = Vec2::new(42.0, 116.0);
        for away in 12..22 {
            sim.players[away].position = Vec2::new(74.0, 30.0 + away as f64);
        }
        sim.players[13].position = Vec2::new(40.8, 97.0);
        sim.ball.holder = Some(player_id);
        sim.ball.position = sim.players[player_id].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(player_id);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(player_id),
            &observation,
            Team::Home,
            sim.players[player_id].role,
        );

        assert!(observation.yards_to_goal > 0.0);
        assert!(observation.yards_to_own_goal > observation.yards_to_goal);
        assert!(observation.opponent_goal_angle_degrees > 0.0);
        assert!(observation.opposing_goalkeeper_distance > 0.0);
        assert!(observation.opposing_goalkeeper_angle_degrees > 0.0);
        assert!(observation.forward_dribble_space_yards < 10.0);
        assert!(observation.real_pressure > 0.0);
        assert!(observation.perceived_pressure >= observation.real_pressure - 0.15);
        assert!(observation.real_time_on_ball_seconds < 2.8);
        assert!(observation.perceived_time_on_ball_seconds < 2.8);
        assert!(state.yards_to_own_goal_bin > 0);
        assert!(state.opponent_goal_angle_bin > 0);
        assert!(state.opposing_goalkeeper_distance_bin > 0);
        assert!(state.perceived_pressure_bin > 0);
    }

    #[test]
    fn pomdp_observation_separates_goal_and_pressure_urgency() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14112,
            ..Default::default()
        });
        let striker = 9;
        for away in 11..22 {
            sim.players[away].position = Vec2::new(74.0, 18.0 + (away - 11) as f64);
        }
        sim.players[striker].position = Vec2::new(40.0, 94.0);
        sim.players[striker].velocity = Vec2::new(0.0, 2.4);
        sim.players[striker].action_facing = FacingBucket::South;
        sim.ball.holder = Some(striker);
        sim.ball.position = sim.players[striker].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let striker_obs = snapshot.observation_for(striker);
        assert!(striker_obs.perceived_pressure < 0.20);
        assert!(striker_obs.offensive_urgency > 0.28);
        assert!(striker_obs.decision_urgency >= striker_obs.offensive_urgency - f64::EPSILON);
        assert!(
            striker_obs.goal_attack_window_score > 0.40,
            "striker facing goal should expose a strong goal attack window"
        );
        assert!(striker_obs.defensive_urgency < 0.05);
        let striker_state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(striker),
            &striker_obs,
            Team::Home,
            sim.players[striker].role,
        );
        assert!(striker_state.offensive_urgency_bin > striker_state.pressure_urgency_bin);
        assert!(striker_state.goal_attack_window_bin >= 2);

        let defender = 4;
        sim.players[defender].position = Vec2::new(38.0, 22.0);
        sim.players[defender].velocity = Vec2::new(0.0, 0.2);
        sim.players[11].position = Vec2::new(38.6, 22.3);
        sim.ball.holder = Some(defender);
        sim.ball.position = sim.players[defender].position;
        sim.ball.last_touch_team = Some(Team::Home);
        let snapshot = WorldSnapshot::from_match(&sim);
        let defender_obs = snapshot.observation_for(defender);
        assert!(defender_obs.perceived_pressure > 0.55);
        assert!(defender_obs.pressure_urgency > 0.55);
        assert!(defender_obs.defensive_urgency > 0.45);
        assert!(defender_obs.decision_urgency >= defender_obs.pressure_urgency - f64::EPSILON);
        assert_eq!(defender_obs.goal_attack_window_score, 0.0);
        let options = sim.players[defender].possession_action_options(
            &defender_obs,
            &snapshot.tactical_directive(Team::Home),
            0,
            0,
            false,
            snapshot.dt_seconds,
            snapshot.field_width,
        );
        assert!(action_option_score(&options, "clearance") > 0.0);
        assert!(action_option_score(&options, "route-one") > 0.0);
        assert!(action_option_score(&options, "fake-left-cut-right") > 0.0);
        assert!(action_option_score(&options, "fake-right-cut-left") > 0.0);

        let transition = SoccerLearningTransition {
            tick: snapshot.tick,
            player_id: defender,
            team: Team::Home,
            role: sim.players[defender].role,
            state: snapshot.mdp_state_for_player(defender),
            observation: defender_obs.clone(),
            belief: belief_from_observation(&defender_obs),
            action: "clearance".to_string(),
            action_target: None,
            decision_context: SoccerDecisionContext::default(),
            tactical_trace: SoccerTacticalLearningTrace::default(),
            reward: 0.0,
            next_state: snapshot.mdp_state_for_player(defender),
            next_observation: defender_obs,
            done: false,
        };
        let features = soccer_neural_transition_features(&transition);
        assert_eq!(features.len(), SOCCER_NEURAL_FEATURE_DIM);
        assert_eq!(features[SOCCER_NEURAL_FEATURE_GOAL_ATTACK_WINDOW], 0.0);
    }

    #[test]
    fn shot_decision_gate_requires_quality_or_near_goal_pressure_bailout() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1414,
            ..Default::default()
        });
        let attacker = 9;
        sim.players[attacker].position = Vec2::new(40.0, 104.0);
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let mut observation = snapshot.observation_for(attacker);
        observation.shot_lane_open = true;
        observation.yards_to_goal = 9.0;
        observation.offensive_urgency = 0.0;
        observation.immediate_dispossession_risk = 0.20;
        observation.shot_on_frame_probability = SHOT_ON_FRAME_MIN_PROBABILITY - 0.01;
        observation.shot_beat_goalkeeper_probability = SHOT_KEEPER_BEAT_MIN_PROBABILITY + 0.20;
        assert!(!shot_decision_is_qualified(&observation));

        observation.shot_on_frame_probability = SHOT_ON_FRAME_MIN_PROBABILITY + 0.01;
        observation.shot_beat_goalkeeper_probability = SHOT_KEEPER_BEAT_MIN_PROBABILITY - 0.01;
        assert!(!shot_decision_is_qualified(&observation));

        observation.offensive_urgency = 0.72;
        observation.shot_on_frame_probability = 0.19;
        observation.shot_beat_goalkeeper_probability = 0.13;
        observation.shot_block_probability = 0.50;
        assert!(shot_decision_is_qualified(&observation));
        observation.offensive_urgency = 0.0;

        observation.shot_on_frame_probability = SHOT_ON_FRAME_MIN_PROBABILITY + 0.01;
        observation.shot_beat_goalkeeper_probability = SHOT_KEEPER_BEAT_MIN_PROBABILITY + 0.01;
        assert!(shot_decision_is_qualified(&observation));

        observation.shot_on_frame_probability = SHOT_BAILOUT_ON_FRAME_PROBABILITY + 0.01;
        observation.shot_beat_goalkeeper_probability = 0.02;
        observation.immediate_dispossession_risk = SHOT_BAILOUT_DISPOSSESSION_RISK + 0.01;
        assert!(shot_decision_is_qualified(&observation));

        observation.yards_to_goal = SHOT_BAILOUT_NEAR_GOAL_YARDS + 0.5;
        assert!(!shot_decision_is_qualified(&observation));

        observation.shot_lane_open = false;
        observation.yards_to_goal = 9.0;
        observation.shot_block_probability = 0.05;
        observation.shot_on_frame_probability = SHOT_ON_FRAME_MIN_PROBABILITY + 0.20;
        observation.shot_beat_goalkeeper_probability = SHOT_KEEPER_BEAT_MIN_PROBABILITY + 0.20;
        observation.immediate_dispossession_risk = SHOT_BAILOUT_DISPOSSESSION_RISK + 0.20;
        assert!(!shot_decision_is_qualified(&observation));
    }

