    #[test]
    fn pomdp_q_state_and_neural_features_track_look_behind_scan_risk() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14122,
            ..Default::default()
        });
        let observer = 6;
        sim.tick = 12;
        sim.players[observer].position = Vec2::new(40.0, 60.0);
        sim.ball.position = Vec2::new(40.0, 82.0);
        sim.ball.velocity = Vec2::new(0.0, 18.0);
        sim.ball.holder = Some(9);
        sim.ball.last_touch_team = Some(Team::Home);
        let previous = WorldSnapshot::from_match(&sim);
        sim.tick = 36;
        sim.players[observer].action_facing = FacingBucket::North;
        sim.players[observer].last_decision =
            Some(test_decision_trace(&previous, observer, "look-behind"));

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(observer);
        let state = snapshot.mdp_state_for_player(observer);
        let key =
            SoccerQStateKey::from_parts(&state, &observation, Team::Home, PlayerRole::Midfielder);
        let transition = SoccerLearningTransition {
            tick: snapshot.tick,
            player_id: observer,
            team: Team::Home,
            role: PlayerRole::Midfielder,
            state,
            observation: observation.clone(),
            belief: belief_from_observation(&observation),
            action: "support-shape".to_string(),
            action_target: None,
            decision_context: SoccerDecisionContext::default(),
            tactical_trace: SoccerTacticalLearningTrace::default(),
            reward: 0.0,
            next_state: snapshot.mdp_state_for_player(observer),
            next_observation: observation.clone(),
            done: false,
        };
        let features = soccer_neural_transition_features(&transition);

        assert!(key.look_behind_scan);
        assert!(key.look_behind_drift_risk_bin >= 2);
        assert_eq!(features.len(), SOCCER_NEURAL_FEATURE_DIM);
        assert!(
            features[SOCCER_NEURAL_FEATURE_LOOK_BEHIND_SCAN] > 0.9,
            "neural learner should see the look-behind scan flag"
        );
        assert!(
            features[SOCCER_NEURAL_FEATURE_LOOK_BEHIND_DRIFT_RISK] > 0.1,
            "neural learner should see the look-behind drift-risk bin"
        );
    }

    #[test]
    fn tactical_learning_penalizes_lingering_look_behind_on_defense() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14123,
            ..Default::default()
        });
        let defender = 2;
        let away_holder = 17;
        sim.tick = 14;
        sim.clock_seconds = sim.tick as f64 * sim.config.dt_seconds;
        sim.players[defender].position = Vec2::new(40.0, 60.0);
        sim.players[defender].home_position = Vec2::new(40.0, 42.0);
        sim.players[away_holder].position = Vec2::new(40.0, 84.0);
        sim.ball.holder = Some(away_holder);
        sim.ball.position = sim.players[away_holder].position;
        sim.ball.velocity = Vec2::new(0.0, 17.0);
        sim.ball.last_touch_team = Some(Team::Away);

        let previous = WorldSnapshot::from_match(&sim);
        sim.tick = 42;
        sim.clock_seconds = sim.tick as f64 * sim.config.dt_seconds;
        sim.players[defender].last_decision =
            Some(test_decision_trace(&previous, defender, "look-behind"));

        sim.players[defender].action_facing = FacingBucket::South;
        let facing_ball_snapshot = WorldSnapshot::from_match(&sim);
        let facing_ball_trace = tactical_shape_trace_for_snapshots(
            defender,
            Team::Home,
            PlayerRole::Defender,
            &facing_ball_snapshot,
            &facing_ball_snapshot,
            sim.players[defender].position,
            sim.players[defender].position,
            &SoccerTacticalLearningWeights::default(),
        );

        sim.players[defender].action_facing = FacingBucket::North;
        let scanning_snapshot = WorldSnapshot::from_match(&sim);
        let scanning_observation = scanning_snapshot.observation_for(defender);
        let scanning_trace = tactical_shape_trace_for_snapshots(
            defender,
            Team::Home,
            PlayerRole::Defender,
            &scanning_snapshot,
            &scanning_snapshot,
            sim.players[defender].position,
            sim.players[defender].position,
            &SoccerTacticalLearningWeights::default(),
        );

        assert!(scanning_observation.look_behind_scan_active);
        assert!(scanning_trace.look_behind_scan_active);
        assert!(scanning_trace.look_behind_drift_risk > 0.45);
        assert!(
            scanning_trace.look_behind_shape_penalty < -0.18,
            "lingering defensive scans should carry positioning cost: {scanning_trace:?}"
        );
        assert!(
            scanning_trace.tactical_reward < facing_ball_trace.tactical_reward - 0.18,
            "facing the ball should beat lingering look-behind when defending: scan={} facing={}",
            scanning_trace.tactical_reward,
            facing_ball_trace.tactical_reward
        );

        let transition = SoccerLearningTransition {
            tick: scanning_snapshot.tick,
            player_id: defender,
            team: Team::Home,
            role: PlayerRole::Defender,
            state: scanning_snapshot.mdp_state_for_player(defender),
            observation: scanning_observation,
            belief: belief_from_observation(&scanning_snapshot.observation_for(defender)),
            action: "defend-shape".to_string(),
            action_target: None,
            decision_context: SoccerDecisionContext::default(),
            tactical_trace: scanning_trace.clone(),
            reward: scanning_trace.tactical_reward,
            next_state: scanning_snapshot.mdp_state_for_player(defender),
            next_observation: scanning_snapshot.observation_for(defender),
            done: false,
        };
        let summary = SoccerTacticalLearningSummary::from_transitions(&[transition]);
        assert_eq!(summary.look_behind_scan_transitions, 1);
        assert!(summary.mean_look_behind_drift_risk > 0.45);
        assert!(
            summary.mean_look_behind_shape_penalty < -0.18,
            "summary should expose aggregate scan penalty: {summary:?}"
        );
    }

    #[test]
    fn pomdp_observation_uses_tired_nearest_defender_as_dribble_cue() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1413,
            ..Default::default()
        });
        let attacker = 9;
        let defender = 13;
        sim.players[attacker].position = Vec2::new(40.0, 88.0);
        sim.players[attacker].velocity = Vec2::new(0.0, 4.0);
        sim.players[attacker].fatigue = 0.05;
        sim.players[attacker].skills.dribbling = 9.0;
        sim.players[attacker].skills.stamina = 9.0;
        sim.players[defender].position = Vec2::new(40.5, 92.0);
        sim.players[defender].fatigue = 0.90;
        for away in 11..22 {
            if away != defender {
                sim.players[away].position = Vec2::new(74.0, 22.0 + away as f64);
                sim.players[away].fatigue = 0.05;
            }
        }
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(attacker);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(attacker),
            &observation,
            Team::Home,
            sim.players[attacker].role,
        );

        assert!(observation.nearest_defender_fatigue > 0.85);
        assert!(observation.nearest_defender_fatigue_confidence > 0.70);
        assert!(observation.perceived_nearest_defender_fatigue > 0.70);
        assert!(observation.perceived_fatigue_advantage > 0.60);
        assert!(state.perceived_fatigue_advantage_bin >= 3);

        let directive = snapshot.tactical_directive(Team::Home);
        let favorable = sim.players[attacker].possession_action_options(
            &observation,
            &directive,
            0,
            0,
            false,
            sim.config.dt_seconds,
            snapshot.field_width,
        );
        let mut unfavorable_observation = observation.clone();
        unfavorable_observation.perceived_nearest_defender_fatigue = 0.05;
        unfavorable_observation.perceived_fatigue_advantage = unfavorable_observation
            .perceived_nearest_defender_fatigue
            - unfavorable_observation.fatigue;
        let unfavorable = sim.players[attacker].possession_action_options(
            &unfavorable_observation,
            &directive,
            0,
            0,
            false,
            sim.config.dt_seconds,
            snapshot.field_width,
        );

        let favorable_dribble = action_option_score(&favorable, "dribble");
        let unfavorable_dribble = action_option_score(&unfavorable, "dribble");
        assert!(
            favorable_dribble > unfavorable_dribble * 1.12,
            "tired defender cue should boost dribble: favorable={favorable_dribble} unfavorable={unfavorable_dribble}"
        );
    }

    #[test]
    fn aerial_pass_targeting_can_bypass_blocked_floor_lane() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1771,
            ..Default::default()
        });
        let passer = 7;
        let target = 9;
        let blocker = 12;
        sim.players[passer].position = Vec2::new(10.0, 86.0);
        sim.players[target].position = Vec2::new(40.0, 104.0);
        sim.players[target].skills.height = 9.0;
        sim.players[target].skills.strength = 8.5;
        sim.players[blocker].position = Vec2::new(25.0, 95.0);
        for away in 11..22 {
            if away != blocker {
                sim.players[away].position = Vec2::new(72.0, 24.0 + away as f64);
            }
        }
        sim.players[11].position = Vec2::new(58.0, 112.0);
        sim.players[13].position = Vec2::new(72.0, 108.0);
        sim.players[14].position = Vec2::new(43.0, 100.0);
        sim.ball.holder = Some(passer);
        sim.ball.position = sim.players[passer].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(passer);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(passer),
            &observation,
            Team::Home,
            sim.players[passer].role,
        );
        assert!(!snapshot.clear_line(
            sim.players[passer].position,
            sim.players[target].position,
            Team::Away,
            2.5
        ));
        assert!(snapshot
            .ranked_visible_aerial_pass_targets(passer, 11)
            .contains(&target));
        assert!(observation.visible_aerial_pass_options > 0);
        assert!(observation.aerial_pass_bypass_score > 0.25);
        assert!(observation.aerial_pass_interception_risk > 0.15);
        assert!(state.visible_aerial_pass_options_bin > 0);
        assert!(state.aerial_pass_bypass_score_bin > 0);
        assert!(state.aerial_pass_interception_risk_bin > 0);

        sim.apply_player_intent(PlayerIntent {
            player_id: passer,
            action: SoccerAction::Pass {
                target_player: Some(target),
                power: 0.85,
                flight: PassFlight::Aerial,
            },
            sprint: false,
        });

        let pending = sim.pending_pass.as_ref().expect("pending aerial pass");
        assert_eq!(pending.flight, PassFlight::Aerial);
        assert!(pending.is_cross);
        assert_eq!(pending.target, Some(target));
        sim.integrate_ball();
        assert!(sim.ball.to_state().altitude_yards > 0.05);
    }

