    #[test]
    fn q_policy_keys_separate_same_action_by_player_grid_cell() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 142,
            ..Default::default()
        });
        sim.ball.holder = Some(5);
        sim.players[5].position = Vec2::new(18.0, 68.0);
        let snapshot_left = WorldSnapshot::from_match(&sim);

        let mut policy = SoccerQPolicy::default();
        assert!(policy.set_action_value_for_snapshot(&snapshot_left, 5, "dribble", 4.0));
        let left_state = SoccerQStateKey::from_parts(
            &snapshot_left.mdp_state_for_player(5),
            &snapshot_left.observation_for(5),
            Team::Home,
            sim.players[5].role,
        );
        assert_eq!(
            policy
                .best_action_for_snapshot(&snapshot_left, 5)
                .as_deref(),
            Some("dribble")
        );

        sim.players[5].position = Vec2::new(62.0, 68.0);
        let snapshot_right = WorldSnapshot::from_match(&sim);
        let right_state = SoccerQStateKey::from_parts(
            &snapshot_right.mdp_state_for_player(5),
            &snapshot_right.observation_for(5),
            Team::Home,
            sim.players[5].role,
        );

        assert_ne!(
            left_state.player_fine_cell_id,
            right_state.player_fine_cell_id
        );
        assert_ne!(
            left_state.player_tactical_cell_id,
            right_state.player_tactical_cell_id
        );
        assert!(policy.q_value(&right_state, "dribble").is_none());
    }

    #[test]
    fn q_policy_uses_parent_grid_backoff_for_spatial_correlation() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1421,
            ..Default::default()
        });
        sim.ball.holder = Some(5);
        sim.ball.position = Vec2::new(21.0, 68.0);
        sim.players[5].position = Vec2::new(18.0, 68.0);
        let snapshot = WorldSnapshot::from_match(&sim);
        let mut base_state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(5),
            &snapshot.observation_for(5),
            Team::Home,
            sim.players[5].role,
        );

        let mut policy = SoccerQPolicy::default();
        policy.set_action_value(base_state.clone(), "dribble", 4.0);
        assert_eq!(
            policy.best_action_hierarchical(&base_state).as_deref(),
            Some("dribble")
        );

        let mut tactical_sibling = base_state.clone();
        tactical_sibling.player_fine_cell_id += 1;
        assert!(policy.q_value(&tactical_sibling, "dribble").is_none());
        assert_eq!(
            policy
                .best_action_hierarchical(&tactical_sibling)
                .as_deref(),
            Some("dribble")
        );

        let mut macro_sibling = base_state.clone();
        macro_sibling.player_fine_cell_id += 7;
        macro_sibling.player_tactical_cell_id += 1;
        assert!(policy.q_value(&macro_sibling, "dribble").is_none());
        assert_eq!(
            policy.best_action_hierarchical(&macro_sibling).as_deref(),
            Some("dribble")
        );

        let mut whole_pitch_sibling = base_state.clone();
        whole_pitch_sibling.player_fine_cell_id += 80;
        whole_pitch_sibling.player_tactical_cell_id += 20;
        whole_pitch_sibling.player_macro_cell_id += 2;
        assert!(policy.q_value(&whole_pitch_sibling, "dribble").is_none());
        assert_eq!(
            policy
                .best_action_hierarchical(&whole_pitch_sibling)
                .as_deref(),
            Some("dribble")
        );

        base_state.action_facing = FacingBucket::North;
        assert_eq!(policy.best_action_hierarchical(&base_state), None);
    }

    #[test]
    fn q_policy_uses_relaxed_indexed_backoff_for_target_grid_preferences() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14212,
            ..Default::default()
        });
        let passer = 5;
        let receiver = 8;
        sim.ball.holder = Some(passer);
        sim.ball.position = Vec2::new(30.0, 62.0);
        sim.players[passer].position = sim.ball.position;
        sim.players[receiver].position = Vec2::new(52.0, 78.0);

        let snapshot = WorldSnapshot::from_match(&sim);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(passer),
            &snapshot.observation_for(passer),
            Team::Home,
            sim.players[passer].role,
        );
        let target_grid = pitch_grid_address(
            sim.players[receiver].position,
            snapshot.field_width,
            snapshot.field_length,
        );
        let mut policy = SoccerQPolicy::default();
        assert!(policy.set_target_value(state.clone(), "pass", target_grid, 4.25));
        assert!(!policy.target_relaxed_spatial_index.is_empty());

        let mut volatile_context = state.clone();
        volatile_context.pressure_bin = volatile_context.pressure_bin.saturating_add(1);
        volatile_context.decision_urgency_bin =
            volatile_context.decision_urgency_bin.saturating_add(1);
        assert!(!state.matches_spatial_level(&volatile_context, PitchGridLevel::Fine));
        assert!(state.matches_relaxed_spatial_level(&volatile_context, PitchGridLevel::Fine));

        let learned_target = policy
            .best_target_grid_for_state_action(&volatile_context, "pass")
            .expect("relaxed indexed target grid");
        assert_eq!(learned_target.target_fine_cell_id, target_grid.fine.id);
        assert_eq!(
            learned_target.target_tactical_cell_id,
            target_grid.tactical.id
        );
        assert!(
            policy
                .target_preference_for_grid(&volatile_context, "pass", &target_grid)
                .expect("relaxed indexed target preference")
                > 4.0,
            "relaxed indexed preference should preserve strong learned target value"
        );
    }

    #[test]
    fn q_policy_relaxed_target_backoff_respects_facing_context() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 14213,
            ..Default::default()
        });
        let passer = 5;
        let receiver = 8;
        sim.ball.holder = Some(passer);
        sim.ball.position = Vec2::new(30.0, 62.0);
        sim.players[passer].position = sim.ball.position;
        sim.players[passer].receive_facing = FacingBucket::South;
        sim.players[passer].action_facing = FacingBucket::South;
        sim.players[receiver].position = Vec2::new(52.0, 78.0);

        let snapshot = WorldSnapshot::from_match(&sim);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(passer),
            &snapshot.observation_for(passer),
            Team::Home,
            sim.players[passer].role,
        );
        let target_grid = pitch_grid_address(
            sim.players[receiver].position,
            snapshot.field_width,
            snapshot.field_length,
        );
        let mut policy = SoccerQPolicy::default();
        assert!(policy.set_target_value(state.clone(), "killer-pass", target_grid, 4.5));

        let mut noisy_same_facing = state.clone();
        noisy_same_facing.pressure_bin = noisy_same_facing.pressure_bin.saturating_add(1);
        noisy_same_facing.decision_urgency_bin =
            noisy_same_facing.decision_urgency_bin.saturating_add(1);
        assert!(state.matches_relaxed_spatial_level(&noisy_same_facing, PitchGridLevel::Fine));
        assert!(
            policy
                .target_preference_for_grid(&noisy_same_facing, "killer-pass", &target_grid)
                .expect("same-facing relaxed target preference")
                > 4.0
        );

        let mut opposite_facing = noisy_same_facing.clone();
        opposite_facing.receive_facing = FacingBucket::North;
        opposite_facing.action_facing = FacingBucket::North;
        assert!(!state.matches_relaxed_spatial_level(&opposite_facing, PitchGridLevel::Fine));
        assert_eq!(
            policy.target_preference_for_grid(&opposite_facing, "killer-pass", &target_grid),
            None,
            "same grid/action target should not leak across opposite-facing POMDP contexts"
        );

        let mut generic_facing = state.clone();
        generic_facing.receive_facing = FacingBucket::Unknown;
        generic_facing.action_facing = FacingBucket::Unknown;
        assert!(policy.set_target_value(generic_facing, "killer-pass", target_grid, 3.25));
        assert!(
            policy
                .target_preference_for_grid(&opposite_facing, "killer-pass", &target_grid)
                .expect("unknown-facing target fallback")
                > 3.0,
            "unknown-facing samples remain available as coarse fallback data"
        );
    }

    #[test]
    fn q_policy_ranks_learned_actions_with_legality_and_probabilities() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1422,
            ..Default::default()
        });
        sim.ball.holder = Some(5);
        sim.ball.position = sim.players[5].position;
        let snapshot = WorldSnapshot::from_match(&sim);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(5),
            &snapshot.observation_for(5),
            Team::Home,
            sim.players[5].role,
        );
        let mut policy = SoccerQPolicy::default();
        policy.set_action_value(state, "dribble", 1.0);
        let state = SoccerQStateKey::from_parts(
            &snapshot.mdp_state_for_player(5),
            &snapshot.observation_for(5),
            Team::Home,
            sim.players[5].role,
        );
        policy.set_action_value(state, "hold", 4.0);

        let (_, actions) = policy
            .ranked_action_values_for_snapshot(&snapshot, 5, 6)
            .expect("ranked policy actions");
        let dribble = actions
            .iter()
            .find(|action| action.label == "dribble")
            .expect("dribble action");
        let hold = actions
            .iter()
            .find(|action| action.label == "hold")
            .expect("hold action");
        assert!(dribble.legal);
        assert!((dribble.probability - 1.0).abs() < 1e-9);
        assert!(!hold.legal);
        assert_eq!(hold.probability, 0.0);
    }

