    #[test]
    fn neural_training_batches_and_replay_drop_invalid_samples() {
        let valid_a = SoccerNeuralTrainingSample {
            input: [0.25; SOCCER_NEURAL_FEATURE_DIM],
            target: 1.0,
            priority: 0.8,
        };
        let valid_b = SoccerNeuralTrainingSample {
            input: [0.50; SOCCER_NEURAL_FEATURE_DIM],
            target: 2.0,
            priority: 0.6,
        };
        let invalid_target = SoccerNeuralTrainingSample {
            input: [0.75; SOCCER_NEURAL_FEATURE_DIM],
            target: f64::NAN,
            priority: 1.0,
        };
        let mut invalid_input = SoccerNeuralTrainingSample {
            input: [0.0; SOCCER_NEURAL_FEATURE_DIM],
            target: 3.0,
            priority: 0.4,
        };
        invalid_input.input[SOCCER_NEURAL_FEATURE_DIM - 1] = f64::INFINITY;

        let batches = soccer_neural_samples_into_batches(
            vec![
                valid_a.clone(),
                invalid_target.clone(),
                invalid_input.clone(),
                valid_b.clone(),
            ],
            2,
            2,
        );
        assert_eq!(batches.len(), 1);
        assert_eq!(batches[0].len(), 2);
        assert_eq!(batches[0][0].target, valid_a.target);
        assert_eq!(batches[0][1].target, valid_b.target);
        assert!(batches.iter().flatten().all(soccer_neural_sample_is_valid));

        let config = MatchConfig {
            neural_learning: SoccerNeuralLearningConfig {
                enabled: true,
                replay_capacity: 8,
                ..SoccerNeuralLearningConfig::default()
            },
            duration_seconds: 0.1,
            seed: 15079,
            ..Default::default()
        };
        let mut learner = SoccerNeuralLearner::new(&config);
        learner.replay.push_back(invalid_target);
        learner.replay.push_back(valid_a.clone());
        learner.replay.push_back(invalid_input);
        learner.replay.push_back(valid_b.clone());
        learner.refresh_replay_stats(8);

        assert_eq!(learner.replay.len(), 2);
        assert!(learner.replay.iter().all(soccer_neural_sample_is_valid));
        assert_eq!(learner.stats.replay_samples, 2);
    }

    #[test]
    fn neural_target_priority_sanitizes_bootstrap_inputs() {
        let (target, priority) =
            soccer_neural_target_and_priority(30.0, f64::NAN, 30.0, false, f64::NAN, f64::NAN);

        assert!(target.is_finite());
        assert!(priority.is_finite());
        assert!((target - 1.94).abs() < 1e-9);
        assert!(priority > target.abs());

        let (bad_target, bad_priority) = soccer_neural_target_and_priority(
            f64::NAN,
            f64::INFINITY,
            f64::INFINITY,
            true,
            0.0,
            f64::NEG_INFINITY,
        );

        assert_eq!(bad_target, 0.0);
        assert!(bad_priority.is_finite());
        assert!(bad_priority >= 0.20);
    }

    #[test]
    fn neural_threaded_snapshots_are_batched_by_cadence() {
        let config = SoccerNeuralLearningConfig {
            snapshot_every_batches: 4,
            ..SoccerNeuralLearningConfig::default()
        };
        let mut stats = SoccerNeuralLearningStatsState {
            training_steps: 1,
            pending_batches: 1,
            ..SoccerNeuralLearningStatsState::default()
        };

        assert!(!should_snapshot_after_threaded_neural_train(
            &stats, 1, &config
        ));
        assert!(should_snapshot_after_threaded_neural_train(
            &stats, 2, &config
        ));

        stats.training_steps = 0;
        stats.pending_batches = 0;
        assert!(should_snapshot_after_threaded_neural_train(
            &stats, 1, &config
        ));

        let final_snapshot_only = SoccerNeuralLearningConfig {
            snapshot_every_batches: 0,
            ..SoccerNeuralLearningConfig::default()
        };
        assert!(!should_snapshot_after_threaded_neural_train(
            &stats,
            8,
            &final_snapshot_only,
        ));
    }

    #[test]
    fn neural_threaded_stats_account_for_coalesced_worker_results() {
        let mut stats = SoccerNeuralLearningStatsState {
            pending_batches: 3,
            ..SoccerNeuralLearningStatsState::default()
        };

        stats.record_result(SoccerNeuralTrainingResult {
            batches: 2,
            samples: 16,
            loss: 0.25,
            parameter_count: 42,
            failed_batches: 1,
        });

        assert_eq!(stats.pending_batches, 0);
        assert_eq!(stats.training_steps, 2);
        assert_eq!(stats.samples, 16);
        assert_eq!(stats.dropped_batches, 1);
        assert_eq!(stats.parameter_count, 42);
        assert_eq!(stats.last_loss, Some(0.25));
        assert_eq!(stats.average_loss(), Some(0.25));
    }

    #[test]
    fn neural_threaded_worker_cancel_join_closes_training_channel() {
        let config = SoccerNeuralLearningConfig {
            enabled: true,
            backend: SoccerNeuralLearningBackend::Threaded,
            batch_size: 1,
            max_batches_per_tick: 4,
            max_pending_batches: 4,
            hidden_units: 4,
            ..SoccerNeuralLearningConfig::default()
        };
        let samples = (0..8)
            .map(|idx| SoccerNeuralTrainingSample {
                input: [idx as f64; SOCCER_NEURAL_FEATURE_DIM],
                target: idx as f64,
                priority: idx as f64,
            })
            .collect::<Vec<_>>();
        let batches = soccer_neural_samples_into_batches(samples, 1, 4);
        let mut worker = spawn_soccer_neural_learning_worker(
            build_soccer_neural_network(&config, 9183),
            config.sanitized_learning_rate(),
            config.sanitized_max_pending_batches(),
        );

        worker
            .sender
            .as_ref()
            .expect("worker sender")
            .try_send(SoccerNeuralLearningWorkerCommand::Train {
                batches,
                snapshot_after_train: true,
            })
            .expect("queue training");
        worker.cancel_and_join();

        assert!(worker.sender.is_none());
        assert!(worker.handle.is_none());
    }

