    #[test]
    fn human_controller_assignment_keeps_learning_operator_controlled() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            max_human_players: 1,
            learning_enabled: true,
            learning_logging_enabled: true,
            full_game_learning_enabled: true,
            formation_lp_enabled: true,
            neural_learning: SoccerNeuralLearningConfig {
                enabled: true,
                backend: SoccerNeuralLearningBackend::Threaded,
                ..SoccerNeuralLearningConfig::default()
            },
            adversarial_embedding_exploitation_enabled: true,
            ..Default::default()
        })
        .with_team_policies(SoccerTeamQPolicies::new(SoccerQPolicyOptions::default()));

        sim.assign_controller_slot(0, Some(5))
            .expect("assign human controller");

        let learning = sim.learning_snapshot();
        assert!(sim.config.learning_enabled);
        assert!(sim.config.learning_logging_enabled);
        assert!(sim.config.full_game_learning_enabled);
        assert!(sim.config.formation_lp_enabled);
        assert!(sim.config.neural_learning.enabled);
        assert!(sim.config.adversarial_embedding_exploitation_enabled);
        assert!(learning.learning_enabled);
        assert!(learning.learning_logging_enabled);
        assert!(learning.adversarial_learning_enabled);
        assert!(learning.adversarial_embedding_exploitation_enabled);
        assert!(learning.neural_learning_enabled);
        assert_eq!(learning.neural_learning_backend, "threaded");

        let response = sim
            .update_learning_runtime(SoccerLearningRuntimeRequest {
                learning_enabled: Some(false),
                learning_logging_enabled: Some(false),
                learning_interval_ticks: Some(6),
                policy_train_max_transitions_per_tick: Some(12),
                neural_learning_enabled: Some(true),
                neural_learning_backend: Some(SoccerNeuralLearningBackend::Inline),
            })
            .expect("runtime learning update");
        assert!(!response.config.learning_enabled);
        assert!(!response.config.learning_logging_enabled);
        assert_eq!(response.config.learning_interval_ticks, 6);
        assert_eq!(response.config.policy_train_max_transitions_per_tick, 12);
        assert!(!response.config.neural_learning.enabled);
        assert!(!response.learning.learning_enabled);
        assert_eq!(response.learning.learning_interval_ticks, 6);
        assert_eq!(response.learning.policy_train_max_transitions_per_tick, 12);
        assert!(!response.learning.neural_learning_enabled);

        let response = sim
            .update_learning_runtime(SoccerLearningRuntimeRequest {
                learning_enabled: Some(true),
                learning_logging_enabled: Some(true),
                learning_interval_ticks: None,
                policy_train_max_transitions_per_tick: None,
                neural_learning_enabled: Some(true),
                neural_learning_backend: Some(SoccerNeuralLearningBackend::Inline),
            })
            .expect("runtime learning re-enable");
        assert!(response.config.learning_enabled);
        assert!(response.config.learning_logging_enabled);
        assert!(response.config.neural_learning.enabled);
        assert_eq!(
            response.config.neural_learning.backend,
            SoccerNeuralLearningBackend::Inline
        );
        assert!(response.learning.learning_enabled);
        assert!(response.learning.learning_logging_enabled);
        assert!(response.learning.neural_learning_enabled);
        assert_eq!(response.learning.neural_learning_backend, "inline");
    }

    #[test]
    fn dense_reward_discourages_still_holder_and_rewards_forward_progression() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 1508,
            ..Default::default()
        });
        let holder = 5;
        sim.ball.holder = Some(holder);
        sim.ball.position = sim.players[holder].position;
        sim.ball.velocity = Vec2::zero();
        let before = WorldSnapshot::from_match(&sim);

        let hold_decision = test_decision_trace(&before, holder, "hold");
        let still_reward = soccer_transition_reward(
            &sim.players[holder],
            &hold_decision,
            &before,
            &before,
            0,
            0,
            0,
            0,
            false,
        );

        let mut after = before.clone();
        after.ball.position.y += 6.0;
        if let Some(player) = after.players.iter_mut().find(|player| player.id == holder) {
            player.position.y += 2.0;
        }
        let dribble_decision = test_decision_trace(&before, holder, "dribble");
        let progress_reward = soccer_transition_reward(
            &sim.players[holder],
            &dribble_decision,
            &before,
            &after,
            0,
            0,
            0,
            0,
            false,
        );

        assert!(still_reward < -0.4, "still reward: {still_reward}");
        assert!(
            progress_reward > 0.6,
            "progression reward: {progress_reward}"
        );
    }

    #[test]
    fn possession_progress_milestone_requires_controlled_teammate_possession() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 15081,
            ..Default::default()
        });
        let passer = 5;
        let link = 7;
        let receiver = 9;
        park_players_except(&mut sim, &[passer, link, receiver]);
        sim.tick = 44;
        sim.ball.holder = Some(passer);
        sim.ball.position = Vec2::new(40.0, 30.0);
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[passer].position = sim.ball.position;
        sim.players[link].position = Vec2::new(42.0, 44.0);
        sim.players[receiver].position = Vec2::new(43.0, 61.0);
        sim.possession_chain.clear();
        sim.possession_chain.push_back(passer);
        sim.possession_chain.push_back(link);
        sim.possession_progress_tracker = Some(PossessionProgressTracker::new(
            Team::Home,
            Vec2::new(40.0, 30.0),
        ));
        let before = WorldSnapshot::from_match(&sim);

        sim.ball.holder = Some(receiver);
        sim.ball.position = sim.players[receiver].position;
        sim.record_possession_touch(receiver);
        sim.note_completed_possession_pass(Team::Home, Vec2::new(40.0, 30.0), sim.ball.position);
        let after = WorldSnapshot::from_match(&sim);
        let event_start = sim.reward_events.len();

        sim.update_possession_progress_milestones(&before, &after, true);

        let total = sim.reward_events[event_start..]
            .iter()
            .map(|event| event.amount)
            .sum::<f64>();
        assert!(
            (total - POSSESSION_PROGRESS_REWARD_POINTS).abs() < 1e-9,
            "controlled 30-yard possession gain should reward the chain: {total}"
        );
        let receiver_reward = sim.reward_events[event_start..]
            .iter()
            .filter(|event| event.player_id == receiver)
            .map(|event| event.amount)
            .sum::<f64>();
        let link_reward = sim.reward_events[event_start..]
            .iter()
            .filter(|event| event.player_id == link)
            .map(|event| event.amount)
            .sum::<f64>();
        let passer_reward = sim.reward_events[event_start..]
            .iter()
            .filter(|event| event.player_id == passer)
            .map(|event| event.amount)
            .sum::<f64>();
        assert!(receiver_reward > link_reward);
        assert!(link_reward > passer_reward);
        assert_eq!(
            sim.possession_progress_tracker
                .as_ref()
                .map(|tracker| tracker.rewarded_milestones),
            Some(1)
        );
        assert_eq!(
            sim.possession_progress_tracker
                .as_ref()
                .map(|tracker| tracker.best_completed_pass_chain_gain_yards),
            Some(31.0)
        );
    }

    #[test]
    fn solo_controlled_carry_does_not_collect_possession_chain_milestone() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 15083,
            ..Default::default()
        });
        let holder = 5;
        park_players_except(&mut sim, &[holder]);
        sim.tick = 46;
        sim.ball.holder = Some(holder);
        sim.ball.position = Vec2::new(40.0, 30.0);
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[holder].position = sim.ball.position;
        sim.possession_chain.clear();
        sim.possession_chain.push_back(holder);
        sim.possession_progress_tracker = Some(PossessionProgressTracker::new(
            Team::Home,
            Vec2::new(40.0, 30.0),
        ));
        let before = WorldSnapshot::from_match(&sim);

        sim.ball.position = Vec2::new(40.0, 66.0);
        sim.players[holder].position = sim.ball.position;
        let after = WorldSnapshot::from_match(&sim);
        let event_start = sim.reward_events.len();

        sim.update_possession_progress_milestones(&before, &after, true);

        assert_eq!(
            sim.reward_events.len(),
            event_start,
            "a solo carry should keep dense carry rewards separate from the 30-point team-chain milestone"
        );
        let tracker = sim
            .possession_progress_tracker
            .as_ref()
            .expect("progress tracker");
        assert!(
            tracker.best_gain_yards >= 36.0,
            "solo carry should still update broad possession progress for stall logic"
        );
        assert_eq!(tracker.best_completed_pass_chain_gain_yards, 0.0);
        assert_eq!(tracker.rewarded_milestones, 0);
    }

