    #[test]
    fn tracking_dataset_infers_kinematics_from_position_only_footage() {
        let tracking = sample_position_only_kinematics_tracking_dataset();
        assert!(tracking.frames[2].players[0].velocity.is_none());
        assert!(tracking.frames[2].players[0].motion_acceleration.is_none());

        let enriched = tracking_frames_with_inferred_kinematics(&tracking);
        let player = &enriched[2].players[0];
        assert!((player.velocity.unwrap().y - 3.0).abs() < 1e-9);
        assert!((player.motion_acceleration.unwrap().y - 20.0).abs() < 1e-9);
        assert!((player.motion_jerk.unwrap().y - 200.0).abs() < 1e-9);
        assert!((enriched[2].ball_velocity.unwrap().y - 8.0).abs() < 1e-9);
        assert!((enriched[2].ball_acceleration.unwrap().y - 40.0).abs() < 1e-9);
        assert!((enriched[2].ball_jerk.unwrap().y - 400.0).abs() < 1e-9);

        let home_positions = tracking_home_positions(&tracking);
        let snapshot =
            tracking_frame_to_world_snapshot(&tracking.config, &enriched[2], &home_positions);
        assert!((snapshot.players[0].velocity.y - 3.0).abs() < 1e-9);
        assert!((snapshot.players[0].acceleration.y - 20.0).abs() < 1e-9);
        assert!((snapshot.players[0].jerk.y - 200.0).abs() < 1e-9);
        assert_eq!(
            snapshot.players[0].receive_facing,
            FacingBucket::South,
            "position-only tracking should infer receive-facing from player motion"
        );
        assert_eq!(
            snapshot.players[0].action_facing,
            FacingBucket::South,
            "position-only tracking should infer action-facing from player motion"
        );
        assert!((snapshot.ball.velocity.y - 8.0).abs() < 1e-9);
        assert!((snapshot.ball.acceleration.y - 40.0).abs() < 1e-9);
        assert!((snapshot.ball.jerk.y - 400.0).abs() < 1e-9);

        let history_snapshot = tracking_frame_to_world_snapshot_with_history(
            &tracking.config,
            &enriched,
            2,
            &home_positions,
        );
        assert_eq!(
            history_snapshot.players[0].position_history,
            vec![
                Vec2::new(40.0, 10.0),
                Vec2::new(40.0, 10.1),
                Vec2::new(40.0, 10.4),
            ]
        );
        let shared_player_history = history_snapshot
            .player_position_history(0)
            .expect("timestamped shared player history");
        assert_eq!(shared_player_history.len(), 3);
        assert_eq!(shared_player_history[0].clock_seconds, 0.0);
        assert_eq!(shared_player_history[2].clock_seconds, 0.2);
        assert_eq!(
            shared_player_history[2].position,
            history_snapshot.players[0].position
        );
        assert!(
            (history_snapshot
                .player_forward_progress_over_seconds(&history_snapshot.players[0], 0.2)
                - 0.4)
                .abs()
                < 1e-9,
            "tracking forward-progress queries should use timestamped shared player history"
        );
        assert_eq!(history_snapshot.ball_history.len(), 3);
        assert_eq!(
            history_snapshot.ball_history[0].position,
            Vec2::new(40.0, 10.0)
        );
        assert_eq!(
            history_snapshot.ball_history[2].position,
            Vec2::new(40.0, 11.2)
        );
        let player_history_velocity = (history_snapshot.players[0].position_history[2]
            - history_snapshot.players[0].position_history[1])
            / tracking.config.dt_seconds;
        let ball_history_velocity = (history_snapshot.ball_history[2].position
            - history_snapshot.ball_history[1].position)
            / tracking.config.dt_seconds;
        assert!((player_history_velocity.y - history_snapshot.players[0].velocity.y).abs() < 1e-9);
        assert!((ball_history_velocity.y - history_snapshot.ball.velocity.y).abs() < 1e-9);

        let dataset = tracking.to_learning_dataset().expect("learning dataset");
        assert_eq!(dataset.transitions.len(), 3);
        let transition = dataset
            .transitions
            .iter()
            .find(|transition| transition.tick == 2 && transition.player_id == 0)
            .expect("late tracking transition");
        assert_eq!(
            transition.state.receive_facing,
            FacingBucket::South,
            "inferred receive-facing should reach the MDP state"
        );
        assert_eq!(
            transition.state.action_facing,
            FacingBucket::South,
            "inferred action-facing should reach the MDP state"
        );
        assert_eq!(
            transition.observation.receive_facing,
            FacingBucket::South,
            "inferred receive-facing should reach the POMDP observation"
        );
        assert_eq!(
            transition.observation.action_facing,
            FacingBucket::South,
            "inferred action-facing should reach the POMDP observation"
        );
        assert!((transition.decision_context.actor_velocity.y - 3.0).abs() < 1e-9);
        assert!((transition.decision_context.actor_acceleration.y - 20.0).abs() < 1e-9);
        assert!((transition.decision_context.ball_velocity.y - 8.0).abs() < 1e-9);
        assert!((transition.decision_context.ball_acceleration.y - 40.0).abs() < 1e-9);
        assert!((transition.decision_context.ball_jerk.y - 400.0).abs() < 1e-9);
        assert!((transition.decision_context.ball_forward_velocity_yps - 8.0).abs() < 1e-9);
        assert!(transition.decision_context.ball_lateral_speed_yps.abs() < 1e-9);
        assert!(transition.decision_context.ball_altitude_yards.abs() < 1e-9);
        assert!(!transition.decision_context.ball_airborne);
    }

