    #[test]
    fn live_http_tracking_import_trains_team_policies() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 2,
            seed: 114,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();
        let tracking = sample_tracking_pass_dataset();
        let tracking_json = serde_json::to_string(&tracking).expect("tracking json");
        let body = serde_json::json!({
            "source": "unit-tracking.json",
            "format": "json",
            "allowPhysicsWarnings": true,
            "content": tracking_json
        })
        .to_string();

        let import = handle_live_soccer_request(
            &format!(
                "POST /api/tracking-policy HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            ),
            &session,
            &input_queue,
        );

        assert_eq!(import.status, 200);
        let value: serde_json::Value =
            serde_json::from_str(&import.body).expect("tracking import json");
        assert_eq!(value["format"], "json");
        assert_eq!(value["frames"], 2);
        assert_eq!(value["importedTransitions"], 3);
        assert_eq!(value["importedNeuralSamples"], 0);
        assert_eq!(value["trackingTacticalSummary"]["totalTransitions"], 3);
        assert!(
            value["trackingTacticalSummary"]["shapeTransitions"]
                .as_u64()
                .unwrap()
                > 0
        );
        assert!(value["trackingTacticalSummary"]["meanTacticalReward"]
            .as_f64()
            .is_some());
        assert!(
            value["trackingTacticalSummary"]["lookBehindScanTransitions"]
                .as_u64()
                .is_some()
        );
        assert_eq!(value["trainingSkipped"], false);
        assert_eq!(value["physicsRejected"], false);
        assert_eq!(value["physicsSmoke"]["framesAnalyzed"], 2);
        assert!(value["physicsSmoke"]["violationCount"].as_u64().unwrap() > 0);
        assert!(!value["physicsSmoke"]["violations"]
            .as_array()
            .expect("physics smoke violations")
            .is_empty());
        assert!(
            value["physicsSmoke"]["maxBallFrameSpeedYps"]
                .as_f64()
                .unwrap()
                > 0.0
        );
        assert!(
            value["physicsSmoke"]["maxPlayerFrameSpeedYps"]
                .as_f64()
                .unwrap()
                > 0.0
        );
        assert!(value["importedHomeEntries"].as_u64().unwrap() > 0);
        assert!(value["importedHomeTargetEntries"].as_u64().unwrap() > 0);
        assert_eq!(
            value["learning"]["homePolicyTargetEntries"],
            value["importedHomeTargetEntries"]
        );
        assert!(value["learning"]["homePolicyEntries"].as_u64().unwrap() > 0);
    }

    #[test]
    fn tracking_import_trains_neural_learner_when_enabled() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 0,
            neural_learning: SoccerNeuralLearningConfig {
                enabled: true,
                backend: SoccerNeuralLearningBackend::Inline,
                batch_size: 2,
                max_batches_per_tick: 2,
                hidden_units: 8,
                ..SoccerNeuralLearningConfig::default()
            },
            seed: 115,
            ..Default::default()
        });
        let tracking = sample_tracking_pass_dataset();
        let tracking_json = serde_json::to_string(&tracking).expect("tracking json");

        let response = sim
            .import_tracking_for_team_policy(SoccerTrackingImportRequest {
                source: "unit-neural-tracking.json".to_string(),
                format: Some("json".to_string()),
                allow_physics_warnings: true,
                content: tracking_json,
            })
            .expect("tracking import");

        assert_eq!(response.imported_transitions, 3);
        assert_eq!(
            response.imported_neural_samples,
            response.imported_transitions
        );
        assert_eq!(
            response.tracking_tactical_summary.total_transitions,
            response.imported_transitions
        );
        assert!(response.tracking_tactical_summary.shape_transitions > 0);
        assert!(response.learning.neural_learning_enabled);
        assert_eq!(response.learning.neural_learning_backend, "inline");
        assert!(response.learning.neural_learning_training_steps > 0);
        assert!(
            response.learning.neural_learning_samples >= response.imported_neural_samples,
            "neural learner should train on imported tracking samples"
        );
        assert!(response.learning.home_policy_entries > 0);
    }

    #[test]
    fn live_http_tracking_template_import_trains_without_override() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 2,
            seed: 116,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();
        let tracking = soccer_tracking_template_dataset(&MatchConfig {
            duration_seconds: 0.2,
            seed: 116,
            ..Default::default()
        });
        let smoke = soccer_tracking_physics_smoke_report(&tracking);
        assert_eq!(
            smoke.violation_count, 0,
            "template should be clean enough for safe default import: {:?}",
            smoke.violations
        );
        let tracking_json = serde_json::to_string(&tracking).expect("tracking json");
        let body = serde_json::json!({
            "source": "tracking-template.json",
            "format": "json",
            "content": tracking_json
        })
        .to_string();

        let import = handle_live_soccer_request(
            &format!(
                "POST /api/tracking-policy HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            ),
            &session,
            &input_queue,
        );

        assert_eq!(import.status, 200);
        let value: serde_json::Value =
            serde_json::from_str(&import.body).expect("tracking import json");
        assert_eq!(value["format"], "json");
        assert_eq!(value["frames"], 2);
        assert_eq!(value["importedTransitions"], 3);
        assert_eq!(value["trainingSkipped"], false);
        assert_eq!(value["physicsRejected"], false);
        assert_eq!(value["physicsSmoke"]["violationCount"], 0);
        assert_eq!(
            value["physicsSmoke"]["violations"]
                .as_array()
                .unwrap()
                .len(),
            0
        );
        assert!(value["importedHomeEntries"].as_u64().unwrap() > 0);
        assert!(value["importedHomeTargetEntries"].as_u64().unwrap() > 0);
        assert_eq!(
            value["learning"]["homePolicyTargetEntries"],
            value["importedHomeTargetEntries"]
        );
    }

