    #[test]
    fn learned_route_one_uses_visible_runner_shaped_landing_zone() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let holder = 6;
        let runner = 9;
        park_players_except(&mut sim, &[holder, runner]);
        sim.players[holder].position = Vec2::new(30.0, 34.0);
        sim.players[holder].home_position = sim.players[holder].position;
        sim.players[holder].action_facing = FacingBucket::South;
        sim.players[holder].receive_facing = FacingBucket::South;
        sim.players[runner].role = PlayerRole::Forward;
        sim.players[runner].position = Vec2::new(58.0, 70.0);
        sim.players[runner].home_position = sim.players[runner].position;
        sim.players[runner].velocity = Vec2::new(0.0, 4.5);
        sim.ball.holder = Some(holder);
        sim.ball.position = sim.players[holder].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(holder);
        let base = route_one_target_for_player(
            Team::Home,
            sim.players[holder].position,
            sim.config.field_width_yards,
            sim.config.field_length_yards,
        );
        let plan = SoccerLearnedPlan {
            action: "route-one".to_string(),
            target_player: None,
            target_point: None,
        };
        let (action, label) = sim.players[holder]
            .action_from_learned_plan(&plan, &snapshot, &observation)
            .expect("learned route-one should resolve");

        assert_eq!(label, "route-one");
        let SoccerAction::RouteOne { target, .. } = action else {
            panic!("expected route-one action, got {action:?}");
        };
        assert!(
            target.x > base.x + 8.0,
            "learned route-one should use the runner-shaped landing zone: base={base:?} target={target:?}"
        );
        assert!(target.y > sim.config.field_length_yards * 0.56);
    }

    #[test]
    fn route_one_long_ball_tracks_airborne_arc_until_landing_zone() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let holder = 6;
        for player in &mut sim.players {
            player.position = Vec2::new(3.0, 3.0);
            player.velocity = Vec2::zero();
        }
        sim.players[holder].position = Vec2::new(40.0, 36.0);
        sim.ball.holder = Some(holder);
        sim.ball.position = sim.players[holder].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);
        let target = Vec2::new(44.0, 92.0);

        sim.apply_player_intent(PlayerIntent {
            player_id: holder,
            action: SoccerAction::RouteOne {
                target,
                power: 0.94,
            },
            sprint: false,
        });

        let flight = sim
            .ball
            .untargeted_long_ball_flight
            .as_ref()
            .expect("route-one launch stores flight path");
        assert_eq!(flight.action, "route-one");
        assert_eq!(flight.origin, Vec2::new(40.0, 36.0));
        assert_eq!(flight.target, target);
        assert!(flight.launch_speed_yps > 18.0);
        assert!(flight.distance_yards > 50.0);

        let midpoint = flight.origin + (flight.target - flight.origin) * 0.5;
        let midpoint_altitude =
            untargeted_long_ball_altitude_yards(&flight, midpoint, flight.launch_speed_yps * 0.9);
        assert!(
            midpoint_altitude > 6.0,
            "route-one ball should stay materially airborne at carry midpoint: {midpoint_altitude}"
        );
        let near_landing = flight.origin + (flight.target - flight.origin) * 0.99;
        assert!(
            untargeted_long_ball_altitude_yards(
                &flight,
                near_landing,
                flight.launch_speed_yps * 0.7
            ) < 0.6
        );

        sim.integrate_ball();
        let old_speed_only_altitude = loose_long_ball_altitude_yards(sim.ball.velocity.len());
        assert!(
            sim.ball.altitude_yards > old_speed_only_altitude + 0.45,
            "integrated route-one altitude should use flight arc, old={old_speed_only_altitude}, actual={}",
            sim.ball.altitude_yards
        );
    }

