    #[test]
    fn transition_reward_reinforces_check_to_ball_under_holder_pressure() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let holder = 6;
        let runner = 9;
        let marker = 15;
        sim.ball.holder = Some(holder);
        sim.ball.position = Vec2::new(40.0, 58.0);
        sim.ball.last_touch_team = Some(Team::Home);
        for id in 11..22 {
            sim.players[id].position = Vec2::new(72.0, 98.0);
        }
        sim.players[holder].position = sim.ball.position;
        sim.players[runner].position = Vec2::new(29.0, 75.0);
        sim.players[marker].position = Vec2::new(30.0, 75.0);
        sim.players[12].position = Vec2::new(43.0, 58.0);
        sim.players[13].position = Vec2::new(41.5, 55.5);
        sim.players[14].position = Vec2::new(43.0, 60.0);

        let before = WorldSnapshot::from_match(&sim);
        let target = before
            .check_to_ball_target_for(runner, sim.players[runner].home_position)
            .expect("test setup exposes check-to-ball target");
        let decision = test_decision_trace(&before, runner, "check-to-ball");
        let mut closing_after = before.clone();
        closing_after.tick += 1;
        closing_after.clock_seconds += closing_after.dt_seconds;
        if let Some(player) = closing_after
            .players
            .iter_mut()
            .find(|player| player.id == runner)
        {
            player.position = target;
        }
        closing_after.shared_positions = SharedPlayerPositionSnapshot::from_player_snapshots(
            &closing_after.players,
            closing_after.tick,
            closing_after.clock_seconds,
        );
        let mut passive_after = before.clone();
        passive_after.tick += 1;
        passive_after.clock_seconds += passive_after.dt_seconds;
        passive_after.shared_positions = SharedPlayerPositionSnapshot::from_player_snapshots(
            &passive_after.players,
            passive_after.tick,
            passive_after.clock_seconds,
        );

        let closing_reward = soccer_transition_reward(
            &sim.players[runner],
            &decision,
            &before,
            &closing_after,
            0,
            0,
            0,
            0,
            false,
        );
        let passive_reward = soccer_transition_reward(
            &sim.players[runner],
            &decision,
            &before,
            &passive_after,
            0,
            0,
            0,
            0,
            false,
        );

        assert!(
            closing_reward > passive_reward + 0.20,
            "checking to the ball under holder pressure should learn better than staying passive: closing={closing_reward} passive={passive_reward}"
        );
    }

    #[test]
    fn support_operation_order_can_prioritize_check_to_ball() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let holder = 6;
        let receiver = 9;
        let marker = 12;
        sim.ball.holder = Some(holder);
        sim.ball.position = Vec2::new(40.0, 56.0);
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[holder].position = sim.ball.position;
        sim.players[receiver].position = Vec2::new(31.0, 70.0);
        sim.players[marker].position = Vec2::new(32.1, 70.0);
        for id in 11..22 {
            if id != marker {
                sim.players[id].position = Vec2::new(70.0, 98.0);
            }
        }

        let snapshot = WorldSnapshot::from_match(&sim);
        let check_target = snapshot
            .check_to_ball_target_for(receiver, sim.players[receiver].home_position)
            .expect("test setup exposes check-to-ball target");
        let mut first_counts: HashMap<String, usize> = HashMap::new();
        let mut checked_to_ball = 0usize;
        for seed in 0..160 {
            let mut player = sim.players[receiver].clone();
            let intent =
                player.run_time_step(&snapshot, None, None, &mut mulberry32(30_400 + seed));
            let decision = player.last_decision.expect("support decision");
            let first = decision
                .operation_order
                .first()
                .cloned()
                .unwrap_or_default();
            if first == "check-to-ball" {
                checked_to_ball += 1;
                assert_eq!(decision.action, "check-to-ball");
                match intent.action {
                    SoccerAction::MoveTo(target) => {
                        assert!(
                            target.distance(check_target) < 1e-9,
                            "check-to-ball first option should move to check target: {target:?} vs {check_target:?}"
                        );
                    }
                    other => panic!("expected check-to-ball move, got {other:?}"),
                }
            }
            *first_counts.entry(first).or_insert(0) += 1;
        }

        assert!(
            checked_to_ball >= 24,
            "check-to-ball should regularly lead the weighted support order: {first_counts:?}"
        );
        assert!(
            first_counts.len() >= 2,
            "support operation order should remain randomized across options: {first_counts:?}"
        );
    }

    #[test]
    fn learned_support_policy_can_choose_wide_outlet() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig::default());
        let passer = 6;
        let winger = 8;
        sim.ball.holder = Some(passer);
        sim.ball.position = Vec2::new(40.0, 56.0);
        sim.ball.last_touch_team = Some(Team::Home);
        sim.players[passer].position = sim.ball.position;
        sim.players[winger].position = Vec2::new(63.0, 57.0);
        for away in 11..22 {
            sim.players[away].position = Vec2::new(35.0, 88.0 + (away - 11) as f64 * 0.5);
        }

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(winger);
        let options = sim.players[winger].support_action_options(&snapshot);
        assert!(
            options.iter().any(|option| option.label == "wide-outlet"),
            "wide midfielder should expose wide-outlet option: {options:?}"
        );
        let wide_option = options
            .iter()
            .find(|option| option.label == "wide-outlet")
            .expect("wide-outlet option");
        assert!(wide_option.legal);
        assert!(
            wide_option.score > 0.0 && wide_option.probability > 0.0,
            "wide-outlet should be a real autonomous/MDP option: {wide_option:?}"
        );
        assert!(learned_action_label_is_legal(
            "wide_outlet",
            &snapshot,
            winger
        ));

        let plan = SoccerLearnedPlan {
            action: "wide_outlet".to_string(),
            target_player: None,
            target_point: None,
        };
        let (action, label) = sim.players[winger]
            .action_from_learned_plan(&plan, &snapshot, &observation)
            .expect("wide-outlet learned action");
        assert_eq!(label, "wide-outlet");
        match action {
            SoccerAction::MoveTo(target) => {
                assert!(
                    target.x > sim.players[winger].position.x,
                    "right winger should move toward touchline: {target:?}"
                );
                assert!(
                    (target.y - sim.players[winger].position.y) * Team::Home.attack_dir() > 0.0,
                    "wide outlet should still move upfield: {target:?}"
                );
            }
            other => panic!("expected wide-outlet movement, got {other:?}"),
        }
    }

