    #[test]
    fn tackle_resolution_is_probabilistic_between_dribbling_and_defense() {
        let mut tackle_wins = 0;
        let mut dribble_survives = 0;
        for seed in 0..220 {
            let mut sim = SoccerMatch::default_11v11(MatchConfig {
                seed,
                ..Default::default()
            });
            sim.players[0].position = Vec2::new(40.0, 60.0);
            sim.players[0].skills.defending = 8.0;
            sim.players[0].skills.aggression = 5.5;
            sim.players[11].position = Vec2::new(41.2, 60.0);
            sim.players[11].skills.dribbling = 7.0;
            sim.players[11].skills.first_touch = 7.0;
            sim.ball.holder = Some(11);
            sim.ball.position = sim.players[11].position;

            let p = tackle_success_probability(&sim.players[0].skills, &sim.players[11].skills);
            assert!(p > 0.5 && p < 1.0);

            sim.apply_player_intent(PlayerIntent {
                player_id: 0,
                action: SoccerAction::Tackle { target_player: 11 },
                sprint: true,
            });

            if sim.ball.holder == Some(0) {
                let tackle_reward = sim
                    .reward_events
                    .iter()
                    .filter(|event| event.player_id == 0)
                    .map(|event| event.amount)
                    .sum::<f64>();
                assert_eq!(tackle_reward, DEFENSIVE_DISPOSSESSION_REWARD_POINTS);
                tackle_wins += 1;
            } else if sim.ball.holder == Some(11) {
                dribble_survives += 1;
            }
        }

        assert!(tackle_wins > 0);
        assert!(dribble_survives > 0);
    }

    #[test]
    fn dribble_kinds_and_defensive_response_probabilities_match_1v1_contract() {
        let mut rng = mulberry32(44_010);
        let mut left = 0usize;
        let mut right = 0usize;
        let mut carry_forward = 0usize;
        let mut carry_out_left = 0usize;
        let mut carry_out_right = 0usize;
        let mut nutmeg = 0usize;
        for _ in 0..10_000 {
            match choose_dribble_move_kind(&mut rng) {
                DribbleMoveKind::LeftCut => left += 1,
                DribbleMoveKind::RightCut => right += 1,
                DribbleMoveKind::CarryForward => carry_forward += 1,
                DribbleMoveKind::CarryOutLeft => carry_out_left += 1,
                DribbleMoveKind::CarryOutRight => carry_out_right += 1,
                DribbleMoveKind::Nutmeg => nutmeg += 1,
                DribbleMoveKind::ProtectBall
                | DribbleMoveKind::FakeLeftCutRight
                | DribbleMoveKind::FakeRightCutLeft => {}
            }
        }
        let ratio = |count: usize| count as f64 / 10_000.0;
        assert!((ratio(left) - 0.28).abs() < 0.025, "left={left}");
        assert!((ratio(right) - 0.28).abs() < 0.025, "right={right}");
        assert!(
            (ratio(carry_forward) - 0.28).abs() < 0.025,
            "carry_forward={carry_forward}"
        );
        assert!(
            (ratio(carry_out_left) - 0.06).abs() < 0.018,
            "carry_out_left={carry_out_left}"
        );
        assert!(
            (ratio(carry_out_right) - 0.06).abs() < 0.018,
            "carry_out_right={carry_out_right}"
        );
        assert!((ratio(nutmeg) - 0.04).abs() < 0.014, "nutmeg={nutmeg}");

        let attacker = SkillProfile {
            dribbling: 7.0,
            first_touch: 7.0,
            acceleration: 7.0,
            ..neutral_tracking_skill_profile(PlayerRole::Forward)
        };
        let defender = SkillProfile {
            defending: 7.0,
            aggression: 7.0,
            ..neutral_tracking_skill_profile(PlayerRole::Defender)
        };
        let hold_up = dribble_dispossession_probability(
            &defender,
            &attacker,
            DefenderDribbleResponse::HoldUp,
        );
        let commit = dribble_dispossession_probability(
            &defender,
            &attacker,
            DefenderDribbleResponse::Commit,
        );
        assert!((hold_up - HOLD_UP_DISPOSSESSION_PROBABILITY).abs() < 1e-9);
        assert!((commit - COMMIT_DISPOSSESSION_PROBABILITY).abs() < 1e-9);

        let hold_up_beat = dribble_beat_probability(
            DribbleMoveKind::LeftCut,
            &attacker,
            &defender,
            DefenderDribbleResponse::HoldUp,
        );
        let commit_beat = dribble_beat_probability(
            DribbleMoveKind::LeftCut,
            &attacker,
            &defender,
            DefenderDribbleResponse::Commit,
        );
        assert!(
            (commit_beat / hold_up_beat - COMMIT_DRIBBLE_BEAT_MULTIPLIER).abs() < 0.02,
            "hold_up_beat={hold_up_beat}, commit_beat={commit_beat}"
        );
    }

    #[test]
    fn hold_up_defender_can_dispossess_dribbler_without_committing() {
        let mut observed = false;
        for seed in 0..260 {
            let mut sim = SoccerMatch::default_11v11(MatchConfig {
                seed,
                ..Default::default()
            });
            let defender = 0;
            let attacker = 11;
            sim.players[defender].position = Vec2::new(40.0, 60.0);
            sim.players[defender].skills.defending = 9.4;
            sim.players[defender].skills.aggression = 8.0;
            sim.players[attacker].position = Vec2::new(41.0, 60.0);
            sim.players[attacker].skills.dribbling = 2.0;
            sim.players[attacker].skills.first_touch = 2.0;
            sim.ball.holder = Some(attacker);
            sim.ball.position = sim.players[attacker].position;
            let before = WorldSnapshot::from_match(&sim);
            sim.players[attacker].last_decision =
                Some(test_decision_trace(&before, attacker, "right-cut"));
            sim.players[defender].last_decision =
                Some(test_decision_trace(&before, defender, "defend"));

            sim.resolve_dribble_hold_up_contests();

            if sim.ball.holder == Some(defender) {
                let defender_reward = sim
                    .reward_events
                    .iter()
                    .filter(|event| event.player_id == defender)
                    .map(|event| event.amount)
                    .sum::<f64>();
                assert_eq!(defender_reward, DEFENSIVE_DISPOSSESSION_REWARD_POINTS);
                assert!(sim
                    .events
                    .iter()
                    .any(|event| event.kind == "hold-up-dispossession"));
                observed = true;
                break;
            }
        }

        assert!(observed, "expected at least one hold-up dispossession");
    }

