    #[test]
    fn live_http_policy_autosave_writes_learning_checkpoint_after_step() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            seed: 157,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();
        let policy_path = std::env::temp_dir().join(format!(
            "soccer-policy-autosave-test-{}.json",
            std::process::id()
        ));
        let history_path = policy_history_disk_path(&policy_path);
        let _ = std::fs::remove_file(&policy_path);
        let _ = std::fs::remove_file(&history_path);

        let autosave_body = serde_json::json!({
            "enabled": true,
            "intervalTicks": 1,
            "path": policy_path.display().to_string()
        })
        .to_string();
        let autosave = handle_live_soccer_request(
            &format!(
                "POST /api/team-policy/autosave HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                autosave_body.len(),
                autosave_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(autosave.status, 200);
        let autosave_value: serde_json::Value =
            serde_json::from_str(&autosave.body).expect("autosave config json");
        assert_eq!(autosave_value["autosave"]["enabled"], true);
        assert_eq!(autosave_value["autosave"]["intervalTicks"], 1);
        assert_eq!(
            autosave_value["autosave"]["historyPath"],
            history_path.display().to_string()
        );
        assert_eq!(autosave_value["storage"]["backend"], "json-disk");
        assert_eq!(
            autosave_value["storage"]["runtimePath"],
            policy_path.display().to_string()
        );
        assert_eq!(
            autosave_value["storage"]["historyPath"],
            history_path.display().to_string()
        );
        assert_eq!(autosave_value["storage"]["postgresEnabled"], true);
        assert_eq!(
            autosave_value["storage"]["postgresTable"],
            SOCCER_POLICY_POSTGRES_POLICY_VERSIONS_TABLE
        );
        assert_eq!(autosave_value["autosave"]["historyRecords"], 0);
        assert!(!policy_path.exists());
        assert!(!history_path.exists());

        let step_body = r#"{"ticks":4,"recordEveryTicks":4}"#;
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(step.status, 200);
        assert!(policy_path.exists());
        assert!(history_path.exists());
        let step_value: serde_json::Value =
            serde_json::from_str(&step.body).expect("step with autosave json");
        assert_eq!(step_value["policyAutosave"]["enabled"], true);
        assert_eq!(step_value["policyAutosave"]["lastSavedTick"], 4);
        assert_eq!(
            step_value["policyAutosave"]["historyPath"],
            history_path.display().to_string()
        );
        assert_eq!(step_value["policyAutosave"]["historyRecords"], 1);
        assert!(step_value["policyAutosave"]["lastHistoryError"].is_null());
        assert!(
            step_value["policyAutosave"]["lastSavedPolicyVisits"]
                .as_u64()
                .unwrap()
                > 0
        );

        let artifact = read_soccer_team_policy_artifact(&policy_path).expect("autosaved policy");
        assert_eq!(artifact.summary.ticks, 4);
        assert!(!artifact.home_entries.is_empty());
        assert!(!artifact.away_entries.is_empty());
        let history = read_policy_history_jsonl(&history_path);
        assert_eq!(history.len(), 1);
        assert_eq!(history[0]["kind"], "autosave");
        assert_eq!(history[0]["tick"].as_u64().unwrap(), 4);
        assert_eq!(history[0]["path"], policy_path.display().to_string());
        assert_eq!(
            history[0]["homePolicyEntries"].as_u64().unwrap(),
            artifact.home_entries.len() as u64
        );
        assert_eq!(
            history[0]["homePolicyTargetEntries"].as_u64().unwrap(),
            artifact.home_target_entries.len() as u64
        );
        let history_response = handle_live_soccer_request(
            "GET /api/team-policy/history HTTP/1.1\r\nHost: local\r\n\r\n",
            &session,
            &input_queue,
        );
        assert_eq!(history_response.status, 200);
        let history_value: serde_json::Value =
            serde_json::from_str(&history_response.body).expect("policy history json");
        assert_eq!(history_value["path"], policy_path.display().to_string());
        assert_eq!(
            history_value["historyPath"],
            history_path.display().to_string()
        );
        assert_eq!(history_value["totalRecords"], 1);
        assert_eq!(history_value["records"].as_array().unwrap().len(), 1);
        assert_eq!(history_value["records"][0]["kind"], "autosave");
        let _ = std::fs::remove_file(policy_path);
        let _ = std::fs::remove_file(history_path);
    }

    #[test]
    fn live_http_reset_writes_episode_policy_checkpoint_when_autosave_enabled() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            seed: 158,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();
        let policy_path = std::env::temp_dir().join(format!(
            "soccer-policy-episode-checkpoint-test-{}.json",
            std::process::id()
        ));
        let history_path = policy_history_disk_path(&policy_path);
        let _ = std::fs::remove_file(&policy_path);
        let _ = std::fs::remove_file(&history_path);

        let autosave_body = serde_json::json!({
            "enabled": true,
            "intervalTicks": 1000,
            "path": policy_path.display().to_string()
        })
        .to_string();
        let autosave = handle_live_soccer_request(
            &format!(
                "POST /api/team-policy/autosave HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                autosave_body.len(),
                autosave_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(autosave.status, 200);

        let step_body = r#"{"ticks":2,"recordEveryTicks":1}"#;
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(step.status, 200);
        assert!(!policy_path.exists());
        assert!(!history_path.exists());
        let step_value: serde_json::Value =
            serde_json::from_str(&step.body).expect("pre-reset step json");
        let home_entries = step_value["learning"]["homePolicyEntries"]
            .as_u64()
            .unwrap();
        let away_entries = step_value["learning"]["awayPolicyEntries"]
            .as_u64()
            .unwrap();
        assert!(home_entries > 0);
        assert!(away_entries > 0);

        let reset = handle_live_soccer_request(
            "POST /api/reset HTTP/1.1\r\nContent-Length: 0\r\n\r\n",
            &session,
            &input_queue,
        );
        assert_eq!(reset.status, 200);
        assert!(policy_path.exists());
        assert!(history_path.exists());
        let reset_value: serde_json::Value = serde_json::from_str(&reset.body).expect("reset json");
        assert_eq!(reset_value["previousSummary"]["ticks"], 2);
        assert_eq!(reset_value["state"]["summary"]["ticks"], 0);
        assert_eq!(
            reset_value["episodePolicyCheckpoint"]["path"],
            policy_path.display().to_string()
        );
        assert_eq!(
            reset_value["episodePolicyCheckpoint"]["homePolicyEntries"],
            home_entries
        );
        assert_eq!(
            reset_value["episodePolicyCheckpoint"]["awayPolicyEntries"],
            away_entries
        );
        assert_eq!(reset_value["state"]["policyAutosave"]["lastSavedTick"], 2);
        assert_eq!(
            reset_value["state"]["policyAutosave"]["historyPath"],
            history_path.display().to_string()
        );
        assert_eq!(reset_value["state"]["policyAutosave"]["historyRecords"], 1);
        assert!(
            reset_value["state"]["policyAutosave"]["lastSavedPolicyVisits"]
                .as_u64()
                .unwrap()
                > 0
        );

        let artifact =
            read_soccer_team_policy_artifact(&policy_path).expect("episode checkpoint policy");
        assert_eq!(artifact.summary.ticks, 2);
        assert_eq!(artifact.home_entries.len() as u64, home_entries);
        assert_eq!(artifact.away_entries.len() as u64, away_entries);
        let history = read_policy_history_jsonl(&history_path);
        assert_eq!(history.len(), 1);
        assert_eq!(history[0]["kind"], "episode-checkpoint");
        assert_eq!(history[0]["tick"].as_u64().unwrap(), 2);
        assert_eq!(history[0]["path"], policy_path.display().to_string());
        let _ = std::fs::remove_file(policy_path);
        let _ = std::fs::remove_file(history_path);
    }

    #[test]
    fn live_http_policy_prune_route_bounds_live_policy_entries() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            seed: 159,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();

        let step_body = r#"{"ticks":3,"recordEveryTicks":3}"#;
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(step.status, 200);
        let step_value: serde_json::Value =
            serde_json::from_str(&step.body).expect("pre-prune step json");
        let home_entries = step_value["learning"]["homePolicyEntries"]
            .as_u64()
            .unwrap();
        let away_entries = step_value["learning"]["awayPolicyEntries"]
            .as_u64()
            .unwrap();
        assert!(home_entries > 3);
        assert!(away_entries > 3);

        let prune_body = serde_json::json!({
            "maxActionEntriesPerTeam": 3,
            "maxTargetEntriesPerTeam": 3,
            "minVisits": 0
        })
        .to_string();
        let prune = handle_live_soccer_request(
            &format!(
                "POST /api/team-policy/prune HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                prune_body.len(),
                prune_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(prune.status, 200);
        let prune_value: serde_json::Value =
            serde_json::from_str(&prune.body).expect("policy prune json");
        assert!(prune_value["removedEntries"].as_u64().unwrap() > 0);
        assert_eq!(
            prune_value["summary"]["home"]["actionEntriesBefore"],
            home_entries
        );
        assert_eq!(
            prune_value["summary"]["away"]["actionEntriesBefore"],
            away_entries
        );
        assert!(
            prune_value["summary"]["home"]["actionEntriesAfter"]
                .as_u64()
                .unwrap()
                <= 3
        );
        assert!(
            prune_value["summary"]["away"]["actionEntriesAfter"]
                .as_u64()
                .unwrap()
                <= 3
        );
        assert!(
            prune_value["learning"]["homePolicyEntries"]
                .as_u64()
                .unwrap()
                <= 3
        );
        assert!(
            prune_value["learning"]["awayPolicyEntries"]
                .as_u64()
                .unwrap()
                <= 3
        );

        let policy = handle_live_soccer_request(
            "GET /api/team-policy HTTP/1.1\r\nHost: local\r\n\r\n",
            &session,
            &input_queue,
        );
        assert_eq!(policy.status, 200);
        let policy_value: serde_json::Value =
            serde_json::from_str(&policy.body).expect("pruned team policy json");
        assert!(policy_value["homeEntries"].as_array().unwrap().len() <= 3);
        assert!(policy_value["awayEntries"].as_array().unwrap().len() <= 3);
        assert!(policy_value["homeTargetEntries"].as_array().unwrap().len() <= 3);
        assert!(policy_value["awayTargetEntries"].as_array().unwrap().len() <= 3);
    }

    #[test]
    fn live_http_reset_starts_new_match_while_preserving_policy_and_controller() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            learning_interval_ticks: 1,
            max_human_players: 2,
            seed: 160,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();

        let step_body = r#"{"ticks":2,"recordEveryTicks":1}"#;
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(step.status, 200);
        let step_value: serde_json::Value =
            serde_json::from_str(&step.body).expect("pre-reset step json");
        let home_entries = step_value["learning"]["homePolicyEntries"]
            .as_u64()
            .unwrap();
        let away_entries = step_value["learning"]["awayPolicyEntries"]
            .as_u64()
            .unwrap();
        assert!(home_entries > 0);
        assert!(away_entries > 0);

        let assign_body = r#"{"controllerSlot":0,"playerId":5}"#;
        let assign = handle_live_soccer_request(
            &format!(
                "POST /api/assign HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                assign_body.len(),
                assign_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(assign.status, 200);

        let reset = handle_live_soccer_request(
            "POST /api/reset HTTP/1.1\r\nContent-Length: 0\r\n\r\n",
            &session,
            &input_queue,
        );
        assert_eq!(reset.status, 200);
        let reset_value: serde_json::Value = serde_json::from_str(&reset.body).expect("reset json");
        assert_eq!(reset_value["previousSummary"]["ticks"], 2);
        assert_eq!(reset_value["previousEpisode"]["episodeIndex"], 0);
        assert_eq!(reset_value["previousEpisode"]["summary"]["ticks"], 2);
        assert_eq!(reset_value["state"]["episodeIndex"], 1);
        assert_ne!(
            reset_value["state"]["config"]["seed"],
            serde_json::json!(160)
        );
        assert_eq!(
            reset_value["state"]["completedEpisodes"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
        assert_eq!(
            reset_value["state"]["completedEpisodes"][0]["summary"]["ticks"],
            2
        );
        assert_eq!(reset_value["state"]["summary"]["ticks"], 0);
        assert_eq!(reset_value["state"]["learning"]["totalTransitions"], 0);
        assert_eq!(
            reset_value["state"]["learning"]["homePolicyEntries"],
            home_entries
        );
        assert_eq!(
            reset_value["state"]["learning"]["awayPolicyEntries"],
            away_entries
        );
        assert_eq!(reset_value["preservedTeamPolicy"], true);
        assert_eq!(reset_value["keptControllerAssignments"], true);
        assert!(reset_value["state"]["controllerAssignments"]
            .as_array()
            .unwrap()
            .iter()
            .any(|assignment| assignment["controllerSlot"] == 0 && assignment["playerId"] == 5));

        let tracking = handle_live_soccer_request(
            "GET /api/tracking-dataset HTTP/1.1\r\nHost: local\r\n\r\n",
            &session,
            &input_queue,
        );
        let tracking_value: serde_json::Value =
            serde_json::from_str(&tracking.body).expect("post-reset tracking json");
        assert_eq!(tracking_value["frames"].as_array().unwrap().len(), 1);
        assert_eq!(tracking_value["frames"][0]["tick"], 0);

        let seeded_reset_body = r#"{"seed":4242,"preserveTeamPolicy":true,"preserveSharedPolicy":true,"keepControllerAssignments":true}"#;
        let seeded_reset = handle_live_soccer_request(
            &format!(
                "POST /api/reset HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                seeded_reset_body.len(),
                seeded_reset_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(seeded_reset.status, 200);
        let seeded_reset_value: serde_json::Value =
            serde_json::from_str(&seeded_reset.body).expect("seeded reset json");
        assert_eq!(seeded_reset_value["state"]["config"]["seed"], 4242);
    }

    #[test]
    fn live_server_autoloads_team_policy_from_configured_json_path() {
        let policy_path = std::env::temp_dir().join(format!(
            "soccer-policy-autoload-test-{}.json",
            std::process::id()
        ));
        let _ = std::fs::remove_file(&policy_path);

        let mut source = SoccerRealtimeSession::new_without_controller_threads(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 0,
            seed: 158,
            ..Default::default()
        });
        source.step(SoccerStepRequest {
            ticks: 4,
            record_every_ticks: Some(4),
            ..Default::default()
        });
        let saved = source
            .save_team_policy_artifact_to_path(&policy_path)
            .expect("save source policy");
        assert!(saved.home_policy_entries > 0);
        assert!(saved.away_policy_entries > 0);

        let server = SoccerLiveServer::new(SoccerLiveServerConfig {
            match_config: MatchConfig {
                duration_seconds: 1.0,
                max_human_players: 0,
                seed: 159,
                ..Default::default()
            },
            http_worker_threads: 2,
            policy_disk_path: policy_path.display().to_string(),
            autoload_team_policy: true,
            autosave_team_policy: true,
            policy_autosave_interval_ticks: 3,
            ..Default::default()
        });
        let state = server.session.lock().unwrap().state_response();

        assert_eq!(
            state.learning.home_policy_entries,
            saved.home_policy_entries
        );
        assert_eq!(
            state.learning.away_policy_entries,
            saved.away_policy_entries
        );
        assert_eq!(
            state.learning.home_policy_target_entries,
            saved.home_policy_target_entries
        );
        assert_eq!(
            state.learning.away_policy_target_entries,
            saved.away_policy_target_entries
        );
        assert!(state.policy_autosave.enabled);
        assert_eq!(state.policy_autosave.interval_ticks, 3);
        assert_eq!(
            state.policy_autosave.path,
            policy_path.display().to_string()
        );
        assert_eq!(state.policy_autosave.last_saved_tick, Some(0));
        assert!(state.policy_autosave.last_saved_policy_visits > 0);
        assert!(state.policy_autosave.last_error.is_none());
        assert_eq!(state.policy_storage.backend, "json-disk");
        assert_eq!(
            state.policy_storage.runtime_path,
            policy_path.display().to_string()
        );
        assert!(state.policy_storage.stores_q_values);
        assert!(state.policy_storage.stores_visits);
        assert!(state.policy_storage.stores_action_probabilities);
        assert!(state.policy_storage.action_probabilities_derived);
        assert!(state.policy_storage.postgres_enabled);
        assert_eq!(
            state.policy_storage.postgres_table.as_deref(),
            Some(SOCCER_POLICY_POSTGRES_POLICY_VERSIONS_TABLE)
        );
        assert_eq!(
            state.policy_storage.postgres_contract.backend,
            SOCCER_POLICY_POSTGRES_BACKEND
        );
        assert_eq!(
            state.policy_storage.postgres_contract.retention_model,
            SOCCER_POLICY_POSTGRES_RETENTION_MODEL
        );
        assert!(
            !state
                .policy_storage
                .postgres_contract
                .stores_all_weight_history
        );
        assert_eq!(
            state.policy_storage.postgres_contract.tables.policy_entries,
            SOCCER_POLICY_POSTGRES_POLICY_ENTRIES_TABLE
        );
        assert!(state.policy_probability.home_states > 0);
        assert!(state.policy_probability.away_states > 0);
        assert_eq!(state.live_http.worker_model, "worker-pool");
        assert_eq!(state.live_http.worker_threads, 2);
        assert!(state.live_http.reuses_workers);
        assert!(!state.live_http.spawns_per_request);
        assert!(state.live_http.batches_step_ticks);

        let _ = std::fs::remove_file(policy_path);
    }

    #[test]
    fn live_http_assign_route_updates_controller_assignments() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 2,
            neural_learning: SoccerNeuralLearningConfig {
                enabled: true,
                ..Default::default()
            },
            seed: 58,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();

        let body = r#"{"controllerSlot":0,"playerId":5}"#;
        let assign = handle_live_soccer_request(
            &format!(
                "POST /api/assign HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(assign.status, 200);
        let assign_value: serde_json::Value =
            serde_json::from_str(&assign.body).expect("assignment json");
        assert!(assign_value["controllerAssignments"]
            .as_array()
            .unwrap()
            .iter()
            .any(|a| a["controllerSlot"] == 0 && a["playerId"] == 5));
        assert_eq!(assign_value["config"]["learningEnabled"], true);
        assert_eq!(assign_value["config"]["neuralLearning"]["enabled"], true);
        assert_eq!(assign_value["learning"]["learningEnabled"], true);
        assert_eq!(assign_value["learning"]["neuralLearningEnabled"], true);
        assert_eq!(
            session.lock().unwrap().match_ref().players[5].controller_slot,
            Some(0)
        );
        assert!(session.lock().unwrap().match_ref().config.learning_enabled);

        let start_x = session.lock().unwrap().match_ref().players[5].position.x;
        let step_body = r#"{"ticks":1,"inputs":[{"controllerSlot":0,"playerId":5,"seq":1,"axis":{"x":1.0,"y":0.0},"sprint":true,"pass":false,"shoot":false,"targetPlayer":null}]}"#;
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(step.status, 200);
        let step_value: serde_json::Value = serde_json::from_str(&step.body).expect("step json");
        let controlled_player = step_value["frame"]["players"]
            .as_array()
            .expect("frame players")
            .iter()
            .find(|player| player["id"] == 5)
            .expect("controlled player");
        let observation = &controlled_player["lastDecision"]["observation"];
        assert_eq!(observation["controllerSlot"].as_u64(), Some(0));
        assert_eq!(observation["humanControlled"], true);
        assert_eq!(observation["humanInputPresent"], true);
        assert_eq!(observation["humanInputSeq"].as_u64(), Some(1));
        assert!(
            observation["humanInputQueueAgeMs"].as_u64().is_some(),
            "live step JSON should expose consumed controller queue age"
        );
        assert_eq!(
            step_value["frame"]["centralBrain"]["controlledHumanPlayers"].as_u64(),
            Some(1)
        );
        let central_assignments = step_value["frame"]["centralBrain"]["controllerAssignments"]
            .as_array()
            .expect("central brain controller assignments");
        assert_eq!(central_assignments.len(), 1);
        assert_eq!(central_assignments[0]["controllerSlot"].as_u64(), Some(0));
        assert_eq!(central_assignments[0]["playerId"].as_u64(), Some(5));
        assert_eq!(
            step_value["frame"]["centralBrain"]["lastDecision"]["controlledHumanPlayers"].as_u64(),
            Some(1)
        );
        assert_eq!(
            step_value["frame"]["centralBrain"]["lastDecision"]["controllerAssignments"][0]
                ["playerId"]
                .as_u64(),
            Some(5)
        );
        assert!(session.lock().unwrap().match_ref().players[5].position.x > start_x);
    }

    #[test]
    fn live_http_routes_accept_four_human_controller_slots() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 4,
            seed: 185,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();

        assert_eq!(session.lock().unwrap().owned_controller_thread_count(), 4);
        for slot in 0..4 {
            let body = serde_json::json!({
                "controllerSlot": slot,
                "playerId": slot
            })
            .to_string();
            let assign = handle_live_soccer_request(
                &format!(
                    "POST /api/assign HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                    body.len(),
                    body
                ),
                &session,
                &input_queue,
            );
            assert_eq!(assign.status, 200);
        }

        let start_x = {
            let session = session.lock().unwrap();
            (0..4)
                .map(|player_id| session.match_ref().players[player_id].position.x)
                .collect::<Vec<_>>()
        };
        let inputs = (0..4)
            .map(|slot| {
                serde_json::json!({
                    "controllerSlot": slot,
                    "playerId": slot,
                    "seq": 1,
                    "axis": {"x": 1.0, "y": 0.0},
                    "sprint": true,
                    "pass": false,
                    "shoot": false,
                    "targetPlayer": null
                })
            })
            .collect::<Vec<_>>();
        let step_body = serde_json::json!({
            "ticks": 1,
            "recordEveryTicks": 1,
            "inputs": inputs
        })
        .to_string();
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );

        assert_eq!(step.status, 200);
        let value: serde_json::Value = serde_json::from_str(&step.body).expect("step json");
        assert_eq!(value["acceptedInputs"], 4);
        assert_eq!(value["queuedHumanInputs"], 0);
        assert_eq!(
            value["controllerAssignments"]
                .as_array()
                .expect("assignments")
                .len(),
            4
        );
        assert_eq!(
            value["controllerThreads"]
                .as_array()
                .expect("controller threads")
                .len(),
            4
        );
        assert_eq!(value["controllerYield"]["assignedPlayers"], 4);
        assert_eq!(value["controllerYield"]["waitAttempts"], 1);
        assert_eq!(value["controllerYield"]["lateWaitAttempts"], 0);
        assert_eq!(value["controllerYield"]["lastWaitLate"], false);
        assert_eq!(value["controllerYield"]["lastQueuedAfter"], 4);
        assert_eq!(value["controllerLatencyBudget"]["tickBudgetMs"], 100.0);
        assert_eq!(
            value["controllerLatencyBudget"]["consumedInputs"], 4,
            "all four controller frames should be consumed by the single-threaded tick"
        );
        assert!(
            value["controllerLatencyBudget"]["estimatedControlLatencyMs"]
                .as_f64()
                .unwrap()
                <= value["controllerLatencyBudget"]["tickBudgetMs"]
                    .as_f64()
                    .unwrap()
        );
        assert_eq!(value["controllerLatencyBudget"]["overBudget"], false);
        let budget_slots = value["controllerLatencyBudget"]["slots"]
            .as_array()
            .expect("controller latency budget slots");
        assert_eq!(budget_slots.len(), 4);
        assert_eq!(
            value["frame"]["agentScheduleSummary"]["complete"], true,
            "live JSON should expose a complete runtime loop contract"
        );
        assert_eq!(
            value["frame"]["agentScheduleSummary"]["totalAgents"].as_u64(),
            Some(27)
        );
        assert_eq!(
            value["frame"]["agentScheduleSummary"]["playerCount"].as_u64(),
            Some(22)
        );
        assert_eq!(
            value["frame"]["agentScheduleSummary"]["officialCount"].as_u64(),
            Some(3)
        );
        assert_eq!(
            value["frame"]["agentScheduleSummary"]["ballCount"].as_u64(),
            Some(1)
        );
        assert_eq!(
            value["frame"]["centralBrain"]["controlledHumanPlayers"].as_u64(),
            Some(4)
        );
        assert!(value["controllerYield"]["lastWaitMs"].as_f64().unwrap() >= 0.0);
        assert!(value["controllerYield"]["totalWaitMs"].as_f64().unwrap() >= 0.0);
        assert!(
            value["controllerYield"]["maxWaitMs"].as_f64().unwrap()
                >= value["controllerYield"]["lastWaitMs"].as_f64().unwrap()
        );
        let frame_players = value["frame"]["players"]
            .as_array()
            .expect("live frame players");

        for slot in 0..4 {
            let thread_stats = value["controllerThreads"]
                .as_array()
                .unwrap()
                .iter()
                .find(|stats| stats["controllerSlot"] == slot)
                .expect("controller thread stats");
            assert_eq!(thread_stats["acceptedFrames"], 1);
            assert_eq!(thread_stats["pushedFrames"], 1);
            assert_eq!(thread_stats["debouncedFrames"], 1);
            assert!(thread_stats["lastDebounceMs"].as_f64().unwrap() >= 0.0);
            assert!(thread_stats["totalDebounceMs"].as_f64().unwrap() >= 0.0);
            assert!(
                thread_stats["maxDebounceMs"].as_f64().unwrap()
                    >= thread_stats["lastDebounceMs"].as_f64().unwrap()
            );
            let slot_budget = budget_slots
                .iter()
                .find(|budget| budget["controllerSlot"] == slot)
                .expect("slot latency budget");
            assert_eq!(slot_budget["assigned"], true);
            assert_eq!(slot_budget["playerId"], slot);
            assert!(slot_budget["pending"].is_boolean());
            assert!(slot_budget["acceptedFrames"].as_u64().unwrap() >= 1);
            assert!(slot_budget["pushedFrames"].as_u64().unwrap() >= 1);
            assert!(slot_budget["debouncedFrames"].as_u64().unwrap() >= 1);
            assert_eq!(
                slot_budget["consumedInputs"], 1,
                "assigned slot {slot} should consume exactly one coalesced frame in the tick"
            );
            assert!(
                slot_budget["estimatedControlLatencyMs"].as_f64().unwrap()
                    <= value["controllerLatencyBudget"]["tickBudgetMs"]
                        .as_f64()
                        .unwrap()
            );
            assert_eq!(slot_budget["overBudget"], false);
            assert!(value["controllerAssignments"]
                .as_array()
                .unwrap()
                .iter()
                .any(|assignment| assignment["controllerSlot"] == slot
                    && assignment["playerId"] == slot));
            let player = frame_players
                .iter()
                .find(|player| player["id"] == slot)
                .expect("human-controlled frame player");
            assert_eq!(player["controllerSlot"].as_u64(), Some(slot as u64));
            assert!(player["scheduledIndex"].as_u64().is_some());
            assert!(!player["positionHistory"]
                .as_array()
                .expect("controlled player history")
                .is_empty());
            assert_eq!(player["lastDecision"]["action"], "human-move");
            assert_eq!(
                player["lastDecision"]["observation"]["humanInputPresent"],
                true
            );
            assert_eq!(
                player["lastDecision"]["observation"]["controllerSlot"].as_u64(),
                Some(slot as u64)
            );
            assert_eq!(
                player["lastDecision"]["observation"]["humanInputSeq"].as_u64(),
                Some(1)
            );
        }

        let session = session.lock().unwrap();
        for player_id in 0..4 {
            let player = &session.match_ref().players[player_id];
            assert!(
                player.position.x > start_x[player_id],
                "player {player_id} should move right from HTTP controller input"
            );
            let decision = player
                .last_decision
                .as_ref()
                .expect("human-controlled player decision");
            assert_eq!(decision.operation_order, vec!["human-input".to_string()]);
            assert_eq!(decision.action, "human-move");
        }
    }

    #[test]
    fn live_http_step_coalesces_same_slot_controller_burst_to_latest_frame() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            max_human_players: 1,
            seed: 186,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();
        {
            session
                .lock()
                .unwrap()
                .match_mut()
                .assign_controller_slot(0, Some(0))
                .expect("assign human controller");
        }

        let inputs = vec![
            serde_json::json!({
                "controllerSlot": 0,
                "playerId": 0,
                "seq": 1,
                "axis": {"x": -1.0, "y": 0.0},
                "sprint": false,
                "pass": false,
                "shoot": false,
                "targetPlayer": null
            }),
            serde_json::json!({
                "controllerSlot": 0,
                "playerId": 0,
                "seq": 3,
                "axis": {"x": 1.0, "y": 0.0},
                "sprint": true,
                "pass": false,
                "shoot": false,
                "targetPlayer": null
            }),
            serde_json::json!({
                "controllerSlot": 0,
                "playerId": 0,
                "seq": 2,
                "axis": {"x": 0.0, "y": -1.0},
                "sprint": false,
                "pass": false,
                "shoot": false,
                "targetPlayer": null
            }),
            serde_json::json!({
                "controllerSlot": 0,
                "playerId": 1,
                "seq": 4,
                "axis": {"x": 0.0, "y": 1.0},
                "sprint": false,
                "pass": false,
                "shoot": false,
                "targetPlayer": null
            }),
            serde_json::json!({
                "controllerSlot": 1,
                "playerId": 1,
                "seq": 5,
                "axis": {"x": 1.0, "y": 1.0},
                "sprint": true,
                "pass": false,
                "shoot": false,
                "targetPlayer": null
            }),
        ];
        let step_body = serde_json::json!({
            "ticks": 1,
            "recordEveryTicks": 1,
            "inputs": inputs
        })
        .to_string();
        let step = handle_live_soccer_request(
            &format!(
                "POST /api/step HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                step_body.len(),
                step_body
            ),
            &session,
            &input_queue,
        );

        assert_eq!(step.status, 200);
        let value: serde_json::Value = serde_json::from_str(&step.body).expect("step json");
        assert_eq!(
            value["acceptedInputs"], 1,
            "same-slot bursts should be coalesced before entering the native controller mailbox"
        );
        assert_eq!(value["queuedHumanInputs"], 0);
        assert_eq!(value["controllerYield"]["assignedPlayers"], 1);
        assert_eq!(value["controllerYield"]["lastQueuedAfter"], 1);
        assert_eq!(value["controllerThreads"].as_array().unwrap().len(), 1);
        assert_eq!(value["controllerThreads"][0]["acceptedFrames"], 1);
        assert_eq!(value["controllerThreads"][0]["latestSeqSeen"], 3);
        assert_eq!(
            value["controllerLatencyBudget"]["consumedInputs"], 1,
            "main loop should consume one latest frame for the assigned slot"
        );
        let player = value["frame"]["players"]
            .as_array()
            .expect("frame players")
            .iter()
            .find(|player| player["id"] == 0)
            .expect("controlled player");
        assert_eq!(player["lastDecision"]["action"], "human-move");
        assert_eq!(
            player["lastDecision"]["observation"]["humanInputSeq"].as_u64(),
            Some(3)
        );
        assert_eq!(
            player["lastDecision"]["observation"]["humanInputPresent"],
            true
        );
    }

