    #[test]
    fn live_http_self_play_training_route_runs_and_imports_policy() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            seed: 590,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();
        let body = serde_json::json!({
            "episodes": 1,
            "minutes": 0.01,
            "periodCount": 2,
            "periodBreakRecoverySeconds": 15.0,
            "dtSeconds": 0.2,
            "learningIntervalTicks": 1,
            "seed": 990,
            "options": {
                "alpha": 0.2,
                "gamma": 0.94
            },
            "tacticalLearning": {
                "attackFlankLaneWeight": 0.22,
                "defenseContractDeltaWeight": 0.33
            },
            "importIntoSession": true
        })
        .to_string();

        let response = handle_live_soccer_request(
            &format!(
                "POST /api/train-self-play HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            ),
            &session,
            &input_queue,
        );

        assert_eq!(response.status, 200);
        let value: serde_json::Value =
            serde_json::from_str(&response.body).expect("self-play response json");
        assert_eq!(value["artifact"]["episodes"].as_array().unwrap().len(), 1);
        assert_eq!(
            value["artifact"]["config"]["periodCount"],
            serde_json::json!(2)
        );
        assert_eq!(
            value["artifact"]["config"]["periodBreakRecoverySeconds"],
            serde_json::json!(15.0)
        );
        assert_eq!(
            value["artifact"]["tacticalLearning"]["attackFlankLaneWeight"],
            serde_json::json!(0.22)
        );
        assert_eq!(
            value["artifact"]["config"]["tacticalLearning"]["defenseContractDeltaWeight"],
            serde_json::json!(0.33)
        );
        assert_eq!(value["learnedParams"]["episodes"], serde_json::json!(1));
        assert_eq!(
            value["learnedParams"]["tacticalLearning"]["attackFlankLaneWeight"],
            serde_json::json!(0.22)
        );
        assert!(
            value["learnedParams"]["homeEntries"]
                .as_array()
                .unwrap()
                .len()
                > 0
        );
        assert!(value["importedHomeEntries"].as_u64().unwrap() > 0);
        assert!(value["importedAwayEntries"].as_u64().unwrap() > 0);
        assert_eq!(
            value["learning"]["homePolicyEntries"],
            value["importedHomeEntries"]
        );
        assert_eq!(
            session
                .lock()
                .unwrap()
                .match_ref()
                .config
                .tactical_learning
                .attack_flank_lane_weight,
            0.22
        );
    }

    #[test]
    fn live_http_learning_route_updates_runtime_switches() {
        let session = Arc::new(Mutex::new(SoccerRealtimeSession::new(MatchConfig {
            duration_seconds: 1.0,
            seed: 591,
            ..Default::default()
        })));
        let input_queue = session.lock().unwrap().input_queue();

        let body = r#"{"learningEnabled":false,"learningLoggingEnabled":false,"learningIntervalTicks":8,"policyTrainMaxTransitionsPerTick":16}"#;
        let response = handle_live_soccer_request(
            &format!(
                "POST /api/learning HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(response.status, 200);
        let value: serde_json::Value =
            serde_json::from_str(&response.body).expect("learning runtime json");
        assert_eq!(value["config"]["learningEnabled"], false);
        assert_eq!(value["config"]["learningLoggingEnabled"], false);
        assert_eq!(value["config"]["learningIntervalTicks"], 8);
        assert_eq!(value["config"]["policyTrainMaxTransitionsPerTick"], 16);
        assert_eq!(value["learning"]["learningEnabled"], false);
        assert_eq!(value["learning"]["learningLoggingEnabled"], false);
        assert_eq!(value["learning"]["learningIntervalTicks"], 8);
        assert_eq!(value["learning"]["policyTrainMaxTransitionsPerTick"], 16);
        assert!(!session.lock().unwrap().match_ref().config.learning_enabled);

        let body = r#"{"learningEnabled":true,"learningLoggingEnabled":true,"learningIntervalTicks":4,"policyTrainMaxTransitionsPerTick":24,"neuralLearningEnabled":true,"neuralLearningBackend":"threaded"}"#;
        let response = handle_live_soccer_request(
            &format!(
                "POST /api/learning HTTP/1.1\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            ),
            &session,
            &input_queue,
        );
        assert_eq!(response.status, 200);
        let value: serde_json::Value =
            serde_json::from_str(&response.body).expect("neural learning runtime json");
        assert_eq!(value["config"]["learningEnabled"], true);
        assert_eq!(value["config"]["learningLoggingEnabled"], true);
        assert_eq!(value["config"]["learningIntervalTicks"], 4);
        assert_eq!(value["config"]["policyTrainMaxTransitionsPerTick"], 24);
        assert_eq!(value["config"]["neuralLearning"]["enabled"], true);
        assert_eq!(value["config"]["neuralLearning"]["backend"], "threaded");
        assert_eq!(value["learning"]["neuralLearningEnabled"], true);
        assert_eq!(value["learning"]["neuralLearningBackend"], "threaded");
        assert!(
            session
                .lock()
                .unwrap()
                .match_ref()
                .config
                .neural_learning
                .enabled
        );
    }

