    #[test]
    fn blocked_shot_lane_makes_shoot_option_and_learned_shoot_illegal() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 2222,
            ..Default::default()
        });
        let attacker = 9;
        let blocker = 13;
        sim.players[attacker].position = Vec2::new(40.0, 103.0);
        sim.players[attacker].skills.shooting = 10.0;
        sim.players[attacker].skills.right_foot_shot_power = 10.0;
        sim.players[attacker].skills.left_foot_shot_power = 9.0;
        sim.players[attacker].preferences.shoot_bias = 1.0;
        for away in 11..22 {
            sim.players[away].position = Vec2::new(74.0, 18.0 + away as f64 * 2.0);
        }
        sim.players[blocker].position = Vec2::new(40.0, 111.0);
        sim.players[blocker].skills.defending = 10.0;
        sim.players[blocker].skills.defensive_tracking = 10.0;
        sim.players[blocker].skills.aggression = 10.0;
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let blocked_snapshot = WorldSnapshot::from_match(&sim);
        let blocked_observation = blocked_snapshot.observation_for(attacker);
        assert!(!blocked_observation.shot_lane_open);
        assert!(!shot_decision_is_qualified(&blocked_observation));
        let directive = blocked_snapshot.tactical_directive(Team::Home);
        let blocked_options = sim.players[attacker].possession_action_options(
            &blocked_observation,
            &directive,
            0,
            0,
            false,
            sim.config.dt_seconds,
            blocked_snapshot.field_width,
        );
        let blocked_shot = blocked_options
            .iter()
            .find(|option| option.label == "shoot")
            .expect("shoot option");
        assert!(!blocked_shot.legal);
        assert_eq!(blocked_shot.probability, 0.0);
        assert!(!learned_action_label_is_legal(
            "shoot",
            &blocked_snapshot,
            attacker
        ));

        sim.players[blocker].position = Vec2::new(68.0, 111.0);
        let clear_snapshot = WorldSnapshot::from_match(&sim);
        let clear_observation = clear_snapshot.observation_for(attacker);
        assert!(clear_observation.shot_lane_open);
        assert!(shot_decision_is_qualified(&clear_observation));
        let directive = clear_snapshot.tactical_directive(Team::Home);
        let clear_options = sim.players[attacker].possession_action_options(
            &clear_observation,
            &directive,
            0,
            0,
            false,
            sim.config.dt_seconds,
            clear_snapshot.field_width,
        );
        let clear_shot = clear_options
            .iter()
            .find(|option| option.label == "shoot")
            .expect("shoot option");
        assert!(clear_shot.legal);
        assert!(clear_shot.probability > 0.0);
        assert!(
            clear_shot.score
                >= close_clear_shot_attempt_probability(
                    &clear_observation,
                    sim.players[attacker].role,
                    ability01(sim.players[attacker].skills.shooting),
                )
        );
        assert!(learned_action_label_is_legal(
            "shoot",
            &clear_snapshot,
            attacker
        ));
    }

    #[test]
    fn blocked_close_attacker_does_not_fire_must_shoot_intent() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 2224,
            ..Default::default()
        });
        let attacker = 9;
        let blocker = 13;
        let keeper = 11;
        park_players_except(&mut sim, &[attacker, blocker, keeper]);
        sim.players[attacker].position = Vec2::new(40.0, 105.0);
        sim.players[attacker].skills.shooting = 10.0;
        sim.players[attacker].skills.right_foot_shot_power = 10.0;
        sim.players[attacker].skills.left_foot_shot_power = 9.0;
        sim.players[attacker].preferences.shoot_bias = 1.0;
        sim.players[blocker].position = Vec2::new(40.0, 111.0);
        sim.players[blocker].skills.defending = 10.0;
        sim.players[blocker].skills.defensive_tracking = 10.0;
        sim.players[blocker].skills.aggression = 10.0;
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(attacker);
        assert!(observation.yards_to_goal <= 20.0);
        assert!(!observation.shot_lane_open);
        assert!(!goal_attack_shot_is_required(
            &observation,
            sim.players[attacker].role
        ));

        let plan = SoccerLearnedPlan {
            action: "shoot".to_string(),
            target_player: None,
            target_point: None,
        };
        assert!(sim.players[attacker]
            .action_from_learned_plan(&plan, &snapshot, &observation)
            .is_none());

        for seed in 0..24 {
            let mut player = sim.players[attacker].clone();
            let intent =
                player.run_time_step(&snapshot, None, None, &mut mulberry32(22_424 + seed));
            if matches!(intent.action, SoccerAction::Shoot { .. }) {
                panic!("blocked close attacker should not shoot through defender, seed {seed}");
            }
            let decision = player.last_decision.expect("blocked close decision");
            let shoot = decision
                .action_options
                .iter()
                .find(|option| option.label == "shoot")
                .expect("shoot option");
            assert!(!shoot.legal);
            assert_eq!(shoot.probability, 0.0);
        }
    }

    #[test]
    fn human_controller_shot_input_respects_shot_lane_qualification() {
        let attacker = 9;
        let keeper = 11;
        let blockers = [12, 13, 14, 15];
        let kept_players = [attacker, keeper, 12, 13, 14, 15];
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.4,
            max_human_players: 1,
            seed: 23_100,
            ..Default::default()
        });
        sim.active_set_play = None;
        park_players_except(&mut sim, &kept_players);
        sim.players[attacker].controller_slot = Some(0);
        sim.players[attacker].position = Vec2::new(40.0, 104.0);
        sim.players[attacker].home_position = sim.players[attacker].position;
        sim.players[attacker].skills.shooting = 9.8;
        sim.players[attacker].skills.right_foot_shot_power = 9.7;
        sim.players[attacker].skills.left_foot_shot_power = 9.4;
        sim.players[attacker].skills.decision_noise = 0.0;
        sim.players[keeper].position = Vec2::new(42.0, 116.5);
        sim.players[keeper].skills.goalkeeping = 7.0;
        for (idx, blocker) in blockers.iter().copied().enumerate() {
            sim.players[blocker].position =
                Vec2::new(39.6 + idx as f64 * 0.28, 108.0 + idx as f64 * 1.35);
            sim.players[blocker].velocity = Vec2::zero();
            sim.players[blocker].fatigue = 0.0;
            sim.players[blocker].skills.defending = 10.0;
            sim.players[blocker].skills.defensive_tracking = 10.0;
            sim.players[blocker].skills.aggression = 10.0;
            sim.players[blocker].skills.strength = 9.5;
        }
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);
        sim.pending_pass = None;
        sim.pending_shot = None;

        let input = HumanInputFrame {
            controller_slot: 0,
            player_id: Some(attacker),
            seq: 1,
            axis: Vec2::zero(),
            sprint: false,
            pass: false,
            pass_flight: PassFlight::Floor,
            shoot: true,
            action: Some("shoot".to_string()),
            target_player: None,
        };

        let blocked_snapshot = WorldSnapshot::from_match(&sim);
        let blocked_observation = blocked_snapshot.observation_for(attacker);
        assert!(!blocked_observation.shot_lane_open);
        assert!(
            blocked_observation.shot_block_probability >= 0.90,
            "covered human shot setup should have very high block odds, got {:.3}",
            blocked_observation.shot_block_probability
        );
        let mut blocked_player = sim.players[attacker].clone();
        let blocked_intent = blocked_player.run_time_step(
            &blocked_snapshot,
            Some(&input),
            None,
            &mut mulberry32(23_400),
        );
        assert!(
            matches!(blocked_intent.action, SoccerAction::DribbleMove { .. }),
            "covered human shoot input should become carry/protect, got {blocked_intent:?}"
        );
        assert_ne!(
            blocked_player
                .last_decision
                .as_ref()
                .map(|decision| decision.action.as_str()),
            Some("shoot")
        );

        sim.ball.holder = None;
        let no_ball_snapshot = WorldSnapshot::from_match(&sim);
        let mut no_ball_player = sim.players[attacker].clone();
        let no_ball_intent = no_ball_player.run_time_step(
            &no_ball_snapshot,
            Some(&input),
            None,
            &mut mulberry32(23_401),
        );
        assert!(
            matches!(no_ball_intent.action, SoccerAction::MoveTo(_)),
            "human shoot input without possession should not become a shot, got {no_ball_intent:?}"
        );

        sim.ball.holder = Some(attacker);
        for blocker in blockers {
            sim.players[blocker].position = Vec2::new(72.0, 18.0 + blocker as f64);
        }
        let clear_snapshot = WorldSnapshot::from_match(&sim);
        let clear_observation = clear_snapshot.observation_for(attacker);
        assert!(clear_observation.shot_lane_open);
        assert!(shot_decision_is_qualified_for_role(
            &clear_observation,
            sim.players[attacker].role
        ));
        let mut clear_player = sim.players[attacker].clone();
        let clear_intent = clear_player.run_time_step(
            &clear_snapshot,
            Some(&input),
            None,
            &mut mulberry32(23_402),
        );
        assert!(
            matches!(clear_intent.action, SoccerAction::Shoot { .. }),
            "clear human shoot input should remain a shot, got {clear_intent:?}"
        );
        assert_eq!(
            clear_player
                .last_decision
                .as_ref()
                .map(|decision| decision.action.as_str()),
            Some("shoot")
        );
    }

    #[test]
    fn blocked_shot_penalizes_shooter_and_rewards_blocker_for_learning() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.3,
            seed: 23_180,
            ..Default::default()
        });
        let shooter = 9;
        let blocker = 13;
        park_players_except(&mut sim, &[shooter, blocker]);
        sim.tick = 44;
        sim.players[shooter].position = Vec2::new(40.0, 104.0);
        sim.players[blocker].position = Vec2::new(40.0, 109.0);
        sim.players[blocker].skills.defending = 10.0;
        sim.players[blocker].skills.defensive_tracking = 10.0;
        sim.ball.holder = None;
        sim.ball.position = sim.players[shooter].position;
        sim.ball.velocity = Vec2::new(0.0, 25.0);
        sim.ball.last_touch_team = Some(Team::Home);
        sim.pending_shot = Some(PendingShot {
            team: Team::Home,
            shooter,
            origin: sim.players[shooter].position,
        });
        let before = WorldSnapshot::from_match(&sim);
        sim.players[shooter].last_decision = Some(test_decision_trace(&before, shooter, "shoot"));
        sim.players[blocker].last_decision = Some(test_decision_trace(&before, blocker, "defend"));
        let event_start = sim.reward_events.len();

        sim.apply_ball_outcome(BallStepOutcome::ShotBlocked {
            shot: PendingShot {
                team: Team::Home,
                shooter,
                origin: before.ball.position,
            },
            blocker_id: blocker,
            defending_team: Team::Away,
            position: sim.players[blocker].position,
            velocity: Vec2::new(0.0, -8.0),
            deflection_kind: ShotDeflectionKind::Rebound,
            keep_shot_active: false,
            restart: None,
        });

        let shot_block_events = &sim.reward_events[event_start..];
        assert!(shot_block_events.iter().any(|event| {
            event.player_id == blocker && event.amount == SHOT_BLOCK_DEFENDER_REWARD_POINTS
        }));
        assert!(shot_block_events.iter().any(|event| {
            event.player_id == shooter && event.amount == -BLOCKED_SHOT_SHOOTER_PENALTY_POINTS
        }));
        let after = WorldSnapshot::from_match(&sim);
        let transitions = sim.learning_transitions_for(
            &before,
            &after,
            sim.score_home,
            sim.score_away,
            shot_block_events,
        );
        let shooter_transition = transitions
            .iter()
            .find(|transition| transition.player_id == shooter)
            .expect("shooter learning transition");
        assert!(
            shooter_transition.reward < 0.0,
            "blocked shot should be net negative for the shooter, got {}",
            shooter_transition.reward
        );
    }

    #[test]
    fn clear_close_striker_shoots_definitely_inside_twenty_five_yards() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 2223,
            ..Default::default()
        });
        let attacker = 9;
        let keeper = 11;
        park_players_except(&mut sim, &[attacker, keeper]);
        sim.players[attacker].position = Vec2::new(40.0, 104.0);
        sim.players[attacker].velocity = Vec2::new(0.0, 5.0);
        sim.players[attacker].skills.shooting = 9.4;
        sim.players[attacker].skills.right_foot_shot_power = 9.2;
        sim.players[attacker].skills.left_foot_shot_power = 8.6;
        sim.players[attacker].skills.decision_noise = 0.0;
        sim.players[attacker].preferences.shoot_bias = 0.95;
        sim.players[attacker].preferences.pass_bias = 0.04;
        sim.players[attacker].preferences.dribble_bias = 0.08;
        sim.players[keeper].position = Vec2::new(38.5, 116.0);
        sim.players[keeper].skills.goalkeeping = 5.0;
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(attacker);
        assert!(shot_decision_is_qualified(&observation));
        assert!(
            observation.yards_to_goal <= 20.0,
            "test scenario should be inside the explicit close-shot window"
        );
        assert!(striker_must_shoot(&observation, sim.players[attacker].role));

        let mut shoot_count = 0;
        let trials = 120;
        for seed in 0..trials {
            let mut player = sim.players[attacker].clone();
            let mut rng = mulberry32(21_000 + seed);
            let intent = player.run_time_step(&snapshot, None, None, &mut rng);
            if matches!(intent.action, SoccerAction::Shoot { .. }) {
                shoot_count += 1;
            }
        }

        assert!(
            shoot_count == trials,
            "clear striker inside 25 yards should shoot every time, got {shoot_count}/{trials}"
        );
    }

