    #[test]
    fn teammate_inside_twenty_five_suppresses_backward_pass_outlet() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 2226,
            ..Default::default()
        });
        let attacker = 8;
        let backward_target = 9;
        let keeper = 11;
        let pressure_defender = 13;
        park_players_except(
            &mut sim,
            &[attacker, backward_target, keeper, pressure_defender],
        );
        sim.players[attacker].role = PlayerRole::Midfielder;
        sim.players[attacker].position = Vec2::new(40.0, 96.5);
        sim.players[attacker].velocity = Vec2::new(0.0, -1.0);
        sim.players[attacker].action_facing = FacingBucket::North;
        sim.players[attacker].receive_facing = FacingBucket::North;
        sim.players[attacker].skills.shooting = 7.6;
        sim.players[attacker].skills.right_foot_shot_power = 7.8;
        sim.players[attacker].skills.left_foot_shot_power = 7.2;
        sim.players[attacker].skills.decision_noise = 0.0;
        sim.players[attacker].preferences.shoot_bias = 0.72;
        sim.players[attacker].preferences.pass_bias = 1.0;
        sim.players[attacker].preferences.dribble_bias = 0.80;
        sim.players[backward_target].position = Vec2::new(39.5, 84.0);
        sim.players[backward_target].velocity = Vec2::new(0.0, 1.0);
        sim.players[keeper].position = Vec2::new(38.5, 116.0);
        sim.players[keeper].skills.goalkeeping = 5.0;
        sim.players[pressure_defender].position = Vec2::new(47.0, 96.0);
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(attacker);
        assert!(must_shoot_near_goal(
            &observation,
            sim.players[attacker].role
        ));
        let pass_targets = snapshot.ranked_visible_pass_targets(attacker, 3);
        assert!(
            pass_targets.contains(&backward_target),
            "test should include the backward outlet, got {pass_targets:?}"
        );
        let options = sim.players[attacker].possession_action_options(
            &observation,
            &snapshot.tactical_directive(Team::Home),
            pass_targets.len(),
            0,
            false,
            snapshot.dt_seconds,
            snapshot.field_width,
        );
        let shoot_score = action_option_score(&options, "shoot");
        let pass_score = action_option_score(&options, "pass1");
        assert!(
            shoot_score > pass_score * 6.0,
            "shoot score {shoot_score} should swamp backward pass score {pass_score}"
        );

        let mut shoot_count = 0;
        let mut pass_count = 0;
        let trials = 80;
        for seed in 0..trials {
            let mut player = sim.players[attacker].clone();
            let mut rng = mulberry32(24_000 + seed);
            let intent = player.run_time_step(&snapshot, None, None, &mut rng);
            match intent.action {
                SoccerAction::Shoot { .. } => shoot_count += 1,
                SoccerAction::Pass { .. } => pass_count += 1,
                _ => {}
            }
        }

        assert!(
            shoot_count >= 72,
            "near-goal teammate should shoot instead of recycling, got {shoot_count}/{trials}"
        );
        assert!(
            pass_count <= 1,
            "backward outlet should be rare in the shooting window, got {pass_count}/{trials}"
        );
    }

    #[test]
    fn near_box_carry_bends_toward_goal_instead_of_endline() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 2228,
            ..Default::default()
        });
        let attacker = 9;
        let blocker = 13;
        let keeper = 11;
        park_players_except(&mut sim, &[attacker, blocker, keeper]);
        sim.players[attacker].position = Vec2::new(70.0, 92.0);
        sim.players[attacker].home_position = sim.players[attacker].position;
        sim.players[attacker].velocity = Vec2::new(0.0, 4.0);
        sim.players[attacker].skills.dribbling = 9.2;
        sim.players[attacker].skills.acceleration = 9.0;
        sim.players[attacker].skills.shooting = 5.0;
        sim.players[attacker].skills.decision_noise = 0.0;
        sim.players[blocker].position = Vec2::new(55.0, 106.0);
        sim.players[blocker].skills.defending = 8.0;
        sim.players[keeper].position = Vec2::new(40.0, 116.0);
        sim.players[keeper].skills.goalkeeping = 6.0;
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);

        let snapshot = WorldSnapshot::from_match(&sim);
        let observation = snapshot.observation_for(attacker);
        assert!(observation.yards_to_goal <= STRIKER_SHOT_WINDOW_YARDS);
        assert!(!shot_decision_is_qualified_for_role(
            &observation,
            sim.players[attacker].role
        ));

        let mut player = sim.players[attacker].clone();
        let plan = SoccerLearnedPlan {
            action: "carry-forward".to_string(),
            target_player: None,
            target_point: None,
        };
        let intent = player.run_time_step(&snapshot, None, Some(&plan), &mut mulberry32(22_280));
        let SoccerAction::DribbleMove { target, .. } = intent.action else {
            panic!("blocked near-box carry should stay on the dribble plan, got {intent:?}");
        };
        let current = sim.players[attacker].position;
        let goal = Vec2::new(
            sim.config.field_width_yards * 0.5,
            Team::Home.goal_y(sim.config.field_length_yards),
        );
        let straight_endline_target = Vec2::new(current.x, target.y);

        assert!(
            target.x < current.x - 2.0,
            "near-box carry should move toward goal center, current={current:?} target={target:?}"
        );
        assert!(
            target.y > current.y && target.y <= goal.y - 4.0,
            "near-box carry should advance without running to the endline, current={current:?} target={target:?}"
        );
        assert!(
            target.distance(goal) < straight_endline_target.distance(goal),
            "goal-facing carry should improve shooting geometry versus straight endline carry: target={target:?}"
        );
    }

    #[test]
    fn wide_attacker_switches_from_goalmouth_drive_to_shot() {
        let mut sim = SoccerMatch::default_11v11(MatchConfig {
            duration_seconds: 0.1,
            seed: 2229,
            ..Default::default()
        });
        let attacker = 9;
        let blocker = 13;
        let keeper = 11;
        park_players_except(&mut sim, &[attacker, blocker, keeper]);
        sim.players[attacker].position = Vec2::new(70.0, 94.0);
        sim.players[attacker].home_position = sim.players[attacker].position;
        sim.players[attacker].velocity = Vec2::new(0.0, 4.4);
        sim.players[attacker].skills.dribbling = 9.1;
        sim.players[attacker].skills.acceleration = 8.9;
        sim.players[attacker].skills.shooting = 7.8;
        sim.players[attacker].skills.decision_noise = 0.0;
        sim.players[attacker].preferences.dribble_bias = 1.0;
        sim.players[blocker].position = Vec2::new(54.0, 108.0);
        sim.players[blocker].skills.defending = 8.4;
        sim.players[keeper].position = Vec2::new(40.0, 116.0);
        sim.players[keeper].skills.goalkeeping = 6.0;
        sim.ball.holder = Some(attacker);
        sim.ball.position = sim.players[attacker].position;
        sim.ball.velocity = Vec2::zero();
        sim.ball.last_touch_team = Some(Team::Home);

        let blocked_snapshot = WorldSnapshot::from_match(&sim);
        let blocked_observation = blocked_snapshot.observation_for(attacker);
        assert!(blocked_observation.yards_to_goal > STRIKER_MUST_SHOOT_YARDS);
        assert!(blocked_observation.yards_to_goal <= STRIKER_SHOT_WINDOW_YARDS);
        assert!(!shot_decision_is_qualified_for_role(
            &blocked_observation,
            sim.players[attacker].role
        ));
        assert!(goal_approach_forces_goalmouth_carry(
            &blocked_observation,
            sim.players[attacker].role
        ));

        let mut player = sim.players[attacker].clone();
        let plan = SoccerLearnedPlan {
            action: "carry-forward".to_string(),
            target_player: None,
            target_point: None,
        };
        let intent = player.run_time_step(
            &blocked_snapshot,
            None,
            Some(&plan),
            &mut mulberry32(22_290),
        );
        let SoccerAction::DribbleMove { target, kind, .. } = intent.action else {
            panic!("blocked approach should drive into a shooting pocket, got {intent:?}");
        };
        let origin = sim.players[attacker].position;
        let goal = Vec2::new(
            blocked_snapshot.field_width * 0.5,
            Team::Home.goal_y(blocked_snapshot.field_length),
        );
        let straight_endline_target = Vec2::new(origin.x, target.y);
        assert_eq!(kind, DribbleMoveKind::CarryForward);
        assert!(
            target.x < origin.x - 2.0,
            "goal approach should bend toward the mouth of goal: origin={origin:?} target={target:?}"
        );
        assert!(
            target.distance(goal) < straight_endline_target.distance(goal),
            "goal approach should improve the shooting angle instead of continuing down the endline: target={target:?}"
        );
        assert!(
            target.y <= Team::Home.goal_y(blocked_snapshot.field_length) - 10.0,
            "goal approach should stop in the shooting pocket, not at the goal line: target={target:?}"
        );

        sim.players[attacker].position = target;
        sim.players[attacker].home_position = target;
        sim.players[attacker].velocity = Vec2::new(-1.2, 3.8);
        sim.players[blocker].position = Vec2::new(15.0, 72.0);
        sim.ball.position = target;
        let clear_snapshot = WorldSnapshot::from_match(&sim);
        let clear_observation = clear_snapshot.observation_for(attacker);
        assert!(must_shoot_near_goal(
            &clear_observation,
            sim.players[attacker].role
        ));

        for seed in 0..24 {
            let mut player = sim.players[attacker].clone();
            let intent = player.run_time_step(
                &clear_snapshot,
                None,
                Some(&plan),
                &mut mulberry32(22_300 + seed),
            );
            assert!(
                matches!(intent.action, SoccerAction::Shoot { .. }),
                "attacker in the shooting pocket should shoot, seed {seed}, got {intent:?}"
            );
        }
    }

